window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1SA"]={"book":"1SA","editions":{"hbo-source":[[1,1,"וַ⁠יְהִי֩ אִ֨ישׁ אֶחָ֜ד מִן־הָ⁠רָמָתַ֛יִם צוֹפִ֖ים מֵ⁠הַ֣ר אֶפְרָ֑יִם וּ⁠שְׁמ֡⁠וֹ אֶ֠לְקָנָה בֶּן־יְרֹחָ֧ם בֶּן־אֱלִיה֛וּא בֶּן־תֹּ֥חוּ בֶן־צ֖וּף אֶפְרָתִֽי׃","wa⁠yĕhiy֩ ʼi֨yş̌ ʼeẖá֜d min-há⁠rámáţa֛yim ẕwòpi֖ym mé⁠ha֣r ʼepĕrá֑yim ẇ⁠şĕ̌m֡⁠wò ʼe֠lĕqánáh bėn-yĕròẖá֧m bėn-ʼèliyh֛ẇʼ bėn-ţò֥̇ẖẇ ben-ẕ֖ẇp ʼepĕráţiֽy׃"],[1,2,"וְ⁠ל⁠וֹ֙ שְׁתֵּ֣י נָשִׁ֔ים שֵׁ֤ם אַחַת֙ חַנָּ֔ה וְ⁠שֵׁ֥ם הַ⁠שֵּׁנִ֖ית פְּנִנָּ֑ה וַ⁠יְהִ֤י לִ⁠פְנִנָּה֙ יְלָדִ֔ים וּ⁠לְ⁠חַנָּ֖ה אֵ֥ין יְלָדִֽים׃","wĕ⁠l⁠wò֙ şĕ̌ţé֣̇y náşǐ֔ym şé֤̌m ʼaẖaţ֙ ẖaná̇֔h wĕ⁠şé֥̌m ha⁠şé̇̌ni֖yţ pĕ̇niná֑̇h wa⁠yĕhi֤y li⁠pĕniná̇h֙ yĕládi֔ym ẇ⁠lĕ⁠ẖaná֖̇h ʼé֥yn yĕládiֽym׃"],[1,3,"וְ⁠עָלָה֩ הָ⁠אִ֨ישׁ הַ⁠ה֤וּא מֵֽ⁠עִיר⁠וֹ֙ מִ⁠יָּמִ֣ים ׀ יָמִ֔ימָ⁠ה לְ⁠הִֽשְׁתַּחֲוֺ֧ת וְ⁠לִ⁠זְבֹּ֛חַ לַ⁠יהוָ֥ה צְבָא֖וֹת בְּ⁠שִׁלֹ֑ה וְ⁠שָׁ֞ם שְׁנֵ֣י בְנֵֽי־עֵלִ֗י חָפְנִי֙ וּ⁠פִ֣נְחָ֔ס כֹּהֲנִ֖ים לַ⁠יהוָֽה׃","wĕ⁠ʻáláh֩ há⁠ʼi֨yş̌ ha⁠h֤ẇʼ méֽ⁠ʻiyr⁠wò֙ mi⁠yá̇mi֣ym ׀ yámi֔ymá⁠h lĕ⁠hiֽşĕ̌ţȧẖàwֺ֧ţ wĕ⁠li⁠zĕbò֛̇ẖa la⁠yhwá֥h ẕĕbáʼ֖wòţ bĕ̇⁠şǐlò֑h wĕ⁠şá̌֞m şĕ̌né֣y bĕnéֽy-ʻéli֗y ẖápĕniy֙ ẇ⁠pi֣nĕẖá֔s kò̇hàni֖ym la⁠yhwáֽh׃"],[1,4,"וַ⁠יְהִ֣י הַ⁠יּ֔וֹם וַ⁠יִּזְבַּ֖ח אֶלְקָנָ֑ה וְ⁠נָתַ֞ן לִ⁠פְנִנָּ֣ה אִשְׁתּ֗⁠וֹ וּֽ⁠לְ⁠כָל־בָּנֶ֛י⁠הָ וּ⁠בְנוֹתֶ֖י⁠הָ מָנֽוֹת׃","wa⁠yĕhi֣y ha⁠ẏ֔wòm wa⁠yi̇zĕbȧ֖ẖ ʼelĕqáná֑h wĕ⁠náţa֞n li⁠pĕniná֣̇h ʼişĕ̌ţ̇֗⁠wò ẇֽ⁠lĕ⁠kál-bá̇ne֛y⁠há ẇ⁠bĕnwòţe֖y⁠há mánֽwòţ׃"],[1,5,"וּ⁠לְ⁠חַנָּ֕ה יִתֵּ֛ן מָנָ֥ה אַחַ֖ת אַפָּ֑יִם כִּ֤י אֶת־חַנָּה֙ אָהֵ֔ב וַֽ⁠יהוָ֖ה סָגַ֥ר רַחְמָֽ⁠הּ׃","ẇ⁠lĕ⁠ẖaná̇֕h yiţé֛̇n máná֥h ʼaẖa֖ţ ʼapá֑̇yim ki֤̇y ʼeţ-ẖaná̇h֙ ʼáhé֔b waֽ⁠yhwá֖h sága֥r raẖĕmáֽ⁠ḣ׃"],[1,6,"וְ⁠כִֽעֲסַ֤תָּ⁠ה צָֽרָתָ⁠הּ֙ גַּם־כַּ֔עַס בַּ⁠עֲב֖וּר הַרְּעִמָ֑⁠הּ כִּֽי־סָגַ֥ר יְהוָ֖ה בְּעַ֥ד רַחְמָֽ⁠הּ׃","wĕ⁠kiֽʻàsa֤ţá̇⁠h ẕáֽráţá⁠ḣ֙ gȧm-kȧ֔ʻas bȧ⁠ʻàb֖ẇr harĕ̇ʻimá֑⁠ḣ kiֽ̇y-sága֥r yĕhwá֖h bĕ̇ʻa֥d raẖĕmáֽ⁠ḣ׃"],[1,7,"וְ⁠כֵ֨ן יַעֲשֶׂ֜ה שָׁנָ֣ה בְ⁠שָׁנָ֗ה מִ⁠דֵּ֤י עֲלֹתָ⁠הּ֙ בְּ⁠בֵ֣ית יְהוָ֔ה כֵּ֖ן תַּכְעִסֶ֑⁠נָּה וַ⁠תִּבְכֶּ֖ה וְ⁠לֹ֥א תֹאכַֽל׃","wĕ⁠ké֨n yaʻàşê֜h şá̌ná֣h bĕ⁠şá̌ná֗h mi⁠dé֤̇y ʻàlòţá⁠ḣ֙ bĕ̇⁠bé֣yţ yĕhwá֔h ké֖̇n ţȧkĕʻise֑⁠ná̇h wa⁠ţi̇bĕkė֖h wĕ⁠lò֥ʼ ţòʼkaֽl׃"],[1,8,"וַ⁠יֹּ֨אמֶר לָ֜⁠הּ אֶלְקָנָ֣ה אִישָׁ֗⁠הּ חַנָּה֙ לָ֣⁠מֶה תִבְכִּ֗י וְ⁠לָ֨⁠מֶה֙ לֹ֣א תֹֽאכְלִ֔י וְ⁠לָ֖⁠מֶה יֵרַ֣ע לְבָבֵ֑⁠ךְ הֲ⁠ל֤וֹא אָֽנֹכִי֙ ט֣וֹב לָ֔⁠ךְ מֵ⁠עֲשָׂרָ֖ה בָּנִֽים׃","wa⁠yò̇֨ʼmer lá֜⁠ḣ ʼelĕqáná֣h ʼiyşá̌֗⁠ḣ ẖaná̇h֙ lá֣⁠meh ţibĕki̇֗y wĕ⁠lá֨⁠meh֙ lò֣ʼ ţòֽʼkĕli֔y wĕ⁠lá֖⁠meh yéra֣ʻ lĕbábé֑⁠kĕ hà⁠l֤wòʼ ʼáֽnòkiy֙ t֣wòb lá֔⁠kĕ mé⁠ʻàşá̂rá֖h bá̇niֽym׃"],[1,9,"וַ⁠תָּ֣קָם חַנָּ֔ה אַחֲרֵ֛י אָכְלָ֥ה בְ⁠שִׁלֹ֖ה וְ⁠אַחֲרֵ֣י שָׁתֹ֑ה וְ⁠עֵלִ֣י הַ⁠כֹּהֵ֗ן יֹשֵׁב֙ עַל־הַ⁠כִּסֵּ֔א עַל־מְזוּזַ֖ת הֵיכַ֥ל יְהוָֽה׃","wa⁠ţá֣̇qám ẖaná̇֔h ʼaẖàré֛y ʼákĕlá֥h bĕ⁠şǐlò֖h wĕ⁠ʼaẖàré֣y şá̌ţò֑h wĕ⁠ʻéli֣y ha⁠kò̇hé֗n yòşé̌b֙ ʻal-ha⁠ki̇sé̇֔ʼ ʻal-mĕzẇza֖ţ héyka֥l yĕhwáֽh׃"],[1,10,"וְ⁠הִ֖יא מָ֣רַת נָ֑פֶשׁ וַ⁠תִּתְפַּלֵּ֥ל עַל־יְהוָ֖ה וּ⁠בָכֹ֥ה תִבְכֶּֽה׃","wĕ⁠hi֖yʼ má֣raţ ná֑peş̌ wa⁠ţi̇ţĕpȧlé֥̇l ʻal-yĕhwá֖h ẇ⁠bákò֥h ţibĕkėֽh׃"],[1,11,"וַ⁠תִּדֹּ֨ר נֶ֜דֶר וַ⁠תֹּאמַ֗ר יְהוָ֨ה צְבָא֜וֹת אִם־רָאֹ֥ה תִרְאֶ֣ה ׀ בָּ⁠עֳנִ֣י אֲמָתֶ֗⁠ךָ וּ⁠זְכַרְתַּ֨⁠נִי֙ וְ⁠לֹֽא־תִשְׁכַּ֣ח אֶת־אֲמָתֶ֔⁠ךָ וְ⁠נָתַתָּ֥ה לַ⁠אֲמָתְ⁠ךָ֖ זֶ֣רַע אֲנָשִׁ֑ים וּ⁠נְתַתִּ֤י⁠ו לַֽ⁠יהוָה֙ כָּל־יְמֵ֣י חַיָּ֔י⁠ו וּ⁠מוֹרָ֖ה לֹא־יַעֲלֶ֥ה עַל־רֹאשֽׁ⁠וֹ׃","wa⁠ţi̇dò̇֨r ne֜der wa⁠ţò̇ʼma֗r yĕhwá֨h ẕĕbáʼ֜wòţ ʼim-ráʼò֥h ţirĕʼe֣h ׀ bá̇⁠ʻoni֣y ʼàmáţe֗⁠ká ẇ⁠zĕkarĕţȧ֨⁠niy֙ wĕ⁠lòֽʼ-ţişĕ̌kȧ֣ẖ ʼeţ-ʼàmáţe֔⁠ká wĕ⁠náţaţá֥̇h la⁠ʼàmáţĕ⁠ká֖ ze֣raʻ ʼànáşǐ֑ym ẇ⁠nĕţaţi֤̇y⁠w laֽ⁠yhwáh֙ ká̇l-yĕmé֣y ẖayá̇֔y⁠w ẇ⁠mwòrá֖h lòʼ-yaʻàle֥h ʻal-ròʼşֽ̌⁠wò׃"],[1,12,"וְ⁠הָיָה֙ כִּ֣י הִרְבְּתָ֔ה לְ⁠הִתְפַּלֵּ֖ל לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠עֵלִ֖י שֹׁמֵ֥ר אֶת־פִּֽי⁠הָ׃","wĕ⁠háyáh֙ ki֣̇y hirĕbĕ̇ţá֔h lĕ⁠hiţĕpȧlé֖̇l li⁠pĕné֣y yĕhwá֑h wĕ⁠ʻéli֖y şò̌mé֥r ʼeţ-piֽ̇y⁠há׃"],[1,13,"וְ⁠חַנָּ֗ה הִ֚יא מְדַבֶּ֣רֶת עַל־לִבָּ֔⁠הּ רַ֚ק שְׂפָתֶ֣י⁠הָ נָּע֔וֹת וְ⁠קוֹלָ֖⁠הּ לֹ֣א יִשָּׁמֵ֑עַ וַ⁠יַּחְשְׁבֶ֥⁠הָ עֵלִ֖י לְ⁠שִׁכֹּרָֽה׃","wĕ⁠ẖaná̇֗h hi֚yʼ mĕdabė֣reţ ʻal-libá̇֔⁠ḣ ra֚q şĕ̂páţe֣y⁠há ná̇ʻ֔wòţ wĕ⁠qwòlá֖⁠ḣ lò֣ʼ yişá̇̌mé֑ʻa wa⁠yȧẖĕşĕ̌be֥⁠há ʻéli֖y lĕ⁠şǐkò̇ráֽh׃"],[1,14,"וַ⁠יֹּ֤אמֶר אֵלֶ֨י⁠הָ֙ עֵלִ֔י עַד־מָתַ֖י תִּשְׁתַּכָּרִ֑י⁠ן הָסִ֥ירִי אֶת־יֵינֵ֖⁠ךְ מֵ⁠עָלָֽיִ⁠ךְ׃","wa⁠yò֤̇ʼmer ʼéle֨y⁠há֙ ʻéli֔y ʻad-máţa֖y ţi̇şĕ̌ţȧká̇ri֑y⁠n hási֥yriy ʼeţ-yéyné֖⁠kĕ mé⁠ʻáláֽyi⁠kĕ׃"],[1,15,"וַ⁠תַּ֨עַן חַנָּ֤ה וַ⁠תֹּ֨אמֶר֙ לֹ֣א אֲדֹנִ֔⁠י אִשָּׁ֤ה קְשַׁת־ר֨וּחַ֙ אָנֹ֔כִי וְ⁠יַ֥יִן וְ⁠שֵׁכָ֖ר לֹ֣א שָׁתִ֑יתִי וָ⁠אֶשְׁפֹּ֥ךְ אֶת־נַפְשִׁ֖⁠י לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠ţȧ֨ʻan ẖaná֤̇h wa⁠ţò̇֨ʼmer֙ lò֣ʼ ʼàdòni֔⁠y ʼişá֤̇̌h qĕşǎţ-r֨ẇẖa֙ ʼánò֔kiy wĕ⁠ya֥yin wĕ⁠şé̌ká֖r lò֣ʼ şá̌ţi֑yţiy wá⁠ʼeşĕ̌pò֥̇kĕ ʼeţ-napĕşǐ֖⁠y li⁠pĕné֥y yĕhwáֽh׃"],[1,16,"אַל־תִּתֵּן֙ אֶת־אֲמָ֣תְ⁠ךָ֔ לִ⁠פְנֵ֖י בַּת־בְּלִיָּ֑עַל כִּֽי־מֵ⁠רֹ֥ב שִׂיחִ֛⁠י וְ⁠כַעְסִ֖⁠י דִּבַּ֥רְתִּי עַד־הֵֽנָּה׃","ʼal-ţi̇ţé̇n֙ ʼeţ-ʼàmá֣ţĕ⁠ká֔ li⁠pĕné֖y bȧţ-bĕ̇liyá֑̇ʻal kiֽ̇y-mé⁠rò֥b şîyẖi֛⁠y wĕ⁠kaʻĕsi֖⁠y di̇bȧ֥rĕţi̇y ʻad-héֽná̇h׃"],[1,17,"וַ⁠יַּ֧עַן עֵלִ֛י וַ⁠יֹּ֖אמֶר לְכִ֣י לְ⁠שָׁל֑וֹם וֵ⁠אלֹהֵ֣י יִשְׂרָאֵ֗ל יִתֵּן֙ אֶת־שֵׁ֣לָתֵ֔⁠ךְ אֲשֶׁ֥ר שָׁאַ֖לְתְּ מֵ⁠עִמּֽ⁠וֹ׃","wa⁠yȧ֧ʻan ʻéli֛y wa⁠yò֖̇ʼmer lĕki֣y lĕ⁠şá̌l֑wòm wé⁠ʼlòhé֣y yişĕ̂ráʼé֗l yiţé̇n֙ ʼeţ-şé֣̌láţé֔⁠kĕ ʼàşě֥r şá̌ʼa֖lĕţĕ̇ mé⁠ʻiṁֽ⁠wò׃"],[1,18,"וַ⁠תֹּ֕אמֶר תִּמְצָ֧א שִׁפְחָתְ⁠ךָ֛ חֵ֖ן בְּ⁠עֵינֶ֑י⁠ךָ וַ⁠תֵּ֨לֶךְ הָ⁠אִשָּׁ֤ה לְ⁠דַרְכָּ⁠הּ֙ וַ⁠תֹּאכַ֔ל וּ⁠פָנֶ֥י⁠הָ לֹא־הָיוּ־לָ֖⁠הּ עֽוֹד׃","wa⁠ţò̇֕ʼmer ţi̇mĕẕá֧ʼ şǐpĕẖáţĕ⁠ká֛ ẖé֖n bĕ̇⁠ʻéyne֑y⁠ká wa⁠ţé̇֨lekĕ há⁠ʼişá֤̇̌h lĕ⁠darĕká̇⁠ḣ֙ wa⁠ţò̇ʼka֔l ẇ⁠páne֥y⁠há lòʼ-háyẇ-lá֖⁠ḣ ʻֽwòd׃"],[1,19,"וַ⁠יַּשְׁכִּ֣מוּ בַ⁠בֹּ֗קֶר וַ⁠יִּֽשְׁתַּחֲווּ֙ לִ⁠פְנֵ֣י יְהוָ֔ה וַ⁠יָּשֻׁ֛בוּ וַ⁠יָּבֹ֥אוּ אֶל־בֵּיתָ֖⁠ם הָ⁠רָמָ֑תָ⁠ה וַ⁠יֵּ֤דַע אֶלְקָנָה֙ אֶת־חַנָּ֣ה אִשְׁתּ֔⁠וֹ וַ⁠יִּֽזְכְּרֶ֖⁠הָ יְהוָֽה׃","wa⁠yȧşĕ̌ki֣̇mẇ ba⁠bò̇֗qer wa⁠yiֽ̇şĕ̌ţȧẖàwẇ֙ li⁠pĕné֣y yĕhwá֔h wa⁠yá̇şǔ֛bẇ wa⁠yá̇bò֥ʼẇ ʼel-bé̇yţá֖⁠m há⁠rámá֑ţá⁠h wa⁠yé֤̇daʻ ʼelĕqánáh֙ ʼeţ-ẖaná֣̇h ʼişĕ̌ţ̇֔⁠wò wa⁠ẏֽizĕkĕ̇re֖⁠há yĕhwáֽh׃"],[1,20,"וַ⁠יְהִי֙ לִ⁠תְקֻפ֣וֹת הַ⁠יָּמִ֔ים וַ⁠תַּ֥הַר חַנָּ֖ה וַ⁠תֵּ֣לֶד בֵּ֑ן וַ⁠תִּקְרָ֤א אֶת־שְׁמ⁠וֹ֙ שְׁמוּאֵ֔ל כִּ֥י מֵ⁠יְהוָ֖ה שְׁאִלְתִּֽי⁠ו׃","wa⁠yĕhiy֙ li⁠ţĕqup֣wòţ ha⁠yá̇mi֔ym wa⁠ţȧ֥har ẖaná֖̇h wa⁠ţé֣̇led bé֑̇n wa⁠ţi̇qĕrá֤ʼ ʼeţ-şĕ̌m⁠wò֙ şĕ̌mẇʼé֔l ki֥̇y mé⁠yĕhwá֖h şĕ̌ʼilĕţiֽ̇y⁠w׃"],[1,21,"וַ⁠יַּ֛עַל הָ⁠אִ֥ישׁ אֶלְקָנָ֖ה וְ⁠כָל־בֵּית֑⁠וֹ לִ⁠זְבֹּ֧חַ לַֽ⁠יהוָ֛ה אֶת־זֶ֥בַח הַ⁠יָּמִ֖ים וְ⁠אֶת־נִדְרֽ⁠וֹ׃","wa⁠yȧ֛ʻal há⁠ʼi֥yş̌ ʼelĕqáná֖h wĕ⁠kál-bé̇yţ֑⁠wò li⁠zĕbò֧̇ẖa laֽ⁠yhwá֛h ʼeţ-ze֥baẖ ha⁠yá̇mi֖ym wĕ⁠ʼeţ-nidĕrֽ⁠wò׃"],[1,22,"וְ⁠חַנָּ֖ה לֹ֣א עָלָ֑תָה כִּֽי־אָמְרָ֣ה לְ⁠אִישָׁ֗⁠הּ עַ֣ד יִגָּמֵ֤ל הַ⁠נַּ֨עַר֙ וַ⁠הֲבִאֹתִ֗י⁠ו וְ⁠נִרְאָה֙ אֶת־פְּנֵ֣י יְהוָ֔ה וְ⁠יָ֥שַׁב שָׁ֖ם עַד־עוֹלָֽם׃","wĕ⁠ẖaná֖̇h lò֣ʼ ʻálá֑ţáh kiֽ̇y-ʼámĕrá֣h lĕ⁠ʼiyşá̌֗⁠ḣ ʻa֣d yigá̇mé֤l ha⁠nȧ֨ʻar֙ wa⁠hàbiʼòţi֗y⁠w wĕ⁠nirĕʼáh֙ ʼeţ-pĕ̇né֣y yĕhwá֔h wĕ⁠yá֥şǎb şá֖̌m ʻad-ʻwòláֽm׃"],[1,23,"וַ⁠יֹּ֣אמֶר לָ⁠הּ֩ אֶלְקָנָ֨ה אִישָׁ֜⁠הּ עֲשִׂ֧י הַ⁠טּ֣וֹב בְּ⁠עֵינַ֗יִ⁠ךְ שְׁבִי֙ עַד־גָּמְלֵ֣⁠ךְ אֹת֔⁠וֹ אַ֛ךְ יָקֵ֥ם יְהוָ֖ה אֶת־דְּבָר֑⁠וֹ וַ⁠תֵּ֤שֶׁב הָֽ⁠אִשָּׁה֙ וַ⁠תֵּ֣ינֶק אֶת־בְּנָ֔⁠הּ עַד־גָּמְלָ֖⁠הּ אֹתֽ⁠וֹ׃","wa⁠yò֣̇ʼmer lá⁠ḣ֩ ʼelĕqáná֨h ʼiyşá̌֜⁠ḣ ʻàşî֧y ha⁠ṫ֣wòb bĕ̇⁠ʻéyna֗yi⁠kĕ şĕ̌biy֙ ʻad-gá̇mĕlé֣⁠kĕ ʼòţ֔⁠wò ʼa֛kĕ yáqé֥m yĕhwá֖h ʼeţ-dĕ̇bár֑⁠wò wa⁠ţé֤̇şěb háֽ⁠ʼişá̇̌h֙ wa⁠ţé֣̇yneq ʼeţ-bĕ̇ná֔⁠ḣ ʻad-gá̇mĕlá֖⁠ḣ ʼòţֽ⁠wò׃"],[1,24,"וַ⁠תַּעֲלֵ֨⁠הוּ עִמָּ֜⁠הּ כַּ⁠אֲשֶׁ֣ר גְּמָלַ֗תּ⁠וּ בְּ⁠פָרִ֤ים שְׁלֹשָׁה֙ וְ⁠אֵיפָ֨ה אַחַ֥ת קֶ֨מַח֙ וְ⁠נֵ֣בֶל יַ֔יִן וַ⁠תְּבִאֵ֥⁠הוּ בֵית־יְהוָ֖ה שִׁל֑וֹ וְ⁠הַ⁠נַּ֖עַר נָֽעַר׃","wa⁠ţȧʻàlé֨⁠hẇ ʻimá̇֜⁠ḣ kȧ⁠ʼàşě֣r gĕ̇mála֗ţ̇⁠ẇ bĕ̇⁠pári֤ym şĕ̌lòşá̌h֙ wĕ⁠ʼéypá֨h ʼaẖa֥ţ qe֨maẖ֙ wĕ⁠né֣bel ya֔yin wa⁠ţĕ̇biʼé֥⁠hẇ béyţ-yĕhwá֖h şǐl֑wò wĕ⁠ha⁠nȧ֖ʻar náֽʻar׃"],[1,25,"וַֽ⁠יִּשְׁחֲט֖וּ אֶת־הַ⁠פָּ֑ר וַ⁠יָּבִ֥יאוּ אֶת־הַ⁠נַּ֖עַר אֶל־עֵלִֽי׃","waֽ⁠yi̇şĕ̌ẖàt֖ẇ ʼeţ-ha⁠pá֑̇r wa⁠yá̇bi֥yʼẇ ʼeţ-ha⁠nȧ֖ʻar ʼel-ʻéliֽy׃"],[1,26,"וַ⁠תֹּ֨אמֶר֙ בִּ֣י אֲדֹנִ֔⁠י חֵ֥י נַפְשְׁ⁠ךָ֖ אֲדֹנִ֑⁠י אֲנִ֣י הָ⁠אִשָּׁ֗ה הַ⁠נִּצֶּ֤בֶת עִמְּ⁠כָה֙ בָּ⁠זֶ֔ה לְ⁠הִתְפַּלֵּ֖ל אֶל־יְהוָֽה׃","wa⁠ţò̇֨ʼmer֙ bi֣̇y ʼàdòni֔⁠y ẖé֥y napĕşĕ̌⁠ká֖ ʼàdòni֑⁠y ʼàni֣y há⁠ʼişá̇̌֗h ha⁠ni̇ẕė֤beţ ʻimĕ̇⁠káh֙ bá̇⁠ze֔h lĕ⁠hiţĕpȧlé֖̇l ʼel-yĕhwáֽh׃"],[1,27,"אֶל־הַ⁠נַּ֥עַר הַ⁠זֶּ֖ה הִתְפַּלָּ֑לְתִּי וַ⁠יִּתֵּ֨ן יְהוָ֥ה לִ⁠י֙ אֶת־שְׁאֵ֣לָתִ֔⁠י אֲשֶׁ֥ר שָׁאַ֖לְתִּי מֵ⁠עִמּֽ⁠וֹ׃","ʼel-ha⁠nȧ֥ʻar ha⁠zė֖h hiţĕpȧlá֑̇lĕţi̇y wa⁠yi̇ţé̇֨n yĕhwá֥h li⁠y֙ ʼeţ-şĕ̌ʼé֣láţi֔⁠y ʼàşě֥r şá̌ʼa֖lĕţi̇y mé⁠ʻiṁֽ⁠wò׃"],[1,28,"וְ⁠גַ֣ם אָנֹכִ֗י הִשְׁאִלְתִּ֨⁠הוּ֙ לַֽ⁠יהוָ֔ה כָּל־הַ⁠יָּמִים֙ אֲשֶׁ֣ר הָיָ֔ה ה֥וּא שָׁא֖וּל לַֽ⁠יהוָ֑ה וַ⁠יִּשְׁתַּ֥חוּ שָׁ֖ם לַ⁠יהוָֽה׃פ","wĕ⁠ga֣m ʼánòki֗y hişĕ̌ʼilĕţi̇֨⁠hẇ֙ laֽ⁠yhwá֔h ká̇l-ha⁠yá̇miym֙ ʼàşě֣r háyá֔h h֥ẇʼ şá̌ʼ֖ẇl laֽ⁠yhwá֑h wa⁠yi̇şĕ̌ţȧ֥ẖẇ şá֖̌m la⁠yhwáֽh׃p"],[2,1,"וַ⁠תִּתְפַּלֵּ֤ל חַנָּה֙ וַ⁠תֹּאמַ֔ר עָלַ֤ץ לִבִּ⁠י֙ בַּֽ⁠יהוָ֔ה רָ֥מָה קַרְנִ֖⁠י בַּֽ⁠יהוָ֑ה רָ֤חַב פִּ⁠י֙ עַל־א֣וֹיְבַ֔⁠י כִּ֥י שָׂמַ֖חְתִּי בִּ⁠ישׁוּעָתֶֽ⁠ךָ׃","wa⁠ţi̇ţĕpȧlé֤̇l ẖaná̇h֙ wa⁠ţò̇ʼma֔r ʻála֤ẕ libi̇⁠y֙ bȧֽ⁠yhwá֔h rá֥máh qarĕni֖⁠y bȧֽ⁠yhwá֑h rá֤ẖab pi̇⁠y֙ ʻal-ʼ֣wòyĕba֔⁠y ki֥̇y şá̂ma֖ẖĕţi̇y bi̇⁠yş̌ẇʻáţeֽ⁠ká׃"],[2,2,"אֵין־קָד֥וֹשׁ כַּ⁠יהוָ֖ה כִּ֣י אֵ֣ין בִּלְתֶּ֑⁠ךָ וְ⁠אֵ֥ין צ֖וּר כֵּ⁠אלֹהֵֽי⁠נוּ׃","ʼéyn-qád֥wòş̌ kȧ⁠yhwá֖h ki֣̇y ʼé֣yn bi̇lĕţė֑⁠ká wĕ⁠ʼé֥yn ẕ֖ẇr ké̇⁠ʼlòhéֽy⁠nẇ׃"],[2,3,"אַל־תַּרְבּ֤וּ תְדַבְּרוּ֙ גְּבֹהָ֣ה גְבֹהָ֔ה יֵצֵ֥א עָתָ֖ק מִ⁠פִּי⁠כֶ֑ם כִּ֣י אֵ֤ל דֵּעוֹת֙ יְהוָ֔ה ו⁠לא נִתְכְּנ֖וּ עֲלִלֽוֹת׃","ʼal-ţȧrĕḃ֤ẇ ţĕdabĕ̇rẇ֙ gĕ̇bòhá֣h gĕbòhá֔h yéẕé֥ʼ ʻáţá֖q mi⁠pi̇y⁠ke֑m ki֣̇y ʼé֤l dé̇ʻwòţ֙ yĕhwá֔h w⁠lʼ niţĕkĕ̇n֖ẇ ʻàlilֽwòţ׃"],[2,4,"קֶ֥שֶׁת גִּבֹּרִ֖ים חַתִּ֑ים וְ⁠נִכְשָׁלִ֖ים אָ֥זְרוּ חָֽיִל׃","qe֥şěţ gi̇bò̇ri֖ym ẖaţi֑̇ym wĕ⁠nikĕşá̌li֖ym ʼá֥zĕrẇ ẖáֽyil׃"],[2,5,"שְׂבֵעִ֤ים בַּ⁠לֶּ֨חֶם֙ נִשְׂכָּ֔רוּ וּ⁠רְעֵבִ֖ים חָדֵ֑לּוּ עַד־עֲקָרָה֙ יָלְדָ֣ה שִׁבְעָ֔ה וְ⁠רַבַּ֥ת בָּנִ֖ים אֻמְלָֽלָה׃","şĕ̂béʻi֤ym bȧ⁠lė֨ẖem֙ nişĕ̂ká̇֔rẇ ẇ⁠rĕʻébi֖ym ẖádé֑l̇ẇ ʻad-ʻàqáráh֙ yálĕdá֣h şǐbĕʻá֔h wĕ⁠rabȧ֥ţ bá̇ni֖ym ʼumĕláֽláh׃"],[2,6,"יְהוָ֖ה מֵמִ֣ית וּ⁠מְחַיֶּ֑ה מוֹרִ֥יד שְׁא֖וֹל וַ⁠יָּֽעַל׃","yĕhwá֖h mémi֣yţ ẇ⁠mĕẖayė֑h mwòri֥yd şĕ̌ʼ֖wòl wa⁠yáֽ̇ʻal׃"],[2,7,"יְהוָ֖ה מוֹרִ֣ישׁ וּ⁠מַעֲשִׁ֑יר מַשְׁפִּ֖יל אַף־מְרוֹמֵֽם׃","yĕhwá֖h mwòri֣yş̌ ẇ⁠maʻàşǐ֑yr maşĕ̌pi֖̇yl ʼap-mĕrwòméֽm׃"],[2,8,"מֵקִ֨ים מֵ⁠עָפָ֜ר דָּ֗ל מֵֽ⁠אַשְׁפֹּת֙ יָרִ֣ים אֶבְי֔וֹן לְ⁠הוֹשִׁיב֙ עִם־נְדִיבִ֔ים וְ⁠כִסֵּ֥א כָב֖וֹד יַנְחִלֵ֑⁠ם כִּ֤י לַֽ⁠יהוָה֙ מְצֻ֣קֵי אֶ֔רֶץ וַ⁠יָּ֥שֶׁת עֲלֵי⁠הֶ֖ם תֵּבֵֽל׃","méqi֨ym mé⁠ʻápá֜r dá̇֗l méֽ⁠ʼaşĕ̌pò̇ţ֙ yári֣ym ʼebĕy֔wòn lĕ⁠hwòşǐyb֙ ʻim-nĕdiybi֔ym wĕ⁠kisé֥̇ʼ káb֖wòd yanĕẖilé֑⁠m ki֤̇y laֽ⁠yhwáh֙ mĕẕu֣qéy ʼe֔reẕ wa⁠yá֥̇şěţ ʻàléy⁠he֖m ţé̇béֽl׃"],[2,9,"רַגְלֵ֤י חסיד⁠ו יִשְׁמֹ֔ר וּ⁠רְשָׁעִ֖ים בַּ⁠חֹ֣שֶׁךְ יִדָּ֑מּוּ כִּֽי־לֹ֥א בְ⁠כֹ֖חַ יִגְבַּר־אִֽישׁ׃","ragĕlé֤y ẖsyd⁠w yişĕ̌mò֔r ẇ⁠rĕşá̌ʻi֖ym bȧ⁠ẖò֣şěkĕ yidá֑̇ṁẇ kiֽ̇y-lò֥ʼ bĕ⁠kò֖ẖa yigĕbȧr-ʼiֽyş̌׃"],[2,10,"יְהוָ֞ה יֵחַ֣תּוּ מריב⁠ו על⁠ו בַּ⁠שָּׁמַ֣יִם יַרְעֵ֔ם יְהוָ֖ה יָדִ֣ין אַפְסֵי־אָ֑רֶץ וְ⁠יִתֶּן־עֹ֣ז לְ⁠מַלְכּ֔⁠וֹ וְ⁠יָרֵ֖ם קֶ֥רֶן מְשִׁיחֽ⁠וֹ׃פ","yĕhwá֞h yéẖa֣ţ̇ẇ mryb⁠w ʻl⁠w bȧ⁠şá̇̌ma֣yim yarĕʻé֔m yĕhwá֖h yádi֣yn ʼapĕséy-ʼá֑reẕ wĕ⁠yiţėn-ʻò֣z lĕ⁠malĕk̇֔⁠wò wĕ⁠yáré֖m qe֥ren mĕşǐyẖֽ⁠wò׃p"],[2,11,"וַ⁠יֵּ֧לֶךְ אֶלְקָנָ֛ה הָ⁠רָמָ֖תָ⁠ה עַל־בֵּית֑⁠וֹ וְ⁠הַ⁠נַּ֗עַר הָיָ֤ה מְשָׁרֵת֙ אֶת־יְהוָ֔ה אֶת־פְּנֵ֖י עֵלִ֥י הַ⁠כֹּהֵֽן׃","wa⁠yé֧̇lekĕ ʼelĕqáná֛h há⁠rámá֖ţá⁠h ʻal-bé̇yţ֑⁠wò wĕ⁠ha⁠nȧ֗ʻar háyá֤h mĕşá̌réţ֙ ʼeţ-yĕhwá֔h ʼeţ-pĕ̇né֖y ʻéli֥y ha⁠kò̇héֽn׃"],[2,12,"וּ⁠בְנֵ֥י עֵלִ֖י בְּנֵ֣י בְלִיָּ֑עַל לֹ֥א יָדְע֖וּ אֶת־יְהוָֽה׃","ẇ⁠bĕné֥y ʻéli֖y bĕ̇né֣y bĕliyá֑̇ʻal lò֥ʼ yádĕʻ֖ẇ ʼeţ-yĕhwáֽh׃"],[2,13,"וּ⁠מִשְׁפַּ֥ט הַ⁠כֹּהֲנִ֖ים אֶת־הָ⁠עָ֑ם כָּל־אִ֞ישׁ זֹבֵ֣חַ זֶ֗בַח וּ⁠בָ֨א נַ֤עַר הַ⁠כֹּהֵן֙ כְּ⁠בַשֵּׁ֣ל הַ⁠בָּשָׂ֔ר וְ⁠הַ⁠מַּזְלֵ֛ג שְׁלֹ֥שׁ־הַ⁠שִּׁנַּ֖יִם בְּ⁠יָדֽ⁠וֹ׃","ẇ⁠mişĕ̌pȧ֥t ha⁠kò̇hàni֖ym ʼeţ-há⁠ʻá֑m ká̇l-ʼi֞yş̌ zòbé֣ẖa ze֗baẖ ẇ⁠bá֨ʼ na֤ʻar ha⁠kò̇hén֙ kĕ̇⁠başé֣̇̌l ha⁠bá̇şá̂֔r wĕ⁠ha⁠mȧzĕlé֛g şĕ̌lò֥ş̌-ha⁠şi̇̌nȧ֖yim bĕ̇⁠yádֽ⁠wò׃"],[2,14,"וְ⁠הִכָּ֨ה בַ⁠כִּיּ֜וֹר א֣וֹ בַ⁠דּ֗וּד א֤וֹ בַ⁠קַּלַּ֨חַת֙ א֣וֹ בַ⁠פָּר֔וּר כֹּ֚ל אֲשֶׁ֣ר יַעֲלֶ֣ה הַ⁠מַּזְלֵ֔ג יִקַּ֥ח הַ⁠כֹּהֵ֖ן בּ֑⁠וֹ כָּ֚כָה יַעֲשׂ֣וּ לְ⁠כָל־יִשְׂרָאֵ֔ל הַ⁠בָּאִ֥ים שָׁ֖ם בְּ⁠שִׁלֹֽה׃","wĕ⁠hiká̇֨h ba⁠ki̇ẏ֜wòr ʼ֣wò ba⁠ḋ֗ẇd ʼ֤wò ba⁠qȧlȧ֨ẖaţ֙ ʼ֣wò ba⁠pá̇r֔ẇr kò֚̇l ʼàşě֣r yaʻàle֣h ha⁠mȧzĕlé֔g yiqȧ֥ẖ ha⁠kò̇hé֖n ḃ֑⁠wò ká֚̇káh yaʻàş֣̂ẇ lĕ⁠kál-yişĕ̂ráʼé֔l ha⁠bá̇ʼi֥ym şá֖̌m bĕ̇⁠şǐlòֽh׃"],[2,15,"גַּם֮ בְּ⁠טֶרֶם֮ יַקְטִר֣וּ⁠ן אֶת־הַ⁠חֵלֶב֒ וּ⁠בָ֣א ׀ נַ֣עַר הַ⁠כֹּהֵ֗ן וְ⁠אָמַר֙ לָ⁠אִ֣ישׁ הַ⁠זֹּבֵ֔חַ תְּנָ֣⁠ה בָשָׂ֔ר לִ⁠צְל֖וֹת לַ⁠כֹּהֵ֑ן וְ⁠לֹֽא־יִקַּ֧ח מִמְּ⁠ךָ֛ בָּשָׂ֥ר מְבֻשָּׁ֖ל כִּ֥י אִם־חָֽי׃","gȧm֮ bĕ̇⁠terem֮ yaqĕtir֣ẇ⁠n ʼeţ-ha⁠ẖéleb֒ ẇ⁠bá֣ʼ ׀ na֣ʻar ha⁠kò̇hé֗n wĕ⁠ʼámar֙ lá⁠ʼi֣yş̌ ha⁠zò̇bé֔ẖa ţĕ̇ná֣⁠h báşá̂֔r li⁠ẕĕl֖wòţ la⁠kò̇hé֑n wĕ⁠lòֽʼ-yiqȧ֧ẖ mimĕ̇⁠ká֛ bá̇şá֥̂r mĕbuşá֖̇̌l ki֥̇y ʼim-ẖáֽy׃"],[2,16,"וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו הָ⁠אִ֗ישׁ קַטֵּ֨ר יַקְטִיר֤וּ⁠ן כַּ⁠יּוֹם֙ הַ⁠חֵ֔לֶב וְ⁠קַ֨ח־לְ⁠ךָ֔ כַּ⁠אֲשֶׁ֥ר תְּאַוֶּ֖ה נַפְשֶׁ֑⁠ךָ וְ⁠אָמַ֥ר ׀ ל⁠ו כִּ֚י עַתָּ֣ה תִתֵּ֔ן וְ⁠אִם־לֹ֖א לָקַ֥חְתִּי בְ⁠חָזְקָֽה׃","wa⁠yò̇֨ʼmer ʼélá֜y⁠w há⁠ʼi֗yş̌ qaté̇֨r yaqĕtiyr֤ẇ⁠n kȧ⁠ẏwòm֙ ha⁠ẖé֔leb wĕ⁠qa֨ẖ-lĕ⁠ká֔ kȧ⁠ʼàşě֥r ţĕ̇ʼawė֖h napĕşě֑⁠ká wĕ⁠ʼáma֥r ׀ l⁠w ki֚̇y ʻaţá֣̇h ţiţé̇֔n wĕ⁠ʼim-lò֖ʼ láqa֥ẖĕţi̇y bĕ⁠ẖázĕqáֽh׃"],[2,17,"וַ⁠תְּהִ֨י חַטַּ֧את הַ⁠נְּעָרִ֛ים גְּדוֹלָ֥ה מְאֹ֖ד אֶת־פְּנֵ֣י יְהוָ֑ה כִּ֤י נִֽאֲצוּ֙ הָֽ⁠אֲנָשִׁ֔ים אֵ֖ת מִנְחַ֥ת יְהוָֽה׃","wa⁠ţĕ̇hi֨y ẖatȧ֧ʼţ ha⁠nĕ̇ʻári֛ym gĕ̇dwòlá֥h mĕʼò֖d ʼeţ-pĕ̇né֣y yĕhwá֑h ki֤̇y niֽʼàẕẇ֙ háֽ⁠ʼànáşǐ֔ym ʼé֖ţ minĕẖa֥ţ yĕhwáֽh׃"],[2,18,"וּ⁠שְׁמוּאֵ֕ל מְשָׁרֵ֖ת אֶת־פְּנֵ֣י יְהוָ֑ה נַ֕עַר חָג֖וּר אֵפ֥וֹד בָּֽד׃","ẇ⁠şĕ̌mẇʼé֕l mĕşá̌ré֖ţ ʼeţ-pĕ̇né֣y yĕhwá֑h na֕ʻar ẖág֖ẇr ʼép֥wòd báֽ̇d׃"],[2,19,"וּ⁠מְעִ֤יל קָטֹן֙ תַּעֲשֶׂה־לּ֣⁠וֹ אִמּ֔⁠וֹ וְ⁠הַעַלְתָ֥ה ל֖⁠וֹ מִ⁠יָּמִ֣ים ׀ יָמִ֑ימָ⁠ה בַּֽ⁠עֲלוֹתָ⁠הּ֙ אֶת־אִישָׁ֔⁠הּ לִ⁠זְבֹּ֖חַ אֶת־זֶ֥בַח הַ⁠יָּמִֽים׃","ẇ⁠mĕʻi֤yl qátòn֙ ţȧʻàşêh-l֣̇⁠wò ʼiṁ֔⁠wò wĕ⁠haʻalĕţá֥h l֖⁠wò mi⁠yá̇mi֣ym ׀ yámi֑ymá⁠h bȧֽ⁠ʻàlwòţá⁠ḣ֙ ʼeţ-ʼiyşá̌֔⁠ḣ li⁠zĕbò֖̇ẖa ʼeţ-ze֥baẖ ha⁠yá̇miֽym׃"],[2,20,"וּ⁠בֵרַ֨ךְ עֵלִ֜י אֶת־אֶלְקָנָ֣ה וְ⁠אֶת־אִשְׁתּ֗⁠וֹ וְ⁠אָמַר֙ יָשֵׂם֩ יְהוָ֨ה לְ⁠ךָ֥ זֶ֨רַע֙ מִן־הָ⁠אִשָּׁ֣ה הַ⁠זֹּ֔את תַּ֚חַת הַ⁠שְּׁאֵלָ֔ה אֲשֶׁ֥ר שָׁאַ֖ל לַֽ⁠יהוָ֑ה וְ⁠הָלְכ֖וּ לִ⁠מְקֹמֽ⁠וֹ׃","ẇ⁠béra֨kĕ ʻéli֜y ʼeţ-ʼelĕqáná֣h wĕ⁠ʼeţ-ʼişĕ̌ţ̇֗⁠wò wĕ⁠ʼámar֙ yáşé̂m֩ yĕhwá֨h lĕ⁠ká֥ ze֨raʻ֙ min-há⁠ʼişá֣̇̌h ha⁠zò̇֔ʼţ ţȧ֚ẖaţ ha⁠şĕ̇̌ʼélá֔h ʼàşě֥r şá̌ʼa֖l laֽ⁠yhwá֑h wĕ⁠hálĕk֖ẇ li⁠mĕqòmֽ⁠wò׃"],[2,21,"כִּֽי־פָקַ֤ד יְהוָה֙ אֶת־חַנָּ֔ה וַ⁠תַּ֛הַר וַ⁠תֵּ֥לֶד שְׁלֹשָֽׁה־בָנִ֖ים וּ⁠שְׁתֵּ֣י בָנ֑וֹת וַ⁠יִּגְדַּ֛ל הַ⁠נַּ֥עַר שְׁמוּאֵ֖ל עִם־יְהוָֽה׃ס","kiֽ̇y-páqa֤d yĕhwáh֙ ʼeţ-ẖaná̇֔h wa⁠ţȧ֛har wa⁠ţé֥̇led şĕ̌lòşáֽ̌h-báni֖ym ẇ⁠şĕ̌ţé֣̇y bán֑wòţ wa⁠yi̇gĕdȧ֛l ha⁠nȧ֥ʻar şĕ̌mẇʼé֖l ʻim-yĕhwáֽh׃s"],[2,22,"וְ⁠עֵלִ֖י זָקֵ֣ן מְאֹ֑ד וְ⁠שָׁמַ֗ע אֵת֩ כָּל־אֲשֶׁ֨ר יַעֲשׂ֤וּ⁠ן בָּנָי⁠ו֙ לְ⁠כָל־יִשְׂרָאֵ֔ל וְ⁠אֵ֤ת אֲשֶֽׁר־יִשְׁכְּבוּ⁠ן֙ אֶת־הַ⁠נָּשִׁ֔ים הַ⁠צֹּ֣בְא֔וֹת פֶּ֖תַח אֹ֥הֶל מוֹעֵֽד׃","wĕ⁠ʻéli֖y záqé֣n mĕʼò֑d wĕ⁠şá̌ma֗ʻ ʼéţ֩ ká̇l-ʼàşě֨r yaʻàş֤̂ẇ⁠n bá̇náy⁠w֙ lĕ⁠kál-yişĕ̂ráʼé֔l wĕ⁠ʼé֤ţ ʼàşěֽr-yişĕ̌kĕ̇bẇ⁠n֙ ʼeţ-ha⁠ná̇şǐ֔ym ha⁠ẕò֣̇bĕʼ֔wòţ pė֖ţaẖ ʼò֥hel mwòʻéֽd׃"],[2,23,"וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם לָ֥⁠מָּה תַעֲשׂ֖וּ⁠ן כַּ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה אֲשֶׁ֨ר אָנֹכִ֤י שֹׁמֵ֨עַ֙ אֶת־דִּבְרֵי⁠כֶ֣ם רָעִ֔ים מֵ⁠אֵ֖ת כָּל־הָ⁠עָ֥ם אֵֽלֶּה׃","wa⁠yò֣̇ʼmer lá⁠he֔m lá֥⁠má̇h ţaʻàş֖̂ẇ⁠n kȧ⁠dĕ̇bári֣ym há⁠ʼé֑lėh ʼàşě֨r ʼánòki֤y şò̌mé֨ʻa֙ ʼeţ-di̇bĕréy⁠ke֣m ráʻi֔ym mé⁠ʼé֖ţ ká̇l-há⁠ʻá֥m ʼéֽlėh׃"],[2,24,"אַ֖ל בָּנָ֑⁠י כִּ֠י לֽוֹא־טוֹבָ֤ה הַ⁠שְּׁמֻעָה֙ אֲשֶׁ֣ר אָנֹכִ֣י שֹׁמֵ֔עַ מַעֲבִרִ֖ים עַם־יְהוָֽה׃","ʼa֖l bá̇ná֑⁠y ki̇֠y lֽwòʼ-twòbá֤h ha⁠şĕ̇̌muʻáh֙ ʼàşě֣r ʼánòki֣y şò̌mé֔ʻa maʻàbiri֖ym ʻam-yĕhwáֽh׃"],[2,25,"אִם־יֶחֱטָ֨א אִ֤ישׁ לְ⁠אִישׁ֙ וּ⁠פִֽלְל֣⁠וֹ אֱלֹהִ֔ים וְ⁠אִ֤ם לַֽ⁠יהוָה֙ יֶֽחֱטָא־אִ֔ישׁ מִ֖י יִתְפַּלֶּל־ל֑⁠וֹ וְ⁠לֹ֤א יִשְׁמְעוּ֙ לְ⁠ק֣וֹל אֲבִי⁠הֶ֔ם כִּֽי־חָפֵ֥ץ יְהוָ֖ה לַ⁠הֲמִיתָֽ⁠ם׃","ʼim-yeẖètá֨ʼ ʼi֤yş̌ lĕ⁠ʼiyş̌֙ ẇ⁠piֽlĕl֣⁠wò ʼèlòhi֔ym wĕ⁠ʼi֤m laֽ⁠yhwáh֙ yֽeẖètáʼ-ʼi֔yş̌ mi֖y yiţĕpȧlėl-l֑⁠wò wĕ⁠lò֤ʼ yişĕ̌mĕʻẇ֙ lĕ⁠q֣wòl ʼàbiy⁠he֔m kiֽ̇y-ẖápé֥ẕ yĕhwá֖h la⁠hàmiyţáֽ⁠m׃"],[2,26,"וְ⁠הַ⁠נַּ֣עַר שְׁמוּאֵ֔ל הֹלֵ֥ךְ וְ⁠גָדֵ֖ל וָ⁠ט֑וֹב גַּ֚ם עִם־יְהוָ֔ה וְ⁠גַ֖ם עִם־אֲנָשִֽׁים׃ס","wĕ⁠ha⁠nȧ֣ʻar şĕ̌mẇʼé֔l hòlé֥kĕ wĕ⁠gádé֖l wá⁠t֑wòb gȧ֚m ʻim-yĕhwá֔h wĕ⁠ga֖m ʻim-ʼànáşǐֽym׃s"],[2,27,"וַ⁠יָּבֹ֥א אִישׁ־אֱלֹהִ֖ים אֶל־עֵלִ֑י וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר יְהוָ֔ה הֲ⁠נִגְלֹ֤ה נִגְלֵ֨יתִי֙ אֶל־בֵּ֣ית אָבִ֔י⁠ךָ בִּֽ⁠הְיוֹתָ֥⁠ם בְּ⁠מִצְרַ֖יִם לְ⁠בֵ֥ית פַּרְעֹֽה׃","wa⁠yá̇bò֥ʼ ʼiyş̌-ʼèlòhi֖ym ʼel-ʻéli֑y wa⁠yò֣̇ʼmer ʼélá֗y⁠w kò֚̇h ʼáma֣r yĕhwá֔h hà⁠nigĕlò֤h nigĕlé֨yţiy֙ ʼel-bé֣̇yţ ʼábi֔y⁠ká biֽ̇⁠hĕywòţá֥⁠m bĕ̇⁠miẕĕra֖yim lĕ⁠bé֥yţ pȧrĕʻòֽh׃"],[2,28,"וּ⁠בָחֹ֣ר אֹ֠ת⁠וֹ מִ⁠כָּל־שִׁבְטֵ֨י יִשְׂרָאֵ֥ל לִ⁠י֙ לְ⁠כֹהֵ֔ן לַ⁠עֲל֣וֹת עַֽל־מִזְבְּחִ֗⁠י לְ⁠הַקְטִ֥יר קְטֹ֛רֶת לָ⁠שֵׂ֥את אֵפ֖וֹד לְ⁠פָנָ֑⁠י וָֽ⁠אֶתְּנָ⁠ה֙ לְ⁠בֵ֣ית אָבִ֔י⁠ךָ אֶת־כָּל־אִשֵּׁ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","ẇ⁠báẖò֣r ʼò֠ţ⁠wò mi⁠ká̇l-şǐbĕté֨y yişĕ̂ráʼé֥l li⁠y֙ lĕ⁠kòhé֔n la⁠ʻàl֣wòţ ʻaֽl-mizĕbĕ̇ẖi֗⁠y lĕ⁠haqĕti֥yr qĕtò֛reţ lá⁠şé֥̂ʼţ ʼép֖wòd lĕ⁠páná֑⁠y wáֽ⁠ʼeţĕ̇ná⁠h֙ lĕ⁠bé֣yţ ʼábi֔y⁠ká ʼeţ-ká̇l-ʼişé֖̇̌y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[2,29,"לָ֣⁠מָּה תִבְעֲט֗וּ בְּ⁠זִבְחִ⁠י֙ וּ⁠בְ⁠מִנְחָתִ֔⁠י אֲשֶׁ֥ר צִוִּ֖יתִי מָע֑וֹן וַ⁠תְּכַבֵּ֤ד אֶת־בָּנֶ֨י⁠ךָ֙ מִמֶּ֔⁠נִּי לְ⁠הַבְרִֽיאֲ⁠כֶ֗ם מֵ⁠רֵאשִׁ֛ית כָּל־מִנְחַ֥ת יִשְׂרָאֵ֖ל לְ⁠עַמִּֽ⁠י׃","lá֣⁠má̇h ţibĕʻàt֗ẇ bĕ̇⁠zibĕẖi⁠y֙ ẇ⁠bĕ⁠minĕẖáţi֔⁠y ʼàşě֥r ẕiwi֖̇yţiy máʻ֑wòn wa⁠ţĕ̇kabé֤̇d ʼeţ-bá̇ne֨y⁠ká֙ mimė֔⁠ni̇y lĕ⁠habĕriֽyʼà⁠ke֗m mé⁠réʼşǐ֛yţ ká̇l-minĕẖa֥ţ yişĕ̂ráʼé֖l lĕ⁠ʻamiֽ̇⁠y׃"],[2,30,"לָ⁠כֵ֗ן נְאֻם־יְהוָה֮ אֱלֹהֵ֣י יִשְׂרָאֵל֒ אָמ֣וֹר אָמַ֔רְתִּי בֵּֽיתְ⁠ךָ֙ וּ⁠בֵ֣ית אָבִ֔י⁠ךָ יִתְהַלְּכ֥וּ לְ⁠פָנַ֖⁠י עַד־עוֹלָ֑ם וְ⁠עַתָּ֤ה נְאֻם־יְהוָה֙ חָלִ֣ילָ⁠ה לִּ֔⁠י כִּֽי־מְכַבְּדַ֥⁠י אֲכַבֵּ֖ד וּ⁠בֹזַ֥⁠י יֵקָֽלּוּ׃","lá⁠ké֗n nĕʼum-yĕhwáh֮ ʼèlòhé֣y yişĕ̂ráʼél֒ ʼám֣wòr ʼáma֔rĕţi̇y béֽ̇yţĕ⁠ká֙ ẇ⁠bé֣yţ ʼábi֔y⁠ká yiţĕhalĕ̇k֥ẇ lĕ⁠pána֖⁠y ʻad-ʻwòlá֑m wĕ⁠ʻaţá֤̇h nĕʼum-yĕhwáh֙ ẖáli֣ylá⁠h li̇֔⁠y kiֽ̇y-mĕkabĕ̇da֥⁠y ʼàkabé֖̇d ẇ⁠bòza֥⁠y yéqáֽl̇ẇ׃"],[2,31,"הִנֵּה֙ יָמִ֣ים בָּאִ֔ים וְ⁠גָֽדַעְתִּי֙ אֶת־זְרֹ֣עֲ⁠ךָ֔ וְ⁠אֶת־זְרֹ֖עַ בֵּ֣ית אָבִ֑י⁠ךָ מִֽ⁠הְי֥וֹת זָקֵ֖ן בְּ⁠בֵיתֶֽ⁠ךָ׃","hiné̇h֙ yámi֣ym bá̇ʼi֔ym wĕ⁠gáֽdaʻĕţi̇y֙ ʼeţ-zĕrò֣ʻà⁠ká֔ wĕ⁠ʼeţ-zĕrò֖ʻa bé֣̇yţ ʼábi֑y⁠ká miֽ⁠hĕy֥wòţ záqé֖n bĕ̇⁠béyţeֽ⁠ká׃"],[2,32,"וְ⁠הִבַּטְתָּ֙ צַ֣ר מָע֔וֹן בְּ⁠כֹ֥ל אֲשֶׁר־יֵיטִ֖יב אֶת־יִשְׂרָאֵ֑ל וְ⁠לֹֽא־יִהְיֶ֥ה זָקֵ֛ן בְּ⁠בֵיתְ⁠ךָ֖ כָּל־הַ⁠יָּמִֽים׃","wĕ⁠hibȧtĕţá̇֙ ẕa֣r máʻ֔wòn bĕ̇⁠kò֥l ʼàşěr-yéyti֖yb ʼeţ-yişĕ̂ráʼé֑l wĕ⁠lòֽʼ-yihĕye֥h záqé֛n bĕ̇⁠béyţĕ⁠ká֖ ká̇l-ha⁠yá̇miֽym׃"],[2,33,"וְ⁠אִ֗ישׁ לֹֽא־אַכְרִ֤ית לְ⁠ךָ֙ מֵ⁠עִ֣ם מִזְבְּחִ֔⁠י לְ⁠כַלּ֥וֹת אֶת־עֵינֶ֖י⁠ךָ וְ⁠לַ⁠אֲדִ֣יב אֶת־נַפְשֶׁ֑⁠ךָ וְ⁠כָל־מַרְבִּ֥ית בֵּיתְ⁠ךָ֖ יָמ֥וּתוּ אֲנָשִֽׁים׃","wĕ⁠ʼi֗yş̌ lòֽʼ-ʼakĕri֤yţ lĕ⁠ká֙ mé⁠ʻi֣m mizĕbĕ̇ẖi֔⁠y lĕ⁠kal֥̇wòţ ʼeţ-ʻéyne֖y⁠ká wĕ⁠la⁠ʼàdi֣yb ʼeţ-napĕşě֑⁠ká wĕ⁠kál-marĕbi֥̇yţ bé̇yţĕ⁠ká֖ yám֥ẇţẇ ʼànáşǐֽym׃"],[2,34,"וְ⁠זֶה־לְּ⁠ךָ֣ הָ⁠א֗וֹת אֲשֶׁ֤ר יָבֹא֙ אֶל־שְׁנֵ֣י בָנֶ֔י⁠ךָ אֶל־חָפְנִ֖י וּ⁠פִֽינְחָ֑ס בְּ⁠י֥וֹם אֶחָ֖ד יָמ֥וּתוּ שְׁנֵי⁠הֶֽם׃","wĕ⁠zeh-lĕ̇⁠ká֣ há⁠ʼ֗wòţ ʼàşě֤r yábòʼ֙ ʼel-şĕ̌né֣y báne֔y⁠ká ʼel-ẖápĕni֖y ẇ⁠piֽynĕẖá֑s bĕ̇⁠y֥wòm ʼeẖá֖d yám֥ẇţẇ şĕ̌néy⁠heֽm׃"],[2,35,"וַ⁠הֲקִימֹתִ֥י לִ⁠י֙ כֹּהֵ֣ן נֶאֱמָ֔ן כַּ⁠אֲשֶׁ֛ר בִּ⁠לְבָבִ֥⁠י וּ⁠בְ⁠נַפְשִׁ֖⁠י יַעֲשֶׂ֑ה וּ⁠בָנִ֤יתִי ל⁠וֹ֙ בַּ֣יִת נֶאֱמָ֔ן וְ⁠הִתְהַלֵּ֥ךְ לִ⁠פְנֵֽי־מְשִׁיחִ֖⁠י כָּל־הַ⁠יָּמִֽים׃","wa⁠hàqiymòţi֥y li⁠y֙ kò̇hé֣n neʼèmá֔n kȧ⁠ʼàşě֛r bi̇⁠lĕbábi֥⁠y ẇ⁠bĕ⁠napĕşǐ֖⁠y yaʻàşê֑h ẇ⁠báni֤yţiy l⁠wò֙ bȧ֣yiţ neʼèmá֔n wĕ⁠hiţĕhalé֥̇kĕ li⁠pĕnéֽy-mĕşǐyẖi֖⁠y ká̇l-ha⁠yá̇miֽym׃"],[2,36,"וְ⁠הָיָ֗ה כָּל־הַ⁠נּוֹתָר֙ בְּ⁠בֵ֣יתְ⁠ךָ֔ יָבוֹא֙ לְ⁠הִשְׁתַּחֲוֺ֣ת ל֔⁠וֹ לַ⁠אֲג֥וֹרַת כֶּ֖סֶף וְ⁠כִכַּר־לָ֑חֶם וְ⁠אָמַ֗ר סְפָחֵ֥⁠נִי נָ֛א אֶל־אַחַ֥ת הַ⁠כְּהֻנּ֖וֹת לֶ⁠אֱכֹ֥ל פַּת־לָֽחֶם׃ס","wĕ⁠háyá֗h ká̇l-ha⁠ṅwòţár֙ bĕ̇⁠bé֣yţĕ⁠ká֔ yábwòʼ֙ lĕ⁠hişĕ̌ţȧẖàwֺ֣ţ l֔⁠wò la⁠ʼàg֥wòraţ kė֖sep wĕ⁠kikȧr-lá֑ẖem wĕ⁠ʼáma֗r sĕpáẖé֥⁠niy ná֛ʼ ʼel-ʼaẖa֥ţ ha⁠kĕ̇huṅ֖wòţ le⁠ʼèkò֥l pȧţ-láֽẖem׃s"],[3,1,"וְ⁠הַ⁠נַּ֧עַר שְׁמוּאֵ֛ל מְשָׁרֵ֥ת אֶת־יְהוָ֖ה לִ⁠פְנֵ֣י עֵלִ֑י וּ⁠דְבַר־יְהוָ֗ה הָיָ֤ה יָקָר֙ בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם אֵ֥ין חָז֖וֹן נִפְרָֽץ׃ס","wĕ⁠ha⁠nȧ֧ʻar şĕ̌mẇʼé֛l mĕşá̌ré֥ţ ʼeţ-yĕhwá֖h li⁠pĕné֣y ʻéli֑y ẇ⁠dĕbar-yĕhwá֗h háyá֤h yáqár֙ bȧ⁠yá̇mi֣ym há⁠hé֔m ʼé֥yn ẖáz֖wòn nipĕráֽẕ׃s"],[3,2,"וַֽ⁠יְהִי֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וְ⁠עֵלִ֖י שֹׁכֵ֣ב בִּ⁠מְקֹמ֑⁠וֹ ו⁠עינ⁠ו הֵחֵ֣לּוּ כֵה֔וֹת לֹ֥א יוּכַ֖ל לִ⁠רְאֽוֹת׃","waֽ⁠yĕhiy֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ wĕ⁠ʻéli֖y şò̌ké֣b bi̇⁠mĕqòm֑⁠wò w⁠ʻyn⁠w héẖé֣l̇ẇ kéh֔wòţ lò֥ʼ yẇka֖l li⁠rĕʼֽwòţ׃"],[3,3,"וְ⁠נֵ֤ר אֱלֹהִים֙ טֶ֣רֶם יִכְבֶּ֔ה וּ⁠שְׁמוּאֵ֖ל שֹׁכֵ֑ב בְּ⁠הֵיכַ֣ל יְהוָ֔ה אֲשֶׁר־שָׁ֖ם אֲר֥וֹן אֱלֹהִֽים׃פ","wĕ⁠né֤r ʼèlòhiym֙ te֣rem yikĕbė֔h ẇ⁠şĕ̌mẇʼé֖l şò̌ké֑b bĕ̇⁠héyka֣l yĕhwá֔h ʼàşěr-şá֖̌m ʼàr֥wòn ʼèlòhiֽym׃p"],[3,4,"וַ⁠יִּקְרָ֧א יְהוָ֛ה אֶל־שְׁמוּאֵ֖ל וַ⁠יֹּ֥אמֶר הִנֵּֽ⁠נִי׃","wa⁠yi̇qĕrá֧ʼ yĕhwá֛h ʼel-şĕ̌mẇʼé֖l wa⁠yò֥̇ʼmer hinéֽ̇⁠niy׃"],[3,5,"וַ⁠יָּ֣רָץ אֶל־עֵלִ֗י וַ⁠יֹּ֤אמֶר הִנְ⁠נִי֙ כִּֽי־קָרָ֣אתָ לִּ֔⁠י וַ⁠יֹּ֥אמֶר לֹֽא־קָרָ֖אתִי שׁ֣וּב שְׁכָ֑ב וַ⁠יֵּ֖לֶךְ וַ⁠יִּשְׁכָּֽב׃ס","wa⁠yá֣̇ráẕ ʼel-ʻéli֗y wa⁠yò֤̇ʼmer hinĕ⁠niy֙ kiֽ̇y-qárá֣ʼţá li̇֔⁠y wa⁠yò֥̇ʼmer lòֽʼ-qárá֖ʼţiy ş֣̌ẇb şĕ̌ká֑b wa⁠yé֖̇lekĕ wa⁠yi̇şĕ̌káֽ̇b׃s"],[3,6,"וַ⁠יֹּ֣סֶף יְהוָ֗ה קְרֹ֣א עוֹד֮ שְׁמוּאֵל֒ וַ⁠יָּ֤קָם שְׁמוּאֵל֙ וַ⁠יֵּ֣לֶךְ אֶל־עֵלִ֔י וַ⁠יֹּ֣אמֶר הִנְ⁠נִ֔י כִּ֥י קָרָ֖אתָ לִ֑⁠י וַ⁠יֹּ֛אמֶר לֹֽא־קָרָ֥אתִי בְנִ֖⁠י שׁ֥וּב שְׁכָֽב׃","wa⁠yò֣̇sep yĕhwá֗h qĕrò֣ʼ ʻwòd֮ şĕ̌mẇʼél֒ wa⁠yá֤̇qám şĕ̌mẇʼél֙ wa⁠yé֣̇lekĕ ʼel-ʻéli֔y wa⁠yò֣̇ʼmer hinĕ⁠ni֔y ki֥̇y qárá֖ʼţá li֑⁠y wa⁠yò֛̇ʼmer lòֽʼ-qárá֥ʼţiy bĕni֖⁠y ş֥̌ẇb şĕ̌káֽb׃"],[3,7,"וּ⁠שְׁמוּאֵ֕ל טֶ֖רֶם יָדַ֣ע אֶת־יְהוָ֑ה וְ⁠טֶ֛רֶם יִגָּלֶ֥ה אֵלָ֖י⁠ו דְּבַר־יְהוָֽה׃","ẇ⁠şĕ̌mẇʼé֕l te֖rem yáda֣ʻ ʼeţ-yĕhwá֑h wĕ⁠te֛rem yigá̇le֥h ʼélá֖y⁠w dĕ̇bar-yĕhwáֽh׃"],[3,8,"וַ⁠יֹּ֨סֶף יְהוָ֥ה קְרֹא־שְׁמוּאֵל֮ בַּ⁠שְּׁלִשִׁית֒ וַ⁠יָּ֨קָם֙ וַ⁠יֵּ֣לֶךְ אֶל־עֵלִ֔י וַ⁠יֹּ֣אמֶר הִנְ⁠נִ֔י כִּ֥י קָרָ֖אתָ לִ֑⁠י וַ⁠יָּ֣בֶן עֵלִ֔י כִּ֥י יְהוָ֖ה קֹרֵ֥א לַ⁠נָּֽעַר׃","wa⁠yò̇֨sep yĕhwá֥h qĕròʼ-şĕ̌mẇʼél֮ bȧ⁠şĕ̇̌lişǐyţ֒ wa⁠yá̇֨qám֙ wa⁠yé֣̇lekĕ ʼel-ʻéli֔y wa⁠yò֣̇ʼmer hinĕ⁠ni֔y ki֥̇y qárá֖ʼţá li֑⁠y wa⁠yá֣̇ben ʻéli֔y ki֥̇y yĕhwá֖h qòré֥ʼ la⁠náֽ̇ʻar׃"],[3,9,"וַ⁠יֹּ֨אמֶר עֵלִ֣י לִ⁠שְׁמוּאֵל֮ לֵ֣ךְ שְׁכָב֒ וְ⁠הָיָה֙ אִם־יִקְרָ֣א אֵלֶ֔י⁠ךָ וְ⁠אָֽמַרְתָּ֙ דַּבֵּ֣ר יְהוָ֔ה כִּ֥י שֹׁמֵ֖עַ עַבְדֶּ֑⁠ךָ וַ⁠יֵּ֣לֶךְ שְׁמוּאֵ֔ל וַ⁠יִּשְׁכַּ֖ב בִּ⁠מְקוֹמֽ⁠וֹ׃","wa⁠yò̇֨ʼmer ʻéli֣y li⁠şĕ̌mẇʼél֮ lé֣kĕ şĕ̌káb֒ wĕ⁠háyáh֙ ʼim-yiqĕrá֣ʼ ʼéle֔y⁠ká wĕ⁠ʼáֽmarĕţá̇֙ dȧbé֣̇r yĕhwá֔h ki֥̇y şò̌mé֖ʻa ʻabĕdė֑⁠ká wa⁠yé֣̇lekĕ şĕ̌mẇʼé֔l wa⁠yi̇şĕ̌kȧ֖b bi̇⁠mĕqwòmֽ⁠wò׃"],[3,10,"וַ⁠יָּבֹ֤א יְהוָה֙ וַ⁠יִּתְיַצַּ֔ב וַ⁠יִּקְרָ֥א כְ⁠פַֽעַם־בְּ⁠פַ֖עַם שְׁמוּאֵ֣ל ׀ שְׁמוּאֵ֑ל וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ דַּבֵּ֔ר כִּ֥י שֹׁמֵ֖עַ עַבְדֶּֽ⁠ךָ׃פ","wa⁠yá̇bò֤ʼ yĕhwáh֙ wa⁠yi̇ţĕyaẕȧ֔b wa⁠yi̇qĕrá֥ʼ kĕ⁠paֽʻam-bĕ̇⁠pa֖ʻam şĕ̌mẇʼé֣l ׀ şĕ̌mẇʼé֑l wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ dȧbé̇֔r ki֥̇y şò̌mé֖ʻa ʻabĕdėֽ⁠ká׃p"],[3,11,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־שְׁמוּאֵ֔ל הִנֵּ֧ה אָנֹכִ֛י עֹשֶׂ֥ה דָבָ֖ר בְּ⁠יִשְׂרָאֵ֑ל אֲשֶׁר֙ כָּל־שֹׁ֣מְע֔⁠וֹ תְּצִלֶּ֖ינָה שְׁתֵּ֥י אָזְנָֽי⁠ו׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-şĕ̌mẇʼé֔l hiné֧̇h ʼánòki֛y ʻòşê֥h dábá֖r bĕ̇⁠yişĕ̂ráʼé֑l ʼàşěr֙ ká̇l-şò֣̌mĕʻ֔⁠wò ţĕ̇ẕilė֖ynáh şĕ̌ţé֥̇y ʼázĕnáֽy⁠w׃"],[3,12,"בַּ⁠יּ֤וֹם הַ⁠הוּא֙ אָקִ֣ים אֶל־עֵלִ֔י אֵ֛ת כָּל־אֲשֶׁ֥ר דִּבַּ֖רְתִּי אֶל־בֵּית֑⁠וֹ הָחֵ֖ל וְ⁠כַלֵּֽה׃","bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ ʼáqi֣ym ʼel-ʻéli֔y ʼé֛ţ ká̇l-ʼàşě֥r di̇bȧ֖rĕţi̇y ʼel-bé̇yţ֑⁠wò háẖé֖l wĕ⁠kaléֽ̇h׃"],[3,13,"וְ⁠הִגַּ֣דְתִּי ל֔⁠וֹ כִּֽי־שֹׁפֵ֥ט אֲנִ֛י אֶת־בֵּית֖⁠וֹ עַד־עוֹלָ֑ם בַּ⁠עֲוֺ֣ן אֲשֶׁר־יָדַ֗ע כִּֽי־מְקַֽלְלִ֤ים לָ⁠הֶם֙ בָּנָ֔י⁠ו וְ⁠לֹ֥א כִהָ֖ה בָּֽ⁠ם׃","wĕ⁠higȧ֣dĕţi̇y l֔⁠wò kiֽ̇y-şò̌pé֥t ʼàni֛y ʼeţ-bé̇yţ֖⁠wò ʻad-ʻwòlá֑m bȧ⁠ʻàwֺ֣n ʼàşěr-yáda֗ʻ kiֽ̇y-mĕqaֽlĕli֤ym lá⁠hem֙ bá̇ná֔y⁠w wĕ⁠lò֥ʼ kihá֖h báֽ̇⁠m׃"],[3,14,"וְ⁠לָ⁠כֵ֥ן נִשְׁבַּ֖עְתִּי לְ⁠בֵ֣ית עֵלִ֑י אִֽם־יִתְכַּפֵּ֞ר עֲוֺ֧ן בֵּית־עֵלִ֛י בְּ⁠זֶ֥בַח וּ⁠בְ⁠מִנְחָ֖ה עַד־עוֹלָֽם׃","wĕ⁠lá⁠ké֥n nişĕ̌bȧ֖ʻĕţi̇y lĕ⁠bé֣yţ ʻéli֑y ʼiֽm-yiţĕkȧpé̇֞r ʻàwֺ֧n bé̇yţ-ʻéli֛y bĕ̇⁠ze֥baẖ ẇ⁠bĕ⁠minĕẖá֖h ʻad-ʻwòláֽm׃"],[3,15,"וַ⁠יִּשְׁכַּ֤ב שְׁמוּאֵל֙ עַד־הַ⁠בֹּ֔קֶר וַ⁠יִּפְתַּ֖ח אֶת־דַּלְת֣וֹת בֵּית־יְהוָ֑ה וּ⁠שְׁמוּאֵ֣ל יָרֵ֔א מֵ⁠הַגִּ֥יד אֶת־הַ⁠מַּרְאָ֖ה אֶל־עֵלִֽי׃","wa⁠yi̇şĕ̌kȧ֤b şĕ̌mẇʼél֙ ʻad-ha⁠bò̇֔qer wa⁠yi̇pĕţȧ֖ẖ ʼeţ-dȧlĕţ֣wòţ bé̇yţ-yĕhwá֑h ẇ⁠şĕ̌mẇʼé֣l yáré֔ʼ mé⁠hagi֥̇yd ʼeţ-ha⁠mȧrĕʼá֖h ʼel-ʻéliֽy׃"],[3,16,"וַ⁠יִּקְרָ֤א עֵלִי֙ אֶת־שְׁמוּאֵ֔ל וַ⁠יֹּ֖אמֶר שְׁמוּאֵ֣ל בְּנִ֑⁠י וַ⁠יֹּ֖אמֶר הִנֵּֽ⁠נִי׃","wa⁠yi̇qĕrá֤ʼ ʻéliy֙ ʼeţ-şĕ̌mẇʼé֔l wa⁠yò֖̇ʼmer şĕ̌mẇʼé֣l bĕ̇ni֑⁠y wa⁠yò֖̇ʼmer hinéֽ̇⁠niy׃"],[3,17,"וַ⁠יֹּ֗אמֶר מָ֤ה הַ⁠דָּבָר֙ אֲשֶׁ֣ר דִּבֶּ֣ר אֵלֶ֔י⁠ךָ אַל־נָ֥א תְכַחֵ֖ד מִמֶּ֑⁠נִּי כֹּ֣ה יַעֲשֶׂה־לְּ⁠ךָ֤ אֱלֹהִים֙ וְ⁠כֹ֣ה יוֹסִ֔יף אִם־תְּכַחֵ֤ד מִמֶּ֨⁠נִּי֙ דָּבָ֔ר מִ⁠כָּל־הַ⁠דָּבָ֖ר אֲשֶׁר־דִּבֶּ֥ר אֵלֶֽי⁠ךָ׃","wa⁠yò̇֗ʼmer má֤h ha⁠dá̇bár֙ ʼàşě֣r di̇bė֣r ʼéle֔y⁠ká ʼal-ná֥ʼ ţĕkaẖé֖d mimė֑⁠ni̇y kò֣̇h yaʻàşêh-lĕ̇⁠ká֤ ʼèlòhiym֙ wĕ⁠kò֣h ywòsi֔yp ʼim-ţĕ̇kaẖé֤d mimė֨⁠ni̇y֙ dá̇bá֔r mi⁠ká̇l-ha⁠dá̇bá֖r ʼàşěr-di̇bė֥r ʼéleֽy⁠ká׃"],[3,18,"וַ⁠יַּגֶּד־ל֤⁠וֹ שְׁמוּאֵל֙ אֶת־כָּל־הַ⁠דְּבָרִ֔ים וְ⁠לֹ֥א כִחֵ֖ד מִמֶּ֑⁠נּוּ וַ⁠יֹּאמַ֕ר יְהוָ֣ה ה֔וּא הַ⁠טּ֥וֹב בעינו יַעֲשֶֽׂה׃פ","wa⁠yȧgėd-l֤⁠wò şĕ̌mẇʼél֙ ʼeţ-ká̇l-ha⁠dĕ̇bári֔ym wĕ⁠lò֥ʼ kiẖé֖d mimė֑⁠ṅẇ wa⁠yò̇ʼma֕r yĕhwá֣h h֔ẇʼ ha⁠ṫ֥wòb bʻynw yaʻàşêֽh׃p"],[3,19,"וַ⁠יִּגְדַּ֖ל שְׁמוּאֵ֑ל וַֽ⁠יהוָה֙ הָיָ֣ה עִמּ֔⁠וֹ וְ⁠לֹֽא־הִפִּ֥יל מִ⁠כָּל־דְּבָרָ֖י⁠ו אָֽרְצָ⁠ה׃","wa⁠yi̇gĕdȧ֖l şĕ̌mẇʼé֑l waֽ⁠yhwáh֙ háyá֣h ʻiṁ֔⁠wò wĕ⁠lòֽʼ-hipi֥̇yl mi⁠ká̇l-dĕ̇bárá֖y⁠w ʼáֽrĕẕá⁠h׃"],[3,20,"וַ⁠יֵּ֨דַע֙ כָּל־יִשְׂרָאֵ֔ל מִ⁠דָּ֖ן וְ⁠עַד־בְּאֵ֣ר שָׁ֑בַע כִּ֚י נֶאֱמָ֣ן שְׁמוּאֵ֔ל לְ⁠נָבִ֖יא לַ⁠יהוָֽה׃","wa⁠yé̇֨daʻ֙ ká̇l-yişĕ̂ráʼé֔l mi⁠dá֖̇n wĕ⁠ʻad-bĕ̇ʼé֣r şá֑̌baʻ ki֚̇y neʼèmá֣n şĕ̌mẇʼé֔l lĕ⁠nábi֖yʼ la⁠yhwáֽh׃"],[3,21,"וַ⁠יֹּ֥סֶף יְהוָ֖ה לְ⁠הֵרָאֹ֣ה בְ⁠שִׁלֹ֑ה כִּֽי־נִגְלָ֨ה יְהוָ֧ה אֶל־שְׁמוּאֵ֛ל בְּ⁠שִׁל֖וֹ בִּ⁠דְבַ֥ר יְהוָֽה׃פ","wa⁠yò֥̇sep yĕhwá֖h lĕ⁠héráʼò֣h bĕ⁠şǐlò֑h kiֽ̇y-nigĕlá֨h yĕhwá֧h ʼel-şĕ̌mẇʼé֛l bĕ̇⁠şǐl֖wò bi̇⁠dĕba֥r yĕhwáֽh׃p"],[4,1,"וַ⁠יְהִ֥י דְבַר־שְׁמוּאֵ֖ל לְ⁠כָל־יִשְׂרָאֵ֑ל וַ⁠יֵּצֵ֣א יִשְׂרָאֵל֩ לִ⁠קְרַ֨את פְּלִשְׁתִּ֜ים לַ⁠מִּלְחָמָ֗ה וַֽ⁠יַּחֲנוּ֙ עַל־הָ⁠אֶ֣בֶן הָעֵ֔זֶר וּ⁠פְלִשְׁתִּ֖ים חָנ֥וּ בַ⁠אֲפֵֽק׃","wa⁠yĕhi֥y dĕbar-şĕ̌mẇʼé֖l lĕ⁠kál-yişĕ̂ráʼé֑l wa⁠yé̇ẕé֣ʼ yişĕ̂ráʼél֩ li⁠qĕra֨ʼţ pĕ̇lişĕ̌ţi̇֜ym la⁠mi̇lĕẖámá֗h waֽ⁠yȧẖànẇ֙ ʻal-há⁠ʼe֣ben háʻé֔zer ẇ⁠pĕlişĕ̌ţi֖̇ym ẖán֥ẇ ba⁠ʼàpéֽq׃"],[4,2,"וַ⁠יַּעַרְכ֨וּ פְלִשְׁתִּ֜ים לִ⁠קְרַ֣את יִשְׂרָאֵ֗ל וַ⁠תִּטֹּשׁ֙ הַ⁠מִּלְחָמָ֔ה וַ⁠יִּנָּ֥גֶף יִשְׂרָאֵ֖ל לִ⁠פְנֵ֣י פְלִשְׁתִּ֑ים וַ⁠יַּכּ֤וּ בַ⁠מַּֽעֲרָכָה֙ בַּ⁠שָּׂדֶ֔ה כְּ⁠אַרְבַּ֥עַת אֲלָפִ֖ים אִֽישׁ׃","wa⁠yȧʻarĕk֨ẇ pĕlişĕ̌ţi̇֜ym li⁠qĕra֣ʼţ yişĕ̂ráʼé֗l wa⁠ţi̇tò̇ş̌֙ ha⁠mi̇lĕẖámá֔h wa⁠yi̇ná֥̇gep yişĕ̂ráʼé֖l li⁠pĕné֣y pĕlişĕ̌ţi֑̇ym wa⁠yȧk֤̇ẇ ba⁠mȧֽʻàrákáh֙ bȧ⁠şá̇̂de֔h kĕ̇⁠ʼarĕbȧ֥ʻaţ ʼàlápi֖ym ʼiֽyş̌׃"],[4,3,"וַ⁠יָּבֹ֣א הָ⁠עָם֮ אֶל־הַֽ⁠מַּחֲנֶה֒ וַ⁠יֹּֽאמְרוּ֙ זִקְנֵ֣י יִשְׂרָאֵ֔ל לָ֣⁠מָּה נְגָפָ֧⁠נוּ יְהוָ֛ה הַ⁠יּ֖וֹם לִ⁠פְנֵ֣י פְלִשְׁתִּ֑ים נִקְחָ֧ה אֵלֵ֣י⁠נוּ מִ⁠שִּׁלֹ֗ה אֶת־אֲרוֹן֙ בְּרִ֣ית יְהוָ֔ה וְ⁠יָבֹ֣א בְ⁠קִרְבֵּ֔⁠נוּ וְ⁠יֹשִׁעֵ֖⁠נוּ מִ⁠כַּ֥ף אֹיְבֵֽי⁠נוּ׃","wa⁠yá̇bò֣ʼ há⁠ʻám֮ ʼel-haֽ⁠mȧẖàneh֒ wa⁠yòֽ̇ʼmĕrẇ֙ ziqĕné֣y yişĕ̂ráʼé֔l lá֣⁠má̇h nĕgápá֧⁠nẇ yĕhwá֛h ha⁠ẏ֖wòm li⁠pĕné֣y pĕlişĕ̌ţi֑̇ym niqĕẖá֧h ʼélé֣y⁠nẇ mi⁠şi̇̌lò֗h ʼeţ-ʼàrwòn֙ bĕ̇ri֣yţ yĕhwá֔h wĕ⁠yábò֣ʼ bĕ⁠qirĕbé̇֔⁠nẇ wĕ⁠yòşǐʻé֖⁠nẇ mi⁠kȧ֥p ʼòyĕbéֽy⁠nẇ׃"],[4,4,"וַ⁠יִּשְׁלַ֤ח הָ⁠עָם֙ שִׁלֹ֔ה וַ⁠יִּשְׂא֣וּ מִ⁠שָּׁ֗ם אֵ֣ת אֲר֧וֹן בְּרִית־יְהוָ֛ה צְבָא֖וֹת יֹשֵׁ֣ב הַ⁠כְּרֻבִ֑ים וְ⁠שָׁ֞ם שְׁנֵ֣י בְנֵֽי־עֵלִ֗י עִם־אֲרוֹן֙ בְּרִ֣ית הָ⁠אֱלֹהִ֔ים חָפְנִ֖י וּ⁠פִֽינְחָֽס׃","wa⁠yi̇şĕ̌la֤ẖ há⁠ʻám֙ şǐlò֔h wa⁠yi̇şĕ̂ʼ֣ẇ mi⁠şá̇̌֗m ʼé֣ţ ʼàr֧wòn bĕ̇riyţ-yĕhwá֛h ẕĕbáʼ֖wòţ yòşé֣̌b ha⁠kĕ̇rubi֑ym wĕ⁠şá̌֞m şĕ̌né֣y bĕnéֽy-ʻéli֗y ʻim-ʼàrwòn֙ bĕ̇ri֣yţ há⁠ʼèlòhi֔ym ẖápĕni֖y ẇ⁠piֽynĕẖáֽs׃"],[4,5,"וַ⁠יְהִ֗י כְּ⁠ב֨וֹא אֲר֤וֹן בְּרִית־יְהוָה֙ אֶל־הַֽ⁠מַּחֲנֶ֔ה וַ⁠יָּרִ֥עוּ כָל־יִשְׂרָאֵ֖ל תְּרוּעָ֣ה גְדוֹלָ֑ה וַ⁠תֵּהֹ֖ם הָ⁠אָֽרֶץ׃","wa⁠yĕhi֗y kĕ̇⁠b֨wòʼ ʼàr֤wòn bĕ̇riyţ-yĕhwáh֙ ʼel-haֽ⁠mȧẖàne֔h wa⁠yá̇ri֥ʻẇ kál-yişĕ̂ráʼé֖l ţĕ̇rẇʻá֣h gĕdwòlá֑h wa⁠ţé̇hò֖m há⁠ʼáֽreẕ׃"],[4,6,"וַ⁠יִּשְׁמְע֤וּ פְלִשְׁתִּים֙ אֶת־ק֣וֹל הַ⁠תְּרוּעָ֔ה וַ⁠יֹּ֣אמְר֔וּ מֶ֠ה ק֣וֹל הַ⁠תְּרוּעָ֧ה הַ⁠גְּדוֹלָ֛ה הַ⁠זֹּ֖את בְּ⁠מַחֲנֵ֣ה הָ⁠עִבְרִ֑ים וַ⁠יֵּ֣דְע֔וּ כִּ֚י אֲר֣וֹן יְהוָ֔ה בָּ֖א אֶל־הַֽ⁠מַּחֲנֶֽה׃","wa⁠yi̇şĕ̌mĕʻ֤ẇ pĕlişĕ̌ţi̇ym֙ ʼeţ-q֣wòl ha⁠ţĕ̇rẇʻá֔h wa⁠yò֣̇ʼmĕr֔ẇ me֠h q֣wòl ha⁠ţĕ̇rẇʻá֧h ha⁠gĕ̇dwòlá֛h ha⁠zò֖̇ʼţ bĕ̇⁠maẖàné֣h há⁠ʻibĕri֑ym wa⁠yé֣̇dĕʻ֔ẇ ki֚̇y ʼàr֣wòn yĕhwá֔h bá֖̇ʼ ʼel-haֽ⁠mȧẖàneֽh׃"],[4,7,"וַ⁠יִּֽרְאוּ֙ הַ⁠פְּלִשְׁתִּ֔ים כִּ֣י אָמְר֔וּ בָּ֥א אֱלֹהִ֖ים אֶל־הַֽ⁠מַּחֲנֶ֑ה וַ⁠יֹּאמְרוּ֙ א֣וֹי לָ֔⁠נוּ כִּ֣י לֹ֥א הָיְתָ֛ה כָּ⁠זֹ֖את אֶתְמ֥וֹל שִׁלְשֹֽׁם׃","wa⁠yiֽ̇rĕʼẇ֙ ha⁠pĕ̇lişĕ̌ţi̇֔ym ki֣̇y ʼámĕr֔ẇ bá֥̇ʼ ʼèlòhi֖ym ʼel-haֽ⁠mȧẖàne֑h wa⁠yò̇ʼmĕrẇ֙ ʼ֣wòy lá֔⁠nẇ ki֣̇y lò֥ʼ háyĕţá֛h ká̇⁠zò֖ʼţ ʼeţĕm֥wòl şǐlĕşòֽ̌m׃"],[4,8,"א֣וֹי לָ֔⁠נוּ מִ֣י יַצִּילֵ֔⁠נוּ מִ⁠יַּ֛ד הָ⁠אֱלֹהִ֥ים הָ⁠אַדִּירִ֖ים הָ⁠אֵ֑לֶּה אֵ֧לֶּה הֵ֣ם הָ⁠אֱלֹהִ֗ים הַ⁠מַּכִּ֧ים אֶת־מִצְרַ֛יִם בְּ⁠כָל־מַכָּ֖ה בַּ⁠מִּדְבָּֽר׃","ʼ֣wòy lá֔⁠nẇ mi֣y yaẕi̇ylé֔⁠nẇ mi⁠yȧ֛d há⁠ʼèlòhi֥ym há⁠ʼadi̇yri֖ym há⁠ʼé֑lėh ʼé֧lėh hé֣m há⁠ʼèlòhi֗ym ha⁠mȧki֧̇ym ʼeţ-miẕĕra֛yim bĕ̇⁠kál-maká֖̇h bȧ⁠mi̇dĕbáֽ̇r׃"],[4,9,"הִֽתְחַזְּק֞וּ וִֽ⁠הְי֤וּ לַֽ⁠אֲנָשִׁים֙ פְּלִשְׁתִּ֔ים פֶּ֚ן תַּעַבְד֣וּ לָ⁠עִבְרִ֔ים כַּ⁠אֲשֶׁ֥ר עָבְד֖וּ לָ⁠כֶ֑ם וִ⁠הְיִיתֶ֥ם לַ⁠אֲנָשִׁ֖ים וְ⁠נִלְחַמְתֶּֽם׃","hiֽţĕẖazĕ̇q֞ẇ wiֽ⁠hĕy֤ẇ lֽa⁠ʼànáşǐym֙ pĕ̇lişĕ̌ţi̇֔ym pė֚n ţȧʻabĕd֣ẇ lá⁠ʻibĕri֔ym kȧ⁠ʼàşě֥r ʻábĕd֖ẇ lá⁠ke֑m wi⁠hĕyiyţe֥m la⁠ʼànáşǐ֖ym wĕ⁠nilĕẖamĕţėֽm׃"],[4,10,"וַ⁠יִּלָּחֲמ֣וּ פְלִשְׁתִּ֗ים וַ⁠יִּנָּ֤גֶף יִשְׂרָאֵל֙ וַ⁠יָּנֻ֨סוּ֙ אִ֣ישׁ לְ⁠אֹהָלָ֔י⁠ו וַ⁠תְּהִ֥י הַ⁠מַּכָּ֖ה גְּדוֹלָ֣ה מְאֹ֑ד וַ⁠יִּפֹּל֙ מִ⁠יִּשְׂרָאֵ֔ל שְׁלֹשִׁ֥ים אֶ֖לֶף רַגְלִֽי׃","wa⁠yi̇lá̇ẖàm֣ẇ pĕlişĕ̌ţi̇֗ym wa⁠yi̇ná֤̇gep yişĕ̂ráʼél֙ wa⁠yá̇nu֨sẇ֙ ʼi֣yş̌ lĕ⁠ʼòhálá֔y⁠w wa⁠ţĕ̇hi֥y ha⁠mȧká֖̇h gĕ̇dwòlá֣h mĕʼò֑d wa⁠yi̇pò̇l֙ mi⁠yi̇şĕ̂ráʼé֔l şĕ̌lòşǐ֥ym ʼe֖lep ragĕliֽy׃"],[4,11,"וַ⁠אֲר֥וֹן אֱלֹהִ֖ים נִלְקָ֑ח וּ⁠שְׁנֵ֤י בְנֵֽי־עֵלִי֙ מֵ֔תוּ חָפְנִ֖י וּ⁠פִֽינְחָֽס׃","wa⁠ʼàr֥wòn ʼèlòhi֖ym nilĕqá֑ẖ ẇ⁠şĕ̌né֤y bĕnéֽy-ʻéliy֙ mé֔ţẇ ẖápĕni֖y ẇ⁠piֽynĕẖáֽs׃"],[4,12,"וַ⁠יָּ֤רָץ אִישׁ־בִּנְיָמִן֙ מֵ⁠הַ⁠מַּ֣עֲרָכָ֔ה וַ⁠יָּבֹ֥א שִׁלֹ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וּ⁠מַדָּ֣י⁠ו קְרֻעִ֔ים וַ⁠אֲדָמָ֖ה עַל־רֹאשֽׁ⁠וֹ׃","wa⁠yá֤̇ráẕ ʼiyş̌-bi̇nĕyámin֙ mé⁠ha⁠mȧ֣ʻàráká֔h wa⁠yá̇bò֥ʼ şǐlò֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ẇ⁠madá֣̇y⁠w qĕruʻi֔ym wa⁠ʼàdámá֖h ʻal-ròʼşֽ̌⁠wò׃"],[4,13,"וַ⁠יָּב֗וֹא וְ⁠הִנֵּ֣ה עֵ֠לִי יֹשֵׁ֨ב עַֽל־הַ⁠כִּסֵּ֜א יך דֶּ֨רֶךְ֙ מְצַפֶּ֔ה כִּֽי־הָיָ֤ה לִבּ⁠וֹ֙ חָרֵ֔ד עַ֖ל אֲר֣וֹן הָ⁠אֱלֹהִ֑ים וְ⁠הָ⁠אִ֗ישׁ בָּ֚א לְ⁠הַגִּ֣יד בָּ⁠עִ֔יר וַ⁠תִּזְעַ֖ק כָּל־הָ⁠עִֽיר׃","wa⁠yá̇b֗wòʼ wĕ⁠hiné֣̇h ʻé֠liy yòşé̌֨b ʻaֽl-ha⁠ki̇sé̇֜ʼ yk dė֨rekĕ֙ mĕẕapė֔h kiֽ̇y-háyá֤h liḃ⁠wò֙ ẖáré֔d ʻa֖l ʼàr֣wòn há⁠ʼèlòhi֑ym wĕ⁠há⁠ʼi֗yş̌ bá֚̇ʼ lĕ⁠hagi֣̇yd bá̇⁠ʻi֔yr wa⁠ţi̇zĕʻa֖q ká̇l-há⁠ʻiֽyr׃"],[4,14,"וַ⁠יִּשְׁמַ֤ע עֵלִי֙ אֶת־ק֣וֹל הַ⁠צְּעָקָ֔ה וַ⁠יֹּ֕אמֶר מֶ֛ה ק֥וֹל הֶ⁠הָמ֖וֹן הַ⁠זֶּ֑ה וְ⁠הָ⁠אִ֣ישׁ מִהַ֔ר וַ⁠יָּבֹ֖א וַ⁠יַּגֵּ֥ד לְ⁠עֵלִֽי׃","wa⁠yi̇şĕ̌ma֤ʻ ʻéliy֙ ʼeţ-q֣wòl ha⁠ẕĕ̇ʻáqá֔h wa⁠yò̇֕ʼmer me֛h q֥wòl he⁠hám֖wòn ha⁠zė֑h wĕ⁠há⁠ʼi֣yş̌ miha֔r wa⁠yá̇bò֖ʼ wa⁠yȧgé֥̇d lĕ⁠ʻéliֽy׃"],[4,15,"וְ⁠עֵלִ֕י בֶּן־תִּשְׁעִ֥ים וּ⁠שְׁמֹנֶ֖ה שָׁנָ֑ה וְ⁠עֵינָ֣י⁠ו קָ֔מָה וְ⁠לֹ֥א יָכ֖וֹל לִ⁠רְאֽוֹת׃","wĕ⁠ʻéli֕y bėn-ţi̇şĕ̌ʻi֥ym ẇ⁠şĕ̌mòne֖h şá̌ná֑h wĕ⁠ʻéyná֣y⁠w qá֔máh wĕ⁠lò֥ʼ yák֖wòl li⁠rĕʼֽwòţ׃"],[4,16,"וַ⁠יֹּ֨אמֶר הָ⁠אִ֜ישׁ אֶל־עֵלִ֗י אָֽנֹכִי֙ הַ⁠בָּ֣א מִן־הַ⁠מַּעֲרָכָ֔ה וַ⁠אֲנִ֕י מִן־הַ⁠מַּעֲרָכָ֖ה נַ֣סְתִּי הַ⁠יּ֑וֹם וַ⁠יֹּ֛אמֶר מֶֽה־הָיָ֥ה הַ⁠דָּבָ֖ר בְּנִֽ⁠י׃","wa⁠yò̇֨ʼmer há⁠ʼi֜yş̌ ʼel-ʻéli֗y ʼáֽnòkiy֙ ha⁠bá֣̇ʼ min-ha⁠mȧʻàráká֔h wa⁠ʼàni֕y min-ha⁠mȧʻàráká֖h na֣sĕţi̇y ha⁠ẏ֑wòm wa⁠yò֛̇ʼmer meֽh-háyá֥h ha⁠dá̇bá֖r bĕ̇niֽ⁠y׃"],[4,17,"וַ⁠יַּ֨עַן הַֽ⁠מְבַשֵּׂ֜ר וַ⁠יֹּ֗אמֶר נָ֤ס יִשְׂרָאֵל֙ לִ⁠פְנֵ֣י פְלִשְׁתִּ֔ים וְ⁠גַ֛ם מַגֵּפָ֥ה גְדוֹלָ֖ה הָיְתָ֣ה בָ⁠עָ֑ם וְ⁠גַם־שְׁנֵ֨י בָנֶ֜י⁠ךָ מֵ֗תוּ חָפְנִי֙ וּ⁠פִ֣ינְחָ֔ס וַ⁠אֲר֥וֹן הָ⁠אֱלֹהִ֖ים נִלְקָֽחָה׃פ","wa⁠yȧ֨ʻan haֽ⁠mĕbaşé̇̂֜r wa⁠yò̇֗ʼmer ná֤s yişĕ̂ráʼél֙ li⁠pĕné֣y pĕlişĕ̌ţi̇֔ym wĕ⁠ga֛m magé̇pá֥h gĕdwòlá֖h háyĕţá֣h bá⁠ʻá֑m wĕ⁠gam-şĕ̌né֨y báne֜y⁠ká mé֗ţẇ ẖápĕniy֙ ẇ⁠pi֣ynĕẖá֔s wa⁠ʼàr֥wòn há⁠ʼèlòhi֖ym nilĕqáֽẖáh׃p"],[4,18,"וַ⁠יְהִ֞י כְּ⁠הַזְכִּיר֣⁠וֹ ׀ אֶת־אֲר֣וֹן הָ⁠אֱלֹהִ֗ים וַ⁠יִּפֹּ֣ל מֵֽ⁠עַל־הַ֠⁠כִּסֵּא אֲחֹ֨רַנִּ֜ית בְּעַ֣ד ׀ יַ֣ד הַ⁠שַּׁ֗עַר וַ⁠תִּשָּׁבֵ֤ר מַפְרַקְתּ⁠וֹ֙ וַ⁠יָּמֹ֔ת כִּֽי־זָקֵ֥ן הָ⁠אִ֖ישׁ וְ⁠כָבֵ֑ד וְ⁠ה֛וּא שָׁפַ֥ט אֶת־יִשְׂרָאֵ֖ל אַרְבָּעִ֥ים שָׁנָֽה׃","wa⁠yĕhi֞y kĕ̇⁠hazĕki̇yr֣⁠wò ׀ ʼeţ-ʼàr֣wòn há⁠ʼèlòhi֗ym wa⁠yi̇pò֣̇l méֽ⁠ʻal-ha֠⁠ki̇sé̇ʼ ʼàẖò֨rani̇֜yţ bĕ̇ʻa֣d ׀ ya֣d ha⁠şȧ̌֗ʻar wa⁠ţi̇şá̇̌bé֤r mapĕraqĕţ̇⁠wò֙ wa⁠yá̇mò֔ţ kiֽ̇y-záqé֥n há⁠ʼi֖yş̌ wĕ⁠kábé֑d wĕ⁠h֛ẇʼ şá̌pa֥t ʼeţ-yişĕ̂ráʼé֖l ʼarĕbá̇ʻi֥ym şá̌náֽh׃"],[4,19,"וְ⁠כַלָּת֣⁠וֹ אֵֽשֶׁת־פִּינְחָס֮ הָרָ֣ה לָ⁠לַת֒ וַ⁠תִּשְׁמַ֣ע אֶת־הַ⁠שְּׁמֻעָ֔ה אֶל־הִלָּקַח֙ אֲר֣וֹן הָ⁠אֱלֹהִ֔ים וּ⁠מֵ֥ת חָמִ֖י⁠הָ וְ⁠אִישָׁ֑⁠הּ וַ⁠תִּכְרַ֣ע וַ⁠תֵּ֔לֶד כִּֽי־נֶהֶפְכ֥וּ עָלֶ֖י⁠הָ צִרֶֽי⁠הָ׃","wĕ⁠kalá̇ţ֣⁠wò ʼéֽşěţ-pi̇ynĕẖás֮ hárá֣h lá⁠laţ֒ wa⁠ţi̇şĕ̌ma֣ʻ ʼeţ-ha⁠şĕ̇̌muʻá֔h ʼel-hilá̇qaẖ֙ ʼàr֣wòn há⁠ʼèlòhi֔ym ẇ⁠mé֥ţ ẖámi֖y⁠há wĕ⁠ʼiyşá֑̌⁠ḣ wa⁠ţi̇kĕra֣ʻ wa⁠ţé̇֔led kiֽ̇y-nehepĕk֥ẇ ʻále֖y⁠há ẕireֽy⁠há׃"],[4,20,"וּ⁠כְ⁠עֵ֣ת מוּתָ֗⁠הּ וַ⁠תְּדַבֵּ֨רְנָה֙ הַ⁠נִּצָּב֣וֹת עָלֶ֔י⁠הָ אַל־תִּֽירְאִ֖י כִּ֣י בֵ֣ן יָלָ֑דְתְּ וְ⁠לֹ֥א עָנְתָ֖ה וְ⁠לֹא־שָׁ֥תָה לִבָּֽ⁠הּ׃","ẇ⁠kĕ⁠ʻé֣ţ mẇţá֗⁠ḣ wa⁠ţĕ̇dabé̇֨rĕnáh֙ ha⁠ni̇ẕá̇b֣wòţ ʻále֔y⁠há ʼal-ţiֽ̇yrĕʼi֖y ki֣̇y bé֣n yálá֑dĕţĕ̇ wĕ⁠lò֥ʼ ʻánĕţá֖h wĕ⁠lòʼ-şá֥̌ţáh libáֽ̇⁠ḣ׃"],[4,21,"וַ⁠תִּקְרָ֣א לַ⁠נַּ֗עַר אִֽי־כָבוֹד֙ לֵ⁠אמֹ֔ר גָּלָ֥ה כָב֖וֹד מִ⁠יִּשְׂרָאֵ֑ל אֶל־הִלָּקַח֙ אֲר֣וֹן הָ⁠אֱלֹהִ֔ים וְ⁠אֶל־חָמִ֖י⁠הָ וְ⁠אִישָֽׁ⁠הּ׃","wa⁠ţi̇qĕrá֣ʼ la⁠nȧ֗ʻar ʼiֽy-kábwòd֙ lé⁠ʼmò֔r gá̇lá֥h káb֖wòd mi⁠yi̇şĕ̂ráʼé֑l ʼel-hilá̇qaẖ֙ ʼàr֣wòn há⁠ʼèlòhi֔ym wĕ⁠ʼel-ẖámi֖y⁠há wĕ⁠ʼiyşáֽ̌⁠ḣ׃"],[4,22,"וַ⁠תֹּ֕אמֶר גָּלָ֥ה כָב֖וֹד מִ⁠יִּשְׂרָאֵ֑ל כִּ֥י נִלְקַ֖ח אֲר֥וֹן הָ⁠אֱלֹהִֽים׃פ","wa⁠ţò̇֕ʼmer gá̇lá֥h káb֖wòd mi⁠yi̇şĕ̂ráʼé֑l ki֥̇y nilĕqa֖ẖ ʼàr֥wòn há⁠ʼèlòhiֽym׃p"],[5,1,"וּ⁠פְלִשְׁתִּים֙ לָֽקְח֔וּ אֵ֖ת אֲר֣וֹן הָ⁠אֱלֹהִ֑ים וַ⁠יְבִאֻ֛⁠הוּ מֵ⁠אֶ֥בֶן הָעֵ֖זֶר אַשְׁדּֽוֹדָ⁠ה׃","ẇ⁠pĕlişĕ̌ţi̇ym֙ láֽqĕẖ֔ẇ ʼé֖ţ ʼàr֣wòn há⁠ʼèlòhi֑ym wa⁠yĕbiʼu֛⁠hẇ mé⁠ʼe֥ben háʻé֖zer ʼaşĕ̌ḋֽwòdá⁠h׃"],[5,2,"וַ⁠יִּקְח֤וּ פְלִשְׁתִּים֙ אֶת־אֲר֣וֹן הָ⁠אֱלֹהִ֔ים וַ⁠יָּבִ֥יאוּ אֹת֖⁠וֹ בֵּ֣ית דָּג֑וֹן וַ⁠יַּצִּ֥יגוּ אֹת֖⁠וֹ אֵ֥צֶל דָּגֽוֹן׃","wa⁠yi̇qĕẖ֤ẇ pĕlişĕ̌ţi̇ym֙ ʼeţ-ʼàr֣wòn há⁠ʼèlòhi֔ym wa⁠yá̇bi֥yʼẇ ʼòţ֖⁠wò bé֣̇yţ dá̇g֑wòn wa⁠yȧẕi֥̇ygẇ ʼòţ֖⁠wò ʼé֥ẕel dá̇gֽwòn׃"],[5,3,"וַ⁠יַּשְׁכִּ֤מוּ אַשְׁדּוֹדִים֙ מִֽ⁠מָּחֳרָ֔ת וְ⁠הִנֵּ֣ה דָג֗וֹן נֹפֵ֤ל לְ⁠פָנָי⁠ו֙ אַ֔רְצָ⁠ה לִ⁠פְנֵ֖י אֲר֣וֹן יְהוָ֑ה וַ⁠יִּקְחוּ֙ אֶת־דָּג֔וֹן וַ⁠יָּשִׁ֥בוּ אֹת֖⁠וֹ לִ⁠מְקוֹמֽ⁠וֹ׃","wa⁠yȧşĕ̌ki֤̇mẇ ʼaşĕ̌ḋwòdiym֙ miֽ⁠má̇ẖorá֔ţ wĕ⁠hiné֣̇h dág֗wòn nòpé֤l lĕ⁠pánáy⁠w֙ ʼa֔rĕẕá⁠h li⁠pĕné֖y ʼàr֣wòn yĕhwá֑h wa⁠yi̇qĕẖẇ֙ ʼeţ-dá̇g֔wòn wa⁠yá̇şǐ֥bẇ ʼòţ֖⁠wò li⁠mĕqwòmֽ⁠wò׃"],[5,4,"וַ⁠יַּשְׁכִּ֣מוּ בַ⁠בֹּקֶר֮ מִֽ⁠מָּחֳרָת֒ וְ⁠הִנֵּ֣ה דָג֗וֹן נֹפֵ֤ל לְ⁠פָנָי⁠ו֙ אַ֔רְצָ⁠ה לִ⁠פְנֵ֖י אֲר֣וֹן יְהוָ֑ה וְ⁠רֹ֨אשׁ דָּג֜וֹן וּ⁠שְׁתֵּ֣י ׀ כַּפּ֣וֹת יָדָ֗י⁠ו כְּרֻתוֹת֙ אֶל־הַ⁠מִּפְתָּ֔ן רַ֥ק דָּג֖וֹן נִשְׁאַ֥ר עָלָֽי⁠ו׃","wa⁠yȧşĕ̌ki֣̇mẇ ba⁠bò̇qer֮ miֽ⁠má̇ẖoráţ֒ wĕ⁠hiné֣̇h dág֗wòn nòpé֤l lĕ⁠pánáy⁠w֙ ʼa֔rĕẕá⁠h li⁠pĕné֖y ʼàr֣wòn yĕhwá֑h wĕ⁠rò֨ʼş̌ dá̇g֜wòn ẇ⁠şĕ̌ţé֣̇y ׀ kȧṗ֣wòţ yádá֗y⁠w kĕ̇ruţwòţ֙ ʼel-ha⁠mi̇pĕţá̇֔n ra֥q dá̇g֖wòn nişĕ̌ʼa֥r ʻáláֽy⁠w׃"],[5,5,"עַל־כֵּ֡ן לֹֽא־יִדְרְכוּ֩ כֹהֲנֵ֨י דָג֜וֹן וְ⁠כָֽל־הַ⁠בָּאִ֧ים בֵּית־דָּג֛וֹן עַל־מִפְתַּ֥ן דָּג֖וֹן בְּ⁠אַשְׁדּ֑וֹד עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","ʻal-ké̇֡n lòֽʼ-yidĕrĕkẇ֩ kòhàné֨y dág֜wòn wĕ⁠káֽl-ha⁠bá̇ʼi֧ym bé̇yţ-dá̇g֛wòn ʻal-mipĕţȧ֥n dá̇g֖wòn bĕ̇⁠ʼaşĕ̌ḋ֑wòd ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃s"],[5,6,"וַ⁠תִּכְבַּ֧ד יַד־יְהוָ֛ה אֶל־הָ⁠אַשְׁדּוֹדִ֖ים וַ⁠יְשִׁמֵּ֑⁠ם וַ⁠יַּ֤ךְ אֹתָ⁠ם֙ ב⁠עפלים אֶת־אַשְׁדּ֖וֹד וְ⁠אֶת־גְּבוּלֶֽי⁠הָ׃","wa⁠ţi̇kĕbȧ֧d yad-yĕhwá֛h ʼel-há⁠ʼaşĕ̌ḋwòdi֖ym wa⁠yĕşǐmé֑̇⁠m wa⁠yȧ֤kĕ ʼòţá⁠m֙ b⁠ʻplym ʼeţ-ʼaşĕ̌ḋ֖wòd wĕ⁠ʼeţ-gĕ̇bẇleֽy⁠há׃"],[5,7,"וַ⁠יִּרְא֥וּ אַנְשֵֽׁי־אַשְׁדּ֖וֹד כִּֽי־כֵ֑ן וְ⁠אָמְר֗וּ לֹֽא־יֵשֵׁ֞ב אֲר֨וֹן אֱלֹהֵ֤י יִשְׂרָאֵל֙ עִמָּ֔⁠נוּ כִּֽי־קָשְׁתָ֤ה יָד⁠וֹ֙ עָלֵ֔י⁠נוּ וְ⁠עַ֖ל דָּג֥וֹן אֱלֹהֵֽי⁠נוּ׃","wa⁠yi̇rĕʼ֥ẇ ʼanĕşéֽ̌y-ʼaşĕ̌ḋ֖wòd kiֽ̇y-ké֑n wĕ⁠ʼámĕr֗ẇ lòֽʼ-yéşé̌֞b ʼàr֨wòn ʼèlòhé֤y yişĕ̂ráʼél֙ ʻimá̇֔⁠nẇ kiֽ̇y-qáşĕ̌ţá֤h yád⁠wò֙ ʻálé֔y⁠nẇ wĕ⁠ʻa֖l dá̇g֥wòn ʼèlòhéֽy⁠nẇ׃"],[5,8,"וַ⁠יִּשְׁלְח֡וּ וַ⁠יַּאַסְפוּ֩ אֶת־כָּל־סַרְנֵ֨י פְלִשְׁתִּ֜ים אֲלֵי⁠הֶ֗ם וַ⁠יֹּֽאמְרוּ֙ מַֽה־נַּעֲשֶׂ֗ה לַֽ⁠אֲרוֹן֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל וַ⁠יֹּ֣אמְר֔וּ גַּ֣ת יִסֹּ֔ב אֲר֖וֹן אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וַ⁠יַּסֵּ֕בּוּ אֶת־אֲר֖וֹן אֱלֹהֵ֥י יִשְׂרָאֵֽל׃ס","wa⁠yi̇şĕ̌lĕẖ֡ẇ wa⁠yȧʼasĕpẇ֩ ʼeţ-ká̇l-sarĕné֨y pĕlişĕ̌ţi̇֜ym ʼàléy⁠he֗m wa⁠yòֽ̇ʼmĕrẇ֙ maֽh-nȧʻàşê֗h laֽ⁠ʼàrwòn֙ ʼèlòhé֣y yişĕ̂ráʼé֔l wa⁠yò֣̇ʼmĕr֔ẇ gȧ֣ţ yisò̇֔b ʼàr֖wòn ʼèlòhé֣y yişĕ̂ráʼé֑l wa⁠yȧsé̇֕ḃẇ ʼeţ-ʼàr֖wòn ʼèlòhé֥y yişĕ̂ráʼéֽl׃s"],[5,9,"וַ⁠יְהִ֞י אַחֲרֵ֣י ׀ הֵסַ֣בּוּ אֹת֗⁠וֹ וַ⁠תְּהִ֨י יַד־יְהוָ֤ה ׀ בָּ⁠עִיר֙ מְהוּמָה֙ גְּדוֹלָ֣ה מְאֹ֔ד וַ⁠יַּךְ֙ אֶת־אַנְשֵׁ֣י הָ⁠עִ֔יר מִ⁠קָּטֹ֖ן וְ⁠עַד־גָּד֑וֹל וַ⁠יִּשָּׂתְר֥וּ לָ⁠הֶ֖ם עפלים׃","wa⁠yĕhi֞y ʼaẖàré֣y ׀ hésa֣ḃẇ ʼòţ֗⁠wò wa⁠ţĕ̇hi֨y yad-yĕhwá֤h ׀ bá̇⁠ʻiyr֙ mĕhẇmáh֙ gĕ̇dwòlá֣h mĕʼò֔d wa⁠yȧkĕ֙ ʼeţ-ʼanĕşé֣̌y há⁠ʻi֔yr mi⁠qá̇tò֖n wĕ⁠ʻad-gá̇d֑wòl wa⁠yi̇şá̇̂ţĕr֥ẇ lá⁠he֖m ʻplym׃"],[5,10,"וַֽ⁠יְשַׁלְּח֛וּ אֶת־אֲר֥וֹן הָ⁠אֱלֹהִ֖ים עֶקְר֑וֹן וַ⁠יְהִ֗י כְּ⁠ב֨וֹא אֲר֤וֹן הָ⁠אֱלֹהִים֙ עֶקְר֔וֹן וַ⁠יִּזְעֲק֨וּ הָֽ⁠עֶקְרֹנִ֜ים לֵ⁠אמֹ֗ר הֵסַ֤בּוּ אֵלַ⁠י֙ אֶת־אֲרוֹן֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל לַ⁠הֲמִיתֵ֖⁠נִי וְ⁠אֶת־עַמִּֽ⁠י׃","waֽ⁠yĕşǎlĕ̇ẖ֛ẇ ʼeţ-ʼàr֥wòn há⁠ʼèlòhi֖ym ʻeqĕr֑wòn wa⁠yĕhi֗y kĕ̇⁠b֨wòʼ ʼàr֤wòn há⁠ʼèlòhiym֙ ʻeqĕr֔wòn wa⁠yi̇zĕʻàq֨ẇ háֽ⁠ʻeqĕròni֜ym lé⁠ʼmò֗r hésa֤ḃẇ ʼéla⁠y֙ ʼeţ-ʼàrwòn֙ ʼèlòhé֣y yişĕ̂ráʼé֔l la⁠hàmiyţé֖⁠niy wĕ⁠ʼeţ-ʻamiֽ̇⁠y׃"],[5,11,"וַ⁠יִּשְׁלְח֨וּ וַ⁠יַּאַסְפ֜וּ אֶת־כָּל־סַרְנֵ֣י פְלִשְׁתִּ֗ים וַ⁠יֹּֽאמְרוּ֙ שַׁלְּח֞וּ אֶת־אֲר֨וֹן אֱלֹהֵ֤י יִשְׂרָאֵל֙ וְ⁠יָשֹׁ֣ב לִ⁠מְקֹמ֔⁠וֹ וְ⁠לֹֽא־יָמִ֥ית אֹתִ֖⁠י וְ⁠אֶת־עַמִּ֑⁠י כִּֽי־הָיְתָ֤ה מְהֽוּמַת־מָ֨וֶת֙ בְּ⁠כָל־הָ⁠עִ֔יר כָּבְדָ֥ה מְאֹ֛ד יַ֥ד הָ⁠אֱלֹהִ֖ים שָֽׁם׃","wa⁠yi̇şĕ̌lĕẖ֨ẇ wa⁠yȧʼasĕp֜ẇ ʼeţ-ká̇l-sarĕné֣y pĕlişĕ̌ţi̇֗ym wa⁠yòֽ̇ʼmĕrẇ֙ şǎlĕ̇ẖ֞ẇ ʼeţ-ʼàr֨wòn ʼèlòhé֤y yişĕ̂ráʼél֙ wĕ⁠yáşò֣̌b li⁠mĕqòm֔⁠wò wĕ⁠lòֽʼ-yámi֥yţ ʼòţi֖⁠y wĕ⁠ʼeţ-ʻami֑̇⁠y kiֽ̇y-háyĕţá֤h mĕhֽẇmaţ-má֨weţ֙ bĕ̇⁠kál-há⁠ʻi֔yr ká̇bĕdá֥h mĕʼò֛d ya֥d há⁠ʼèlòhi֖ym şáֽ̌m׃"],[5,12,"וְ⁠הָֽ⁠אֲנָשִׁים֙ אֲשֶׁ֣ר לֹא־מֵ֔תוּ הֻכּ֖וּ ב⁠עפלים וַ⁠תַּ֛עַל שַֽׁוְעַ֥ת הָ⁠עִ֖יר הַ⁠שָּׁמָֽיִם׃","wĕ⁠háֽ⁠ʼànáşǐym֙ ʼàşě֣r lòʼ-mé֔ţẇ huk֖̇ẇ b⁠ʻplym wa⁠ţȧ֛ʻal şǎֽwĕʻa֥ţ há⁠ʻi֖yr ha⁠şá̇̌máֽyim׃"],[6,1,"וַ⁠יְהִ֧י אֲרוֹן־יְהוָ֛ה בִּ⁠שְׂדֵ֥ה פְלִשְׁתִּ֖ים שִׁבְעָ֥ה חֳדָשִֽׁים׃","wa⁠yĕhi֧y ʼàrwòn-yĕhwá֛h bi̇⁠şĕ̂dé֥h pĕlişĕ̌ţi֖̇ym şǐbĕʻá֥h ẖodáşǐֽym׃"],[6,2,"וַ⁠יִּקְרְא֣וּ פְלִשְׁתִּ֗ים לַ⁠כֹּהֲנִ֤ים וְ⁠לַ⁠קֹּֽסְמִים֙ לֵ⁠אמֹ֔ר מַֽה־נַּעֲשֶׂ֖ה לַ⁠אֲר֣וֹן יְהוָ֑ה הוֹדִעֻ֕⁠נוּ בַּ⁠מֶּ֖ה נְשַׁלְּחֶ֥⁠נּוּ לִ⁠מְקוֹמֽ⁠וֹ׃","wa⁠yi̇qĕrĕʼ֣ẇ pĕlişĕ̌ţi̇֗ym la⁠kò̇hàni֤ym wĕ⁠la⁠qòֽ̇sĕmiym֙ lé⁠ʼmò֔r maֽh-nȧʻàşê֖h la⁠ʼàr֣wòn yĕhwá֑h hwòdiʻu֕⁠nẇ bȧ⁠mė֖h nĕşǎlĕ̇ẖe֥⁠ṅẇ li⁠mĕqwòmֽ⁠wò׃"],[6,3,"וַ⁠יֹּאמְר֗וּ אִֽם־מְשַׁלְּחִ֞ים אֶת־אֲר֨וֹן אֱלֹהֵ֤י יִשְׂרָאֵל֙ אַל־תְּשַׁלְּח֤וּ אֹת⁠וֹ֙ רֵיקָ֔ם כִּֽי־הָשֵׁ֥ב תָּשִׁ֛יבוּ ל֖⁠וֹ אָשָׁ֑ם אָ֤ז תֵּרָֽפְאוּ֙ וְ⁠נוֹדַ֣ע לָ⁠כֶ֔ם לָ֛⁠מָּה לֹא־תָס֥וּר יָד֖⁠וֹ מִ⁠כֶּֽם׃","wa⁠yò̇ʼmĕr֗ẇ ʼiֽm-mĕşǎlĕ̇ẖi֞ym ʼeţ-ʼàr֨wòn ʼèlòhé֤y yişĕ̂ráʼél֙ ʼal-ţĕ̇şǎlĕ̇ẖ֤ẇ ʼòţ⁠wò֙ réyqá֔m kiֽ̇y-háşé֥̌b ţá̇şǐ֛ybẇ l֖⁠wò ʼáşá֑̌m ʼá֤z ţé̇ráֽpĕʼẇ֙ wĕ⁠nwòda֣ʻ lá⁠ke֔m lá֛⁠má̇h lòʼ-ţás֥ẇr yád֖⁠wò mi⁠kėֽm׃"],[6,4,"וַ⁠יֹּאמְר֗וּ מָ֣ה הָ⁠אָשָׁם֮ אֲשֶׁ֣ר נָשִׁ֣יב ל⁠וֹ֒ וַ⁠יֹּאמְר֗וּ מִסְפַּר֙ סַרְנֵ֣י פְלִשְׁתִּ֔ים חֲמִשָּׁה֙ עפלי זָהָ֔ב וַ⁠חֲמִשָּׁ֖ה עַכְבְּרֵ֣י זָהָ֑ב כִּֽי־מַגֵּפָ֥ה אַחַ֛ת לְ⁠כֻלָּ֖⁠ם וּ⁠לְ⁠סַרְנֵי⁠כֶֽם׃","wa⁠yò̇ʼmĕr֗ẇ má֣h há⁠ʼáşá̌m֮ ʼàşě֣r náşǐ֣yb l⁠wò֒ wa⁠yò̇ʼmĕr֗ẇ misĕpȧr֙ sarĕné֣y pĕlişĕ̌ţi̇֔ym ẖàmişá̇̌h֙ ʻply záhá֔b wa⁠ẖàmişá֖̇̌h ʻakĕbĕ̇ré֣y záhá֑b kiֽ̇y-magé̇pá֥h ʼaẖa֛ţ lĕ⁠kulá֖̇⁠m ẇ⁠lĕ⁠sarĕnéy⁠keֽm׃"],[6,5,"וַ⁠עֲשִׂיתֶם֩ צַלְמֵ֨י עפלי⁠כם וְ⁠צַלְמֵ֣י עַכְבְּרֵי⁠כֶ֗ם הַ⁠מַּשְׁחִיתִם֙ אֶת־הָ⁠אָ֔רֶץ וּ⁠נְתַתֶּ֛ם לֵ⁠אלֹהֵ֥י יִשְׂרָאֵ֖ל כָּב֑וֹד אוּלַ֗י יָקֵ֤ל אֶת־יָד⁠וֹ֙ מֵֽ⁠עֲלֵי⁠כֶ֔ם וּ⁠מֵ⁠עַ֥ל אֱלֹהֵי⁠כֶ֖ם וּ⁠מֵ⁠עַ֥ל אַרְצְ⁠כֶֽם׃","wa⁠ʻàşîyţem֩ ẕalĕmé֨y ʻply⁠km wĕ⁠ẕalĕmé֣y ʻakĕbĕ̇réy⁠ke֗m ha⁠mȧşĕ̌ẖiyţim֙ ʼeţ-há⁠ʼá֔reẕ ẇ⁠nĕţaţė֛m lé⁠ʼlòhé֥y yişĕ̂ráʼé֖l ká̇b֑wòd ʼẇla֗y yáqé֤l ʼeţ-yád⁠wò֙ méֽ⁠ʻàléy⁠ke֔m ẇ⁠mé⁠ʻa֥l ʼèlòhéy⁠ke֖m ẇ⁠mé⁠ʻa֥l ʼarĕẕĕ⁠keֽm׃"],[6,6,"וְ⁠לָ֤⁠מָּה תְכַבְּדוּ֙ אֶת־לְבַבְ⁠כֶ֔ם כַּ⁠אֲשֶׁ֧ר כִּבְּד֛וּ מִצְרַ֥יִם וּ⁠פַרְעֹ֖ה אֶת־לִבָּ֑⁠ם הֲ⁠לוֹא֙ כַּ⁠אֲשֶׁ֣ר הִתְעַלֵּ֣ל בָּ⁠הֶ֔ם וַֽ⁠יְשַׁלְּח֖וּ⁠ם וַ⁠יֵּלֵֽכוּ׃","wĕ⁠lá֤⁠má̇h ţĕkabĕ̇dẇ֙ ʼeţ-lĕbabĕ⁠ke֔m kȧ⁠ʼàşě֧r ki̇bĕ̇d֛ẇ miẕĕra֥yim ẇ⁠parĕʻò֖h ʼeţ-libá֑̇⁠m hà⁠lwòʼ֙ kȧ⁠ʼàşě֣r hiţĕʻalé֣̇l bá̇⁠he֔m wֽa⁠yĕşǎlĕ̇ẖ֖ẇ⁠m wa⁠yé̇léֽkẇ׃"],[6,7,"וְ⁠עַתָּ֗ה קְח֨וּ וַ⁠עֲשׂ֜וּ עֲגָלָ֤ה חֲדָשָׁה֙ אֶחָ֔ת וּ⁠שְׁתֵּ֤י פָרוֹת֙ עָל֔וֹת אֲשֶׁ֛ר לֹא־עָלָ֥ה עֲלֵי⁠הֶ֖ם עֹ֑ל וַ⁠אֲסַרְתֶּ֤ם אֶת־הַ⁠פָּרוֹת֙ בָּ⁠עֲגָלָ֔ה וַ⁠הֲשֵׁיבֹתֶ֧ם בְּנֵי⁠הֶ֛ם מֵ⁠אַחֲרֵי⁠הֶ֖ם הַ⁠בָּֽיְתָ⁠ה׃","wĕ⁠ʻaţá̇֗h qĕẖ֨ẇ wa⁠ʻàş̂֜ẇ ʻàgálá֤h ẖàdáşá̌h֙ ʼeẖá֔ţ ẇ⁠şĕ̌ţé֤̇y párwòţ֙ ʻál֔wòţ ʼàşě֛r lòʼ-ʻálá֥h ʻàléy⁠he֖m ʻò֑l wa⁠ʼàsarĕţė֤m ʼeţ-ha⁠pá̇rwòţ֙ bá̇⁠ʻàgálá֔h wa⁠hàşé̌ybòţe֧m bĕ̇néy⁠he֛m mé⁠ʼaẖàréy⁠he֖m ha⁠báֽ̇yĕţá⁠h׃"],[6,8,"וּ⁠לְקַחְתֶּ֞ם אֶת־אֲר֣וֹן יְהוָ֗ה וּ⁠נְתַתֶּ֤ם אֹת⁠וֹ֙ אֶל־הָ֣⁠עֲגָלָ֔ה וְ⁠אֵ֣ת ׀ כְּלֵ֣י הַ⁠זָּהָ֗ב אֲשֶׁ֨ר הֲשֵׁבֹתֶ֥ם ל⁠וֹ֙ אָשָׁ֔ם תָּשִׂ֥ימוּ בָ⁠אַרְגַּ֖ז מִ⁠צִּדּ֑⁠וֹ וְ⁠שִׁלַּחְתֶּ֥ם אֹת֖⁠וֹ וְ⁠הָלָֽךְ׃","ẇ⁠lĕqaẖĕţė֞m ʼeţ-ʼàr֣wòn yĕhwá֗h ẇ⁠nĕţaţė֤m ʼòţ⁠wò֙ ʼel-há֣⁠ʻàgálá֔h wĕ⁠ʼé֣ţ ׀ kĕ̇lé֣y ha⁠zá̇há֗b ʼàşě֨r hàşé̌bòţe֥m l⁠wò֙ ʼáşá̌֔m ţá̇şî֥ymẇ bá⁠ʼarĕgȧ֖z mi⁠ẕi̇ḋ֑⁠wò wĕ⁠şǐlȧẖĕţė֥m ʼòţ֖⁠wò wĕ⁠háláֽkĕ׃"],[6,9,"וּ⁠רְאִיתֶ֗ם אִם־דֶּ֨רֶךְ גְּבוּל֤⁠וֹ יַֽעֲלֶה֙ בֵּ֣ית שֶׁ֔מֶשׁ ה֚וּא עָ֣שָׂה לָ֔⁠נוּ אֶת־הָ⁠רָעָ֥ה הַ⁠גְּדוֹלָ֖ה הַ⁠זֹּ֑את וְ⁠אִם־לֹ֗א וְ⁠יָדַ֨עְנוּ֙ כִּ֣י לֹ֤א יָד⁠וֹ֙ נָ֣גְעָה בָּ֔⁠נוּ מִקְרֶ֥ה ה֖וּא הָ֥יָה לָֽ⁠נוּ׃","ẇ⁠rĕʼiyţe֗m ʼim-dė֨rekĕ gĕ̇bẇl֤⁠wò yaֽʻàleh֙ bé֣̇yţ şě֔meş̌ h֚ẇʼ ʻá֣şá̂h lá֔⁠nẇ ʼeţ-há⁠ráʻá֥h ha⁠gĕ̇dwòlá֖h ha⁠zò֑̇ʼţ wĕ⁠ʼim-lò֗ʼ wĕ⁠yáda֨ʻĕnẇ֙ ki֣̇y lò֤ʼ yád⁠wò֙ ná֣gĕʻáh bá̇֔⁠nẇ miqĕre֥h h֖ẇʼ há֥yáh láֽ⁠nẇ׃"],[6,10,"וַ⁠יַּעֲשׂ֤וּ הָ⁠אֲנָשִׁים֙ כֵּ֔ן וַ⁠יִּקְח֗וּ שְׁתֵּ֤י פָרוֹת֙ עָל֔וֹת וַ⁠יַּאַסְר֖וּ⁠ם בָּ⁠עֲגָלָ֑ה וְ⁠אֶת־בְּנֵי⁠הֶ֖ם כָּל֥וּ בַ⁠בָּֽיִת׃","wa⁠yȧʻàş֤̂ẇ há⁠ʼànáşǐym֙ ké̇֔n wa⁠yi̇qĕẖ֗ẇ şĕ̌ţé֤̇y párwòţ֙ ʻál֔wòţ wa⁠yȧʼasĕr֖ẇ⁠m bá̇⁠ʻàgálá֑h wĕ⁠ʼeţ-bĕ̇néy⁠he֖m ká̇l֥ẇ ba⁠báֽ̇yiţ׃"],[6,11,"וַ⁠יָּשִׂ֛מוּ אֶת־אֲר֥וֹן יְהוָ֖ה אֶל־הָ⁠עֲגָלָ֑ה וְ⁠אֵ֣ת הָ⁠אַרְגַּ֗ז וְ⁠אֵת֙ עַכְבְּרֵ֣י הַ⁠זָּהָ֔ב וְ⁠אֵ֖ת צַלְמֵ֥י טְחֹרֵי⁠הֶֽם׃","wa⁠yá̇şî֛mẇ ʼeţ-ʼàr֥wòn yĕhwá֖h ʼel-há⁠ʻàgálá֑h wĕ⁠ʼé֣ţ há⁠ʼarĕgȧ֗z wĕ⁠ʼéţ֙ ʻakĕbĕ̇ré֣y ha⁠zá̇há֔b wĕ⁠ʼé֖ţ ẕalĕmé֥y tĕẖòréy⁠heֽm׃"],[6,12,"וַ⁠יִשַּׁ֨רְנָה הַ⁠פָּר֜וֹת בַּ⁠דֶּ֗רֶךְ עַל־דֶּ֨רֶךְ֙ בֵּ֣ית שֶׁ֔מֶשׁ בִּ⁠מְסִלָּ֣ה אַחַ֗ת הָלְכ֤וּ הָלֹךְ֙ וְ⁠גָע֔וֹ וְ⁠לֹא־סָ֖רוּ יָמִ֣ין וּ⁠שְׂמֹ֑אול וְ⁠סַרְנֵ֤י פְלִשְׁתִּים֙ הֹלְכִ֣ים אַחֲרֵי⁠הֶ֔ם עַד־גְּב֖וּל בֵּ֥ית שָֽׁמֶשׁ׃","wa⁠yişȧ̌֨rĕnáh ha⁠pá̇r֜wòţ bȧ⁠dė֗rekĕ ʻal-dė֨rekĕ֙ bé֣̇yţ şě֔meş̌ bi̇⁠mĕsilá֣̇h ʼaẖa֗ţ hálĕk֤ẇ hálòkĕ֙ wĕ⁠gáʻ֔wò wĕ⁠lòʼ-sá֖rẇ yámi֣yn ẇ⁠şĕ̂mò֑ʼwl wĕ⁠sarĕné֤y pĕlişĕ̌ţi̇ym֙ hòlĕki֣ym ʼaẖàréy⁠he֔m ʻad-gĕ̇b֖ẇl bé֥̇yţ şáֽ̌meş̌׃"],[6,13,"וּ⁠בֵ֣ית שֶׁ֔מֶשׁ קֹצְרִ֥ים קְצִיר־חִטִּ֖ים בָּ⁠עֵ֑מֶק וַ⁠יִּשְׂא֣וּ אֶת־עֵינֵי⁠הֶ֗ם וַ⁠יִּרְאוּ֙ אֶת־הָ֣⁠אָר֔וֹן וַֽ⁠יִּשְׂמְח֖וּ לִ⁠רְאֽוֹת׃","ẇ⁠bé֣yţ şě֔meş̌ qòẕĕri֥ym qĕẕiyr-ẖiti֖̇ym bá̇⁠ʻé֑meq wa⁠yi̇şĕ̂ʼ֣ẇ ʼeţ-ʻéynéy⁠he֗m wa⁠yi̇rĕʼẇ֙ ʼeţ-há֣⁠ʼár֔wòn waֽ⁠yi̇şĕ̂mĕẖ֖ẇ li⁠rĕʼֽwòţ׃"],[6,14,"וְ⁠הָ⁠עֲגָלָ֡ה בָּ֠אָה אֶל־שְׂדֵ֨ה יְהוֹשֻׁ֤עַ בֵּֽית־הַשִּׁמְשִׁי֙ וַ⁠תַּעֲמֹ֣ד שָׁ֔ם וְ⁠שָׁ֖ם אֶ֣בֶן גְּדוֹלָ֑ה וַֽ⁠יְבַקְּעוּ֙ אֶת־עֲצֵ֣י הָ⁠עֲגָלָ֔ה וְ⁠אֶת־הַ֨⁠פָּר֔וֹת הֶעֱל֥וּ עֹלָ֖ה לַ⁠יהוָֽה׃ס","wĕ⁠há⁠ʻàgálá֡h bá̇֠ʼáh ʼel-şĕ̂dé֨h yĕhwòşǔ֤ʻa béֽ̇yţ-haşi̇̌mĕşǐy֙ wa⁠ţȧʻàmò֣d şá̌֔m wĕ⁠şá֖̌m ʼe֣ben gĕ̇dwòlá֑h waֽ⁠yĕbaqĕ̇ʻẇ֙ ʼeţ-ʻàẕé֣y há⁠ʻàgálá֔h wĕ⁠ʼeţ-ha֨⁠pá̇r֔wòţ heʻèl֥ẇ ʻòlá֖h la⁠yhwáֽh׃s"],[6,15,"וְ⁠הַ⁠לְוִיִּ֞ם הוֹרִ֣ידוּ ׀ אֶת־אֲר֣וֹן יְהוָ֗ה וְ⁠אֶת־הָ⁠אַרְגַּ֤ז אֲשֶׁר־אִתּ⁠וֹ֙ אֲשֶׁר־בּ֣⁠וֹ כְלֵֽי־זָהָ֔ב וַ⁠יָּשִׂ֖מוּ אֶל־הָ⁠אֶ֣בֶן הַ⁠גְּדוֹלָ֑ה וְ⁠אַנְשֵׁ֣י בֵֽית־שֶׁ֗מֶשׁ הֶעֱל֨וּ עֹל֜וֹת וַֽ⁠יִּזְבְּח֧וּ זְבָחִ֛ים בַּ⁠יּ֥וֹם הַ⁠ה֖וּא לַֽ⁠יהוָֽה׃","wĕ⁠ha⁠lĕwiyi̇֞m hwòri֣ydẇ ׀ ʼeţ-ʼàr֣wòn yĕhwá֗h wĕ⁠ʼeţ-há⁠ʼarĕgȧ֤z ʼàşěr-ʼiţ̇⁠wò֙ ʼàşěr-ḃ֣⁠wò kĕléֽy-záhá֔b wa⁠yá̇şî֖mẇ ʼel-há⁠ʼe֣ben ha⁠gĕ̇dwòlá֑h wĕ⁠ʼanĕşé֣̌y béֽyţ-şě֗meş̌ heʻèl֨ẇ ʻòl֜wòţ wֽa⁠yi̇zĕbĕ̇ẖ֧ẇ zĕbáẖi֛ym bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ laֽ⁠yhwáֽh׃"],[6,16,"וַ⁠חֲמִשָּׁ֥ה סַרְנֵֽי־פְלִשְׁתִּ֖ים רָא֑וּ וַ⁠יָּשֻׁ֥בוּ עֶקְר֖וֹן בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃ס","wa⁠ẖàmişá֥̇̌h sarĕnéֽy-pĕlişĕ̌ţi֖̇ym ráʼ֑ẇ wa⁠yá̇şǔ֥bẇ ʻeqĕr֖wòn bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃s"],[6,17,"וְ⁠אֵ֨לֶּה֙ טְחֹרֵ֣י הַ⁠זָּהָ֔ב אֲשֶׁ֨ר הֵשִׁ֧יבוּ פְלִשְׁתִּ֛ים אָשָׁ֖ם לַֽ⁠יהוָ֑ה לְ⁠אַשְׁדּ֨וֹד אֶחָ֜ד לְ⁠עַזָּ֤ה אֶחָד֙ לְ⁠אַשְׁקְל֣וֹן אֶחָ֔ד לְ⁠גַ֥ת אֶחָ֖ד לְ⁠עֶקְר֥וֹן אֶחָֽד׃ס","wĕ⁠ʼé֨lėh֙ tĕẖòré֣y ha⁠zá̇há֔b ʼàşě֨r héşǐ֧ybẇ pĕlişĕ̌ţi֛̇ym ʼáşá֖̌m laֽ⁠yhwá֑h lĕ⁠ʼaşĕ̌ḋ֨wòd ʼeẖá֜d lĕ⁠ʻazá֤̇h ʼeẖád֙ lĕ⁠ʼaşĕ̌qĕl֣wòn ʼeẖá֔d lĕ⁠ga֥ţ ʼeẖá֖d lĕ⁠ʻeqĕr֥wòn ʼeẖáֽd׃s"],[6,18,"וְ⁠עַכְבְּרֵ֣י הַ⁠זָּהָ֗ב מִסְפַּ֞ר כָּל־עָרֵ֤י פְלִשְׁתִּים֙ לַ⁠חֲמֵ֣שֶׁת הַ⁠סְּרָנִ֔ים מֵ⁠עִ֣יר מִבְצָ֔ר וְ⁠עַ֖ד כֹּ֣פֶר הַ⁠פְּרָזִ֑י וְ⁠עַ֣ד ׀ אָבֵ֣ל הַ⁠גְּדוֹלָ֗ה אֲשֶׁ֨ר הִנִּ֤יחוּ עָלֶ֨י⁠הָ֙ אֵ֚ת אֲר֣וֹן יְהוָ֔ה עַ֚ד הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה בִּ⁠שְׂדֵ֥ה יְהוֹשֻׁ֖עַ בֵּֽית־הַשִּׁמְשִֽׁי׃","wĕ⁠ʻakĕbĕ̇ré֣y ha⁠zá̇há֗b misĕpȧ֞r ká̇l-ʻáré֤y pĕlişĕ̌ţi̇ym֙ la⁠ẖàmé֣şěţ ha⁠sĕ̇ráni֔ym mé⁠ʻi֣yr mibĕẕá֔r wĕ⁠ʻa֖d kò֣̇per ha⁠pĕ̇rázi֑y wĕ⁠ʻa֣d ׀ ʼábé֣l ha⁠gĕ̇dwòlá֗h ʼàşě֨r hini֤̇yẖẇ ʻále֨y⁠há֙ ʼé֚ţ ʼàr֣wòn yĕhwá֔h ʻa֚d ha⁠ẏ֣wòm ha⁠zė֔h bi̇⁠şĕ̂dé֥h yĕhwòşǔ֖ʻa béֽ̇yţ-haşi̇̌mĕşǐֽy׃"],[6,19,"וַ⁠יַּ֞ךְ בְּ⁠אַנְשֵׁ֣י בֵֽית־שֶׁ֗מֶשׁ כִּ֤י רָאוּ֙ בַּ⁠אֲר֣וֹן יְהוָ֔ה וַ⁠יַּ֤ךְ בָּ⁠עָם֙ שִׁבְעִ֣ים אִ֔ישׁ חֲמִשִּׁ֥ים אֶ֖לֶף אִ֑ישׁ וַ⁠יִּֽתְאַבְּל֣וּ הָ⁠עָ֔ם כִּֽי־הִכָּ֧ה יְהוָ֛ה בָּ⁠עָ֖ם מַכָּ֥ה גְדוֹלָֽה","wa⁠yȧ֞kĕ bĕ̇⁠ʼanĕşé֣̌y béֽyţ-şě֗meş̌ ki֤̇y ráʼẇ֙ bȧ⁠ʼàr֣wòn yĕhwá֔h wa⁠yȧ֤kĕ bá̇⁠ʻám֙ şǐbĕʻi֣ym ʼi֔yş̌ ẖàmişi֥̇̌ym ʼe֖lep ʼi֑yş̌ wa⁠yiֽ̇ţĕʼabĕ̇l֣ẇ há⁠ʻá֔m kiֽ̇y-hiká֧̇h yĕhwá֛h bá̇⁠ʻá֖m maká֥̇h gĕdwòláֽh"],[6,20,"וַ⁠יֹּֽאמְרוּ֙ אַנְשֵׁ֣י בֵֽית־שֶׁ֔מֶשׁ מִ֚י יוּכַ֣ל לַ⁠עֲמֹ֔ד לִ⁠פְנֵ֨י יְהוָ֧ה הָ⁠אֱלֹהִ֛ים הַ⁠קָּד֖וֹשׁ הַ⁠זֶּ֑ה וְ⁠אֶל־מִ֖י יַעֲלֶ֥ה מֵ⁠עָלֵֽי⁠נוּ׃ס","wa⁠yòֽ̇ʼmĕrẇ֙ ʼanĕşé֣̌y béֽyţ-şě֔meş̌ mi֚y yẇka֣l la⁠ʻàmò֔d li⁠pĕné֨y yĕhwá֧h há⁠ʼèlòhi֛ym ha⁠qá̇d֖wòş̌ ha⁠zė֑h wĕ⁠ʼel-mi֖y yaʻàle֥h mé⁠ʻáléֽy⁠nẇ׃s"],[6,21,"וַֽ⁠יִּשְׁלְחוּ֙ מַלְאָכִ֔ים אֶל־יוֹשְׁבֵ֥י קִרְיַת־יְעָרִ֖ים לֵ⁠אמֹ֑ר הֵשִׁ֤בוּ פְלִשְׁתִּים֙ אֶת־אֲר֣וֹן יְהוָ֔ה רְד֕וּ הַעֲל֥וּ אֹת֖⁠וֹ אֲלֵי⁠כֶֽם׃","waֽ⁠yi̇şĕ̌lĕẖẇ֙ malĕʼáki֔ym ʼel-ywòşĕ̌bé֥y qirĕyaţ-yĕʻári֖ym lé⁠ʼmò֑r héşǐ֤bẇ pĕlişĕ̌ţi̇ym֙ ʼeţ-ʼàr֣wòn yĕhwá֔h rĕd֕ẇ haʻàl֥ẇ ʼòţ֖⁠wò ʼàléy⁠keֽm׃"],[7,1,"וַ⁠יָּבֹ֜אוּ אַנְשֵׁ֣י ׀ קִרְיַ֣ת יְעָרִ֗ים וַֽ⁠יַּעֲלוּ֙ אֶת־אֲר֣וֹן יְהוָ֔ה וַ⁠יָּבִ֣אוּ אֹת֔⁠וֹ אֶל־בֵּ֥ית אֲבִינָדָ֖ב בַּ⁠גִּבְעָ֑ה וְ⁠אֶת־אֶלְעָזָ֤ר בְּנ⁠וֹ֙ קִדְּשׁ֔וּ לִ⁠שְׁמֹ֖ר אֶת־אֲר֥וֹן יְהוָֽה׃פ","wa⁠yá̇bò֜ʼẇ ʼanĕşé֣̌y ׀ qirĕya֣ţ yĕʻári֗ym wֽa⁠yȧʻàlẇ֙ ʼeţ-ʼàr֣wòn yĕhwá֔h wa⁠yá̇bi֣ʼẇ ʼòţ֔⁠wò ʼel-bé֥̇yţ ʼàbiynádá֖b bȧ⁠gi̇bĕʻá֑h wĕ⁠ʼeţ-ʼelĕʻázá֤r bĕ̇n⁠wò֙ qidĕ̇ş̌֔ẇ li⁠şĕ̌mò֖r ʼeţ-ʼàr֥wòn yĕhwáֽh׃p"],[7,2,"וַ⁠יְהִ֗י מִ⁠יּ֞וֹם שֶׁ֤בֶת הָֽ⁠אָרוֹן֙ בְּ⁠קִרְיַ֣ת יְעָרִ֔ים וַ⁠יִּרְבּוּ֙ הַ⁠יָּמִ֔ים וַ⁠יִּֽהְי֖וּ עֶשְׂרִ֣ים שָׁנָ֑ה וַ⁠יִּנָּה֛וּ כָּל־בֵּ֥ית יִשְׂרָאֵ֖ל אַחֲרֵ֥י יְהוָֽה׃ס","wa⁠yĕhi֗y mi⁠ẏ֞wòm şě֤beţ háֽ⁠ʼárwòn֙ bĕ̇⁠qirĕya֣ţ yĕʻári֔ym wa⁠yi̇rĕḃẇ֙ ha⁠yá̇mi֔ym wa⁠yiֽ̇hĕy֖ẇ ʻeşĕ̂ri֣ym şá̌ná֑h wa⁠yi̇ná̇h֛ẇ ká̇l-bé֥̇yţ yişĕ̂ráʼé֖l ʼaẖàré֥y yĕhwáֽh׃s"],[7,3,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֗ל אֶל־כָּל־בֵּ֣ית יִשְׂרָאֵל֮ לֵ⁠אמֹר֒ אִם־בְּ⁠כָל־לְבַבְ⁠כֶ֗ם אַתֶּ֤ם שָׁבִים֙ אֶל־יְהוָ֔ה הָסִ֜ירוּ אֶת־אֱלֹהֵ֧י הַ⁠נֵּכָ֛ר מִ⁠תּוֹכְ⁠כֶ֖ם וְ⁠הָ⁠עַשְׁתָּר֑וֹת וְ⁠הָכִ֨ינוּ לְבַבְ⁠כֶ֤ם אֶל־יְהוָה֙ וְ⁠עִבְדֻ֣⁠הוּ לְ⁠בַדּ֔⁠וֹ וְ⁠יַצֵּ֥ל אֶתְ⁠כֶ֖ם מִ⁠יַּ֥ד פְּלִשְׁתִּֽים׃","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֗l ʼel-ká̇l-bé֣̇yţ yişĕ̂ráʼél֮ lé⁠ʼmòr֒ ʼim-bĕ̇⁠kál-lĕbabĕ⁠ke֗m ʼaţė֤m şá̌biym֙ ʼel-yĕhwá֔h hási֜yrẇ ʼeţ-ʼèlòhé֧y ha⁠né̇ká֛r mi⁠ţ̇wòkĕ⁠ke֖m wĕ⁠há⁠ʻaşĕ̌ţá̇r֑wòţ wĕ⁠háki֨ynẇ lĕbabĕ⁠ke֤m ʼel-yĕhwáh֙ wĕ⁠ʻibĕdu֣⁠hẇ lĕ⁠baḋ֔⁠wò wĕ⁠yaẕé֥̇l ʼeţĕ⁠ke֖m mi⁠yȧ֥d pĕ̇lişĕ̌ţiֽ̇ym׃"],[7,4,"וַ⁠יָּסִ֨ירוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶת־הַ⁠בְּעָלִ֖ים וְ⁠אֶת־הָ⁠עַשְׁתָּרֹ֑ת וַ⁠יַּעַבְד֥וּ אֶת־יְהוָ֖ה לְ⁠בַדּֽ⁠וֹ׃פ","wa⁠yá̇si֨yrẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼeţ-ha⁠bĕ̇ʻáli֖ym wĕ⁠ʼeţ-há⁠ʻaşĕ̌ţá̇rò֑ţ wa⁠yȧʻabĕd֥ẇ ʼeţ-yĕhwá֖h lĕ⁠baḋֽ⁠wò׃p"],[7,5,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֔ל קִבְצ֥וּ אֶת־כָּל־יִשְׂרָאֵ֖ל הַ⁠מִּצְפָּ֑תָ⁠ה וְ⁠אֶתְפַּלֵּ֥ל בַּעַדְ⁠כֶ֖ם אֶל־יְהוָֽה׃","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֔l qibĕẕ֥ẇ ʼeţ-ká̇l-yişĕ̂ráʼé֖l ha⁠mi̇ẕĕpá֑̇ţá⁠h wĕ⁠ʼeţĕpȧlé֥̇l bȧʻadĕ⁠ke֖m ʼel-yĕhwáֽh׃"],[7,6,"וַ⁠יִּקָּבְצ֣וּ הַ֠⁠מִּצְפָּתָ⁠ה וַ⁠יִּֽשְׁאֲבוּ־מַ֜יִם וַֽ⁠יִּשְׁפְּכ֣וּ ׀ לִ⁠פְנֵ֣י יְהוָ֗ה וַ⁠יָּצ֨וּמוּ֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וַ⁠יֹּ֣אמְרוּ שָׁ֔ם חָטָ֖אנוּ לַ⁠יהוָ֑ה וַ⁠יִּשְׁפֹּ֧ט שְׁמוּאֵ֛ל אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל בַּ⁠מִּצְפָּֽה׃","wa⁠yi̇qá̇bĕẕ֣ẇ ha֠⁠mi̇ẕĕpá̇ţá⁠h wa⁠yiֽ̇şĕ̌ʼàbẇ-ma֜yim wֽa⁠yi̇şĕ̌pĕ̇k֣ẇ ׀ li⁠pĕné֣y yĕhwá֗h wa⁠yá̇ẕ֨ẇmẇ֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ wa⁠yò֣̇ʼmĕrẇ şá̌֔m ẖátá֖ʼnẇ la⁠yhwá֑h wa⁠yi̇şĕ̌pò֧̇t şĕ̌mẇʼé֛l ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l bȧ⁠mi̇ẕĕpáֽ̇h׃"],[7,7,"וַ⁠יִּשְׁמְע֣וּ פְלִשְׁתִּ֗ים כִּֽי־הִתְקַבְּצ֤וּ בְנֵֽי־יִשְׂרָאֵל֙ הַ⁠מִּצְפָּ֔תָ⁠ה וַ⁠יַּעֲל֥וּ סַרְנֵֽי־פְלִשְׁתִּ֖ים אֶל־יִשְׂרָאֵ֑ל וַֽ⁠יִּשְׁמְעוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יִּֽרְא֖וּ מִ⁠פְּנֵ֥י פְלִשְׁתִּֽים׃","wa⁠yi̇şĕ̌mĕʻ֣ẇ pĕlişĕ̌ţi̇֗ym kiֽ̇y-hiţĕqabĕ̇ẕ֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ ha⁠mi̇ẕĕpá̇֔ţá⁠h wa⁠yȧʻàl֥ẇ sarĕnéֽy-pĕlişĕ̌ţi֖̇ym ʼel-yişĕ̂ráʼé֑l waֽ⁠yi̇şĕ̌mĕʻẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l wa⁠yiֽ̇rĕʼ֖ẇ mi⁠pĕ̇né֥y pĕlişĕ̌ţiֽ̇ym׃"],[7,8,"וַ⁠יֹּאמְר֤וּ בְנֵֽי־יִשְׂרָאֵל֙ אֶל־שְׁמוּאֵ֔ל אַל־תַּחֲרֵ֣שׁ מִמֶּ֔⁠נּוּ מִ⁠זְּעֹ֖ק אֶל־יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ וְ⁠יֹשִׁעֵ֖⁠נוּ מִ⁠יַּ֥ד פְּלִשְׁתִּֽים׃","wa⁠yò̇ʼmĕr֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ ʼel-şĕ̌mẇʼé֔l ʼal-ţȧẖàré֣ş̌ mimė֔⁠ṅẇ mi⁠zĕ̇ʻò֖q ʼel-yĕhwá֣h ʼèlòhé֑y⁠nẇ wĕ⁠yòşǐʻé֖⁠nẇ mi⁠yȧ֥d pĕ̇lişĕ̌ţiֽ̇ym׃"],[7,9,"וַ⁠יִּקַּ֣ח שְׁמוּאֵ֗ל טְלֵ֤ה חָלָב֙ אֶחָ֔ד ו⁠יעלה עוֹלָ֛ה כָּלִ֖יל לַֽ⁠יהוָ֑ה וַ⁠יִּזְעַ֨ק שְׁמוּאֵ֤ל אֶל־יְהוָה֙ בְּעַ֣ד יִשְׂרָאֵ֔ל וַֽ⁠יַּעֲנֵ֖⁠הוּ יְהוָֽה׃","wa⁠yi̇qȧ֣ẖ şĕ̌mẇʼé֗l tĕlé֤h ẖáláb֙ ʼeẖá֔d w⁠yʻlh ʻwòlá֛h ká̇li֖yl laֽ⁠yhwá֑h wa⁠yi̇zĕʻa֨q şĕ̌mẇʼé֤l ʼel-yĕhwáh֙ bĕ̇ʻa֣d yişĕ̂ráʼé֔l waֽ⁠yȧʻàné֖⁠hẇ yĕhwáֽh׃"],[7,10,"וַ⁠יְהִ֤י שְׁמוּאֵל֙ מַעֲלֶ֣ה הָ⁠עוֹלָ֔ה וּ⁠פְלִשְׁתִּ֣ים נִגְּשׁ֔וּ לַ⁠מִּלְחָמָ֖ה בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יַּרְעֵ֣ם יְהוָ֣ה ׀ בְּ⁠קוֹל־גָּ֠דוֹל בַּ⁠יּ֨וֹם הַ⁠ה֤וּא עַל־פְּלִשְׁתִּים֙ וַ⁠יְהֻמֵּ֔⁠ם וַ⁠יִּנָּגְפ֖וּ לִ⁠פְנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yĕhi֤y şĕ̌mẇʼél֙ maʻàle֣h há⁠ʻwòlá֔h ẇ⁠pĕlişĕ̌ţi֣̇ym nigĕ̇ş̌֔ẇ la⁠mi̇lĕẖámá֖h bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yȧrĕʻé֣m yĕhwá֣h ׀ bĕ̇⁠qwòl-gá̇֠dwòl bȧ⁠ẏ֨wòm ha⁠h֤ẇʼ ʻal-pĕ̇lişĕ̌ţi̇ym֙ wa⁠yĕhumé̇֔⁠m wa⁠yi̇ná̇gĕp֖ẇ li⁠pĕné֥y yişĕ̂ráʼéֽl׃"],[7,11,"וַ⁠יֵּ֨צְא֜וּ אַנְשֵׁ֤י יִשְׂרָאֵל֙ מִן־הַ⁠מִּצְפָּ֔ה וַֽ⁠יִּרְדְּפ֖וּ אֶת־פְּלִשְׁתִּ֑ים וַ⁠יַּכּ֕וּ⁠ם עַד־מִ⁠תַּ֖חַת לְ⁠בֵ֥ית כָּֽר׃","wa⁠yé̇֨ẕĕʼ֜ẇ ʼanĕşé֤̌y yişĕ̂ráʼél֙ min-ha⁠mi̇ẕĕpá̇֔h waֽ⁠yi̇rĕdĕ̇p֖ẇ ʼeţ-pĕ̇lişĕ̌ţi֑̇ym wa⁠yȧk̇֕ẇ⁠m ʻad-mi⁠ţȧ֖ẖaţ lĕ⁠bé֥yţ káֽ̇r׃"],[7,12,"וַ⁠יִּקַּ֨ח שְׁמוּאֵ֜ל אֶ֣בֶן אַחַ֗ת וַ⁠יָּ֤שֶׂם בֵּֽין־הַ⁠מִּצְפָּה֙ וּ⁠בֵ֣ין הַ⁠שֵּׁ֔ן וַ⁠יִּקְרָ֥א אֶת־שְׁמָ֖⁠הּ אֶ֣בֶן הָעָ֑זֶר וַ⁠יֹּאמַ֕ר עַד־הֵ֖נָּה עֲזָרָ֥⁠נוּ יְהוָֽה׃","wa⁠yi̇qȧ֨ẖ şĕ̌mẇʼé֜l ʼe֣ben ʼaẖa֗ţ wa⁠yá֤̇şêm béֽ̇yn-ha⁠mi̇ẕĕpá̇h֙ ẇ⁠bé֣yn ha⁠şé̇̌֔n wa⁠yi̇qĕrá֥ʼ ʼeţ-şĕ̌má֖⁠ḣ ʼe֣ben háʻá֑zer wa⁠yò̇ʼma֕r ʻad-hé֖ná̇h ʻàzárá֥⁠nẇ yĕhwáֽh׃"],[7,13,"וַ⁠יִּכָּֽנְעוּ֙ הַ⁠פְּלִשְׁתִּ֔ים וְ⁠לֹא־יָסְפ֣וּ ע֔וֹד לָ⁠ב֖וֹא בִּ⁠גְב֣וּל יִשְׂרָאֵ֑ל וַ⁠תְּהִ֤י יַד־יְהוָה֙ בַּ⁠פְּלִשְׁתִּ֔ים כֹּ֖ל יְמֵ֥י שְׁמוּאֵֽל׃","wa⁠yi̇káֽ̇nĕʻẇ֙ ha⁠pĕ̇lişĕ̌ţi̇֔ym wĕ⁠lòʼ-yásĕp֣ẇ ʻ֔wòd lá⁠b֖wòʼ bi̇⁠gĕb֣ẇl yişĕ̂ráʼé֑l wa⁠ţĕ̇hi֤y yad-yĕhwáh֙ bȧ⁠pĕ̇lişĕ̌ţi̇֔ym kò֖̇l yĕmé֥y şĕ̌mẇʼéֽl׃"],[7,14,"וַ⁠תָּשֹׁ֣בְנָה הֶ⁠עָרִ֡ים אֲשֶׁ֣ר לָֽקְחוּ־פְלִשְׁתִּים֩ מֵ⁠אֵ֨ת יִשְׂרָאֵ֤ל ׀ לְ⁠יִשְׂרָאֵל֙ מֵ⁠עֶקְר֣וֹן וְ⁠עַד־גַּ֔ת וְ⁠אֶ֨ת־גְּבוּלָ֔⁠ן הִצִּ֥יל יִשְׂרָאֵ֖ל מִ⁠יַּ֣ד פְּלִשְׁתִּ֑ים וַ⁠יְהִ֣י שָׁל֔וֹם בֵּ֥ין יִשְׂרָאֵ֖ל וּ⁠בֵ֥ין הָ⁠אֱמֹרִֽי׃","wa⁠ţá̇şò֣̌bĕnáh he⁠ʻári֡ym ʼàşě֣r láֽqĕẖẇ-pĕlişĕ̌ţi̇ym֩ mé⁠ʼé֨ţ yişĕ̂ráʼé֤l ׀ lĕ⁠yişĕ̂ráʼél֙ mé⁠ʻeqĕr֣wòn wĕ⁠ʻad-gȧ֔ţ wĕ⁠ʼe֨ţ-gĕ̇bẇlá֔⁠n hiẕi֥̇yl yişĕ̂ráʼé֖l mi⁠yȧ֣d pĕ̇lişĕ̌ţi֑̇ym wa⁠yĕhi֣y şá̌l֔wòm bé֥̇yn yişĕ̂ráʼé֖l ẇ⁠bé֥yn há⁠ʼèmòriֽy׃"],[7,15,"וַ⁠יִּשְׁפֹּ֤ט שְׁמוּאֵל֙ אֶת־יִשְׂרָאֵ֔ל כֹּ֖ל יְמֵ֥י חַיָּֽי⁠ו׃","wa⁠yi̇şĕ̌pò֤̇t şĕ̌mẇʼél֙ ʼeţ-yişĕ̂ráʼé֔l kò֖̇l yĕmé֥y ẖayáֽ̇y⁠w׃"],[7,16,"וְ⁠הָלַ֗ךְ מִ⁠דֵּ֤י שָׁנָה֙ בְּ⁠שָׁנָ֔ה וְ⁠סָבַב֙ בֵּֽית־אֵ֔ל וְ⁠הַ⁠גִּלְגָּ֖ל וְ⁠הַ⁠מִּצְפָּ֑ה וְ⁠שָׁפַט֙ אֶת־יִשְׂרָאֵ֔ל אֵ֥ת כָּל־הַ⁠מְּקוֹמ֖וֹת הָ⁠אֵֽלֶּה׃","wĕ⁠hála֗kĕ mi⁠dé֤̇y şá̌náh֙ bĕ̇⁠şá̌ná֔h wĕ⁠sábab֙ béֽ̇yţ-ʼé֔l wĕ⁠ha⁠gi̇lĕgá֖̇l wĕ⁠ha⁠mi̇ẕĕpá֑̇h wĕ⁠şá̌pat֙ ʼeţ-yişĕ̂ráʼé֔l ʼé֥ţ ká̇l-ha⁠mĕ̇qwòm֖wòţ há⁠ʼéֽlėh׃"],[7,17,"וּ⁠תְשֻׁבָת֤⁠וֹ הָ⁠רָמָ֨תָ⁠ה֙ כִּֽי־שָׁ֣ם בֵּית֔⁠וֹ וְ⁠שָׁ֖ם שָׁפָ֣ט אֶת־יִשְׂרָאֵ֑ל וַ⁠יִּֽבֶן־שָׁ֥ם מִזְבֵּ֖חַ לַֽ⁠יהוָֽה׃פ","ẇ⁠ţĕşǔbáţ֤⁠wò há⁠rámá֨ţá⁠h֙ kiֽ̇y-şá֣̌m bé̇yţ֔⁠wò wĕ⁠şá֖̌m şá̌pá֣t ʼeţ-yişĕ̂ráʼé֑l wa⁠yiֽ̇ben-şá֥̌m mizĕbé֖̇ẖa laֽ⁠yhwáֽh׃p"],[8,1,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁ֥ר זָקֵ֖ן שְׁמוּאֵ֑ל וַ⁠יָּ֧שֶׂם אֶת־בָּנָ֛י⁠ו שֹׁפְטִ֖ים לְ⁠יִשְׂרָאֵֽל׃","wa⁠yĕhi֕y kȧ⁠ʼàşě֥r záqé֖n şĕ̌mẇʼé֑l wa⁠yá֧̇şêm ʼeţ-bá̇ná֛y⁠w şò̌pĕti֖ym lĕ⁠yişĕ̂ráʼéֽl׃"],[8,2,"וַ⁠יְהִ֞י שֶׁם־בְּנ֤⁠וֹ הַ⁠בְּכוֹר֙ יוֹאֵ֔ל וְ⁠שֵׁ֥ם מִשְׁנֵ֖⁠הוּ אֲבִיָּ֑ה שֹׁפְטִ֖ים בִּ⁠בְאֵ֥ר שָֽׁבַע׃","wa⁠yĕhi֞y şěm-bĕ̇n֤⁠wò ha⁠bĕ̇kwòr֙ ywòʼé֔l wĕ⁠şé֥̌m mişĕ̌né֖⁠hẇ ʼàbiyá֑̇h şò̌pĕti֖ym bi̇⁠bĕʼé֥r şáֽ̌baʻ׃"],[8,3,"וְ⁠לֹֽא־הָלְכ֤וּ בָנָי⁠ו֙ ב⁠דרכ⁠ו וַ⁠יִּטּ֖וּ אַחֲרֵ֣י הַ⁠בָּ֑צַע וַ⁠יִּ֨קְחוּ־שֹׁ֔חַד וַ⁠יַּטּ֖וּ מִשְׁפָּֽט׃פ","wĕ⁠lòֽʼ-hálĕk֤ẇ bánáy⁠w֙ b⁠drk⁠w wa⁠yi̇ṫ֖ẇ ʼaẖàré֣y ha⁠bá֑̇ẕaʻ wa⁠yi̇֨qĕẖẇ-şò̌֔ẖad wa⁠yȧṫ֖ẇ mişĕ̌páֽ̇t׃p"],[8,4,"וַ⁠יִּֽתְקַבְּצ֔וּ כֹּ֖ל זִקְנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יָּבֹ֥אוּ אֶל־שְׁמוּאֵ֖ל הָ⁠רָמָֽתָ⁠ה׃","wa⁠yiֽ̇ţĕqabĕ̇ẕ֔ẇ kò֖̇l ziqĕné֣y yişĕ̂ráʼé֑l wa⁠yá̇bò֥ʼẇ ʼel-şĕ̌mẇʼé֖l há⁠rámáֽţá⁠h׃"],[8,5,"וַ⁠יֹּאמְר֣וּ אֵלָ֗י⁠ו הִנֵּה֙ אַתָּ֣ה זָקַ֔נְתָּ וּ⁠בָנֶ֕י⁠ךָ לֹ֥א הָלְכ֖וּ בִּ⁠דְרָכֶ֑י⁠ךָ עַתָּ֗ה שִֽׂימָ⁠ה־לָּ֥⁠נוּ מֶ֛לֶךְ לְ⁠שָׁפְטֵ֖⁠נוּ כְּ⁠כָל־הַ⁠גּוֹיִֽם׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֗y⁠w hiné̇h֙ ʼaţá֣̇h záqa֔nĕţá̇ ẇ⁠báne֕y⁠ká lò֥ʼ hálĕk֖ẇ bi̇⁠dĕráke֑y⁠ká ʻaţá̇֗h şîֽymá⁠h-lá֥̇⁠nẇ me֛lekĕ lĕ⁠şá̌pĕté֖⁠nẇ kĕ̇⁠kál-ha⁠ġwòyiֽm׃"],[8,6,"וַ⁠יֵּ֤רַע הַ⁠דָּבָר֙ בְּ⁠עֵינֵ֣י שְׁמוּאֵ֔ל כַּ⁠אֲשֶׁ֣ר אָמְר֔וּ תְּנָ⁠ה־לָּ֥⁠נוּ מֶ֖לֶךְ לְ⁠שָׁפְטֵ֑⁠נוּ וַ⁠יִּתְפַּלֵּ֥ל שְׁמוּאֵ֖ל אֶל־יְהוָֽה׃פ","wa⁠yé֤̇raʻ ha⁠dá̇bár֙ bĕ̇⁠ʻéyné֣y şĕ̌mẇʼé֔l kȧ⁠ʼàşě֣r ʼámĕr֔ẇ ţĕ̇ná⁠h-lá֥̇⁠nẇ me֖lekĕ lĕ⁠şá̌pĕté֑⁠nẇ wa⁠yi̇ţĕpȧlé֥̇l şĕ̌mẇʼé֖l ʼel-yĕhwáֽh׃p"],[8,7,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־שְׁמוּאֵ֔ל שְׁמַע֙ בְּ⁠ק֣וֹל הָ⁠עָ֔ם לְ⁠כֹ֥ל אֲשֶׁר־יֹאמְר֖וּ אֵלֶ֑י⁠ךָ כִּ֣י לֹ֤א אֹֽתְ⁠ךָ֙ מָאָ֔סוּ כִּֽי־אֹתִ֥⁠י מָאֲס֖וּ מִ⁠מְּלֹ֥ךְ עֲלֵי⁠הֶֽם׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-şĕ̌mẇʼé֔l şĕ̌maʻ֙ bĕ̇⁠q֣wòl há⁠ʻá֔m lĕ⁠kò֥l ʼàşěr-yòʼmĕr֖ẇ ʼéle֑y⁠ká ki֣̇y lò֤ʼ ʼòֽţĕ⁠ká֙ máʼá֔sẇ kiֽ̇y-ʼòţi֥⁠y máʼàs֖ẇ mi⁠mĕ̇lò֥kĕ ʻàléy⁠heֽm׃"],[8,8,"כְּ⁠כָֽל־הַ⁠מַּעֲשִׂ֣ים אֲשֶׁר־עָשׂ֗וּ מִ⁠יּוֹם֩ הַעֲלֹתִ֨⁠י אֹתָ֤⁠ם מִ⁠מִּצְרַ֨יִם֙ וְ⁠עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה וַ⁠יַּ֣עַזְבֻ֔⁠נִי וַ⁠יַּעַבְד֖וּ אֱלֹהִ֣ים אֲחֵרִ֑ים כֵּ֛ן הֵ֥מָּה עֹשִׂ֖ים גַּם־לָֽ⁠ךְ׃","kĕ̇⁠káֽl-ha⁠mȧʻàşî֣ym ʼàşěr-ʻáş̂֗ẇ mi⁠ẏwòm֩ haʻàlòţi֨⁠y ʼòţá֤⁠m mi⁠mi̇ẕĕra֨yim֙ wĕ⁠ʻad-ha⁠ẏ֣wòm ha⁠zė֔h wa⁠yȧ֣ʻazĕbu֔⁠niy wa⁠yȧʻabĕd֖ẇ ʼèlòhi֣ym ʼàẖéri֑ym ké֛̇n hé֥má̇h ʻòşî֖ym gȧm-láֽ⁠kĕ׃"],[8,9,"וְ⁠עַתָּ֖ה שְׁמַ֣ע בְּ⁠קוֹלָ֑⁠ם אַ֗ךְ כִּֽי־הָעֵ֤ד תָּעִיד֙ בָּ⁠הֶ֔ם וְ⁠הִגַּדְתָּ֣ לָ⁠הֶ֔ם מִשְׁפַּ֣ט הַ⁠מֶּ֔לֶךְ אֲשֶׁ֥ר יִמְלֹ֖ךְ עֲלֵי⁠הֶֽם׃ס","wĕ⁠ʻaţá֖̇h şĕ̌ma֣ʻ bĕ̇⁠qwòlá֑⁠m ʼa֗kĕ kiֽ̇y-háʻé֤d ţá̇ʻiyd֙ bá̇⁠he֔m wĕ⁠higȧdĕţá֣̇ lá⁠he֔m mişĕ̌pȧ֣t ha⁠mė֔lekĕ ʼàşě֥r yimĕlò֖kĕ ʻàléy⁠heֽm׃s"],[8,10,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֔ל אֵ֖ת כָּל־דִּבְרֵ֣י יְהוָ֑ה אֶל־הָ⁠עָ֕ם הַ⁠שֹּׁאֲלִ֥ים מֵ⁠אִתּ֖⁠וֹ מֶֽלֶךְ׃ס","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֔l ʼé֖ţ ká̇l-di̇bĕré֣y yĕhwá֑h ʼel-há⁠ʻá֕m ha⁠şò̇̌ʼàli֥ym mé⁠ʼiţ֖̇⁠wò meֽlekĕ׃s"],[8,11,"וַ⁠יֹּ֕אמֶר זֶ֗ה יִֽהְיֶה֙ מִשְׁפַּ֣ט הַ⁠מֶּ֔לֶךְ אֲשֶׁ֥ר יִמְלֹ֖ךְ עֲלֵי⁠כֶ֑ם אֶת־בְּנֵי⁠כֶ֣ם יִקָּ֗ח וְ⁠שָׂ֥ם ל⁠וֹ֙ בְּ⁠מֶרְכַּבְתּ֣⁠וֹ וּ⁠בְ⁠פָרָשָׁ֔י⁠ו וְ⁠רָצ֖וּ לִ⁠פְנֵ֥י מֶרְכַּבְתּֽ⁠וֹ׃","wa⁠yò̇֕ʼmer ze֗h yiֽhĕyeh֙ mişĕ̌pȧ֣t ha⁠mė֔lekĕ ʼàşě֥r yimĕlò֖kĕ ʻàléy⁠ke֑m ʼeţ-bĕ̇néy⁠ke֣m yiqá̇֗ẖ wĕ⁠şá֥̂m l⁠wò֙ bĕ̇⁠merĕkȧbĕţ֣̇⁠wò ẇ⁠bĕ⁠páráşá̌֔y⁠w wĕ⁠ráẕ֖ẇ li⁠pĕné֥y merĕkȧbĕţֽ̇⁠wò׃"],[8,12,"וְ⁠לָ⁠שׂ֣וּם ל֔⁠וֹ שָׂרֵ֥י אֲלָפִ֖ים וְ⁠שָׂרֵ֣י חֲמִשִּׁ֑ים וְ⁠לַ⁠חֲרֹ֤שׁ חֲרִישׁ⁠וֹ֙ וְ⁠לִ⁠קְצֹ֣ר קְצִיר֔⁠וֹ וְ⁠לַ⁠עֲשׂ֥וֹת כְּלֵֽי־מִלְחַמְתּ֖⁠וֹ וּ⁠כְלֵ֥י רִכְבּֽ⁠וֹ׃","wĕ⁠lá⁠ş֣̂ẇm l֔⁠wò şá̂ré֥y ʼàlápi֖ym wĕ⁠şá̂ré֣y ẖàmişi֑̇̌ym wĕ⁠la⁠ẖàrò֤ş̌ ẖàriyş̌⁠wò֙ wĕ⁠li⁠qĕẕò֣r qĕẕiyr֔⁠wò wĕ⁠la⁠ʻàş֥̂wòţ kĕ̇léֽy-milĕẖamĕţ֖̇⁠wò ẇ⁠kĕlé֥y rikĕḃֽ⁠wò׃"],[8,13,"וְ⁠אֶת־בְּנוֹתֵי⁠כֶ֖ם יִקָּ֑ח לְ⁠רַקָּח֥וֹת וּ⁠לְ⁠טַבָּח֖וֹת וּ⁠לְ⁠אֹפֽוֹת׃","wĕ⁠ʼeţ-bĕ̇nwòţéy⁠ke֖m yiqá֑̇ẖ lĕ⁠raqá̇ẖ֥wòţ ẇ⁠lĕ⁠tabá̇ẖ֖wòţ ẇ⁠lĕ⁠ʼòpֽwòţ׃"],[8,14,"וְ⁠אֶת־שְׂ֠דֽוֹתֵי⁠כֶם וְ⁠אֶת־כַּרְמֵי⁠כֶ֧ם וְ⁠זֵיתֵי⁠כֶ֛ם הַ⁠טּוֹבִ֖ים יִקָּ֑ח וְ⁠נָתַ֖ן לַ⁠עֲבָדָֽי⁠ו׃","wĕ⁠ʼeţ-şĕ̂֠dֽwòţéy⁠kem wĕ⁠ʼeţ-kȧrĕméy⁠ke֧m wĕ⁠zéyţéy⁠ke֛m ha⁠ṫwòbi֖ym yiqá֑̇ẖ wĕ⁠náţa֖n la⁠ʻàbádáֽy⁠w׃"],[8,15,"וְ⁠זַרְעֵי⁠כֶ֥ם וְ⁠כַרְמֵי⁠כֶ֖ם יַעְשֹׂ֑ר וְ⁠נָתַ֥ן לְ⁠סָרִיסָ֖י⁠ו וְ⁠לַ⁠עֲבָדָֽי⁠ו׃","wĕ⁠zarĕʻéy⁠ke֥m wĕ⁠karĕméy⁠ke֖m yaʻĕşò֑̂r wĕ⁠náţa֥n lĕ⁠sáriysá֖y⁠w wĕ⁠la⁠ʻàbádáֽy⁠w׃"],[8,16,"וְ⁠אֶת־עַבְדֵי⁠כֶם֩ וְֽ⁠אֶת־שִׁפְח֨וֹתֵי⁠כֶ֜ם וְ⁠אֶת־בַּחוּרֵי⁠כֶ֧ם הַ⁠טּוֹבִ֛ים וְ⁠אֶת־חֲמוֹרֵי⁠כֶ֖ם יִקָּ֑ח וְ⁠עָשָׂ֖ה לִ⁠מְלַאכְתּֽ⁠וֹ׃","wĕ⁠ʼeţ-ʻabĕdéy⁠kem֩ wĕֽ⁠ʼeţ-şǐpĕẖ֨wòţéy⁠ke֜m wĕ⁠ʼeţ-bȧẖẇréy⁠ke֧m ha⁠ṫwòbi֛ym wĕ⁠ʼeţ-ẖàmwòréy⁠ke֖m yiqá֑̇ẖ wĕ⁠ʻáşá֖̂h li⁠mĕlaʼkĕţֽ̇⁠wò׃"],[8,17,"צֹאנְ⁠כֶ֖ם יַעְשֹׂ֑ר וְ⁠אַתֶּ֖ם תִּֽהְיוּ־ל֥⁠וֹ לַ⁠עֲבָדִֽים׃","ẕòʼnĕ⁠ke֖m yaʻĕşò֑̂r wĕ⁠ʼaţė֖m ţiֽ̇hĕyẇ-l֥⁠wò la⁠ʻàbádiֽym׃"],[8,18,"וּ⁠זְעַקְתֶּם֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא מִ⁠לִּ⁠פְנֵ֣י מַלְכְּ⁠כֶ֔ם אֲשֶׁ֥ר בְּחַרְתֶּ֖ם לָ⁠כֶ֑ם וְ⁠לֹֽא־יַעֲנֶ֧ה יְהוָ֛ה אֶתְ⁠כֶ֖ם בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","ẇ⁠zĕʻaqĕţėm֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ mi⁠li̇⁠pĕné֣y malĕkĕ̇⁠ke֔m ʼàşě֥r bĕ̇ẖarĕţė֖m lá⁠ke֑m wĕ⁠lòֽʼ-yaʻàne֧h yĕhwá֛h ʼeţĕ⁠ke֖m bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"],[8,19,"וַ⁠יְמָאֲנ֣וּ הָ⁠עָ֔ם לִ⁠שְׁמֹ֖עַ בְּ⁠ק֣וֹל שְׁמוּאֵ֑ל וַ⁠יֹּאמְר֣וּ לֹּ֔א כִּ֥י אִם־מֶ֖לֶךְ יִֽהְיֶ֥ה עָלֵֽי⁠נוּ׃","wa⁠yĕmáʼàn֣ẇ há⁠ʻá֔m li⁠şĕ̌mò֖ʻa bĕ̇⁠q֣wòl şĕ̌mẇʼé֑l wa⁠yò̇ʼmĕr֣ẇ lò̇֔ʼ ki֥̇y ʼim-me֖lekĕ yiֽhĕye֥h ʻáléֽy⁠nẇ׃"],[8,20,"וְ⁠הָיִ֥ינוּ גַם־אֲנַ֖חְנוּ כְּ⁠כָל־הַ⁠גּוֹיִ֑ם וּ⁠שְׁפָטָ֤⁠נוּ מַלְכֵּ֨⁠נוּ֙ וְ⁠יָצָ֣א לְ⁠פָנֵ֔י⁠נוּ וְ⁠נִלְחַ֖ם אֶת־מִלְחֲמֹתֵֽ⁠נוּ׃","wĕ⁠háyi֥ynẇ gam-ʼàna֖ẖĕnẇ kĕ̇⁠kál-ha⁠ġwòyi֑m ẇ⁠şĕ̌pátá֤⁠nẇ malĕké̇֨⁠nẇ֙ wĕ⁠yáẕá֣ʼ lĕ⁠páné֔y⁠nẇ wĕ⁠nilĕẖa֖m ʼeţ-milĕẖàmòţéֽ⁠nẇ׃"],[8,21,"וַ⁠יִּשְׁמַ֣ע שְׁמוּאֵ֔ל אֵ֖ת כָּל־דִּבְרֵ֣י הָ⁠עָ֑ם וַֽ⁠יְדַבְּרֵ֖⁠ם בְּ⁠אָזְנֵ֥י יְהוָֽה׃פ","wa⁠yi̇şĕ̌ma֣ʻ şĕ̌mẇʼé֔l ʼé֖ţ ká̇l-di̇bĕré֣y há⁠ʻá֑m waֽ⁠yĕdabĕ̇ré֖⁠m bĕ̇⁠ʼázĕné֥y yĕhwáֽh׃p"],[8,22,"וַ⁠יֹּ֨אמֶר יְהוָ֤ה אֶל־שְׁמוּאֵל֙ שְׁמַ֣ע בְּ⁠קוֹלָ֔⁠ם וְ⁠הִמְלַכְתָּ֥ לָ⁠הֶ֖ם מֶ֑לֶךְ וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־אַנְשֵׁ֣י יִשְׂרָאֵ֔ל לְכ֖וּ אִ֥ישׁ לְ⁠עִירֽ⁠וֹ׃פ","wa⁠yò̇֨ʼmer yĕhwá֤h ʼel-şĕ̌mẇʼél֙ şĕ̌ma֣ʻ bĕ̇⁠qwòlá֔⁠m wĕ⁠himĕlakĕţá֥̇ lá⁠he֖m me֑lekĕ wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-ʼanĕşé֣̌y yişĕ̂ráʼé֔l lĕk֖ẇ ʼi֥yş̌ lĕ⁠ʻiyrֽ⁠wò׃p"],[9,1,"וַֽ⁠יְהִי־אִ֣ישׁ מ⁠בן־ימין וּ֠⁠שְׁמ⁠וֹ קִ֣ישׁ בֶּן־אֲבִיאֵ֞ל בֶּן־צְר֧וֹר בֶּן־בְּכוֹרַ֛ת בֶּן־אֲפִ֖יחַ בֶּן־אִ֣ישׁ יְמִינִ֑י גִּבּ֖וֹר חָֽיִל׃","wֽa⁠yĕhiy-ʼi֣yş̌ m⁠bn-ymyn ẇ֠⁠şĕ̌m⁠wò qi֣yş̌ bėn-ʼàbiyʼé֞l bėn-ẕĕr֧wòr bėn-bĕ̇kwòra֛ţ bėn-ʼàpi֖yẖa bėn-ʼi֣yş̌ yĕmiyni֑y gi̇ḃ֖wòr ẖáֽyil׃"],[9,2,"וְ⁠ל⁠וֹ־הָיָ֨ה בֵ֜ן וּ⁠שְׁמ֤⁠וֹ שָׁאוּל֙ בָּח֣וּר וָ⁠ט֔וֹב וְ⁠אֵ֥ין אִ֛ישׁ מִ⁠בְּנֵ֥י יִשְׂרָאֵ֖ל ט֣וֹב מִמֶּ֑⁠נּוּ מִ⁠שִּׁכְמ֣⁠וֹ וָ⁠מַ֔עְלָ⁠ה גָּבֹ֖הַּ מִ⁠כָּל־הָ⁠עָֽם׃","wĕ⁠l⁠wò-háyá֨h bé֜n ẇ⁠şĕ̌m֤⁠wò şá̌ʼẇl֙ bá̇ẖ֣ẇr wá⁠t֔wòb wĕ⁠ʼé֥yn ʼi֛yş̌ mi⁠bĕ̇né֥y yişĕ̂ráʼé֖l t֣wòb mimė֑⁠ṅẇ mi⁠şi̇̌kĕm֣⁠wò wá⁠ma֔ʻĕlá⁠h gá̇bò֖hȧ mi⁠ká̇l-há⁠ʻáֽm׃"],[9,3,"וַ⁠תֹּאבַ֨דְנָה֙ הָ⁠אֲתֹנ֔וֹת לְ⁠קִ֖ישׁ אֲבִ֣י שָׁא֑וּל וַ⁠יֹּ֨אמֶר קִ֜ישׁ אֶל־שָׁא֣וּל בְּנ֗⁠וֹ קַח־נָ֤א אִתְּ⁠ךָ֙ אֶת־אַחַ֣ד מֵֽ⁠הַ⁠נְּעָרִ֔ים וְ⁠ק֣וּם לֵ֔ךְ בַּקֵּ֖שׁ אֶת־הָ⁠אֲתֹנֹֽת׃","wa⁠ţò̇ʼba֨dĕnáh֙ há⁠ʼàţòn֔wòţ lĕ⁠qi֖yş̌ ʼàbi֣y şá̌ʼ֑ẇl wa⁠yò̇֨ʼmer qi֜yş̌ ʼel-şá̌ʼ֣ẇl bĕ̇n֗⁠wò qaẖ-ná֤ʼ ʼiţĕ̇⁠ká֙ ʼeţ-ʼaẖa֣d méֽ⁠ha⁠nĕ̇ʻári֔ym wĕ⁠q֣ẇm lé֔kĕ bȧqé֖̇ş̌ ʼeţ-há⁠ʼàţònòֽţ׃"],[9,4,"וַ⁠יַּעֲבֹ֧ר בְּ⁠הַר־אֶפְרַ֛יִם וַ⁠יַּעֲבֹ֥ר בְּ⁠אֶֽרֶץ־שָׁלִ֖שָׁה וְ⁠לֹ֣א מָצָ֑אוּ וַ⁠יַּעַבְר֤וּ בְ⁠אֶֽרֶץ־שַׁעֲלִים֙ וָ⁠אַ֔יִן וַ⁠יַּעֲבֹ֥ר בְּ⁠אֶֽרֶץ־יְמִינִ֖י וְ⁠לֹ֥א מָצָֽאוּ׃","wa⁠yȧʻàbò֧r bĕ̇⁠har-ʼepĕra֛yim wa⁠yȧʻàbò֥r bĕ̇⁠ʼeֽreẕ-şá̌li֖şá̌h wĕ⁠lò֣ʼ máẕá֑ʼẇ wa⁠yȧʻabĕr֤ẇ bĕ⁠ʼeֽreẕ-şǎʻàliym֙ wá⁠ʼa֔yin wa⁠yȧʻàbò֥r bĕ̇⁠ʼeֽreẕ-yĕmiyni֖y wĕ⁠lò֥ʼ máẕáֽʼẇ׃"],[9,5,"הֵ֗מָּה בָּ֚אוּ בְּ⁠אֶ֣רֶץ צ֔וּף וְ⁠שָׁא֥וּל אָמַ֛ר לְ⁠נַעֲר֥⁠וֹ אֲשֶׁר־עִמּ֖⁠וֹ לְכָ֣⁠ה וְ⁠נָשׁ֑וּבָה פֶּן־יֶחְדַּ֥ל אָבִ֛⁠י מִן־הָ⁠אֲתֹנ֖וֹת וְ⁠דָ֥אַג לָֽ⁠נוּ׃","hé֗má̇h bá֚̇ʼẇ bĕ̇⁠ʼe֣reẕ ẕ֔ẇp wĕ⁠şá̌ʼ֥ẇl ʼáma֛r lĕ⁠naʻàr֥⁠wò ʼàşěr-ʻiṁ֖⁠wò lĕká֣⁠h wĕ⁠náş֑̌ẇbáh pėn-yeẖĕdȧ֥l ʼábi֛⁠y min-há⁠ʼàţòn֖wòţ wĕ⁠dá֥ʼag láֽ⁠nẇ׃"],[9,6,"וַ⁠יֹּ֣אמֶר ל֗⁠וֹ הִנֵּה־נָ֤א אִישׁ־אֱלֹהִים֙ בָּ⁠עִ֣יר הַ⁠זֹּ֔את וְ⁠הָ⁠אִ֣ישׁ נִכְבָּ֔ד כֹּ֥ל אֲשֶׁר־יְדַבֵּ֖ר בּ֣וֹא יָב֑וֹא עַתָּה֙ נֵ֣לֲכָה שָּׁ֔ם אוּלַי֙ יַגִּ֣יד לָ֔⁠נוּ אֶת־דַּרְכֵּ֖⁠נוּ אֲשֶׁר־הָלַ֥כְנוּ עָלֶֽי⁠הָ׃","wa⁠yò֣̇ʼmer l֗⁠wò hiné̇h-ná֤ʼ ʼiyş̌-ʼèlòhiym֙ bá̇⁠ʻi֣yr ha⁠zò̇֔ʼţ wĕ⁠há⁠ʼi֣yş̌ nikĕbá̇֔d kò֥̇l ʼàşěr-yĕdabé֖̇r ḃ֣wòʼ yáb֑wòʼ ʻaţá̇h֙ né֣làkáh şá̇̌֔m ʼẇlay֙ yagi֣̇yd lá֔⁠nẇ ʼeţ-dȧrĕké֖̇⁠nẇ ʼàşěr-hála֥kĕnẇ ʻáleֽy⁠há׃"],[9,7,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל לְ⁠נַעֲר֗⁠וֹ וְ⁠הִנֵּ֣ה נֵלֵךְ֮ וּ⁠מַה־נָּבִ֣יא לָ⁠אִישׁ֒ כִּ֤י הַ⁠לֶּ֨חֶם֙ אָזַ֣ל מִ⁠כֵּלֵ֔י⁠נוּ וּ⁠תְשׁוּרָ֥ה אֵין־לְ⁠הָבִ֖יא לְ⁠אִ֣ישׁ הָ⁠אֱלֹהִ֑ים מָ֖ה אִתָּֽ⁠נוּ׃","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl lĕ⁠naʻàr֗⁠wò wĕ⁠hiné֣̇h nélékĕ֮ ẇ⁠mah-ná̇bi֣yʼ lá⁠ʼiyş̌֒ ki֤̇y ha⁠lė֨ẖem֙ ʼáza֣l mi⁠ké̇lé֔y⁠nẇ ẇ⁠ţĕş̌ẇrá֥h ʼéyn-lĕ⁠hábi֖yʼ lĕ⁠ʼi֣yş̌ há⁠ʼèlòhi֑ym má֖h ʼiţáֽ̇⁠nẇ׃"],[9,8,"וַ⁠יֹּ֤סֶף הַ⁠נַּ֨עַר֙ לַ⁠עֲנ֣וֹת אֶת־שָׁא֔וּל וַ⁠יֹּ֕אמֶר הִנֵּה֙ נִמְצָ֣א בְ⁠יָדִ֔⁠י רֶ֖בַע שֶׁ֣קֶל כָּ֑סֶף וְ⁠נָֽתַתִּי֙ לְ⁠אִ֣ישׁ הָ⁠אֱלֹהִ֔ים וְ⁠הִגִּ֥יד לָ֖⁠נוּ אֶת־דַּרְכֵּֽ⁠נוּ׃","wa⁠yò֤̇sep ha⁠nȧ֨ʻar֙ la⁠ʻàn֣wòţ ʼeţ-şá̌ʼ֔ẇl wa⁠yò̇֕ʼmer hiné̇h֙ nimĕẕá֣ʼ bĕ⁠yádi֔⁠y re֖baʻ şě֣qel ká֑̇sep wĕ⁠náֽţaţi̇y֙ lĕ⁠ʼi֣yş̌ há⁠ʼèlòhi֔ym wĕ⁠higi֥̇yd lá֖⁠nẇ ʼeţ-dȧrĕkéֽ̇⁠nẇ׃"],[9,9,"לְ⁠פָנִ֣ים ׀ בְּ⁠יִשְׂרָאֵ֗ל כֹּֽה־אָמַ֤ר הָ⁠אִישׁ֙ בְּ⁠לֶכְתּ⁠וֹ֙ לִ⁠דְר֣וֹשׁ אֱלֹהִ֔ים לְכ֥וּ וְ⁠נֵלְכָ֖ה עַד־הָ⁠רֹאֶ֑ה כִּ֤י לַ⁠נָּבִיא֙ הַ⁠יּ֔וֹם יִקָּרֵ֥א לְ⁠פָנִ֖ים הָ⁠רֹאֶֽה׃","lĕ⁠páni֣ym ׀ bĕ̇⁠yişĕ̂ráʼé֗l kòֽ̇h-ʼáma֤r há⁠ʼiyş̌֙ bĕ̇⁠lekĕţ̇⁠wò֙ li⁠dĕr֣wòş̌ ʼèlòhi֔ym lĕk֥ẇ wĕ⁠nélĕká֖h ʻad-há⁠ròʼe֑h ki֤̇y la⁠ná̇biyʼ֙ ha⁠ẏ֔wòm yiqá̇ré֥ʼ lĕ⁠páni֖ym há⁠ròʼeֽh׃"],[9,10,"וַ⁠יֹּ֨אמֶר שָׁא֧וּל לְ⁠נַעֲר֛⁠וֹ ט֥וֹב דְּבָרְ⁠ךָ֖ לְכָ֣⁠ה ׀ נֵלֵ֑כָה וַ⁠יֵּֽלְכוּ֙ אֶל־הָ⁠עִ֔יר אֲשֶׁר־שָׁ֖ם אִ֥ישׁ הָ⁠אֱלֹהִֽים׃","wa⁠yò̇֨ʼmer şá̌ʼ֧ẇl lĕ⁠naʻàr֛⁠wò t֥wòb dĕ̇bárĕ⁠ká֖ lĕká֣⁠h ׀ nélé֑káh wa⁠yéֽ̇lĕkẇ֙ ʼel-há⁠ʻi֔yr ʼàşěr-şá֖̌m ʼi֥yş̌ há⁠ʼèlòhiֽym׃"],[9,11,"הֵ֗מָּה עֹלִים֙ בְּ⁠מַעֲלֵ֣ה הָ⁠עִ֔יר וְ⁠הֵ֨מָּה֙ מָצְא֣וּ נְעָר֔וֹת יֹצְא֖וֹת לִ⁠שְׁאֹ֣ב מָ֑יִם וַ⁠יֹּאמְר֣וּ לָ⁠הֶ֔ן הֲ⁠יֵ֥שׁ בָּ⁠זֶ֖ה הָ⁠רֹאֶֽה׃","hé֗má̇h ʻòliym֙ bĕ̇⁠maʻàlé֣h há⁠ʻi֔yr wĕ⁠hé֨má̇h֙ máẕĕʼ֣ẇ nĕʻár֔wòţ yòẕĕʼ֖wòţ li⁠şĕ̌ʼò֣b má֑yim wa⁠yò̇ʼmĕr֣ẇ lá⁠he֔n hà⁠yé֥ş̌ bá̇⁠ze֖h há⁠ròʼeֽh׃"],[9,12,"וַ⁠תַּעֲנֶ֧ינָה אוֹתָ֛⁠ם וַ⁠תֹּאמַ֥רְנָה יֵּ֖שׁ הִנֵּ֣ה לְ⁠פָנֶ֑י⁠ךָ מַהֵ֣ר ׀ עַתָּ֗ה כִּ֤י הַ⁠יּוֹם֙ בָּ֣א לָ⁠עִ֔יר כִּ֣י זֶ֧בַח הַ⁠יּ֛וֹם לָ⁠עָ֖ם בַּ⁠בָּמָֽה׃","wa⁠ţȧʻàne֧ynáh ʼwòţá֛⁠m wa⁠ţò̇ʼma֥rĕnáh yé֖̇ş̌ hiné֣̇h lĕ⁠páne֑y⁠ká mahé֣r ׀ ʻaţá̇֗h ki֤̇y ha⁠ẏwòm֙ bá֣̇ʼ lá⁠ʻi֔yr ki֣̇y ze֧baẖ ha⁠ẏ֛wòm lá⁠ʻá֖m bȧ⁠bá̇máֽh׃"],[9,13,"כְּ⁠בֹאֲ⁠כֶ֣ם הָ⁠עִ֣יר כֵּ֣ן תִּמְצְא֣וּ⁠ן אֹת֡⁠וֹ בְּ⁠טֶרֶם֩ יַעֲלֶ֨ה הַ⁠בָּמָ֜תָ⁠ה לֶ⁠אֱכֹ֗ל כִּ֠י לֹֽא־יֹאכַ֤ל הָ⁠עָם֙ עַד־בֹּא֔⁠וֹ כִּֽי־הוּא֙ יְבָרֵ֣ךְ הַ⁠זֶּ֔בַח אַחֲרֵי־כֵ֖ן יֹאכְל֣וּ הַ⁠קְּרֻאִ֑ים וְ⁠עַתָּ֣ה עֲל֔וּ כִּֽי־אֹת֥⁠וֹ כְ⁠הַ⁠יּ֖וֹם תִּמְצְא֥וּ⁠ן אֹתֽ⁠וֹ׃","kĕ̇⁠bòʼà⁠ke֣m há⁠ʻi֣yr ké֣̇n ţi̇mĕẕĕʼ֣ẇ⁠n ʼòţ֡⁠wò bĕ̇⁠terem֩ yaʻàle֨h ha⁠bá̇má֜ţá⁠h le⁠ʼèkò֗l ki̇֠y lòֽʼ-yòʼka֤l há⁠ʻám֙ ʻad-bò̇ʼ֔⁠wò kiֽ̇y-hẇʼ֙ yĕbáré֣kĕ ha⁠zė֔baẖ ʼaẖàréy-ké֖n yòʼkĕl֣ẇ ha⁠qĕ̇ruʼi֑ym wĕ⁠ʻaţá֣̇h ʻàl֔ẇ kiֽ̇y-ʼòţ֥⁠wò kĕ⁠ha⁠ẏ֖wòm ţi̇mĕẕĕʼ֥ẇ⁠n ʼòţֽ⁠wò׃"],[9,14,"וַֽ⁠יַּעֲל֖וּ הָ⁠עִ֑יר הֵ֗מָּה בָּאִים֙ בְּ⁠ת֣וֹךְ הָ⁠עִ֔יר וְ⁠הִנֵּ֤ה שְׁמוּאֵל֙ יֹצֵ֣א לִ⁠קְרָאתָ֔⁠ם לַ⁠עֲל֖וֹת הַ⁠בָּמָֽה׃ס","waֽ⁠yȧʻàl֖ẇ há⁠ʻi֑yr hé֗má̇h bá̇ʼiym֙ bĕ̇⁠ţ֣wòkĕ há⁠ʻi֔yr wĕ⁠hiné֤̇h şĕ̌mẇʼél֙ yòẕé֣ʼ li⁠qĕráʼţá֔⁠m la⁠ʻàl֖wòţ ha⁠bá̇máֽh׃s"],[9,15,"וַֽ⁠יהוָ֔ה גָּלָ֖ה אֶת־אֹ֣זֶן שְׁמוּאֵ֑ל י֣וֹם אֶחָ֔ד לִ⁠פְנֵ֥י בֽוֹא־שָׁא֖וּל לֵ⁠אמֹֽר׃","waֽ⁠yhwá֔h gá̇lá֖h ʼeţ-ʼò֣zen şĕ̌mẇʼé֑l y֣wòm ʼeẖá֔d li⁠pĕné֥y bֽwòʼ-şá̌ʼ֖ẇl lé⁠ʼmòֽr׃"],[9,16,"כָּ⁠עֵ֣ת ׀ מָחָ֡ר אֶשְׁלַח֩ אֵלֶ֨י⁠ךָ אִ֜ישׁ מֵ⁠אֶ֣רֶץ בִּנְיָמִ֗ן וּ⁠מְשַׁחְתּ֤⁠וֹ לְ⁠נָגִיד֙ עַל־עַמִּ֣⁠י יִשְׂרָאֵ֔ל וְ⁠הוֹשִׁ֥יעַ אֶת־עַמִּ֖⁠י מִ⁠יַּ֣ד פְּלִשְׁתִּ֑ים כִּ֤י רָאִ֨יתִי֙ אֶת־עַמִּ֔⁠י כִּ֛י בָּ֥אָה צַעֲקָת֖⁠וֹ אֵלָֽ⁠י׃","ká̇⁠ʻé֣ţ ׀ máẖá֡r ʼeşĕ̌laẖ֩ ʼéle֨y⁠ká ʼi֜yş̌ mé⁠ʼe֣reẕ bi̇nĕyámi֗n ẇ⁠mĕşǎẖĕţ֤̇⁠wò lĕ⁠nágiyd֙ ʻal-ʻami֣̇⁠y yişĕ̂ráʼé֔l wĕ⁠hwòşǐ֥yʻa ʼeţ-ʻami֖̇⁠y mi⁠yȧ֣d pĕ̇lişĕ̌ţi֑̇ym ki֤̇y ráʼi֨yţiy֙ ʼeţ-ʻami̇֔⁠y ki֛̇y bá֥̇ʼáh ẕaʻàqáţ֖⁠wò ʼéláֽ⁠y׃"],[9,17,"וּ⁠שְׁמוּאֵ֖ל רָאָ֣ה אֶת־שָׁא֑וּל וַ⁠יהוָ֣ה עָנָ֔⁠הוּ הִנֵּ֤ה הָ⁠אִישׁ֙ אֲשֶׁ֣ר אָמַ֣רְתִּי אֵלֶ֔י⁠ךָ זֶ֖ה יַעְצֹ֥ר בְּ⁠עַמִּֽ⁠י׃","ẇ⁠şĕ̌mẇʼé֖l ráʼá֣h ʼeţ-şá̌ʼ֑ẇl wa⁠yhwá֣h ʻáná֔⁠hẇ hiné֤̇h há⁠ʼiyş̌֙ ʼàşě֣r ʼáma֣rĕţi̇y ʼéle֔y⁠ká ze֖h yaʻĕẕò֥r bĕ̇⁠ʻamiֽ̇⁠y׃"],[9,18,"וַ⁠יִּגַּ֥שׁ שָׁא֛וּל אֶת־שְׁמוּאֵ֖ל בְּ⁠ת֣וֹךְ הַ⁠שָּׁ֑עַר וַ⁠יֹּ֨אמֶר֙ הַגִּֽידָ⁠ה־נָּ֣א לִ֔⁠י אֵי־זֶ֖ה בֵּ֥ית הָ⁠רֹאֶֽה׃","wa⁠yi̇gȧ֥ş̌ şá̌ʼ֛ẇl ʼeţ-şĕ̌mẇʼé֖l bĕ̇⁠ţ֣wòkĕ ha⁠şá֑̇̌ʻar wa⁠yò̇֨ʼmer֙ hagiֽ̇ydá⁠h-ná֣̇ʼ li֔⁠y ʼéy-ze֖h bé֥̇yţ há⁠ròʼeֽh׃"],[9,19,"וַ⁠יַּ֨עַן שְׁמוּאֵ֜ל אֶת־שָׁא֗וּל וַ⁠יֹּ֨אמֶר֙ אָנֹכִ֣י הָ⁠רֹאֶ֔ה עֲלֵ֤ה לְ⁠פָנַ⁠י֙ הַ⁠בָּמָ֔ה וַ⁠אֲכַלְתֶּ֥ם עִמִּ֖⁠י הַ⁠יּ֑וֹם וְ⁠שִׁלַּחְתִּ֣י⁠ךָ בַ⁠בֹּ֔קֶר וְ⁠כֹ֛ל אֲשֶׁ֥ר בִּֽ⁠לְבָבְ⁠ךָ֖ אַגִּ֥יד לָֽ⁠ךְ׃","wa⁠yȧ֨ʻan şĕ̌mẇʼé֜l ʼeţ-şá̌ʼ֗ẇl wa⁠yò̇֨ʼmer֙ ʼánòki֣y há⁠ròʼe֔h ʻàlé֤h lĕ⁠pána⁠y֙ ha⁠bá̇má֔h wa⁠ʼàkalĕţė֥m ʻimi֖̇⁠y ha⁠ẏ֑wòm wĕ⁠şǐlȧẖĕţi֣̇y⁠ká ba⁠bò̇֔qer wĕ⁠kò֛l ʼàşě֥r biֽ̇⁠lĕbábĕ⁠ká֖ ʼagi֥̇yd láֽ⁠kĕ׃"],[9,20,"וְ⁠לָ⁠אֲתֹנ֞וֹת הָ⁠אֹבְד֣וֹת לְ⁠ךָ֗ הַ⁠יּוֹם֙ שְׁלֹ֣שֶׁת הַ⁠יָּמִ֔ים אַל־תָּ֧שֶׂם אֶֽת־לִבְּ⁠ךָ֛ לָ⁠הֶ֖ם כִּ֣י נִמְצָ֑אוּ וּ⁠לְ⁠מִי֙ כָּל־חֶמְדַּ֣ת יִשְׂרָאֵ֔ל הֲ⁠ל֣וֹא לְ⁠ךָ֔ וּ⁠לְ⁠כֹ֖ל בֵּ֥ית אָבִֽי⁠ךָ׃ס","wĕ⁠lá⁠ʼàţòn֞wòţ há⁠ʼòbĕd֣wòţ lĕ⁠ká֗ ha⁠ẏwòm֙ şĕ̌lò֣şěţ ha⁠yá̇mi֔ym ʼal-ţá֧̇şêm ʼeֽţ-libĕ̇⁠ká֛ lá⁠he֖m ki֣̇y nimĕẕá֑ʼẇ ẇ⁠lĕ⁠miy֙ ká̇l-ẖemĕdȧ֣ţ yişĕ̂ráʼé֔l hà⁠l֣wòʼ lĕ⁠ká֔ ẇ⁠lĕ⁠kò֖l bé֥̇yţ ʼábiֽy⁠ká׃s"],[9,21,"וַ⁠יַּ֨עַן שָׁא֜וּל וַ⁠יֹּ֗אמֶר הֲ⁠ל֨וֹא בֶן־יְמִינִ֤י אָ֨נֹכִי֙ מִ⁠קַּטַנֵּי֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל וּ⁠מִשְׁפַּחְתִּ⁠י֙ הַ⁠צְּעִרָ֔ה מִ⁠כָּֽל־מִשְׁפְּח֖וֹת שִׁבְטֵ֣י בִנְיָמִ֑ן וְ⁠לָ֨⁠מָּה֙ דִּבַּ֣רְתָּ אֵלַ֔⁠י כַּ⁠דָּבָ֖ר הַ⁠זֶּֽה׃ס","wa⁠yȧ֨ʻan şá̌ʼ֜ẇl wa⁠yò̇֗ʼmer hà⁠l֨wòʼ ben-yĕmiyni֤y ʼá֨nòkiy֙ mi⁠qȧtané̇y֙ şǐbĕté֣y yişĕ̂ráʼé֔l ẇ⁠mişĕ̌pȧẖĕţi̇⁠y֙ ha⁠ẕĕ̇ʻirá֔h mi⁠káֽ̇l-mişĕ̌pĕ̇ẖ֖wòţ şǐbĕté֣y binĕyámi֑n wĕ⁠lá֨⁠má̇h֙ di̇bȧ֣rĕţá̇ ʼéla֔⁠y kȧ⁠dá̇bá֖r ha⁠zėֽh׃s"],[9,22,"וַ⁠יִּקַּ֤ח שְׁמוּאֵל֙ אֶת־שָׁא֣וּל וְ⁠אֶֽת־נַעֲר֔⁠וֹ וַ⁠יְבִיאֵ֖⁠ם לִשְׁכָּ֑תָ⁠ה וַ⁠יִּתֵּ֨ן לָ⁠הֶ֤ם מָקוֹם֙ בְּ⁠רֹ֣אשׁ הַ⁠קְּרוּאִ֔ים וְ⁠הֵ֖מָּה כִּ⁠שְׁלֹשִׁ֥ים אִֽישׁ׃","wa⁠yi̇qȧ֤ẖ şĕ̌mẇʼél֙ ʼeţ-şá̌ʼ֣ẇl wĕ⁠ʼeֽţ-naʻàr֔⁠wò wa⁠yĕbiyʼé֖⁠m lişĕ̌ká֑̇ţá⁠h wa⁠yi̇ţé̇֨n lá⁠he֤m máqwòm֙ bĕ̇⁠rò֣ʼş̌ ha⁠qĕ̇rẇʼi֔ym wĕ⁠hé֖má̇h ki̇⁠şĕ̌lòşǐ֥ym ʼiֽyş̌׃"],[9,23,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ לַ⁠טַּבָּ֔ח תְּנָ⁠ה֙ אֶת־הַ⁠מָּנָ֔ה אֲשֶׁ֥ר נָתַ֖תִּי לָ֑⁠ךְ אֲשֶׁר֙ אָמַ֣רְתִּי אֵלֶ֔י⁠ךָ שִׂ֥ים אֹתָ֖⁠הּ עִמָּֽ⁠ךְ׃","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ la⁠tȧbá̇֔ẖ ţĕ̇ná⁠h֙ ʼeţ-ha⁠má̇ná֔h ʼàşě֥r náţa֖ţi̇y lá֑⁠kĕ ʼàşěr֙ ʼáma֣rĕţi̇y ʼéle֔y⁠ká şî֥ym ʼòţá֖⁠ḣ ʻimáֽ̇⁠kĕ׃"],[9,24,"וַ⁠יָּ֣רֶם הַ֠⁠טַּבָּח אֶת־הַ⁠שּׁ֨וֹק וְ⁠הֶ⁠עָלֶ֜י⁠הָ וַ⁠יָּ֣שֶׂם ׀ לִ⁠פְנֵ֣י שָׁא֗וּל וַ⁠יֹּ֨אמֶר֙ הִנֵּ֤ה הַ⁠נִּשְׁאָר֙ שִׂים־לְ⁠פָנֶ֣י⁠ךָ אֱכֹ֔ל כִּ֧י לַ⁠מּוֹעֵ֛ד שָֽׁמוּר־לְ⁠ךָ֥ לֵ⁠אמֹ֖ר הָ⁠עָ֣ם ׀ קָרָ֑אתִי וַ⁠יֹּ֧אכַל שָׁא֛וּל עִם־שְׁמוּאֵ֖ל בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","wa⁠yá֣̇rem ha֠⁠tȧbá̇ẖ ʼeţ-ha⁠ş̇̌֨wòq wĕ⁠he⁠ʻále֜y⁠há wa⁠yá֣̇şêm ׀ li⁠pĕné֣y şá̌ʼ֗ẇl wa⁠yò̇֨ʼmer֙ hiné֤̇h ha⁠ni̇şĕ̌ʼár֙ şîym-lĕ⁠páne֣y⁠ká ʼèkò֔l ki֧̇y la⁠ṁwòʻé֛d şáֽ̌mẇr-lĕ⁠ká֥ lé⁠ʼmò֖r há⁠ʻá֣m ׀ qárá֑ʼţiy wa⁠yò֧̇ʼkal şá̌ʼ֛ẇl ʻim-şĕ̌mẇʼé֖l bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"],[9,25,"וַ⁠יֵּרְד֥וּ מֵ⁠הַ⁠בָּמָ֖ה הָ⁠עִ֑יר וַ⁠יְדַבֵּ֥ר עִם־שָׁא֖וּל עַל־הַ⁠גָּֽג׃","wa⁠yé̇rĕd֥ẇ mé⁠ha⁠bá̇má֖h há⁠ʻi֑yr wa⁠yĕdabé֥̇r ʻim-şá̌ʼ֖ẇl ʻal-ha⁠gáֽ̇g׃"],[9,26,"וַ⁠יַּשְׁכִּ֗מוּ וַ⁠יְהִ֞י כַּ⁠עֲל֤וֹת הַ⁠שַּׁ֨חַר֙ וַ⁠יִּקְרָ֨א שְׁמוּאֵ֤ל אֶל־שָׁאוּל֙ ה⁠גג לֵ⁠אמֹ֔ר ק֖וּמָ⁠ה וַ⁠אֲשַׁלְּחֶ֑⁠ךָּ וַ⁠יָּ֣קָם שָׁא֗וּל וַ⁠יֵּצְא֧וּ שְׁנֵי⁠הֶ֛ם ה֥וּא וּ⁠שְׁמוּאֵ֖ל הַ⁠חֽוּצָ⁠ה׃","wa⁠yȧşĕ̌ki̇֗mẇ wa⁠yĕhi֞y kȧ⁠ʻàl֤wòţ ha⁠şȧ̌֨ẖar֙ wa⁠yi̇qĕrá֨ʼ şĕ̌mẇʼé֤l ʼel-şá̌ʼẇl֙ h⁠gg lé⁠ʼmò֔r q֖ẇmá⁠h wa⁠ʼàşǎlĕ̇ẖe֑⁠ká̇ wa⁠yá֣̇qám şá̌ʼ֗ẇl wa⁠yé̇ẕĕʼ֧ẇ şĕ̌néy⁠he֛m h֥ẇʼ ẇ⁠şĕ̌mẇʼé֖l ha⁠ẖֽẇẕá⁠h׃"],[9,27,"הֵ֗מָּה יֽוֹרְדִים֙ בִּ⁠קְצֵ֣ה הָ⁠עִ֔יר וּ⁠שְׁמוּאֵ֞ל אָמַ֣ר אֶל־שָׁא֗וּל אֱמֹ֥ר לַ⁠נַּ֛עַר וְ⁠יַעֲבֹ֥ר לְ⁠פָנֵ֖י⁠נוּ וַֽ⁠יַּעֲבֹ֑ר וְ⁠אַתָּה֙ עֲמֹ֣ד כַּ⁠יּ֔וֹם וְ⁠אַשְׁמִיעֲ⁠ךָ֖ אֶת־דְּבַ֥ר אֱלֹהִֽים׃פ","hé֗má̇h yֽwòrĕdiym֙ bi̇⁠qĕẕé֣h há⁠ʻi֔yr ẇ⁠şĕ̌mẇʼé֞l ʼáma֣r ʼel-şá̌ʼ֗ẇl ʼèmò֥r la⁠nȧ֛ʻar wĕ⁠yaʻàbò֥r lĕ⁠páné֖y⁠nẇ waֽ⁠yȧʻàbò֑r wĕ⁠ʼaţá̇h֙ ʻàmò֣d kȧ⁠ẏ֔wòm wĕ⁠ʼaşĕ̌miyʻà⁠ká֖ ʼeţ-dĕ̇ba֥r ʼèlòhiֽym׃p"],[10,1,"וַ⁠יִּקַּ֨ח שְׁמוּאֵ֜ל אֶת־פַּ֥ךְ הַ⁠שֶּׁ֛מֶן וַ⁠יִּצֹ֥ק עַל־רֹאשׁ֖⁠וֹ וַ⁠יִּשָּׁקֵ֑⁠הוּ וַ⁠יֹּ֕אמֶר הֲ⁠ל֗וֹא כִּֽי־מְשָׁחֲ⁠ךָ֧ יְהוָ֛ה עַל־נַחֲלָת֖⁠וֹ לְ⁠נָגִֽיד׃","wa⁠yi̇qȧ֨ẖ şĕ̌mẇʼé֜l ʼeţ-pȧ֥kĕ ha⁠şė֛̌men wa⁠yi̇ẕò֥q ʻal-ròʼş֖̌⁠wò wa⁠yi̇şá̇̌qé֑⁠hẇ wa⁠yò̇֕ʼmer hà⁠l֗wòʼ kiֽ̇y-mĕşá̌ẖà⁠ká֧ yĕhwá֛h ʻal-naẖàláţ֖⁠wò lĕ⁠nágiֽyd׃"],[10,2,"בְּ⁠לֶכְתְּ⁠ךָ֤ הַ⁠יּוֹם֙ מֵ⁠עִמָּדִ֔⁠י וּ⁠מָצָאתָ֩ שְׁנֵ֨י אֲנָשִׁ֜ים עִם־קְבֻרַ֥ת רָחֵ֛ל בִּ⁠גְב֥וּל בִּנְיָמִ֖ן בְּ⁠צֶלְצַ֑ח וְ⁠אָמְר֣וּ אֵלֶ֗י⁠ךָ נִמְצְא֤וּ הָ⁠אֲתֹנוֹת֙ אֲשֶׁ֣ר הָלַ֣כְתָּ לְ⁠בַקֵּ֔שׁ וְ⁠הִנֵּ֨ה נָטַ֤שׁ אָבִ֨י⁠ךָ֙ אֶת־דִּבְרֵ֣י הָ⁠אֲתֹנ֔וֹת וְ⁠דָאַ֤ג לָ⁠כֶם֙ לֵ⁠אמֹ֔ר מָ֥ה אֶעֱשֶׂ֖ה לִ⁠בְנִֽ⁠י׃","bĕ̇⁠lekĕţĕ̇⁠ká֤ ha⁠ẏwòm֙ mé⁠ʻimá̇di֔⁠y ẇ⁠máẕáʼţá֩ şĕ̌né֨y ʼànáşǐ֜ym ʻim-qĕbura֥ţ ráẖé֛l bi̇⁠gĕb֥ẇl bi̇nĕyámi֖n bĕ̇⁠ẕelĕẕa֑ẖ wĕ⁠ʼámĕr֣ẇ ʼéle֗y⁠ká nimĕẕĕʼ֤ẇ há⁠ʼàţònwòţ֙ ʼàşě֣r hála֣kĕţá̇ lĕ⁠baqé̇֔ş̌ wĕ⁠hiné̇֨h náta֤ş̌ ʼábi֨y⁠ká֙ ʼeţ-di̇bĕré֣y há⁠ʼàţòn֔wòţ wĕ⁠dáʼa֤g lá⁠kem֙ lé⁠ʼmò֔r má֥h ʼeʻèşê֖h li⁠bĕniֽ⁠y׃"],[10,3,"וְ⁠חָלַפְתָּ֨ מִ⁠שָּׁ֜ם וָ⁠הָ֗לְאָה וּ⁠בָ֨אתָ֙ עַד־אֵל֣וֹן תָּב֔וֹר וּ⁠מְצָא֤וּ⁠ךָ שָּׁם֙ שְׁלֹשָׁ֣ה אֲנָשִׁ֔ים עֹלִ֥ים אֶל־הָ⁠אֱלֹהִ֖ים בֵּֽית־אֵ֑ל אֶחָ֞ד נֹשֵׂ֣א ׀ שְׁלֹשָׁ֣ה גְדָיִ֗ים וְ⁠אֶחָד֙ נֹשֵׂ֗א שְׁלֹ֨שֶׁת֙ כִּכְּר֣וֹת לֶ֔חֶם וְ⁠אֶחָ֥ד נֹשֵׂ֖א נֵֽבֶל־יָֽיִן׃","wĕ⁠ẖálapĕţá̇֨ mi⁠şá̇̌֜m wá⁠há֗lĕʼáh ẇ⁠bá֨ʼţá֙ ʻad-ʼél֣wòn ţá̇b֔wòr ẇ⁠mĕẕáʼ֤ẇ⁠ká şá̇̌m֙ şĕ̌lòşá֣̌h ʼànáşǐ֔ym ʻòli֥ym ʼel-há⁠ʼèlòhi֖ym béֽ̇yţ-ʼé֑l ʼeẖá֞d nòşé֣̂ʼ ׀ şĕ̌lòşá֣̌h gĕdáyi֗ym wĕ⁠ʼeẖád֙ nòşé̂֗ʼ şĕ̌lò֨şěţ֙ ki̇kĕ̇r֣wòţ le֔ẖem wĕ⁠ʼeẖá֥d nòşé֖̂ʼ néֽbel-yáֽyin׃"],[10,4,"וְ⁠שָׁאֲל֥וּ לְ⁠ךָ֖ לְ⁠שָׁל֑וֹם וְ⁠נָתְנ֤וּ לְ⁠ךָ֙ שְׁתֵּי־לֶ֔חֶם וְ⁠לָקַחְתָּ֖ מִ⁠יָּדָֽ⁠ם׃","wĕ⁠şá̌ʼàl֥ẇ lĕ⁠ká֖ lĕ⁠şá̌l֑wòm wĕ⁠náţĕn֤ẇ lĕ⁠ká֙ şĕ̌ţé̇y-le֔ẖem wĕ⁠láqaẖĕţá֖̇ mi⁠yá̇dáֽ⁠m׃"],[10,5,"אַ֣חַר כֵּ֗ן תָּבוֹא֙ גִּבְעַ֣ת הָ⁠אֱלֹהִ֔ים אֲשֶׁר־שָׁ֖ם נְצִבֵ֣י פְלִשְׁתִּ֑ים וִ⁠יהִי֩ כְ⁠בֹאֲ⁠ךָ֨ שָׁ֜ם הָ⁠עִ֗יר וּ⁠פָגַעְתָּ֞ חֶ֤בֶל נְבִיאִים֙ יֹרְדִ֣ים מֵֽ⁠הַ⁠בָּמָ֔ה וְ⁠לִ⁠פְנֵי⁠הֶ֞ם נֵ֤בֶל וְ⁠תֹף֙ וְ⁠חָלִ֣יל וְ⁠כִנּ֔וֹר וְ⁠הֵ֖מָּה מִֽתְנַבְּאִֽים׃","ʼa֣ẖar ké̇֗n ţá̇bwòʼ֙ gi̇bĕʻa֣ţ há⁠ʼèlòhi֔ym ʼàşěr-şá֖̌m nĕẕibé֣y pĕlişĕ̌ţi֑̇ym wi⁠yhiy֩ kĕ⁠bòʼà⁠ká֨ şá̌֜m há⁠ʻi֗yr ẇ⁠págaʻĕţá̇֞ ẖe֤bel nĕbiyʼiym֙ yòrĕdi֣ym méֽ⁠ha⁠bá̇má֔h wĕ⁠li⁠pĕnéy⁠he֞m né֤bel wĕ⁠ţòp֙ wĕ⁠ẖáli֣yl wĕ⁠kiṅ֔wòr wĕ⁠hé֖má̇h miֽţĕnabĕ̇ʼiֽym׃"],[10,6,"וְ⁠צָלְחָ֤ה עָלֶ֨י⁠ךָ֙ ר֣וּחַ יְהוָ֔ה וְ⁠הִתְנַבִּ֖יתָ עִמָּ֑⁠ם וְ⁠נֶהְפַּכְתָּ֖ לְ⁠אִ֥ישׁ אַחֵֽר׃","wĕ⁠ẕálĕẖá֤h ʻále֨y⁠ká֙ r֣ẇẖa yĕhwá֔h wĕ⁠hiţĕnabi֖̇yţá ʻimá֑̇⁠m wĕ⁠nehĕpȧkĕţá֖̇ lĕ⁠ʼi֥yş̌ ʼaẖéֽr׃"],[10,7,"וְ⁠הָיָ֗ה כִּ֥י תבאינה הָ⁠אֹת֥וֹת הָ⁠אֵ֖לֶּה לָ֑⁠ךְ עֲשֵׂ֤ה לְ⁠ךָ֙ אֲשֶׁ֣ר תִּמְצָ֣א יָדֶ֔⁠ךָ כִּ֥י הָ⁠אֱלֹהִ֖ים עִמָּֽ⁠ךְ׃","wĕ⁠háyá֗h ki֥̇y ţbʼynh há⁠ʼòţ֥wòţ há⁠ʼé֖lėh lá֑⁠kĕ ʻàşé֤̂h lĕ⁠ká֙ ʼàşě֣r ţi̇mĕẕá֣ʼ yáde֔⁠ká ki֥̇y há⁠ʼèlòhi֖ym ʻimáֽ̇⁠kĕ׃"],[10,8,"וְ⁠יָרַדְתָּ֣ לְ⁠פָנַ⁠י֮ הַ⁠גִּלְגָּל֒ וְ⁠הִנֵּ֤ה אָֽנֹכִי֙ יֹרֵ֣ד אֵלֶ֔י⁠ךָ לְ⁠הַעֲל֣וֹת עֹל֔וֹת לִ⁠זְבֹּ֖חַ זִבְחֵ֣י שְׁלָמִ֑ים שִׁבְעַ֨ת יָמִ֤ים תּוֹחֵל֙ עַד־בּוֹאִ֣⁠י אֵלֶ֔י⁠ךָ וְ⁠הוֹדַעְתִּ֣י לְ⁠ךָ֔ אֵ֖ת אֲשֶׁ֥ר תַּעֲשֶֽׂה׃","wĕ⁠yáradĕţá֣̇ lĕ⁠pána⁠y֮ ha⁠gi̇lĕgá̇l֒ wĕ⁠hiné֤̇h ʼáֽnòkiy֙ yòré֣d ʼéle֔y⁠ká lĕ⁠haʻàl֣wòţ ʻòl֔wòţ li⁠zĕbò֖̇ẖa zibĕẖé֣y şĕ̌lámi֑ym şǐbĕʻa֨ţ yámi֤ym ţ̇wòẖél֙ ʻad-ḃwòʼi֣⁠y ʼéle֔y⁠ká wĕ⁠hwòdaʻĕţi֣̇y lĕ⁠ká֔ ʼé֖ţ ʼàşě֥r ţȧʻàşêֽh׃"],[10,9,"וְ⁠הָיָ֗ה כְּ⁠הַפְנֹת֤⁠וֹ שִׁכְמ⁠וֹ֙ לָ⁠לֶ֨כֶת֙ מֵ⁠עִ֣ם שְׁמוּאֵ֔ל וַ⁠יַּהֲפָךְ־ל֥⁠וֹ אֱלֹהִ֖ים לֵ֣ב אַחֵ֑ר וַ⁠יָּבֹ֛אוּ כָּל־הָ⁠אֹת֥וֹת הָ⁠אֵ֖לֶּה בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃ס","wĕ⁠háyá֗h kĕ̇⁠hapĕnòţ֤⁠wò şǐkĕm⁠wò֙ lá⁠le֨keţ֙ mé⁠ʻi֣m şĕ̌mẇʼé֔l wa⁠yȧhàpákĕ-l֥⁠wò ʼèlòhi֖ym lé֣b ʼaẖé֑r wa⁠yá̇bò֛ʼẇ ká̇l-há⁠ʼòţ֥wòţ há⁠ʼé֖lėh bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃s"],[10,10,"וַ⁠יָּבֹ֤אוּ שָׁם֙ הַ⁠גִּבְעָ֔תָ⁠ה וְ⁠הִנֵּ֥ה חֶֽבֶל־נְבִאִ֖ים לִ⁠קְרָאת֑⁠וֹ וַ⁠תִּצְלַ֤ח עָלָי⁠ו֙ ר֣וּחַ אֱלֹהִ֔ים וַ⁠יִּתְנַבֵּ֖א בְּ⁠תוֹכָֽ⁠ם׃","wa⁠yá̇bò֤ʼẇ şá̌m֙ ha⁠gi̇bĕʻá֔ţá⁠h wĕ⁠hiné֥̇h ẖeֽbel-nĕbiʼi֖ym li⁠qĕráʼţ֑⁠wò wa⁠ţi̇ẕĕla֤ẖ ʻáláy⁠w֙ r֣ẇẖa ʼèlòhi֔ym wa⁠yi̇ţĕnabé֖̇ʼ bĕ̇⁠ţwòkáֽ⁠m׃"],[10,11,"וַ⁠יְהִ֗י כָּל־יֽוֹדְע⁠וֹ֙ מֵ⁠אִתְּמ֣וֹל שִׁלְשׁ֔וֹם וַ⁠יִּרְא֕וּ וְ⁠הִנֵּ֥ה עִם־נְבִאִ֖ים נִבָּ֑א וַ⁠יֹּ֨אמֶר הָ⁠עָ֜ם אִ֣ישׁ אֶל־רֵעֵ֗⁠הוּ מַה־זֶּה֙ הָיָ֣ה לְ⁠בֶן־קִ֔ישׁ הֲ⁠גַ֥ם שָׁא֖וּל בַּ⁠נְּבִיאִֽים׃","wa⁠yĕhi֗y ká̇l-yֽwòdĕʻ⁠wò֙ mé⁠ʼiţĕ̇m֣wòl şǐlĕş̌֔wòm wa⁠yi̇rĕʼ֕ẇ wĕ⁠hiné֥̇h ʻim-nĕbiʼi֖ym nibá֑̇ʼ wa⁠yò̇֨ʼmer há⁠ʻá֜m ʼi֣yş̌ ʼel-réʻé֗⁠hẇ mah-zėh֙ háyá֣h lĕ⁠ben-qi֔yş̌ hà⁠ga֥m şá̌ʼ֖ẇl bȧ⁠nĕ̇biyʼiֽym׃"],[10,12,"וַ⁠יַּ֨עַן אִ֥ישׁ מִ⁠שָּׁ֛ם וַ⁠יֹּ֖אמֶר וּ⁠מִ֣י אֲבִי⁠הֶ֑ם עַל־כֵּן֙ הָיְתָ֣ה לְ⁠מָשָׁ֔ל הֲ⁠גַ֥ם שָׁא֖וּל בַּ⁠נְּבִאִֽים׃","wa⁠yȧ֨ʻan ʼi֥yş̌ mi⁠şá֛̇̌m wa⁠yò֖̇ʼmer ẇ⁠mi֣y ʼàbiy⁠he֑m ʻal-ké̇n֙ háyĕţá֣h lĕ⁠máşá̌֔l hà⁠ga֥m şá̌ʼ֖ẇl bȧ⁠nĕ̇biʼiֽym׃"],[10,13,"וַ⁠יְכַל֙ מֵֽ⁠הִתְנַבּ֔וֹת וַ⁠יָּבֹ֖א הַ⁠בָּמָֽה׃","wa⁠yĕkal֙ méֽ⁠hiţĕnaḃ֔wòţ wa⁠yá̇bò֖ʼ ha⁠bá̇máֽh׃"],[10,14,"וַ⁠יֹּאמֶר֩ דּ֨וֹד שָׁא֥וּל אֵלָ֛י⁠ו וְ⁠אֶֽל־נַעֲר֖⁠וֹ אָ֣ן הֲלַכְתֶּ֑ם וַ⁠יֹּ֕אמֶר לְ⁠בַקֵּשׁ֙ אֶת־הָ֣⁠אֲתֹנ֔וֹת וַ⁠נִּרְאֶ֣ה כִי־אַ֔יִן וַ⁠נָּב֖וֹא אֶל־שְׁמוּאֵֽל׃","wa⁠yò̇ʼmer֩ ḋ֨wòd şá̌ʼ֥ẇl ʼélá֛y⁠w wĕ⁠ʼeֽl-naʻàr֖⁠wò ʼá֣n hàlakĕţė֑m wa⁠yò̇֕ʼmer lĕ⁠baqé̇ş̌֙ ʼeţ-há֣⁠ʼàţòn֔wòţ wa⁠ni̇rĕʼe֣h kiy-ʼa֔yin wa⁠ná̇b֖wòʼ ʼel-şĕ̌mẇʼéֽl׃"],[10,15,"וַ⁠יֹּ֖אמֶר דּ֣וֹד שָׁא֑וּל הַגִּֽידָ⁠ה־נָּ֣א לִ֔⁠י מָֽה־אָמַ֥ר לָ⁠כֶ֖ם שְׁמוּאֵֽל׃","wa⁠yò֖̇ʼmer ḋ֣wòd şá̌ʼ֑ẇl hagiֽ̇ydá⁠h-ná֣̇ʼ li֔⁠y máֽh-ʼáma֥r lá⁠ke֖m şĕ̌mẇʼéֽl׃"],[10,16,"וַ⁠יֹּ֤אמֶר שָׁאוּל֙ אֶל־דּוֹד֔⁠וֹ הַגֵּ֤ד הִגִּיד֙ לָ֔⁠נוּ כִּ֥י נִמְצְא֖וּ הָ⁠אֲתֹנ֑וֹת וְ⁠אֶת־דְּבַ֤ר הַ⁠מְּלוּכָה֙ לֹֽא־הִגִּ֣יד ל֔⁠וֹ אֲשֶׁ֖ר אָמַ֥ר שְׁמוּאֵֽל׃פ","wa⁠yò֤̇ʼmer şá̌ʼẇl֙ ʼel-ḋwòd֔⁠wò hagé֤̇d higi̇yd֙ lá֔⁠nẇ ki֥̇y nimĕẕĕʼ֖ẇ há⁠ʼàţòn֑wòţ wĕ⁠ʼeţ-dĕ̇ba֤r ha⁠mĕ̇lẇkáh֙ lòֽʼ-higi֣̇yd l֔⁠wò ʼàşě֖r ʼáma֥r şĕ̌mẇʼéֽl׃p"],[10,17,"וַ⁠יַּצְעֵ֤ק שְׁמוּאֵל֙ אֶת־הָ⁠עָ֔ם אֶל־יְהוָ֖ה הַ⁠מִּצְפָּֽה׃","wa⁠yȧẕĕʻé֤q şĕ̌mẇʼél֙ ʼeţ-há⁠ʻá֔m ʼel-yĕhwá֖h ha⁠mi̇ẕĕpáֽ̇h׃"],[10,18,"וַ⁠יֹּ֣אמֶר ׀ אֶל־בְּנֵ֣י יִשְׂרָאֵ֗ל פ כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אָנֹכִ֛י הֶעֱלֵ֥יתִי אֶת־יִשְׂרָאֵ֖ל מִ⁠מִּצְרָ֑יִם וָ⁠אַצִּ֤יל אֶתְ⁠כֶם֙ מִ⁠יַּ֣ד מִצְרַ֔יִם וּ⁠מִ⁠יַּד֙ כָּל־הַ⁠מַּמְלָכ֔וֹת הַ⁠לֹּחֲצִ֖ים אֶתְ⁠כֶֽם׃","wa⁠yò֣̇ʼmer ׀ ʼel-bĕ̇né֣y yişĕ̂ráʼé֗l p kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼánòki֛y heʻèlé֥yţiy ʼeţ-yişĕ̂ráʼé֖l mi⁠mi̇ẕĕrá֑yim wá⁠ʼaẕi֤̇yl ʼeţĕ⁠kem֙ mi⁠yȧ֣d miẕĕra֔yim ẇ⁠mi⁠yȧd֙ ká̇l-ha⁠mȧmĕlák֔wòţ ha⁠lò̇ẖàẕi֖ym ʼeţĕ⁠keֽm׃"],[10,19,"וְ⁠אַתֶּ֨ם הַ⁠יּ֜וֹם מְאַסְתֶּ֣ם אֶת־אֱלֹהֵי⁠כֶ֗ם אֲשֶׁר־ה֣וּא מוֹשִׁ֣יעַ לָ⁠כֶם֮ מִ⁠כָּל־רָעוֹתֵי⁠כֶ֣ם וְ⁠צָרֹֽתֵי⁠כֶם֒ וַ⁠תֹּ֣אמְרוּ ל֔⁠וֹ כִּי־מֶ֖לֶךְ תָּשִׂ֣ים עָלֵ֑י⁠נוּ וְ⁠עַתָּ֗ה הִֽתְיַצְּבוּ֙ לִ⁠פְנֵ֣י יְהוָ֔ה לְ⁠שִׁבְטֵי⁠כֶ֖ם וּ⁠לְ⁠אַלְפֵי⁠כֶֽם׃","wĕ⁠ʼaţė֨m ha⁠ẏ֜wòm mĕʼasĕţė֣m ʼeţ-ʼèlòhéy⁠ke֗m ʼàşěr-h֣ẇʼ mwòşǐ֣yʻa lá⁠kem֮ mi⁠ká̇l-ráʻwòţéy⁠ke֣m wĕ⁠ẕáròֽţéy⁠kem֒ wa⁠ţò֣̇ʼmĕrẇ l֔⁠wò ki̇y-me֖lekĕ ţá̇şî֣ym ʻálé֑y⁠nẇ wĕ⁠ʻaţá̇֗h hiֽţĕyaẕĕ̇bẇ֙ li⁠pĕné֣y yĕhwá֔h lĕ⁠şǐbĕtéy⁠ke֖m ẇ⁠lĕ⁠ʼalĕpéy⁠keֽm׃"],[10,20,"וַ⁠יַּקְרֵ֣ב שְׁמוּאֵ֔ל אֵ֖ת כָּל־שִׁבְטֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּלָּכֵ֖ד שֵׁ֥בֶט בִּנְיָמִֽן׃","wa⁠yȧqĕré֣b şĕ̌mẇʼé֔l ʼé֖ţ ká̇l-şǐbĕté֣y yişĕ̂ráʼé֑l wa⁠yi̇lá̇ké֖d şé֥̌bet bi̇nĕyámiֽn׃"],[10,21,"וַ⁠יַּקְרֵ֞ב אֶת־שֵׁ֤בֶט בִּנְיָמִן֙ ל⁠משפחת⁠ו וַ⁠תִּלָּכֵ֖ד מִשְׁפַּ֣חַת הַ⁠מַּטְרִ֑י וַ⁠יִּלָּכֵד֙ שָׁא֣וּל בֶּן־קִ֔ישׁ וַ⁠יְבַקְשֻׁ֖⁠הוּ וְ⁠לֹ֥א נִמְצָֽא׃","wa⁠yȧqĕré֞b ʼeţ-şé֤̌bet bi̇nĕyámin֙ l⁠mşpẖţ⁠w wa⁠ţi̇lá̇ké֖d mişĕ̌pȧ֣ẖaţ ha⁠mȧtĕri֑y wa⁠yi̇lá̇kéd֙ şá̌ʼ֣ẇl bėn-qi֔yş̌ wa⁠yĕbaqĕşǔ֖⁠hẇ wĕ⁠lò֥ʼ nimĕẕáֽʼ׃"],[10,22,"וַ⁠יִּשְׁאֲלוּ־עוֹד֙ בַּֽ⁠יהוָ֔ה הֲ⁠בָ֥א ע֖וֹד הֲלֹ֣ם אִ֑ישׁ ס וַ⁠יֹּ֣אמֶר יְהוָ֔ה הִנֵּה־ה֥וּא נֶחְבָּ֖א אֶל־הַ⁠כֵּלִֽים׃","wa⁠yi̇şĕ̌ʼàlẇ-ʻwòd֙ bȧֽ⁠yhwá֔h hà⁠bá֥ʼ ʻ֖wòd hàlò֣m ʼi֑yş̌ s wa⁠yò֣̇ʼmer yĕhwá֔h hiné̇h-h֥ẇʼ neẖĕbá֖̇ʼ ʼel-ha⁠ké̇liֽym׃"],[10,23,"וַ⁠יָּרֻ֨צוּ֙ וַ⁠יִּקָּחֻ֣⁠הוּ מִ⁠שָּׁ֔ם וַ⁠יִּתְיַצֵּ֖ב בְּ⁠ת֣וֹךְ הָ⁠עָ֑ם וַ⁠יִּגְבַּהּ֙ מִ⁠כָּל־הָ⁠עָ֔ם מִ⁠שִּׁכְמ֖⁠וֹ וָ⁠מָֽעְלָ⁠ה׃","wa⁠yá̇ru֨ẕẇ֙ wa⁠yi̇qá̇ẖu֣⁠hẇ mi⁠şá̇̌֔m wa⁠yi̇ţĕyaẕé֖̇b bĕ̇⁠ţ֣wòkĕ há⁠ʻá֑m wa⁠yi̇gĕbȧḣ֙ mi⁠ká̇l-há⁠ʻá֔m mi⁠şi̇̌kĕm֖⁠wò wá⁠máֽʻĕlá⁠h׃"],[10,24,"וַ⁠יֹּ֨אמֶר שְׁמוּאֵ֜ל אֶל־כָּל־הָ⁠עָ֗ם הַ⁠רְּאִיתֶם֙ אֲשֶׁ֣ר בָּֽחַר־בּ֣⁠וֹ יְהוָ֔ה כִּ֛י אֵ֥ין כָּמֹ֖⁠הוּ בְּ⁠כָל־הָ⁠עָ֑ם וַ⁠יָּרִ֧עוּ כָל־הָ⁠עָ֛ם וַ⁠יֹּאמְר֖וּ יְחִ֥י הַ⁠מֶּֽלֶךְ׃פ","wa⁠yò̇֨ʼmer şĕ̌mẇʼé֜l ʼel-ká̇l-há⁠ʻá֗m ha⁠rĕ̇ʼiyţem֙ ʼàşě֣r báֽ̇ẖar-ḃ֣⁠wò yĕhwá֔h ki֛̇y ʼé֥yn ká̇mò֖⁠hẇ bĕ̇⁠kál-há⁠ʻá֑m wa⁠yá̇ri֧ʻẇ kál-há⁠ʻá֛m wa⁠yò̇ʼmĕr֖ẇ yĕẖi֥y ha⁠mėֽlekĕ׃p"],[10,25,"וַ⁠יְדַבֵּ֨ר שְׁמוּאֵ֜ל אֶל־הָ⁠עָ֗ם אֵ֚ת מִשְׁפַּ֣ט הַ⁠מְּלֻכָ֔ה וַ⁠יִּכְתֹּ֣ב בַּ⁠סֵּ֔פֶר וַ⁠יַּנַּ֖ח לִ⁠פְנֵ֣י יְהוָ֑ה וַ⁠יְשַׁלַּ֧ח שְׁמוּאֵ֛ל אֶת־כָּל־הָ⁠עָ֖ם אִ֥ישׁ לְ⁠בֵיתֽ⁠וֹ׃","wa⁠yĕdabé̇֨r şĕ̌mẇʼé֜l ʼel-há⁠ʻá֗m ʼé֚ţ mişĕ̌pȧ֣t ha⁠mĕ̇luká֔h wa⁠yi̇kĕţò֣̇b bȧ⁠sé̇֔per wa⁠yȧnȧ֖ẖ li⁠pĕné֣y yĕhwá֑h wa⁠yĕşǎlȧ֧ẖ şĕ̌mẇʼé֛l ʼeţ-ká̇l-há⁠ʻá֖m ʼi֥yş̌ lĕ⁠béyţֽ⁠wò׃"],[10,26,"וְ⁠גַ֨ם־שָׁא֔וּל הָלַ֥ךְ לְ⁠בֵית֖⁠וֹ גִּבְעָ֑תָ⁠ה וַ⁠יֵּלְכ֣וּ עִמּ֔⁠וֹ הַ⁠חַ֕יִל אֲשֶׁר־נָגַ֥ע אֱלֹהִ֖ים בְּ⁠לִבָּֽ⁠ם׃","wĕ⁠ga֨m-şá̌ʼ֔ẇl hála֥kĕ lĕ⁠béyţ֖⁠wò gi̇bĕʻá֑ţá⁠h wa⁠yé̇lĕk֣ẇ ʻiṁ֔⁠wò ha⁠ẖa֕yil ʼàşěr-nága֥ʻ ʼèlòhi֖ym bĕ̇⁠libáֽ̇⁠m׃"],[10,27,"וּ⁠בְנֵ֧י בְלִיַּ֣עַל אָמְר֗וּ מַה־יֹּשִׁעֵ֨⁠נוּ֙ זֶ֔ה וַ⁠יִּבְזֻ֕⁠הוּ וְ⁠לֹֽא־הֵבִ֥יאוּ ל֖⁠וֹ מִנְחָ֑ה וַ⁠יְהִ֖י כְּ⁠מַחֲרִֽישׁ׃פ","ẇ⁠bĕné֧y bĕliyȧ֣ʻal ʼámĕr֗ẇ mah-yò̇şǐʻé֨⁠nẇ֙ ze֔h wa⁠yi̇bĕzu֕⁠hẇ wĕ⁠lòֽʼ-hébi֥yʼẇ l֖⁠wò minĕẖá֑h wa⁠yĕhi֖y kĕ̇⁠maẖàriֽyş̌׃p"],[11,1,"וַ⁠יַּ֗עַל נָחָשׁ֙ הָֽ⁠עַמּוֹנִ֔י וַ⁠יִּ֖חַן עַל־יָבֵ֣שׁ גִּלְעָ֑ד וַ⁠יֹּ֨אמְר֜וּ כָּל־אַנְשֵׁ֤י יָבֵישׁ֙ אֶל־נָחָ֔שׁ כְּרָת־לָ֥⁠נוּ בְרִ֖ית וְ⁠נַעַבְדֶֽ⁠ךָּ׃","wa⁠yȧ֗ʻal náẖáş̌֙ háֽ⁠ʻaṁwòni֔y wa⁠yi֖̇ẖan ʻal-yábé֣ş̌ gi̇lĕʻá֑d wa⁠yò̇֨ʼmĕr֜ẇ ká̇l-ʼanĕşé֤̌y yábéyş̌֙ ʼel-náẖá֔ş̌ kĕ̇ráţ-lá֥⁠nẇ bĕri֖yţ wĕ⁠naʻabĕdeֽ⁠ká̇׃"],[11,2,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֗ם נָחָשׁ֙ הָ⁠עַמּוֹנִ֔י בְּ⁠זֹאת֙ אֶכְרֹ֣ת לָ⁠כֶ֔ם בִּ⁠נְק֥וֹר לָ⁠כֶ֖ם כָּל־עֵ֣ין יָמִ֑ין וְ⁠שַׂמְתִּ֥י⁠הָ חֶרְפָּ֖ה עַל־כָּל־יִשְׂרָאֵֽל׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֗m náẖáş̌֙ há⁠ʻaṁwòni֔y bĕ̇⁠zòʼţ֙ ʼekĕrò֣ţ lá⁠ke֔m bi̇⁠nĕq֥wòr lá⁠ke֖m ká̇l-ʻé֣yn yámi֑yn wĕ⁠şâmĕţi֥̇y⁠há ẖerĕpá֖̇h ʻal-ká̇l-yişĕ̂ráʼéֽl׃"],[11,3,"וַ⁠יֹּאמְר֨וּ אֵלָ֜י⁠ו זִקְנֵ֣י יָבֵ֗ישׁ הֶ֤רֶף לָ֨⁠נוּ֙ שִׁבְעַ֣ת יָמִ֔ים וְ⁠נִשְׁלְחָה֙ מַלְאָכִ֔ים בְּ⁠כֹ֖ל גְּב֣וּל יִשְׂרָאֵ֑ל וְ⁠אִם־אֵ֥ין מוֹשִׁ֛יעַ אֹתָ֖⁠נוּ וְ⁠יָצָ֥אנוּ אֵלֶֽי⁠ךָ׃","wa⁠yò̇ʼmĕr֨ẇ ʼélá֜y⁠w ziqĕné֣y yábé֗yş̌ he֤rep lá֨⁠nẇ֙ şǐbĕʻa֣ţ yámi֔ym wĕ⁠nişĕ̌lĕẖáh֙ malĕʼáki֔ym bĕ̇⁠kò֖l gĕ̇b֣ẇl yişĕ̂ráʼé֑l wĕ⁠ʼim-ʼé֥yn mwòşǐ֛yʻa ʼòţá֖⁠nẇ wĕ⁠yáẕá֥ʼnẇ ʼéleֽy⁠ká׃"],[11,4,"וַ⁠יָּבֹ֤אוּ הַ⁠מַּלְאָכִים֙ גִּבְעַ֣ת שָׁא֔וּל וַ⁠יְדַבְּר֥וּ הַ⁠דְּבָרִ֖ים בְּ⁠אָזְנֵ֣י הָ⁠עָ֑ם וַ⁠יִּשְׂא֧וּ כָל־הָ⁠עָ֛ם אֶת־קוֹלָ֖⁠ם וַ⁠יִּבְכּֽוּ׃","wa⁠yá̇bò֤ʼẇ ha⁠mȧlĕʼákiym֙ gi̇bĕʻa֣ţ şá̌ʼ֔ẇl wa⁠yĕdabĕ̇r֥ẇ ha⁠dĕ̇bári֖ym bĕ̇⁠ʼázĕné֣y há⁠ʻá֑m wa⁠yi̇şĕ̂ʼ֧ẇ kál-há⁠ʻá֛m ʼeţ-qwòlá֖⁠m wa⁠yi̇bĕkֽ̇ẇ׃"],[11,5,"וְ⁠הִנֵּ֣ה שָׁא֗וּל בָּ֣א אַחֲרֵ֤י הַ⁠בָּקָר֙ מִן־הַ⁠שָּׂדֶ֔ה וַ⁠יֹּ֣אמֶר שָׁא֔וּל מַה־לָּ⁠עָ֖ם כִּ֣י יִבְכּ֑וּ וַ⁠יְסַ֨פְּרוּ־ל֔⁠וֹ אֶת־דִּבְרֵ֖י אַנְשֵׁ֥י יָבֵֽישׁ׃","wĕ⁠hiné֣̇h şá̌ʼ֗ẇl bá֣̇ʼ ʼaẖàré֤y ha⁠bá̇qár֙ min-ha⁠şá̇̂de֔h wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl mah-lá̇⁠ʻá֖m ki֣̇y yibĕk֑̇ẇ wa⁠yĕsa֨pĕ̇rẇ-l֔⁠wò ʼeţ-di̇bĕré֖y ʼanĕşé֥̌y yábéֽyş̌׃"],[11,6,"וַ⁠תִּצְלַ֤ח רֽוּחַ־אֱלֹהִים֙ עַל־שָׁא֔וּל ב⁠שמע⁠ו אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה וַ⁠יִּ֥חַר אַפּ֖⁠וֹ מְאֹֽד׃","wa⁠ţi̇ẕĕla֤ẖ rֽẇẖa-ʼèlòhiym֙ ʻal-şá̌ʼ֔ẇl b⁠şmʻ⁠w ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh wa⁠yi֥̇ẖar ʼaṗ֖⁠wò mĕʼòֽd׃"],[11,7,"וַ⁠יִּקַּח֩ צֶ֨מֶד בָּקָ֜ר וַֽ⁠יְנַתְּחֵ֗⁠הוּ וַ⁠יְשַׁלַּ֞ח בְּ⁠כָל־גְּב֣וּל יִשְׂרָאֵל֮ בְּ⁠יַ֣ד הַ⁠מַּלְאָכִ֣ים ׀ לֵ⁠אמֹר֒ אֲשֶׁר֩ אֵינֶ֨⁠נּוּ יֹצֵ֜א אַחֲרֵ֤י שָׁאוּל֙ וְ⁠אַחַ֣ר שְׁמוּאֵ֔ל כֹּ֥ה יֵעָשֶׂ֖ה לִ⁠בְקָר֑⁠וֹ וַ⁠יִּפֹּ֤ל פַּֽחַד־יְהוָה֙ עַל־הָ⁠עָ֔ם וַ⁠יֵּצְא֖וּ כְּ⁠אִ֥ישׁ אֶחָֽד׃","wa⁠yi̇qȧẖ֩ ẕe֨med bá̇qá֜r waֽ⁠yĕnaţĕ̇ẖé֗⁠hẇ wa⁠yĕşǎlȧ֞ẖ bĕ̇⁠kál-gĕ̇b֣ẇl yişĕ̂ráʼél֮ bĕ̇⁠ya֣d ha⁠mȧlĕʼáki֣ym ׀ lé⁠ʼmòr֒ ʼàşěr֩ ʼéyne֨⁠ṅẇ yòẕé֜ʼ ʼaẖàré֤y şá̌ʼẇl֙ wĕ⁠ʼaẖa֣r şĕ̌mẇʼé֔l kò֥̇h yéʻáşê֖h li⁠bĕqár֑⁠wò wa⁠yi̇pò֤̇l pȧֽẖad-yĕhwáh֙ ʻal-há⁠ʻá֔m wa⁠yé̇ẕĕʼ֖ẇ kĕ̇⁠ʼi֥yş̌ ʼeẖáֽd׃"],[11,8,"וַֽ⁠יִּפְקְדֵ֖⁠ם בְּ⁠בָ֑זֶק וַ⁠יִּהְי֤וּ בְנֵֽי־יִשְׂרָאֵל֙ שְׁלֹ֣שׁ מֵא֣וֹת אֶ֔לֶף וְ⁠אִ֥ישׁ יְהוּדָ֖ה שְׁלֹשִׁ֥ים אָֽלֶף׃","waֽ⁠yi̇pĕqĕdé֖⁠m bĕ̇⁠bá֑zeq wa⁠yi̇hĕy֤ẇ bĕnéֽy-yişĕ̂ráʼél֙ şĕ̌lò֣ş̌ méʼ֣wòţ ʼe֔lep wĕ⁠ʼi֥yş̌ yĕhẇdá֖h şĕ̌lòşǐ֥ym ʼáֽlep׃"],[11,9,"וַ⁠יֹּאמְר֞וּ לַ⁠מַּלְאָכִ֣ים הַ⁠בָּאִ֗ים כֹּ֤ה תֹֽאמְרוּ⁠ן֙ לְ⁠אִישׁ֙ יָבֵ֣ישׁ גִּלְעָ֔ד מָחָ֛ר תִּהְיֶֽה־לָ⁠כֶ֥ם תְּשׁוּעָ֖ה ב⁠חם הַ⁠שָּׁ֑מֶשׁ וַ⁠יָּבֹ֣אוּ הַ⁠מַּלְאָכִ֗ים וַ⁠יַּגִּ֛ידוּ לְ⁠אַנְשֵׁ֥י יָבֵ֖ישׁ וַ⁠יִּשְׂמָֽחוּ׃","wa⁠yò̇ʼmĕr֞ẇ la⁠mȧlĕʼáki֣ym ha⁠bá̇ʼi֗ym kò֤̇h ţòֽʼmĕrẇ⁠n֙ lĕ⁠ʼiyş̌֙ yábé֣yş̌ gi̇lĕʻá֔d máẖá֛r ţi̇hĕyeֽh-lá⁠ke֥m ţĕ̇ş̌ẇʻá֖h b⁠ẖm ha⁠şá֑̇̌meş̌ wa⁠yá̇bò֣ʼẇ ha⁠mȧlĕʼáki֗ym wa⁠yȧgi֛̇ydẇ lĕ⁠ʼanĕşé֥̌y yábé֖yş̌ wa⁠yi̇şĕ̂máֽẖẇ׃"],[11,10,"וַֽ⁠יֹּאמְרוּ֙ אַנְשֵׁ֣י יָבֵ֔ישׁ מָחָ֖ר נֵצֵ֣א אֲלֵי⁠כֶ֑ם וַ⁠עֲשִׂיתֶ֣ם לָּ֔⁠נוּ כְּ⁠כָל־הַ⁠טּ֖וֹב בְּ⁠עֵינֵי⁠כֶֽם׃ס","waֽ⁠yò̇ʼmĕrẇ֙ ʼanĕşé֣̌y yábé֔yş̌ máẖá֖r néẕé֣ʼ ʼàléy⁠ke֑m wa⁠ʻàşîyţe֣m lá̇֔⁠nẇ kĕ̇⁠kál-ha⁠ṫ֖wòb bĕ̇⁠ʻéynéy⁠keֽm׃s"],[11,11,"וַ⁠יְהִ֣י מִֽ⁠מָּחֳרָ֗ת וַ⁠יָּ֨שֶׂם שָׁא֣וּל אֶת־הָ⁠עָם֮ שְׁלֹשָׁ֣ה רָאשִׁים֒ וַ⁠יָּבֹ֤אוּ בְ⁠תוֹךְ־הַֽ⁠מַּחֲנֶה֙ בְּ⁠אַשְׁמֹ֣רֶת הַ⁠בֹּ֔קֶר וַ⁠יַּכּ֥וּ אֶת־עַמּ֖וֹן עַד־חֹ֣ם הַ⁠יּ֑וֹם וַ⁠יְהִ֤י הַ⁠נִּשְׁאָרִים֙ וַ⁠יָּפֻ֔צוּ וְ⁠לֹ֥א נִשְׁאֲרוּ־בָ֖⁠ם שְׁנַ֥יִם יָֽחַד׃","wa⁠yĕhi֣y miֽ⁠má̇ẖorá֗ţ wa⁠yá̇֨şêm şá̌ʼ֣ẇl ʼeţ-há⁠ʻám֮ şĕ̌lòşá֣̌h ráʼşǐym֒ wa⁠yá̇bò֤ʼẇ bĕ⁠ţwòkĕ-haֽ⁠mȧẖàneh֙ bĕ̇⁠ʼaşĕ̌mò֣reţ ha⁠bò̇֔qer wa⁠yȧk֥̇ẇ ʼeţ-ʻaṁ֖wòn ʻad-ẖò֣m ha⁠ẏ֑wòm wa⁠yĕhi֤y ha⁠ni̇şĕ̌ʼáriym֙ wa⁠yá̇pu֔ẕẇ wĕ⁠lò֥ʼ nişĕ̌ʼàrẇ-bá֖⁠m şĕ̌na֥yim yáֽẖad׃"],[11,12,"וַ⁠יֹּ֤אמֶר הָ⁠עָם֙ אֶל־שְׁמוּאֵ֔ל מִ֣י הָ⁠אֹמֵ֔ר שָׁא֖וּל יִמְלֹ֣ךְ עָלֵ֑י⁠נוּ תְּנ֥וּ הָ⁠אֲנָשִׁ֖ים וּ⁠נְמִיתֵֽ⁠ם׃","wa⁠yò֤̇ʼmer há⁠ʻám֙ ʼel-şĕ̌mẇʼé֔l mi֣y há⁠ʼòmé֔r şá̌ʼ֖ẇl yimĕlò֣kĕ ʻálé֑y⁠nẇ ţĕ̇n֥ẇ há⁠ʼànáşǐ֖ym ẇ⁠nĕmiyţéֽ⁠m׃"],[11,13,"וַ⁠יֹּ֣אמֶר שָׁא֔וּל לֹֽא־יוּמַ֥ת אִ֖ישׁ בַּ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ֥י הַ⁠יּ֛וֹם עָשָֽׂה־יְהוָ֥ה תְּשׁוּעָ֖ה בְּ⁠יִשְׂרָאֵֽל׃ס","wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl lòֽʼ-yẇma֥ţ ʼi֖yş̌ bȧ⁠ẏ֣wòm ha⁠zė֑h ki֥̇y ha⁠ẏ֛wòm ʻáşáֽ̂h-yĕhwá֥h ţĕ̇ş̌ẇʻá֖h bĕ̇⁠yişĕ̂ráʼéֽl׃s"],[11,14,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־הָ⁠עָ֔ם לְכ֖וּ וְ⁠נֵלְכָ֣ה הַ⁠גִּלְגָּ֑ל וּ⁠נְחַדֵּ֥שׁ שָׁ֖ם הַ⁠מְּלוּכָֽה׃","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-há⁠ʻá֔m lĕk֖ẇ wĕ⁠nélĕká֣h ha⁠gi̇lĕgá֑̇l ẇ⁠nĕẖadé֥̇ş̌ şá֖̌m ha⁠mĕ̇lẇkáֽh׃"],[11,15,"וַ⁠יֵּלְכ֨וּ כָל־הָ⁠עָ֜ם הַ⁠גִּלְגָּ֗ל וַ⁠יַּמְלִכוּ֩ שָׁ֨ם אֶת־שָׁא֜וּל לִ⁠פְנֵ֤י יְהוָה֙ בַּ⁠גִּלְגָּ֔ל וַ⁠יִּזְבְּחוּ־שָׁ֛ם זְבָחִ֥ים שְׁלָמִ֖ים לִ⁠פְנֵ֣י יְהוָ֑ה וַ⁠יִּשְׂמַ֨ח שָׁ֥ם שָׁא֛וּל וְ⁠כָל־אַנְשֵׁ֥י יִשְׂרָאֵ֖ל עַד־מְאֹֽד׃פ","wa⁠yé̇lĕk֨ẇ kál-há⁠ʻá֜m ha⁠gi̇lĕgá̇֗l wa⁠yȧmĕlikẇ֩ şá̌֨m ʼeţ-şá̌ʼ֜ẇl li⁠pĕné֤y yĕhwáh֙ bȧ⁠gi̇lĕgá̇֔l wa⁠yi̇zĕbĕ̇ẖẇ-şá֛̌m zĕbáẖi֥ym şĕ̌lámi֖ym li⁠pĕné֣y yĕhwá֑h wa⁠yi̇şĕ̂ma֨ẖ şá֥̌m şá̌ʼ֛ẇl wĕ⁠kál-ʼanĕşé֥̌y yişĕ̂ráʼé֖l ʻad-mĕʼòֽd׃p"],[12,1,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־כָּל־יִשְׂרָאֵ֔ל הִנֵּה֙ שָׁמַ֣עְתִּי בְ⁠קֹֽלְ⁠כֶ֔ם לְ⁠כֹ֥ל אֲשֶׁר־אֲמַרְתֶּ֖ם לִ֑⁠י וָ⁠אַמְלִ֥יךְ עֲלֵי⁠כֶ֖ם מֶֽלֶךְ׃","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-ká̇l-yişĕ̂ráʼé֔l hiné̇h֙ şá̌ma֣ʻĕţi̇y bĕ⁠qòֽlĕ⁠ke֔m lĕ⁠kò֥l ʼàşěr-ʼàmarĕţė֖m li֑⁠y wá⁠ʼamĕli֥ykĕ ʻàléy⁠ke֖m meֽlekĕ׃"],[12,2,"וְ⁠עַתָּ֞ה הִנֵּ֥ה הַ⁠מֶּ֣לֶךְ ׀ מִתְהַלֵּ֣ךְ לִ⁠פְנֵי⁠כֶ֗ם וַ⁠אֲנִי֙ זָקַ֣נְתִּי וָ⁠שַׂ֔בְתִּי וּ⁠בָנַ֖⁠י הִנָּ֣⁠ם אִתְּ⁠כֶ֑ם וַ⁠אֲנִי֙ הִתְהַלַּ֣כְתִּי לִ⁠פְנֵי⁠כֶ֔ם מִ⁠נְּעֻרַ֖⁠י עַד־הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wĕ⁠ʻaţá̇֞h hiné֥̇h ha⁠mė֣lekĕ ׀ miţĕhalé֣̇kĕ li⁠pĕnéy⁠ke֗m wa⁠ʼàniy֙ záqa֣nĕţi̇y wá⁠şâ֔bĕţi̇y ẇ⁠bána֖⁠y hiná֣̇⁠m ʼiţĕ̇⁠ke֑m wa⁠ʼàniy֙ hiţĕhalȧ֣kĕţi̇y li⁠pĕnéy⁠ke֔m mi⁠nĕ̇ʻura֖⁠y ʻad-ha⁠ẏ֥wòm ha⁠zėֽh׃"],[12,3,"הִנְ⁠נִ֣י עֲנ֣וּ בִ⁠י֩ נֶ֨גֶד יְהוָ֜ה וְ⁠נֶ֣גֶד מְשִׁיח֗⁠וֹ אֶת־שׁוֹר֩ ׀ מִ֨י לָקַ֜חְתִּי וַ⁠חֲמ֧וֹר מִ֣י לָקַ֗חְתִּי וְ⁠אֶת־מִ֤י עָשַׁ֨קְתִּי֙ אֶת־מִ֣י רַצּ֔וֹתִי וּ⁠מִ⁠יַּד־מִי֙ לָקַ֣חְתִּי כֹ֔פֶר וְ⁠אַעְלִ֥ים עֵינַ֖⁠י בּ֑⁠וֹ וְ⁠אָשִׁ֖יב לָ⁠כֶֽם׃","hinĕ⁠ni֣y ʻàn֣ẇ bi⁠y֩ ne֨ged yĕhwá֜h wĕ⁠ne֣ged mĕşǐyẖ֗⁠wò ʼeţ-ş̌wòr֩ ׀ mi֨y láqa֜ẖĕţi̇y wa⁠ẖàm֧wòr mi֣y láqa֗ẖĕţi̇y wĕ⁠ʼeţ-mi֤y ʻáşǎ֨qĕţi̇y֙ ʼeţ-mi֣y raẕ̇֔wòţiy ẇ⁠mi⁠yȧd-miy֙ láqa֣ẖĕţi̇y kò֔per wĕ⁠ʼaʻĕli֥ym ʻéyna֖⁠y ḃ֑⁠wò wĕ⁠ʼáşǐ֖yb lá⁠keֽm׃"],[12,4,"וַ⁠יֹּ֣אמְר֔וּ לֹ֥א עֲשַׁקְתָּ֖⁠נוּ וְ⁠לֹ֣א רַצּוֹתָ֑⁠נוּ וְ⁠לֹֽא־לָקַ֥חְתָּ מִ⁠יַּד־אִ֖ישׁ מְאֽוּמָה׃","wa⁠yò֣̇ʼmĕr֔ẇ lò֥ʼ ʻàşǎqĕţá֖̇⁠nẇ wĕ⁠lò֣ʼ raẕ̇wòţá֑⁠nẇ wĕ⁠lòֽʼ-láqa֥ẖĕţá̇ mi⁠yȧd-ʼi֖yş̌ mĕʼֽẇmáh׃"],[12,5,"וַ⁠יֹּ֨אמֶר אֲלֵי⁠הֶ֜ם עֵ֧ד יְהוָ֣ה בָּ⁠כֶ֗ם וְ⁠עֵ֤ד מְשִׁיח⁠וֹ֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה כִּ֣י לֹ֧א מְצָאתֶ֛ם בְּ⁠יָדִ֖⁠י מְא֑וּמָה וַ⁠יֹּ֖אמֶר עֵֽד׃פ","wa⁠yò̇֨ʼmer ʼàléy⁠he֜m ʻé֧d yĕhwá֣h bá̇⁠ke֗m wĕ⁠ʻé֤d mĕşǐyẖ⁠wò֙ ha⁠ẏ֣wòm ha⁠zė֔h ki֣̇y lò֧ʼ mĕẕáʼţe֛m bĕ̇⁠yádi֖⁠y mĕʼ֑ẇmáh wa⁠yò֖̇ʼmer ʻéֽd׃p"],[12,6,"וַ⁠יֹּ֥אמֶר שְׁמוּאֵ֖ל אֶל־הָ⁠עָ֑ם יְהוָ֗ה אֲשֶׁ֤ר עָשָׂה֙ אֶת־מֹשֶׁ֣ה וְ⁠אֶֽת־אַהֲרֹ֔ן וַ⁠אֲשֶׁ֧ר הֶעֱלָ֛ה אֶת־אֲבֹתֵי⁠כֶ֖ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yò֥̇ʼmer şĕ̌mẇʼé֖l ʼel-há⁠ʻá֑m yĕhwá֗h ʼàşě֤r ʻáşá̂h֙ ʼeţ-mòşě֣h wĕ⁠ʼeֽţ-ʼahàrò֔n wa⁠ʼàşě֧r heʻèlá֛h ʼeţ-ʼàbòţéy⁠ke֖m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[12,7,"וְ⁠עַתָּ֗ה הִֽתְיַצְּב֛וּ וְ⁠אִשָּׁפְטָ֥ה אִתְּ⁠כֶ֖ם לִ⁠פְנֵ֣י יְהוָ֑ה אֵ֚ת כָּל־צִדְק֣וֹת יְהוָ֔ה אֲשֶׁר־עָשָׂ֥ה אִתְּ⁠כֶ֖ם וְ⁠אֶת־אֲבוֹתֵי⁠כֶֽם׃","wĕ⁠ʻaţá̇֗h hiֽţĕyaẕĕ̇b֛ẇ wĕ⁠ʼişá̇̌pĕtá֥h ʼiţĕ̇⁠ke֖m li⁠pĕné֣y yĕhwá֑h ʼé֚ţ ká̇l-ẕidĕq֣wòţ yĕhwá֔h ʼàşěr-ʻáşá֥̂h ʼiţĕ̇⁠ke֖m wĕ⁠ʼeţ-ʼàbwòţéy⁠keֽm׃"],[12,8,"כַּֽ⁠אֲשֶׁר־בָּ֥א יַעֲקֹ֖ב מִצְרָ֑יִם וַ⁠יִּזְעֲק֤וּ אֲבֽוֹתֵי⁠כֶם֙ אֶל־יְהוָ֔ה וַ⁠יִּשְׁלַ֨ח יְהוָ֜ה אֶת־מֹשֶׁ֣ה וְ⁠אֶֽת־אַהֲרֹ֗ן וַ⁠יּוֹצִ֤יאוּ אֶת־אֲבֹֽתֵי⁠כֶם֙ מִ⁠מִּצְרַ֔יִם וַ⁠יֹּשִׁב֖וּ⁠ם בַּ⁠מָּק֥וֹם הַ⁠זֶּֽה׃","kȧֽ⁠ʼàşěr-bá֥̇ʼ yaʻàqò֖b miẕĕrá֑yim wa⁠yi̇zĕʻàq֤ẇ ʼàbֽwòţéy⁠kem֙ ʼel-yĕhwá֔h wa⁠yi̇şĕ̌la֨ẖ yĕhwá֜h ʼeţ-mòşě֣h wĕ⁠ʼeֽţ-ʼahàrò֗n wa⁠ẏwòẕi֤yʼẇ ʼeţ-ʼàbòֽţéy⁠kem֙ mi⁠mi̇ẕĕra֔yim wa⁠yò̇şǐb֖ẇ⁠m bȧ⁠má̇q֥wòm ha⁠zėֽh׃"],[12,9,"וַֽ⁠יִּשְׁכְּח֖וּ אֶת־יְהוָ֣ה אֱלֹהֵי⁠הֶ֑ם וַ⁠יִּמְכֹּ֣ר אֹתָ֡⁠ם בְּ⁠יַ֣ד סִֽיסְרָא֩ שַׂר־צְבָ֨א חָצ֜וֹר וּ⁠בְ⁠יַד־פְּלִשְׁתִּ֗ים וּ⁠בְ⁠יַד֙ מֶ֣לֶךְ מוֹאָ֔ב וַ⁠יִּֽלָּחֲמ֖וּ בָּֽ⁠ם׃","waֽ⁠yi̇şĕ̌kĕ̇ẖ֖ẇ ʼeţ-yĕhwá֣h ʼèlòhéy⁠he֑m wa⁠yi̇mĕkò֣̇r ʼòţá֡⁠m bĕ̇⁠ya֣d siֽysĕráʼ֩ şâr-ẕĕbá֨ʼ ẖáẕ֜wòr ẇ⁠bĕ⁠yad-pĕ̇lişĕ̌ţi̇֗ym ẇ⁠bĕ⁠yad֙ me֣lekĕ mwòʼá֔b wa⁠yiֽ̇lá̇ẖàm֖ẇ báֽ̇⁠m׃"],[12,10,"וַ⁠יִּזְעֲק֤וּ אֶל־יְהוָה֙ ו⁠יאמר חָטָ֔אנוּ כִּ֤י עָזַ֨בְנוּ֙ אֶת־יְהוָ֔ה וַ⁠נַּעֲבֹ֥ד אֶת־הַ⁠בְּעָלִ֖ים וְ⁠אֶת־הָ⁠עַשְׁתָּר֑וֹת וְ⁠עַתָּ֗ה הַצִּילֵ֛⁠נוּ מִ⁠יַּ֥ד אֹיְבֵ֖י⁠נוּ וְ⁠נַעַבְדֶֽ⁠ךָּ׃","wa⁠yi̇zĕʻàq֤ẇ ʼel-yĕhwáh֙ w⁠yʼmr ẖátá֔ʼnẇ ki֤̇y ʻáza֨bĕnẇ֙ ʼeţ-yĕhwá֔h wa⁠nȧʻàbò֥d ʼeţ-ha⁠bĕ̇ʻáli֖ym wĕ⁠ʼeţ-há⁠ʻaşĕ̌ţá̇r֑wòţ wĕ⁠ʻaţá̇֗h haẕi̇ylé֛⁠nẇ mi⁠yȧ֥d ʼòyĕbé֖y⁠nẇ wĕ⁠naʻabĕdeֽ⁠ká̇׃"],[12,11,"וַ⁠יִּשְׁלַ֤ח יְהוָה֙ אֶת־יְרֻבַּ֣עַל וְ⁠אֶת־בְּדָ֔ן וְ⁠אֶת־יִפְתָּ֖ח וְ⁠אֶת־שְׁמוּאֵ֑ל וַ⁠יַּצֵּ֨ל אֶתְ⁠כֶ֜ם מִ⁠יַּ֤ד אֹֽיְבֵי⁠כֶם֙ מִ⁠סָּבִ֔יב וַ⁠תֵּשְׁב֖וּ בֶּֽטַח׃","wa⁠yi̇şĕ̌la֤ẖ yĕhwáh֙ ʼeţ-yĕrubȧ֣ʻal wĕ⁠ʼeţ-bĕ̇dá֔n wĕ⁠ʼeţ-yipĕţá֖̇ẖ wĕ⁠ʼeţ-şĕ̌mẇʼé֑l wa⁠yȧẕé̇֨l ʼeţĕ⁠ke֜m mi⁠yȧ֤d ʼòֽyĕbéy⁠kem֙ mi⁠sá̇bi֔yb wa⁠ţé̇şĕ̌b֖ẇ bėֽtaẖ׃"],[12,12,"וַ⁠תִּרְא֗וּ כִּֽי־נָחָ֞שׁ מֶ֣לֶךְ בְּנֵֽי־עַמּוֹן֮ בָּ֣א עֲלֵי⁠כֶם֒ וַ⁠תֹּ֣אמְרוּ לִ֔⁠י לֹ֕א כִּי־מֶ֖לֶךְ יִמְלֹ֣ךְ עָלֵ֑י⁠נוּ וַ⁠יהוָ֥ה אֱלֹהֵי⁠כֶ֖ם מַלְכְּ⁠כֶֽם׃","wa⁠ţi̇rĕʼ֗ẇ kiֽ̇y-náẖá֞ş̌ me֣lekĕ bĕ̇néֽy-ʻaṁwòn֮ bá֣̇ʼ ʻàléy⁠kem֒ wa⁠ţò֣̇ʼmĕrẇ li֔⁠y lò֕ʼ ki̇y-me֖lekĕ yimĕlò֣kĕ ʻálé֑y⁠nẇ wa⁠yhwá֥h ʼèlòhéy⁠ke֖m malĕkĕ̇⁠keֽm׃"],[12,13,"וְ⁠עַתָּ֗ה הִנֵּ֥ה הַ⁠מֶּ֛לֶךְ אֲשֶׁ֥ר בְּחַרְתֶּ֖ם אֲשֶׁ֣ר שְׁאֶלְתֶּ֑ם וְ⁠הִנֵּ֨ה נָתַ֧ן יְהוָ֛ה עֲלֵי⁠כֶ֖ם מֶֽלֶךְ׃","wĕ⁠ʻaţá̇֗h hiné֥̇h ha⁠mė֛lekĕ ʼàşě֥r bĕ̇ẖarĕţė֖m ʼàşě֣r şĕ̌ʼelĕţė֑m wĕ⁠hiné̇֨h náţa֧n yĕhwá֛h ʻàléy⁠ke֖m meֽlekĕ׃"],[12,14,"אִם־תִּֽירְא֣וּ אֶת־יְהוָ֗ה וַ⁠עֲבַדְתֶּ֤ם אֹת⁠וֹ֙ וּ⁠שְׁמַעְתֶּ֣ם בְּ⁠קֹל֔⁠וֹ וְ⁠לֹ֥א תַמְר֖וּ אֶת־פִּ֣י יְהוָ֑ה וִ⁠הְיִתֶ֣ם גַּם־אַתֶּ֗ם וְ⁠גַם־הַ⁠מֶּ֨לֶךְ֙ אֲשֶׁ֣ר מָלַ֣ךְ עֲלֵי⁠כֶ֔ם אַחַ֖ר יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","ʼim-ţiֽ̇yrĕʼ֣ẇ ʼeţ-yĕhwá֗h wa⁠ʻàbadĕţė֤m ʼòţ⁠wò֙ ẇ⁠şĕ̌maʻĕţė֣m bĕ̇⁠qòl֔⁠wò wĕ⁠lò֥ʼ ţamĕr֖ẇ ʼeţ-pi֣̇y yĕhwá֑h wi⁠hĕyiţe֣m gȧm-ʼaţė֗m wĕ⁠gam-ha⁠mė֨lekĕ֙ ʼàşě֣r mála֣kĕ ʻàléy⁠ke֔m ʼaẖa֖r yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[12,15,"וְ⁠אִם־לֹ֤א תִשְׁמְעוּ֙ בְּ⁠ק֣וֹל יְהוָ֔ה וּ⁠מְרִיתֶ֖ם אֶת־פִּ֣י יְהוָ֑ה וְ⁠הָיְתָ֧ה יַד־יְהוָ֛ה בָּ⁠כֶ֖ם וּ⁠בַ⁠אֲבֹתֵי⁠כֶֽם׃","wĕ⁠ʼim-lò֤ʼ ţişĕ̌mĕʻẇ֙ bĕ̇⁠q֣wòl yĕhwá֔h ẇ⁠mĕriyţe֖m ʼeţ-pi֣̇y yĕhwá֑h wĕ⁠háyĕţá֧h yad-yĕhwá֛h bá̇⁠ke֖m ẇ⁠ba⁠ʼàbòţéy⁠keֽm׃"],[12,16,"גַּם־עַתָּה֙ הִתְיַצְּב֣וּ וּ⁠רְא֔וּ אֶת־הַ⁠דָּבָ֥ר הַ⁠גָּד֖וֹל הַ⁠זֶּ֑ה אֲשֶׁ֣ר יְהוָ֔ה עֹשֶׂ֖ה לְ⁠עֵינֵי⁠כֶֽם׃","gȧm-ʻaţá̇h֙ hiţĕyaẕĕ̇b֣ẇ ẇ⁠rĕʼ֔ẇ ʼeţ-ha⁠dá̇bá֥r ha⁠gá̇d֖wòl ha⁠zė֑h ʼàşě֣r yĕhwá֔h ʻòşê֖h lĕ⁠ʻéynéy⁠keֽm׃"],[12,17,"הֲ⁠ל֤וֹא קְצִיר־חִטִּים֙ הַ⁠יּ֔וֹם אֶקְרָא֙ אֶל־יְהוָ֔ה וְ⁠יִתֵּ֥ן קֹל֖וֹת וּ⁠מָטָ֑ר וּ⁠דְע֣וּ וּ⁠רְא֗וּ כִּֽי־רָעַתְ⁠כֶ֤ם רַבָּה֙ אֲשֶׁ֤ר עֲשִׂיתֶם֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה לִ⁠שְׁא֥וֹל לָ⁠כֶ֖ם מֶֽלֶךְ׃ס","hà⁠l֤wòʼ qĕẕiyr-ẖiti̇ym֙ ha⁠ẏ֔wòm ʼeqĕráʼ֙ ʼel-yĕhwá֔h wĕ⁠yiţé֥̇n qòl֖wòţ ẇ⁠mátá֑r ẇ⁠dĕʻ֣ẇ ẇ⁠rĕʼ֗ẇ kiֽ̇y-ráʻaţĕ⁠ke֤m rabá̇h֙ ʼàşě֤r ʻàşîyţem֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h li⁠şĕ̌ʼ֥wòl lá⁠ke֖m meֽlekĕ׃s"],[12,18,"וַ⁠יִּקְרָ֤א שְׁמוּאֵל֙ אֶל־יְהוָ֔ה וַ⁠יִּתֵּ֧ן יְהוָ֛ה קֹלֹ֥ת וּ⁠מָטָ֖ר בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וַ⁠יִּירָ֨א כָל־הָ⁠עָ֥ם מְאֹ֛ד אֶת־יְהוָ֖ה וְ⁠אֶת־שְׁמוּאֵֽל׃","wa⁠yi̇qĕrá֤ʼ şĕ̌mẇʼél֙ ʼel-yĕhwá֔h wa⁠yi̇ţé֧̇n yĕhwá֛h qòlò֥ţ ẇ⁠mátá֖r bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wa⁠yi̇yrá֨ʼ kál-há⁠ʻá֥m mĕʼò֛d ʼeţ-yĕhwá֖h wĕ⁠ʼeţ-şĕ̌mẇʼéֽl׃"],[12,19,"וַ⁠יֹּאמְר֨וּ כָל־הָ⁠עָ֜ם אֶל־שְׁמוּאֵ֗ל הִתְפַּלֵּ֧ל בְּעַד־עֲבָדֶ֛י⁠ךָ אֶל־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ וְ⁠אַל־נָמ֑וּת כִּֽי־יָסַ֤פְנוּ עַל־כָּל־חַטֹּאתֵ֨י⁠נוּ֙ רָעָ֔ה לִ⁠שְׁאֹ֥ל לָ֖⁠נוּ מֶֽלֶךְ׃ס","wa⁠yò̇ʼmĕr֨ẇ kál-há⁠ʻá֜m ʼel-şĕ̌mẇʼé֗l hiţĕpȧlé֧̇l bĕ̇ʻad-ʻàbáde֛y⁠ká ʼel-yĕhwá֥h ʼèlòhe֖y⁠ká wĕ⁠ʼal-nám֑ẇţ kiֽ̇y-yása֤pĕnẇ ʻal-ká̇l-ẖatò̇ʼţé֨y⁠nẇ֙ ráʻá֔h li⁠şĕ̌ʼò֥l lá֖⁠nẇ meֽlekĕ׃s"],[12,20,"וַ⁠יֹּ֨אמֶר שְׁמוּאֵ֤ל אֶל־הָ⁠עָם֙ אַל־תִּירָ֔אוּ אַתֶּ֣ם עֲשִׂיתֶ֔ם אֵ֥ת כָּל־הָ⁠רָעָ֖ה הַ⁠זֹּ֑את אַ֗ךְ אַל־תָּס֨וּרוּ֙ מֵ⁠אַחֲרֵ֣י יְהוָ֔ה וַ⁠עֲבַדְתֶּ֥ם אֶת־יְהוָ֖ה בְּ⁠כָל־לְבַבְ⁠כֶֽם׃","wa⁠yò̇֨ʼmer şĕ̌mẇʼé֤l ʼel-há⁠ʻám֙ ʼal-ţi̇yrá֔ʼẇ ʼaţė֣m ʻàşîyţe֔m ʼé֥ţ ká̇l-há⁠ráʻá֖h ha⁠zò֑̇ʼţ ʼa֗kĕ ʼal-ţá̇s֨ẇrẇ֙ mé⁠ʼaẖàré֣y yĕhwá֔h wa⁠ʻàbadĕţė֥m ʼeţ-yĕhwá֖h bĕ̇⁠kál-lĕbabĕ⁠keֽm׃"],[12,21,"וְ⁠לֹ֖א תָּס֑וּרוּ כִּ֣י ׀ אַחֲרֵ֣י הַ⁠תֹּ֗הוּ אֲשֶׁ֧ר לֹֽא־יוֹעִ֛ילוּ וְ⁠לֹ֥א יַצִּ֖ילוּ כִּי־תֹ֥הוּ הֵֽמָּה׃","wĕ⁠lò֖ʼ ţá̇s֑ẇrẇ ki֣̇y ׀ ʼaẖàré֣y ha⁠ţò̇֗hẇ ʼàşě֧r lòֽʼ-ywòʻi֛ylẇ wĕ⁠lò֥ʼ yaẕi֖̇ylẇ ki̇y-ţò֥hẇ héֽmá̇h׃"],[12,22,"כִּ֠י לֹֽא־יִטֹּ֤שׁ יְהוָה֙ אֶת־עַמּ֔⁠וֹ בַּ⁠עֲב֖וּר שְׁמ֣⁠וֹ הַ⁠גָּד֑וֹל כִּ֚י הוֹאִ֣יל יְהוָ֔ה לַ⁠עֲשׂ֥וֹת אֶתְ⁠כֶ֛ם ל֖⁠וֹ לְ⁠עָֽם׃","ki̇֠y lòֽʼ-yitò֤̇ş̌ yĕhwáh֙ ʼeţ-ʻaṁ֔⁠wò bȧ⁠ʻàb֖ẇr şĕ̌m֣⁠wò ha⁠gá̇d֑wòl ki֚̇y hwòʼi֣yl yĕhwá֔h la⁠ʻàş֥̂wòţ ʼeţĕ⁠ke֛m l֖⁠wò lĕ⁠ʻáֽm׃"],[12,23,"גַּ֣ם אָנֹכִ֗י חָלִ֤ילָ⁠ה לִּ⁠י֙ מֵ⁠חֲטֹ֣א לַֽ⁠יהוָ֔ה מֵ⁠חֲדֹ֖ל לְ⁠הִתְפַּלֵּ֣ל בַּעַדְ⁠כֶ֑ם וְ⁠הוֹרֵיתִ֣י אֶתְ⁠כֶ֔ם בְּ⁠דֶ֥רֶךְ הַ⁠טּוֹבָ֖ה וְ⁠הַ⁠יְשָׁרָֽה׃","gȧ֣m ʼánòki֗y ẖáli֤ylá⁠h li̇⁠y֙ mé⁠ẖàtò֣ʼ laֽ⁠yhwá֔h mé⁠ẖàdò֖l lĕ⁠hiţĕpȧlé֣̇l bȧʻadĕ⁠ke֑m wĕ⁠hwòréyţi֣y ʼeţĕ⁠ke֔m bĕ̇⁠de֥rekĕ ha⁠ṫwòbá֖h wĕ⁠ha⁠yĕşá̌ráֽh׃"],[12,24,"אַ֣ךְ ׀ יְר֣אוּ אֶת־יְהוָ֗ה וַ⁠עֲבַדְתֶּ֥ם אֹת֛⁠וֹ בֶּ⁠אֱמֶ֖ת בְּ⁠כָל־לְבַבְ⁠כֶ֑ם כִּ֣י רְא֔וּ אֵ֥ת אֲשֶׁר־הִגְדִּ֖ל עִמָּ⁠כֶֽם׃","ʼa֣kĕ ׀ yĕr֣ʼẇ ʼeţ-yĕhwá֗h wa⁠ʻàbadĕţė֥m ʼòţ֛⁠wò bė⁠ʼème֖ţ bĕ̇⁠kál-lĕbabĕ⁠ke֑m ki֣̇y rĕʼ֔ẇ ʼé֥ţ ʼàşěr-higĕdi֖̇l ʻimá̇⁠keֽm׃"],[12,25,"וְ⁠אִם־הָרֵ֖עַ תָּרֵ֑עוּ גַּם־אַתֶּ֥ם גַּֽם־מַלְכְּ⁠כֶ֖ם תִּסָּפֽוּ׃פ","wĕ⁠ʼim-háré֖ʻa ţá̇ré֑ʻẇ gȧm-ʼaţė֥m gȧֽm-malĕkĕ̇⁠ke֖m ţi̇sá̇pֽẇ׃p"],[13,1,"בֶּן־שָׁנָ֖ה שָׁא֣וּל בְּ⁠מָלְכ֑⁠וֹ וּ⁠שְׁתֵּ֣י שָׁנִ֔ים מָלַ֖ךְ עַל־יִשְׂרָאֵֽל׃","bėn-şá̌ná֖h şá̌ʼ֣ẇl bĕ̇⁠málĕk֑⁠wò ẇ⁠şĕ̌ţé֣̇y şá̌ni֔ym mála֖kĕ ʻal-yişĕ̂ráʼéֽl׃"],[13,2,"וַ⁠יִּבְחַר־ל֨⁠וֹ שָׁא֜וּל שְׁלֹ֣שֶׁת אֲלָפִים֮ מִ⁠יִּשְׂרָאֵל֒ וַ⁠יִּהְי֨וּ עִם־שָׁא֜וּל אַלְפַּ֗יִם בְּ⁠מִכְמָשׂ֙ וּ⁠בְ⁠הַ֣ר בֵּֽית־אֵ֔ל וְ⁠אֶ֗לֶף הָיוּ֙ עִם־י֣וֹנָתָ֔ן בְּ⁠גִבְעַ֖ת בִּנְיָמִ֑ין וְ⁠יֶ֣תֶר הָ⁠עָ֔ם שִׁלַּ֖ח אִ֥ישׁ לְ⁠אֹהָלָֽי⁠ו׃","wa⁠yi̇bĕẖar-l֨⁠wò şá̌ʼ֜ẇl şĕ̌lò֣şěţ ʼàlápiym֮ mi⁠yi̇şĕ̂ráʼél֒ wa⁠yi̇hĕy֨ẇ ʻim-şá̌ʼ֜ẇl ʼalĕpȧ֗yim bĕ̇⁠mikĕmáş̂֙ ẇ⁠bĕ⁠ha֣r béֽ̇yţ-ʼé֔l wĕ⁠ʼe֗lep háyẇ֙ ʻim-y֣wònáţá֔n bĕ̇⁠gibĕʻa֖ţ bi̇nĕyámi֑yn wĕ⁠ye֣ţer há⁠ʻá֔m şǐlȧ֖ẖ ʼi֥yş̌ lĕ⁠ʼòháláֽy⁠w׃"],[13,3,"וַ⁠יַּ֣ךְ יוֹנָתָ֗ן אֵ֣ת נְצִ֤יב פְּלִשְׁתִּים֙ אֲשֶׁ֣ר בְּ⁠גֶ֔בַע וַֽ⁠יִּשְׁמְע֖וּ פְּלִשְׁתִּ֑ים וְ⁠שָׁאוּל֩ תָּקַ֨ע בַּ⁠שּׁוֹפָ֤ר בְּ⁠כָל־הָ⁠אָ֨רֶץ֙ לֵ⁠אמֹ֔ר יִשְׁמְע֖וּ הָ⁠עִבְרִֽים׃","wa⁠yȧ֣kĕ ywònáţá֗n ʼé֣ţ nĕẕi֤yb pĕ̇lişĕ̌ţi̇ym֙ ʼàşě֣r bĕ̇⁠ge֔baʻ waֽ⁠yi̇şĕ̌mĕʻ֖ẇ pĕ̇lişĕ̌ţi֑̇ym wĕ⁠şá̌ʼẇl֩ ţá̇qa֨ʻ bȧ⁠ş̇̌wòpá֤r bĕ̇⁠kál-há⁠ʼá֨reẕ֙ lé⁠ʼmò֔r yişĕ̌mĕʻ֖ẇ há⁠ʻibĕriֽym׃"],[13,4,"וְ⁠כָל־יִשְׂרָאֵ֞ל שָׁמְע֣וּ לֵ⁠אמֹ֗ר הִכָּ֤ה שָׁאוּל֙ אֶת־נְצִ֣יב פְּלִשְׁתִּ֔ים וְ⁠גַם־נִבְאַשׁ יִשְׂרָאֵ֖ל בַּ⁠פְּלִשְׁתִּ֑ים וַ⁠יִּצָּעֲק֥וּ הָ⁠עָ֛ם אַחֲרֵ֥י שָׁא֖וּל הַ⁠גִּלְגָּֽל׃","wĕ⁠kál-yişĕ̂ráʼé֞l şá̌mĕʻ֣ẇ lé⁠ʼmò֗r hiká֤̇h şá̌ʼẇl֙ ʼeţ-nĕẕi֣yb pĕ̇lişĕ̌ţi̇֔ym wĕ⁠gam-nibĕʼaş̌ yişĕ̂ráʼé֖l bȧ⁠pĕ̇lişĕ̌ţi֑̇ym wa⁠yi̇ẕá̇ʻàq֥ẇ há⁠ʻá֛m ʼaẖàré֥y şá̌ʼ֖ẇl ha⁠gi̇lĕgáֽ̇l׃"],[13,5,"וּ⁠פְלִשְׁתִּ֞ים נֶאֶסְפ֣וּ ׀ לְ⁠הִלָּחֵ֣ם עִם־יִשְׂרָאֵ֗ל שְׁלֹשִׁ֨ים אֶ֤לֶף רֶ֨כֶב֙ וְ⁠שֵׁ֤שֶׁת אֲלָפִים֙ פָּרָשִׁ֔ים וְ⁠עָ֕ם כַּ⁠ח֛וֹל אֲשֶׁ֥ר עַל־שְׂפַֽת־הַ⁠יָּ֖ם לָ⁠רֹ֑ב וַֽ⁠יַּעֲלוּ֙ וַ⁠יַּחֲנ֣וּ בְ⁠מִכְמָ֔שׂ קִדְמַ֖ת בֵּ֥ית אָֽוֶן׃","ẇ⁠pĕlişĕ̌ţi̇֞ym neʼesĕp֣ẇ ׀ lĕ⁠hilá̇ẖé֣m ʻim-yişĕ̂ráʼé֗l şĕ̌lòşǐ֨ym ʼe֤lep re֨keb֙ wĕ⁠şé֤̌şěţ ʼàlápiym֙ pá̇ráşǐ֔ym wĕ⁠ʻá֕m kȧ⁠ẖ֛wòl ʼàşě֥r ʻal-şĕ̂paֽţ-ha⁠yá֖̇m lá⁠rò֑b waֽ⁠yȧʻàlẇ֙ wa⁠yȧẖàn֣ẇ bĕ⁠mikĕmá֔ş̂ qidĕma֖ţ bé֥̇yţ ʼáֽwen׃"],[13,6,"וְ⁠אִ֨ישׁ יִשְׂרָאֵ֤ל רָאוּ֙ כִּ֣י צַר־ל֔⁠וֹ כִּ֥י נִגַּ֖שׂ הָ⁠עָ֑ם וַ⁠יִּֽתְחַבְּא֣וּ הָ⁠עָ֗ם בַּ⁠מְּעָר֤וֹת וּ⁠בַֽ⁠חֲוָחִים֙ וּ⁠בַ⁠סְּלָעִ֔ים וּ⁠בַ⁠צְּרִחִ֖ים וּ⁠בַ⁠בֹּרֽוֹת׃","wĕ⁠ʼi֨yş̌ yişĕ̂ráʼé֤l ráʼẇ֙ ki֣̇y ẕar-l֔⁠wò ki֥̇y nigȧ֖ş̂ há⁠ʻá֑m wa⁠yiֽ̇ţĕẖabĕ̇ʼ֣ẇ há⁠ʻá֗m bȧ⁠mĕ̇ʻár֤wòţ ẇ⁠baֽ⁠ẖàwáẖiym֙ ẇ⁠ba⁠sĕ̇láʻi֔ym ẇ⁠ba⁠ẕĕ̇riẖi֖ym ẇ⁠ba⁠bò̇rֽwòţ׃"],[13,7,"וְ⁠עִבְרִ֗ים עָֽבְרוּ֙ אֶת־הַ⁠יַּרְדֵּ֔ן אֶ֥רֶץ גָּ֖ד וְ⁠גִלְעָ֑ד וְ⁠שָׁאוּל֙ עוֹדֶ֣⁠נּוּ בַ⁠גִּלְגָּ֔ל וְ⁠כָל־הָ⁠עָ֖ם חָרְד֥וּ אַחֲרָֽי⁠ו׃","wĕ⁠ʻibĕri֗ym ʻáֽbĕrẇ֙ ʼeţ-ha⁠yȧrĕdé̇֔n ʼe֥reẕ gá֖̇d wĕ⁠gilĕʻá֑d wĕ⁠şá̌ʼẇl֙ ʻwòde֣⁠ṅẇ ba⁠gi̇lĕgá̇֔l wĕ⁠kál-há⁠ʻá֖m ẖárĕd֥ẇ ʼaẖàráֽy⁠w׃"],[13,8,"ו⁠ייחל ׀ שִׁבְעַ֣ת יָמִ֗ים לַ⁠מּוֹעֵד֙ אֲשֶׁ֣ר שְׁמוּאֵ֔ל וְ⁠לֹא־בָ֥א שְׁמוּאֵ֖ל הַ⁠גִּלְגָּ֑ל וַ⁠יָּ֥פֶץ הָ⁠עָ֖ם מֵ⁠עָלָֽי⁠ו׃","w⁠yyẖl ׀ şǐbĕʻa֣ţ yámi֗ym la⁠ṁwòʻéd֙ ʼàşě֣r şĕ̌mẇʼé֔l wĕ⁠lòʼ-bá֥ʼ şĕ̌mẇʼé֖l ha⁠gi̇lĕgá֑̇l wa⁠yá֥̇peẕ há⁠ʻá֖m mé⁠ʻáláֽy⁠w׃"],[13,9,"וַ⁠יֹּ֣אמֶר שָׁא֔וּל הַגִּ֣שׁוּ אֵלַ֔⁠י הָ⁠עֹלָ֖ה וְ⁠הַ⁠שְּׁלָמִ֑ים וַ⁠יַּ֖עַל הָ⁠עֹלָֽה׃","wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl hagi֣̇ş̌ẇ ʼéla֔⁠y há⁠ʻòlá֖h wĕ⁠ha⁠şĕ̇̌lámi֑ym wa⁠yȧ֖ʻal há⁠ʻòláֽh׃"],[13,10,"וַ⁠יְהִ֗י כְּ⁠כַלֹּת⁠וֹ֙ לְ⁠הַעֲל֣וֹת הָ⁠עֹלָ֔ה וְ⁠הִנֵּ֥ה שְׁמוּאֵ֖ל בָּ֑א וַ⁠יֵּצֵ֥א שָׁא֛וּל לִ⁠קְרָאת֖⁠וֹ לְ⁠בָרֲכֽ⁠וֹ׃","wa⁠yĕhi֗y kĕ̇⁠kalò̇ţ⁠wò֙ lĕ⁠haʻàl֣wòţ há⁠ʻòlá֔h wĕ⁠hiné֥̇h şĕ̌mẇʼé֖l bá֑̇ʼ wa⁠yé̇ẕé֥ʼ şá̌ʼ֛ẇl li⁠qĕráʼţ֖⁠wò lĕ⁠báràkֽ⁠wò׃"],[13,11,"וַ⁠יֹּ֥אמֶר שְׁמוּאֵ֖ל מֶ֣ה עָשִׂ֑יתָ וַ⁠יֹּ֣אמֶר שָׁא֡וּל כִּֽי־רָאִיתִי֩ כִֽי־נָפַ֨ץ הָ⁠עָ֜ם מֵ⁠עָלַ֗⁠י וְ⁠אַתָּה֙ לֹא־בָ֨אתָ֙ לְ⁠מוֹעֵ֣ד הַ⁠יָּמִ֔ים וּ⁠פְלִשְׁתִּ֖ים נֶאֱסָפִ֥ים מִכְמָֽשׂ׃","wa⁠yò֥̇ʼmer şĕ̌mẇʼé֖l me֣h ʻáşî֑yţá wa⁠yò֣̇ʼmer şá̌ʼ֡ẇl kiֽ̇y-ráʼiyţiy֩ kiֽy-nápa֨ẕ há⁠ʻá֜m mé⁠ʻála֗⁠y wĕ⁠ʼaţá̇h֙ lòʼ-bá֨ʼţá֙ lĕ⁠mwòʻé֣d ha⁠yá̇mi֔ym ẇ⁠pĕlişĕ̌ţi֖̇ym neʼèsápi֥ym mikĕmáֽş̂׃"],[13,12,"וָ⁠אֹמַ֗ר עַ֠תָּה יֵרְד֨וּ פְלִשְׁתִּ֤ים אֵלַ⁠י֙ הַ⁠גִּלְגָּ֔ל וּ⁠פְנֵ֥י יְהוָ֖ה לֹ֣א חִלִּ֑יתִי וָֽ⁠אֶתְאַפַּ֔ק וָ⁠אַעֲלֶ֖ה הָ⁠עֹלָֽה׃ס","wá⁠ʼòma֗r ʻa֠ţá̇h yérĕd֨ẇ pĕlişĕ̌ţi֤̇ym ʼéla⁠y֙ ha⁠gi̇lĕgá̇֔l ẇ⁠pĕné֥y yĕhwá֖h lò֣ʼ ẖili֑̇yţiy wáֽ⁠ʼeţĕʼapȧ֔q wá⁠ʼaʻàle֖h há⁠ʻòláֽh׃s"],[13,13,"וַ⁠יֹּ֧אמֶר שְׁמוּאֵ֛ל אֶל־שָׁא֖וּל נִסְכָּ֑לְתָּ לֹ֣א שָׁמַ֗רְתָּ אֶת־מִצְוַ֞ת יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֲשֶׁ֣ר צִוָּ֔⁠ךְ כִּ֣י עַתָּ֗ה הֵכִ֨ין יְהוָ֧ה אֶת־מַֽמְלַכְתְּ⁠ךָ֛ אֶל־יִשְׂרָאֵ֖ל עַד־עוֹלָֽם׃","wa⁠yò֧̇ʼmer şĕ̌mẇʼé֛l ʼel-şá̌ʼ֖ẇl nisĕká֑̇lĕţá̇ lò֣ʼ şá̌ma֗rĕţá̇ ʼeţ-miẕĕwa֞ţ yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼàşě֣r ẕiwá̇֔⁠kĕ ki֣̇y ʻaţá̇֗h héki֨yn yĕhwá֧h ʼeţ-maֽmĕlakĕţĕ̇⁠ká֛ ʼel-yişĕ̂ráʼé֖l ʻad-ʻwòláֽm׃"],[13,14,"וְ⁠עַתָּ֖ה מַמְלַכְתְּ⁠ךָ֣ לֹא־תָק֑וּם בִּקֵּשׁ֩ יְהוָ֨ה ל֜⁠וֹ אִ֣ישׁ כִּ⁠לְבָב֗⁠וֹ וַ⁠יְצַוֵּ֨⁠הוּ יְהוָ֤ה לְ⁠נָגִיד֙ עַל־עַמּ֔⁠וֹ כִּ֚י לֹ֣א שָׁמַ֔רְתָּ אֵ֥ת אֲשֶֽׁר־צִוְּ⁠ךָ֖ יְהוָֽה׃פ","wĕ⁠ʻaţá֖̇h mamĕlakĕţĕ̇⁠ká֣ lòʼ-ţáq֑ẇm bi̇qé̇ş̌֩ yĕhwá֨h l֜⁠wò ʼi֣yş̌ ki̇⁠lĕbáb֗⁠wò wa⁠yĕẕawé̇֨⁠hẇ yĕhwá֤h lĕ⁠nágiyd֙ ʻal-ʻaṁ֔⁠wò ki֚̇y lò֣ʼ şá̌ma֔rĕţá̇ ʼé֥ţ ʼàşěֽr-ẕiwĕ̇⁠ká֖ yĕhwáֽh׃p"],[13,15,"וַ⁠יָּ֣קָם שְׁמוּאֵ֗ל וַ⁠יַּ֛עַל מִן־הַ⁠גִּלְגָּ֖ל גִּבְעַ֣ת בִּנְיָמִ֑ן וַ⁠יִּפְקֹ֣ד שָׁא֗וּל אֶת־הָ⁠עָם֙ הַ⁠נִּמְצְאִ֣ים עִמּ֔⁠וֹ כְּ⁠שֵׁ֥שׁ מֵא֖וֹת אִֽישׁ׃","wa⁠yá֣̇qám şĕ̌mẇʼé֗l wa⁠yȧ֛ʻal min-ha⁠gi̇lĕgá֖̇l gi̇bĕʻa֣ţ bi̇nĕyámi֑n wa⁠yi̇pĕqò֣d şá̌ʼ֗ẇl ʼeţ-há⁠ʻám֙ ha⁠ni̇mĕẕĕʼi֣ym ʻiṁ֔⁠wò kĕ̇⁠şé֥̌ş̌ méʼ֖wòţ ʼiֽyş̌׃"],[13,16,"וְ⁠שָׁא֞וּל וְ⁠יוֹנָתָ֣ן בְּנ֗⁠וֹ וְ⁠הָ⁠עָם֙ הַ⁠נִּמְצָ֣א עִמָּ֔⁠ם יֹשְׁבִ֖ים בְּ⁠גֶ֣בַע בִּנְיָמִ֑ן וּ⁠פְלִשְׁתִּ֖ים חָנ֥וּ בְ⁠מִכְמָֽשׂ׃","wĕ⁠şá̌ʼ֞ẇl wĕ⁠ywònáţá֣n bĕ̇n֗⁠wò wĕ⁠há⁠ʻám֙ ha⁠ni̇mĕẕá֣ʼ ʻimá̇֔⁠m yòşĕ̌bi֖ym bĕ̇⁠ge֣baʻ bi̇nĕyámi֑n ẇ⁠pĕlişĕ̌ţi֖̇ym ẖán֥ẇ bĕ⁠mikĕmáֽş̂׃"],[13,17,"וַ⁠יֵּצֵ֧א הַ⁠מַּשְׁחִ֛ית מִ⁠מַּחֲנֵ֥ה פְלִשְׁתִּ֖ים שְׁלֹשָׁ֣ה רָאשִׁ֑ים הָ⁠רֹ֨אשׁ אֶחָ֥ד יִפְנֶ֛ה אֶל־דֶּ֥רֶךְ עָפְרָ֖ה אֶל־אֶ֥רֶץ שׁוּעָֽל׃","wa⁠yé̇ẕé֧ʼ ha⁠mȧşĕ̌ẖi֛yţ mi⁠mȧẖàné֥h pĕlişĕ̌ţi֖̇ym şĕ̌lòşá֣̌h ráʼşǐ֑ym há⁠rò֨ʼş̌ ʼeẖá֥d yipĕne֛h ʼel-dė֥rekĕ ʻápĕrá֖h ʼel-ʼe֥reẕ ş̌ẇʻáֽl׃"],[13,18,"וְ⁠הָ⁠רֹ֤אשׁ אֶחָד֙ יִפְנֶ֔ה דֶּ֖רֶךְ בֵּ֣ית חֹר֑וֹן וְ⁠הָ⁠רֹ֨אשׁ אֶחָ֤ד יִפְנֶה֙ דֶּ֣רֶךְ הַ⁠גְּב֔וּל הַ⁠נִּשְׁקָ֛ף עַל־גֵּ֥י הַצְּבֹעִ֖ים הַ⁠מִּדְבָּֽרָ⁠ה׃ס","wĕ⁠há⁠rò֤ʼş̌ ʼeẖád֙ yipĕne֔h dė֖rekĕ bé֣̇yţ ẖòr֑wòn wĕ⁠há⁠rò֨ʼş̌ ʼeẖá֤d yipĕneh֙ dė֣rekĕ ha⁠gĕ̇b֔ẇl ha⁠ni̇şĕ̌qá֛p ʻal-gé֥̇y haẕĕ̇bòʻi֖ym ha⁠mi̇dĕbáֽ̇rá⁠h׃s"],[13,19,"וְ⁠חָרָשׁ֙ לֹ֣א יִמָּצֵ֔א בְּ⁠כֹ֖ל אֶ֣רֶץ יִשְׂרָאֵ֑ל כִּֽי־אמר פְלִשְׁתִּ֔ים פֶּ֚ן יַעֲשׂ֣וּ הָ⁠עִבְרִ֔ים חֶ֖רֶב א֥וֹ חֲנִֽית׃","wĕ⁠ẖáráş̌֙ lò֣ʼ yimá̇ẕé֔ʼ bĕ̇⁠kò֖l ʼe֣reẕ yişĕ̂ráʼé֑l kiֽ̇y-ʼmr pĕlişĕ̌ţi̇֔ym pė֚n yaʻàş֣̂ẇ há⁠ʻibĕri֔ym ẖe֖reb ʼ֥wò ẖàniֽyţ׃"],[13,20,"וַ⁠יֵּרְד֥וּ כָל־יִשְׂרָאֵ֖ל הַ⁠פְּלִשְׁתִּ֑ים לִ֠⁠לְטוֹשׁ אִ֣ישׁ אֶת־מַחֲרַשְׁתּ֤⁠וֹ וְ⁠אֶת־אֵת⁠וֹ֙ וְ⁠אֶת־קַרְדֻּמּ֔⁠וֹ וְ⁠אֵ֖ת מַחֲרֵשָׁתֽ⁠וֹ׃","wa⁠yé̇rĕd֥ẇ kál-yişĕ̂ráʼé֖l ha⁠pĕ̇lişĕ̌ţi֑̇ym li֠⁠lĕtwòş̌ ʼi֣yş̌ ʼeţ-maẖàraşĕ̌ţ֤̇⁠wò wĕ⁠ʼeţ-ʼéţ⁠wò֙ wĕ⁠ʼeţ-qarĕdu̇ṁ֔⁠wò wĕ⁠ʼé֖ţ maẖàréşá̌ţֽ⁠wò׃"],[13,21,"וְֽ⁠הָיְתָ֞ה הַ⁠פְּצִ֣ירָה פִ֗ים לַ⁠מַּֽחֲרֵשֹׁת֙ וְ⁠לָ֣⁠אֵתִ֔ים וְ⁠לִ⁠שְׁלֹ֥שׁ קִלְּשׁ֖וֹן וּ⁠לְ⁠הַ⁠קַּרְדֻּמִּ֑ים וּ⁠לְ⁠הַצִּ֖יב הַ⁠דָּרְבָֽן׃","wĕֽ⁠háyĕţá֞h ha⁠pĕ̇ẕi֣yráh pi֗ym la⁠mȧֽẖàréşò̌ţ֙ wĕ⁠lá֣⁠ʼéţi֔ym wĕ⁠li⁠şĕ̌lò֥ş̌ qilĕ̇ş֖̌wòn ẇ⁠lĕ⁠ha⁠qȧrĕdu̇mi֑̇ym ẇ⁠lĕ⁠haẕi֖̇yb ha⁠dá̇rĕbáֽn׃"],[13,22,"וְ⁠הָיָה֙ בְּ⁠י֣וֹם מִלְחֶ֔מֶת וְ⁠לֹ֨א נִמְצָ֜א חֶ֤רֶב וַ⁠חֲנִית֙ בְּ⁠יַ֣ד כָּל־הָ⁠עָ֔ם אֲשֶׁ֥ר אֶת־שָׁא֖וּל וְ⁠אֶת־יוֹנָתָ֑ן וַ⁠תִּמָּצֵ֣א לְ⁠שָׁא֔וּל וּ⁠לְ⁠יוֹנָתָ֖ן בְּנֽ⁠וֹ׃","wĕ⁠háyáh֙ bĕ̇⁠y֣wòm milĕẖe֔meţ wĕ⁠lò֨ʼ nimĕẕá֜ʼ ẖe֤reb wa⁠ẖàniyţ֙ bĕ̇⁠ya֣d ká̇l-há⁠ʻá֔m ʼàşě֥r ʼeţ-şá̌ʼ֖ẇl wĕ⁠ʼeţ-ywònáţá֑n wa⁠ţi̇má̇ẕé֣ʼ lĕ⁠şá̌ʼ֔ẇl ẇ⁠lĕ⁠ywònáţá֖n bĕ̇nֽ⁠wò׃"],[13,23,"וַ⁠יֵּצֵא֙ מַצַּ֣ב פְּלִשְׁתִּ֔ים אֶֽל־מַעֲבַ֖ר מִכְמָֽשׂ׃ס","wa⁠yé̇ẕéʼ֙ maẕȧ֣b pĕ̇lişĕ̌ţi̇֔ym ʼeֽl-maʻàba֖r mikĕmáֽş̂׃s"],[14,1,"וַ⁠יְהִ֣י הַ⁠יּ֗וֹם וַ⁠יֹּ֨אמֶר יוֹנָתָ֤ן בֶּן־שָׁאוּל֙ אֶל־הַ⁠נַּ֨עַר֙ נֹשֵׂ֣א כֵלָ֔י⁠ו לְכָ֗⁠ה וְ⁠נַעְבְּרָה֙ אֶל־מַצַּ֣ב פְּלִשְׁתִּ֔ים אֲשֶׁ֖ר מֵ⁠עֵ֣בֶר הַלָּ֑ז וּ⁠לְ⁠אָבִ֖י⁠ו לֹ֥א הִגִּֽיד׃","wa⁠yĕhi֣y ha⁠ẏ֗wòm wa⁠yò̇֨ʼmer ywònáţá֤n bėn-şá̌ʼẇl֙ ʼel-ha⁠nȧ֨ʻar֙ nòşé֣̂ʼ kélá֔y⁠w lĕká֗⁠h wĕ⁠naʻĕbĕ̇ráh֙ ʼel-maẕȧ֣b pĕ̇lişĕ̌ţi̇֔ym ʼàşě֖r mé⁠ʻé֣ber halá֑̇z ẇ⁠lĕ⁠ʼábi֖y⁠w lò֥ʼ higiֽ̇yd׃"],[14,2,"וְ⁠שָׁא֗וּל יוֹשֵׁב֙ בִּ⁠קְצֵ֣ה הַ⁠גִּבְעָ֔ה תַּ֥חַת הָ⁠רִמּ֖וֹן אֲשֶׁ֣ר בְּ⁠מִגְר֑וֹן וְ⁠הָ⁠עָם֙ אֲשֶׁ֣ר עִמּ֔⁠וֹ כְּ⁠שֵׁ֥שׁ מֵא֖וֹת אִֽישׁ׃","wĕ⁠şá̌ʼ֗ẇl ywòşé̌b֙ bi̇⁠qĕẕé֣h ha⁠gi̇bĕʻá֔h ţȧ֥ẖaţ há⁠riṁ֖wòn ʼàşě֣r bĕ̇⁠migĕr֑wòn wĕ⁠há⁠ʻám֙ ʼàşě֣r ʻiṁ֔⁠wò kĕ̇⁠şé֥̌ş̌ méʼ֖wòţ ʼiֽyş̌׃"],[14,3,"וַ⁠אֲחִיָּ֣ה בֶן־אֲחִט֡וּב אֲחִ֡י אִיכָב֣וֹד ׀ בֶּן־פִּינְחָ֨ס בֶּן־עֵלִ֜י כֹּהֵ֧ן ׀ יְהוָ֛ה בְּ⁠שִׁל֖וֹ נֹשֵׂ֣א אֵפ֑וֹד וְ⁠הָ⁠עָם֙ לֹ֣א יָדַ֔ע כִּ֥י הָלַ֖ךְ יוֹנָתָֽן׃","wa⁠ʼàẖiyá֣̇h ben-ʼàẖit֡ẇb ʼàẖi֡y ʼiykáb֣wòd ׀ bėn-pi̇ynĕẖá֨s bėn-ʻéli֜y kò̇hé֧n ׀ yĕhwá֛h bĕ̇⁠şǐl֖wò nòşé֣̂ʼ ʼép֑wòd wĕ⁠há⁠ʻám֙ lò֣ʼ yáda֔ʻ ki֥̇y hála֖kĕ ywònáţáֽn׃"],[14,4,"וּ⁠בֵ֣ין הַֽ⁠מַּעְבְּר֗וֹת אֲשֶׁ֨ר בִּקֵּ֤שׁ יֽוֹנָתָן֙ לַֽ⁠עֲבֹר֙ עַל־מַצַּ֣ב פְּלִשְׁתִּ֔ים שֵׁן־הַ⁠סֶּ֤לַע מֵ⁠הָ⁠עֵ֨בֶר֙ מִ⁠זֶּ֔ה וְ⁠שֵׁן־הַ⁠סֶּ֥לַע מֵ⁠הָ⁠עֵ֖בֶר מִ⁠זֶּ֑ה וְ⁠שֵׁ֤ם הָֽ⁠אֶחָד֙ בּוֹצֵ֔ץ וְ⁠שֵׁ֥ם הָ⁠אֶחָ֖ד סֶֽנֶּה׃","ẇ⁠bé֣yn haֽ⁠mȧʻĕbĕ̇r֗wòţ ʼàşě֨r bi̇qé֤̇ş̌ yֽwònáţán֙ laֽ⁠ʻàbòr֙ ʻal-maẕȧ֣b pĕ̇lişĕ̌ţi̇֔ym şé̌n-ha⁠sė֤laʻ mé⁠há⁠ʻé֨ber֙ mi⁠zė֔h wĕ⁠şé̌n-ha⁠sė֥laʻ mé⁠há⁠ʻé֖ber mi⁠zė֑h wĕ⁠şé֤̌m háֽ⁠ʼeẖád֙ ḃwòẕé֔ẕ wĕ⁠şé֥̌m há⁠ʼeẖá֖d seֽnėh׃"],[14,5,"הַ⁠שֵּׁ֧ן הָ⁠אֶחָ֛ד מָצ֥וּק מִ⁠צָּפ֖וֹן מ֣וּל מִכְמָ֑שׂ וְ⁠הָ⁠אֶחָ֥ד מִ⁠נֶּ֖גֶב מ֥וּל גָּֽבַע׃ס","ha⁠şé֧̇̌n há⁠ʼeẖá֛d máẕ֥ẇq mi⁠ẕá̇p֖wòn m֣ẇl mikĕmá֑ş̂ wĕ⁠há⁠ʼeẖá֥d mi⁠nė֖geb m֥ẇl gáֽ̇baʻ׃s"],[14,6,"וַ⁠יֹּ֨אמֶר יְהוֹנָתָ֜ן אֶל־הַ⁠נַּ֣עַר ׀ נֹשֵׂ֣א כֵלָ֗י⁠ו לְכָ⁠ה֙ וְ⁠נַעְבְּרָ֗ה אֶל־מַצַּב֙ הָ⁠עֲרֵלִ֣ים הָ⁠אֵ֔לֶּה אוּלַ֛י יַעֲשֶׂ֥ה יְהוָ֖ה לָ֑⁠נוּ כִּ֣י אֵ֤ין לַֽ⁠יהוָה֙ מַעְצ֔וֹר לְ⁠הוֹשִׁ֥יעַ בְּ⁠רַ֖ב א֥וֹ בִ⁠מְעָֽט׃","wa⁠yò̇֨ʼmer yĕhwònáţá֜n ʼel-ha⁠nȧ֣ʻar ׀ nòşé֣̂ʼ kélá֗y⁠w lĕká⁠h֙ wĕ⁠naʻĕbĕ̇rá֗h ʼel-maẕȧb֙ há⁠ʻàréli֣ym há⁠ʼé֔lėh ʼẇla֛y yaʻàşê֥h yĕhwá֖h lá֑⁠nẇ ki֣̇y ʼé֤yn laֽ⁠yhwáh֙ maʻĕẕ֔wòr lĕ⁠hwòşǐ֥yʻa bĕ̇⁠ra֖b ʼ֥wò bi⁠mĕʻáֽt׃"],[14,7,"וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ נֹשֵׂ֣א כֵלָ֔י⁠ו עֲשֵׂ֖ה כָּל־אֲשֶׁ֣ר בִּ⁠לְבָבֶ֑⁠ךָ נְטֵ֣ה לָ֔⁠ךְ הִנְ⁠נִ֥י עִמְּ⁠ךָ֖ כִּ⁠לְבָבֶֽ⁠ךָ׃ס","wa⁠yò֤̇ʼmer l⁠wò֙ nòşé֣̂ʼ kélá֔y⁠w ʻàşé֖̂h ká̇l-ʼàşě֣r bi̇⁠lĕbábe֑⁠ká nĕté֣h lá֔⁠kĕ hinĕ⁠ni֥y ʻimĕ̇⁠ká֖ ki̇⁠lĕbábeֽ⁠ká׃s"],[14,8,"וַ⁠יֹּ֨אמֶר֙ יְה֣וֹנָתָ֔ן הִנֵּ֛ה אֲנַ֥חְנוּ עֹבְרִ֖ים אֶל־הָ⁠אֲנָשִׁ֑ים וְ⁠נִגְלִ֖ינוּ אֲלֵי⁠הֶֽם׃","wa⁠yò̇֨ʼmer֙ yĕh֣wònáţá֔n hiné֛̇h ʼàna֥ẖĕnẇ ʻòbĕri֖ym ʼel-há⁠ʼànáşǐ֑ym wĕ⁠nigĕli֖ynẇ ʼàléy⁠heֽm׃"],[14,9,"אִם־כֹּ֤ה יֹֽאמְרוּ֙ אֵלֵ֔י⁠נוּ דֹּ֕מּוּ עַד־הַגִּיעֵ֖⁠נוּ אֲלֵי⁠כֶ֑ם וְ⁠עָמַ֣דְנוּ תַחְתֵּ֔י⁠נוּ וְ⁠לֹ֥א נַעֲלֶ֖ה אֲלֵי⁠הֶֽם׃","ʼim-kò֤̇h yòֽʼmĕrẇ֙ ʼélé֔y⁠nẇ dò̇֕ṁẇ ʻad-hagi̇yʻé֖⁠nẇ ʼàléy⁠ke֑m wĕ⁠ʻáma֣dĕnẇ ţaẖĕţé̇֔y⁠nẇ wĕ⁠lò֥ʼ naʻàle֖h ʼàléy⁠heֽm׃"],[14,10,"וְ⁠אִם־כֹּ֨ה יֹאמְר֜וּ עֲל֤וּ עָלֵ֨י⁠נוּ֙ וְ⁠עָלִ֔ינוּ כִּֽי־נְתָנָ֥⁠ם יְהוָ֖ה בְּ⁠יָדֵ֑⁠נוּ וְ⁠זֶה־לָּ֖⁠נוּ הָ⁠אֽוֹת׃","wĕ⁠ʼim-kò̇֨h yòʼmĕr֜ẇ ʻàl֤ẇ ʻálé֨y⁠nẇ֙ wĕ⁠ʻáli֔ynẇ kiֽ̇y-nĕţáná֥⁠m yĕhwá֖h bĕ̇⁠yádé֑⁠nẇ wĕ⁠zeh-lá֖̇⁠nẇ há⁠ʼֽwòţ׃"],[14,11,"וַ⁠יִּגָּל֣וּ שְׁנֵי⁠הֶ֔ם אֶל־מַצַּ֖ב פְּלִשְׁתִּ֑ים וַ⁠יֹּאמְר֣וּ פְלִשְׁתִּ֔ים הִנֵּ֤ה עִבְרִים֙ יֹֽצְאִ֔ים מִן־הַ⁠חֹרִ֖ים אֲשֶׁ֥ר הִתְחַבְּאוּ־שָֽׁם׃","wa⁠yi̇gá̇l֣ẇ şĕ̌néy⁠he֔m ʼel-maẕȧ֖b pĕ̇lişĕ̌ţi֑̇ym wa⁠yò̇ʼmĕr֣ẇ pĕlişĕ̌ţi̇֔ym hiné֤̇h ʻibĕriym֙ yòֽẕĕʼi֔ym min-ha⁠ẖòri֖ym ʼàşě֥r hiţĕẖabĕ̇ʼẇ-şáֽ̌m׃"],[14,12,"וַ⁠יַּעֲנוּ֩ אַנְשֵׁ֨י הַ⁠מַּצָּבָ֜ה אֶת־יוֹנָתָ֣ן ׀ וְ⁠אֶת־נֹשֵׂ֣א כֵלָ֗י⁠ו וַ⁠יֹּֽאמְרוּ֙ עֲל֣וּ אֵלֵ֔י⁠נוּ וְ⁠נוֹדִ֥יעָה אֶתְ⁠כֶ֖ם דָּבָ֑ר פ וַ⁠יֹּ֨אמֶר יוֹנָתָ֜ן אֶל־נֹשֵׂ֤א כֵלָי⁠ו֙ עֲלֵ֣ה אַחֲרַ֔⁠י כִּֽי־נְתָנָ֥⁠ם יְהוָ֖ה בְּ⁠יַ֥ד יִשְׂרָאֵֽל׃","wa⁠yȧʻànẇ֩ ʼanĕşé̌֨y ha⁠mȧẕá̇bá֜h ʼeţ-ywònáţá֣n ׀ wĕ⁠ʼeţ-nòşé֣̂ʼ kélá֗y⁠w wa⁠yòֽ̇ʼmĕrẇ֙ ʻàl֣ẇ ʼélé֔y⁠nẇ wĕ⁠nwòdi֥yʻáh ʼeţĕ⁠ke֖m dá̇bá֑r p wa⁠yò̇֨ʼmer ywònáţá֜n ʼel-nòşé֤̂ʼ kéláy⁠w֙ ʻàlé֣h ʼaẖàra֔⁠y kiֽ̇y-nĕţáná֥⁠m yĕhwá֖h bĕ̇⁠ya֥d yişĕ̂ráʼéֽl׃"],[14,13,"וַ⁠יַּ֣עַל יוֹנָתָ֗ן עַל־יָדָי⁠ו֙ וְ⁠עַל־רַגְלָ֔י⁠ו וְ⁠נֹשֵׂ֥א כֵלָ֖י⁠ו אַחֲרָ֑י⁠ו וַֽ⁠יִּפְּלוּ֙ לִ⁠פְנֵ֣י יוֹנָתָ֔ן וְ⁠נֹשֵׂ֥א כֵלָ֖י⁠ו מְמוֹתֵ֥ת אַחֲרָֽי⁠ו׃","wa⁠yȧ֣ʻal ywònáţá֗n ʻal-yádáy⁠w֙ wĕ⁠ʻal-ragĕlá֔y⁠w wĕ⁠nòşé֥̂ʼ kélá֖y⁠w ʼaẖàrá֑y⁠w waֽ⁠yi̇pĕ̇lẇ֙ li⁠pĕné֣y ywònáţá֔n wĕ⁠nòşé֥̂ʼ kélá֖y⁠w mĕmwòţé֥ţ ʼaẖàráֽy⁠w׃"],[14,14,"וַ⁠תְּהִ֞י הַ⁠מַּכָּ֣ה הָ⁠רִאשֹׁנָ֗ה אֲשֶׁ֨ר הִכָּ֧ה יוֹנָתָ֛ן וְ⁠נֹשֵׂ֥א כֵלָ֖י⁠ו כְּ⁠עֶשְׂרִ֣ים אִ֑ישׁ כְּ⁠בַ⁠חֲצִ֥י מַעֲנָ֖ה צֶ֥מֶד שָׂדֶֽה׃","wa⁠ţĕ̇hi֞y ha⁠mȧká֣̇h há⁠riʼşò̌ná֗h ʼàşě֨r hiká֧̇h ywònáţá֛n wĕ⁠nòşé֥̂ʼ kélá֖y⁠w kĕ̇⁠ʻeşĕ̂ri֣ym ʼi֑yş̌ kĕ̇⁠ba⁠ẖàẕi֥y maʻàná֖h ẕe֥med şá̂deֽh׃"],[14,15,"וַ⁠תְּהִי֩ חֲרָדָ֨ה בַ⁠מַּחֲנֶ֤ה בַ⁠שָּׂדֶה֙ וּ⁠בְ⁠כָל־הָ⁠עָ֔ם הַ⁠מַּצָּב֙ וְ⁠הַ⁠מַּשְׁחִ֔ית חָרְד֖וּ גַּם־הֵ֑מָּה וַ⁠תִּרְגַּ֣ז הָ⁠אָ֔רֶץ וַ⁠תְּהִ֖י לְ⁠חֶרְדַּ֥ת אֱלֹהִֽים׃","wa⁠ţĕ̇hiy֩ ẖàrádá֨h ba⁠mȧẖàne֤h ba⁠şá̇̂deh֙ ẇ⁠bĕ⁠kál-há⁠ʻá֔m ha⁠mȧẕá̇b֙ wĕ⁠ha⁠mȧşĕ̌ẖi֔yţ ẖárĕd֖ẇ gȧm-hé֑má̇h wa⁠ţi̇rĕgȧ֣z há⁠ʼá֔reẕ wa⁠ţĕ̇hi֖y lĕ⁠ẖerĕdȧ֥ţ ʼèlòhiֽym׃"],[14,16,"וַ⁠יִּרְא֤וּ הַ⁠צֹּפִים֙ לְ⁠שָׁא֔וּל בְּ⁠גִבְעַ֖ת בִּנְיָמִ֑ן וְ⁠הִנֵּ֧ה הֶ⁠הָמ֛וֹן נָמ֖וֹג וַ⁠יֵּ֥לֶךְ וַ⁠הֲלֹֽם׃פ","wa⁠yi̇rĕʼ֤ẇ ha⁠ẕò̇piym֙ lĕ⁠şá̌ʼ֔ẇl bĕ̇⁠gibĕʻa֖ţ bi̇nĕyámi֑n wĕ⁠hiné֧̇h he⁠hám֛wòn nám֖wòg wa⁠yé֥̇lekĕ wa⁠hàlòֽm׃p"],[14,17,"וַ⁠יֹּ֣אמֶר שָׁא֗וּל לָ⁠עָם֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ פִּקְדוּ־נָ֣א וּ⁠רְא֔וּ מִ֖י הָלַ֣ךְ מֵ⁠עִמָּ֑⁠נוּ וַֽ⁠יִּפְקְד֔וּ וְ⁠הִנֵּ֛ה אֵ֥ין יוֹנָתָ֖ן וְ⁠נֹשֵׂ֥א כֵלָֽי⁠ו׃","wa⁠yò֣̇ʼmer şá̌ʼ֗ẇl lá⁠ʻám֙ ʼàşě֣r ʼiţ̇֔⁠wò pi̇qĕdẇ-ná֣ʼ ẇ⁠rĕʼ֔ẇ mi֖y hála֣kĕ mé⁠ʻimá֑̇⁠nẇ waֽ⁠yi̇pĕqĕd֔ẇ wĕ⁠hiné֛̇h ʼé֥yn ywònáţá֖n wĕ⁠nòşé֥̂ʼ kéláֽy⁠w׃"],[14,18,"וַ⁠יֹּ֤אמֶר שָׁאוּל֙ לַֽ⁠אֲחִיָּ֔ה הַגִּ֖ישָׁ⁠ה אֲר֣וֹן הָ⁠אֱלֹהִ֑ים כִּֽי־הָיָ֞ה אֲר֧וֹן הָ⁠אֱלֹהִ֛ים בַּ⁠יּ֥וֹם הַ⁠ה֖וּא וּ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yò֤̇ʼmer şá̌ʼẇl֙ laֽ⁠ʼàẖiyá̇֔h hagi֖̇yşá̌⁠h ʼàr֣wòn há⁠ʼèlòhi֑ym kiֽ̇y-háyá֞h ʼàr֧wòn há⁠ʼèlòhi֛ym bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ ẇ⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[14,19,"וַ⁠יְהִ֗י עַ֣ד דִּבֶּ֤ר שָׁאוּל֙ אֶל־הַ⁠כֹּהֵ֔ן וְ⁠הֶ⁠הָמ֗וֹן אֲשֶׁר֙ בְּ⁠מַחֲנֵ֣ה פְלִשְׁתִּ֔ים וַ⁠יֵּ֥לֶךְ הָל֖וֹךְ וָ⁠רָ֑ב פ וַ⁠יֹּ֧אמֶר שָׁא֛וּל אֶל־הַ⁠כֹּהֵ֖ן אֱסֹ֥ף יָדֶֽ⁠ךָ׃","wa⁠yĕhi֗y ʻa֣d di̇bė֤r şá̌ʼẇl֙ ʼel-ha⁠kò̇hé֔n wĕ⁠he⁠hám֗wòn ʼàşěr֙ bĕ̇⁠maẖàné֣h pĕlişĕ̌ţi̇֔ym wa⁠yé֥̇lekĕ hál֖wòkĕ wá⁠rá֑b p wa⁠yò֧̇ʼmer şá̌ʼ֛ẇl ʼel-ha⁠kò̇hé֖n ʼèsò֥p yádeֽ⁠ká׃"],[14,20,"וַ⁠יִּזָּעֵ֣ק שָׁא֗וּל וְ⁠כָל־הָ⁠עָם֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ וַ⁠יָּבֹ֖אוּ עַד־הַ⁠מִּלְחָמָ֑ה וְ⁠הִנֵּ֨ה הָיְתָ֜ה חֶ֤רֶב אִישׁ֙ בְּ⁠רֵעֵ֔⁠הוּ מְהוּמָ֖ה גְּדוֹלָ֥ה מְאֹֽד׃","wa⁠yi̇zá̇ʻé֣q şá̌ʼ֗ẇl wĕ⁠kál-há⁠ʻám֙ ʼàşě֣r ʼiţ̇֔⁠wò wa⁠yá̇bò֖ʼẇ ʻad-ha⁠mi̇lĕẖámá֑h wĕ⁠hiné̇֨h háyĕţá֜h ẖe֤reb ʼiyş̌֙ bĕ̇⁠réʻé֔⁠hẇ mĕhẇmá֖h gĕ̇dwòlá֥h mĕʼòֽd׃"],[14,21,"וְ⁠הָ⁠עִבְרִ֗ים הָי֤וּ לַ⁠פְּלִשְׁתִּים֙ כְּ⁠אֶתְמ֣וֹל שִׁלְשׁ֔וֹם אֲשֶׁ֨ר עָל֥וּ עִמָּ֛⁠ם בַּֽ⁠מַּחֲנֶ֖ה סָבִ֑יב וְ⁠גַם־הֵ֗מָּה לִֽ⁠הְיוֹת֙ עִם־יִשְׂרָאֵ֔ל אֲשֶׁ֥ר עִם־שָׁא֖וּל וְ⁠יוֹנָתָֽן׃","wĕ⁠há⁠ʻibĕri֗ym háy֤ẇ la⁠pĕ̇lişĕ̌ţi̇ym֙ kĕ̇⁠ʼeţĕm֣wòl şǐlĕş̌֔wòm ʼàşě֨r ʻál֥ẇ ʻimá֛̇⁠m bȧֽ⁠mȧẖàne֖h sábi֑yb wĕ⁠gam-hé֗má̇h liֽ⁠hĕywòţ֙ ʻim-yişĕ̂ráʼé֔l ʼàşě֥r ʻim-şá̌ʼ֖ẇl wĕ⁠ywònáţáֽn׃"],[14,22,"וְ⁠כֹל֩ אִ֨ישׁ יִשְׂרָאֵ֜ל הַ⁠מִּֽתְחַבְּאִ֤ים בְּ⁠הַר־אֶפְרַ֨יִם֙ שָֽׁמְע֔וּ כִּֽי־נָ֖סוּ פְּלִשְׁתִּ֑ים וַֽ⁠יַּדְבְּק֥וּ גַם־הֵ֛מָּה אַחֲרֵי⁠הֶ֖ם בַּ⁠מִּלְחָמָֽה׃","wĕ⁠kòl֩ ʼi֨yş̌ yişĕ̂ráʼé֜l ha⁠miֽ̇ţĕẖabĕ̇ʼi֤ym bĕ̇⁠har-ʼepĕra֨yim֙ şáֽ̌mĕʻ֔ẇ kiֽ̇y-ná֖sẇ pĕ̇lişĕ̌ţi֑̇ym waֽ⁠yȧdĕbĕ̇q֥ẇ gam-hé֛má̇h ʼaẖàréy⁠he֖m bȧ⁠mi̇lĕẖámáֽh׃"],[14,23,"וַ⁠יּ֧וֹשַׁע יְהוָ֛ה בַּ⁠יּ֥וֹם הַ⁠ה֖וּא אֶת־יִשְׂרָאֵ֑ל וְ⁠הַ֨⁠מִּלְחָמָ֔ה עָבְרָ֖ה אֶת־בֵּ֥ית אָֽוֶן׃","wa⁠ẏ֧wòşǎʻ yĕhwá֛h bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ ʼeţ-yişĕ̂ráʼé֑l wĕ⁠ha֨⁠mi̇lĕẖámá֔h ʻábĕrá֖h ʼeţ-bé֥̇yţ ʼáֽwen׃"],[14,24,"וְ⁠אִֽישׁ־יִשְׂרָאֵ֥ל נִגַּ֖שׂ בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וַ⁠יֹּאֶל֩ שָׁא֨וּל אֶת־הָ⁠עָ֜ם לֵ⁠אמֹ֗ר אָר֣וּר הָ֠⁠אִישׁ אֲשֶׁר־יֹ֨אכַל לֶ֜חֶם עַד־הָ⁠עֶ֗רֶב וְ⁠נִקַּמְתִּי֙ מֵ⁠אֹ֣יְבַ֔⁠י וְ⁠לֹֽא טָעַ֥ם כָּל־הָ⁠עָ֖ם לָֽחֶם׃ס","wĕ⁠ʼiֽyş̌-yişĕ̂ráʼé֥l nigȧ֖ş̂ bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wa⁠yò̇ʼel֩ şá̌ʼ֨ẇl ʼeţ-há⁠ʻá֜m lé⁠ʼmò֗r ʼár֣ẇr há֠⁠ʼiyş̌ ʼàşěr-yò֨ʼkal le֜ẖem ʻad-há⁠ʻe֗reb wĕ⁠niqȧmĕţi̇y֙ mé⁠ʼò֣yĕba֔⁠y wĕ⁠lòֽʼ táʻa֥m ká̇l-há⁠ʻá֖m láֽẖem׃s"],[14,25,"וְ⁠כָל־הָ⁠אָ֖רֶץ בָּ֣אוּ בַ⁠יָּ֑עַר וַ⁠יְהִ֥י דְבַ֖שׁ עַל־פְּנֵ֥י הַ⁠שָּׂדֶֽה׃","wĕ⁠kál-há⁠ʼá֖reẕ bá֣̇ʼẇ ba⁠yá֑̇ʻar wa⁠yĕhi֥y dĕba֖ş̌ ʻal-pĕ̇né֥y ha⁠şá̇̂deֽh׃"],[14,26,"וַ⁠יָּבֹ֤א הָ⁠עָם֙ אֶל־הַ⁠יַּ֔עַר וְ⁠הִנֵּ֖ה הֵ֣לֶךְ דְּבָ֑שׁ וְ⁠אֵין־מַשִּׂ֤יג יָד⁠וֹ֙ אֶל־פִּ֔י⁠ו כִּֽי־יָרֵ֥א הָ⁠עָ֖ם אֶת־הַ⁠שְּׁבֻעָֽה׃","wa⁠yá̇bò֤ʼ há⁠ʻám֙ ʼel-ha⁠yȧ֔ʻar wĕ⁠hiné֖̇h hé֣lekĕ dĕ̇bá֑ş̌ wĕ⁠ʼéyn-maşi֤̇̂yg yád⁠wò֙ ʼel-pi̇֔y⁠w kiֽ̇y-yáré֥ʼ há⁠ʻá֖m ʼeţ-ha⁠şĕ̇̌buʻáֽh׃"],[14,27,"וְ⁠יוֹנָתָ֣ן לֹֽא־שָׁמַ֗ע בְּ⁠הַשְׁבִּ֣יעַ אָבִי⁠ו֮ אֶת־הָ⁠עָם֒ וַ⁠יִּשְׁלַ֗ח אֶת־קְצֵ֤ה הַ⁠מַּטֶּה֙ אֲשֶׁ֣ר בְּ⁠יָד֔⁠וֹ וַ⁠יִּטְבֹּ֥ל אוֹתָ֖⁠הּ בְּ⁠יַעְרַ֣ת הַ⁠דְּבָ֑שׁ וַ⁠יָּ֤שֶׁב יָד⁠וֹ֙ אֶל־פִּ֔י⁠ו ו⁠תראנה עֵינָֽי⁠ו׃","wĕ⁠ywònáţá֣n lòֽʼ-şá̌ma֗ʻ bĕ̇⁠haşĕ̌bi֣̇yʻa ʼábiy⁠w֮ ʼeţ-há⁠ʻám֒ wa⁠yi̇şĕ̌la֗ẖ ʼeţ-qĕẕé֤h ha⁠mȧtėh֙ ʼàşě֣r bĕ̇⁠yád֔⁠wò wa⁠yi̇tĕbò֥̇l ʼwòţá֖⁠ḣ bĕ̇⁠yaʻĕra֣ţ ha⁠dĕ̇bá֑ş̌ wa⁠yá֤̇şěb yád⁠wò֙ ʼel-pi̇֔y⁠w w⁠ţrʼnh ʻéynáֽy⁠w׃"],[14,28,"וַ⁠יַּעַן֩ אִ֨ישׁ מֵֽ⁠הָ⁠עָ֜ם וַ⁠יֹּ֗אמֶר הַשְׁבֵּעַ֩ הִשְׁבִּ֨יעַ אָבִ֤י⁠ךָ אֶת־הָ⁠עָם֙ לֵ⁠אמֹ֔ר אָר֥וּר הָ⁠אִ֛ישׁ אֲשֶׁר־יֹ֥אכַל לֶ֖חֶם הַ⁠יּ֑וֹם וַ⁠יָּ֖עַף הָ⁠עָֽם׃","wa⁠yȧʻan֩ ʼi֨yş̌ méֽ⁠há⁠ʻá֜m wa⁠yò̇֗ʼmer haşĕ̌bé̇ʻa֩ hişĕ̌bi̇֨yʻa ʼábi֤y⁠ká ʼeţ-há⁠ʻám֙ lé⁠ʼmò֔r ʼár֥ẇr há⁠ʼi֛yş̌ ʼàşěr-yò֥ʼkal le֖ẖem ha⁠ẏ֑wòm wa⁠yá֖̇ʻap há⁠ʻáֽm׃"],[14,29,"וַ⁠יֹּ֨אמֶר֙ יֽוֹנָתָ֔ן עָכַ֥ר אָבִ֖⁠י אֶת־הָ⁠אָ֑רֶץ רְאוּ־נָא֙ כִּֽי־אֹ֣רוּ עֵינַ֔⁠י כִּ֣י טָעַ֔מְתִּי מְעַ֖ט דְּבַ֥שׁ הַ⁠זֶּֽה׃","wa⁠yò̇֨ʼmer֙ yֽwònáţá֔n ʻáka֥r ʼábi֖⁠y ʼeţ-há⁠ʼá֑reẕ rĕʼẇ-náʼ֙ kiֽ̇y-ʼò֣rẇ ʻéyna֔⁠y ki֣̇y táʻa֔mĕţi̇y mĕʻa֖t dĕ̇ba֥ş̌ ha⁠zėֽh׃"],[14,30,"אַ֗ף כִּ֡י לוּא֩ אָכֹ֨ל אָכַ֤ל הַ⁠יּוֹם֙ הָ⁠עָ֔ם מִ⁠שְּׁלַ֥ל אֹיְבָ֖י⁠ו אֲשֶׁ֣ר מָצָ֑א כִּ֥י עַתָּ֛ה לֹֽא־רָבְתָ֥ה מַכָּ֖ה בַּ⁠פְּלִשְׁתִּֽים׃","ʼa֗p ki̇֡y lẇʼ֩ ʼákò֨l ʼáka֤l ha⁠ẏwòm֙ há⁠ʻá֔m mi⁠şĕ̇̌la֥l ʼòyĕbá֖y⁠w ʼàşě֣r máẕá֑ʼ ki֥̇y ʻaţá֛̇h lòֽʼ-rábĕţá֥h maká֖̇h bȧ⁠pĕ̇lişĕ̌ţiֽ̇ym׃"],[14,31,"וַ⁠יַּכּ֞וּ בַּ⁠יּ֤וֹם הַ⁠הוּא֙ בַּ⁠פְּלִשְׁתִּ֔ים מִ⁠מִּכְמָ֖שׂ אַיָּלֹ֑נָ⁠ה וַ⁠יָּ֥עַף הָ⁠עָ֖ם מְאֹֽד׃","wa⁠yȧk̇֞ẇ bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ bȧ⁠pĕ̇lişĕ̌ţi̇֔ym mi⁠mi̇kĕmá֖ş̂ ʼayá̇lò֑ná⁠h wa⁠yá֥̇ʻap há⁠ʻá֖m mĕʼòֽd׃"],[14,32,"ו⁠יעש הָ⁠עָם֙ אֶל־שלל וַ⁠יִּקְח֨וּ צֹ֧אן וּ⁠בָקָ֛ר וּ⁠בְנֵ֥י בָקָ֖ר וַ⁠יִּשְׁחֲטוּ־אָ֑רְצָ⁠ה וַ⁠יֹּ֥אכַל הָ⁠עָ֖ם עַל־הַ⁠דָּֽם׃","w⁠yʻş há⁠ʻám֙ ʼel-şll wa⁠yi̇qĕẖ֨ẇ ẕò֧ʼn ẇ⁠báqá֛r ẇ⁠bĕné֥y báqá֖r wa⁠yi̇şĕ̌ẖàtẇ-ʼá֑rĕẕá⁠h wa⁠yò֥̇ʼkal há⁠ʻá֖m ʻal-ha⁠dáֽ̇m׃"],[14,33,"וַ⁠יַּגִּ֤ידוּ לְ⁠שָׁאוּל֙ לֵ⁠אמֹ֔ר הִנֵּ֥ה הָ⁠עָ֛ם חֹטִ֥אים לַֽ⁠יהוָ֖ה לֶ⁠אֱכֹ֣ל עַל־הַ⁠דָּ֑ם וַ⁠יֹּ֣אמֶר בְּגַדְתֶּ֔ם גֹּֽלּוּ־אֵלַ֥⁠י הַ⁠יּ֖וֹם אֶ֥בֶן גְּדוֹלָֽה׃","wa⁠yȧgi֤̇ydẇ lĕ⁠şá̌ʼẇl֙ lé⁠ʼmò֔r hiné֥̇h há⁠ʻá֛m ẖòti֥ʼym laֽ⁠yhwá֖h le⁠ʼèkò֣l ʻal-ha⁠dá֑̇m wa⁠yò֣̇ʼmer bĕ̇gadĕţė֔m gòֽ̇l̇ẇ-ʼéla֥⁠y ha⁠ẏ֖wòm ʼe֥ben gĕ̇dwòláֽh׃"],[14,34,"וַ⁠יֹּ֣אמֶר שָׁא֣וּל פֻּ֣צוּ בָ⁠עָ֡ם וַ⁠אֲמַרְתֶּ֣ם לָ⁠הֶ֡ם הַגִּ֣ישׁוּ אֵלַ⁠י֩ אִ֨ישׁ שׁוֹר֜⁠וֹ וְ⁠אִ֣ישׁ שְׂיֵ֗⁠הוּ וּ⁠שְׁחַטְתֶּ֤ם בָּ⁠זֶה֙ וַ⁠אֲכַלְתֶּ֔ם וְ⁠לֹֽא־תֶחֶטְא֥וּ לַֽ⁠יהוָ֖ה לֶ⁠אֱכֹ֣ל אֶל־הַ⁠דָּ֑ם וַ⁠יַּגִּ֨שׁוּ כָל־הָ⁠עָ֜ם אִ֣ישׁ שׁוֹר֧⁠וֹ בְ⁠יָד֛⁠וֹ הַ⁠לַּ֖יְלָה וַ⁠יִּשְׁחֲטוּ־שָֽׁם׃","wa⁠yò֣̇ʼmer şá̌ʼ֣ẇl pu֣̇ẕẇ bá⁠ʻá֡m wa⁠ʼàmarĕţė֣m lá⁠he֡m hagi֣̇yş̌ẇ ʼéla⁠y֩ ʼi֨yş̌ ş̌wòr֜⁠wò wĕ⁠ʼi֣yş̌ şĕ̂yé֗⁠hẇ ẇ⁠şĕ̌ẖatĕţė֤m bá̇⁠zeh֙ wa⁠ʼàkalĕţė֔m wĕ⁠lòֽʼ-ţeẖetĕʼ֥ẇ laֽ⁠yhwá֖h le⁠ʼèkò֣l ʼel-ha⁠dá֑̇m wa⁠yȧgi̇֨ş̌ẇ kál-há⁠ʻá֜m ʼi֣yş̌ ş̌wòr֧⁠wò bĕ⁠yád֛⁠wò ha⁠lȧ֖yĕláh wa⁠yi̇şĕ̌ẖàtẇ-şáֽ̌m׃"],[14,35,"וַ⁠יִּ֧בֶן שָׁא֛וּל מִזְבֵּ֖חַ לַֽ⁠יהוָ֑ה אֹת֣⁠וֹ הֵחֵ֔ל לִ⁠בְנ֥וֹת מִזְבֵּ֖חַ לַֽ⁠יהוָֽה׃פ","wa⁠yi֧̇ben şá̌ʼ֛ẇl mizĕbé֖̇ẖa laֽ⁠yhwá֑h ʼòţ֣⁠wò héẖé֔l li⁠bĕn֥wòţ mizĕbé֖̇ẖa laֽ⁠yhwáֽh׃p"],[14,36,"וַ⁠יֹּ֣אמֶר שָׁא֡וּל נֵרְדָ֣ה אַחֲרֵי֩ פְלִשְׁתִּ֨ים ׀ לַ֜יְלָה וְֽ⁠נָבֹ֥זָה בָ⁠הֶ֣ם ׀ עַד־א֣וֹר הַ⁠בֹּ֗קֶר וְ⁠לֹֽא־נַשְׁאֵ֤ר בָּ⁠הֶם֙ אִ֔ישׁ וַ⁠יֹּ֣אמְר֔וּ כָּל־הַ⁠טּ֥וֹב בְּ⁠עֵינֶ֖י⁠ךָ עֲשֵׂ֑ה ס וַ⁠יֹּ֨אמֶר֙ הַ⁠כֹּהֵ֔ן נִקְרְבָ֥ה הֲלֹ֖ם אֶל־הָ⁠אֱלֹהִֽים׃","wa⁠yò֣̇ʼmer şá̌ʼ֡ẇl nérĕdá֣h ʼaẖàréy֩ pĕlişĕ̌ţi̇֨ym ׀ la֜yĕláh wĕֽ⁠nábò֥záh bá⁠he֣m ׀ ʻad-ʼ֣wòr ha⁠bò̇֗qer wĕ⁠lòֽʼ-naşĕ̌ʼé֤r bá̇⁠hem֙ ʼi֔yş̌ wa⁠yò֣̇ʼmĕr֔ẇ ká̇l-ha⁠ṫ֥wòb bĕ̇⁠ʻéyne֖y⁠ká ʻàşé֑̂h s wa⁠yò̇֨ʼmer֙ ha⁠kò̇hé֔n niqĕrĕbá֥h hàlò֖m ʼel-há⁠ʼèlòhiֽym׃"],[14,37,"וַ⁠יִּשְׁאַ֤ל שָׁאוּל֙ בֵּֽ⁠אלֹהִ֔ים הַֽ⁠אֵרֵד֙ אַחֲרֵ֣י פְלִשְׁתִּ֔ים הֲ⁠תִתְּנֵ֖⁠ם בְּ⁠יַ֣ד יִשְׂרָאֵ֑ל וְ⁠לֹ֥א עָנָ֖⁠הוּ בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","wa⁠yi̇şĕ̌ʼa֤l şá̌ʼẇl֙ béֽ̇⁠ʼlòhi֔ym haֽ⁠ʼéréd֙ ʼaẖàré֣y pĕlişĕ̌ţi̇֔ym hà⁠ţiţĕ̇né֖⁠m bĕ̇⁠ya֣d yişĕ̂ráʼé֑l wĕ⁠lò֥ʼ ʻáná֖⁠hẇ bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"],[14,38,"וַ⁠יֹּ֣אמֶר שָׁא֔וּל גֹּ֣שֽׁוּ הֲלֹ֔ם כֹּ֖ל פִּנּ֣וֹת הָ⁠עָ֑ם וּ⁠דְע֣וּ וּ⁠רְא֔וּ בַּ⁠מָּ֗ה הָֽיְתָ֛ה הַ⁠חַטָּ֥את הַ⁠זֹּ֖את הַ⁠יּֽוֹם׃","wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl gò֣̇şֽ̌ẇ hàlò֔m kò֖̇l pi̇ṅ֣wòţ há⁠ʻá֑m ẇ⁠dĕʻ֣ẇ ẇ⁠rĕʼ֔ẇ bȧ⁠má̇֗h háֽyĕţá֛h ha⁠ẖatá֥̇ʼţ ha⁠zò֖̇ʼţ ha⁠ẏֽwòm׃"],[14,39,"כִּ֣י חַי־יְהוָ֗ה הַ⁠מּוֹשִׁ֨יעַ֙ אֶת־יִשְׂרָאֵ֔ל כִּ֧י אִם־יֶשְׁנ֛⁠וֹ בְּ⁠יוֹנָתָ֥ן בְּנִ֖⁠י כִּ֣י מ֣וֹת יָמ֑וּת וְ⁠אֵ֥ין עֹנֵ֖⁠הוּ מִ⁠כָּל־הָ⁠עָֽם׃","ki֣̇y ẖay-yĕhwá֗h ha⁠ṁwòşǐ֨yʻa֙ ʼeţ-yişĕ̂ráʼé֔l ki֧̇y ʼim-yeşĕ̌n֛⁠wò bĕ̇⁠ywònáţá֥n bĕ̇ni֖⁠y ki֣̇y m֣wòţ yám֑ẇţ wĕ⁠ʼé֥yn ʻòné֖⁠hẇ mi⁠ká̇l-há⁠ʻáֽm׃"],[14,40,"וַ⁠יֹּ֣אמֶר אֶל־כָּל־יִשְׂרָאֵ֗ל אַתֶּם֙ תִּֽהְיוּ֙ לְ⁠עֵ֣בֶר אֶחָ֔ד וַֽ⁠אֲנִי֙ וְ⁠יוֹנָתָ֣ן בְּנִ֔⁠י נִהְיֶ֖ה לְ⁠עֵ֣בֶר אֶחָ֑ד וַ⁠יֹּאמְר֤וּ הָ⁠עָם֙ אֶל־שָׁא֔וּל הַ⁠טּ֥וֹב בְּ⁠עֵינֶ֖י⁠ךָ עֲשֵֽׂה׃ס","wa⁠yò֣̇ʼmer ʼel-ká̇l-yişĕ̂ráʼé֗l ʼaţėm֙ ţiֽ̇hĕyẇ֙ lĕ⁠ʻé֣ber ʼeẖá֔d waֽ⁠ʼàniy֙ wĕ⁠ywònáţá֣n bĕ̇ni֔⁠y nihĕye֖h lĕ⁠ʻé֣ber ʼeẖá֑d wa⁠yò̇ʼmĕr֤ẇ há⁠ʻám֙ ʼel-şá̌ʼ֔ẇl ha⁠ṫ֥wòb bĕ̇⁠ʻéyne֖y⁠ká ʻàşéֽ̂h׃s"],[14,41,"וַ⁠יֹּ֣אמֶר שָׁא֗וּל אֶל־יְהוָ֛ה אֱלֹהֵ֥י יִשְׂרָאֵ֖ל הָ֣בָ⁠ה תָמִ֑ים וַ⁠יִּלָּכֵ֧ד יוֹנָתָ֛ן וְ⁠שָׁא֖וּל וְ⁠הָ⁠עָ֥ם יָצָֽאוּ׃","wa⁠yò֣̇ʼmer şá̌ʼ֗ẇl ʼel-yĕhwá֛h ʼèlòhé֥y yişĕ̂ráʼé֖l há֣bá⁠h ţámi֑ym wa⁠yi̇lá̇ké֧d ywònáţá֛n wĕ⁠şá̌ʼ֖ẇl wĕ⁠há⁠ʻá֥m yáẕáֽʼẇ׃"],[14,42,"וַ⁠יֹּ֣אמֶר שָׁא֔וּל הַפִּ֕ילוּ בֵּינִ֕⁠י וּ⁠בֵ֖ין יוֹנָתָ֣ן בְּנִ֑⁠י וַ⁠יִּלָּכֵ֖ד יוֹנָתָֽן׃","wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl hapi̇֕ylẇ bé̇yni֕⁠y ẇ⁠bé֖yn ywònáţá֣n bĕ̇ni֑⁠y wa⁠yi̇lá̇ké֖d ywònáţáֽn׃"],[14,43,"וַ⁠יֹּ֤אמֶר שָׁאוּל֙ אֶל־י֣וֹנָתָ֔ן הַגִּ֥ידָ⁠ה לִּ֖⁠י מֶ֣ה עָשִׂ֑יתָה וַ⁠יַּגֶּד־ל֣⁠וֹ יוֹנָתָ֗ן וַ⁠יֹּאמֶר֩ טָעֹ֨ם טָעַ֜מְתִּי בִּ⁠קְצֵ֨ה הַ⁠מַּטֶּ֧ה אֲשֶׁר־בְּ⁠יָדִ֛⁠י מְעַ֥ט דְּבַ֖שׁ הִנְ⁠נִ֥י אָמֽוּת׃","wa⁠yò֤̇ʼmer şá̌ʼẇl֙ ʼel-y֣wònáţá֔n hagi֥̇ydá⁠h li֖̇⁠y me֣h ʻáşî֑yţáh wa⁠yȧgėd-l֣⁠wò ywònáţá֗n wa⁠yò̇ʼmer֩ táʻò֨m táʻa֜mĕţi̇y bi̇⁠qĕẕé֨h ha⁠mȧtė֧h ʼàşěr-bĕ̇⁠yádi֛⁠y mĕʻa֥t dĕ̇ba֖ş̌ hinĕ⁠ni֥y ʼámֽẇţ׃"],[14,44,"וַ⁠יֹּ֣אמֶר שָׁא֔וּל כֹּֽה־יַעֲשֶׂ֥ה אֱלֹהִ֖ים וְ⁠כֹ֣ה יוֹסִ֑ף כִּֽי־מ֥וֹת תָּמ֖וּת יוֹנָתָֽן׃","wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl kòֽ̇h-yaʻàşê֥h ʼèlòhi֖ym wĕ⁠kò֣h ywòsi֑p kiֽ̇y-m֥wòţ ţá̇m֖ẇţ ywònáţáֽn׃"],[14,45,"וַ⁠יֹּ֨אמֶר הָ⁠עָ֜ם אֶל־שָׁא֗וּל הֲֽ⁠יוֹנָתָ֤ן ׀ יָמוּת֙ אֲשֶׁ֣ר עָ֠שָׂה הַ⁠יְשׁוּעָ֨ה הַ⁠גְּדוֹלָ֣ה הַ⁠זֹּאת֮ בְּ⁠יִשְׂרָאֵל֒ חָלִ֗ילָ⁠ה חַי־יְהוָה֙ אִם־יִפֹּ֞ל מִ⁠שַּׂעֲרַ֤ת רֹאשׁ⁠וֹ֙ אַ֔רְצָ⁠ה כִּֽי־עִם־אֱלֹהִ֥ים עָשָׂ֖ה הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וַ⁠יִּפְדּ֥וּ הָ⁠עָ֛ם אֶת־יוֹנָתָ֖ן וְ⁠לֹא־מֵֽת׃ס","wa⁠yò̇֨ʼmer há⁠ʻá֜m ʼel-şá̌ʼ֗ẇl hàֽ⁠ywònáţá֤n ׀ yámẇţ֙ ʼàşě֣r ʻá֠şá̂h ha⁠yĕş̌ẇʻá֨h ha⁠gĕ̇dwòlá֣h ha⁠zò̇ʼţ֮ bĕ̇⁠yişĕ̂ráʼél֒ ẖáli֗ylá⁠h ẖay-yĕhwáh֙ ʼim-yipò̇֞l mi⁠şȧ̂ʻàra֤ţ ròʼş̌⁠wò֙ ʼa֔rĕẕá⁠h kiֽ̇y-ʻim-ʼèlòhi֥ym ʻáşá֖̂h ha⁠ẏ֣wòm ha⁠zė֑h wa⁠yi̇pĕḋ֥ẇ há⁠ʻá֛m ʼeţ-ywònáţá֖n wĕ⁠lòʼ-méֽţ׃s"],[14,46,"וַ⁠יַּ֣עַל שָׁא֔וּל מֵ⁠אַחֲרֵ֖י פְּלִשְׁתִּ֑ים וּ⁠פְלִשְׁתִּ֖ים הָלְכ֥וּ לִ⁠מְקוֹמָֽ⁠ם׃","wa⁠yȧ֣ʻal şá̌ʼ֔ẇl mé⁠ʼaẖàré֖y pĕ̇lişĕ̌ţi֑̇ym ẇ⁠pĕlişĕ̌ţi֖̇ym hálĕk֥ẇ li⁠mĕqwòmáֽ⁠m׃"],[14,47,"וְ⁠שָׁא֛וּל לָכַ֥ד הַ⁠מְּלוּכָ֖ה עַל־יִשְׂרָאֵ֑ל וַ⁠יִּלָּ֣חֶם סָבִ֣יב ׀ בְּֽ⁠כָל־אֹיְבָ֡י⁠ו בְּ⁠מוֹאָ֣ב ׀ וּ⁠בִ⁠בְנֵי־עַמּ֨וֹן וּ⁠בֶ⁠אֱד֜וֹם וּ⁠בְ⁠מַלְכֵ֤י צוֹבָה֙ וּ⁠בַ⁠פְּלִשְׁתִּ֔ים וּ⁠בְ⁠כֹ֥ל אֲשֶׁר־יִפְנֶ֖ה יַרְשִֽׁיעַ׃","wĕ⁠şá̌ʼ֛ẇl láka֥d ha⁠mĕ̇lẇká֖h ʻal-yişĕ̂ráʼé֑l wa⁠yi̇lá֣̇ẖem sábi֣yb ׀ bĕֽ̇⁠kál-ʼòyĕbá֡y⁠w bĕ̇⁠mwòʼá֣b ׀ ẇ⁠bi⁠bĕnéy-ʻaṁ֨wòn ẇ⁠be⁠ʼèd֜wòm ẇ⁠bĕ⁠malĕké֤y ẕwòbáh֙ ẇ⁠ba⁠pĕ̇lişĕ̌ţi̇֔ym ẇ⁠bĕ⁠kò֥l ʼàşěr-yipĕne֖h yarĕşǐֽyʻa׃"],[14,48,"וַ⁠יַּ֣עַשׂ חַ֔יִל וַ⁠יַּ֖ךְ אֶת־עֲמָלֵ֑ק וַ⁠יַּצֵּ֥ל אֶת־יִשְׂרָאֵ֖ל מִ⁠יַּ֥ד שֹׁסֵֽ⁠הוּ׃ס","wa⁠yȧ֣ʻaş̂ ẖa֔yil wa⁠yȧ֖kĕ ʼeţ-ʻàmálé֑q wa⁠yȧẕé֥̇l ʼeţ-yişĕ̂ráʼé֖l mi⁠yȧ֥d şò̌séֽ⁠hẇ׃s"],[14,49,"וַ⁠יִּֽהְיוּ֙ בְּנֵ֣י שָׁא֔וּל יוֹנָתָ֥ן וְ⁠יִשְׁוִ֖י וּ⁠מַלְכִּי־שׁ֑וּעַ וְ⁠שֵׁם֙ שְׁתֵּ֣י בְנֹתָ֔י⁠ו שֵׁ֤ם הַ⁠בְּכִירָה֙ מֵרַ֔ב וְ⁠שֵׁ֥ם הַ⁠קְּטַנָּ֖ה מִיכַֽל׃","wa⁠yiֽ̇hĕyẇ֙ bĕ̇né֣y şá̌ʼ֔ẇl ywònáţá֥n wĕ⁠yişĕ̌wi֖y ẇ⁠malĕki̇y-ş֑̌ẇʻa wĕ⁠şé̌m֙ şĕ̌ţé֣̇y bĕnòţá֔y⁠w şé֤̌m ha⁠bĕ̇kiyráh֙ méra֔b wĕ⁠şé֥̌m ha⁠qĕ̇taná֖̇h miykaֽl׃"],[14,50,"וְ⁠שֵׁם֙ אֵ֣שֶׁת שָׁא֔וּל אֲחִינֹ֖עַם בַּת־אֲחִימָ֑עַץ וְ⁠שֵׁ֤ם שַׂר־צְבָא⁠וֹ֙ אֲבִינֵ֔ר בֶּן־נֵ֖ר דּ֥וֹד שָׁאֽוּל׃","wĕ⁠şé̌m֙ ʼé֣şěţ şá̌ʼ֔ẇl ʼàẖiynò֖ʻam bȧţ-ʼàẖiymá֑ʻaẕ wĕ⁠şé֤̌m şâr-ẕĕbáʼ⁠wò֙ ʼàbiyné֔r bėn-né֖r ḋ֥wòd şá̌ʼֽẇl׃"],[14,51,"וְ⁠קִ֧ישׁ אֲבִֽי־שָׁא֛וּל וְ⁠נֵ֥ר אֲבִֽי־אַבְנֵ֖ר בֶּן־אֲבִיאֵֽל׃ס","wĕ⁠qi֧yş̌ ʼàbiֽy-şá̌ʼ֛ẇl wĕ⁠né֥r ʼàbiֽy-ʼabĕné֖r bėn-ʼàbiyʼéֽl׃s"],[14,52,"וַ⁠תְּהִ֤י הַ⁠מִּלְחָמָה֙ חֲזָקָ֣ה עַל־פְּלִשְׁתִּ֔ים כֹּ֖ל יְמֵ֣י שָׁא֑וּל וְ⁠רָאָ֨ה שָׁא֜וּל כָּל־אִ֤ישׁ גִּבּוֹר֙ וְ⁠כָל־בֶּן־חַ֔יִל וַ⁠יַּאַסְפֵ֖⁠הוּ אֵלָֽי⁠ו׃ס","wa⁠ţĕ̇hi֤y ha⁠mi̇lĕẖámáh֙ ẖàzáqá֣h ʻal-pĕ̇lişĕ̌ţi̇֔ym kò֖̇l yĕmé֣y şá̌ʼ֑ẇl wĕ⁠ráʼá֨h şá̌ʼ֜ẇl ká̇l-ʼi֤yş̌ gi̇ḃwòr֙ wĕ⁠kál-bėn-ẖa֔yil wa⁠yȧʼasĕpé֖⁠hẇ ʼéláֽy⁠w׃s"],[15,1,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־שָׁא֔וּל אֹתִ֨⁠י שָׁלַ֤ח יְהוָה֙ לִ⁠מְשָׁחֳ⁠ךָ֣ לְ⁠מֶ֔לֶךְ עַל־עַמּ֖⁠וֹ עַל־יִשְׂרָאֵ֑ל וְ⁠עַתָּ֣ה שְׁמַ֔ע לְ⁠ק֖וֹל דִּבְרֵ֥י יְהוָֽה׃ס","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-şá̌ʼ֔ẇl ʼòţi֨⁠y şá̌la֤ẖ yĕhwáh֙ li⁠mĕşá̌ẖo⁠ká֣ lĕ⁠me֔lekĕ ʻal-ʻaṁ֖⁠wò ʻal-yişĕ̂ráʼé֑l wĕ⁠ʻaţá֣̇h şĕ̌ma֔ʻ lĕ⁠q֖wòl di̇bĕré֥y yĕhwáֽh׃s"],[15,2,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת פָּקַ֕דְתִּי אֵ֛ת אֲשֶׁר־עָשָׂ֥ה עֲמָלֵ֖ק לְ⁠יִשְׂרָאֵ֑ל אֲשֶׁר־שָׂ֥ם ל⁠וֹ֙ בַּ⁠דֶּ֔רֶךְ בַּ⁠עֲלֹת֖⁠וֹ מִ⁠מִּצְרָֽיִם׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ pá̇qa֕dĕţi̇y ʼé֛ţ ʼàşěr-ʻáşá֥̂h ʻàmálé֖q lĕ⁠yişĕ̂ráʼé֑l ʼàşěr-şá֥̂m l⁠wò֙ bȧ⁠dė֔rekĕ bȧ⁠ʻàlòţ֖⁠wò mi⁠mi̇ẕĕráֽyim׃"],[15,3,"עַתָּה֩ לֵ֨ךְ וְ⁠הִכִּֽיתָ֜ה אֶת־עֲמָלֵ֗ק וְ⁠הַֽחֲרַמְתֶּם֙ אֶת־כָּל־אֲשֶׁר־ל֔⁠וֹ וְ⁠לֹ֥א תַחְמֹ֖ל עָלָ֑י⁠ו וְ⁠הֵמַתָּ֞ה מֵ⁠אִ֣ישׁ עַד־אִשָּׁ֗ה מֵֽ⁠עֹלֵל֙ וְ⁠עַד־יוֹנֵ֔ק מִ⁠שּׁ֣וֹר וְ⁠עַד־שֶׂ֔ה מִ⁠גָּמָ֖ל וְ⁠עַד־חֲמֽוֹר׃ס","ʻaţá̇h֩ lé֨kĕ wĕ⁠hikiֽ̇yţá֜h ʼeţ-ʻàmálé֗q wĕ⁠haֽẖàramĕţėm֙ ʼeţ-ká̇l-ʼàşěr-l֔⁠wò wĕ⁠lò֥ʼ ţaẖĕmò֖l ʻálá֑y⁠w wĕ⁠hémaţá̇֞h mé⁠ʼi֣yş̌ ʻad-ʼişá̇̌֗h méֽ⁠ʻòlél֙ wĕ⁠ʻad-ywòné֔q mi⁠ş֣̇̌wòr wĕ⁠ʻad-şê֔h mi⁠gá̇má֖l wĕ⁠ʻad-ẖàmֽwòr׃s"],[15,4,"וַ⁠יְשַׁמַּ֤ע שָׁאוּל֙ אֶת־הָ⁠עָ֔ם וַֽ⁠יִּפְקְדֵ⁠ם֙ בַּ⁠טְּלָאִ֔ים מָאתַ֥יִם אֶ֖לֶף רַגְלִ֑י וַ⁠עֲשֶׂ֥רֶת אֲלָפִ֖ים אֶת־אִ֥ישׁ יְהוּדָֽה׃","wa⁠yĕşǎmȧ֤ʻ şá̌ʼẇl֙ ʼeţ-há⁠ʻá֔m waֽ⁠yi̇pĕqĕdé⁠m֙ bȧ⁠tĕ̇láʼi֔ym máʼţa֥yim ʼe֖lep ragĕli֑y wa⁠ʻàşê֥reţ ʼàlápi֖ym ʼeţ-ʼi֥yş̌ yĕhẇdáֽh׃"],[15,5,"וַ⁠יָּבֹ֥א שָׁא֖וּל עַד־עִ֣יר עֲמָלֵ֑ק וַ⁠יָּ֖רֶב בַּ⁠נָּֽחַל׃","wa⁠yá̇bò֥ʼ şá̌ʼ֖ẇl ʻad-ʻi֣yr ʻàmálé֑q wa⁠yá֖̇reb bȧ⁠náֽ̇ẖal׃"],[15,6,"וַ⁠יֹּ֣אמֶר שָׁא֣וּל אֶֽל־הַ⁠קֵּינִ֡י לְכוּ֩ סֻּ֨רוּ רְד֜וּ מִ⁠תּ֣וֹךְ עֲמָלֵקִ֗י פֶּן־אֹֽסִפְ⁠ךָ֙ עִמּ֔⁠וֹ וְ⁠אַתָּ֞ה עָשִׂ֤יתָה חֶ֨סֶד֙ עִם־כָּל־בְּנֵ֣י יִשְׂרָאֵ֔ל בַּ⁠עֲלוֹתָ֖⁠ם מִ⁠מִּצְרָ֑יִם וַ⁠יָּ֥סַר קֵינִ֖י מִ⁠תּ֥וֹךְ עֲמָלֵֽק׃","wa⁠yò֣̇ʼmer şá̌ʼ֣ẇl ʼeֽl-ha⁠qé̇yni֡y lĕkẇ֩ su̇֨rẇ rĕd֜ẇ mi⁠ţ֣̇wòkĕ ʻàmáléqi֗y pėn-ʼòֽsipĕ⁠ká֙ ʻiṁ֔⁠wò wĕ⁠ʼaţá̇֞h ʻáşî֤yţáh ẖe֨sed֙ ʻim-ká̇l-bĕ̇né֣y yişĕ̂ráʼé֔l bȧ⁠ʻàlwòţá֖⁠m mi⁠mi̇ẕĕrá֑yim wa⁠yá֥̇sar qéyni֖y mi⁠ţ֥̇wòkĕ ʻàmáléֽq׃"],[15,7,"וַ⁠יַּ֥ךְ שָׁא֖וּל אֶת־עֲמָלֵ֑ק מֵֽ⁠חֲוִילָה֙ בּוֹאֲ⁠ךָ֣ שׁ֔וּר אֲשֶׁ֖ר עַל־פְּנֵ֥י מִצְרָֽיִם׃","wa⁠yȧ֥kĕ şá̌ʼ֖ẇl ʼeţ-ʻàmálé֑q méֽ⁠ẖàwiyláh֙ ḃwòʼà⁠ká֣ ş̌֔ẇr ʼàşě֖r ʻal-pĕ̇né֥y miẕĕráֽyim׃"],[15,8,"וַ⁠יִּתְפֹּ֛שׂ אֶת־אֲגַ֥ג מֶֽלֶךְ־עֲמָלֵ֖ק חָ֑י וְ⁠אֶת־כָּל־הָ⁠עָ֖ם הֶחֱרִ֥ים לְ⁠פִי־חָֽרֶב׃","wa⁠yi̇ţĕpò֛̇ş̂ ʼeţ-ʼàga֥g meֽlekĕ-ʻàmálé֖q ẖá֑y wĕ⁠ʼeţ-ká̇l-há⁠ʻá֖m heẖèri֥ym lĕ⁠piy-ẖáֽreb׃"],[15,9,"וַ⁠יַּחְמֹל֩ שָׁא֨וּל וְ⁠הָ⁠עָ֜ם עַל־אֲגָ֗ג וְ⁠עַל־מֵיטַ֣ב הַ⁠צֹּאן֩ וְ⁠הַ⁠בָּקָ֨ר וְ⁠הַ⁠מִּשְׁנִ֤ים וְ⁠עַל־הַ⁠כָּרִים֙ וְ⁠עַל־כָּל־הַ⁠טּ֔וֹב וְ⁠לֹ֥א אָב֖וּ הַחֲרִימָ֑⁠ם וְ⁠כָל־הַ⁠מְּלָאכָ֛ה נְמִבְזָ֥ה וְ⁠נָמֵ֖ס אֹתָ֥⁠הּ הֶחֱרִֽימוּ׃פ","wa⁠yȧẖĕmòl֩ şá̌ʼ֨ẇl wĕ⁠há⁠ʻá֜m ʻal-ʼàgá֗g wĕ⁠ʻal-méyta֣b ha⁠ẕò̇ʼn֩ wĕ⁠ha⁠bá̇qá֨r wĕ⁠ha⁠mi̇şĕ̌ni֤ym wĕ⁠ʻal-ha⁠ká̇riym֙ wĕ⁠ʻal-ká̇l-ha⁠ṫ֔wòb wĕ⁠lò֥ʼ ʼáb֖ẇ haẖàriymá֑⁠m wĕ⁠kál-ha⁠mĕ̇láʼká֛h nĕmibĕzá֥h wĕ⁠námé֖s ʼòţá֥⁠ḣ heẖèriֽymẇ׃p"],[15,10,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־שְׁמוּאֵ֖ל לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-şĕ̌mẇʼé֖l lé⁠ʼmòֽr׃"],[15,11,"נִחַ֗מְתִּי כִּֽי־הִמְלַ֤כְתִּי אֶת־שָׁאוּל֙ לְ⁠מֶ֔לֶךְ כִּֽי־שָׁב֙ מֵ⁠אַֽחֲרַ֔⁠י וְ⁠אֶת־דְּבָרַ֖⁠י לֹ֣א הֵקִ֑ים וַ⁠יִּ֨חַר֙ לִ⁠שְׁמוּאֵ֔ל וַ⁠יִּזְעַ֥ק אֶל־יְהוָ֖ה כָּל־הַ⁠לָּֽיְלָה׃","niẖa֗mĕţi̇y kiֽ̇y-himĕla֤kĕţi̇y ʼeţ-şá̌ʼẇl֙ lĕ⁠me֔lekĕ kiֽ̇y-şá̌b֙ mé⁠ʼaֽẖàra֔⁠y wĕ⁠ʼeţ-dĕ̇bára֖⁠y lò֣ʼ héqi֑ym wa⁠yi̇֨ẖar֙ li⁠şĕ̌mẇʼé֔l wa⁠yi̇zĕʻa֥q ʼel-yĕhwá֖h ká̇l-ha⁠láֽ̇yĕláh׃"],[15,12,"וַ⁠יַּשְׁכֵּ֧ם שְׁמוּאֵ֛ל לִ⁠קְרַ֥את שָׁא֖וּל בַּ⁠בֹּ֑קֶר וַ⁠יֻּגַּ֨ד לִ⁠שְׁמוּאֵ֜ל לֵ⁠אמֹ֗ר בָּֽא־שָׁא֤וּל הַ⁠כַּרְמֶ֨לָ⁠ה֙ וְ⁠הִנֵּ֨ה מַצִּ֥יב ל⁠וֹ֙ יָ֔ד וַ⁠יִּסֹּב֙ וַֽ⁠יַּעֲבֹ֔ר וַ⁠יֵּ֖רֶד הַ⁠גִּלְגָּֽל׃","wa⁠yȧşĕ̌ké֧̇m şĕ̌mẇʼé֛l li⁠qĕra֥ʼţ şá̌ʼ֖ẇl bȧ⁠bò֑̇qer wa⁠yu̇gȧ֨d li⁠şĕ̌mẇʼé֜l lé⁠ʼmò֗r báֽ̇ʼ-şá̌ʼ֤ẇl ha⁠kȧrĕme֨lá⁠h֙ wĕ⁠hiné̇֨h maẕi֥̇yb l⁠wò֙ yá֔d wa⁠yi̇sò̇b֙ waֽ⁠yȧʻàbò֔r wa⁠yé֖̇red ha⁠gi̇lĕgáֽ̇l׃"],[15,13,"וַ⁠יָּבֹ֥א שְׁמוּאֵ֖ל אֶל־שָׁא֑וּל וַ⁠יֹּ֧אמֶר ל֣⁠וֹ שָׁא֗וּל בָּר֤וּךְ אַתָּה֙ לַֽ⁠יהוָ֔ה הֲקִימֹ֖תִי אֶת־דְּבַ֥ר יְהוָֽה׃","wa⁠yá̇bò֥ʼ şĕ̌mẇʼé֖l ʼel-şá̌ʼ֑ẇl wa⁠yò֧̇ʼmer l֣⁠wò şá̌ʼ֗ẇl bá̇r֤ẇkĕ ʼaţá̇h֙ laֽ⁠yhwá֔h hàqiymò֖ţiy ʼeţ-dĕ̇ba֥r yĕhwáֽh׃"],[15,14,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֔ל וּ⁠מֶ֛ה קֽוֹל־הַ⁠צֹּ֥אן הַ⁠זֶּ֖ה בְּ⁠אָזְנָ֑⁠י וְ⁠ק֣וֹל הַ⁠בָּקָ֔ר אֲשֶׁ֥ר אָנֹכִ֖י שֹׁמֵֽעַ׃","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֔l ẇ⁠me֛h qֽwòl-ha⁠ẕò֥̇ʼn ha⁠zė֖h bĕ̇⁠ʼázĕná֑⁠y wĕ⁠q֣wòl ha⁠bá̇qá֔r ʼàşě֥r ʼánòki֖y şò̌méֽʻa׃"],[15,15,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל מֵ⁠עֲמָלֵקִ֣י הֱבִיא֗וּ⁠ם אֲשֶׁ֨ר חָמַ֤ל הָ⁠עָם֙ עַל־מֵיטַ֤ב הַ⁠צֹּאן֙ וְ⁠הַ⁠בָּקָ֔ר לְמַ֥עַן זְבֹ֖חַ לַ⁠יהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠אֶת־הַ⁠יּוֹתֵ֖ר הֶחֱרַֽמְנוּ׃ס","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl mé⁠ʻàmáléqi֣y hèbiyʼ֗ẇ⁠m ʼàşě֨r ẖáma֤l há⁠ʻám֙ ʻal-méyta֤b ha⁠ẕò̇ʼn֙ wĕ⁠ha⁠bá̇qá֔r lĕma֥ʻan zĕbò֖ẖa la⁠yhwá֣h ʼèlòhe֑y⁠ká wĕ⁠ʼeţ-ha⁠ẏwòţé֖r heẖèraֽmĕnẇ׃s"],[15,16,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־שָׁא֔וּל הֶ֚רֶף וְ⁠אַגִּ֣ידָה לְּ⁠ךָ֔ אֵת֩ אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה אֵלַ֖⁠י הַ⁠לָּ֑יְלָה ו⁠יאמרו ל֖⁠וֹ דַּבֵּֽר׃ס","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-şá̌ʼ֔ẇl he֚rep wĕ⁠ʼagi֣̇ydáh lĕ̇⁠ká֔ ʼéţ֩ ʼàşě֨r di̇bė֧r yĕhwá֛h ʼéla֖⁠y ha⁠lá֑̇yĕláh w⁠yʼmrw l֖⁠wò dȧbéֽ̇r׃s"],[15,17,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֔ל הֲ⁠ל֗וֹא אִם־קָטֹ֤ן אַתָּה֙ בְּ⁠עֵינֶ֔י⁠ךָ רֹ֛אשׁ שִׁבְטֵ֥י יִשְׂרָאֵ֖ל אָ֑תָּה וַ⁠יִּמְשָׁחֲ⁠ךָ֧ יְהוָ֛ה לְ⁠מֶ֖לֶךְ עַל־יִשְׂרָאֵֽל׃","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֔l hà⁠l֗wòʼ ʼim-qátò֤n ʼaţá̇h֙ bĕ̇⁠ʻéyne֔y⁠ká rò֛ʼş̌ şǐbĕté֥y yişĕ̂ráʼé֖l ʼá֑ţá̇h wa⁠yi̇mĕşá̌ẖà⁠ká֧ yĕhwá֛h lĕ⁠me֖lekĕ ʻal-yişĕ̂ráʼéֽl׃"],[15,18,"וַ⁠יִּשְׁלָחֲ⁠ךָ֥ יְהוָ֖ה בְּ⁠דָ֑רֶךְ וַ⁠יֹּ֗אמֶר לֵ֣ךְ וְ⁠הַחֲרַמְתָּ֞ה אֶת־הַֽ⁠חַטָּאִים֙ אֶת־עֲמָלֵ֔ק וְ⁠נִלְחַמְתָּ֣ ב֔⁠וֹ עַ֥ד כַּלּוֹתָ֖⁠ם אֹתָֽ⁠ם׃","wa⁠yi̇şĕ̌láẖà⁠ká֥ yĕhwá֖h bĕ̇⁠dá֑rekĕ wa⁠yò̇֗ʼmer lé֣kĕ wĕ⁠haẖàramĕţá̇֞h ʼeţ-haֽ⁠ẖatá̇ʼiym֙ ʼeţ-ʻàmálé֔q wĕ⁠nilĕẖamĕţá֣̇ b֔⁠wò ʻa֥d kȧl̇wòţá֖⁠m ʼòţáֽ⁠m׃"],[15,19,"וְ⁠לָ֥⁠מָּה לֹא־שָׁמַ֖עְתָּ בְּ⁠ק֣וֹל יְהוָ֑ה וַ⁠תַּ֨עַט֙ אֶל־הַ⁠שָּׁלָ֔ל וַ⁠תַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֥י יְהוָֽה׃ס","wĕ⁠lá֥⁠má̇h lòʼ-şá̌ma֖ʻĕţá̇ bĕ̇⁠q֣wòl yĕhwá֑h wa⁠ţȧ֨ʻat֙ ʼel-ha⁠şá̇̌lá֔l wa⁠ţȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh׃s"],[15,20,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל אֶל־שְׁמוּאֵ֗ל אֲשֶׁ֤ר שָׁמַ֨עְתִּי֙ בְּ⁠ק֣וֹל יְהוָ֔ה וָ⁠אֵלֵ֕ךְ בַּ⁠דֶּ֖רֶךְ אֲשֶׁר־שְׁלָחַ֣⁠נִי יְהוָ֑ה וָ⁠אָבִ֗יא אֶת־אֲגַג֙ מֶ֣לֶךְ עֲמָלֵ֔ק וְ⁠אֶת־עֲמָלֵ֖ק הֶחֱרַֽמְתִּי׃","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl ʼel-şĕ̌mẇʼé֗l ʼàşě֤r şá̌ma֨ʻĕţi̇y֙ bĕ̇⁠q֣wòl yĕhwá֔h wá⁠ʼélé֕kĕ bȧ⁠dė֖rekĕ ʼàşěr-şĕ̌láẖa֣⁠niy yĕhwá֑h wá⁠ʼábi֗yʼ ʼeţ-ʼàgag֙ me֣lekĕ ʻàmálé֔q wĕ⁠ʼeţ-ʻàmálé֖q heẖèraֽmĕţi̇y׃"],[15,21,"וַ⁠יִּקַּ֨ח הָ⁠עָ֧ם מֵ⁠הַ⁠שָּׁלָ֛ל צֹ֥אן וּ⁠בָקָ֖ר רֵאשִׁ֣ית הַ⁠חֵ֑רֶם לִ⁠זְבֹּ֛חַ לַֽ⁠יהוָ֥ה אֱלֹהֶ֖י⁠ךָ בַּ⁠גִּלְגָּֽל׃","wa⁠yi̇qȧ֨ẖ há⁠ʻá֧m mé⁠ha⁠şá̇̌lá֛l ẕò֥ʼn ẇ⁠báqá֖r réʼşǐ֣yţ ha⁠ẖé֑rem li⁠zĕbò֛̇ẖa laֽ⁠yhwá֥h ʼèlòhe֖y⁠ká bȧ⁠gi̇lĕgáֽ̇l׃"],[15,22,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֗ל הַ⁠חֵ֤פֶץ לַֽ⁠יהוָה֙ בְּ⁠עֹל֣וֹת וּ⁠זְבָחִ֔ים כִּ⁠שְׁמֹ֖עַ בְּ⁠ק֣וֹל יְהוָ֑ה הִנֵּ֤ה שְׁמֹ֨עַ֙ מִ⁠זֶּ֣בַח ט֔וֹב לְ⁠הַקְשִׁ֖יב מֵ⁠חֵ֥לֶב אֵילִֽים׃","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֗l ha⁠ẖé֤peẕ laֽ⁠yhwáh֙ bĕ̇⁠ʻòl֣wòţ ẇ⁠zĕbáẖi֔ym ki̇⁠şĕ̌mò֖ʻa bĕ̇⁠q֣wòl yĕhwá֑h hiné֤̇h şĕ̌mò֨ʻa֙ mi⁠zė֣baẖ t֔wòb lĕ⁠haqĕşǐ֖yb mé⁠ẖé֥leb ʼéylֽiym׃"],[15,23,"כִּ֤י חַטַּאת־קֶ֨סֶם֙ מֶ֔רִי וְ⁠אָ֥וֶן וּ⁠תְרָפִ֖ים הַפְצַ֑ר יַ֗עַן מָאַ֨סְתָּ֙ אֶת־דְּבַ֣ר יְהוָ֔ה וַ⁠יִּמְאָסְ⁠ךָ֖ מִ⁠מֶּֽלֶךְ׃ס","ki֤̇y ẖatȧʼţ-qe֨sem֙ me֔riy wĕ⁠ʼá֥wen ẇ⁠ţĕrápi֖ym hapĕẕa֑r ya֗ʻan máʼa֨sĕţá̇֙ ʼeţ-dĕ̇ba֣r yĕhwá֔h wa⁠yi̇mĕʼásĕ⁠ká֖ mi⁠mėֽlekĕ׃s"],[15,24,"וַ⁠יֹּ֨אמֶר שָׁא֤וּל אֶל־שְׁמוּאֵל֙ חָטָ֔אתִי כִּֽי־עָבַ֥רְתִּי אֶת־פִּֽי־יְהוָ֖ה וְ⁠אֶת־דְּבָרֶ֑י⁠ךָ כִּ֤י יָרֵ֨אתִי֙ אֶת־הָ⁠עָ֔ם וָ⁠אֶשְׁמַ֖ע בְּ⁠קוֹלָֽ⁠ם׃","wa⁠yò̇֨ʼmer şá̌ʼ֤ẇl ʼel-şĕ̌mẇʼél֙ ẖátá֔ʼţiy kiֽ̇y-ʻába֥rĕţi̇y ʼeţ-piֽ̇y-yĕhwá֖h wĕ⁠ʼeţ-dĕ̇báre֑y⁠ká ki֤̇y yáré֨ʼţiy֙ ʼeţ-há⁠ʻá֔m wá⁠ʼeşĕ̌ma֖ʻ bĕ̇⁠qwòláֽ⁠m׃"],[15,25,"וְ⁠עַתָּ֕ה שָׂ֥א נָ֖א אֶת־חַטָּאתִ֑⁠י וְ⁠שׁ֣וּב עִמִּ֔⁠י וְ⁠אֶֽשְׁתַּחֲוֶ֖ה לַֽ⁠יהוָֽה׃","wĕ⁠ʻaţá̇֕h şá֥̂ʼ ná֖ʼ ʼeţ-ẖatá̇ʼţi֑⁠y wĕ⁠ş֣̌ẇb ʻimi̇֔⁠y wĕ⁠ʼeֽşĕ̌ţȧẖàwe֖h laֽ⁠yhwáֽh׃"],[15,26,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־שָׁא֔וּל לֹ֥א אָשׁ֖וּב עִמָּ֑⁠ךְ כִּ֤י מָאַ֨סְתָּה֙ אֶת־דְּבַ֣ר יְהוָ֔ה וַ⁠יִּמְאָסְ⁠ךָ֣ יְהוָ֔ה מִ⁠הְי֥וֹת מֶ֖לֶךְ עַל־יִשְׂרָאֵֽל׃ס","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-şá̌ʼ֔ẇl lò֥ʼ ʼáş֖̌ẇb ʻimá֑̇⁠kĕ ki֤̇y máʼa֨sĕţá̇h֙ ʼeţ-dĕ̇ba֣r yĕhwá֔h wa⁠yi̇mĕʼásĕ⁠ká֣ yĕhwá֔h mi⁠hĕy֥wòţ me֖lekĕ ʻal-yişĕ̂ráʼéֽl׃s"],[15,27,"וַ⁠יִּסֹּ֥ב שְׁמוּאֵ֖ל לָ⁠לֶ֑כֶת וַ⁠יַּחֲזֵ֥ק בִּ⁠כְנַף־מְעִיל֖⁠וֹ וַ⁠יִּקָּרַֽע׃","wa⁠yi̇sò֥̇b şĕ̌mẇʼé֖l lá⁠le֑keţ wa⁠yȧẖàzé֥q bi̇⁠kĕnap-mĕʻiyl֖⁠wò wa⁠yi̇qá̇raֽʻ׃"],[15,28,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ שְׁמוּאֵ֔ל קָרַ֨ע יְהוָ֜ה אֶֽת־מַמְלְכ֧וּת יִשְׂרָאֵ֛ל מֵ⁠עָלֶ֖י⁠ךָ הַ⁠יּ֑וֹם וּ⁠נְתָנָ֕⁠הּ לְ⁠רֵעֲ⁠ךָ֖ הַ⁠טּ֥וֹב מִמֶּֽ⁠ךָּ׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ şĕ̌mẇʼé֔l qára֨ʻ yĕhwá֜h ʼeֽţ-mamĕlĕk֧ẇţ yişĕ̂ráʼé֛l mé⁠ʻále֖y⁠ká ha⁠ẏ֑wòm ẇ⁠nĕţáná֕⁠ḣ lĕ⁠réʻà⁠ká֖ ha⁠ṫ֥wòb mimėֽ⁠ká̇׃"],[15,29,"וְ⁠גַם֙ נֵ֣צַח יִשְׂרָאֵ֔ל לֹ֥א יְשַׁקֵּ֖ר וְ⁠לֹ֣א יִנָּחֵ֑ם כִּ֣י לֹ֥א אָדָ֛ם ה֖וּא לְ⁠הִנָּחֵֽם׃","wĕ⁠gam֙ né֣ẕaẖ yişĕ̂ráʼé֔l lò֥ʼ yĕşǎqé֖̇r wĕ⁠lò֣ʼ yiná̇ẖé֑m ki֣̇y lò֥ʼ ʼádá֛m h֖ẇʼ lĕ⁠hiná̇ẖéֽm׃"],[15,30,"וַ⁠יֹּ֣אמֶר חָטָ֔אתִי עַתָּ֗ה כַּבְּדֵ֥⁠נִי נָ֛א נֶ֥גֶד זִקְנֵֽי־עַמִּ֖⁠י וְ⁠נֶ֣גֶד יִשְׂרָאֵ֑ל וְ⁠שׁ֣וּב עִמִּ֔⁠י וְ⁠הִֽשְׁתַּחֲוֵ֖יתִי לַֽ⁠יהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wa⁠yò֣̇ʼmer ẖátá֔ʼţiy ʻaţá̇֗h kȧbĕ̇dé֥⁠niy ná֛ʼ ne֥ged ziqĕnéֽy-ʻami֖̇⁠y wĕ⁠ne֣ged yişĕ̂ráʼé֑l wĕ⁠ş֣̌ẇb ʻimi̇֔⁠y wĕ⁠hiֽşĕ̌ţȧẖàwé֖yţiy laֽ⁠yhwá֥h ʼèlòheֽy⁠ká׃"],[15,31,"וַ⁠יָּ֥שָׁב שְׁמוּאֵ֖ל אַחֲרֵ֣י שָׁא֑וּל וַ⁠יִּשְׁתַּ֥חוּ שָׁא֖וּל לַֽ⁠יהוָֽה׃ס","wa⁠yá֥̇şá̌b şĕ̌mẇʼé֖l ʼaẖàré֣y şá̌ʼ֑ẇl wa⁠yi̇şĕ̌ţȧ֥ẖẇ şá̌ʼ֖ẇl laֽ⁠yhwáֽh׃s"],[15,32,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֗ל הַגִּ֤ישׁוּ אֵלַ⁠י֙ אֶת־אֲגַג֙ מֶ֣לֶךְ עֲמָלֵ֔ק וַ⁠יֵּ֣לֶךְ אֵלָ֔י⁠ו אֲגַ֖ג מַעֲדַנֹּ֑ת וַ⁠יֹּ֣אמֶר אֲגָ֔ג אָכֵ֖ן סָ֥ר מַר־הַ⁠מָּֽוֶת׃ס","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֗l hagi֤̇yş̌ẇ ʼéla⁠y֙ ʼeţ-ʼàgag֙ me֣lekĕ ʻàmálé֔q wa⁠yé֣̇lekĕ ʼélá֔y⁠w ʼàga֖g maʻàdanò֑̇ţ wa⁠yò֣̇ʼmer ʼàgá֔g ʼáké֖n sá֥r mar-ha⁠máֽ̇weţ׃s"],[15,33,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֔ל כַּ⁠אֲשֶׁ֨ר שִׁכְּלָ֤ה נָשִׁים֙ חַרְבֶּ֔⁠ךָ כֵּן־תִּשְׁכַּ֥ל מִ⁠נָּשִׁ֖ים אִמֶּ֑⁠ךָ וַ⁠יְשַׁסֵּ֨ף שְׁמוּאֵ֧ל אֶת־אֲגָ֛ג לִ⁠פְנֵ֥י יְהוָ֖ה בַּ⁠גִּלְגָּֽל׃ס","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֔l kȧ⁠ʼàşě֨r şǐkĕ̇lá֤h náşǐym֙ ẖarĕbė֔⁠ká ké̇n-ţi̇şĕ̌kȧ֥l mi⁠ná̇şǐ֖ym ʼimė֑⁠ká wa⁠yĕşǎsé̇֨p şĕ̌mẇʼé֧l ʼeţ-ʼàgá֛g li⁠pĕné֥y yĕhwá֖h bȧ⁠gi̇lĕgáֽ̇l׃s"],[15,34,"וַ⁠יֵּ֥לֶךְ שְׁמוּאֵ֖ל הָ⁠רָמָ֑תָ⁠ה וְ⁠שָׁא֛וּל עָלָ֥ה אֶל־בֵּית֖⁠וֹ גִּבְעַ֥ת שָׁאֽוּל׃","wa⁠yé֥̇lekĕ şĕ̌mẇʼé֖l há⁠rámá֑ţá⁠h wĕ⁠şá̌ʼ֛ẇl ʻálá֥h ʼel-bé̇yţ֖⁠wò gi̇bĕʻa֥ţ şá̌ʼֽẇl׃"],[15,35,"וְ⁠לֹא־יָסַ֨ף שְׁמוּאֵ֜ל לִ⁠רְא֤וֹת אֶת־שָׁאוּל֙ עַד־י֣וֹם מוֹת֔⁠וֹ כִּֽי־הִתְאַבֵּ֥ל שְׁמוּאֵ֖ל אֶל־שָׁא֑וּל וַ⁠יהוָ֣ה נִחָ֔ם כִּֽי־הִמְלִ֥יךְ אֶת־שָׁא֖וּל עַל־יִשְׂרָאֵֽל׃פ","wĕ⁠lòʼ-yása֨p şĕ̌mẇʼé֜l li⁠rĕʼ֤wòţ ʼeţ-şá̌ʼẇl֙ ʻad-y֣wòm mwòţ֔⁠wò kiֽ̇y-hiţĕʼabé֥̇l şĕ̌mẇʼé֖l ʼel-şá̌ʼ֑ẇl wa⁠yhwá֣h niẖá֔m kiֽ̇y-himĕli֥ykĕ ʼeţ-şá̌ʼ֖ẇl ʻal-yişĕ̂ráʼéֽl׃p"],[16,1,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־שְׁמוּאֵ֗ל עַד־מָתַי֙ אַתָּה֙ מִתְאַבֵּ֣ל אֶל־שָׁא֔וּל וַ⁠אֲנִ֣י מְאַסְתִּ֔י⁠ו מִ⁠מְּלֹ֖ךְ עַל־יִשְׂרָאֵ֑ל מַלֵּ֨א קַרְנְ⁠ךָ֜ שֶׁ֗מֶן וְ⁠לֵ֤ךְ אֶֽשְׁלָחֲ⁠ךָ֙ אֶל־יִשַׁ֣י בֵּֽית־הַלַּחְמִ֔י כִּֽי־רָאִ֧יתִי בְּ⁠בָנָ֛י⁠ו לִ֖⁠י מֶֽלֶךְ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-şĕ̌mẇʼé֗l ʻad-máţay֙ ʼaţá̇h֙ miţĕʼabé֣̇l ʼel-şá̌ʼ֔ẇl wa⁠ʼàni֣y mĕʼasĕţi̇֔y⁠w mi⁠mĕ̇lò֖kĕ ʻal-yişĕ̂ráʼé֑l malé̇֨ʼ qarĕnĕ⁠ká֜ şě֗men wĕ⁠lé֤kĕ ʼeֽşĕ̌láẖà⁠ká֙ ʼel-yişǎ֣y béֽ̇yţ-halȧẖĕmi֔y kiֽ̇y-ráʼi֧yţiy bĕ̇⁠báná֛y⁠w li֖⁠y meֽlekĕ׃"],[16,2,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֵ֣יךְ אֵלֵ֔ךְ וְ⁠שָׁמַ֥ע שָׁא֖וּל וַ⁠הֲרָגָ֑⁠נִי ס וַ⁠יֹּ֣אמֶר יְהוָ֗ה עֶגְלַ֤ת בָּקָר֙ תִּקַּ֣ח בְּ⁠יָדֶ֔⁠ךָ וְ⁠אָ֣מַרְתָּ֔ לִ⁠זְבֹּ֥חַ לַֽ⁠יהוָ֖ה בָּֽאתִי׃","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼé֣ykĕ ʼélé֔kĕ wĕ⁠şá̌ma֥ʻ şá̌ʼ֖ẇl wa⁠hàrágá֑⁠niy s wa⁠yò֣̇ʼmer yĕhwá֗h ʻegĕla֤ţ bá̇qár֙ ţi̇qȧ֣ẖ bĕ̇⁠yáde֔⁠ká wĕ⁠ʼá֣marĕţá̇֔ li⁠zĕbò֥̇ẖa laֽ⁠yhwá֖h báֽ̇ʼţiy׃"],[16,3,"וְ⁠קָרָ֥אתָ לְ⁠יִשַׁ֖י בַּ⁠זָּ֑בַח וְ⁠אָֽנֹכִ֗י אוֹדִֽיעֲ⁠ךָ֙ אֵ֣ת אֲשֶֽׁר־תַּעֲשֶׂ֔ה וּ⁠מָשַׁחְתָּ֣ לִ֔⁠י אֵ֥ת אֲשֶׁר־אֹמַ֖ר אֵלֶֽי⁠ךָ׃","wĕ⁠qárá֥ʼţá lĕ⁠yişǎ֖y bȧ⁠zá֑̇baẖ wĕ⁠ʼáֽnòki֗y ʼwòdiֽyʻà⁠ká֙ ʼé֣ţ ʼàşěֽr-ţȧʻàşê֔h ẇ⁠máşǎẖĕţá֣̇ li֔⁠y ʼé֥ţ ʼàşěr-ʼòma֖r ʼéleֽy⁠ká׃"],[16,4,"וַ⁠יַּ֣עַשׂ שְׁמוּאֵ֗ל אֵ֚ת אֲשֶׁ֣ר דִּבֶּ֣ר יְהוָ֔ה וַ⁠יָּבֹ֖א בֵּ֣ית לָ֑חֶם וַ⁠יֶּחֶרְד֞וּ זִקְנֵ֤י הָ⁠עִיר֙ לִ⁠קְרָאת֔⁠וֹ וַ⁠יֹּ֖אמֶר שָׁלֹ֥ם בּוֹאֶֽ⁠ךָ׃","wa⁠yȧ֣ʻaş̂ şĕ̌mẇʼé֗l ʼé֚ţ ʼàşě֣r di̇bė֣r yĕhwá֔h wa⁠yá̇bò֖ʼ bé֣̇yţ lá֑ẖem wa⁠yėẖerĕd֞ẇ ziqĕné֤y há⁠ʻiyr֙ li⁠qĕráʼţ֔⁠wò wa⁠yò֖̇ʼmer şá̌lò֥m ḃwòʼeֽ⁠ká׃"],[16,5,"וַ⁠יֹּ֣אמֶר ׀ שָׁל֗וֹם לִ⁠זְבֹּ֤חַ לַֽ⁠יהוָה֙ בָּ֔אתִי הִֽתְקַדְּשׁ֔וּ וּ⁠בָאתֶ֥ם אִתִּ֖⁠י בַּ⁠זָּ֑בַח וַ⁠יְקַדֵּ֤שׁ אֶת־יִשַׁי֙ וְ⁠אֶת־בָּנָ֔י⁠ו וַ⁠יִּקְרָ֥א לָ⁠הֶ֖ם לַ⁠זָּֽבַח׃","wa⁠yò֣̇ʼmer ׀ şá̌l֗wòm li⁠zĕbò֤̇ẖa laֽ⁠yhwáh֙ bá̇֔ʼţiy hiֽţĕqadĕ̇ş̌֔ẇ ẇ⁠báʼţe֥m ʼiţi֖̇⁠y bȧ⁠zá֑̇baẖ wa⁠yĕqadé֤̇ş̌ ʼeţ-yişǎy֙ wĕ⁠ʼeţ-bá̇ná֔y⁠w wa⁠yi̇qĕrá֥ʼ lá⁠he֖m la⁠záֽ̇baẖ׃"],[16,6,"וַ⁠יְהִ֣י בְּ⁠בוֹאָ֔⁠ם וַ⁠יַּ֖רְא אֶת־אֱלִיאָ֑ב וַ⁠יֹּ֕אמֶר אַ֛ךְ נֶ֥גֶד יְהוָ֖ה מְשִׁיחֽ⁠וֹ׃","wa⁠yĕhi֣y bĕ̇⁠bwòʼá֔⁠m wa⁠yȧ֖rĕʼ ʼeţ-ʼèliyʼá֑b wa⁠yò̇֕ʼmer ʼa֛kĕ ne֥ged yĕhwá֖h mĕşǐyẖֽ⁠wò׃"],[16,7,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־שְׁמוּאֵ֗ל אַל־תַּבֵּ֧ט אֶל־מַרְאֵ֛⁠הוּ וְ⁠אֶל־גְּבֹ֥הַּ קוֹמָת֖⁠וֹ כִּ֣י מְאַסְתִּ֑י⁠הוּ כִּ֣י ׀ לֹ֗א אֲשֶׁ֤ר יִרְאֶה֙ הָ⁠אָדָ֔ם כִּ֤י הָֽ⁠אָדָם֙ יִרְאֶ֣ה לַ⁠עֵינַ֔יִם וַ⁠יהוָ֖ה יִרְאֶ֥ה לַ⁠לֵּבָֽב׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-şĕ̌mẇʼé֗l ʼal-ţȧbé֧̇t ʼel-marĕʼé֛⁠hẇ wĕ⁠ʼel-gĕ̇bò֥hȧ qwòmáţ֖⁠wò ki֣̇y mĕʼasĕţi֑̇y⁠hẇ ki֣̇y ׀ lò֗ʼ ʼàşě֤r yirĕʼeh֙ há⁠ʼádá֔m ki֤̇y háֽ⁠ʼádám֙ yirĕʼe֣h la⁠ʻéyna֔yim wa⁠yhwá֖h yirĕʼe֥h la⁠lé̇báֽb׃"],[16,8,"וַ⁠יִּקְרָ֤א יִשַׁי֙ אֶל־אֲבִ֣ינָדָ֔ב וַ⁠יַּעֲבִרֵ֖⁠הוּ לִ⁠פְנֵ֣י שְׁמוּאֵ֑ל וַ⁠יֹּ֕אמֶר גַּם־בָּ⁠זֶ֖ה לֹֽא־בָחַ֥ר יְהוָֽה׃","wa⁠yi̇qĕrá֤ʼ yişǎy֙ ʼel-ʼàbi֣ynádá֔b wa⁠yȧʻàbiré֖⁠hẇ li⁠pĕné֣y şĕ̌mẇʼé֑l wa⁠yò̇֕ʼmer gȧm-bá̇⁠ze֖h lòֽʼ-báẖa֥r yĕhwáֽh׃"],[16,9,"וַ⁠יַּעֲבֵ֥ר יִשַׁ֖י שַׁמָּ֑ה וַ⁠יֹּ֕אמֶר גַּם־בָּ⁠זֶ֖ה לֹא־בָחַ֥ר יְהוָֽה׃","wa⁠yȧʻàbé֥r yişǎ֖y şǎmá֑̇h wa⁠yò̇֕ʼmer gȧm-bá̇⁠ze֖h lòʼ-báẖa֥r yĕhwáֽh׃"],[16,10,"וַ⁠יַּעֲבֵ֥ר יִשַׁ֛י שִׁבְעַ֥ת בָּנָ֖י⁠ו לִ⁠פְנֵ֣י שְׁמוּאֵ֑ל וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־יִשַׁ֔י לֹא־בָחַ֥ר יְהוָ֖ה בָּ⁠אֵֽלֶּה׃","wa⁠yȧʻàbé֥r yişǎ֛y şǐbĕʻa֥ţ bá̇ná֖y⁠w li⁠pĕné֣y şĕ̌mẇʼé֑l wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-yişǎ֔y lòʼ-báẖa֥r yĕhwá֖h bá̇⁠ʼéֽlėh׃"],[16,11,"וַ⁠יֹּ֨אמֶר שְׁמוּאֵ֣ל אֶל־יִשַׁי֮ הֲ⁠תַ֣מּוּ הַ⁠נְּעָרִים֒ וַ⁠יֹּ֗אמֶר ע֚וֹד שָׁאַ֣ר הַ⁠קָּטָ֔ן וְ⁠הִנֵּ֥ה רֹעֶ֖ה בַּ⁠צֹּ֑אן וַ⁠יֹּ֨אמֶר שְׁמוּאֵ֤ל אֶל־יִשַׁי֙ שִׁלְחָ֣⁠ה וְ⁠קָחֶ֔⁠נּוּ כִּ֥י לֹא־נָסֹ֖ב עַד־בֹּא֥⁠וֹ פֹֽה׃","wa⁠yò̇֨ʼmer şĕ̌mẇʼé֣l ʼel-yişǎy֮ hà⁠ţa֣ṁẇ ha⁠nĕ̇ʻáriym֒ wa⁠yò̇֗ʼmer ʻ֚wòd şá̌ʼa֣r ha⁠qá̇tá֔n wĕ⁠hiné֥̇h ròʻe֖h bȧ⁠ẕò֑̇ʼn wa⁠yò̇֨ʼmer şĕ̌mẇʼé֤l ʼel-yişǎy֙ şǐlĕẖá֣⁠h wĕ⁠qáẖe֔⁠ṅẇ ki֥̇y lòʼ-násò֖b ʻad-bò̇ʼ֥⁠wò pòֽh׃"],[16,12,"וַ⁠יִּשְׁלַ֤ח וַ⁠יְבִיאֵ֨⁠הוּ֙ וְ⁠ה֣וּא אַדְמוֹנִ֔י עִם־יְפֵ֥ה עֵינַ֖יִם וְ⁠ט֣וֹב רֹ֑אִי פ וַ⁠יֹּ֧אמֶר יְהוָ֛ה ק֥וּם מְשָׁחֵ֖⁠הוּ כִּֽי־זֶ֥ה הֽוּא׃","wa⁠yi̇şĕ̌la֤ẖ wa⁠yĕbiyʼé֨⁠hẇ֙ wĕ⁠h֣ẇʼ ʼadĕmwòni֔y ʻim-yĕpé֥h ʻéyna֖yim wĕ⁠t֣wòb rò֑ʼiy p wa⁠yò֧̇ʼmer yĕhwá֛h q֥ẇm mĕşá̌ẖé֖⁠hẇ kiֽ̇y-ze֥h hֽẇʼ׃"],[16,13,"וַ⁠יִּקַּ֨ח שְׁמוּאֵ֜ל אֶת־קֶ֣רֶן הַ⁠שֶּׁ֗מֶן וַ⁠יִּמְשַׁ֣ח אֹת⁠וֹ֮ בְּ⁠קֶ֣רֶב אֶחָי⁠ו֒ וַ⁠תִּצְלַ֤ח רֽוּחַ־יְהוָה֙ אֶל־דָּוִ֔ד מֵ⁠הַ⁠יּ֥וֹם הַ⁠ה֖וּא וָ⁠מָ֑עְלָ⁠ה וַ⁠יָּ֣קָם שְׁמוּאֵ֔ל וַ⁠יֵּ֖לֶךְ הָ⁠רָמָֽתָ⁠ה׃ס","wa⁠yi̇qȧ֨ẖ şĕ̌mẇʼé֜l ʼeţ-qe֣ren ha⁠şė̌֗men wa⁠yi̇mĕşǎ֣ẖ ʼòţ⁠wò֮ bĕ̇⁠qe֣reb ʼeẖáy⁠w֒ wa⁠ţi̇ẕĕla֤ẖ rֽẇẖa-yĕhwáh֙ ʼel-dá̇wi֔d mé⁠ha⁠ẏ֥wòm ha⁠h֖ẇʼ wá⁠má֑ʻĕlá⁠h wa⁠yá֣̇qám şĕ̌mẇʼé֔l wa⁠yé֖̇lekĕ há⁠rámáֽţá⁠h׃s"],[16,14,"וְ⁠ר֧וּחַ יְהוָ֛ה סָ֖רָה מֵ⁠עִ֣ם שָׁא֑וּל וּ⁠בִֽעֲתַ֥תּ⁠וּ רֽוּחַ־רָעָ֖ה מֵ⁠אֵ֥ת יְהוָֽה׃","wĕ⁠r֧ẇẖa yĕhwá֛h sá֖ráh mé⁠ʻi֣m şá̌ʼ֑ẇl ẇ⁠biֽʻàţa֥ţ̇⁠ẇ rֽẇẖa-ráʻá֖h mé⁠ʼé֥ţ yĕhwáֽh׃"],[16,15,"וַ⁠יֹּאמְר֥וּ עַבְדֵֽי־שָׁא֖וּל אֵלָ֑י⁠ו הִנֵּה־נָ֧א רֽוּחַ־אֱלֹהִ֛ים רָעָ֖ה מְבַעִתֶּֽ⁠ךָ׃","wa⁠yò̇ʼmĕr֥ẇ ʻabĕdéֽy-şá̌ʼ֖ẇl ʼélá֑y⁠w hiné̇h-ná֧ʼ rֽẇẖa-ʼèlòhi֛ym ráʻá֖h mĕbaʻiţėֽ⁠ká׃"],[16,16,"יֹאמַר־נָ֤א אֲדֹנֵ֨⁠נוּ֙ עֲבָדֶ֣י⁠ךָ לְ⁠פָנֶ֔י⁠ךָ יְבַקְשׁ֕וּ אִ֕ישׁ יֹדֵ֖עַ מְנַגֵּ֣ן בַּ⁠כִּנּ֑וֹר וְ⁠הָיָ֗ה בִּֽ⁠הְי֨וֹת עָלֶ֤י⁠ךָ רֽוּחַ־אֱלֹהִים֙ רָעָ֔ה וְ⁠נִגֵּ֥ן בְּ⁠יָד֖⁠וֹ וְ⁠ט֥וֹב לָֽ⁠ךְ׃פ","yòʼmar-ná֤ʼ ʼàdòné֨⁠nẇ֙ ʻàbáde֣y⁠ká lĕ⁠páne֔y⁠ká yĕbaqĕş̌֕ẇ ʼi֕yş̌ yòdé֖ʻa mĕnagé֣̇n bȧ⁠ki̇ṅ֑wòr wĕ⁠háyá֗h biֽ̇⁠hĕy֨wòţ ʻále֤y⁠ká rֽẇẖa-ʼèlòhiym֙ ráʻá֔h wĕ⁠nigé֥̇n bĕ̇⁠yád֖⁠wò wĕ⁠t֥wòb láֽ⁠kĕ׃p"],[16,17,"וַ⁠יֹּ֥אמֶר שָׁא֖וּל אֶל־עֲבָדָ֑י⁠ו רְאוּ־נָ֣א לִ֗⁠י אִ֚ישׁ מֵיטִ֣יב לְ⁠נַגֵּ֔ן וַ⁠הֲבִיאוֹתֶ֖ם אֵלָֽ⁠י׃","wa⁠yò֥̇ʼmer şá̌ʼ֖ẇl ʼel-ʻàbádá֑y⁠w rĕʼẇ-ná֣ʼ li֗⁠y ʼi֚yş̌ méyti֣yb lĕ⁠nagé̇֔n wa⁠hàbiyʼwòţe֖m ʼéláֽ⁠y׃"],[16,18,"וַ⁠יַּעַן֩ אֶחָ֨ד מֵ⁠הַ⁠נְּעָרִ֜ים וַ⁠יֹּ֗אמֶר הִנֵּ֨ה רָאִ֜יתִי בֵּ֣ן לְ⁠יִשַׁי֮ בֵּ֣ית הַלַּחְמִי֒ יֹדֵ֣עַ נַ֠גֵּן וְ⁠גִבּ֨וֹר חַ֜יִל וְ⁠אִ֧ישׁ מִלְחָמָ֛ה וּ⁠נְב֥וֹן דָּבָ֖ר וְ⁠אִ֣ישׁ תֹּ֑אַר וַ⁠יהוָ֖ה עִמּֽ⁠וֹ׃","wa⁠yȧʻan֩ ʼeẖá֨d mé⁠ha⁠nĕ̇ʻári֜ym wa⁠yò̇֗ʼmer hiné̇֨h ráʼi֜yţiy bé֣̇n lĕ⁠yişǎy֮ bé֣̇yţ halȧẖĕmiy֒ yòdé֣ʻa na֠gé̇n wĕ⁠giḃ֨wòr ẖa֜yil wĕ⁠ʼi֧yş̌ milĕẖámá֛h ẇ⁠nĕb֥wòn dá̇bá֖r wĕ⁠ʼi֣yş̌ ţò֑̇ʼar wa⁠yhwá֖h ʻiṁֽ⁠wò׃"],[16,19,"וַ⁠יִּשְׁלַ֥ח שָׁא֛וּל מַלְאָכִ֖ים אֶל־יִשָׁ֑י וַ⁠יֹּ֕אמֶר שִׁלְחָ֥⁠ה אֵלַ֛⁠י אֶת־דָּוִ֥ד בִּנְ⁠ךָ֖ אֲשֶׁ֥ר בַּ⁠צֹּֽאן׃","wa⁠yi̇şĕ̌la֥ẖ şá̌ʼ֛ẇl malĕʼáki֖ym ʼel-yişá֑̌y wa⁠yò̇֕ʼmer şǐlĕẖá֥⁠h ʼéla֛⁠y ʼeţ-dá̇wi֥d bi̇nĕ⁠ká֖ ʼàşě֥r bȧ⁠ẕòֽ̇ʼn׃"],[16,20,"וַ⁠יִּקַּ֨ח יִשַׁ֜י חֲמ֥וֹר לֶ֨חֶם֙ וְ⁠נֹ֣אד יַ֔יִן וּ⁠גְדִ֥י עִזִּ֖ים אֶחָ֑ד וַ⁠יִּשְׁלַ֛ח בְּ⁠יַד־דָּוִ֥ד בְּנ֖⁠וֹ אֶל־שָׁאֽוּל׃","wa⁠yi̇qȧ֨ẖ yişǎ֜y ẖàm֥wòr le֨ẖem֙ wĕ⁠nò֣ʼd ya֔yin ẇ⁠gĕdi֥y ʻizi֖̇ym ʼeẖá֑d wa⁠yi̇şĕ̌la֛ẖ bĕ̇⁠yad-dá̇wi֥d bĕ̇n֖⁠wò ʼel-şá̌ʼֽẇl׃"],[16,21,"וַ⁠יָּבֹ֤א דָוִד֙ אֶל־שָׁא֔וּל וַֽ⁠יַּעֲמֹ֖ד לְ⁠פָנָ֑י⁠ו וַ⁠יֶּאֱהָבֵ֣⁠הֽוּ מְאֹ֔ד וַֽ⁠יְהִי־ל֖⁠וֹ נֹשֵׂ֥א כֵלִֽים׃","wa⁠yá̇bò֤ʼ dáwid֙ ʼel-şá̌ʼ֔ẇl waֽ⁠yȧʻàmò֖d lĕ⁠páná֑y⁠w wa⁠yėʼèhábé֣⁠hֽẇ mĕʼò֔d waֽ⁠yĕhiy-l֖⁠wò nòşé֥̂ʼ kéliֽym׃"],[16,22,"וַ⁠יִּשְׁלַ֣ח שָׁא֔וּל אֶל־יִשַׁ֖י לֵ⁠אמֹ֑ר יַעֲמָד־נָ֤א דָוִד֙ לְ⁠פָנַ֔⁠י כִּֽי־מָ֥צָא חֵ֖ן בְּ⁠עֵינָֽ⁠י׃","wa⁠yi̇şĕ̌la֣ẖ şá̌ʼ֔ẇl ʼel-yişǎ֖y lé⁠ʼmò֑r yaʻàmád-ná֤ʼ dáwid֙ lĕ⁠pána֔⁠y kiֽ̇y-má֥ẕáʼ ẖé֖n bĕ̇⁠ʻéynáֽ⁠y׃"],[16,23,"וְ⁠הָיָ֗ה בִּֽ⁠הְי֤וֹת רֽוּחַ־אֱלֹהִים֙ אֶל־שָׁא֔וּל וְ⁠לָקַ֥ח דָּוִ֛ד אֶת־הַ⁠כִּנּ֖וֹר וְ⁠נִגֵּ֣ן בְּ⁠יָד֑⁠וֹ וְ⁠רָוַ֤ח לְ⁠שָׁאוּל֙ וְ⁠ט֣וֹב ל֔⁠וֹ וְ⁠סָ֥רָה מֵ⁠עָלָ֖י⁠ו ר֥וּחַ הָ⁠רָעָֽה׃פ","wĕ⁠háyá֗h biֽ̇⁠hĕy֤wòţ rֽẇẖa-ʼèlòhiym֙ ʼel-şá̌ʼ֔ẇl wĕ⁠láqa֥ẖ dá̇wi֛d ʼeţ-ha⁠ki̇ṅ֖wòr wĕ⁠nigé֣̇n bĕ̇⁠yád֑⁠wò wĕ⁠ráwa֤ẖ lĕ⁠şá̌ʼẇl֙ wĕ⁠t֣wòb l֔⁠wò wĕ⁠sá֥ráh mé⁠ʻálá֖y⁠w r֥ẇẖa há⁠ráʻáֽh׃p"],[17,1,"וַ⁠יַּאַסְפ֨וּ פְלִשְׁתִּ֤ים אֶת־מַֽחֲנֵי⁠הֶם֙ לַ⁠מִּלְחָמָ֔ה וַ⁠יֵּאָ֣סְפ֔וּ שֹׂכֹ֖ה אֲשֶׁ֣ר לִ⁠יהוּדָ֑ה וַֽ⁠יַּחֲנ֛וּ בֵּין־שׂוֹכֹ֥ה וּ⁠בֵין־עֲזֵקָ֖ה בְּ⁠אֶ֥פֶס דַּמִּֽים׃","wa⁠yȧʼasĕp֨ẇ pĕlişĕ̌ţi֤̇ym ʼeţ-maֽẖànéy⁠hem֙ la⁠mi̇lĕẖámá֔h wa⁠yé̇ʼá֣sĕp֔ẇ şò̂kò֖h ʼàşě֣r li⁠yhẇdá֑h waֽ⁠yȧẖàn֛ẇ bé̇yn-ş̂wòkò֥h ẇ⁠béyn-ʻàzéqá֖h bĕ̇⁠ʼe֥pes dȧmiֽ̇ym׃"],[17,2,"וְ⁠שָׁא֤וּל וְ⁠אִֽישׁ־יִשְׂרָאֵל֙ נֶאֶסְפ֔וּ וַֽ⁠יַּחֲנ֖וּ בְּ⁠עֵ֣מֶק הָאֵלָ֑ה וַ⁠יַּעַרְכ֥וּ מִלְחָמָ֖ה לִ⁠קְרַ֥את פְּלִשְׁתִּֽים׃","wĕ⁠şá̌ʼ֤ẇl wĕ⁠ʼiֽyş̌-yişĕ̂ráʼél֙ neʼesĕp֔ẇ waֽ⁠yȧẖàn֖ẇ bĕ̇⁠ʻé֣meq háʼélá֑h wa⁠yȧʻarĕk֥ẇ milĕẖámá֖h li⁠qĕra֥ʼţ pĕ̇lişĕ̌ţiֽ̇ym׃"],[17,3,"וּ⁠פְלִשְׁתִּ֞ים עֹמְדִ֤ים אֶל־הָ⁠הָר֙ מִ⁠זֶּ֔ה וְ⁠יִשְׂרָאֵ֛ל עֹמְדִ֥ים אֶל־הָ⁠הָ֖ר מִ⁠זֶּ֑ה וְ⁠הַ⁠גַּ֖יְא בֵּינֵי⁠הֶֽם׃","ẇ⁠pĕlişĕ̌ţi̇֞ym ʻòmĕdi֤ym ʼel-há⁠hár֙ mi⁠zė֔h wĕ⁠yişĕ̂ráʼé֛l ʻòmĕdi֥ym ʼel-há⁠há֖r mi⁠zė֑h wĕ⁠ha⁠gȧ֖yĕʼ bé̇ynéy⁠heֽm׃"],[17,4,"וַ⁠יֵּצֵ֤א אִֽישׁ־הַ⁠בֵּנַ֨יִם֙ מִ⁠מַּחֲנ֣וֹת פְּלִשְׁתִּ֔ים גָּלְיָ֥ת שְׁמ֖⁠וֹ מִ⁠גַּ֑ת גָּבְה֕⁠וֹ שֵׁ֥שׁ אַמּ֖וֹת וָ⁠זָֽרֶת׃","wa⁠yé̇ẕé֤ʼ ʼiֽyş̌-ha⁠bé̇na֨yim֙ mi⁠mȧẖàn֣wòţ pĕ̇lişĕ̌ţi̇֔ym gá̇lĕyá֥ţ şĕ̌m֖⁠wò mi⁠gȧ֑ţ gá̇bĕh֕⁠wò şé֥̌ş̌ ʼaṁ֖wòţ wá⁠záֽreţ׃"],[17,5,"וְ⁠כ֤וֹבַע נְחֹ֨שֶׁת֙ עַל־רֹאשׁ֔⁠וֹ וְ⁠שִׁרְי֥וֹן קַשְׂקַשִּׂ֖ים ה֣וּא לָב֑וּשׁ וּ⁠מִשְׁקַל֙ הַ⁠שִּׁרְי֔וֹן חֲמֵשֶׁת־אֲלָפִ֥ים שְׁקָלִ֖ים נְחֹֽשֶֽׁת׃","wĕ⁠k֤wòbaʻ nĕẖò֨şěţ֙ ʻal-ròʼş̌֔⁠wò wĕ⁠şǐrĕy֥wòn qaşĕ̂qaşi֖̇̂ym h֣ẇʼ láb֑ẇş̌ ẇ⁠mişĕ̌qal֙ ha⁠şi̇̌rĕy֔wòn ẖàméşěţ-ʼàlápi֥ym şĕ̌qáli֖ym nĕẖòֽşěֽţ׃"],[17,6,"וּ⁠מִצְחַ֥ת נְחֹ֖שֶׁת עַל־רַגְלָ֑י⁠ו וְ⁠כִיד֥וֹן נְחֹ֖שֶׁת בֵּ֥ין כְּתֵפָֽי⁠ו׃","ẇ⁠miẕĕẖa֥ţ nĕẖò֖şěţ ʻal-ragĕlá֑y⁠w wĕ⁠kiyd֥wòn nĕẖò֖şěţ bé֥̇yn kĕ̇ţépáֽy⁠w׃"],[17,7,"ו⁠חץ חֲנִית֗⁠וֹ כִּ⁠מְנוֹר֙ אֹֽרְגִ֔ים וְ⁠לַהֶ֣בֶת חֲנִית֔⁠וֹ שֵׁשׁ־מֵא֥וֹת שְׁקָלִ֖ים בַּרְזֶ֑ל וְ⁠נֹשֵׂ֥א הַ⁠צִּנָּ֖ה הֹלֵ֥ךְ לְ⁠פָנָֽי⁠ו׃","w⁠ẖẕ ẖàniyţ֗⁠wò ki̇⁠mĕnwòr֙ ʼòֽrĕgi֔ym wĕ⁠lahe֣beţ ẖàniyţ֔⁠wò şé̌ş̌-méʼ֥wòţ şĕ̌qáli֖ym bȧrĕze֑l wĕ⁠nòşé֥̂ʼ ha⁠ẕi̇ná֖̇h hòlé֥kĕ lĕ⁠pánáֽy⁠w׃"],[17,8,"וַֽ⁠יַּעֲמֹ֗ד וַ⁠יִּקְרָא֙ אֶל־מַעַרְכֹ֣ת יִשְׂרָאֵ֔ל וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם לָ֥⁠מָּה תֵצְא֖וּ לַ⁠עֲרֹ֣ךְ מִלְחָמָ֑ה הֲ⁠ל֧וֹא אָנֹכִ֣י הַ⁠פְּלִשְׁתִּ֗י וְ⁠אַתֶּם֙ עֲבָדִ֣ים לְ⁠שָׁא֔וּל בְּרוּ־לָ⁠כֶ֥ם אִ֖ישׁ וְ⁠יֵרֵ֥ד אֵלָֽ⁠י׃","waֽ⁠yȧʻàmò֗d wa⁠yi̇qĕráʼ֙ ʼel-maʻarĕkò֣ţ yişĕ̂ráʼé֔l wa⁠yò֣̇ʼmer lá⁠he֔m lá֥⁠má̇h ţéẕĕʼ֖ẇ la⁠ʻàrò֣kĕ milĕẖámá֑h hà⁠l֧wòʼ ʼánòki֣y ha⁠pĕ̇lişĕ̌ţi̇֗y wĕ⁠ʼaţėm֙ ʻàbádi֣ym lĕ⁠şá̌ʼ֔ẇl bĕ̇rẇ-lá⁠ke֥m ʼi֖yş̌ wĕ⁠yéré֥d ʼéláֽ⁠y׃"],[17,9,"אִם־יוּכַ֞ל לְ⁠הִלָּחֵ֤ם אִתִּ⁠י֙ וְ⁠הִכָּ֔⁠נִי וְ⁠הָיִ֥ינוּ לָ⁠כֶ֖ם לַ⁠עֲבָדִ֑ים וְ⁠אִם־אֲנִ֤י אֽוּכַל־ל⁠וֹ֙ וְ⁠הִכִּיתִ֔י⁠ו וִ⁠הְיִ֤יתֶם לָ֨⁠נוּ֙ לַ⁠עֲבָדִ֔ים וַ⁠עֲבַדְתֶּ֖ם אֹתָֽ⁠נוּ׃","ʼim-yẇka֞l lĕ⁠hilá̇ẖé֤m ʼiţi̇⁠y֙ wĕ⁠hiká̇֔⁠niy wĕ⁠háyi֥ynẇ lá⁠ke֖m la⁠ʻàbádi֑ym wĕ⁠ʼim-ʼàni֤y ʼֽẇkal-l⁠wò֙ wĕ⁠hiki̇yţi֔y⁠w wi⁠hĕyi֤yţem lá֨⁠nẇ֙ la⁠ʻàbádi֔ym wa⁠ʻàbadĕţė֖m ʼòţáֽ⁠nẇ׃"],[17,10,"וַ⁠יֹּ֨אמֶר֙ הַ⁠פְּלִשְׁתִּ֔י אֲנִ֗י חֵרַ֛פְתִּי אֶת־מַעַרְכ֥וֹת יִשְׂרָאֵ֖ל הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה תְּנוּ־לִ֣⁠י אִ֔ישׁ וְ⁠נִֽלָּחֲמָ֖ה יָֽחַד׃","wa⁠yò̇֨ʼmer֙ ha⁠pĕ̇lişĕ̌ţi̇֔y ʼàni֗y ẖéra֛pĕţi̇y ʼeţ-maʻarĕk֥wòţ yişĕ̂ráʼé֖l ha⁠ẏ֣wòm ha⁠zė֑h ţĕ̇nẇ-li֣⁠y ʼi֔yş̌ wĕ⁠niֽlá̇ẖàmá֖h yáֽẖad׃"],[17,11,"וַ⁠יִּשְׁמַ֤ע שָׁאוּל֙ וְ⁠כָל־יִשְׂרָאֵ֔ל אֶת־דִּבְרֵ֥י הַ⁠פְּלִשְׁתִּ֖י הָ⁠אֵ֑לֶּה וַ⁠יֵּחַ֥תּוּ וַ⁠יִּֽרְא֖וּ מְאֹֽד׃פ","wa⁠yi̇şĕ̌ma֤ʻ şá̌ʼẇl֙ wĕ⁠kál-yişĕ̂ráʼé֔l ʼeţ-di̇bĕré֥y ha⁠pĕ̇lişĕ̌ţi֖̇y há⁠ʼé֑lėh wa⁠yé̇ẖa֥ţ̇ẇ wa⁠yiֽ̇rĕʼ֖ẇ mĕʼòֽd׃p"],[17,12,"וְ⁠דָוִד֩ בֶּן־אִ֨ישׁ אֶפְרָתִ֜י הַ⁠זֶּ֗ה מִ⁠בֵּ֥ית לֶ֨חֶם֙ יְהוּדָ֔ה וּ⁠שְׁמ֣⁠וֹ יִשַׁ֔י וְ⁠ל֖⁠וֹ שְׁמֹנָ֣ה בָנִ֑ים וְ⁠הָ⁠אִישׁ֙ בִּ⁠ימֵ֣י שָׁא֔וּל זָקֵ֖ן בָּ֥א בַ⁠אֲנָשִֽׁים׃","wĕ⁠dáwid֩ bėn-ʼi֨yş̌ ʼepĕráţi֜y ha⁠zė֗h mi⁠bé֥̇yţ le֨ẖem֙ yĕhẇdá֔h ẇ⁠şĕ̌m֣⁠wò yişǎ֔y wĕ⁠l֖⁠wò şĕ̌mòná֣h báni֑ym wĕ⁠há⁠ʼiyş̌֙ bi̇⁠ymé֣y şá̌ʼ֔ẇl záqé֖n bá֥̇ʼ ba⁠ʼànáşǐֽym׃"],[17,13,"וַ⁠יֵּ֨לְכ֜וּ שְׁלֹ֤שֶׁת בְּנֵֽי־יִשַׁי֙ הַ⁠גְּדֹלִ֔ים הָלְכ֥וּ אַחֲרֵי־שָׁא֖וּל לַ⁠מִּלְחָמָ֑ה וְ⁠שֵׁ֣ם ׀ שְׁלֹ֣שֶׁת בָּנָ֗י⁠ו אֲשֶׁ֤ר הָלְכוּ֙ בַּ⁠מִּלְחָמָ֔ה אֱלִיאָ֣ב הַ⁠בְּכ֗וֹר וּ⁠מִשְׁנֵ֨⁠הוּ֙ אֲבִ֣ינָדָ֔ב וְ⁠הַ⁠שְּׁלִשִׁ֖י שַׁמָּֽה׃","wa⁠yé̇֨lĕk֜ẇ şĕ̌lò֤şěţ bĕ̇néֽy-yişǎy֙ ha⁠gĕ̇dòli֔ym hálĕk֥ẇ ʼaẖàréy-şá̌ʼ֖ẇl la⁠mi̇lĕẖámá֑h wĕ⁠şé֣̌m ׀ şĕ̌lò֣şěţ bá̇ná֗y⁠w ʼàşě֤r hálĕkẇ֙ bȧ⁠mi̇lĕẖámá֔h ʼèliyʼá֣b ha⁠bĕ̇k֗wòr ẇ⁠mişĕ̌né֨⁠hẇ֙ ʼàbi֣ynádá֔b wĕ⁠ha⁠şĕ̇̌lişǐ֖y şǎmáֽ̇h׃"],[17,14,"וְ⁠דָוִ֖ד ה֣וּא הַ⁠קָּטָ֑ן וּ⁠שְׁלֹשָׁה֙ הַ⁠גְּדֹלִ֔ים הָלְכ֖וּ אַחֲרֵ֥י שָׁאֽוּל׃ס","wĕ⁠dáwi֖d h֣ẇʼ ha⁠qá̇tá֑n ẇ⁠şĕ̌lòşá̌h֙ ha⁠gĕ̇dòli֔ym hálĕk֖ẇ ʼaẖàré֥y şá̌ʼֽẇl׃s"],[17,15,"וְ⁠דָוִ֛ד הֹלֵ֥ךְ וָ⁠שָׁ֖ב מֵ⁠עַ֣ל שָׁא֑וּל לִ⁠רְע֛וֹת אֶת־צֹ֥אן אָבִ֖י⁠ו בֵּֽית־לָֽחֶם׃","wĕ⁠dáwi֛d hòlé֥kĕ wá⁠şá֖̌b mé⁠ʻa֣l şá̌ʼ֑ẇl li⁠rĕʻ֛wòţ ʼeţ-ẕò֥ʼn ʼábi֖y⁠w béֽ̇yţ-láֽẖem׃"],[17,16,"וַ⁠יִּגַּ֥שׁ הַ⁠פְּלִשְׁתִּ֖י הַשְׁכֵּ֣ם וְ⁠הַעֲרֵ֑ב וַ⁠יִּתְיַצֵּ֖ב אַרְבָּעִ֥ים יֽוֹם׃פ","wa⁠yi̇gȧ֥ş̌ ha⁠pĕ̇lişĕ̌ţi֖̇y haşĕ̌ké֣̇m wĕ⁠haʻàré֑b wa⁠yi̇ţĕyaẕé֖̇b ʼarĕbá̇ʻi֥ym yֽwòm׃p"],[17,17,"וַ⁠יֹּ֨אמֶר יִשַׁ֜י לְ⁠דָוִ֣ד בְּנ֗⁠וֹ קַח־נָ֤א לְ⁠אַחֶ֨י⁠ךָ֙ אֵיפַ֤ת הַ⁠קָּלִיא֙ הַ⁠זֶּ֔ה וַ⁠עֲשָׂרָ֥ה לֶ֖חֶם הַ⁠זֶּ֑ה וְ⁠הָרֵ֥ץ הַֽ⁠מַּחֲנֶ֖ה לְ⁠אַחֶֽי⁠ךָ׃","wa⁠yò̇֨ʼmer yişǎ֜y lĕ⁠dáwi֣d bĕ̇n֗⁠wò qaẖ-ná֤ʼ lĕ⁠ʼaẖe֨y⁠ká֙ ʼéypa֤ţ ha⁠qá̇liyʼ֙ ha⁠zė֔h wa⁠ʻàşá̂rá֥h le֖ẖem ha⁠zė֑h wĕ⁠háré֥ẕ haֽ⁠mȧẖàne֖h lĕ⁠ʼaẖeֽy⁠ká׃"],[17,18,"וְ֠⁠אֵת עֲשֶׂ֜רֶת חֲרִצֵ֤י הֶֽ⁠חָלָב֙ הָ⁠אֵ֔לֶּה תָּבִ֖יא לְ⁠שַׂר־הָ⁠אָ֑לֶף וְ⁠אֶת־אַחֶ֨י⁠ךָ֙ תִּפְקֹ֣ד לְ⁠שָׁל֔וֹם וְ⁠אֶת־עֲרֻבָּתָ֖⁠ם תִּקָּֽח׃","wĕ֠⁠ʼéţ ʻàşê֜reţ ẖàriẕé֤y heֽ⁠ẖáláb֙ há⁠ʼé֔lėh ţá̇bi֖yʼ lĕ⁠şâr-há⁠ʼá֑lep wĕ⁠ʼeţ-ʼaẖe֨y⁠ká֙ ţi̇pĕqò֣d lĕ⁠şá̌l֔wòm wĕ⁠ʼeţ-ʻàrubá̇ţá֖⁠m ţi̇qáֽ̇ẖ׃"],[17,19,"וְ⁠שָׁא֤וּל וְ⁠הֵ֨מָּה֙ וְ⁠כָל־אִ֣ישׁ יִשְׂרָאֵ֔ל בְּ⁠עֵ֖מֶק הָֽאֵלָ֑ה נִלְחָמִ֖ים עִם־פְּלִשְׁתִּֽים׃","wĕ⁠şá̌ʼ֤ẇl wĕ⁠hé֨má̇h֙ wĕ⁠kál-ʼi֣yş̌ yişĕ̂ráʼé֔l bĕ̇⁠ʻé֖meq háֽʼélá֑h nilĕẖámi֖ym ʻim-pĕ̇lişĕ̌ţiֽ̇ym׃"],[17,20,"וַ⁠יַּשְׁכֵּ֨ם דָּוִ֜ד בַּ⁠בֹּ֗קֶר וַ⁠יִּטֹּ֤שׁ אֶת־הַ⁠צֹּאן֙ עַל־שֹׁמֵ֔ר וַ⁠יִּשָּׂ֣א וַ⁠יֵּ֔לֶךְ כַּ⁠אֲשֶׁ֥ר צִוָּ֖⁠הוּ יִשָׁ֑י וַ⁠יָּבֹא֙ הַ⁠מַּעְגָּ֔לָ⁠ה וְ⁠הַ⁠חַ֗יִל הַ⁠יֹּצֵא֙ אֶל־הַ⁠מַּ֣עֲרָכָ֔ה וְ⁠הֵרֵ֖עוּ בַּ⁠מִּלְחָמָֽה׃","wa⁠yȧşĕ̌ké̇֨m dá̇wi֜d bȧ⁠bò̇֗qer wa⁠yi̇tò֤̇ş̌ ʼeţ-ha⁠ẕò̇ʼn֙ ʻal-şò̌mé֔r wa⁠yi̇şá֣̇̂ʼ wa⁠yé̇֔lekĕ kȧ⁠ʼàşě֥r ẕiwá֖̇⁠hẇ yişá֑̌y wa⁠yá̇bòʼ֙ ha⁠mȧʻĕgá̇֔lá⁠h wĕ⁠ha⁠ẖa֗yil ha⁠yò̇ẕéʼ֙ ʼel-ha⁠mȧ֣ʻàráká֔h wĕ⁠héré֖ʻẇ bȧ⁠mi̇lĕẖámáֽh׃"],[17,21,"וַ⁠תַּעֲרֹ֤ךְ יִשְׂרָאֵל֙ וּ⁠פְלִשְׁתִּ֔ים מַעֲרָכָ֖ה לִ⁠קְרַ֥את מַעֲרָכָֽה׃","wa⁠ţȧʻàrò֤kĕ yişĕ̂ráʼél֙ ẇ⁠pĕlişĕ̌ţi̇֔ym maʻàráká֖h li⁠qĕra֥ʼţ maʻàrákáֽh׃"],[17,22,"וַ⁠יִּטֹּשׁ֩ דָּוִ֨ד אֶת־הַ⁠כֵּלִ֜ים מֵ⁠עָלָ֗י⁠ו עַל־יַד֙ שׁוֹמֵ֣ר הַ⁠כֵּלִ֔ים וַ⁠יָּ֖רָץ הַ⁠מַּעֲרָכָ֑ה וַ⁠יָּבֹ֕א וַ⁠יִּשְׁאַ֥ל לְ⁠אֶחָ֖י⁠ו לְ⁠שָׁלֽוֹם׃","wa⁠yi̇tò̇ş̌֩ dá̇wi֨d ʼeţ-ha⁠ké̇li֜ym mé⁠ʻálá֗y⁠w ʻal-yad֙ ş̌wòmé֣r ha⁠ké̇li֔ym wa⁠yá֖̇ráẕ ha⁠mȧʻàráká֑h wa⁠yá̇bò֕ʼ wa⁠yi̇şĕ̌ʼa֥l lĕ⁠ʼeẖá֖y⁠w lĕ⁠şá̌lֽwòm׃"],[17,23,"וְ⁠ה֣וּא ׀ מְדַבֵּ֣ר עִמָּ֗⁠ם וְ⁠הִנֵּ֣ה אִ֣ישׁ הַ⁠בֵּנַ֡יִם עוֹלֶ֞ה גָּלְיָת֩ הַ⁠פְּלִשְׁתִּ֨י שְׁמ֤⁠וֹ מִ⁠גַּת֙ ממערות פְּלִשְׁתִּ֔ים וַ⁠יְדַבֵּ֖ר כַּ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה וַ⁠יִּשְׁמַ֖ע דָּוִֽד׃","wĕ⁠h֣ẇʼ ׀ mĕdabé֣̇r ʻimá̇֗⁠m wĕ⁠hiné֣̇h ʼi֣yş̌ ha⁠bé̇na֡yim ʻwòle֞h gá̇lĕyáţ֩ ha⁠pĕ̇lişĕ̌ţi̇֨y şĕ̌m֤⁠wò mi⁠gȧţ֙ mmʻrwţ pĕ̇lişĕ̌ţi̇֔ym wa⁠yĕdabé֖̇r kȧ⁠dĕ̇bári֣ym há⁠ʼé֑lėh wa⁠yi̇şĕ̌ma֖ʻ dá̇wiֽd׃"],[17,24,"וְ⁠כֹל֙ אִ֣ישׁ יִשְׂרָאֵ֔ל בִּ⁠רְאוֹתָ֖⁠ם אֶת־הָ⁠אִ֑ישׁ וַ⁠יָּנֻ֨סוּ֙ מִ⁠פָּנָ֔י⁠ו וַ⁠יִּֽירְא֖וּ מְאֹֽד׃","wĕ⁠kòl֙ ʼi֣yş̌ yişĕ̂ráʼé֔l bi̇⁠rĕʼwòţá֖⁠m ʼeţ-há⁠ʼi֑yş̌ wa⁠yá̇nu֨sẇ֙ mi⁠pá̇ná֔y⁠w wa⁠yiֽ̇yrĕʼ֖ẇ mĕʼòֽd׃"],[17,25,"וַ⁠יֹּ֣אמֶר ׀ אִ֣ישׁ יִשְׂרָאֵ֗ל הַ⁠רְּאִיתֶם֙ הָ⁠אִ֤ישׁ הָֽ⁠עֹלֶה֙ הַ⁠זֶּ֔ה כִּ֛י לְ⁠חָרֵ֥ף אֶת־יִשְׂרָאֵ֖ל עֹלֶ֑ה וְֽ֠⁠הָיָה הָ⁠אִ֨ישׁ אֲשֶׁר־יַכֶּ֜⁠נּוּ יַעְשְׁרֶ֥⁠נּוּ הַ⁠מֶּ֣לֶךְ ׀ עֹ֣שֶׁר גָּד֗וֹל וְ⁠אֶת־בִּתּ⁠וֹ֙ יִתֶּן־ל֔⁠וֹ וְ⁠אֵת֙ בֵּ֣ית אָבִ֔י⁠ו יַעֲשֶׂ֥ה חָפְשִׁ֖י בְּ⁠יִשְׂרָאֵֽל׃","wa⁠yò֣̇ʼmer ׀ ʼi֣yş̌ yişĕ̂ráʼé֗l ha⁠rĕ̇ʼiyţem֙ há⁠ʼi֤yş̌ háֽ⁠ʻòleh֙ ha⁠zė֔h ki֛̇y lĕ⁠ẖáré֥p ʼeţ-yişĕ̂ráʼé֖l ʻòle֑h wĕֽ֠⁠háyáh há⁠ʼi֨yş̌ ʼàşěr-yakė֜⁠ṅẇ yaʻĕşĕ̌re֥⁠ṅẇ ha⁠mė֣lekĕ ׀ ʻò֣şěr gá̇d֗wòl wĕ⁠ʼeţ-bi̇ţ̇⁠wò֙ yiţėn-l֔⁠wò wĕ⁠ʼéţ֙ bé֣̇yţ ʼábi֔y⁠w yaʻàşê֥h ẖápĕşǐ֖y bĕ̇⁠yişĕ̂ráʼéֽl׃"],[17,26,"וַ⁠יֹּ֣אמֶר דָּוִ֗ד אֶֽל־הָ⁠אֲנָשִׁ֞ים הָ⁠עֹמְדִ֣ים עִמּ⁠וֹ֮ לֵ⁠אמֹר֒ מַה־יֵּעָשֶׂ֗ה לָ⁠אִישׁ֙ אֲשֶׁ֤ר יַכֶּה֙ אֶת־הַ⁠פְּלִשְׁתִּ֣י הַלָּ֔ז וְ⁠הֵסִ֥יר חֶרְפָּ֖ה מֵ⁠עַ֣ל יִשְׂרָאֵ֑ל כִּ֣י מִ֗י הַ⁠פְּלִשְׁתִּ֤י הֶֽ⁠עָרֵל֙ הַ⁠זֶּ֔ה כִּ֣י חֵרֵ֔ף מַעַרְכ֖וֹת אֱלֹהִ֥ים חַיִּֽים׃","wa⁠yò֣̇ʼmer dá̇wi֗d ʼeֽl-há⁠ʼànáşǐ֞ym há⁠ʻòmĕdi֣ym ʻiṁ⁠wò֮ lé⁠ʼmòr֒ mah-yé̇ʻáşê֗h lá⁠ʼiyş̌֙ ʼàşě֤r yakėh֙ ʼeţ-ha⁠pĕ̇lişĕ̌ţi֣̇y halá̇֔z wĕ⁠hési֥yr ẖerĕpá֖̇h mé⁠ʻa֣l yişĕ̂ráʼé֑l ki֣̇y mi֗y ha⁠pĕ̇lişĕ̌ţi֤̇y heֽ⁠ʻárél֙ ha⁠zė֔h ki֣̇y ẖéré֔p maʻarĕk֖wòţ ʼèlòhi֥ym ẖayiֽ̇ym׃"],[17,27,"וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ הָ⁠עָ֔ם כַּ⁠דָּבָ֥ר הַ⁠זֶּ֖ה לֵ⁠אמֹ֑ר כֹּ֣ה יֵעָשֶׂ֔ה לָ⁠אִ֖ישׁ אֲשֶׁ֥ר יַכֶּֽ⁠נּוּ׃","wa⁠yò֤̇ʼmer l⁠wò֙ há⁠ʻá֔m kȧ⁠dá̇bá֥r ha⁠zė֖h lé⁠ʼmò֑r kò֣̇h yéʻáşê֔h lá⁠ʼi֖yş̌ ʼàşě֥r yakėֽ⁠ṅẇ׃"],[17,28,"וַ⁠יִּשְׁמַ֤ע אֱלִיאָב֙ אָחִ֣י⁠ו הַ⁠גָּד֔וֹל בְּ⁠דַבְּר֖⁠וֹ אֶל־הָ⁠אֲנָשִׁ֑ים וַ⁠יִּֽחַר־אַף֩ אֱלִיאָ֨ב בְּ⁠דָוִ֜ד וַ⁠יֹּ֣אמֶר ׀ לָ⁠מָּה־זֶּ֣ה יָרַ֗דְתָּ וְ⁠עַל־מִ֨י נָטַ֜שְׁתָּ מְעַ֨ט הַ⁠צֹּ֤אן הָ⁠הֵ֨נָּה֙ בַּ⁠מִּדְבָּ֔ר אֲנִ֧י יָדַ֣עְתִּי אֶת־זְדֹנְ⁠ךָ֗ וְ⁠אֵת֙ רֹ֣עַ לְבָבֶ֔⁠ךָ כִּ֗י לְמַ֛עַן רְא֥וֹת הַ⁠מִּלְחָמָ֖ה יָרָֽדְתָּ׃","wa⁠yi̇şĕ̌ma֤ʻ ʼèliyʼáb֙ ʼáẖi֣y⁠w ha⁠gá̇d֔wòl bĕ̇⁠dabĕ̇r֖⁠wò ʼel-há⁠ʼànáşǐ֑ym wa⁠yiֽ̇ẖar-ʼap֩ ʼèliyʼá֨b bĕ̇⁠dáwi֜d wa⁠yò֣̇ʼmer ׀ lá⁠má̇h-zė֣h yára֗dĕţá̇ wĕ⁠ʻal-mi֨y náta֜şĕ̌ţá̇ mĕʻa֨t ha⁠ẕò֤̇ʼn há⁠hé֨ná̇h֙ bȧ⁠mi̇dĕbá̇֔r ʼàni֧y yáda֣ʻĕţi̇y ʼeţ-zĕdònĕ⁠ká֗ wĕ⁠ʼéţ֙ rò֣ʻa lĕbábe֔⁠ká ki̇֗y lĕma֛ʻan rĕʼ֥wòţ ha⁠mi̇lĕẖámá֖h yáráֽdĕţá̇׃"],[17,29,"וַ⁠יֹּ֣אמֶר דָּוִ֔ד מֶ֥ה עָשִׂ֖יתִי עָ֑תָּה הֲ⁠ל֖וֹא דָּבָ֥ר הֽוּא׃","wa⁠yò֣̇ʼmer dá̇wi֔d me֥h ʻáşî֖yţiy ʻá֑ţá̇h hà⁠l֖wòʼ dá̇bá֥r hֽẇʼ׃"],[17,30,"וַ⁠יִּסֹּ֤ב מֵֽ⁠אֶצְל⁠וֹ֙ אֶל־מ֣וּל אַחֵ֔ר וַ⁠יֹּ֖אמֶר כַּ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַ⁠יְשִׁבֻ֤⁠הוּ הָ⁠עָם֙ דָּבָ֔ר כַּ⁠דָּבָ֖ר הָ⁠רִאשֽׁוֹן׃","wa⁠yi̇sò֤̇b méֽ⁠ʼeẕĕl⁠wò֙ ʼel-m֣ẇl ʼaẖé֔r wa⁠yò֖̇ʼmer kȧ⁠dá̇bá֣r ha⁠zė֑h wa⁠yĕşǐbu֤⁠hẇ há⁠ʻám֙ dá̇bá֔r kȧ⁠dá̇bá֖r há⁠riʼşֽ̌wòn׃"],[17,31,"וַ⁠יְּשָּֽׁמְעוּ֙ הַ⁠דְּבָרִ֔ים אֲשֶׁ֖ר דִּבֶּ֣ר דָּוִ֑ד וַ⁠יַּגִּ֥דוּ לִ⁠פְנֵֽי־שָׁא֖וּל וַ⁠יִּקָּחֵֽ⁠הוּ׃","wa⁠yĕ̇şáֽ̇̌mĕʻẇ֙ ha⁠dĕ̇bári֔ym ʼàşě֖r di̇bė֣r dá̇wi֑d wa⁠yȧgi֥̇dẇ li⁠pĕnéֽy-şá̌ʼ֖ẇl wa⁠yi̇qá̇ẖéֽ⁠hẇ׃"],[17,32,"וַ⁠יֹּ֤אמֶר דָּוִד֙ אֶל־שָׁא֔וּל אַל־יִפֹּ֥ל לֵב־אָדָ֖ם עָלָ֑י⁠ו עַבְדְּ⁠ךָ֣ יֵלֵ֔ךְ וְ⁠נִלְחַ֖ם עִם־הַ⁠פְּלִשְׁתִּ֥י הַ⁠זֶּֽה׃","wa⁠yò֤̇ʼmer dá̇wid֙ ʼel-şá̌ʼ֔ẇl ʼal-yipò֥̇l léb-ʼádá֖m ʻálá֑y⁠w ʻabĕdĕ̇⁠ká֣ yélé֔kĕ wĕ⁠nilĕẖa֖m ʻim-ha⁠pĕ̇lişĕ̌ţi֥̇y ha⁠zėֽh׃"],[17,33,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל אֶל־דָּוִ֗ד לֹ֤א תוּכַל֙ לָ⁠לֶ֨כֶת֙ אֶל־הַ⁠פְּלִשְׁתִּ֣י הַ⁠זֶּ֔ה לְ⁠הִלָּחֵ֖ם עִמּ֑⁠וֹ כִּֽי־נַ֣עַר אַ֔תָּה וְ⁠ה֛וּא אִ֥ישׁ מִלְחָמָ֖ה מִ⁠נְּעֻרָֽי⁠ו׃ס","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl ʼel-dá̇wi֗d lò֤ʼ ţẇkal֙ lá⁠le֨keţ֙ ʼel-ha⁠pĕ̇lişĕ̌ţi֣̇y ha⁠zė֔h lĕ⁠hilá̇ẖé֖m ʻiṁ֑⁠wò kiֽ̇y-na֣ʻar ʼa֔ţá̇h wĕ⁠h֛ẇʼ ʼi֥yş̌ milĕẖámá֖h mi⁠nĕ̇ʻuráֽy⁠w׃s"],[17,34,"וַ⁠יֹּ֤אמֶר דָּוִד֙ אֶל־שָׁא֔וּל רֹעֶ֨ה הָיָ֧ה עַבְדְּ⁠ךָ֛ לְ⁠אָבִ֖י⁠ו בַּ⁠צֹּ֑אן וּ⁠בָ֤א הָֽ⁠אֲרִי֙ וְ⁠אֶת־הַ⁠דּ֔וֹב וְ⁠נָשָׂ֥א שֶׂ֖ה מֵ⁠הָ⁠עֵֽדֶר׃","wa⁠yò֤̇ʼmer dá̇wid֙ ʼel-şá̌ʼ֔ẇl ròʻe֨h háyá֧h ʻabĕdĕ̇⁠ká֛ lĕ⁠ʼábi֖y⁠w bȧ⁠ẕò֑̇ʼn ẇ⁠bá֤ʼ háֽ⁠ʼàriy֙ wĕ⁠ʼeţ-ha⁠ḋ֔wòb wĕ⁠náşá֥̂ʼ şê֖h mé⁠há⁠ʻéֽder׃"],[17,35,"וְ⁠יָצָ֧אתִי אַחֲרָ֛י⁠ו וְ⁠הִכִּתִ֖י⁠ו וְ⁠הִצַּ֣לְתִּי מִ⁠פִּ֑י⁠ו וַ⁠יָּ֣קָם עָלַ֔⁠י וְ⁠הֶחֱזַ֨קְתִּי֙ בִּ⁠זְקָנ֔⁠וֹ וְ⁠הִכִּתִ֖י⁠ו וַ⁠הֲמִיתִּֽי⁠ו׃","wĕ⁠yáẕá֧ʼţiy ʼaẖàrá֛y⁠w wĕ⁠hiki̇ţi֖y⁠w wĕ⁠hiẕȧ֣lĕţi̇y mi⁠pi֑̇y⁠w wa⁠yá֣̇qám ʻála֔⁠y wĕ⁠heẖèza֨qĕţi̇y֙ bi̇⁠zĕqán֔⁠wò wĕ⁠hiki̇ţi֖y⁠w wa⁠hàmiyţiֽ̇y⁠w׃"],[17,36,"גַּ֧ם אֶֽת־הָ⁠אֲרִ֛י גַּם־הַ⁠דּ֖וֹב הִכָּ֣ה עַבְדֶּ֑⁠ךָ וְֽ֠⁠הָיָה הַ⁠פְּלִשְׁתִּ֨י הֶ⁠עָרֵ֤ל הַ⁠זֶּה֙ כְּ⁠אַחַ֣ד מֵ⁠הֶ֔ם כִּ֣י חֵרֵ֔ף מַעַרְכֹ֖ת אֱלֹהִ֥ים חַיִּֽים׃ס","gȧ֧m ʼeֽţ-há⁠ʼàri֛y gȧm-ha⁠ḋ֖wòb hiká֣̇h ʻabĕdė֑⁠ká wĕֽ֠⁠háyáh ha⁠pĕ̇lişĕ̌ţi̇֨y he⁠ʻáré֤l ha⁠zėh֙ kĕ̇⁠ʼaẖa֣d mé⁠he֔m ki֣̇y ẖéré֔p maʻarĕkò֖ţ ʼèlòhi֥ym ẖayiֽ̇ym׃s"],[17,37,"וַ⁠יֹּאמֶר֮ דָּוִד֒ יְהוָ֗ה אֲשֶׁ֨ר הִצִּלַ֜⁠נִי מִ⁠יַּ֤ד הָֽ⁠אֲרִי֙ וּ⁠מִ⁠יַּ֣ד הַ⁠דֹּ֔ב ה֣וּא יַצִּילֵ֔⁠נִי מִ⁠יַּ֥ד הַ⁠פְּלִשְׁתִּ֖י הַ⁠זֶּ֑ה ס וַ⁠יֹּ֨אמֶר שָׁא֤וּל אֶל־דָּוִד֙ לֵ֔ךְ וַֽ⁠יהוָ֖ה יִהְיֶ֥ה עִמָּֽ⁠ךְ׃","wa⁠yò̇ʼmer֮ dá̇wid֒ yĕhwá֗h ʼàşě֨r hiẕi̇la֜⁠niy mi⁠yȧ֤d háֽ⁠ʼàriy֙ ẇ⁠mi⁠yȧ֣d ha⁠dò̇֔b h֣ẇʼ yaẕi̇ylé֔⁠niy mi⁠yȧ֥d ha⁠pĕ̇lişĕ̌ţi֖̇y ha⁠zė֑h s wa⁠yò̇֨ʼmer şá̌ʼ֤ẇl ʼel-dá̇wid֙ lé֔kĕ waֽ⁠yhwá֖h yihĕye֥h ʻimáֽ̇⁠kĕ׃"],[17,38,"וַ⁠יַּלְבֵּ֨שׁ שָׁא֤וּל אֶת־דָּוִד֙ מַדָּ֔י⁠ו וְ⁠נָתַ֛ן ק֥וֹבַע נְחֹ֖שֶׁת עַל־רֹאשׁ֑⁠וֹ וַ⁠יַּלְבֵּ֥שׁ אֹת֖⁠וֹ שִׁרְיֽוֹן׃","wa⁠yȧlĕbé̇֨ş̌ şá̌ʼ֤ẇl ʼeţ-dá̇wid֙ madá̇֔y⁠w wĕ⁠náţa֛n q֥wòbaʻ nĕẖò֖şěţ ʻal-ròʼş֑̌⁠wò wa⁠yȧlĕbé֥̇ş̌ ʼòţ֖⁠wò şǐrĕyֽwòn׃"],[17,39,"וַ⁠יַּחְגֹּ֣ר דָּוִ֣ד אֶת־חַ֠רְבּ⁠וֹ מֵ⁠עַ֨ל לְ⁠מַדָּ֜י⁠ו וַ⁠יֹּ֣אֶל לָ⁠לֶכֶת֮ כִּ֣י לֹֽא־נִסָּה֒ וַ⁠יֹּ֨אמֶר דָּוִ֜ד אֶל־שָׁא֗וּל לֹ֥א אוּכַ֛ל לָ⁠לֶ֥כֶת בָּ⁠אֵ֖לֶּה כִּ֣י לֹ֣א נִסִּ֑יתִי וַ⁠יְסִרֵ֥⁠ם דָּוִ֖ד מֵ⁠עָלָֽי⁠ו׃","wa⁠yȧẖĕgò֣̇r dá̇wi֣d ʼeţ-ẖa֠rĕḃ⁠wò mé⁠ʻa֨l lĕ⁠madá̇֜y⁠w wa⁠yò֣̇ʼel lá⁠lekeţ֮ ki֣̇y lòֽʼ-nisá̇h֒ wa⁠yò̇֨ʼmer dá̇wi֜d ʼel-şá̌ʼ֗ẇl lò֥ʼ ʼẇka֛l lá⁠le֥keţ bá̇⁠ʼé֖lėh ki֣̇y lò֣ʼ nisi֑̇yţiy wa⁠yĕsiré֥⁠m dá̇wi֖d mé⁠ʻáláֽy⁠w׃"],[17,40,"וַ⁠יִּקַּ֨ח מַקְל֜⁠וֹ בְּ⁠יָד֗⁠וֹ וַ⁠יִּבְחַר־ל֣⁠וֹ חֲמִשָּׁ֣ה חַלֻּקֵֽי־אֲבָנִ֣ים ׀ מִן־הַ⁠נַּ֡חַל וַ⁠יָּ֣שֶׂם אֹ֠תָ⁠ם בִּ⁠כְלִ֨י הָ⁠רֹעִ֧ים אֲשֶׁר־ל֛⁠וֹ וּ⁠בַ⁠יַּלְק֖וּט וְ⁠קַלְּע֣⁠וֹ בְ⁠יָד֑⁠וֹ וַ⁠יִּגַּ֖שׁ אֶל־הַ⁠פְּלִשְׁתִּֽי׃","wa⁠yi̇qȧ֨ẖ maqĕl֜⁠wò bĕ̇⁠yád֗⁠wò wa⁠yi̇bĕẖar-l֣⁠wò ẖàmişá֣̇̌h ẖalu̇qéֽy-ʼàbáni֣ym ׀ min-ha⁠nȧ֡ẖal wa⁠yá֣̇şêm ʼò֠ţá⁠m bi̇⁠kĕli֨y há⁠ròʻi֧ym ʼàşěr-l֛⁠wò ẇ⁠ba⁠yȧlĕq֖ẇt wĕ⁠qalĕ̇ʻ֣⁠wò bĕ⁠yád֑⁠wò wa⁠yi̇gȧ֖ş̌ ʼel-ha⁠pĕ̇lişĕ̌ţiֽ̇y׃"],[17,41,"וַ⁠יֵּ֨לֶךְ֙ הַ⁠פְּלִשְׁתִּ֔י הֹלֵ֥ךְ וְ⁠קָרֵ֖ב אֶל־דָּוִ֑ד וְ⁠הָ⁠אִ֛ישׁ נֹשֵׂ֥א הַ⁠צִּנָּ֖ה לְ⁠פָנָֽי⁠ו׃","wa⁠yé̇֨lekĕ֙ ha⁠pĕ̇lişĕ̌ţi̇֔y hòlé֥kĕ wĕ⁠qáré֖b ʼel-dá̇wi֑d wĕ⁠há⁠ʼi֛yş̌ nòşé֥̂ʼ ha⁠ẕi̇ná֖̇h lĕ⁠pánáֽy⁠w׃"],[17,42,"וַ⁠יַּבֵּ֧ט הַ⁠פְּלִשְׁתִּ֛י וַ⁠יִּרְאֶ֥ה אֶת־דָּוִ֖ד וַ⁠יִּבְזֵ֑⁠הוּ כִּֽי־הָיָ֣ה נַ֔עַר וְ⁠אַדְמֹנִ֖י עִם־יְפֵ֥ה מַרְאֶֽה׃","wa⁠yȧbé֧̇t ha⁠pĕ̇lişĕ̌ţi֛̇y wa⁠yi̇rĕʼe֥h ʼeţ-dá̇wi֖d wa⁠yi̇bĕzé֑⁠hẇ kiֽ̇y-háyá֣h na֔ʻar wĕ⁠ʼadĕmòni֖y ʻim-yĕpé֥h marĕʼeֽh׃"],[17,43,"וַ⁠יֹּ֤אמֶר הַ⁠פְּלִשְׁתִּי֙ אֶל־דָּוִ֔ד הֲ⁠כֶ֣לֶב אָנֹ֔כִי כִּֽי־אַתָּ֥ה בָֽא־אֵלַ֖⁠י בַּ⁠מַּקְל֑וֹת וַ⁠יְקַלֵּ֧ל הַ⁠פְּלִשְׁתִּ֛י אֶת־דָּוִ֖ד בֵּ⁠אלֹהָֽי⁠ו׃","wa⁠yò֤̇ʼmer ha⁠pĕ̇lişĕ̌ţi̇y֙ ʼel-dá̇wi֔d hà⁠ke֣leb ʼánò֔kiy kiֽ̇y-ʼaţá֥̇h báֽʼ-ʼéla֖⁠y bȧ⁠mȧqĕl֑wòţ wa⁠yĕqalé֧̇l ha⁠pĕ̇lişĕ̌ţi֛̇y ʼeţ-dá̇wi֖d bé̇⁠ʼlòháֽy⁠w׃"],[17,44,"וַ⁠יֹּ֥אמֶר הַ⁠פְּלִשְׁתִּ֖י אֶל־דָּוִ֑ד לְכָ֣⁠ה אֵלַ֔⁠י וְ⁠אֶתְּנָה֙ אֶת־בְּשָׂ֣רְ⁠ךָ֔ לְ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם וּ⁠לְ⁠בֶהֱמַ֥ת הַ⁠שָּׂדֶֽה׃ס","wa⁠yò֥̇ʼmer ha⁠pĕ̇lişĕ̌ţi֖̇y ʼel-dá̇wi֑d lĕká֣⁠h ʼéla֔⁠y wĕ⁠ʼeţĕ̇náh֙ ʼeţ-bĕ̇şá֣̂rĕ⁠ká֔ lĕ⁠ʻ֥wòp ha⁠şá̇̌ma֖yim ẇ⁠lĕ⁠behèma֥ţ ha⁠şá̇̂deֽh׃s"],[17,45,"וַ⁠יֹּ֤אמֶר דָּוִד֙ אֶל־הַ⁠פְּלִשְׁתִּ֔י אַתָּה֙ בָּ֣א אֵלַ֔⁠י בְּ⁠חֶ֖רֶב וּ⁠בַ⁠חֲנִ֣ית וּ⁠בְ⁠כִיד֑וֹן וְ⁠אָנֹכִ֣י בָֽא־אֵלֶ֗י⁠ךָ בְּ⁠שֵׁם֙ יְהוָ֣ה צְבָא֔וֹת אֱלֹהֵ֛י מַעַרְכ֥וֹת יִשְׂרָאֵ֖ל אֲשֶׁ֥ר חֵרַֽפְתָּ׃","wa⁠yò֤̇ʼmer dá̇wid֙ ʼel-ha⁠pĕ̇lişĕ̌ţi̇֔y ʼaţá̇h֙ bá֣̇ʼ ʼéla֔⁠y bĕ̇⁠ẖe֖reb ẇ⁠ba⁠ẖàni֣yţ ẇ⁠bĕ⁠kiyd֑wòn wĕ⁠ʼánòki֣y báֽʼ-ʼéle֗y⁠ká bĕ̇⁠şé̌m֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʼèlòhé֛y maʻarĕk֥wòţ yişĕ̂ráʼé֖l ʼàşě֥r ẖéraֽpĕţá̇׃"],[17,46,"הַ⁠יּ֣וֹם הַ⁠זֶּ֡ה יְסַגֶּרְ⁠ךָ֩ יְהוָ֨ה בְּ⁠יָדִ֜⁠י וְ⁠הִכִּיתִ֗⁠ךָ וַ⁠הֲסִרֹתִ֤י אֶת־רֹֽאשְׁ⁠ךָ֙ מֵ⁠עָלֶ֔י⁠ךָ וְ⁠נָ֨תַתִּ֜י פֶּ֣גֶר מַחֲנֵ֤ה פְלִשְׁתִּים֙ הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה לְ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם וּ⁠לְ⁠חַיַּ֣ת הָ⁠אָ֑רֶץ וְ⁠יֵֽדְעוּ֙ כָּל־הָ⁠אָ֔רֶץ כִּ֛י יֵ֥שׁ אֱלֹהִ֖ים לְ⁠יִשְׂרָאֵֽל׃","ha⁠ẏ֣wòm ha⁠zė֡h yĕsagėrĕ⁠ká֩ yĕhwá֨h bĕ̇⁠yádi֜⁠y wĕ⁠hiki̇yţi֗⁠ká wa⁠hàsiròţi֤y ʼeţ-ròֽʼşĕ̌⁠ká֙ mé⁠ʻále֔y⁠ká wĕ⁠ná֨ţaţi̇֜y pė֣ger maẖàné֤h pĕlişĕ̌ţi̇ym֙ ha⁠ẏ֣wòm ha⁠zė֔h lĕ⁠ʻ֥wòp ha⁠şá̇̌ma֖yim ẇ⁠lĕ⁠ẖayȧ֣ţ há⁠ʼá֑reẕ wĕ⁠yéֽdĕʻẇ֙ ká̇l-há⁠ʼá֔reẕ ki֛̇y yé֥ş̌ ʼèlòhi֖ym lĕ⁠yişĕ̂ráʼéֽl׃"],[17,47,"וְ⁠יֵֽדְעוּ֙ כָּל־הַ⁠קָּהָ֣ל הַ⁠זֶּ֔ה כִּֽי־לֹ֛א בְּ⁠חֶ֥רֶב וּ⁠בַ⁠חֲנִ֖ית יְהוֹשִׁ֣יעַ יְהוָ֑ה כִּ֤י לַֽ⁠יהוָה֙ הַ⁠מִּלְחָמָ֔ה וְ⁠נָתַ֥ן אֶתְ⁠כֶ֖ם בְּ⁠יָדֵֽ⁠נוּ׃","wĕ⁠yéֽdĕʻẇ֙ ká̇l-ha⁠qá̇há֣l ha⁠zė֔h kiֽ̇y-lò֛ʼ bĕ̇⁠ẖe֥reb ẇ⁠ba⁠ẖàni֖yţ yĕhwòşǐ֣yʻa yĕhwá֑h ki֤̇y laֽ⁠yhwáh֙ ha⁠mi̇lĕẖámá֔h wĕ⁠náţa֥n ʼeţĕ⁠ke֖m bĕ̇⁠yádéֽ⁠nẇ׃"],[17,48,"וְ⁠הָיָה֙ כִּֽי־קָ֣ם הַ⁠פְּלִשְׁתִּ֔י וַ⁠יֵּ֥לֶךְ וַ⁠יִּקְרַ֖ב לִ⁠קְרַ֣את דָּוִ֑ד וַ⁠יְמַהֵ֣ר דָּוִ֔ד וַ⁠יָּ֥רָץ הַ⁠מַּעֲרָכָ֖ה לִ⁠קְרַ֥את הַ⁠פְּלִשְׁתִּֽי׃","wĕ⁠háyáh֙ kiֽ̇y-qá֣m ha⁠pĕ̇lişĕ̌ţi̇֔y wa⁠yé֥̇lekĕ wa⁠yi̇qĕra֖b li⁠qĕra֣ʼţ dá̇wi֑d wa⁠yĕmahé֣r dá̇wi֔d wa⁠yá֥̇ráẕ ha⁠mȧʻàráká֖h li⁠qĕra֥ʼţ ha⁠pĕ̇lişĕ̌ţiֽ̇y׃"],[17,49,"וַ⁠יִּשְׁלַח֩ דָּוִ֨ד אֶת־יָד֜⁠וֹ אֶל־הַ⁠כֶּ֗לִי וַ⁠יִּקַּ֨ח מִ⁠שָּׁ֥ם אֶ֨בֶן֙ וַ⁠יְקַלַּ֔ע וַ⁠יַּ֥ךְ אֶת־הַ⁠פְּלִשְׁתִּ֖י אֶל־מִצְח֑⁠וֹ וַ⁠תִּטְבַּ֤ע הָ⁠אֶ֨בֶן֙ בְּ⁠מִצְח֔⁠וֹ וַ⁠יִּפֹּ֥ל עַל־פָּנָ֖י⁠ו אָֽרְצָ⁠ה׃","wa⁠yi̇şĕ̌laẖ֩ dá̇wi֨d ʼeţ-yád֜⁠wò ʼel-ha⁠kė֗liy wa⁠yi̇qȧ֨ẖ mi⁠şá֥̇̌m ʼe֨ben֙ wa⁠yĕqalȧ֔ʻ wa⁠yȧ֥kĕ ʼeţ-ha⁠pĕ̇lişĕ̌ţi֖̇y ʼel-miẕĕẖ֑⁠wò wa⁠ţi̇tĕbȧ֤ʻ há⁠ʼe֨ben֙ bĕ̇⁠miẕĕẖ֔⁠wò wa⁠yi̇pò֥̇l ʻal-pá̇ná֖y⁠w ʼáֽrĕẕá⁠h׃"],[17,50,"וַ⁠יֶּחֱזַ֨ק דָּוִ֤ד מִן־הַ⁠פְּלִשְׁתִּי֙ בַּ⁠קֶּ֣לַע וּ⁠בָ⁠אֶ֔בֶן וַ⁠יַּ֥ךְ אֶת־הַ⁠פְּלִשְׁתִּ֖י וַ⁠יְמִיתֵ֑⁠הוּ וְ⁠חֶ֖רֶב אֵ֥ין בְּ⁠יַד־דָּוִֽד׃","wa⁠yėẖèza֨q dá̇wi֤d min-ha⁠pĕ̇lişĕ̌ţi̇y֙ bȧ⁠qė֣laʻ ẇ⁠bá⁠ʼe֔ben wa⁠yȧ֥kĕ ʼeţ-ha⁠pĕ̇lişĕ̌ţi֖̇y wa⁠yĕmiyţé֑⁠hẇ wĕ⁠ẖe֖reb ʼé֥yn bĕ̇⁠yad-dá̇wiֽd׃"],[17,51,"וַ⁠יָּ֣רָץ דָּ֠וִד וַ⁠יַּעֲמֹ֨ד אֶל־הַ⁠פְּלִשְׁתִּ֜י וַ⁠יִּקַּ֣ח אֶת־חַ֠רְבּ⁠וֹ וַֽ⁠יִּשְׁלְפָ֤⁠הּ מִ⁠תַּעְרָ⁠הּ֙ וַ⁠יְמֹ֣תְתֵ֔⁠הוּ וַ⁠יִּכְרָת־בָּ֖⁠הּ אֶת־רֹאשׁ֑⁠וֹ וַ⁠יִּרְא֧וּ הַ⁠פְּלִשְׁתִּ֛ים כִּֽי־מֵ֥ת גִּבּוֹרָ֖⁠ם וַ⁠יָּנֻֽסוּ׃","wa⁠yá֣̇ráẕ dá̇֠wid wa⁠yȧʻàmò֨d ʼel-ha⁠pĕ̇lişĕ̌ţi̇֜y wa⁠yi̇qȧ֣ẖ ʼeţ-ẖa֠rĕḃ⁠wò waֽ⁠yi̇şĕ̌lĕpá֤⁠ḣ mi⁠ţȧʻĕrá⁠ḣ֙ wa⁠yĕmò֣ţĕţé֔⁠hẇ wa⁠yi̇kĕráţ-bá֖̇⁠ḣ ʼeţ-ròʼş֑̌⁠wò wa⁠yi̇rĕʼ֧ẇ ha⁠pĕ̇lişĕ̌ţi֛̇ym kiֽ̇y-mé֥ţ gi̇ḃwòrá֖⁠m wa⁠yá̇nuֽsẇ׃"],[17,52,"וַ⁠יָּקֻ֣מוּ אַנְשֵׁי֩ יִשְׂרָאֵ֨ל וִ⁠יהוּדָ֜ה וַ⁠יָּרִ֗עוּ וַֽ⁠יִּרְדְּפוּ֙ אֶת־הַ⁠פְּלִשְׁתִּ֔ים עַד־בּוֹאֲ⁠ךָ֣ גַ֔יְא וְ⁠עַ֖ד שַׁעֲרֵ֣י עֶקְר֑וֹן וַֽ⁠יִּפְּל֞וּ חַֽלְלֵ֤י פְלִשְׁתִּים֙ בְּ⁠דֶ֣רֶךְ שַׁעֲרַ֔יִם וְ⁠עַד־גַּ֖ת וְ⁠עַד־עֶקְרֽוֹן׃","wa⁠yá̇qu֣mẇ ʼanĕşé̌y֩ yişĕ̂ráʼé֨l wi⁠yhẇdá֜h wa⁠yá̇ri֗ʻẇ waֽ⁠yi̇rĕdĕ̇pẇ֙ ʼeţ-ha⁠pĕ̇lişĕ̌ţi̇֔ym ʻad-ḃwòʼà⁠ká֣ ga֔yĕʼ wĕ⁠ʻa֖d şǎʻàré֣y ʻeqĕr֑wòn waֽ⁠yi̇pĕ̇l֞ẇ ẖaֽlĕlé֤y pĕlişĕ̌ţi̇ym֙ bĕ̇⁠de֣rekĕ şǎʻàra֔yim wĕ⁠ʻad-gȧ֖ţ wĕ⁠ʻad-ʻeqĕrֽwòn׃"],[17,53,"וַ⁠יָּשֻׁ֨בוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל מִ⁠דְּלֹ֖ק אַחֲרֵ֣י פְלִשְׁתִּ֑ים וַ⁠יָּשֹׁ֖סּוּ אֶת־מַחֲנֵי⁠הֶֽם׃","wa⁠yá̇şǔ֨bẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l mi⁠dĕ̇lò֖q ʼaẖàré֣y pĕlişĕ̌ţi֑̇ym wa⁠yá̇şò֖̌ṡẇ ʼeţ-maẖànéy⁠heֽm׃"],[17,54,"וַ⁠יִּקַּ֤ח דָּוִד֙ אֶת־רֹ֣אשׁ הַ⁠פְּלִשְׁתִּ֔י וַ⁠יְבִאֵ֖⁠הוּ יְרוּשָׁלִָ֑ם וְ⁠אֶת־כֵּלָ֖י⁠ו שָׂ֥ם בְּ⁠אָהֳלֽ⁠וֹ׃ס","wa⁠yi̇qȧ֤ẖ dá̇wid֙ ʼeţ-rò֣ʼş̌ ha⁠pĕ̇lişĕ̌ţi̇֔y wa⁠yĕbiʼé֖⁠hẇ yĕrẇşá̌liá֑m wĕ⁠ʼeţ-ké̇lá֖y⁠w şá֥̂m bĕ̇⁠ʼáholֽ⁠wò׃s"],[17,55,"וְ⁠כִ⁠רְא֨וֹת שָׁא֜וּל אֶת־דָּוִ֗ד יֹצֵא֙ לִ⁠קְרַ֣את הַ⁠פְּלִשְׁתִּ֔י אָמַ֗ר אֶל־אַבְנֵר֙ שַׂ֣ר הַ⁠צָּבָ֔א בֶּן־מִי־זֶ֥ה הַ⁠נַּ֖עַר אַבְנֵ֑ר וַ⁠יֹּ֣אמֶר אַבְנֵ֔ר חֵֽי־נַפְשְׁ⁠ךָ֥ הַ⁠מֶּ֖לֶךְ אִם־יָדָֽעְתִּי׃","wĕ⁠ki⁠rĕʼ֨wòţ şá̌ʼ֜ẇl ʼeţ-dá̇wi֗d yòẕéʼ֙ li⁠qĕra֣ʼţ ha⁠pĕ̇lişĕ̌ţi̇֔y ʼáma֗r ʼel-ʼabĕnér֙ şâ֣r ha⁠ẕá̇bá֔ʼ bėn-miy-ze֥h ha⁠nȧ֖ʻar ʼabĕné֑r wa⁠yò֣̇ʼmer ʼabĕné֔r ẖéֽy-napĕşĕ̌⁠ká֥ ha⁠mė֖lekĕ ʼim-yádáֽʻĕţi̇y׃"],[17,56,"וַ⁠יֹּ֖אמֶר הַ⁠מֶּ֑לֶךְ שְׁאַ֣ל אַתָּ֔ה בֶּן־מִי־זֶ֖ה הָ⁠עָֽלֶם׃ס","wa⁠yò֖̇ʼmer ha⁠mė֑lekĕ şĕ̌ʼa֣l ʼaţá̇֔h bėn-miy-ze֖h há⁠ʻáֽlem׃s"],[17,57,"וּ⁠כְ⁠שׁ֣וּב דָּוִ֗ד מֵֽ⁠הַכּוֹת֙ אֶת־הַ⁠פְּלִשְׁתִּ֔י וַ⁠יִּקַּ֤ח אֹת⁠וֹ֙ אַבְנֵ֔ר וַ⁠יְבִאֵ֖⁠הוּ לִ⁠פְנֵ֣י שָׁא֑וּל וְ⁠רֹ֥אשׁ הַ⁠פְּלִשְׁתִּ֖י בְּ⁠יָדֽ⁠וֹ׃","ẇ⁠kĕ⁠ş֣̌ẇb dá̇wi֗d méֽ⁠hak̇wòţ֙ ʼeţ-ha⁠pĕ̇lişĕ̌ţi̇֔y wa⁠yi̇qȧ֤ẖ ʼòţ⁠wò֙ ʼabĕné֔r wa⁠yĕbiʼé֖⁠hẇ li⁠pĕné֣y şá̌ʼ֑ẇl wĕ⁠rò֥ʼş̌ ha⁠pĕ̇lişĕ̌ţi֖̇y bĕ̇⁠yádֽ⁠wò׃"],[17,58,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ שָׁא֔וּל בֶּן־מִ֥י אַתָּ֖ה הַ⁠נָּ֑עַר וַ⁠יֹּ֣אמֶר דָּוִ֔ד בֶּֽן־עַבְדְּ⁠ךָ֥ יִשַׁ֖י בֵּ֥ית הַלַּחְמִֽי׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ şá̌ʼ֔ẇl bėn-mi֥y ʼaţá֖̇h ha⁠ná֑̇ʻar wa⁠yò֣̇ʼmer dá̇wi֔d bėֽn-ʻabĕdĕ̇⁠ká֥ yişǎ֖y bé֥̇yţ halȧẖĕmiֽy׃"],[18,1,"וַ⁠יְהִ֗י כְּ⁠כַלֹּת⁠וֹ֙ לְ⁠דַבֵּ֣ר אֶל־שָׁא֔וּל וְ⁠נֶ֨פֶשׁ֙ יְה֣וֹנָתָ֔ן נִקְשְׁרָ֖ה בְּ⁠נֶ֣פֶשׁ דָּוִ֑ד ו⁠יאהבו יְהוֹנָתָ֖ן כְּ⁠נַפְשֽׁ⁠וֹ׃","wa⁠yĕhi֗y kĕ̇⁠kalò̇ţ⁠wò֙ lĕ⁠dabé֣̇r ʼel-şá̌ʼ֔ẇl wĕ⁠ne֨peş̌֙ yĕh֣wònáţá֔n niqĕşĕ̌rá֖h bĕ̇⁠ne֣peş̌ dá̇wi֑d w⁠yʼhbw yĕhwònáţá֖n kĕ̇⁠napĕşֽ̌⁠wò׃"],[18,2,"וַ⁠יִּקָּחֵ֥⁠הוּ שָׁא֖וּל בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וְ⁠לֹ֣א נְתָנ֔⁠וֹ לָ⁠שׁ֖וּב בֵּ֥ית אָבִֽי⁠ו׃","wa⁠yi̇qá̇ẖé֥⁠hẇ şá̌ʼ֖ẇl bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wĕ⁠lò֣ʼ nĕţán֔⁠wò lá⁠ş֖̌ẇb bé֥̇yţ ʼábiֽy⁠w׃"],[18,3,"וַ⁠יִּכְרֹ֧ת יְהוֹנָתָ֛ן וְ⁠דָוִ֖ד בְּרִ֑ית בְּ⁠אַהֲבָת֥⁠וֹ אֹת֖⁠וֹ כְּ⁠נַפְשֽׁ⁠וֹ׃","wa⁠yi̇kĕrò֧ţ yĕhwònáţá֛n wĕ⁠dáwi֖d bĕ̇ri֑yţ bĕ̇⁠ʼahàbáţ֥⁠wò ʼòţ֖⁠wò kĕ̇⁠napĕşֽ̌⁠wò׃"],[18,4,"וַ⁠יִּתְפַּשֵּׁ֣ט יְהוֹנָתָ֗ן אֶֽת־הַ⁠מְּעִיל֙ אֲשֶׁ֣ר עָלָ֔י⁠ו וַֽ⁠יִּתְּנֵ֖⁠הוּ לְ⁠דָוִ֑ד וּ⁠מַדָּ֕י⁠ו וְ⁠עַד־חַרְבּ֥⁠וֹ וְ⁠עַד־קַשְׁתּ֖⁠וֹ וְ⁠עַד־חֲגֹרֽ⁠וֹ׃","wa⁠yi̇ţĕpȧşé֣̇̌t yĕhwònáţá֗n ʼeֽţ-ha⁠mĕ̇ʻiyl֙ ʼàşě֣r ʻálá֔y⁠w waֽ⁠yi̇ţĕ̇né֖⁠hẇ lĕ⁠dáwi֑d ẇ⁠madá̇֕y⁠w wĕ⁠ʻad-ẖarĕḃ֥⁠wò wĕ⁠ʻad-qaşĕ̌ţ֖̇⁠wò wĕ⁠ʻad-ẖàgòrֽ⁠wò׃"],[18,5,"וַ⁠יֵּצֵ֨א דָוִ֜ד בְּ⁠כֹל֩ אֲשֶׁ֨ר יִשְׁלָחֶ֤⁠נּוּ שָׁאוּל֙ יַשְׂכִּ֔יל וַ⁠יְשִׂמֵ֣⁠הוּ שָׁא֔וּל עַ֖ל אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֑ה וַ⁠יִּיטַב֙ בְּ⁠עֵינֵ֣י כָל־הָ⁠עָ֔ם וְ⁠גַ֕ם בְּ⁠עֵינֵ֖י עַבְדֵ֥י שָׁאֽוּל׃פ","wa⁠yé̇ẕé֨ʼ dáwi֜d bĕ̇⁠kòl֩ ʼàşě֨r yişĕ̌láẖe֤⁠ṅẇ şá̌ʼẇl֙ yaşĕ̂ki̇֔yl wa⁠yĕşîmé֣⁠hẇ şá̌ʼ֔ẇl ʻa֖l ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֑h wa⁠yi̇ytab֙ bĕ̇⁠ʻéyné֣y kál-há⁠ʻá֔m wĕ⁠ga֕m bĕ̇⁠ʻéyné֖y ʻabĕdé֥y şá̌ʼֽẇl׃p"],[18,6,"וַ⁠יְהִ֣י בְּ⁠בוֹאָ֗⁠ם בְּ⁠שׁ֤וּב דָּוִד֙ מֵ⁠הַכּ֣וֹת אֶת־הַ⁠פְּלִשְׁתִּ֔י וַ⁠תֵּצֶ֨אנָה הַ⁠נָּשִׁ֜ים מִ⁠כָּל־עָרֵ֤י יִשְׂרָאֵל֙ ל⁠שור וְ⁠הַ⁠מְּחֹל֔וֹת לִ⁠קְרַ֖את שָׁא֣וּל הַ⁠מֶּ֑לֶךְ בְּ⁠תֻפִּ֥ים בְּ⁠שִׂמְחָ֖ה וּ⁠בְ⁠שָׁלִשִֽׁים׃","wa⁠yĕhi֣y bĕ̇⁠bwòʼá֗⁠m bĕ̇⁠ş֤̌ẇb dá̇wid֙ mé⁠hak֣̇wòţ ʼeţ-ha⁠pĕ̇lişĕ̌ţi̇֔y wa⁠ţé̇ẕe֨ʼnáh ha⁠ná̇şǐ֜ym mi⁠ká̇l-ʻáré֤y yişĕ̂ráʼél֙ l⁠şwr wĕ⁠ha⁠mĕ̇ẖòl֔wòţ li⁠qĕra֖ʼţ şá̌ʼ֣ẇl ha⁠mė֑lekĕ bĕ̇⁠ţupi֥̇ym bĕ̇⁠şîmĕẖá֖h ẇ⁠bĕ⁠şá̌lişǐֽym׃"],[18,7,"וַֽ⁠תַּעֲנֶ֛ינָה הַ⁠נָּשִׁ֥ים הַֽ⁠מְשַׂחֲק֖וֹת וַ⁠תֹּאמַ֑רְןָ הִכָּ֤ה שָׁאוּל֙ ב⁠אלפ⁠ו וְ⁠דָוִ֖ד בְּ⁠רִבְבֹתָֽי⁠ו׃","waֽ⁠ţȧʻàne֛ynáh ha⁠ná̇şǐ֥ym haֽ⁠mĕşâẖàq֖wòţ wa⁠ţò̇ʼma֑rĕná hiká֤̇h şá̌ʼẇl֙ b⁠ʼlp⁠w wĕ⁠dáwi֖d bĕ̇⁠ribĕbòţáֽy⁠w׃"],[18,8,"וַ⁠יִּ֨חַר לְ⁠שָׁא֜וּל מְאֹ֗ד וַ⁠יֵּ֤רַע בְּ⁠עֵינָי⁠ו֙ הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה וַ⁠יֹּ֗אמֶר נָתְנ֤וּ לְ⁠דָוִד֙ רְבָב֔וֹת וְ⁠לִ֥⁠י נָתְנ֖וּ הָ⁠אֲלָפִ֑ים וְ⁠ע֥וֹד ל֖⁠וֹ אַ֥ךְ הַ⁠מְּלוּכָֽה׃","wa⁠yi̇֨ẖar lĕ⁠şá̌ʼ֜ẇl mĕʼò֗d wa⁠yé֤̇raʻ bĕ̇⁠ʻéynáy⁠w֙ ha⁠dá̇bá֣r ha⁠zė֔h wa⁠yò̇֗ʼmer náţĕn֤ẇ lĕ⁠dáwid֙ rĕbáb֔wòţ wĕ⁠li֥⁠y náţĕn֖ẇ há⁠ʼàlápi֑ym wĕ⁠ʻ֥wòd l֖⁠wò ʼa֥kĕ ha⁠mĕ̇lẇkáֽh׃"],[18,9,"וַ⁠יְהִ֥י שָׁא֖וּל עון אֶת־דָּוִ֑ד מֵ⁠הַ⁠יּ֥וֹם הַ⁠ה֖וּא וָ⁠הָֽלְאָה׃ס","wa⁠yĕhi֥y şá̌ʼ֖ẇl ʻwn ʼeţ-dá̇wi֑d mé⁠ha⁠ẏ֥wòm ha⁠h֖ẇʼ wá⁠háֽlĕʼáh׃s"],[18,10,"וַ⁠יְהִ֣י מִֽ⁠מָּחֳרָ֗ת וַ⁠תִּצְלַ֣ח רוּחַ֩ אֱלֹהִ֨ים ׀ רָעָ֤ה ׀ אֶל־שָׁאוּל֙ וַ⁠יִּתְנַבֵּ֣א בְ⁠תוֹךְ־הַ⁠בַּ֔יִת וְ⁠דָוִ֛ד מְנַגֵּ֥ן בְּ⁠יָד֖⁠וֹ כְּ⁠י֣וֹם ׀ בְּ⁠י֑וֹם וְ⁠הַ⁠חֲנִ֖ית בְּ⁠יַד־שָׁאֽוּל׃","wa⁠yĕhi֣y miֽ⁠má̇ẖorá֗ţ wa⁠ţi̇ẕĕla֣ẖ rẇẖa֩ ʼèlòhi֨ym ׀ ráʻá֤h ׀ ʼel-şá̌ʼẇl֙ wa⁠yi̇ţĕnabé֣̇ʼ bĕ⁠ţwòkĕ-ha⁠bȧ֔yiţ wĕ⁠dáwi֛d mĕnagé֥̇n bĕ̇⁠yád֖⁠wò kĕ̇⁠y֣wòm ׀ bĕ̇⁠y֑wòm wĕ⁠ha⁠ẖàni֖yţ bĕ̇⁠yad-şá̌ʼֽẇl׃"],[18,11,"וַ⁠יָּ֤טֶל שָׁאוּל֙ אֶֽת־הַ⁠חֲנִ֔ית וַ⁠יֹּ֕אמֶר אַכֶּ֥ה בְ⁠דָוִ֖ד וּ⁠בַ⁠קִּ֑יר וַ⁠יִּסֹּ֥ב דָּוִ֛ד מִ⁠פָּנָ֖י⁠ו פַּעֲמָֽיִם׃","wa⁠yá֤̇tel şá̌ʼẇl֙ ʼeֽţ-ha⁠ẖàni֔yţ wa⁠yò̇֕ʼmer ʼakė֥h bĕ⁠dáwi֖d ẇ⁠ba⁠qi֑̇yr wa⁠yi̇sò֥̇b dá̇wi֛d mi⁠pá̇ná֖y⁠w pȧʻàmáֽyim׃"],[18,12,"וַ⁠יִּרָ֥א שָׁא֖וּל מִ⁠לִּ⁠פְנֵ֣י דָוִ֑ד כִּֽי־הָיָ֤ה יְהוָה֙ עִמּ֔⁠וֹ וּ⁠מֵ⁠עִ֥ם שָׁא֖וּל סָֽר׃","wa⁠yi̇rá֥ʼ şá̌ʼ֖ẇl mi⁠li̇⁠pĕné֣y dáwi֑d kiֽ̇y-háyá֤h yĕhwáh֙ ʻiṁ֔⁠wò ẇ⁠mé⁠ʻi֥m şá̌ʼ֖ẇl sáֽr׃"],[18,13,"וַ⁠יְסִרֵ֤⁠הוּ שָׁאוּל֙ מֵֽ⁠עִמּ֔⁠וֹ וַ⁠יְשִׂמֵ֥⁠הוּ ל֖⁠וֹ שַׂר־אָ֑לֶף וַ⁠יֵּצֵ֥א וַ⁠יָּבֹ֖א לִ⁠פְנֵ֥י הָ⁠עָֽם׃פ","wa⁠yĕsiré֤⁠hẇ şá̌ʼẇl֙ méֽ⁠ʻiṁ֔⁠wò wa⁠yĕşîmé֥⁠hẇ l֖⁠wò şâr-ʼá֑lep wa⁠yé̇ẕé֥ʼ wa⁠yá̇bò֖ʼ li⁠pĕné֥y há⁠ʻáֽm׃p"],[18,14,"וַ⁠יְהִ֥י דָוִ֛ד לְ⁠כָל־דרכו מַשְׂכִּ֑יל וַֽ⁠יהוָ֖ה עִמּֽ⁠וֹ׃","wa⁠yĕhi֥y dáwi֛d lĕ⁠kál-drkw maşĕ̂ki֑̇yl waֽ⁠yhwá֖h ʻiṁֽ⁠wò׃"],[18,15,"וַ⁠יַּ֣רְא שָׁא֔וּל אֲשֶׁר־ה֖וּא מַשְׂכִּ֣יל מְאֹ֑ד וַ⁠יָּ֖גָר מִ⁠פָּנָֽי⁠ו׃","wa⁠yȧ֣rĕʼ şá̌ʼ֔ẇl ʼàşěr-h֖ẇʼ maşĕ̂ki֣̇yl mĕʼò֑d wa⁠yá֖̇gár mi⁠pá̇náֽy⁠w׃"],[18,16,"וְ⁠כָל־יִשְׂרָאֵל֙ וִ⁠יהוּדָ֔ה אֹהֵ֖ב אֶת־דָּוִ֑ד כִּֽי־ה֛וּא יוֹצֵ֥א וָ⁠בָ֖א לִ⁠פְנֵי⁠הֶֽם׃פ","wĕ⁠kál-yişĕ̂ráʼél֙ wi⁠yhẇdá֔h ʼòhé֖b ʼeţ-dá̇wi֑d kiֽ̇y-h֛ẇʼ ywòẕé֥ʼ wá⁠bá֖ʼ li⁠pĕnéy⁠heֽm׃p"],[18,17,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל אֶל־דָּוִ֗ד הִנֵּה֩ בִתִּ֨⁠י הַ⁠גְּדוֹלָ֤ה מֵרַב֙ אֹתָ⁠הּ֙ אֶתֶּן־לְ⁠ךָ֣ לְ⁠אִשָּׁ֔ה אַ֚ךְ הֱיֵה־לִּ֣⁠י לְ⁠בֶן־חַ֔יִל וְ⁠הִלָּחֵ֖ם מִלְחֲמ֣וֹת יְהוָ֑ה וְ⁠שָׁא֣וּל אָמַ֗ר אַל־תְּהִ֤י יָדִ⁠י֙ בּ֔⁠וֹ וּ⁠תְהִי־ב֖⁠וֹ יַד־פְּלִשְׁתִּֽים׃ס","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl ʼel-dá̇wi֗d hiné̇h֩ biţi̇֨⁠y ha⁠gĕ̇dwòlá֤h mérab֙ ʼòţá⁠ḣ֙ ʼeţėn-lĕ⁠ká֣ lĕ⁠ʼişá̇̌֔h ʼa֚kĕ hèyéh-li֣̇⁠y lĕ⁠ben-ẖa֔yil wĕ⁠hilá̇ẖé֖m milĕẖàm֣wòţ yĕhwá֑h wĕ⁠şá̌ʼ֣ẇl ʼáma֗r ʼal-ţĕ̇hi֤y yádi⁠y֙ ḃ֔⁠wò ẇ⁠ţĕhiy-b֖⁠wò yad-pĕ̇lişĕ̌ţiֽ̇ym׃s"],[18,18,"וַ⁠יֹּ֨אמֶר דָּוִ֜ד אֶל־שָׁא֗וּל מִ֤י אָֽנֹכִי֙ וּ⁠מִ֣י חַיַּ֔⁠י מִשְׁפַּ֥חַת אָבִ֖⁠י בְּ⁠יִשְׂרָאֵ֑ל כִּֽי־אֶהְיֶ֥ה חָתָ֖ן לַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֨ʼmer dá̇wi֜d ʼel-şá̌ʼ֗ẇl mi֤y ʼáֽnòkiy֙ ẇ⁠mi֣y ẖayȧ֔⁠y mişĕ̌pȧ֥ẖaţ ʼábi֖⁠y bĕ̇⁠yişĕ̂ráʼé֑l kiֽ̇y-ʼehĕye֥h ẖáţá֖n la⁠mėֽlekĕ׃"],[18,19,"וַ⁠יְהִ֗י בְּ⁠עֵ֥ת תֵּ֛ת אֶת־מֵרַ֥ב בַּת־שָׁא֖וּל לְ⁠דָוִ֑ד וְ⁠הִ֧יא נִתְּנָ֛ה לְ⁠עַדְרִיאֵ֥ל הַ⁠מְּחֹלָתִ֖י לְ⁠אִשָּֽׁה׃","wa⁠yĕhi֗y bĕ̇⁠ʻé֥ţ ţé֛̇ţ ʼeţ-méra֥b bȧţ-şá̌ʼ֖ẇl lĕ⁠dáwi֑d wĕ⁠hi֧yʼ niţĕ̇ná֛h lĕ⁠ʻadĕriyʼé֥l ha⁠mĕ̇ẖòláţi֖y lĕ⁠ʼişáֽ̇̌h׃"],[18,20,"וַ⁠תֶּאֱהַ֛ב מִיכַ֥ל בַּת־שָׁא֖וּל אֶת־דָּוִ֑ד וַ⁠יַּגִּ֣דוּ לְ⁠שָׁא֔וּל וַ⁠יִּשַׁ֥ר הַ⁠דָּבָ֖ר בְּ⁠עֵינָֽי⁠ו׃","wa⁠ţėʼèha֛b miyka֥l bȧţ-şá̌ʼ֖ẇl ʼeţ-dá̇wi֑d wa⁠yȧgi֣̇dẇ lĕ⁠şá̌ʼ֔ẇl wa⁠yi̇şǎ֥r ha⁠dá̇bá֖r bĕ̇⁠ʻéynáֽy⁠w׃"],[18,21,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל אֶתְּנֶ֤⁠נָּה לּ⁠וֹ֙ וּ⁠תְהִי־ל֣⁠וֹ לְ⁠מוֹקֵ֔שׁ וּ⁠תְהִי־ב֖⁠וֹ יַד־פְּלִשְׁתִּ֑ים וַ⁠יֹּ֤אמֶר שָׁאוּל֙ אֶל־דָּוִ֔ד בִּ⁠שְׁתַּ֛יִם תִּתְחַתֵּ֥ן בִּ֖⁠י הַ⁠יּֽוֹם׃","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl ʼeţĕ̇ne֤⁠ná̇h l̇⁠wò֙ ẇ⁠ţĕhiy-l֣⁠wò lĕ⁠mwòqé֔ş̌ ẇ⁠ţĕhiy-b֖⁠wò yad-pĕ̇lişĕ̌ţi֑̇ym wa⁠yò֤̇ʼmer şá̌ʼẇl֙ ʼel-dá̇wi֔d bi̇⁠şĕ̌ţȧ֛yim ţi̇ţĕẖaţé֥̇n bi֖̇⁠y ha⁠ẏֽwòm׃"],[18,22,"וַ⁠יְצַ֨ו שָׁא֜וּל אֶת־עבדו דַּבְּר֨וּ אֶל־דָּוִ֤ד בַּ⁠לָּט֙ לֵ⁠אמֹ֔ר הִנֵּ֨ה חָפֵ֤ץ בְּ⁠ךָ֙ הַ⁠מֶּ֔לֶךְ וְ⁠כָל־עֲבָדָ֖י⁠ו אֲהֵב֑וּ⁠ךָ וְ⁠עַתָּ֖ה הִתְחַתֵּ֥ן בַּ⁠מֶּֽלֶךְ׃","wa⁠yĕẕa֨w şá̌ʼ֜ẇl ʼeţ-ʻbdw dȧbĕ̇r֨ẇ ʼel-dá̇wi֤d bȧ⁠lá̇t֙ lé⁠ʼmò֔r hiné̇֨h ẖápé֤ẕ bĕ̇⁠ká֙ ha⁠mė֔lekĕ wĕ⁠kál-ʻàbádá֖y⁠w ʼàhéb֑ẇ⁠ká wĕ⁠ʻaţá֖̇h hiţĕẖaţé֥̇n bȧ⁠mėֽlekĕ׃"],[18,23,"וַֽ⁠יְדַבְּר֞וּ עַבְדֵ֤י שָׁאוּל֙ בְּ⁠אָזְנֵ֣י דָוִ֔ד אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וַ⁠יֹּ֣אמֶר דָּוִ֗ד הַֽ⁠נְקַלָּ֤ה בְ⁠עֵֽינֵי⁠כֶם֙ הִתְחַתֵּ֣ן בַּ⁠מֶּ֔לֶךְ וְ⁠אָנֹכִ֖י אִֽישׁ־רָ֥שׁ וְ⁠נִקְלֶֽה׃","waֽ⁠yĕdabĕ̇r֞ẇ ʻabĕdé֤y şá̌ʼẇl֙ bĕ̇⁠ʼázĕné֣y dáwi֔d ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wa⁠yò֣̇ʼmer dá̇wi֗d haֽ⁠nĕqalá֤̇h bĕ⁠ʻéֽynéy⁠kem֙ hiţĕẖaţé֣̇n bȧ⁠mė֔lekĕ wĕ⁠ʼánòki֖y ʼiֽyş̌-rá֥ş̌ wĕ⁠niqĕleֽh׃"],[18,24,"וַ⁠יַּגִּ֜דוּ עַבְדֵ֥י שָׁא֛וּל ל֖⁠וֹ לֵ⁠אמֹ֑ר כַּ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה דִּבֶּ֥ר דָּוִֽד׃פ","wa⁠yȧgi̇֜dẇ ʻabĕdé֥y şá̌ʼ֛ẇl l֖⁠wò lé⁠ʼmò֑r kȧ⁠dĕ̇bári֥ym há⁠ʼé֖lėh di̇bė֥r dá̇wiֽd׃p"],[18,25,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל כֹּֽה־תֹאמְר֣וּ לְ⁠דָוִ֗ד אֵֽין־חֵ֤פֶץ לַ⁠מֶּ֨לֶךְ֙ בְּ⁠מֹ֔הַר כִּ֗י בְּ⁠מֵאָה֙ עָרְל֣וֹת פְּלִשְׁתִּ֔ים לְ⁠הִנָּקֵ֖ם בְּ⁠אֹיְבֵ֣י הַ⁠מֶּ֑לֶךְ וְ⁠שָׁא֣וּל חָשַׁ֔ב לְ⁠הַפִּ֥יל אֶת־דָּוִ֖ד בְּ⁠יַד־פְּלִשְׁתִּֽים׃","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl kòֽ̇h-ţòʼmĕr֣ẇ lĕ⁠dáwi֗d ʼéֽyn-ẖé֤peẕ la⁠mė֨lekĕ֙ bĕ̇⁠mò֔har ki̇֗y bĕ̇⁠méʼáh֙ ʻárĕl֣wòţ pĕ̇lişĕ̌ţi̇֔ym lĕ⁠hiná̇qé֖m bĕ̇⁠ʼòyĕbé֣y ha⁠mė֑lekĕ wĕ⁠şá̌ʼ֣ẇl ẖáşǎ֔b lĕ⁠hapi֥̇yl ʼeţ-dá̇wi֖d bĕ̇⁠yad-pĕ̇lişĕ̌ţiֽ̇ym׃"],[18,26,"וַ⁠יַּגִּ֨דוּ עֲבָדָ֤י⁠ו לְ⁠דָוִד֙ אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וַ⁠יִּשַׁ֤ר הַ⁠דָּבָר֙ בְּ⁠עֵינֵ֣י דָוִ֔ד לְ⁠הִתְחַתֵּ֖ן בַּ⁠מֶּ֑לֶךְ וְ⁠לֹ֥א מָלְא֖וּ הַ⁠יָּמִֽים׃","wa⁠yȧgi̇֨dẇ ʻàbádá֤y⁠w lĕ⁠dáwid֙ ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wa⁠yi̇şǎ֤r ha⁠dá̇bár֙ bĕ̇⁠ʻéyné֣y dáwi֔d lĕ⁠hiţĕẖaţé֖̇n bȧ⁠mė֑lekĕ wĕ⁠lò֥ʼ málĕʼ֖ẇ ha⁠yá̇miֽym׃"],[18,27,"וַ⁠יָּ֨קָם דָּוִ֜ד וַ⁠יֵּ֣לֶךְ ׀ ה֣וּא וַ⁠אֲנָשָׁ֗י⁠ו וַ⁠יַּ֣ךְ בַּ⁠פְּלִשְׁתִּים֮ מָאתַ֣יִם אִישׁ֒ וַ⁠יָּבֵ֤א דָוִד֙ אֶת־עָרְלֹ֣תֵי⁠הֶ֔ם וַ⁠יְמַלְא֣וּ⁠ם לַ⁠מֶּ֔לֶךְ לְ⁠הִתְחַתֵּ֖ן בַּ⁠מֶּ֑לֶךְ וַ⁠יִּתֶּן־ל֥⁠וֹ שָׁא֛וּל אֶת־מִיכַ֥ל בִּתּ֖⁠וֹ לְ⁠אִשָּֽׁה׃ס","wa⁠yá̇֨qám dá̇wi֜d wa⁠yé֣̇lekĕ ׀ h֣ẇʼ wa⁠ʼànáşá̌֗y⁠w wa⁠yȧ֣kĕ bȧ⁠pĕ̇lişĕ̌ţi̇ym֮ máʼţa֣yim ʼiyş̌֒ wa⁠yá̇bé֤ʼ dáwid֙ ʼeţ-ʻárĕlò֣ţéy⁠he֔m wa⁠yĕmalĕʼ֣ẇ⁠m la⁠mė֔lekĕ lĕ⁠hiţĕẖaţé֖̇n bȧ⁠mė֑lekĕ wa⁠yi̇ţėn-l֥⁠wò şá̌ʼ֛ẇl ʼeţ-miyka֥l bi̇ţ֖̇⁠wò lĕ⁠ʼişáֽ̇̌h׃s"],[18,28,"וַ⁠יַּ֤רְא שָׁאוּל֙ וַ⁠יֵּ֔דַע כִּ֥י יְהוָ֖ה עִם־דָּוִ֑ד וּ⁠מִיכַ֥ל בַּת־שָׁא֖וּל אֲהֵבַֽתְ⁠הוּ׃","wa⁠yȧ֤rĕʼ şá̌ʼẇl֙ wa⁠yé̇֔daʻ ki֥̇y yĕhwá֖h ʻim-dá̇wi֑d ẇ⁠miyka֥l bȧţ-şá̌ʼ֖ẇl ʼàhébaֽţĕ⁠hẇ׃"],[18,29,"וַ⁠יֹּ֣אסֶף שָׁא֗וּל לֵ⁠רֹ֛א מִ⁠פְּנֵ֥י דָוִ֖ד ע֑וֹד וַ⁠יְהִ֥י שָׁא֛וּל אֹיֵ֥ב אֶת־דָּוִ֖ד כָּל־הַ⁠יָּמִֽים׃ס","wa⁠yò֣̇ʼsep şá̌ʼ֗ẇl lé⁠rò֛ʼ mi⁠pĕ̇né֥y dáwi֖d ʻ֑wòd wa⁠yĕhi֥y şá̌ʼ֛ẇl ʼòyé֥b ʼeţ-dá̇wi֖d ká̇l-ha⁠yá̇miֽym׃s"],[18,30,"וַ⁠יֵּצְא֖וּ שָׂרֵ֣י פְלִשְׁתִּ֑ים וַ⁠יְהִ֣י ׀ מִ⁠דֵּ֣י צֵאתָ֗⁠ם שָׂכַ֤ל דָּוִד֙ מִ⁠כֹּל֙ עַבְדֵ֣י שָׁא֔וּל וַ⁠יִּיקַ֥ר שְׁמ֖⁠וֹ מְאֹֽד׃ס","wa⁠yé̇ẕĕʼ֖ẇ şá̂ré֣y pĕlişĕ̌ţi֑̇ym wa⁠yĕhi֣y ׀ mi⁠dé֣̇y ẕéʼţá֗⁠m şá̂ka֤l dá̇wid֙ mi⁠kò̇l֙ ʻabĕdé֣y şá̌ʼ֔ẇl wa⁠yi̇yqa֥r şĕ̌m֖⁠wò mĕʼòֽd׃s"],[19,1,"וַ⁠יְדַבֵּ֣ר שָׁא֗וּל אֶל־יוֹנָתָ֤ן בְּנ⁠וֹ֙ וְ⁠אֶל־כָּל־עֲבָדָ֔י⁠ו לְ⁠הָמִ֖ית אֶת־דָּוִ֑ד וִ⁠יהֽוֹנָתָן֙ בֶּן־שָׁא֔וּל חָפֵ֥ץ בְּ⁠דָוִ֖ד מְאֹֽד׃","wa⁠yĕdabé֣̇r şá̌ʼ֗ẇl ʼel-ywònáţá֤n bĕ̇n⁠wò֙ wĕ⁠ʼel-ká̇l-ʻàbádá֔y⁠w lĕ⁠hámi֖yţ ʼeţ-dá̇wi֑d wi⁠yhֽwònáţán֙ bėn-şá̌ʼ֔ẇl ẖápé֥ẕ bĕ̇⁠dáwi֖d mĕʼòֽd׃"],[19,2,"וַ⁠יַּגֵּ֤ד יְהוֹנָתָן֙ לְ⁠דָוִ֣ד לֵ⁠אמֹ֔ר מְבַקֵּ֛שׁ שָׁא֥וּל אָבִ֖⁠י לַ⁠הֲמִיתֶ֑⁠ךָ וְ⁠עַתָּה֙ הִשָּֽׁמֶר־נָ֣א בַ⁠בֹּ֔קֶר וְ⁠יָשַׁבְתָּ֥ בַ⁠סֵּ֖תֶר וְ⁠נַחְבֵּֽאתָ׃","wa⁠yȧgé֤̇d yĕhwònáţán֙ lĕ⁠dáwi֣d lé⁠ʼmò֔r mĕbaqé֛̇ş̌ şá̌ʼ֥ẇl ʼábi֖⁠y la⁠hàmiyţe֑⁠ká wĕ⁠ʻaţá̇h֙ hişáֽ̇̌mer-ná֣ʼ ba⁠bò̇֔qer wĕ⁠yáşǎbĕţá֥̇ ba⁠sé֖̇ţer wĕ⁠naẖĕbéֽ̇ʼţá׃"],[19,3,"וַ⁠אֲנִ֨י אֵצֵ֜א וְ⁠עָמַדְתִּ֣י לְ⁠יַד־אָבִ֗⁠י בַּ⁠שָּׂדֶה֙ אֲשֶׁ֣ר אַתָּ֣ה שָׁ֔ם וַ⁠אֲנִ֕י אֲדַבֵּ֥ר בְּ⁠ךָ֖ אֶל־אָבִ֑⁠י וְ⁠רָאִ֥יתִי מָ֖ה וְ⁠הִגַּ֥דְתִּי לָֽ⁠ךְ׃ס","wa⁠ʼàni֨y ʼéẕé֜ʼ wĕ⁠ʻámadĕţi֣̇y lĕ⁠yad-ʼábi֗⁠y bȧ⁠şá̇̂deh֙ ʼàşě֣r ʼaţá֣̇h şá̌֔m wa⁠ʼàni֕y ʼàdabé֥̇r bĕ̇⁠ká֖ ʼel-ʼábi֑⁠y wĕ⁠ráʼi֥yţiy má֖h wĕ⁠higȧ֥dĕţi̇y láֽ⁠kĕ׃s"],[19,4,"וַ⁠יְדַבֵּ֨ר יְהוֹנָתָ֤ן בְּ⁠דָוִד֙ ט֔וֹב אֶל־שָׁא֖וּל אָבִ֑י⁠ו וַ⁠יֹּ֣אמֶר אֵ֠לָי⁠ו אַל־יֶחֱטָ֨א הַ⁠מֶּ֜לֶךְ בְּ⁠עַבְדּ֣⁠וֹ בְ⁠דָוִ֗ד כִּ֣י ל֤וֹא חָטָא֙ לָ֔⁠ךְ וְ⁠כִ֥י מַעֲשָׂ֖י⁠ו טוֹב־לְ⁠ךָ֥ מְאֹֽד׃","wa⁠yĕdabé̇֨r yĕhwònáţá֤n bĕ̇⁠dáwid֙ t֔wòb ʼel-şá̌ʼ֖ẇl ʼábi֑y⁠w wa⁠yò֣̇ʼmer ʼé֠láy⁠w ʼal-yeẖètá֨ʼ ha⁠mė֜lekĕ bĕ̇⁠ʻabĕḋ֣⁠wò bĕ⁠dáwi֗d ki֣̇y l֤wòʼ ẖátáʼ֙ lá֔⁠kĕ wĕ⁠ki֥y maʻàşá֖̂y⁠w twòb-lĕ⁠ká֥ mĕʼòֽd׃"],[19,5,"וַ⁠יָּשֶׂם֩ אֶת־נַפְשׁ֨⁠וֹ בְ⁠כַפּ֜⁠וֹ וַ⁠יַּ֣ךְ אֶת־הַ⁠פְּלִשְׁתִּ֗י וַ⁠יַּ֨עַשׂ יְהוָ֜ה תְּשׁוּעָ֤ה גְדוֹלָה֙ לְ⁠כָל־יִשְׂרָאֵ֔ל רָאִ֖יתָ וַ⁠תִּשְׂמָ֑ח וְ⁠לָ֤⁠מָּה תֶֽחֱטָא֙ בְּ⁠דָ֣ם נָקִ֔י לְ⁠הָמִ֥ית אֶת־דָּוִ֖ד חִנָּֽם׃","wa⁠yá̇şêm֩ ʼeţ-napĕş̌֨⁠wò bĕ⁠kaṗ֜⁠wò wa⁠yȧ֣kĕ ʼeţ-ha⁠pĕ̇lişĕ̌ţi̇֗y wa⁠yȧ֨ʻaş̂ yĕhwá֜h ţĕ̇ş̌ẇʻá֤h gĕdwòláh֙ lĕ⁠kál-yişĕ̂ráʼé֔l ráʼi֖yţá wa⁠ţi̇şĕ̂má֑ẖ wĕ⁠lá֤⁠má̇h ţeֽẖètáʼ֙ bĕ̇⁠dá֣m náqi֔y lĕ⁠hámi֥yţ ʼeţ-dá̇wi֖d ẖináֽ̇m׃"],[19,6,"וַ⁠יִּשְׁמַ֥ע שָׁא֖וּל בְּ⁠ק֣וֹל יְהוֹנָתָ֑ן וַ⁠יִּשָּׁבַ֣ע שָׁא֔וּל חַי־יְהוָ֖ה אִם־יוּמָֽת׃","wa⁠yi̇şĕ̌ma֥ʻ şá̌ʼ֖ẇl bĕ̇⁠q֣wòl yĕhwònáţá֑n wa⁠yi̇şá̇̌ba֣ʻ şá̌ʼ֔ẇl ẖay-yĕhwá֖h ʼim-yẇmáֽţ׃"],[19,7,"וַ⁠יִּקְרָ֤א יְהוֹנָתָן֙ לְ⁠דָוִ֔ד וַ⁠יַּגֶּד־ל⁠וֹ֙ יְה֣וֹנָתָ֔ן אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וַ⁠יָּבֵ֨א יְהוֹנָתָ֤ן אֶת־דָּוִד֙ אֶל־שָׁא֔וּל וַ⁠יְהִ֥י לְ⁠פָנָ֖י⁠ו כְּ⁠אֶתְמ֥וֹל שִׁלְשֽׁוֹם׃ס","wa⁠yi̇qĕrá֤ʼ yĕhwònáţán֙ lĕ⁠dáwi֔d wa⁠yȧgėd-l⁠wò֙ yĕh֣wònáţá֔n ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wa⁠yá̇bé֨ʼ yĕhwònáţá֤n ʼeţ-dá̇wid֙ ʼel-şá̌ʼ֔ẇl wa⁠yĕhi֥y lĕ⁠páná֖y⁠w kĕ̇⁠ʼeţĕm֥wòl şǐlĕşֽ̌wòm׃s"],[19,8,"וַ⁠תּ֥וֹסֶף הַ⁠מִּלְחָמָ֖ה לִֽ⁠הְי֑וֹת וַ⁠יֵּצֵ֨א דָוִ֜ד וַ⁠יִּלָּ֣חֶם בַּ⁠פְּלִשְׁתִּ֗ים וַ⁠יַּ֤ךְ בָּ⁠הֶם֙ מַכָּ֣ה גְדוֹלָ֔ה וַ⁠יָּנֻ֖סוּ מִ⁠פָּנָֽי⁠ו׃","wa⁠ţ֥̇wòsep ha⁠mi̇lĕẖámá֖h liֽ⁠hĕy֑wòţ wa⁠yé̇ẕé֨ʼ dáwi֜d wa⁠yi̇lá֣̇ẖem bȧ⁠pĕ̇lişĕ̌ţi̇֗ym wa⁠yȧ֤kĕ bá̇⁠hem֙ maká֣̇h gĕdwòlá֔h wa⁠yá̇nu֖sẇ mi⁠pá̇náֽy⁠w׃"],[19,9,"וַ⁠תְּהִי֩ ר֨וּחַ יְהוָ֤ה ׀ רָעָה֙ אֶל־שָׁא֔וּל וְ⁠הוּא֙ בְּ⁠בֵית֣⁠וֹ יוֹשֵׁ֔ב וַ⁠חֲנִית֖⁠וֹ בְּ⁠יָד֑⁠וֹ וְ⁠דָוִ֖ד מְנַגֵּ֥ן בְּ⁠יָֽד׃","wa⁠ţĕ̇hiy֩ r֨ẇẖa yĕhwá֤h ׀ ráʻáh֙ ʼel-şá̌ʼ֔ẇl wĕ⁠hẇʼ֙ bĕ̇⁠béyţ֣⁠wò ywòşé̌֔b wa⁠ẖàniyţ֖⁠wò bĕ̇⁠yád֑⁠wò wĕ⁠dáwi֖d mĕnagé֥̇n bĕ̇⁠yáֽd׃"],[19,10,"וַ⁠יְבַקֵּ֨שׁ שָׁא֜וּל לְ⁠הַכּ֤וֹת בַּֽ⁠חֲנִית֙ בְּ⁠דָוִ֣ד וּ⁠בַ⁠קִּ֔יר וַ⁠יִּפְטַר֙ מִ⁠פְּנֵ֣י שָׁא֔וּל וַ⁠יַּ֥ךְ אֶֽת־הַ⁠חֲנִ֖ית בַּ⁠קִּ֑יר וְ⁠דָוִ֛ד נָ֥ס וַ⁠יִּמָּלֵ֖ט בַּ⁠לַּ֥יְלָה הֽוּא׃פ","wa⁠yĕbaqé̇֨ş̌ şá̌ʼ֜ẇl lĕ⁠hak֤̇wòţ bȧֽ⁠ẖàniyţ֙ bĕ̇⁠dáwi֣d ẇ⁠ba⁠qi̇֔yr wa⁠yi̇pĕtar֙ mi⁠pĕ̇né֣y şá̌ʼ֔ẇl wa⁠yȧ֥kĕ ʼeֽţ-ha⁠ẖàni֖yţ bȧ⁠qi֑̇yr wĕ⁠dáwi֛d ná֥s wa⁠yi̇má̇lé֖t bȧ⁠lȧ֥yĕláh hֽẇʼ׃p"],[19,11,"וַ⁠יִּשְׁלַח֩ שָׁא֨וּל מַלְאָכִ֜ים אֶל־בֵּ֤ית דָּוִד֙ לְ⁠שָׁמְר֔⁠וֹ וְ⁠לַ⁠הֲמִית֖⁠וֹ בַּ⁠בֹּ֑קֶר וַ⁠תַּגֵּ֣ד לְ⁠דָוִ֗ד מִיכַ֤ל אִשְׁתּ⁠וֹ֙ לֵ⁠אמֹ֔ר אִם־אֵ֨ינְ⁠ךָ֜ מְמַלֵּ֤ט אֶֽת־נַפְשְׁ⁠ךָ֙ הַ⁠לַּ֔יְלָה מָחָ֖ר אַתָּ֥ה מוּמָֽת׃","wa⁠yi̇şĕ̌laẖ֩ şá̌ʼ֨ẇl malĕʼáki֜ym ʼel-bé֤̇yţ dá̇wid֙ lĕ⁠şá̌mĕr֔⁠wò wĕ⁠la⁠hàmiyţ֖⁠wò bȧ⁠bò֑̇qer wa⁠ţȧgé֣̇d lĕ⁠dáwi֗d miyka֤l ʼişĕ̌ţ̇⁠wò֙ lé⁠ʼmò֔r ʼim-ʼé֨ynĕ⁠ká֜ mĕmalé֤̇t ʼeֽţ-napĕşĕ̌⁠ká֙ ha⁠lȧ֔yĕláh máẖá֖r ʼaţá֥̇h mẇmáֽţ׃"],[19,12,"וַ⁠תֹּ֧רֶד מִיכַ֛ל אֶת־דָּוִ֖ד בְּעַ֣ד הַ⁠חַלּ֑וֹן וַ⁠יֵּ֥לֶךְ וַ⁠יִּבְרַ֖ח וַ⁠יִּמָּלֵֽט׃","wa⁠ţò֧̇red miyka֛l ʼeţ-dá̇wi֖d bĕ̇ʻa֣d ha⁠ẖal֑̇wòn wa⁠yé֥̇lekĕ wa⁠yi̇bĕra֖ẖ wa⁠yi̇má̇léֽt׃"],[19,13,"וַ⁠תִּקַּ֨ח מִיכַ֜ל אֶת־הַ⁠תְּרָפִ֗ים וַ⁠תָּ֨שֶׂם֙ אֶל־הַ⁠מִּטָּ֔ה וְ⁠אֵת֙ כְּבִ֣יר הָֽ⁠עִזִּ֔ים שָׂ֖מָה מְרַֽאֲשֹׁתָ֑י⁠ו וַ⁠תְּכַ֖ס בַּ⁠בָּֽגֶד׃ס","wa⁠ţi̇qȧ֨ẖ miyka֜l ʼeţ-ha⁠ţĕ̇rápi֗ym wa⁠ţá̇֨şêm֙ ʼel-ha⁠mi̇tá̇֔h wĕ⁠ʼéţ֙ kĕ̇bi֣yr háֽ⁠ʻizi̇֔ym şá֖̂máh mĕraֽʼàşò̌ţá֑y⁠w wa⁠ţĕ̇ka֖s bȧ⁠báֽ̇ged׃s"],[19,14,"וַ⁠יִּשְׁלַ֥ח שָׁא֛וּל מַלְאָכִ֖ים לָ⁠קַ֣חַת אֶת־דָּוִ֑ד וַ⁠תֹּ֖אמֶר חֹלֶ֥ה הֽוּא׃פ","wa⁠yi̇şĕ̌la֥ẖ şá̌ʼ֛ẇl malĕʼáki֖ym lá⁠qa֣ẖaţ ʼeţ-dá̇wi֑d wa⁠ţò֖̇ʼmer ẖòle֥h hֽẇʼ׃p"],[19,15,"וַ⁠יִּשְׁלַ֤ח שָׁאוּל֙ אֶת־הַ⁠מַּלְאָכִ֔ים לִ⁠רְא֥וֹת אֶת־דָּוִ֖ד לֵ⁠אמֹ֑ר הַעֲל֨וּ אֹת֧⁠וֹ בַ⁠מִּטָּ֛ה אֵלַ֖⁠י לַ⁠הֲמִתֽ⁠וֹ׃","wa⁠yi̇şĕ̌la֤ẖ şá̌ʼẇl֙ ʼeţ-ha⁠mȧlĕʼáki֔ym li⁠rĕʼ֥wòţ ʼeţ-dá̇wi֖d lé⁠ʼmò֑r haʻàl֨ẇ ʼòţ֧⁠wò ba⁠mi̇tá֛̇h ʼéla֖⁠y la⁠hàmiţֽ⁠wò׃"],[19,16,"וַ⁠יָּבֹ֨אוּ֙ הַ⁠מַּלְאָכִ֔ים וְ⁠הִנֵּ֥ה הַ⁠תְּרָפִ֖ים אֶל־הַ⁠מִּטָּ֑ה וּ⁠כְבִ֥יר הָ⁠עִזִּ֖ים מְרַאֲשֹׁתָֽי⁠ו׃","wa⁠yá̇bò֨ʼẇ֙ ha⁠mȧlĕʼáki֔ym wĕ⁠hiné֥̇h ha⁠ţĕ̇rápi֖ym ʼel-ha⁠mi̇tá֑̇h ẇ⁠kĕbi֥yr há⁠ʻizi֖̇ym mĕraʼàşò̌ţáֽy⁠w׃"],[19,17,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל אֶל־מִיכַ֗ל לָ֤⁠מָּה כָּ֨כָה֙ רִמִּיתִ֔⁠נִי וַ⁠תְּשַׁלְּחִ֥י אֶת־אֹיְבִ֖⁠י וַ⁠יִּמָּלֵ֑ט וַ⁠תֹּ֤אמֶר מִיכַל֙ אֶל־שָׁא֔וּל הוּא־אָמַ֥ר אֵלַ֛⁠י שַׁלְּחִ֖⁠נִי לָ⁠מָ֥ה אֲמִיתֵֽ⁠ךְ׃","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl ʼel-miyka֗l lá֤⁠má̇h ká̇֨káh֙ rimi̇yţi֔⁠niy wa⁠ţĕ̇şǎlĕ̇ẖi֥y ʼeţ-ʼòyĕbi֖⁠y wa⁠yi̇má̇lé֑t wa⁠ţò֤̇ʼmer miykal֙ ʼel-şá̌ʼ֔ẇl hẇʼ-ʼáma֥r ʼéla֛⁠y şǎlĕ̇ẖi֖⁠niy lá⁠má֥h ʼàmiyţéֽ⁠kĕ׃"],[19,18,"וְ⁠דָוִ֨ד בָּרַ֜ח וַ⁠יִּמָּלֵ֗ט וַ⁠יָּבֹ֤א אֶל־שְׁמוּאֵל֙ הָ⁠רָמָ֔תָ⁠ה וַ⁠יַּ֨גֶּד־ל֔⁠וֹ אֵ֛ת כָּל־אֲשֶׁ֥ר עָֽשָׂה־ל֖⁠וֹ שָׁא֑וּל וַ⁠יֵּ֤לֶךְ הוּא֙ וּ⁠שְׁמוּאֵ֔ל וַ⁠יֵּשְׁב֖וּ ב⁠נוית׃","wĕ⁠dáwi֨d bá̇ra֜ẖ wa⁠yi̇má̇lé֗t wa⁠yá̇bò֤ʼ ʼel-şĕ̌mẇʼél֙ há⁠rámá֔ţá⁠h wa⁠yȧ֨gėd-l֔⁠wò ʼé֛ţ ká̇l-ʼàşě֥r ʻáֽşá̂h-l֖⁠wò şá̌ʼ֑ẇl wa⁠yé֤̇lekĕ hẇʼ֙ ẇ⁠şĕ̌mẇʼé֔l wa⁠yé̇şĕ̌b֖ẇ b⁠nwyţ׃"],[19,19,"וַ⁠יֻּגַּ֥ד לְ⁠שָׁא֖וּל לֵ⁠אמֹ֑ר הִנֵּ֣ה דָוִ֔ד ב⁠נוית בָּ⁠רָמָֽה׃","wa⁠yu̇gȧ֥d lĕ⁠şá̌ʼ֖ẇl lé⁠ʼmò֑r hiné֣̇h dáwi֔d b⁠nwyţ bá̇⁠rámáֽh׃"],[19,20,"וַ⁠יִּשְׁלַ֨ח שָׁא֣וּל מַלְאָכִים֮ לָ⁠קַ֣חַת אֶת־דָּוִד֒ וַ⁠יַּ֗רְא אֶֽת־לַהֲקַ֤ת הַ⁠נְּבִיאִים֙ נִבְּאִ֔ים וּ⁠שְׁמוּאֵ֕ל עֹמֵ֥ד נִצָּ֖ב עֲלֵי⁠הֶ֑ם וַ⁠תְּהִ֞י עַֽל־מַלְאֲכֵ֤י שָׁאוּל֙ ר֣וּחַ אֱלֹהִ֔ים וַ⁠יִּֽתְנַבְּא֖וּ גַּם־הֵֽמָּה׃","wa⁠yi̇şĕ̌la֨ẖ şá̌ʼ֣ẇl malĕʼákiym֮ lá⁠qa֣ẖaţ ʼeţ-dá̇wid֒ wa⁠yȧ֗rĕʼ ʼeֽţ-lahàqa֤ţ ha⁠nĕ̇biyʼiym֙ nibĕ̇ʼi֔ym ẇ⁠şĕ̌mẇʼé֕l ʻòmé֥d niẕá֖̇b ʻàléy⁠he֑m wa⁠ţĕ̇hi֞y ʻaֽl-malĕʼàké֤y şá̌ʼẇl֙ r֣ẇẖa ʼèlòhi֔ym wa⁠yiֽ̇ţĕnabĕ̇ʼ֖ẇ gȧm-héֽmá̇h׃"],[19,21,"וַ⁠יַּגִּ֣דוּ לְ⁠שָׁא֗וּל וַ⁠יִּשְׁלַח֙ מַלְאָכִ֣ים אֲחֵרִ֔ים וַ⁠יִּֽתְנַבְּא֖וּ גַּם־הֵ֑מָּה וַ⁠יֹּ֣סֶף שָׁא֗וּל וַ⁠יִּשְׁלַח֙ מַלְאָכִ֣ים שְׁלִשִׁ֔ים וַ⁠יִּֽתְנַבְּא֖וּ גַּם־הֵֽמָּה׃","wa⁠yȧgi֣̇dẇ lĕ⁠şá̌ʼ֗ẇl wa⁠yi̇şĕ̌laẖ֙ malĕʼáki֣ym ʼàẖéri֔ym wa⁠yiֽ̇ţĕnabĕ̇ʼ֖ẇ gȧm-hé֑má̇h wa⁠yò֣̇sep şá̌ʼ֗ẇl wa⁠yi̇şĕ̌laẖ֙ malĕʼáki֣ym şĕ̌lişǐ֔ym wa⁠yiֽ̇ţĕnabĕ̇ʼ֖ẇ gȧm-héֽmá̇h׃"],[19,22,"וַ⁠יֵּ֨לֶךְ גַּם־ה֜וּא הָ⁠רָמָ֗תָ⁠ה וַ⁠יָּבֹא֙ עַד־בּ֤וֹר הַ⁠גָּדוֹל֙ אֲשֶׁ֣ר בַּ⁠שֶּׂ֔כוּ וַ⁠יִּשְׁאַ֣ל וַ⁠יֹּ֔אמֶר אֵיפֹ֥ה שְׁמוּאֵ֖ל וְ⁠דָוִ֑ד וַ⁠יֹּ֕אמֶר הִנֵּ֖ה ב⁠נוית בָּ⁠רָמָֽה׃","wa⁠yé̇֨lekĕ gȧm-h֜ẇʼ há⁠rámá֗ţá⁠h wa⁠yá̇bòʼ֙ ʻad-ḃ֤wòr ha⁠gá̇dwòl֙ ʼàşě֣r bȧ⁠şė̂֔kẇ wa⁠yi̇şĕ̌ʼa֣l wa⁠yò̇֔ʼmer ʼéypò֥h şĕ̌mẇʼé֖l wĕ⁠dáwi֑d wa⁠yò̇֕ʼmer hiné֖̇h b⁠nwyţ bá̇⁠rámáֽh׃"],[19,23,"וַ⁠יֵּ֣לֶךְ שָׁ֔ם אֶל־נוית בָּ⁠רָמָ֑ה וַ⁠תְּהִי֩ עָלָ֨י⁠ו גַּם־ה֜וּא ר֣וּחַ אֱלֹהִ֗ים וַ⁠יֵּ֤לֶךְ הָלוֹךְ֙ וַ⁠יִּתְנַבֵּ֔א עַד־בֹּא֖⁠וֹ ב⁠נוית בָּ⁠רָמָֽה׃","wa⁠yé֣̇lekĕ şá̌֔m ʼel-nwyţ bá̇⁠rámá֑h wa⁠ţĕ̇hiy֩ ʻálá֨y⁠w gȧm-h֜ẇʼ r֣ẇẖa ʼèlòhi֗ym wa⁠yé֤̇lekĕ hálwòkĕ֙ wa⁠yi̇ţĕnabé̇֔ʼ ʻad-bò̇ʼ֖⁠wò b⁠nwyţ bá̇⁠rámáֽh׃"],[19,24,"וַ⁠יִּפְשַׁ֨ט גַּם־ה֜וּא בְּגָדָ֗י⁠ו וַ⁠יִּתְנַבֵּ֤א גַם־הוּא֙ לִ⁠פְנֵ֣י שְׁמוּאֵ֔ל וַ⁠יִּפֹּ֣ל עָרֹ֔ם כָּל־הַ⁠יּ֥וֹם הַ⁠ה֖וּא וְ⁠כָל־הַ⁠לָּ֑יְלָה עַל־כֵּן֙ יֹֽאמְר֔וּ הֲ⁠גַ֥ם שָׁא֖וּל בַּ⁠נְּבִיאִֽם׃פ","wa⁠yi̇pĕşǎ֨t gȧm-h֜ẇʼ bĕ̇gádá֗y⁠w wa⁠yi̇ţĕnabé֤̇ʼ gam-hẇʼ֙ li⁠pĕné֣y şĕ̌mẇʼé֔l wa⁠yi̇pò֣̇l ʻárò֔m ká̇l-ha⁠ẏ֥wòm ha⁠h֖ẇʼ wĕ⁠kál-ha⁠lá֑̇yĕláh ʻal-ké̇n֙ yòֽʼmĕr֔ẇ hà⁠ga֥m şá̌ʼ֖ẇl bȧ⁠nĕ̇biyʼiֽm׃p"],[20,1,"וַ⁠יִּבְרַ֣ח דָּוִ֔ד מ⁠נוות בָּ⁠רָמָ֑ה וַ⁠יָּבֹ֞א וַ⁠יֹּ֣אמֶר ׀ לִ⁠פְנֵ֣י יְהוֹנָתָ֗ן מֶ֤ה עָשִׂ֨יתִי֙ מֶֽה־עֲוֺנִ֤⁠י וּ⁠מֶֽה־חַטָּאתִ⁠י֙ לִ⁠פְנֵ֣י אָבִ֔י⁠ךָ כִּ֥י מְבַקֵּ֖שׁ אֶת־נַפְשִֽׁ⁠י׃","wa⁠yi̇bĕra֣ẖ dá̇wi֔d m⁠nwwţ bá̇⁠rámá֑h wa⁠yá̇bò֞ʼ wa⁠yò֣̇ʼmer ׀ li⁠pĕné֣y yĕhwònáţá֗n me֤h ʻáşî֨yţiy֙ meֽh-ʻàwֺni֤⁠y ẇ⁠meֽh-ẖatá̇ʼţi⁠y֙ li⁠pĕné֣y ʼábi֔y⁠ká ki֥̇y mĕbaqé֖̇ş̌ ʼeţ-napĕşǐֽ⁠y׃"],[20,2,"וַ⁠יֹּ֨אמֶר ל֣⁠וֹ חָלִילָ⁠ה֮ לֹ֣א תָמוּת֒ הִנֵּ֡ה ל⁠ו־עשה אָבִ֜⁠י דָּבָ֣ר גָּד֗וֹל א֚וֹ דָּבָ֣ר קָטֹ֔ן וְ⁠לֹ֥א יִגְלֶ֖ה אֶת־אָזְנִ֑⁠י וּ⁠מַדּוּעַ֩ יַסְתִּ֨יר אָבִ֥⁠י מִמֶּ֛⁠נִּי אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה אֵ֥ין זֹֽאת׃","wa⁠yò̇֨ʼmer l֣⁠wò ẖáliylá⁠h֮ lò֣ʼ ţámẇţ֒ hiné̇֡h l⁠w-ʻşh ʼábi֜⁠y dá̇bá֣r gá̇d֗wòl ʼ֚wò dá̇bá֣r qátò֔n wĕ⁠lò֥ʼ yigĕle֖h ʼeţ-ʼázĕni֑⁠y ẇ⁠maḋẇʻa֩ yasĕţi̇֨yr ʼábi֥⁠y mimė֛⁠ni̇y ʼeţ-ha⁠dá̇bá֥r ha⁠zė֖h ʼé֥yn zòֽʼţ׃"],[20,3,"וַ⁠יִּשָּׁבַ֨ע ע֜וֹד דָּוִ֗ד וַ⁠יֹּ֨אמֶר֙ יָדֹ֨עַ יָדַ֜ע אָבִ֗י⁠ךָ כִּֽי־מָצָ֤אתִי חֵן֙ בְּ⁠עֵינֶ֔י⁠ךָ וַ⁠יֹּ֛אמֶר אַל־יֵֽדַע־זֹ֥את יְהוֹנָתָ֖ן פֶּן־יֵֽעָצֵ֑ב וְ⁠אוּלָ֗ם חַי־יְהוָה֙ וְ⁠חֵ֣י נַפְשֶׁ֔⁠ךָ כִּ֣י כְ⁠פֶ֔שַׂע בֵּינִ֖⁠י וּ⁠בֵ֥ין הַ⁠מָּֽוֶת׃","wa⁠yi̇şá̇̌ba֨ʻ ʻ֜wòd dá̇wi֗d wa⁠yò̇֨ʼmer֙ yádò֨ʻa yáda֜ʻ ʼábi֗y⁠ká kiֽ̇y-máẕá֤ʼţiy ẖén֙ bĕ̇⁠ʻéyne֔y⁠ká wa⁠yò֛̇ʼmer ʼal-yéֽdaʻ-zò֥ʼţ yĕhwònáţá֖n pėn-yéֽʻáẕé֑b wĕ⁠ʼẇlá֗m ẖay-yĕhwáh֙ wĕ⁠ẖé֣y napĕşě֔⁠ká ki֣̇y kĕ⁠pe֔şâʻ bé̇yni֖⁠y ẇ⁠bé֥yn ha⁠máֽ̇weţ׃"],[20,4,"וַ⁠יֹּ֥אמֶר יְהוֹנָתָ֖ן אֶל־דָּוִ֑ד מַה־תֹּאמַ֥ר נַפְשְׁ⁠ךָ֖ וְ⁠אֶֽעֱשֶׂה־לָּֽ⁠ךְ׃פ","wa⁠yò֥̇ʼmer yĕhwònáţá֖n ʼel-dá̇wi֑d mah-ţò̇ʼma֥r napĕşĕ̌⁠ká֖ wĕ⁠ʼeֽʻèşêh-láֽ̇⁠kĕ׃p"],[20,5,"וַ⁠יֹּ֨אמֶר דָּוִ֜ד אֶל־יְהוֹנָתָ֗ן הִֽנֵּה־חֹ֨דֶשׁ֙ מָחָ֔ר וְ⁠אָנֹכִ֛י יָשֹׁב־אֵשֵׁ֥ב עִם־הַ⁠מֶּ֖לֶךְ לֶ⁠אֱכ֑וֹל וְ⁠שִׁלַּחְתַּ֨⁠נִי֙ וְ⁠נִסְתַּרְתִּ֣י בַ⁠שָּׂדֶ֔ה עַ֖ד הָ⁠עֶ֥רֶב הַ⁠שְּׁלִשִֽׁית׃","wa⁠yò̇֨ʼmer dá̇wi֜d ʼel-yĕhwònáţá֗n hiֽné̇h-ẖò֨deş̌֙ máẖá֔r wĕ⁠ʼánòki֛y yáşò̌b-ʼéşé֥̌b ʻim-ha⁠mė֖lekĕ le⁠ʼèk֑wòl wĕ⁠şǐlȧẖĕţȧ֨⁠niy֙ wĕ⁠nisĕţȧrĕţi֣̇y ba⁠şá̇̂de֔h ʻa֖d há⁠ʻe֥reb ha⁠şĕ̇̌lişǐֽyţ׃"],[20,6,"אִם־פָּקֹ֥ד יִפְקְדֵ֖⁠נִי אָבִ֑י⁠ךָ וְ⁠אָמַרְתָּ֗ נִשְׁאֹל֩ נִשְׁאַ֨ל מִמֶּ֤⁠נִּי דָוִד֙ לָ⁠רוּץ֙ בֵּֽית־לֶ֣חֶם עִיר֔⁠וֹ כִּ֣י זֶ֧בַח הַ⁠יָּמִ֛ים שָׁ֖ם לְ⁠כָל־הַ⁠מִּשְׁפָּחָֽה׃","ʼim-pá̇qò֥d yipĕqĕdé֖⁠niy ʼábi֑y⁠ká wĕ⁠ʼámarĕţá̇֗ nişĕ̌ʼòl֩ nişĕ̌ʼa֨l mimė֤⁠ni̇y dáwid֙ lá⁠rẇẕ֙ béֽ̇yţ-le֣ẖem ʻiyr֔⁠wò ki֣̇y ze֧baẖ ha⁠yá̇mi֛ym şá֖̌m lĕ⁠kál-ha⁠mi̇şĕ̌pá̇ẖáֽh׃"],[20,7,"אִם־כֹּ֥ה יֹאמַ֛ר ט֖וֹב שָׁל֣וֹם לְ⁠עַבְדֶּ֑⁠ךָ וְ⁠אִם־חָרֹ֤ה יֶֽחֱרֶה֙ ל֔⁠וֹ דַּ֕ע כִּֽי־כָלְתָ֥ה הָ⁠רָעָ֖ה מֵ⁠עִמּֽ⁠וֹ׃","ʼim-kò֥̇h yòʼma֛r t֖wòb şá̌l֣wòm lĕ⁠ʻabĕdė֑⁠ká wĕ⁠ʼim-ẖárò֤h yeֽẖèreh֙ l֔⁠wò dȧ֕ʻ kiֽ̇y-kálĕţá֥h há⁠ráʻá֖h mé⁠ʻiṁֽ⁠wò׃"],[20,8,"וְ⁠עָשִׂ֤יתָ חֶ֨סֶד֙ עַל־עַבְדֶּ֔⁠ךָ כִּ֚י בִּ⁠בְרִ֣ית יְהוָ֔ה הֵבֵ֥אתָ אֶֽת־עַבְדְּ⁠ךָ֖ עִמָּ֑⁠ךְ וְ⁠אִם־יֶשׁ־בִּ֤⁠י עָוֺן֙ הֲמִיתֵ֣⁠נִי אַ֔תָּה וְ⁠עַד־אָבִ֖י⁠ךָ לָ⁠מָּה־זֶּ֥ה תְבִיאֵֽ⁠נִי׃פ","wĕ⁠ʻáşî֤yţá ẖe֨sed֙ ʻal-ʻabĕdė֔⁠ká ki֚̇y bi̇⁠bĕri֣yţ yĕhwá֔h hébé֥ʼţá ʼeֽţ-ʻabĕdĕ̇⁠ká֖ ʻimá֑̇⁠kĕ wĕ⁠ʼim-yeş̌-bi֤̇⁠y ʻáwֺn֙ hàmiyţé֣⁠niy ʼa֔ţá̇h wĕ⁠ʻad-ʼábi֖y⁠ká lá⁠má̇h-zė֥h ţĕbiyʼéֽ⁠niy׃p"],[20,9,"וַ⁠יֹּ֥אמֶר יְהוֹנָתָ֖ן חָלִ֣ילָ⁠ה לָּ֑⁠ךְ כִּ֣י ׀ אִם־יָדֹ֣עַ אֵדַ֗ע כִּֽי־כָלְתָ֨ה הָ⁠רָעָ֜ה מֵ⁠עִ֤ם אָבִ⁠י֙ לָ⁠ב֣וֹא עָלֶ֔י⁠ךָ וְ⁠לֹ֥א אֹתָ֖⁠הּ אַגִּ֥יד לָֽ⁠ךְ׃ס","wa⁠yò֥̇ʼmer yĕhwònáţá֖n ẖáli֣ylá⁠h lá֑̇⁠kĕ ki֣̇y ׀ ʼim-yádò֣ʻa ʼéda֗ʻ kiֽ̇y-kálĕţá֨h há⁠ráʻá֜h mé⁠ʻi֤m ʼábi⁠y֙ lá⁠b֣wòʼ ʻále֔y⁠ká wĕ⁠lò֥ʼ ʼòţá֖⁠ḣ ʼagi֥̇yd láֽ⁠kĕ׃s"],[20,10,"וַ⁠יֹּ֤אמֶר דָּוִד֙ אֶל־יְה֣וֹנָתָ֔ן מִ֖י יַגִּ֣יד לִ֑⁠י א֛וֹ מַה־יַּעַנְ⁠ךָ֥ אָבִ֖י⁠ךָ קָשָֽׁה׃ס","wa⁠yò֤̇ʼmer dá̇wid֙ ʼel-yĕh֣wònáţá֔n mi֖y yagi֣̇yd li֑⁠y ʼ֛wò mah-yȧʻanĕ⁠ká֥ ʼábi֖y⁠ká qáşáֽ̌h׃s"],[20,11,"וַ⁠יֹּ֤אמֶר יְהֽוֹנָתָן֙ אֶל־דָּוִ֔ד לְכָ֖⁠ה וְ⁠נֵצֵ֣א הַ⁠שָּׂדֶ֑ה וַ⁠יֵּצְא֥וּ שְׁנֵי⁠הֶ֖ם הַ⁠שָּׂדֶֽה׃ס","wa⁠yò֤̇ʼmer yĕhֽwònáţán֙ ʼel-dá̇wi֔d lĕká֖⁠h wĕ⁠néẕé֣ʼ ha⁠şá̇̂de֑h wa⁠yé̇ẕĕʼ֥ẇ şĕ̌néy⁠he֖m ha⁠şá̇̂deֽh׃s"],[20,12,"וַ⁠יֹּ֨אמֶר יְהוֹנָתָ֜ן אֶל־דָּוִ֗ד יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ כִּֽי־אֶחְקֹ֣ר אֶת־אָבִ֗⁠י כָּ⁠עֵ֤ת ׀ מָחָר֙ הַ⁠שְּׁלִשִׁ֔ית וְ⁠הִנֵּה־ט֖וֹב אֶל־דָּוִ֑ד וְ⁠לֹֽא־אָז֙ אֶשְׁלַ֣ח אֵלֶ֔י⁠ךָ וְ⁠גָלִ֖יתִי אֶת־אָזְנֶֽ⁠ךָ׃","wa⁠yò̇֨ʼmer yĕhwònáţá֜n ʼel-dá̇wi֗d yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ kiֽ̇y-ʼeẖĕqò֣r ʼeţ-ʼábi֗⁠y ká̇⁠ʻé֤ţ ׀ máẖár֙ ha⁠şĕ̇̌lişǐ֔yţ wĕ⁠hiné̇h-t֖wòb ʼel-dá̇wi֑d wĕ⁠lòֽʼ-ʼáz֙ ʼeşĕ̌la֣ẖ ʼéle֔y⁠ká wĕ⁠gáli֖yţiy ʼeţ-ʼázĕneֽ⁠ká׃"],[20,13,"כֹּֽה־יַעֲשֶׂה֩ יְהוָ֨ה לִֽ⁠יהוֹנָתָ֜ן וְ⁠כֹ֣ה יֹסִ֗יף כִּֽי־יֵיטִ֨ב אֶל־אָבִ֤⁠י אֶת־הָֽ⁠רָעָה֙ עָלֶ֔י⁠ךָ וְ⁠גָלִ֨יתִי֙ אֶת־אָזְנֶ֔⁠ךָ וְ⁠שִׁלַּחְתִּ֖י⁠ךָ וְ⁠הָלַכְתָּ֣ לְ⁠שָׁל֑וֹם וִ⁠יהִ֤י יְהוָה֙ עִמָּ֔⁠ךְ כַּ⁠אֲשֶׁ֥ר הָיָ֖ה עִם־אָבִֽ⁠י׃","kòֽ̇h-yaʻàşêh֩ yĕhwá֨h liֽ⁠yhwònáţá֜n wĕ⁠kò֣h yòsi֗yp kiֽ̇y-yéyti֨b ʼel-ʼábi֤⁠y ʼeţ-háֽ⁠ráʻáh֙ ʻále֔y⁠ká wĕ⁠gáli֨yţiy֙ ʼeţ-ʼázĕne֔⁠ká wĕ⁠şǐlȧẖĕţi֖̇y⁠ká wĕ⁠hálakĕţá֣̇ lĕ⁠şá̌l֑wòm wi⁠yhi֤y yĕhwáh֙ ʻimá̇֔⁠kĕ kȧ⁠ʼàşě֥r háyá֖h ʻim-ʼábiֽ⁠y׃"],[20,14,"וְ⁠לֹ֖א אִם־עוֹדֶ֣⁠נִּי חָ֑י וְ⁠לֹֽא־תַעֲשֶׂ֧ה עִמָּדִ֛⁠י חֶ֥סֶד יְהוָ֖ה וְ⁠לֹ֥א אָמֽוּת׃","wĕ⁠lò֖ʼ ʼim-ʻwòde֣⁠ni̇y ẖá֑y wĕ⁠lòֽʼ-ţaʻàşê֧h ʻimá̇di֛⁠y ẖe֥sed yĕhwá֖h wĕ⁠lò֥ʼ ʼámֽẇţ׃"],[20,15,"וְ⁠לֹֽא־תַכְרִ֧ת אֶֽת־חַסְדְּ⁠ךָ֛ מֵ⁠עִ֥ם בֵּיתִ֖⁠י עַד־עוֹלָ֑ם וְ⁠לֹ֗א בְּ⁠הַכְרִ֤ת יְהוָה֙ אֶת־אֹיְבֵ֣י דָוִ֔ד אִ֕ישׁ מֵ⁠עַ֖ל פְּנֵ֥י הָ⁠אֲדָמָֽה׃","wĕ⁠lòֽʼ-ţakĕri֧ţ ʼeֽţ-ẖasĕdĕ̇⁠ká֛ mé⁠ʻi֥m bé̇yţi֖⁠y ʻad-ʻwòlá֑m wĕ⁠lò֗ʼ bĕ̇⁠hakĕri֤ţ yĕhwáh֙ ʼeţ-ʼòyĕbé֣y dáwi֔d ʼi֕yş̌ mé⁠ʻa֖l pĕ̇né֥y há⁠ʼàdámáֽh׃"],[20,16,"וַ⁠יִּכְרֹ֥ת יְהוֹנָתָ֖ן עִם־בֵּ֣ית דָּוִ֑ד וּ⁠בִקֵּ֣שׁ יְהוָ֔ה מִ⁠יַּ֖ד אֹיְבֵ֥י דָוִֽד׃","wa⁠yi̇kĕrò֥ţ yĕhwònáţá֖n ʻim-bé֣̇yţ dá̇wi֑d ẇ⁠biqé֣̇ş̌ yĕhwá֔h mi⁠yȧ֖d ʼòyĕbé֥y dáwiֽd׃"],[20,17,"וַ⁠יּ֤וֹסֶף יְהֽוֹנָתָן֙ לְ⁠הַשְׁבִּ֣יעַ אֶת־דָּוִ֔ד בְּ⁠אַהֲבָת֖⁠וֹ אֹת֑⁠וֹ כִּֽי־אַהֲבַ֥ת נַפְשׁ֖⁠וֹ אֲהֵבֽ⁠וֹ׃ס","wa⁠ẏ֤wòsep yĕhֽwònáţán֙ lĕ⁠haşĕ̌bi֣̇yʻa ʼeţ-dá̇wi֔d bĕ̇⁠ʼahàbáţ֖⁠wò ʼòţ֑⁠wò kiֽ̇y-ʼahàba֥ţ napĕş֖̌⁠wò ʼàhébֽ⁠wò׃s"],[20,18,"וַ⁠יֹּֽאמֶר־ל֥⁠וֹ יְהוֹנָתָ֖ן מָחָ֣ר חֹ֑דֶשׁ וְ⁠נִפְקַ֕דְתָּ כִּ֥י יִפָּקֵ֖ד מוֹשָׁבֶֽ⁠ךָ׃","wa⁠yòֽ̇ʼmer-l֥⁠wò yĕhwònáţá֖n máẖá֣r ẖò֑deş̌ wĕ⁠nipĕqa֕dĕţá̇ ki֥̇y yipá̇qé֖d mwòşá̌beֽ⁠ká׃"],[20,19,"וְ⁠שִׁלַּשְׁתָּ֙ תֵּרֵ֣ד מְאֹ֔ד וּ⁠בָאתָ֙ אֶל־הַ⁠מָּק֔וֹם אֲשֶׁר־נִסְתַּ֥רְתָּ שָּׁ֖ם בְּ⁠י֣וֹם הַֽ⁠מַּעֲשֶׂ֑ה וְ⁠יָ֣שַׁבְתָּ֔ אֵ֖צֶל הָ⁠אֶ֥בֶן הָ⁠אָֽזֶל׃","wĕ⁠şǐlȧşĕ̌ţá̇֙ ţé̇ré֣d mĕʼò֔d ẇ⁠báʼţá֙ ʼel-ha⁠má̇q֔wòm ʼàşěr-nisĕţȧ֥rĕţá̇ şá֖̇̌m bĕ̇⁠y֣wòm haֽ⁠mȧʻàşê֑h wĕ⁠yá֣şǎbĕţá̇֔ ʼé֖ẕel há⁠ʼe֥ben há⁠ʼáֽzel׃"],[20,20,"וַ⁠אֲנִ֕י שְׁלֹ֥שֶׁת הַ⁠חִצִּ֖ים צִדָּ֣⁠ה אוֹרֶ֑ה לְ⁠שַֽׁלַּֽח־לִ֖⁠י לְ⁠מַטָּרָֽה׃","wa⁠ʼàni֕y şĕ̌lò֥şěţ ha⁠ẖiẕi֖̇ym ẕidá֣̇⁠h ʼwòre֑h lĕ⁠şǎֽlȧֽẖ-li֖⁠y lĕ⁠matá̇ráֽh׃"],[20,21,"וְ⁠הִנֵּה֙ אֶשְׁלַ֣ח אֶת־הַ⁠נַּ֔עַר לֵ֖ךְ מְצָ֣א אֶת־הַ⁠חִצִּ֑ים אִם־אָמֹר֩ אֹמַ֨ר לַ⁠נַּ֜עַר הִנֵּ֥ה הַ⁠חִצִּ֣ים ׀ מִמְּ⁠ךָ֣ וָ⁠הֵ֗נָּה קָחֶ֧⁠נּוּ ׀ וָ⁠בֹ֛אָ⁠ה כִּֽי־שָׁל֥וֹם לְ⁠ךָ֛ וְ⁠אֵ֥ין דָּבָ֖ר חַי־יְהוָֽה׃","wĕ⁠hiné̇h֙ ʼeşĕ̌la֣ẖ ʼeţ-ha⁠nȧ֔ʻar lé֖kĕ mĕẕá֣ʼ ʼeţ-ha⁠ẖiẕi֑̇ym ʼim-ʼámòr֩ ʼòma֨r la⁠nȧ֜ʻar hiné֥̇h ha⁠ẖiẕi֣̇ym ׀ mimĕ̇⁠ká֣ wá⁠hé֗ná̇h qáẖe֧⁠ṅẇ ׀ wá⁠bò֛ʼá⁠h kiֽ̇y-şá̌l֥wòm lĕ⁠ká֛ wĕ⁠ʼé֥yn dá̇bá֖r ẖay-yĕhwáֽh׃"],[20,22,"וְ⁠אִם־כֹּ֤ה אֹמַר֙ לָ⁠עֶ֔לֶם הִנֵּ֥ה הַ⁠חִצִּ֖ים מִמְּ⁠ךָ֣ וָ⁠הָ֑לְאָה לֵ֕ךְ כִּ֥י שִֽׁלַּחֲ⁠ךָ֖ יְהוָֽה׃","wĕ⁠ʼim-kò֤̇h ʼòmar֙ lá⁠ʻe֔lem hiné֥̇h ha⁠ẖiẕi֖̇ym mimĕ̇⁠ká֣ wá⁠há֑lĕʼáh lé֕kĕ ki֥̇y şǐֽlȧẖà⁠ká֖ yĕhwáֽh׃"],[20,23,"וְ⁠הַ֨⁠דָּבָ֔ר אֲשֶׁ֥ר דִּבַּ֖רְנוּ אֲנִ֣י וָ⁠אָ֑תָּה הִנֵּ֧ה יְהוָ֛ה בֵּינִ֥⁠י וּ⁠בֵינְ⁠ךָ֖ עַד־עוֹלָֽם׃ס","wĕ⁠ha֨⁠dá̇bá֔r ʼàşě֥r di̇bȧ֖rĕnẇ ʼàni֣y wá⁠ʼá֑ţá̇h hiné֧̇h yĕhwá֛h bé̇yni֥⁠y ẇ⁠béynĕ⁠ká֖ ʻad-ʻwòláֽm׃s"],[20,24,"וַ⁠יִּסָּתֵ֥ר דָּוִ֖ד בַּ⁠שָּׂדֶ֑ה וַ⁠יְהִ֣י הַ⁠חֹ֔דֶשׁ וַ⁠יֵּ֧שֶׁב הַ⁠מֶּ֛לֶךְ על־הַ⁠לֶּ֖חֶם לֶ⁠אֱכֽוֹל׃","wa⁠yi̇sá̇ţé֥r dá̇wi֖d bȧ⁠şá̇̂de֑h wa⁠yĕhi֣y ha⁠ẖò֔deş̌ wa⁠yé֧̇şěb ha⁠mė֛lekĕ ʻl-ha⁠lė֖ẖem le⁠ʼèkֽwòl׃"],[20,25,"וַ⁠יֵּ֣שֶׁב הַ֠⁠מֶּלֶךְ עַל־מ֨וֹשָׁב֜⁠וֹ כְּ⁠פַ֣עַם ׀ בְּ⁠פַ֗עַם אֶל־מוֹשַׁב֙ הַ⁠קִּ֔יר וַ⁠יָּ֨קָם֙ יְה֣וֹנָתָ֔ן וַ⁠יֵּ֥שֶׁב אַבְנֵ֖ר מִ⁠צַּ֣ד שָׁא֑וּל וַ⁠יִּפָּקֵ֖ד מְק֥וֹם דָּוִֽד׃","wa⁠yé֣̇şěb ha֠⁠mėlekĕ ʻal-m֨wòşá̌b֜⁠wò kĕ̇⁠pa֣ʻam ׀ bĕ̇⁠pa֗ʻam ʼel-mwòşǎb֙ ha⁠qi̇֔yr wa⁠yá̇֨qám֙ yĕh֣wònáţá֔n wa⁠yé֥̇şěb ʼabĕné֖r mi⁠ẕȧ֣d şá̌ʼ֑ẇl wa⁠yi̇pá̇qé֖d mĕq֥wòm dá̇wiֽd׃"],[20,26,"וְ⁠לֹֽא־דִבֶּ֥ר שָׁא֛וּל מְא֖וּמָה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא כִּ֤י אָמַר֙ מִקְרֶ֣ה ה֔וּא בִּלְתִּ֥י טָה֛וֹר ה֖וּא כִּֽי־לֹ֥א טָהֽוֹר׃ס","wĕ⁠lòֽʼ-dibė֥r şá̌ʼ֛ẇl mĕʼ֖ẇmáh bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ki֤̇y ʼámar֙ miqĕre֣h h֔ẇʼ bi̇lĕţi֥̇y táh֛wòr h֖ẇʼ kiֽ̇y-lò֥ʼ táhֽwòr׃s"],[20,27,"וַ⁠יְהִ֗י מִֽ⁠מָּחֳרַ֤ת הַ⁠חֹ֨דֶשׁ֙ הַ⁠שֵּׁנִ֔י וַ⁠יִּפָּקֵ֖ד מְק֣וֹם דָּוִ֑ד ס וַ⁠יֹּ֤אמֶר שָׁאוּל֙ אֶל־יְהוֹנָתָ֣ן בְּנ֔⁠וֹ מַדּ֜וּעַ לֹא־בָ֧א בֶן־יִשַׁ֛י גַּם־תְּמ֥וֹל גַּם־הַ⁠יּ֖וֹם אֶל־הַ⁠לָּֽחֶם׃","wa⁠yĕhi֗y miֽ⁠má̇ẖora֤ţ ha⁠ẖò֨deş̌֙ ha⁠şé̇̌ni֔y wa⁠yi̇pá̇qé֖d mĕq֣wòm dá̇wi֑d s wa⁠yò֤̇ʼmer şá̌ʼẇl֙ ʼel-yĕhwònáţá֣n bĕ̇n֔⁠wò maḋ֜ẇʻa lòʼ-bá֧ʼ ben-yişǎ֛y gȧm-ţĕ̇m֥wòl gȧm-ha⁠ẏ֖wòm ʼel-ha⁠láֽ̇ẖem׃"],[20,28,"וַ⁠יַּ֥עַן יְהוֹנָתָ֖ן אֶת־שָׁא֑וּל נִשְׁאֹ֨ל נִשְׁאַ֥ל דָּוִ֛ד מֵ⁠עִמָּדִ֖⁠י עַד־בֵּ֥ית לָֽחֶם׃","wa⁠yȧ֥ʻan yĕhwònáţá֖n ʼeţ-şá̌ʼ֑ẇl nişĕ̌ʼò֨l nişĕ̌ʼa֥l dá̇wi֛d mé⁠ʻimá̇di֖⁠y ʻad-bé֥̇yţ láֽẖem׃"],[20,29,"וַ⁠יֹּ֡אמֶר שַׁלְּחֵ֣⁠נִי נָ֡א כִּ֣י זֶבַח֩ מִשְׁפָּחָ֨ה לָ֜⁠נוּ בָּ⁠עִ֗יר וְ⁠ה֤וּא צִוָּֽה־לִ⁠י֙ אָחִ֔⁠י וְ⁠עַתָּ֗ה אִם־מָצָ֤אתִי חֵן֙ בְּ⁠עֵינֶ֔י⁠ךָ אִמָּ֥לְטָה נָּ֖א וְ⁠אֶרְאֶ֣ה אֶת־אֶחָ֑⁠י עַל־כֵּ֣ן לֹא־בָ֔א אֶל־שֻׁלְחַ֖ן הַ⁠מֶּֽלֶךְ׃ס","wa⁠yò̇֡ʼmer şǎlĕ̇ẖé֣⁠niy ná֡ʼ ki֣̇y zebaẖ֩ mişĕ̌pá̇ẖá֨h lá֜⁠nẇ bá̇⁠ʻi֗yr wĕ⁠h֤ẇʼ ẕiwáֽ̇h-li⁠y֙ ʼáẖi֔⁠y wĕ⁠ʻaţá̇֗h ʼim-máẕá֤ʼţiy ẖén֙ bĕ̇⁠ʻéyne֔y⁠ká ʼimá֥̇lĕtáh ná֖̇ʼ wĕ⁠ʼerĕʼe֣h ʼeţ-ʼeẖá֑⁠y ʻal-ké֣̇n lòʼ-bá֔ʼ ʼel-şǔlĕẖa֖n ha⁠mėֽlekĕ׃s"],[20,30,"וַ⁠יִּֽחַר־אַ֤ף שָׁאוּל֙ בִּ⁠יה֣וֹנָתָ֔ן וַ⁠יֹּ֣אמֶר ל֔⁠וֹ בֶּֽן־נַעֲוַ֖ת הַ⁠מַּרְדּ֑וּת הֲ⁠ל֣וֹא יָדַ֗עְתִּי כִּֽי־בֹחֵ֤ר אַתָּה֙ לְ⁠בֶן־יִשַׁ֔י לְ⁠בָ֨שְׁתְּ⁠ךָ֔ וּ⁠לְ⁠בֹ֖שֶׁת עֶרְוַ֥ת אִמֶּֽ⁠ךָ׃","wa⁠yiֽ̇ẖar-ʼa֤p şá̌ʼẇl֙ bi̇⁠yh֣wònáţá֔n wa⁠yò֣̇ʼmer l֔⁠wò bėֽn-naʻàwa֖ţ ha⁠mȧrĕḋ֑ẇţ hà⁠l֣wòʼ yáda֗ʻĕţi̇y kiֽ̇y-bòẖé֤r ʼaţá̇h֙ lĕ⁠ben-yişǎ֔y lĕ⁠bá֨şĕ̌ţĕ̇⁠ká֔ ẇ⁠lĕ⁠bò֖şěţ ʻerĕwa֥ţ ʼimėֽ⁠ká׃"],[20,31,"כִּ֣י כָל־הַ⁠יָּמִ֗ים אֲשֶׁ֤ר בֶּן־יִשַׁי֙ חַ֣י עַל־הָ⁠אֲדָמָ֔ה לֹ֥א תִכּ֖וֹן אַתָּ֣ה וּ⁠מַלְכוּתֶ֑⁠ךָ וְ⁠עַתָּ֗ה שְׁלַ֨ח וְ⁠קַ֤ח אֹת⁠וֹ֙ אֵלַ֔⁠י כִּ֥י בֶן־מָ֖וֶת הֽוּא׃ס","ki֣̇y kál-ha⁠yá̇mi֗ym ʼàşě֤r bėn-yişǎy֙ ẖa֣y ʻal-há⁠ʼàdámá֔h lò֥ʼ ţik֖̇wòn ʼaţá֣̇h ẇ⁠malĕkẇţe֑⁠ká wĕ⁠ʻaţá̇֗h şĕ̌la֨ẖ wĕ⁠qa֤ẖ ʼòţ⁠wò֙ ʼéla֔⁠y ki֥̇y ben-má֖weţ hֽẇʼ׃s"],[20,32,"וַ⁠יַּ֨עַן֙ יְה֣וֹנָתָ֔ן אֶת־שָׁא֖וּל אָבִ֑י⁠ו וַ⁠יֹּ֧אמֶר אֵלָ֛י⁠ו לָ֥⁠מָּה יוּמַ֖ת מֶ֥ה עָשָֽׂה׃","wa⁠yȧ֨ʻan֙ yĕh֣wònáţá֔n ʼeţ-şá̌ʼ֖ẇl ʼábi֑y⁠w wa⁠yò֧̇ʼmer ʼélá֛y⁠w lá֥⁠má̇h yẇma֖ţ me֥h ʻáşáֽ̂h׃"],[20,33,"וַ⁠יָּ֨טֶל שָׁא֧וּל אֶֽת־הַ⁠חֲנִ֛ית עָלָ֖י⁠ו לְ⁠הַכֹּת֑⁠וֹ וַ⁠יֵּ֨דַע֙ יְה֣וֹנָתָ֔ן כִּֽי־כָ֥לָה הִ֛יא מֵ⁠עִ֥ם אָבִ֖י⁠ו לְ⁠הָמִ֥ית אֶת־דָּוִֽד׃ס","wa⁠yá̇֨tel şá̌ʼ֧ẇl ʼeֽţ-ha⁠ẖàni֛yţ ʻálá֖y⁠w lĕ⁠hakò̇ţ֑⁠wò wa⁠yé̇֨daʻ֙ yĕh֣wònáţá֔n kiֽ̇y-ká֥láh hi֛yʼ mé⁠ʻi֥m ʼábi֖y⁠w lĕ⁠hámi֥yţ ʼeţ-dá̇wiֽd׃s"],[20,34,"וַ⁠יָּ֧קָם יְהוֹנָתָ֛ן מֵ⁠עִ֥ם הַ⁠שֻּׁלְחָ֖ן בָּ⁠חֳרִי־אָ֑ף וְ⁠לֹא־אָכַ֞ל בְּ⁠יוֹם־הַ⁠חֹ֤דֶשׁ הַ⁠שֵּׁנִי֙ לֶ֔חֶם כִּ֤י נֶעְצַב֙ אֶל־דָּוִ֔ד כִּ֥י הִכְלִמ֖⁠וֹ אָבִֽי⁠ו׃ס","wa⁠yá֧̇qám yĕhwònáţá֛n mé⁠ʻi֥m ha⁠şu̇̌lĕẖá֖n bá̇⁠ẖoriy-ʼá֑p wĕ⁠lòʼ-ʼáka֞l bĕ̇⁠ywòm-ha⁠ẖò֤deş̌ ha⁠şé̇̌niy֙ le֔ẖem ki֤̇y neʻĕẕab֙ ʼel-dá̇wi֔d ki֥̇y hikĕlim֖⁠wò ʼábiֽy⁠w׃s"],[20,35,"וַ⁠יְהִ֣י בַ⁠בֹּ֔קֶר וַ⁠יֵּצֵ֧א יְהוֹנָתָ֛ן הַ⁠שָּׂדֶ֖ה לְ⁠מוֹעֵ֣ד דָּוִ֑ד וְ⁠נַ֥עַר קָטֹ֖ן עִמּֽ⁠וֹ׃","wa⁠yĕhi֣y ba⁠bò̇֔qer wa⁠yé̇ẕé֧ʼ yĕhwònáţá֛n ha⁠şá̇̂de֖h lĕ⁠mwòʻé֣d dá̇wi֑d wĕ⁠na֥ʻar qátò֖n ʻiṁֽ⁠wò׃"],[20,36,"וַ⁠יֹּ֣אמֶר לְ⁠נַעֲר֔⁠וֹ רֻ֗ץ מְצָ֥א נָא֙ אֶת־הַ֣⁠חִצִּ֔ים אֲשֶׁ֥ר אָנֹכִ֖י מוֹרֶ֑ה הַ⁠נַּ֣עַר רָ֔ץ וְ⁠הֽוּא־יָרָ֥ה הַ⁠חֵ֖צִי לְ⁠הַעֲבִרֽ⁠וֹ׃","wa⁠yò֣̇ʼmer lĕ⁠naʻàr֔⁠wò ru֗ẕ mĕẕá֥ʼ náʼ֙ ʼeţ-ha֣⁠ẖiẕi̇֔ym ʼàşě֥r ʼánòki֖y mwòre֑h ha⁠nȧ֣ʻar rá֔ẕ wĕ⁠hֽẇʼ-yárá֥h ha⁠ẖé֖ẕiy lĕ⁠haʻàbirֽ⁠wò׃"],[20,37,"וַ⁠יָּבֹ֤א הַ⁠נַּ֨עַר֙ עַד־מְק֣וֹם הַ⁠חֵ֔צִי אֲשֶׁ֥ר יָרָ֖ה יְהוֹנָתָ֑ן וַ⁠יִּקְרָ֨א יְהוֹנָתָ֜ן אַחֲרֵ֤י הַ⁠נַּ֨עַר֙ וַ⁠יֹּ֔אמֶר הֲ⁠ל֥וֹא הַ⁠חֵ֖צִי מִמְּ⁠ךָ֥ וָ⁠הָֽלְאָה׃","wa⁠yá̇bò֤ʼ ha⁠nȧ֨ʻar֙ ʻad-mĕq֣wòm ha⁠ẖé֔ẕiy ʼàşě֥r yárá֖h yĕhwònáţá֑n wa⁠yi̇qĕrá֨ʼ yĕhwònáţá֜n ʼaẖàré֤y ha⁠nȧ֨ʻar֙ wa⁠yò̇֔ʼmer hà⁠l֥wòʼ ha⁠ẖé֖ẕiy mimĕ̇⁠ká֥ wá⁠háֽlĕʼáh׃"],[20,38,"וַ⁠יִּקְרָ֤א יְהֽוֹנָתָן֙ אַחֲרֵ֣י הַ⁠נַּ֔עַר מְהֵרָ֥ה ח֖וּשָׁ⁠ה אַֽל־תַּעֲמֹ֑ד וַ⁠יְלַקֵּ֞ט נַ֤עַר יְהֽוֹנָתָן֙ אֶת־החצי וַ⁠יָּבֹ֖א אֶל־אֲדֹנָֽי⁠ו׃","wa⁠yi̇qĕrá֤ʼ yĕhֽwònáţán֙ ʼaẖàré֣y ha⁠nȧ֔ʻar mĕhérá֥h ẖ֖ẇşá̌⁠h ʼaֽl-ţȧʻàmò֑d wa⁠yĕlaqé̇֞t na֤ʻar yĕhֽwònáţán֙ ʼeţ-hẖẕy wa⁠yá̇bò֖ʼ ʼel-ʼàdònáֽy⁠w׃"],[20,39,"וְ⁠הַ⁠נַּ֖עַר לֹֽא־יָדַ֣ע מְא֑וּמָה אַ֤ךְ יְהֽוֹנָתָן֙ וְ⁠דָוִ֔ד יָדְע֖וּ אֶת־הַ⁠דָּבָֽר׃","wĕ⁠ha⁠nȧ֖ʻar lòֽʼ-yáda֣ʻ mĕʼ֑ẇmáh ʼa֤kĕ yĕhֽwònáţán֙ wĕ⁠dáwi֔d yádĕʻ֖ẇ ʼeţ-ha⁠dá̇báֽr׃"],[20,40,"וַ⁠יִּתֵּ֤ן יְהֽוֹנָתָן֙ אֶת־כֵּלָ֔י⁠ו אֶל־הַ⁠נַּ֖עַר אֲשֶׁר־ל֑⁠וֹ וַ⁠יֹּ֣אמֶר ל֔⁠וֹ לֵ֖ךְ הָבֵ֥יא הָ⁠עִֽיר׃","wa⁠yi̇ţé֤̇n yĕhֽwònáţán֙ ʼeţ-ké̇lá֔y⁠w ʼel-ha⁠nȧ֖ʻar ʼàşěr-l֑⁠wò wa⁠yò֣̇ʼmer l֔⁠wò lé֖kĕ hábé֥yʼ há⁠ʻiֽyr׃"],[20,41,"הַ⁠נַּעַר֮ בָּא֒ וְ⁠דָוִ֗ד קָ֚ם מֵ⁠אֵ֣צֶל הַ⁠נֶּ֔גֶב וַ⁠יִּפֹּ֨ל לְ⁠אַפָּ֥י⁠ו אַ֛רְצָ⁠ה וַ⁠יִּשְׁתַּ֖חוּ שָׁלֹ֣שׁ פְּעָמִ֑ים וַֽ⁠יִּשְּׁק֣וּ ׀ אִ֣ישׁ אֶת־רֵעֵ֗⁠הוּ וַ⁠יִּבְכּוּ֙ אִ֣ישׁ אֶת־רֵעֵ֔⁠הוּ עַד־דָּוִ֖ד הִגְדִּֽיל׃","ha⁠nȧʻar֮ bá̇ʼ֒ wĕ⁠dáwi֗d qá֚m mé⁠ʼé֣ẕel ha⁠nė֔geb wa⁠yi̇pò̇֨l lĕ⁠ʼapá֥̇y⁠w ʼa֛rĕẕá⁠h wa⁠yi̇şĕ̌ţȧ֖ẖẇ şá̌lò֣ş̌ pĕ̇ʻámi֑ym waֽ⁠yi̇şĕ̇̌q֣ẇ ׀ ʼi֣yş̌ ʼeţ-réʻé֗⁠hẇ wa⁠yi̇bĕk̇ẇ֙ ʼi֣yş̌ ʼeţ-réʻé֔⁠hẇ ʻad-dá̇wi֖d higĕdiֽ̇yl׃"],[20,42,"וַ⁠יֹּ֧אמֶר יְהוֹנָתָ֛ן לְ⁠דָוִ֖ד לֵ֣ךְ לְ⁠שָׁל֑וֹם אֲשֶׁר֩ נִשְׁבַּ֨עְנוּ שְׁנֵ֜י⁠נוּ אֲנַ֗חְנוּ בְּ⁠שֵׁ֤ם יְהוָה֙ לֵ⁠אמֹ֔ר יְהוָ֞ה יִֽהְיֶ֣ה ׀ בֵּינִ֣⁠י וּ⁠בֵינֶ֗⁠ךָ וּ⁠בֵ֥ין זַרְעִ֛⁠י וּ⁠בֵ֥ין זַרְעֲ⁠ךָ֖ עַד־עוֹלָֽם׃פ וַ⁠יָּ֖קָם וַ⁠יֵּלַ֑ךְ וִ⁠יהוֹנָתָ֖ן בָּ֥א הָ⁠עִֽיר׃","wa⁠yò֧̇ʼmer yĕhwònáţá֛n lĕ⁠dáwi֖d lé֣kĕ lĕ⁠şá̌l֑wòm ʼàşěr֩ nişĕ̌bȧ֨ʻĕnẇ şĕ̌né֜y⁠nẇ ʼàna֗ẖĕnẇ bĕ̇⁠şé֤̌m yĕhwáh֙ lé⁠ʼmò֔r yĕhwá֞h yiֽhĕye֣h ׀ bé̇yni֣⁠y ẇ⁠béyne֗⁠ká ẇ⁠bé֥yn zarĕʻi֛⁠y ẇ⁠bé֥yn zarĕʻà⁠ká֖ ʻad-ʻwòláֽm׃p wa⁠yá֖̇qám wa⁠yé̇la֑kĕ wi⁠yhwònáţá֖n bá֥̇ʼ há⁠ʻiֽyr׃"],[21,1,"וַ⁠יָּבֹ֤א דָוִד֙ נֹ֔בֶ⁠ה אֶל־אֲחִימֶ֖לֶךְ הַ⁠כֹּהֵ֑ן וַ⁠יֶּחֱרַ֨ד אֲחִימֶ֜לֶךְ לִ⁠קְרַ֣את דָּוִ֗ד וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ מַדּ֤וּעַ אַתָּה֙ לְ⁠בַדֶּ֔⁠ךָ וְ⁠אִ֖ישׁ אֵ֥ין אִתָּֽ⁠ךְ׃","wa⁠yá̇bò֤ʼ dáwid֙ nò֔be⁠h ʼel-ʼàẖiyme֖lekĕ ha⁠kò̇hé֑n wa⁠yėẖèra֨d ʼàẖiyme֜lekĕ li⁠qĕra֣ʼţ dá̇wi֗d wa⁠yò֤̇ʼmer l⁠wò֙ maḋ֤ẇʻa ʼaţá̇h֙ lĕ⁠badė֔⁠ká wĕ⁠ʼi֖yş̌ ʼé֥yn ʼiţáֽ̇⁠kĕ׃"],[21,2,"וַ⁠יֹּ֨אמֶר דָּוִ֜ד לַ⁠אֲחִימֶ֣לֶךְ הַ⁠כֹּהֵ֗ן הַ⁠מֶּלֶךְ֮ צִוַּ֣⁠נִי דָבָר֒ וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י אִ֣ישׁ אַל־יֵ֧דַע מְא֛וּמָה אֶת־הַ⁠דָּבָ֛ר אֲשֶׁר־אָנֹכִ֥י שֹׁלֵֽחֲ⁠ךָ֖ וַ⁠אֲשֶׁ֣ר צִוִּיתִ֑⁠ךָ וְ⁠אֶת־הַ⁠נְּעָרִ֣ים יוֹדַ֔עְתִּי אֶל־מְק֥וֹם פְּלֹנִ֖י אַלְמוֹנִֽי׃","wa⁠yò̇֨ʼmer dá̇wi֜d la⁠ʼàẖiyme֣lekĕ ha⁠kò̇hé֗n ha⁠mėlekĕ֮ ẕiwȧ֣⁠niy dábár֒ wa⁠yò֣̇ʼmer ʼéla֗⁠y ʼi֣yş̌ ʼal-yé֧daʻ mĕʼ֛ẇmáh ʼeţ-ha⁠dá̇bá֛r ʼàşěr-ʼánòki֥y şò̌léֽẖà⁠ká֖ wa⁠ʼàşě֣r ẕiwi̇yţi֑⁠ká wĕ⁠ʼeţ-ha⁠nĕ̇ʻári֣ym ywòda֔ʻĕţi̇y ʼel-mĕq֥wòm pĕ̇lòni֖y ʼalĕmwòniֽy׃"],[21,3,"וְ⁠עַתָּ֗ה מַה־יֵּ֧שׁ תַּֽחַת־יָדְ⁠ךָ֛ חֲמִשָּׁה־לֶ֖חֶם תְּנָ֣⁠ה בְ⁠יָדִ֑⁠י א֖וֹ הַ⁠נִּמְצָֽא׃","wĕ⁠ʻaţá̇֗h mah-yé֧̇ş̌ ţȧֽẖaţ-yádĕ⁠ká֛ ẖàmişá̇̌h-le֖ẖem ţĕ̇ná֣⁠h bĕ⁠yádi֑⁠y ʼ֖wò ha⁠ni̇mĕẕáֽʼ׃"],[21,4,"וַ⁠יַּ֨עַן הַ⁠כֹּהֵ֤ן אֶת־דָּוִד֙ וַ⁠יֹּ֔אמֶר אֵֽין־לֶ֥חֶם חֹ֖ל אֶל־תַּ֣חַת יָדִ֑⁠י כִּֽי־אִם־לֶ֤חֶם קֹ֨דֶשׁ֙ יֵ֔שׁ אִם־נִשְׁמְר֥וּ הַ⁠נְּעָרִ֖ים אַ֥ךְ מֵ⁠אִשָּֽׁה׃פ","wa⁠yȧ֨ʻan ha⁠kò̇hé֤n ʼeţ-dá̇wid֙ wa⁠yò̇֔ʼmer ʼéֽyn-le֥ẖem ẖò֖l ʼel-ţȧ֣ẖaţ yádi֑⁠y kiֽ̇y-ʼim-le֤ẖem qò֨deş̌֙ yé֔ş̌ ʼim-nişĕ̌mĕr֥ẇ ha⁠nĕ̇ʻári֖ym ʼa֥kĕ mé⁠ʼişáֽ̇̌h׃p"],[21,5,"וַ⁠יַּעַן֩ דָּוִ֨ד אֶת־הַ⁠כֹּהֵ֜ן וַ⁠יֹּ֣אמֶר ל֗⁠וֹ כִּ֣י אִם־אִשָּׁ֤ה עֲצֻֽרָה־לָ֨⁠נוּ֙ כִּ⁠תְמ֣וֹל שִׁלְשֹׁ֔ם בְּ⁠צֵאתִ֕⁠י וַ⁠יִּהְי֥וּ כְלֵֽי־הַ⁠נְּעָרִ֖ים קֹ֑דֶשׁ וְ⁠הוּא֙ דֶּ֣רֶךְ חֹ֔ל וְ⁠אַ֕ף כִּ֥י הַ⁠יּ֖וֹם יִקְדַּ֥שׁ בַּ⁠כֶּֽלִי׃","wa⁠yȧʻan֩ dá̇wi֨d ʼeţ-ha⁠kò̇hé֜n wa⁠yò֣̇ʼmer l֗⁠wò ki֣̇y ʼim-ʼişá֤̇̌h ʻàẕuֽráh-lá֨⁠nẇ֙ ki̇⁠ţĕm֣wòl şǐlĕşò̌֔m bĕ̇⁠ẕéʼţi֕⁠y wa⁠yi̇hĕy֥ẇ kĕléֽy-ha⁠nĕ̇ʻári֖ym qò֑deş̌ wĕ⁠hẇʼ֙ dė֣rekĕ ẖò֔l wĕ⁠ʼa֕p ki֥̇y ha⁠ẏ֖wòm yiqĕdȧ֥ş̌ bȧ⁠kėֽliy׃"],[21,6,"וַ⁠יִּתֶּן־ל֥⁠וֹ הַ⁠כֹּהֵ֖ן קֹ֑דֶשׁ כִּי֩ לֹא־הָ֨יָה שָׁ֜ם לֶ֗חֶם כִּֽי־אִם־לֶ֤חֶם הַ⁠פָּנִים֙ הַ⁠מּֽוּסָרִים֙ מִ⁠לִּ⁠פְנֵ֣י יְהוָ֔ה לָ⁠שׂוּם֙ לֶ֣חֶם חֹ֔ם בְּ⁠י֖וֹם הִלָּקְחֽ⁠וֹ׃","wa⁠yi̇ţėn-l֥⁠wò ha⁠kò̇hé֖n qò֑deş̌ ki̇y֩ lòʼ-há֨yáh şá̌֜m le֗ẖem kiֽ̇y-ʼim-le֤ẖem ha⁠pá̇niym֙ ha⁠ṁֽẇsáriym֙ mi⁠li̇⁠pĕné֣y yĕhwá֔h lá⁠ş̂ẇm֙ le֣ẖem ẖò֔m bĕ̇⁠y֖wòm hilá̇qĕẖֽ⁠wò׃"],[21,7,"וְ⁠שָׁ֡ם אִישׁ֩ מֵ⁠עַבְדֵ֨י שָׁא֜וּל בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נֶעְצָר֙ לִ⁠פְנֵ֣י יְהוָ֔ה וּ⁠שְׁמ֖⁠וֹ דֹּאֵ֣ג הָ⁠אֲדֹמִ֑י אַבִּ֥יר הָ⁠רֹעִ֖ים אֲשֶׁ֥ר לְ⁠שָׁאֽוּל׃","wĕ⁠şá̌֡m ʼiyş̌֩ mé⁠ʻabĕdé֨y şá̌ʼ֜ẇl bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ neʻĕẕár֙ li⁠pĕné֣y yĕhwá֔h ẇ⁠şĕ̌m֖⁠wò dò̇ʼé֣g há⁠ʼàdòmi֑y ʼabi֥̇yr há⁠ròʻi֖ym ʼàşě֥r lĕ⁠şá̌ʼֽẇl׃"],[21,8,"וַ⁠יֹּ֤אמֶר דָּוִד֙ לַ⁠אֲחִימֶ֔לֶךְ וְ⁠אִ֛ין יֶשׁ־פֹּ֥ה תַֽחַת־יָדְ⁠ךָ֖ חֲנִ֣ית אוֹ־חָ֑רֶב כִּ֣י גַם־חַרְבִּ֤⁠י וְ⁠גַם־כֵּלַ⁠י֙ לֹֽא־לָקַ֣חְתִּי בְ⁠יָדִ֔⁠י כִּֽי־הָיָ֥ה דְבַר־הַ⁠מֶּ֖לֶךְ נָחֽוּץ׃ס","wa⁠yò֤̇ʼmer dá̇wid֙ la⁠ʼàẖiyme֔lekĕ wĕ⁠ʼi֛yn yeş̌-pò֥̇h ţaֽẖaţ-yádĕ⁠ká֖ ẖàni֣yţ ʼwò-ẖá֑reb ki֣̇y gam-ẖarĕbi֤̇⁠y wĕ⁠gam-ké̇la⁠y֙ lòֽʼ-láqa֣ẖĕţi̇y bĕ⁠yádi֔⁠y kiֽ̇y-háyá֥h dĕbar-ha⁠mė֖lekĕ náẖֽẇẕ׃s"],[21,9,"וַ⁠יֹּ֣אמֶר הַ⁠כֹּהֵ֗ן חֶרֶב֩ גָּלְיָ֨ת הַ⁠פְּלִשְׁתִּ֜י אֲשֶׁר־הִכִּ֣יתָ ׀ בְּ⁠עֵ֣מֶק הָאֵלָ֗ה הִנֵּה־הִ֞יא לוּטָ֣ה בַ⁠שִּׂמְלָה֮ אַחֲרֵ֣י הָ⁠אֵפוֹד֒ אִם־אֹתָ֤⁠הּ תִּֽקַּח־לְ⁠ךָ֙ קָ֔ח כִּ֣י אֵ֥ין אַחֶ֛רֶת זוּלָתָ֖⁠הּ בָּ⁠זֶ֑ה וַ⁠יֹּ֧אמֶר דָּוִ֛ד אֵ֥ין כָּמ֖וֹ⁠הָ תְּנֶ֥⁠נָּה לִּֽ⁠י׃","wa⁠yò֣̇ʼmer ha⁠kò̇hé֗n ẖereb֩ gá̇lĕyá֨ţ ha⁠pĕ̇lişĕ̌ţi̇֜y ʼàşěr-hiki֣̇yţá ׀ bĕ̇⁠ʻé֣meq háʼélá֗h hiné̇h-hi֞yʼ lẇtá֣h ba⁠şi̇̂mĕláh֮ ʼaẖàré֣y há⁠ʼépwòd֒ ʼim-ʼòţá֤⁠ḣ ţiֽ̇qȧẖ-lĕ⁠ká֙ qá֔ẖ ki֣̇y ʼé֥yn ʼaẖe֛reţ zẇláţá֖⁠ḣ bá̇⁠ze֑h wa⁠yò֧̇ʼmer dá̇wi֛d ʼé֥yn ká̇m֖wò⁠há ţĕ̇ne֥⁠ná̇h liֽ̇⁠y׃"],[21,10,"וַ⁠יָּ֣קָם דָּוִ֔ד וַ⁠יִּבְרַ֥ח בַּ⁠יּוֹם־הַ⁠ה֖וּא מִ⁠פְּנֵ֣י שָׁא֑וּל וַ⁠יָּבֹ֕א אֶל־אָכִ֖ישׁ מֶ֥לֶךְ גַּֽת׃","wa⁠yá֣̇qám dá̇wi֔d wa⁠yi̇bĕra֥ẖ bȧ⁠ẏwòm-ha⁠h֖ẇʼ mi⁠pĕ̇né֣y şá̌ʼ֑ẇl wa⁠yá̇bò֕ʼ ʼel-ʼáki֖yş̌ me֥lekĕ gȧֽţ׃"],[21,11,"וַ⁠יֹּ֨אמְר֜וּ עַבְדֵ֤י אָכִישׁ֙ אֵלָ֔י⁠ו הֲ⁠לוֹא־זֶ֥ה דָוִ֖ד מֶ֣לֶךְ הָ⁠אָ֑רֶץ הֲ⁠ל֣וֹא לָ⁠זֶ֗ה יַעֲנ֤וּ בַ⁠מְּחֹלוֹת֙ לֵ⁠אמֹ֔ר הִכָּ֤ה שָׁאוּל֙ ב⁠אלפ⁠ו וְ⁠דָוִ֖ד ברבבתו׃","wa⁠yò̇֨ʼmĕr֜ẇ ʻabĕdé֤y ʼákiyş̌֙ ʼélá֔y⁠w hà⁠lwòʼ-ze֥h dáwi֖d me֣lekĕ há⁠ʼá֑reẕ hà⁠l֣wòʼ lá⁠ze֗h yaʻàn֤ẇ ba⁠mĕ̇ẖòlwòţ֙ lé⁠ʼmò֔r hiká֤̇h şá̌ʼẇl֙ b⁠ʼlp⁠w wĕ⁠dáwi֖d brbbţw׃"],[21,12,"וַ⁠יָּ֧שֶׂם דָּוִ֛ד אֶת־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה בִּ⁠לְבָב֑⁠וֹ וַ⁠יִּרָ֣א מְאֹ֔ד מִ⁠פְּנֵ֖י אָכִ֥ישׁ מֶֽלֶךְ־גַּֽת׃","wa⁠yá֧̇şêm dá̇wi֛d ʼeţ-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh bi̇⁠lĕbáb֑⁠wò wa⁠yi̇rá֣ʼ mĕʼò֔d mi⁠pĕ̇né֖y ʼáki֥yş̌ meֽlekĕ-gȧֽţ׃"],[21,13,"וַ⁠יְשַׁנּ֤⁠וֹ אֶת־טַעְמ⁠וֹ֙ בְּ⁠עֵ֣ינֵי⁠הֶ֔ם וַ⁠יִּתְהֹלֵ֖ל בְּ⁠יָדָ֑⁠ם ו⁠יתו עַל־דַּלְת֣וֹת הַ⁠שַּׁ֔עַר וַ⁠יּ֥וֹרֶד רִיר֖⁠וֹ אֶל־זְקָנֽ⁠וֹ׃","wa⁠yĕşǎṅ֤⁠wò ʼeţ-taʻĕm⁠wò֙ bĕ̇⁠ʻé֣ynéy⁠he֔m wa⁠yi̇ţĕhòlé֖l bĕ̇⁠yádá֑⁠m w⁠yţw ʻal-dȧlĕţ֣wòţ ha⁠şȧ̌֔ʻar wa⁠ẏ֥wòred riyr֖⁠wò ʼel-zĕqánֽ⁠wò׃"],[21,14,"וַ⁠יֹּ֥אמֶר אָכִ֖ישׁ אֶל־עֲבָדָ֑י⁠ו הִנֵּ֤ה תִרְאוּ֙ אִ֣ישׁ מִשְׁתַּגֵּ֔עַ לָ֛⁠מָּה תָּבִ֥יאוּ אֹת֖⁠וֹ אֵלָֽ⁠י׃","wa⁠yò֥̇ʼmer ʼáki֖yş̌ ʼel-ʻàbádá֑y⁠w hiné֤̇h ţirĕʼẇ֙ ʼi֣yş̌ mişĕ̌ţȧgé̇֔ʻa lá֛⁠má̇h ţá̇bi֥yʼẇ ʼòţ֖⁠wò ʼéláֽ⁠y׃"],[21,15,"חֲסַ֤ר מְשֻׁגָּעִים֙ אָ֔נִי כִּי־הֲבֵאתֶ֣ם אֶת־זֶ֔ה לְ⁠הִשְׁתַּגֵּ֖עַ עָלָ֑⁠י הֲ⁠זֶ֖ה יָב֥וֹא אֶל־בֵּיתִֽ⁠י׃ס","ẖàsa֤r mĕşǔgá̇ʻiym֙ ʼá֔niy ki̇y-hàbéʼţe֣m ʼeţ-ze֔h lĕ⁠hişĕ̌ţȧgé֖̇ʻa ʻálá֑⁠y hà⁠ze֖h yáb֥wòʼ ʼel-bé̇yţiֽ⁠y׃s"],[22,1,"וַ⁠יֵּ֤לֶךְ דָּוִד֙ מִ⁠שָּׁ֔ם וַ⁠יִּמָּלֵ֖ט אֶל־מְעָרַ֣ת עֲדֻלָּ֑ם וַ⁠יִּשְׁמְע֤וּ אֶחָי⁠ו֙ וְ⁠כָל־בֵּ֣ית אָבִ֔י⁠ו וַ⁠יֵּרְד֥וּ אֵלָ֖י⁠ו שָֽׁמָּ⁠ה׃","wa⁠yé֤̇lekĕ dá̇wid֙ mi⁠şá̇̌֔m wa⁠yi̇má̇lé֖t ʼel-mĕʻára֣ţ ʻàdulá֑̇m wa⁠yi̇şĕ̌mĕʻ֤ẇ ʼeẖáy⁠w֙ wĕ⁠kál-bé֣̇yţ ʼábi֔y⁠w wa⁠yé̇rĕd֥ẇ ʼélá֖y⁠w şáֽ̌má̇⁠h׃"],[22,2,"וַ⁠יִּֽתְקַבְּצ֣וּ אֵ֠לָי⁠ו כָּל־אִ֨ישׁ מָצ֜וֹק וְ⁠כָל־אִ֨ישׁ אֲשֶׁר־ל֤⁠וֹ נֹשֶׁא֙ וְ⁠כָל־אִ֣ישׁ מַר־נֶ֔פֶשׁ וַ⁠יְהִ֥י עֲלֵי⁠הֶ֖ם לְ⁠שָׂ֑ר וַ⁠יִּהְי֣וּ עִמּ֔⁠וֹ כְּ⁠אַרְבַּ֥ע מֵא֖וֹת אִֽישׁ׃","wa⁠yiֽ̇ţĕqabĕ̇ẕ֣ẇ ʼé֠láy⁠w ká̇l-ʼi֨yş̌ máẕ֜wòq wĕ⁠kál-ʼi֨yş̌ ʼàşěr-l֤⁠wò nòşěʼ֙ wĕ⁠kál-ʼi֣yş̌ mar-ne֔peş̌ wa⁠yĕhi֥y ʻàléy⁠he֖m lĕ⁠şá֑̂r wa⁠yi̇hĕy֣ẇ ʻiṁ֔⁠wò kĕ̇⁠ʼarĕbȧ֥ʻ méʼ֖wòţ ʼiֽyş̌׃"],[22,3,"וַ⁠יֵּ֧לֶךְ דָּוִ֛ד מִ⁠שָּׁ֖ם מִצְפֵּ֣ה מוֹאָ֑ב וַ⁠יֹּ֣אמֶר ׀ אֶל־מֶ֣לֶךְ מוֹאָ֗ב יֵֽצֵא־נָ֞א אָבִ֤⁠י וְ⁠אִמִּ⁠י֙ אִתְּ⁠כֶ֔ם עַ֚ד אֲשֶׁ֣ר אֵדַ֔ע מַה־יַּֽעֲשֶׂה־לִּ֖⁠י אֱלֹהִֽים׃","wa⁠yé֧̇lekĕ dá̇wi֛d mi⁠şá֖̇̌m miẕĕpé֣̇h mwòʼá֑b wa⁠yò֣̇ʼmer ׀ ʼel-me֣lekĕ mwòʼá֗b yéֽẕéʼ-ná֞ʼ ʼábi֤⁠y wĕ⁠ʼimi̇⁠y֙ ʼiţĕ̇⁠ke֔m ʻa֚d ʼàşě֣r ʼéda֔ʻ mah-yȧֽʻàşêh-li֖̇⁠y ʼèlòhiֽym׃"],[22,4,"וַ⁠יַּנְחֵ֕⁠ם אֶת־פְּנֵ֖י מֶ֣לֶךְ מוֹאָ֑ב וַ⁠יֵּשְׁב֣וּ עִמּ֔⁠וֹ כָּל־יְמֵ֥י הֱיוֹת־דָּוִ֖ד בַּ⁠מְּצוּדָֽה׃ס","wa⁠yȧnĕẖé֕⁠m ʼeţ-pĕ̇né֖y me֣lekĕ mwòʼá֑b wa⁠yé̇şĕ̌b֣ẇ ʻiṁ֔⁠wò ká̇l-yĕmé֥y hèywòţ-dá̇wi֖d bȧ⁠mĕ̇ẕẇdáֽh׃s"],[22,5,"וַ⁠יֹּאמֶר֩ גָּ֨ד הַ⁠נָּבִ֜יא אֶל־דָּוִ֗ד לֹ֤א תֵשֵׁב֙ בַּ⁠מְּצוּדָ֔ה לֵ֥ךְ וּ⁠בָֽאתָ־לְּ⁠ךָ֖ אֶ֣רֶץ יְהוּדָ֑ה וַ⁠יֵּ֣לֶךְ דָּוִ֔ד וַ⁠יָּבֹ֖א יַ֥עַר חָֽרֶת׃ס","wa⁠yò̇ʼmer֩ gá̇֨d ha⁠ná̇bi֜yʼ ʼel-dá̇wi֗d lò֤ʼ ţéşé̌b֙ bȧ⁠mĕ̇ẕẇdá֔h lé֥kĕ ẇ⁠báֽʼţá-lĕ̇⁠ká֖ ʼe֣reẕ yĕhẇdá֑h wa⁠yé֣̇lekĕ dá̇wi֔d wa⁠yá̇bò֖ʼ ya֥ʻar ẖáֽreţ׃s"],[22,6,"וַ⁠יִּשְׁמַ֣ע שָׁא֔וּל כִּ֚י נוֹדַ֣ע דָּוִ֔ד וַ⁠אֲנָשִׁ֖ים אֲשֶׁ֣ר אִתּ֑⁠וֹ וְ⁠שָׁאוּל֩ יוֹשֵׁ֨ב בַּ⁠גִּבְעָ֜ה תַּֽחַת־הָ⁠אֶ֤שֶׁל בָּֽ⁠רָמָה֙ וַ⁠חֲנִית֣⁠וֹ בְ⁠יָד֔⁠וֹ וְ⁠כָל־עֲבָדָ֖י⁠ו נִצָּבִ֥ים עָלָֽי⁠ו׃","wa⁠yi̇şĕ̌ma֣ʻ şá̌ʼ֔ẇl ki֚̇y nwòda֣ʻ dá̇wi֔d wa⁠ʼànáşǐ֖ym ʼàşě֣r ʼiţ֑̇⁠wò wĕ⁠şá̌ʼẇl֩ ywòşé̌֨b bȧ⁠gi̇bĕʻá֜h ţȧֽẖaţ-há⁠ʼe֤şěl báֽ̇⁠rámáh֙ wa⁠ẖàniyţ֣⁠wò bĕ⁠yád֔⁠wò wĕ⁠kál-ʻàbádá֖y⁠w niẕá̇bi֥ym ʻáláֽy⁠w׃"],[22,7,"וַ⁠יֹּ֣אמֶר שָׁא֗וּל לַֽ⁠עֲבָדָי⁠ו֙ הַ⁠נִּצָּבִ֣ים עָלָ֔י⁠ו שִׁמְעוּ־נָ֖א בְּנֵ֣י יְמִינִ֑י גַּם־לְ⁠כֻלְּ⁠כֶ֗ם יִתֵּ֤ן בֶּן־יִשַׁי֙ שָׂד֣וֹת וּ⁠כְרָמִ֔ים לְ⁠כֻלְּ⁠כֶ֣ם יָשִׂ֔ים שָׂרֵ֥י אֲלָפִ֖ים וְ⁠שָׂרֵ֥י מֵאֽוֹת׃","wa⁠yò֣̇ʼmer şá̌ʼ֗ẇl laֽ⁠ʻàbádáy⁠w֙ ha⁠ni̇ẕá̇bi֣ym ʻálá֔y⁠w şǐmĕʻẇ-ná֖ʼ bĕ̇né֣y yĕmiyni֑y gȧm-lĕ⁠kulĕ̇⁠ke֗m yiţé֤̇n bėn-yişǎy֙ şá̂d֣wòţ ẇ⁠kĕrámi֔ym lĕ⁠kulĕ̇⁠ke֣m yáşî֔ym şá̂ré֥y ʼàlápi֖ym wĕ⁠şá̂ré֥y méʼֽwòţ׃"],[22,8,"כִּי֩ קְשַׁרְתֶּ֨ם כֻּלְּ⁠כֶ֜ם עָלַ֗⁠י וְ⁠אֵין־גֹּלֶ֤ה אֶת־אָזְנִ⁠י֙ בִּ⁠כְרָת־בְּנִ֣⁠י עִם־בֶּן־יִשַׁ֔י וְ⁠אֵין־חֹלֶ֥ה מִ⁠כֶּ֛ם עָלַ֖⁠י וְ⁠גֹלֶ֣ה אֶת־אָזְנִ֑⁠י כִּ֣י הֵקִים֩ בְּנִ֨⁠י אֶת־עַבְדִּ֥⁠י עָלַ֛⁠י לְ⁠אֹרֵ֖ב כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","ki̇y֩ qĕşǎrĕţė֨m ku̇lĕ̇⁠ke֜m ʻála֗⁠y wĕ⁠ʼéyn-gò̇le֤h ʼeţ-ʼázĕni⁠y֙ bi̇⁠kĕráţ-bĕ̇ni֣⁠y ʻim-bėn-yişǎ֔y wĕ⁠ʼéyn-ẖòle֥h mi⁠kė֛m ʻála֖⁠y wĕ⁠gòle֣h ʼeţ-ʼázĕni֑⁠y ki֣̇y héqiym֩ bĕ̇ni֨⁠y ʼeţ-ʻabĕdi֥̇⁠y ʻála֛⁠y lĕ⁠ʼòré֖b kȧ⁠ẏ֥wòm ha⁠zėֽh׃s"],[22,9,"וַ⁠יַּ֜עַן דֹּאֵ֣ג הָ⁠אֲדֹמִ֗י וְ⁠ה֛וּא נִצָּ֥ב עַל־עַבְדֵֽי־שָׁא֖וּל וַ⁠יֹּאמַ֑ר רָאִ֨יתִי֙ אֶת־בֶּן־יִשַׁ֔י בָּ֣א נֹ֔בֶ⁠ה אֶל־אֲחִימֶ֖לֶךְ בֶּן־אֲחִטֽוּב׃","wa⁠yȧ֜ʻan dò̇ʼé֣g há⁠ʼàdòmi֗y wĕ⁠h֛ẇʼ niẕá֥̇b ʻal-ʻabĕdéֽy-şá̌ʼ֖ẇl wa⁠yò̇ʼma֑r ráʼi֨yţiy֙ ʼeţ-bėn-yişǎ֔y bá֣̇ʼ nò֔be⁠h ʼel-ʼàẖiyme֖lekĕ bėn-ʼàẖitֽẇb׃"],[22,10,"וַ⁠יִּשְׁאַל־ל⁠וֹ֙ בַּֽ⁠יהוָ֔ה וְ⁠צֵידָ֖ה נָ֣תַן ל֑⁠וֹ וְ⁠אֵ֗ת חֶ֛רֶב גָּלְיָ֥ת הַ⁠פְּלִשְׁתִּ֖י נָ֥תַן לֽ⁠וֹ׃","wa⁠yi̇şĕ̌ʼal-l⁠wò֙ bȧֽ⁠yhwá֔h wĕ⁠ẕéydá֖h ná֣ţan l֑⁠wò wĕ⁠ʼé֗ţ ẖe֛reb gá̇lĕyá֥ţ ha⁠pĕ̇lişĕ̌ţi֖̇y ná֥ţan lֽ⁠wò׃"],[22,11,"וַ⁠יִּשְׁלַ֣ח הַ⁠מֶּ֡לֶךְ לִ⁠קְרֹא֩ אֶת־אֲחִימֶ֨לֶךְ בֶּן־אֲחִיט֜וּב הַ⁠כֹּהֵ֗ן וְ⁠אֵ֨ת כָּל־בֵּ֥ית אָבִ֛י⁠ו הַ⁠כֹּהֲנִ֖ים אֲשֶׁ֣ר בְּ⁠נֹ֑ב וַ⁠יָּבֹ֥אוּ כֻלָּ֖⁠ם אֶל־הַ⁠מֶּֽלֶךְ׃ס","wa⁠yi̇şĕ̌la֣ẖ ha⁠mė֡lekĕ li⁠qĕròʼ֩ ʼeţ-ʼàẖiyme֨lekĕ bėn-ʼàẖiyt֜ẇb ha⁠kò̇hé֗n wĕ⁠ʼé֨ţ ká̇l-bé֥̇yţ ʼábi֛y⁠w ha⁠kò̇hàni֖ym ʼàşě֣r bĕ̇⁠nò֑b wa⁠yá̇bò֥ʼẇ kulá֖̇⁠m ʼel-ha⁠mėֽlekĕ׃s"],[22,12,"וַ⁠יֹּ֣אמֶר שָׁא֔וּל שְֽׁמַֽע־נָ֖א בֶּן־אֲחִיט֑וּב וַ⁠יֹּ֖אמֶר הִנְ⁠נִ֥י אֲדֹנִֽ⁠י׃","wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl şĕֽ̌maֽʻ-ná֖ʼ bėn-ʼàẖiyt֑ẇb wa⁠yò֖̇ʼmer hinĕ⁠ni֥y ʼàdòniֽ⁠y׃"],[22,13,"וַ⁠יֹּ֤אמֶר אל⁠ו שָׁא֔וּל לָ֚⁠מָּה קְשַׁרְתֶּ֣ם עָלַ֔⁠י אַתָּ֖ה וּ⁠בֶן־יִשָׁ֑י בְּ⁠תִתְּ⁠ךָ֨ ל֜⁠וֹ לֶ֣חֶם וְ⁠חֶ֗רֶב וְ⁠שָׁא֥וֹל ל⁠וֹ֙ בֵּֽ⁠אלֹהִ֔ים לָ⁠ק֥וּם אֵלַ֛⁠י לְ⁠אֹרֵ֖ב כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","wa⁠yò֤̇ʼmer ʼl⁠w şá̌ʼ֔ẇl lá֚⁠má̇h qĕşǎrĕţė֣m ʻála֔⁠y ʼaţá֖̇h ẇ⁠ben-yişá֑̌y bĕ̇⁠ţiţĕ̇⁠ká֨ l֜⁠wò le֣ẖem wĕ⁠ẖe֗reb wĕ⁠şá̌ʼ֥wòl l⁠wò֙ béֽ̇⁠ʼlòhi֔ym lá⁠q֥ẇm ʼéla֛⁠y lĕ⁠ʼòré֖b kȧ⁠ẏ֥wòm ha⁠zėֽh׃s"],[22,14,"וַ⁠יַּ֧עַן אֲחִימֶ֛לֶךְ אֶת־הַ⁠מֶּ֖לֶךְ וַ⁠יֹּאמַ֑ר וּ⁠מִ֤י בְ⁠כָל־עֲבָדֶ֨י⁠ךָ֙ כְּ⁠דָוִ֣ד נֶאֱמָ֔ן וַ⁠חֲתַ֥ן הַ⁠מֶּ֛לֶךְ וְ⁠סָ֥ר אֶל־מִשְׁמַעְתֶּ֖⁠ךָ וְ⁠נִכְבָּ֥ד בְּ⁠בֵיתֶֽ⁠ךָ׃","wa⁠yȧ֧ʻan ʼàẖiyme֛lekĕ ʼeţ-ha⁠mė֖lekĕ wa⁠yò̇ʼma֑r ẇ⁠mi֤y bĕ⁠kál-ʻàbáde֨y⁠ká֙ kĕ̇⁠dáwi֣d neʼèmá֔n wa⁠ẖàţa֥n ha⁠mė֛lekĕ wĕ⁠sá֥r ʼel-mişĕ̌maʻĕţė֖⁠ká wĕ⁠nikĕbá֥̇d bĕ̇⁠béyţeֽ⁠ká׃"],[22,15,"הַ⁠יּ֧וֹם הַחִלֹּ֛תִי ל⁠שאול־ל֥⁠וֹ בֵ⁠אלֹהִ֖ים חָלִ֣ילָ⁠ה לִּ֑⁠י אַל־יָשֵׂם֩ הַ⁠מֶּ֨לֶךְ בְּ⁠עַבְדּ֤⁠וֹ דָבָר֙ בְּ⁠כָל־בֵּ֣ית אָבִ֔⁠י כִּ֠י לֹֽא־יָדַ֤ע עַבְדְּ⁠ךָ֙ בְּ⁠כָל־זֹ֔את דָּבָ֥ר קָטֹ֖ן א֥וֹ גָדֽוֹל׃","ha⁠ẏ֧wòm haẖilò֛̇ţiy l⁠şʼwl-l֥⁠wò bé⁠ʼlòhi֖ym ẖáli֣ylá⁠h li֑̇⁠y ʼal-yáşé̂m֩ ha⁠mė֨lekĕ bĕ̇⁠ʻabĕḋ֤⁠wò dábár֙ bĕ̇⁠kál-bé֣̇yţ ʼábi֔⁠y ki̇֠y lòֽʼ-yáda֤ʻ ʻabĕdĕ̇⁠ká֙ bĕ̇⁠kál-zò֔ʼţ dá̇bá֥r qátò֖n ʼ֥wò gádֽwòl׃"],[22,16,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ מ֥וֹת תָּמ֖וּת אֲחִימֶ֑לֶךְ אַתָּ֖ה וְ⁠כָל־בֵּ֥ית אָבִֽי⁠ךָ׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ m֥wòţ ţá̇m֖ẇţ ʼàẖiyme֑lekĕ ʼaţá֖̇h wĕ⁠kál-bé֥̇yţ ʼábiֽy⁠ká׃"],[22,17,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֡לֶךְ לָ⁠רָצִים֩ הַ⁠נִּצָּבִ֨ים עָלָ֜י⁠ו סֹ֥בּוּ וְ⁠הָמִ֣יתוּ ׀ כֹּהֲנֵ֣י יְהוָ֗ה כִּ֤י גַם־יָדָ⁠ם֙ עִם־דָּוִ֔ד וְ⁠כִ֤י יָֽדְעוּ֙ כִּֽי־בֹרֵ֣חַ ה֔וּא וְ⁠לֹ֥א גָל֖וּ אֶת־אזנ⁠ו וְ⁠לֹֽא־אָב֞וּ עַבְדֵ֤י הַ⁠מֶּ֨לֶךְ֙ לִ⁠שְׁלֹ֣חַ אֶת־יָדָ֔⁠ם לִ⁠פְגֹ֖עַ בְּ⁠כֹהֲנֵ֥י יְהוָֽה׃ס","wa⁠yò֣̇ʼmer ha⁠mė֡lekĕ lá⁠ráẕiym֩ ha⁠ni̇ẕá̇bi֨ym ʻálá֜y⁠w sò֥ḃẇ wĕ⁠hámi֣yţẇ ׀ kò̇hàné֣y yĕhwá֗h ki֤̇y gam-yádá⁠m֙ ʻim-dá̇wi֔d wĕ⁠ki֤y yáֽdĕʻẇ֙ kiֽ̇y-bòré֣ẖa h֔ẇʼ wĕ⁠lò֥ʼ gál֖ẇ ʼeţ-ʼzn⁠w wĕ⁠lòֽʼ-ʼáb֞ẇ ʻabĕdé֤y ha⁠mė֨lekĕ֙ li⁠şĕ̌lò֣ẖa ʼeţ-yádá֔⁠m li⁠pĕgò֖ʻa bĕ̇⁠kòhàné֥y yĕhwáֽh׃s"],[22,18,"וַ⁠יֹּ֤אמֶר הַ⁠מֶּ֨לֶךְ֙ ל⁠דויג סֹ֣ב אַתָּ֔ה וּ⁠פְגַ֖ע בַּ⁠כֹּהֲנִ֑ים וַ⁠יִּסֹּ֞ב דויג הָ⁠אֲדֹמִ֗י וַ⁠יִּפְגַּע־הוּא֙ בַּ⁠כֹּ֣הֲנִ֔ים וַ⁠יָּ֣מֶת ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא שְׁמֹנִ֤ים וַ⁠חֲמִשָּׁה֙ אִ֔ישׁ נֹשֵׂ֖א אֵפ֥וֹד בָּֽד׃","wa⁠yò֤̇ʼmer ha⁠mė֨lekĕ֙ l⁠dwyg sò֣b ʼaţá̇֔h ẇ⁠pĕga֖ʻ bȧ⁠kò̇hàni֑ym wa⁠yi̇sò̇֞b dwyg há⁠ʼàdòmi֗y wa⁠yi̇pĕgȧʻ-hẇʼ֙ bȧ⁠kò֣̇hàni֔ym wa⁠yá֣̇meţ ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ şĕ̌mòni֤ym wa⁠ẖàmişá̇̌h֙ ʼi֔yş̌ nòşé֖̂ʼ ʼép֥wòd báֽ̇d׃"],[22,19,"וְ⁠אֵ֨ת נֹ֤ב עִיר־הַ⁠כֹּֽהֲנִים֙ הִכָּ֣ה לְ⁠פִי־חֶ֔רֶב מֵ⁠אִישׁ֙ וְ⁠עַד־אִשָּׁ֔ה מֵ⁠עוֹלֵ֖ל וְ⁠עַד־יוֹנֵ֑ק וְ⁠שׁ֧וֹר וַ⁠חֲמ֛וֹר וָ⁠שֶׂ֖ה לְ⁠פִי־חָֽרֶב׃","wĕ⁠ʼé֨ţ nò֤b ʻiyr-ha⁠kòֽ̇hàniym֙ hiká֣̇h lĕ⁠piy-ẖe֔reb mé⁠ʼiyş̌֙ wĕ⁠ʻad-ʼişá̇̌֔h mé⁠ʻwòlé֖l wĕ⁠ʻad-ywòné֑q wĕ⁠ş֧̌wòr wa⁠ẖàm֛wòr wá⁠şê֖h lĕ⁠piy-ẖáֽreb׃"],[22,20,"וַ⁠יִּמָּלֵ֣ט בֵּן־אֶחָ֗ד לַ⁠אֲחִימֶ֨לֶךְ֙ בֶּן־אֲחִט֔וּב וּ⁠שְׁמ֖⁠וֹ אֶבְיָתָ֑ר וַ⁠יִּבְרַ֖ח אַחֲרֵ֥י דָוִֽד׃","wa⁠yi̇má̇lé֣t bé̇n-ʼeẖá֗d la⁠ʼàẖiyme֨lekĕ֙ bėn-ʼàẖit֔ẇb ẇ⁠şĕ̌m֖⁠wò ʼebĕyáţá֑r wa⁠yi̇bĕra֖ẖ ʼaẖàré֥y dáwiֽd׃"],[22,21,"וַ⁠יַּגֵּ֥ד אֶבְיָתָ֖ר לְ⁠דָוִ֑ד כִּ֚י הָרַ֣ג שָׁא֔וּל אֵ֖ת כֹּהֲנֵ֥י יְהוָֽה׃","wa⁠yȧgé֥̇d ʼebĕyáţá֖r lĕ⁠dáwi֑d ki֚̇y hára֣g şá̌ʼ֔ẇl ʼé֖ţ kò̇hàné֥y yĕhwáֽh׃"],[22,22,"וַ⁠יֹּ֨אמֶר דָּוִ֜ד לְ⁠אֶבְיָתָ֗ר יָדַ֜עְתִּי בַּ⁠יּ֤וֹם הַ⁠הוּא֙ כִּֽי־שָׁם֙ דויג הָ⁠אֲדֹמִ֔י כִּֽי־הַגֵּ֥ד יַגִּ֖יד לְ⁠שָׁא֑וּל אָנֹכִ֣י סַבֹּ֔תִי בְּ⁠כָל־נֶ֖פֶשׁ בֵּ֥ית אָבִֽי⁠ךָ׃","wa⁠yò̇֨ʼmer dá̇wi֜d lĕ⁠ʼebĕyáţá֗r yáda֜ʻĕţi̇y bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ kiֽ̇y-şá̌m֙ dwyg há⁠ʼàdòmi֔y kiֽ̇y-hagé֥̇d yagi֖̇yd lĕ⁠şá̌ʼ֑ẇl ʼánòki֣y sabò̇֔ţiy bĕ̇⁠kál-ne֖peş̌ bé֥̇yţ ʼábiֽy⁠ká׃"],[22,23,"שְׁבָ֤⁠ה אִתִּ⁠י֙ אַל־תִּירָ֔א כִּ֛י אֲשֶׁר־יְבַקֵּ֥שׁ אֶת־נַפְשִׁ֖⁠י יְבַקֵּ֣שׁ אֶת־נַפְשֶׁ֑⁠ךָ כִּֽי־מִשְׁמֶ֥רֶת אַתָּ֖ה עִמָּדִֽ⁠י׃","şĕ̌bá֤⁠h ʼiţi̇⁠y֙ ʼal-ţi̇yrá֔ʼ ki֛̇y ʼàşěr-yĕbaqé֥̇ş̌ ʼeţ-napĕşǐ֖⁠y yĕbaqé֣̇ş̌ ʼeţ-napĕşě֑⁠ká kiֽ̇y-mişĕ̌me֥reţ ʼaţá֖̇h ʻimá̇diֽ⁠y׃"],[23,1,"וַ⁠יַּגִּ֥דוּ לְ⁠דָוִ֖ד לֵ⁠אמֹ֑ר הִנֵּ֤ה פְלִשְׁתִּים֙ נִלְחָמִ֣ים בִּ⁠קְעִילָ֔ה וְ⁠הֵ֖מָּה שֹׁסִ֥ים אֶת־הַ⁠גֳּרָנֽוֹת׃","wa⁠yȧgi֥̇dẇ lĕ⁠dáwi֖d lé⁠ʼmò֑r hiné֤̇h pĕlişĕ̌ţi̇ym֙ nilĕẖámi֣ym bi̇⁠qĕʻiylá֔h wĕ⁠hé֖má̇h şò̌si֥ym ʼeţ-ha⁠gȯránֽwòţ׃"],[23,2,"וַ⁠יִּשְׁאַ֨ל דָּוִ֤ד בַּֽ⁠יהוָה֙ לֵ⁠אמֹ֔ר הַ⁠אֵלֵ֣ךְ וְ⁠הִכֵּ֔יתִי בַּ⁠פְּלִשְׁתִּ֖ים הָ⁠אֵ֑לֶּה ס וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־דָּוִ֗ד לֵ֚ךְ וְ⁠הִכִּ֣יתָ בַ⁠פְּלִשְׁתִּ֔ים וְ⁠הוֹשַׁעְתָּ֖ אֶת־קְעִילָֽה׃","wa⁠yi̇şĕ̌ʼa֨l dá̇wi֤d bȧֽ⁠yhwáh֙ lé⁠ʼmò֔r ha⁠ʼélé֣kĕ wĕ⁠hiké̇֔yţiy bȧ⁠pĕ̇lişĕ̌ţi֖̇ym há⁠ʼé֑lėh s wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-dá̇wi֗d lé֚kĕ wĕ⁠hiki֣̇yţá ba⁠pĕ̇lişĕ̌ţi̇֔ym wĕ⁠hwòşǎʻĕţá֖̇ ʼeţ-qĕʻiyláֽh׃"],[23,3,"וַ⁠יֹּ֨אמְר֜וּ אַנְשֵׁ֤י דָוִד֙ אֵלָ֔י⁠ו הִנֵּ֨ה אֲנַ֥חְנוּ פֹ֛ה בִּֽ⁠יהוּדָ֖ה יְרֵאִ֑ים וְ⁠אַף֙ כִּֽי־נֵלֵ֣ךְ קְעִלָ֔ה אֶל־מַֽעַרְכ֖וֹת פְּלִשְׁתִּֽים׃ס","wa⁠yò̇֨ʼmĕr֜ẇ ʼanĕşé֤̌y dáwid֙ ʼélá֔y⁠w hiné̇֨h ʼàna֥ẖĕnẇ pò֛h biֽ̇⁠yhẇdá֖h yĕréʼi֑ym wĕ⁠ʼap֙ kiֽ̇y-nélé֣kĕ qĕʻilá֔h ʼel-mֽaʻarĕk֖wòţ pĕ̇lişĕ̌ţiֽ̇ym׃s"],[23,4,"וַ⁠יּ֨וֹסֶף ע֤וֹד דָּוִד֙ לִ⁠שְׁאֹ֣ל בַּֽ⁠יהוָ֔ה ס וַֽ⁠יַּעֲנֵ֖⁠הוּ יְהוָ֑ה וַ⁠יֹּ֗אמֶר ק֚וּם רֵ֣ד קְעִילָ֔ה כִּֽי־אֲנִ֥י נֹתֵ֛ן אֶת־פְּלִשְׁתִּ֖ים בְּ⁠יָדֶֽ⁠ךָ׃","wa⁠ẏ֨wòsep ʻ֤wòd dá̇wid֙ li⁠şĕ̌ʼò֣l bȧֽ⁠yhwá֔h s waֽ⁠yȧʻàné֖⁠hẇ yĕhwá֑h wa⁠yò̇֗ʼmer q֚ẇm ré֣d qĕʻiylá֔h kiֽ̇y-ʼàni֥y nòţé֛n ʼeţ-pĕ̇lişĕ̌ţi֖̇ym bĕ̇⁠yádeֽ⁠ká׃"],[23,5,"וַ⁠יֵּ֣לֶךְ דָּוִד֩ ו⁠אנש⁠ו קְעִילָ֜ה וַ⁠יִּלָּ֣חֶם בַּ⁠פְּלִשְׁתִּ֗ים וַ⁠יִּנְהַג֙ אֶת־מִקְנֵי⁠הֶ֔ם וַ⁠יַּ֥ךְ בָּ⁠הֶ֖ם מַכָּ֣ה גְדוֹלָ֑ה וַ⁠יֹּ֣שַׁע דָּוִ֔ד אֵ֖ת יֹשְׁבֵ֥י קְעִילָֽה׃ס","wa⁠yé֣̇lekĕ dá̇wid֩ w⁠ʼnş⁠w qĕʻiylá֜h wa⁠yi̇lá֣̇ẖem bȧ⁠pĕ̇lişĕ̌ţi̇֗ym wa⁠yi̇nĕhag֙ ʼeţ-miqĕnéy⁠he֔m wa⁠yȧ֥kĕ bá̇⁠he֖m maká֣̇h gĕdwòlá֑h wa⁠yò֣̇şǎʻ dá̇wi֔d ʼé֖ţ yòşĕ̌bé֥y qĕʻiyláֽh׃s"],[23,6,"וַ⁠יְהִ֗י בִּ֠⁠בְרֹחַ אֶבְיָתָ֧ר בֶּן־אֲחִימֶ֛לֶךְ אֶל־דָּוִ֖ד קְעִילָ֑ה אֵפ֖וֹד יָרַ֥ד בְּ⁠יָדֽ⁠וֹ׃","wa⁠yĕhi֗y bi̇֠⁠bĕròẖa ʼebĕyáţá֧r bėn-ʼàẖiyme֛lekĕ ʼel-dá̇wi֖d qĕʻiylá֑h ʼép֖wòd yára֥d bĕ̇⁠yádֽ⁠wò׃"],[23,7,"וַ⁠יֻּגַּ֣ד לְ⁠שָׁא֔וּל כִּי־בָ֥א דָוִ֖ד קְעִילָ֑ה וַ⁠יֹּ֣אמֶר שָׁא֗וּל נִכַּ֨ר אֹת֤⁠וֹ אֱלֹהִים֙ בְּ⁠יָדִ֔⁠י כִּ֚י נִסְגַּ֣ר לָ⁠ב֔וֹא בְּ⁠עִ֖יר דְּלָתַ֥יִם וּ⁠בְרִֽיחַ׃","wa⁠yu̇gȧ֣d lĕ⁠şá̌ʼ֔ẇl ki̇y-bá֥ʼ dáwi֖d qĕʻiylá֑h wa⁠yò֣̇ʼmer şá̌ʼ֗ẇl nikȧ֨r ʼòţ֤⁠wò ʼèlòhiym֙ bĕ̇⁠yádi֔⁠y ki֚̇y nisĕgȧ֣r lá⁠b֔wòʼ bĕ̇⁠ʻi֖yr dĕ̇láţa֥yim ẇ⁠bĕriֽyẖa׃"],[23,8,"וַ⁠יְשַׁמַּ֥ע שָׁא֛וּל אֶת־כָּל־הָ⁠עָ֖ם לַ⁠מִּלְחָמָ֑ה לָ⁠רֶ֣דֶת קְעִילָ֔ה לָ⁠צ֥וּר אֶל־דָּוִ֖ד וְ⁠אֶל־אֲנָשָֽׁי⁠ו׃","wa⁠yĕşǎmȧ֥ʻ şá̌ʼ֛ẇl ʼeţ-ká̇l-há⁠ʻá֖m la⁠mi̇lĕẖámá֑h lá⁠re֣deţ qĕʻiylá֔h lá⁠ẕ֥ẇr ʼel-dá̇wi֖d wĕ⁠ʼel-ʼànáşáֽ̌y⁠w׃"],[23,9,"וַ⁠יֵּ֣דַע דָּוִ֔ד כִּ֣י עָלָ֔י⁠ו שָׁא֖וּל מַחֲרִ֣ישׁ הָ⁠רָעָ֑ה וַ⁠יֹּ֨אמֶר֙ אֶל־אֶבְיָתָ֣ר הַ⁠כֹּהֵ֔ן הַגִּ֖ישָׁ⁠ה הָ⁠אֵפֽוֹד׃ס","wa⁠yé֣̇daʻ dá̇wi֔d ki֣̇y ʻálá֔y⁠w şá̌ʼ֖ẇl maẖàri֣yş̌ há⁠ráʻá֑h wa⁠yò̇֨ʼmer֙ ʼel-ʼebĕyáţá֣r ha⁠kò̇hé֔n hagi֖̇yşá̌⁠h há⁠ʼépֽwòd׃s"],[23,10,"וַ⁠יֹּאמֶר֮ דָּוִד֒ יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל שָׁמֹ֤עַ שָׁמַע֙ עַבְדְּ⁠ךָ֔ כִּֽי־מְבַקֵּ֥שׁ שָׁא֖וּל לָ⁠ב֣וֹא אֶל־קְעִילָ֑ה לְ⁠שַׁחֵ֥ת לָ⁠עִ֖יר בַּ⁠עֲבוּרִֽ⁠י׃","wa⁠yò̇ʼmer֮ dá̇wid֒ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l şá̌mò֤ʻa şá̌maʻ֙ ʻabĕdĕ̇⁠ká֔ kiֽ̇y-mĕbaqé֥̇ş̌ şá̌ʼ֖ẇl lá⁠b֣wòʼ ʼel-qĕʻiylá֑h lĕ⁠şǎẖé֥ţ lá⁠ʻi֖yr bȧ⁠ʻàbẇriֽ⁠y׃"],[23,11,"הֲ⁠יַסְגִּרֻ֣⁠נִי בַעֲלֵי֩ קְעִילָ֨ה בְ⁠יָד֜⁠וֹ הֲ⁠יֵרֵ֣ד שָׁא֗וּל כַּֽ⁠אֲשֶׁר֙ שָׁמַ֣ע עַבְדֶּ֔⁠ךָ יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הַגֶּד־נָ֖א לְ⁠עַבְדֶּ֑⁠ךָ ס וַ⁠יֹּ֥אמֶר יְהוָ֖ה יֵרֵֽד׃","hà⁠yasĕgi̇ru֣⁠niy baʻàléy֩ qĕʻiylá֨h bĕ⁠yád֜⁠wò hà⁠yéré֣d şá̌ʼ֗ẇl kȧֽ⁠ʼàşěr֙ şá̌ma֣ʻ ʻabĕdė֔⁠ká yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l hagėd-ná֖ʼ lĕ⁠ʻabĕdė֑⁠ká s wa⁠yò֥̇ʼmer yĕhwá֖h yéréֽd׃"],[23,12,"וַ⁠יֹּ֣אמֶר דָּוִ֔ד הֲ⁠יַסְגִּ֜רוּ בַּעֲלֵ֧י קְעִילָ֛ה אֹתִ֥⁠י וְ⁠אֶת־אֲנָשַׁ֖⁠י בְּ⁠יַד־שָׁא֑וּל וַ⁠יֹּ֥אמֶר יְהוָ֖ה יַסְגִּֽירוּ׃ס","wa⁠yò֣̇ʼmer dá̇wi֔d hà⁠yasĕgi̇֜rẇ bȧʻàlé֧y qĕʻiylá֛h ʼòţi֥⁠y wĕ⁠ʼeţ-ʼànáşǎ֖⁠y bĕ̇⁠yad-şá̌ʼ֑ẇl wa⁠yò֥̇ʼmer yĕhwá֖h yasĕgiֽ̇yrẇ׃s"],[23,13,"וַ⁠יָּקָם֩ דָּוִ֨ד וַ⁠אֲנָשָׁ֜י⁠ו כְּ⁠שֵׁשׁ־מֵא֣וֹת אִ֗ישׁ וַ⁠יֵּצְאוּ֙ מִ⁠קְּעִלָ֔ה וַ⁠יִּֽתְהַלְּכ֖וּ בַּ⁠אֲשֶׁ֣ר יִתְהַלָּ֑כוּ וּ⁠לְ⁠שָׁא֣וּל הֻגַּ֗ד כִּֽי־נִמְלַ֤ט דָּוִד֙ מִ⁠קְּעִילָ֔ה וַ⁠יֶּחְדַּ֖ל לָ⁠צֵֽאת׃","wa⁠yá̇qám֩ dá̇wi֨d wa⁠ʼànáşá̌֜y⁠w kĕ̇⁠şé̌ş̌-méʼ֣wòţ ʼi֗yş̌ wa⁠yé̇ẕĕʼẇ֙ mi⁠qĕ̇ʻilá֔h wa⁠yiֽ̇ţĕhalĕ̇k֖ẇ bȧ⁠ʼàşě֣r yiţĕhalá֑̇kẇ ẇ⁠lĕ⁠şá̌ʼ֣ẇl hugȧ֗d kiֽ̇y-nimĕla֤t dá̇wid֙ mi⁠qĕ̇ʻiylá֔h wa⁠yėẖĕdȧ֖l lá⁠ẕéֽʼţ׃"],[23,14,"וַ⁠יֵּ֨שֶׁב דָּוִ֤ד בַּ⁠מִּדְבָּר֙ בַּ⁠מְּצָד֔וֹת וַ⁠יֵּ֥שֶׁב בָּ⁠הָ֖ר בְּ⁠מִדְבַּר־זִ֑יף וַ⁠יְבַקְשֵׁ֤⁠הוּ שָׁאוּל֙ כָּל־הַ⁠יָּמִ֔ים וְ⁠לֹֽא־נְתָנ֥⁠וֹ אֱלֹהִ֖ים בְּ⁠יָדֽ⁠וֹ׃","wa⁠yé̇֨şěb dá̇wi֤d bȧ⁠mi̇dĕbá̇r֙ bȧ⁠mĕ̇ẕád֔wòţ wa⁠yé֥̇şěb bá̇⁠há֖r bĕ̇⁠midĕbȧr-zi֑yp wa⁠yĕbaqĕşé֤̌⁠hẇ şá̌ʼẇl֙ ká̇l-ha⁠yá̇mi֔ym wĕ⁠lòֽʼ-nĕţán֥⁠wò ʼèlòhi֖ym bĕ̇⁠yádֽ⁠wò׃"],[23,15,"וַ⁠יַּ֣רְא דָוִ֔ד כִּֽי־יָצָ֥א שָׁא֖וּל לְ⁠בַקֵּ֣שׁ אֶת־נַפְשׁ֑⁠וֹ וְ⁠דָוִ֥ד בְּ⁠מִדְבַּר־זִ֖יף בַּ⁠חֹֽרְשָׁה׃ס","wa⁠yȧ֣rĕʼ dáwi֔d kiֽ̇y-yáẕá֥ʼ şá̌ʼ֖ẇl lĕ⁠baqé֣̇ş̌ ʼeţ-napĕş֑̌⁠wò wĕ⁠dáwi֥d bĕ̇⁠midĕbȧr-zi֖yp bȧ⁠ẖòֽrĕşá̌h׃s"],[23,16,"וַ⁠יָּ֨קָם֙ יְהוֹנָתָ֣ן בֶּן־שָׁא֔וּל וַ⁠יֵּ֥לֶךְ אֶל־דָּוִ֖ד חֹ֑רְשָׁה וַ⁠יְחַזֵּ֥ק אֶת־יָד֖⁠וֹ בֵּ⁠אלֹהִֽים׃","wa⁠yá̇֨qám֙ yĕhwònáţá֣n bėn-şá̌ʼ֔ẇl wa⁠yé֥̇lekĕ ʼel-dá̇wi֖d ẖò֑rĕşá̌h wa⁠yĕẖazé֥̇q ʼeţ-yád֖⁠wò bé̇⁠ʼlòhiֽym׃"],[23,17,"וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו אַל־תִּירָ֗א כִּ֠י לֹ֤א תִֽמְצָאֲ⁠ךָ֙ יַ֚ד שָׁא֣וּל אָבִ֔⁠י וְ⁠אַתָּה֙ תִּמְלֹ֣ךְ עַל־יִשְׂרָאֵ֔ל וְ⁠אָנֹכִ֖י אֶֽהְיֶה־לְּ⁠ךָ֣ לְ⁠מִשְׁנֶ֑ה וְ⁠גַם־שָׁא֥וּל אָבִ֖⁠י יֹדֵ֥עַ כֵּֽן׃","wa⁠yò̇֨ʼmer ʼélá֜y⁠w ʼal-ţi̇yrá֗ʼ ki̇֠y lò֤ʼ ţiֽmĕẕáʼà⁠ká֙ ya֚d şá̌ʼ֣ẇl ʼábi֔⁠y wĕ⁠ʼaţá̇h֙ ţi̇mĕlò֣kĕ ʻal-yişĕ̂ráʼé֔l wĕ⁠ʼánòki֖y ʼeֽhĕyeh-lĕ̇⁠ká֣ lĕ⁠mişĕ̌ne֑h wĕ⁠gam-şá̌ʼ֥ẇl ʼábi֖⁠y yòdé֥ʻa kéֽ̇n׃"],[23,18,"וַ⁠יִּכְרְת֧וּ שְׁנֵי⁠הֶ֛ם בְּרִ֖ית לִ⁠פְנֵ֣י יְהוָ֑ה וַ⁠יֵּ֤שֶׁב דָּוִד֙ בַּ⁠חֹ֔רְשָׁה וִ⁠יהוֹנָתָ֖ן הָלַ֥ךְ לְ⁠בֵיתֽ⁠וֹ׃ס","wa⁠yi̇kĕrĕţ֧ẇ şĕ̌néy⁠he֛m bĕ̇ri֖yţ li⁠pĕné֣y yĕhwá֑h wa⁠yé֤̇şěb dá̇wid֙ bȧ⁠ẖò֔rĕşá̌h wi⁠yhwònáţá֖n hála֥kĕ lĕ⁠béyţֽ⁠wò׃s"],[23,19,"וַ⁠יַּעֲל֤וּ זִפִים֙ אֶל־שָׁא֔וּל הַ⁠גִּבְעָ֖תָ⁠ה לֵ⁠אמֹ֑ר הֲ⁠ל֣וֹא דָ֠וִד מִסְתַּתֵּ֨ר עִמָּ֤⁠נוּ בַ⁠מְּצָדוֹת֙ בַּ⁠חֹ֔רְשָׁה בְּ⁠גִבְעַת֙ הַֽ⁠חֲכִילָ֔ה אֲשֶׁ֖ר מִ⁠ימִ֥ין הַ⁠יְשִׁימֽוֹן׃","wa⁠yȧʻàl֤ẇ zipiym֙ ʼel-şá̌ʼ֔ẇl ha⁠gi̇bĕʻá֖ţá⁠h lé⁠ʼmò֑r hà⁠l֣wòʼ dá֠wid misĕţȧţé̇֨r ʻimá֤̇⁠nẇ ba⁠mĕ̇ẕádwòţ֙ bȧ⁠ẖò֔rĕşá̌h bĕ̇⁠gibĕʻaţ֙ haֽ⁠ẖàkiylá֔h ʼàşě֖r mi⁠ymi֥yn ha⁠yĕşǐymֽwòn׃"],[23,20,"וְ֠⁠עַתָּה לְ⁠כָל־אַוַּ֨ת נַפְשְׁ⁠ךָ֥ הַ⁠מֶּ֛לֶךְ לָ⁠רֶ֖דֶת רֵ֑ד וְ⁠לָ֥⁠נוּ הַסְגִּיר֖⁠וֹ בְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wĕ֠⁠ʻaţá̇h lĕ⁠kál-ʼawȧ֨ţ napĕşĕ̌⁠ká֥ ha⁠mė֛lekĕ lá⁠re֖deţ ré֑d wĕ⁠lá֥⁠nẇ hasĕgi̇yr֖⁠wò bĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[23,21,"וַ⁠יֹּ֣אמֶר שָׁא֔וּל בְּרוּכִ֥ים אַתֶּ֖ם לַֽ⁠יהוָ֑ה כִּ֥י חֲמַלְתֶּ֖ם עָלָֽ⁠י׃","wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl bĕ̇rẇki֥ym ʼaţė֖m laֽ⁠yhwá֑h ki֥̇y ẖàmalĕţė֖m ʻáláֽ⁠y׃"],[23,22,"לְכוּ־נָ֞א הָכִ֣ינוּ ע֗וֹד וּ⁠דְע֤וּ וּ⁠רְאוּ֙ אֶת־מְקוֹמ⁠וֹ֙ אֲשֶׁ֣ר תִּֽהְיֶ֣ה רַגְל֔⁠וֹ מִ֥י רָאָ֖⁠הוּ שָׁ֑ם כִּ֚י אָמַ֣ר אֵלַ֔⁠י עָר֥וֹם יַעְרִ֖ם הֽוּא׃","lĕkẇ-ná֞ʼ háki֣ynẇ ʻ֗wòd ẇ⁠dĕʻ֤ẇ ẇ⁠rĕʼẇ֙ ʼeţ-mĕqwòm⁠wò֙ ʼàşě֣r ţiֽ̇hĕye֣h ragĕl֔⁠wò mi֥y ráʼá֖⁠hẇ şá֑̌m ki֚̇y ʼáma֣r ʼéla֔⁠y ʻár֥wòm yaʻĕri֖m hֽẇʼ׃"],[23,23,"וּ⁠רְא֣וּ וּ⁠דְע֗וּ מִ⁠כֹּ֤ל הַ⁠מַּֽחֲבֹאִים֙ אֲשֶׁ֣ר יִתְחַבֵּ֣א שָׁ֔ם וְ⁠שַׁבְתֶּ֤ם אֵלַ⁠י֙ אֶל־נָכ֔וֹן וְ⁠הָלַכְתִּ֖י אִתְּ⁠כֶ֑ם וְ⁠הָיָה֙ אִם־יֶשְׁנ֣⁠וֹ בָ⁠אָ֔רֶץ וְ⁠חִפַּשְׂתִּ֣י אֹת֔⁠וֹ בְּ⁠כֹ֖ל אַלְפֵ֥י יְהוּדָֽה׃","ẇ⁠rĕʼ֣ẇ ẇ⁠dĕʻ֗ẇ mi⁠kò֤̇l ha⁠mȧֽẖàbòʼiym֙ ʼàşě֣r yiţĕẖabé֣̇ʼ şá̌֔m wĕ⁠şǎbĕţė֤m ʼéla⁠y֙ ʼel-nák֔wòn wĕ⁠hálakĕţi֖̇y ʼiţĕ̇⁠ke֑m wĕ⁠háyáh֙ ʼim-yeşĕ̌n֣⁠wò bá⁠ʼá֔reẕ wĕ⁠ẖipȧşĕ̂ţi֣̇y ʼòţ֔⁠wò bĕ̇⁠kò֖l ʼalĕpé֥y yĕhẇdáֽh׃"],[23,24,"וַ⁠יָּק֛וּמוּ וַ⁠יֵּלְכ֥וּ זִ֖יפָ⁠ה לִ⁠פְנֵ֣י שָׁא֑וּל וְ⁠דָוִ֨ד וַ⁠אֲנָשָׁ֜י⁠ו בְּ⁠מִדְבַּ֤ר מָעוֹן֙ בָּ⁠עֲרָבָ֔ה אֶ֖ל יְמִ֥ין הַ⁠יְשִׁימֽוֹן׃","wa⁠yá̇q֛ẇmẇ wa⁠yé̇lĕk֥ẇ zi֖ypá⁠h li⁠pĕné֣y şá̌ʼ֑ẇl wĕ⁠dáwi֨d wa⁠ʼànáşá̌֜y⁠w bĕ̇⁠midĕbȧ֤r máʻwòn֙ bá̇⁠ʻàrábá֔h ʼe֖l yĕmi֥yn ha⁠yĕşǐymֽwòn׃"],[23,25,"וַ⁠יֵּ֨לֶךְ שָׁא֣וּל וַ⁠אֲנָשָׁי⁠ו֮ לְ⁠בַקֵּשׁ֒ וַ⁠יַּגִּ֣דוּ לְ⁠דָוִ֔ד וַ⁠יֵּ֣רֶד הַ⁠סֶּ֔לַע וַ⁠יֵּ֖שֶׁב בְּ⁠מִדְבַּ֣ר מָע֑וֹן וַ⁠יִּשְׁמַ֣ע שָׁא֔וּל וַ⁠יִּרְדֹּ֥ף אַחֲרֵֽי־דָוִ֖ד מִדְבַּ֥ר מָעֽוֹן׃","wa⁠yé̇֨lekĕ şá̌ʼ֣ẇl wa⁠ʼànáşá̌y⁠w֮ lĕ⁠baqé̇ş̌֒ wa⁠yȧgi֣̇dẇ lĕ⁠dáwi֔d wa⁠yé֣̇red ha⁠sė֔laʻ wa⁠yé֖̇şěb bĕ̇⁠midĕbȧ֣r máʻ֑wòn wa⁠yi̇şĕ̌ma֣ʻ şá̌ʼ֔ẇl wa⁠yi̇rĕdò֥̇p ʼaẖàréֽy-dáwi֖d midĕbȧ֥r máʻֽwòn׃"],[23,26,"וַ⁠יֵּ֨לֶךְ שָׁא֜וּל מִ⁠צַּ֤ד הָ⁠הָר֙ מִ⁠זֶּ֔ה וְ⁠דָוִ֧ד וַ⁠אֲנָשָׁ֛י⁠ו מִ⁠צַּ֥ד הָ⁠הָ֖ר מִ⁠זֶּ֑ה וַ⁠יְהִ֨י דָוִ֜ד נֶחְפָּ֤ז לָ⁠לֶ֨כֶת֙ מִ⁠פְּנֵ֣י שָׁא֔וּל וְ⁠שָׁא֣וּל וַ⁠אֲנָשָׁ֗י⁠ו עֹֽטְרִ֛ים אֶל־דָּוִ֥ד וְ⁠אֶל־אֲנָשָׁ֖י⁠ו לְ⁠תָפְשָֽׂ⁠ם׃","wa⁠yé̇֨lekĕ şá̌ʼ֜ẇl mi⁠ẕȧ֤d há⁠hár֙ mi⁠zė֔h wĕ⁠dáwi֧d wa⁠ʼànáşá֛̌y⁠w mi⁠ẕȧ֥d há⁠há֖r mi⁠zė֑h wa⁠yĕhi֨y dáwi֜d neẖĕpá֤̇z lá⁠le֨keţ֙ mi⁠pĕ̇né֣y şá̌ʼ֔ẇl wĕ⁠şá̌ʼ֣ẇl wa⁠ʼànáşá̌֗y⁠w ʻòֽtĕri֛ym ʼel-dá̇wi֥d wĕ⁠ʼel-ʼànáşá֖̌y⁠w lĕ⁠ţápĕşáֽ̂⁠m׃"],[23,27,"וּ⁠מַלְאָ֣ךְ בָּ֔א אֶל־שָׁא֖וּל לֵ⁠אמֹ֑ר מַהֲרָ֣⁠ה וְ⁠לֵ֔כָ⁠ה כִּֽי־פָשְׁט֥וּ פְלִשְׁתִּ֖ים עַל־הָ⁠אָֽרֶץ׃","ẇ⁠malĕʼá֣kĕ bá̇֔ʼ ʼel-şá̌ʼ֖ẇl lé⁠ʼmò֑r mahàrá֣⁠h wĕ⁠lé֔ká⁠h kiֽ̇y-páşĕ̌t֥ẇ pĕlişĕ̌ţi֖̇ym ʻal-há⁠ʼáֽreẕ׃"],[23,28,"וַ⁠יָּ֣שָׁב שָׁא֗וּל מִ⁠רְדֹף֙ אַחֲרֵ֣י דָוִ֔ד וַ⁠יֵּ֖לֶךְ לִ⁠קְרַ֣את פְּלִשְׁתִּ֑ים עַל־כֵּ֗ן קָֽרְאוּ֙ לַ⁠מָּק֣וֹם הַ⁠ה֔וּא סֶ֖לַע הַֽמַּחְלְקֽוֹת׃","wa⁠yá֣̇şá̌b şá̌ʼ֗ẇl mi⁠rĕdòp֙ ʼaẖàré֣y dáwi֔d wa⁠yé֖̇lekĕ li⁠qĕra֣ʼţ pĕ̇lişĕ̌ţi֑̇ym ʻal-ké̇֗n qáֽrĕʼẇ֙ la⁠má̇q֣wòm ha⁠h֔ẇʼ se֖laʻ haֽmȧẖĕlĕqֽwòţ׃"],[23,29,"וַ⁠יַּ֥עַל דָּוִ֖ד מִ⁠שָּׁ֑ם וַ⁠יֵּ֖שֶׁב בִּ⁠מְצָד֥וֹת עֵֽין־גֶּֽדִי׃","wa⁠yȧ֥ʻal dá̇wi֖d mi⁠şá֑̇̌m wa⁠yé֖̇şěb bi̇⁠mĕẕád֥wòţ ʻéֽyn-gėֽdiy׃"],[24,1,"וַ⁠יְהִ֗י כַּֽ⁠אֲשֶׁר֙ שָׁ֣ב שָׁא֔וּל מֵ⁠אַחֲרֵ֖י פְּלִשְׁתִּ֑ים וַ⁠יַּגִּ֤דוּ ל⁠וֹ֙ לֵ⁠אמֹ֔ר הִנֵּ֣ה דָוִ֔ד בְּ⁠מִדְבַּ֖ר עֵ֥ין גֶּֽדִי׃ס","wa⁠yĕhi֗y kȧֽ⁠ʼàşěr֙ şá֣̌b şá̌ʼ֔ẇl mé⁠ʼaẖàré֖y pĕ̇lişĕ̌ţi֑̇ym wa⁠yȧgi֤̇dẇ l⁠wò֙ lé⁠ʼmò֔r hiné֣̇h dáwi֔d bĕ̇⁠midĕbȧ֖r ʻé֥yn gėֽdiy׃s"],[24,2,"וַ⁠יִּקַּ֣ח שָׁא֗וּל שְׁלֹ֧שֶׁת אֲלָפִ֛ים אִ֥ישׁ בָּח֖וּר מִ⁠כָּל־יִשְׂרָאֵ֑ל וַ⁠יֵּ֗לֶךְ לְ⁠בַקֵּ֤שׁ אֶת־דָּוִד֙ וַֽ⁠אֲנָשָׁ֔י⁠ו עַל־פְּנֵ֖י צוּרֵ֥י הַ⁠יְּעֵלִֽים׃","wa⁠yi̇qȧ֣ẖ şá̌ʼ֗ẇl şĕ̌lò֧şěţ ʼàlápi֛ym ʼi֥yş̌ bá̇ẖ֖ẇr mi⁠ká̇l-yişĕ̂ráʼé֑l wa⁠yé̇֗lekĕ lĕ⁠baqé֤̇ş̌ ʼeţ-dá̇wid֙ waֽ⁠ʼànáşá̌֔y⁠w ʻal-pĕ̇né֖y ẕẇré֥y ha⁠yĕ̇ʻéliֽym׃"],[24,3,"וַ֠⁠יָּבֹא אֶל־גִּדְר֨וֹת הַ⁠צֹּ֤אן עַל־הַ⁠דֶּ֨רֶךְ֙ וְ⁠שָׁ֣ם מְעָרָ֔ה וַ⁠יָּבֹ֥א שָׁא֖וּל לְ⁠הָסֵ֣ךְ אֶת־רַגְלָ֑י⁠ו וְ⁠דָוִד֙ וַ⁠אֲנָשָׁ֔י⁠ו בְּ⁠יַרְכְּתֵ֥י הַ⁠מְּעָרָ֖ה יֹשְׁבִֽים׃","wa֠⁠yá̇bòʼ ʼel-gi̇dĕr֨wòţ ha⁠ẕò֤̇ʼn ʻal-ha⁠dė֨rekĕ֙ wĕ⁠şá֣̌m mĕʻárá֔h wa⁠yá̇bò֥ʼ şá̌ʼ֖ẇl lĕ⁠hásé֣kĕ ʼeţ-ragĕlá֑y⁠w wĕ⁠dáwid֙ wa⁠ʼànáşá̌֔y⁠w bĕ̇⁠yarĕkĕ̇ţé֥y ha⁠mĕ̇ʻárá֖h yòşĕ̌biֽym׃"],[24,4,"וַ⁠יֹּאמְרוּ֩ אַנְשֵׁ֨י דָוִ֜ד אֵלָ֗י⁠ו הִנֵּ֨ה הַ⁠יּ֜וֹם אֲֽשֶׁר־אָמַ֧ר יְהוָ֣ה אֵלֶ֗י⁠ךָ הִנֵּ֨ה אָנֹכִ֜י נֹתֵ֤ן אֶת־איבי⁠ך בְּ⁠יָדֶ֔⁠ךָ וְ⁠עָשִׂ֣יתָ לּ֔⁠וֹ כַּ⁠אֲשֶׁ֖ר יִטַ֣ב בְּ⁠עֵינֶ֑י⁠ךָ וַ⁠יָּ֣קָם דָּוִ֗ד וַ⁠יִּכְרֹ֛ת אֶת־כְּנַֽף־הַ⁠מְּעִ֥יל אֲשֶׁר־לְ⁠שָׁא֖וּל בַּ⁠לָּֽט׃","wa⁠yò̇ʼmĕrẇ֩ ʼanĕşé̌֨y dáwi֜d ʼélá֗y⁠w hiné̇֨h ha⁠ẏ֜wòm ʼàֽşěr-ʼáma֧r yĕhwá֣h ʼéle֗y⁠ká hiné̇֨h ʼánòki֜y nòţé֤n ʼeţ-ʼyby⁠k bĕ̇⁠yáde֔⁠ká wĕ⁠ʻáşî֣yţá l̇֔⁠wò kȧ⁠ʼàşě֖r yita֣b bĕ̇⁠ʻéyne֑y⁠ká wa⁠yá֣̇qám dá̇wi֗d wa⁠yi̇kĕrò֛ţ ʼeţ-kĕ̇naֽp-ha⁠mĕ̇ʻi֥yl ʼàşěr-lĕ⁠şá̌ʼ֖ẇl bȧ⁠láֽ̇t׃"],[24,5,"וַֽ⁠יְהִי֙ אַֽחֲרֵי־כֵ֔ן וַ⁠יַּ֥ךְ לֵב־דָּוִ֖ד אֹת֑⁠וֹ עַ֚ל אֲשֶׁ֣ר כָּרַ֔ת אֶת־כָּנָ֖ף אֲשֶׁ֥ר לְ⁠שָׁאֽוּל׃ס","waֽ⁠yĕhiy֙ ʼaֽẖàréy-ké֔n wa⁠yȧ֥kĕ léb-dá̇wi֖d ʼòţ֑⁠wò ʻa֚l ʼàşě֣r ká̇ra֔ţ ʼeţ-ká̇ná֖p ʼàşě֥r lĕ⁠şá̌ʼֽẇl׃s"],[24,6,"וַ⁠יֹּ֨אמֶר לַ⁠אֲנָשָׁ֜י⁠ו חָלִ֧ילָ⁠ה לִּ֣⁠י מֵֽ⁠יהוָ֗ה אִם־אֶעֱשֶׂה֩ אֶת־הַ⁠דָּבָ֨ר הַ⁠זֶּ֤ה לַֽ⁠אדֹנִ⁠י֙ לִ⁠מְשִׁ֣יחַ יְהוָ֔ה לִ⁠שְׁלֹ֥חַ יָדִ֖⁠י בּ֑⁠וֹ כִּֽי־מְשִׁ֥יחַ יְהוָ֖ה הֽוּא׃","wa⁠yò̇֨ʼmer la⁠ʼànáşá̌֜y⁠w ẖáli֧ylá⁠h li֣̇⁠y méֽ⁠yhwá֗h ʼim-ʼeʻèşêh֩ ʼeţ-ha⁠dá̇bá֨r ha⁠zė֤h laֽ⁠ʼdòni⁠y֙ li⁠mĕşǐ֣yẖa yĕhwá֔h li⁠şĕ̌lò֥ẖa yádi֖⁠y ḃ֑⁠wò kiֽ̇y-mĕşǐ֥yẖa yĕhwá֖h hֽẇʼ׃"],[24,7,"וַ⁠יְשַׁסַּ֨ע דָּוִ֤ד אֶת־אֲנָשָׁי⁠ו֙ בַּ⁠דְּבָרִ֔ים וְ⁠לֹ֥א נְתָנָ֖⁠ם לָ⁠ק֣וּם אֶל־שָׁא֑וּל וְ⁠שָׁא֛וּל קָ֥ם מֵ⁠הַ⁠מְּעָרָ֖ה וַ⁠יֵּ֥לֶךְ בַּ⁠דָּֽרֶךְ׃ס","wa⁠yĕşǎsȧ֨ʻ dá̇wi֤d ʼeţ-ʼànáşá̌y⁠w֙ bȧ⁠dĕ̇bári֔ym wĕ⁠lò֥ʼ nĕţáná֖⁠m lá⁠q֣ẇm ʼel-şá̌ʼ֑ẇl wĕ⁠şá̌ʼ֛ẇl qá֥m mé⁠ha⁠mĕ̇ʻárá֖h wa⁠yé֥̇lekĕ bȧ⁠dáֽ̇rekĕ׃s"],[24,8,"וַ⁠יָּ֨קָם דָּוִ֜ד אַחֲרֵי־כֵ֗ן וַ⁠יֵּצֵא֙ מן־ה⁠מערה וַ⁠יִּקְרָ֧א אַֽחֲרֵי־שָׁא֛וּל לֵ⁠אמֹ֖ר אֲדֹנִ֣⁠י הַ⁠מֶּ֑לֶךְ וַ⁠יַּבֵּ֤ט שָׁאוּל֙ אַֽחֲרָ֔י⁠ו וַ⁠יִּקֹּ֨ד דָּוִ֥ד אַפַּ֛יִם אַ֖רְצָ⁠ה וַ⁠יִּשְׁתָּֽחוּ׃ס","wa⁠yá̇֨qám dá̇wi֜d ʼaẖàréy-ké֗n wa⁠yé̇ẕéʼ֙ mn-h⁠mʻrh wa⁠yi̇qĕrá֧ʼ ʼaֽẖàréy-şá̌ʼ֛ẇl lé⁠ʼmò֖r ʼàdòni֣⁠y ha⁠mė֑lekĕ wa⁠yȧbé֤̇t şá̌ʼẇl֙ ʼaֽẖàrá֔y⁠w wa⁠yi̇qò̇֨d dá̇wi֥d ʼapȧ֛yim ʼa֖rĕẕá⁠h wa⁠yi̇şĕ̌ţáֽ̇ẖẇ׃s"],[24,9,"וַ⁠יֹּ֤אמֶר דָּוִד֙ לְ⁠שָׁא֔וּל לָ֧⁠מָּה תִשְׁמַ֛ע אֶת־דִּבְרֵ֥י אָדָ֖ם לֵ⁠אמֹ֑ר הִנֵּ֣ה דָוִ֔ד מְבַקֵּ֖שׁ רָעָתֶֽ⁠ךָ׃","wa⁠yò֤̇ʼmer dá̇wid֙ lĕ⁠şá̌ʼ֔ẇl lá֧⁠má̇h ţişĕ̌ma֛ʻ ʼeţ-di̇bĕré֥y ʼádá֖m lé⁠ʼmò֑r hiné֣̇h dáwi֔d mĕbaqé֖̇ş̌ ráʻáţeֽ⁠ká׃"],[24,10,"הִנֵּה֩ הַ⁠יּ֨וֹם הַ⁠זֶּ֜ה רָא֣וּ עֵינֶ֗י⁠ךָ אֵ֣ת אֲשֶׁר־נְתָנְ⁠ךָ֩ יְהוָ֨ה ׀ הַ⁠יּ֤וֹם ׀ בְּ⁠יָדִ⁠י֙ בַּ⁠מְּעָרָ֔ה וְ⁠אָמַ֥ר לַ⁠הֲרָגֲ⁠ךָ֖ וַ⁠תָּ֣חָס עָלֶ֑י⁠ךָ וָ⁠אֹמַ֗ר לֹא־אֶשְׁלַ֤ח יָדִ⁠י֙ בַּֽ⁠אדֹנִ֔⁠י כִּי־מְשִׁ֥יחַ יְהוָ֖ה הֽוּא׃","hiné̇h֩ ha⁠ẏ֨wòm ha⁠zė֜h ráʼ֣ẇ ʻéyne֗y⁠ká ʼé֣ţ ʼàşěr-nĕţánĕ⁠ká֩ yĕhwá֨h ׀ ha⁠ẏ֤wòm ׀ bĕ̇⁠yádi⁠y֙ bȧ⁠mĕ̇ʻárá֔h wĕ⁠ʼáma֥r la⁠hàrágà⁠ká֖ wa⁠ţá֣̇ẖás ʻále֑y⁠ká wá⁠ʼòma֗r lòʼ-ʼeşĕ̌la֤ẖ yádi⁠y֙ bȧֽ⁠ʼdòni֔⁠y ki̇y-mĕşǐ֥yẖa yĕhwá֖h hֽẇʼ׃"],[24,11,"וְ⁠אָבִ֣⁠י רְאֵ֔ה גַּ֗ם רְאֵ֛ה אֶת־כְּנַ֥ף מְעִילְ⁠ךָ֖ בְּ⁠יָדִ֑⁠י כִּ֡י בְּ⁠כָרְתִ⁠י֩ אֶת־כְּנַ֨ף מְעִֽילְ⁠ךָ֜ וְ⁠לֹ֣א הֲרַגְתִּ֗י⁠ךָ דַּ֤ע וּ⁠רְאֵה֙ כִּי֩ אֵ֨ין בְּ⁠יָדִ֜⁠י רָעָ֤ה וָ⁠פֶ֨שַׁע֙ וְ⁠לֹא־חָטָ֣אתִי לָ֔⁠ךְ וְ⁠אַתָּ֛ה צֹדֶ֥ה אֶת־נַפְשִׁ֖⁠י לְ⁠קַחְתָּֽ⁠הּ׃","wĕ⁠ʼábi֣⁠y rĕʼé֔h gȧ֗m rĕʼé֛h ʼeţ-kĕ̇na֥p mĕʻiylĕ⁠ká֖ bĕ̇⁠yádi֑⁠y ki̇֡y bĕ̇⁠kárĕţi⁠y֩ ʼeţ-kĕ̇na֨p mĕʻiֽylĕ⁠ká֜ wĕ⁠lò֣ʼ hàragĕţi̇֗y⁠ká dȧ֤ʻ ẇ⁠rĕʼéh֙ ki̇y֩ ʼé֨yn bĕ̇⁠yádi֜⁠y ráʻá֤h wá⁠pe֨şǎʻ֙ wĕ⁠lòʼ-ẖátá֣ʼţiy lá֔⁠kĕ wĕ⁠ʼaţá֛̇h ẕòde֥h ʼeţ-napĕşǐ֖⁠y lĕ⁠qaẖĕţáֽ̇⁠ḣ׃"],[24,12,"יִשְׁפֹּ֤ט יְהוָה֙ בֵּינִ֣⁠י וּ⁠בֵינֶ֔⁠ךָ וּ⁠נְקָמַ֥⁠נִי יְהוָ֖ה מִמֶּ֑⁠ךָּ וְ⁠יָדִ֖⁠י לֹ֥א תִֽהְיֶה־בָּֽ⁠ךְ׃","yişĕ̌pò֤̇t yĕhwáh֙ bé̇yni֣⁠y ẇ⁠béyne֔⁠ká ẇ⁠nĕqáma֥⁠niy yĕhwá֖h mimė֑⁠ká̇ wĕ⁠yádi֖⁠y lò֥ʼ ţiֽhĕyeh-báֽ̇⁠kĕ׃"],[24,13,"כַּ⁠אֲשֶׁ֣ר יֹאמַ֗ר מְשַׁל֙ הַ⁠קַּדְמֹנִ֔י מֵ⁠רְשָׁעִ֖ים יֵ֣צֵא רֶ֑שַׁע וְ⁠יָדִ֖⁠י לֹ֥א תִֽהְיֶה־בָּֽ⁠ךְ׃","kȧ⁠ʼàşě֣r yòʼma֗r mĕşǎl֙ ha⁠qȧdĕmòni֔y mé⁠rĕşá̌ʻi֖ym yé֣ẕéʼ re֑şǎʻ wĕ⁠yádi֖⁠y lò֥ʼ ţiֽhĕyeh-báֽ̇⁠kĕ׃"],[24,14,"אַחֲרֵ֨י מִ֤י יָצָא֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל אַחֲרֵ֥י מִ֖י אַתָּ֣ה רֹדֵ֑ף אַֽחֲרֵי֙ כֶּ֣לֶב מֵ֔ת אַחֲרֵ֖י פַּרְעֹ֥שׁ אֶחָֽד׃","ʼaẖàré֨y mi֤y yáẕáʼ֙ me֣lekĕ yişĕ̂ráʼé֔l ʼaẖàré֥y mi֖y ʼaţá֣̇h ròdé֑p ʼaֽẖàréy֙ kė֣leb mé֔ţ ʼaẖàré֖y pȧrĕʻò֥ş̌ ʼeẖáֽd׃"],[24,15,"וְ⁠הָיָ֤ה יְהוָה֙ לְ⁠דַיָּ֔ן וְ⁠שָׁפַ֖ט בֵּינִ֣⁠י וּ⁠בֵינֶ֑⁠ךָ וְ⁠יֵ֨רֶא֙ וְ⁠יָרֵ֣ב אֶת־רִיבִ֔⁠י וְ⁠יִשְׁפְּטֵ֖⁠נִי מִ⁠יָּדֶֽ⁠ךָ׃פ","wĕ⁠háyá֤h yĕhwáh֙ lĕ⁠dayá̇֔n wĕ⁠şá̌pa֖t bé̇yni֣⁠y ẇ⁠béyne֑⁠ká wĕ⁠yé֨reʼ֙ wĕ⁠yáré֣b ʼeţ-riybi֔⁠y wĕ⁠yişĕ̌pĕ̇té֖⁠niy mi⁠yá̇deֽ⁠ká׃p"],[24,16,"וַ⁠יְהִ֣י ׀ כְּ⁠כַלּ֣וֹת דָּוִ֗ד לְ⁠דַבֵּ֞ר אֶת־הַ⁠דְּבָרִ֤ים הָ⁠אֵ֨לֶּה֙ אֶל־שָׁא֔וּל וַ⁠יֹּ֣אמֶר שָׁא֔וּל הֲ⁠קֹלְ⁠ךָ֥ זֶ֖ה בְּנִ֣⁠י דָוִ֑ד וַ⁠יִּשָּׂ֥א שָׁא֛וּל קֹל֖⁠וֹ וַ⁠יֵּֽבְךְּ׃","wa⁠yĕhi֣y ׀ kĕ̇⁠kal֣̇wòţ dá̇wi֗d lĕ⁠dabé̇֞r ʼeţ-ha⁠dĕ̇bári֤ym há⁠ʼé֨lėh֙ ʼel-şá̌ʼ֔ẇl wa⁠yò֣̇ʼmer şá̌ʼ֔ẇl hà⁠qòlĕ⁠ká֥ ze֖h bĕ̇ni֣⁠y dáwi֑d wa⁠yi̇şá֥̇̂ʼ şá̌ʼ֛ẇl qòl֖⁠wò wa⁠yéֽ̇bĕkĕ̇׃"],[24,17,"וַ⁠יֹּ֨אמֶר֙ אֶל־דָּוִ֔ד צַדִּ֥יק אַתָּ֖ה מִמֶּ֑⁠נִּי כִּ֤י אַתָּה֙ גְּמַלְתַּ֣⁠נִי הַ⁠טּוֹבָ֔ה וַ⁠אֲנִ֖י גְּמַלְתִּ֥י⁠ךָ הָ⁠רָעָֽה׃","wa⁠yò̇֨ʼmer֙ ʼel-dá̇wi֔d ẕadi֥̇yq ʼaţá֖̇h mimė֑⁠ni̇y ki֤̇y ʼaţá̇h֙ gĕ̇malĕţȧ֣⁠niy ha⁠ṫwòbá֔h wa⁠ʼàni֖y gĕ̇malĕţi֥̇y⁠ká há⁠ráʻáֽh׃"],[24,18,"ו⁠את הִגַּ֣דְתָּ הַ⁠יּ֔וֹם אֵ֛ת אֲשֶׁר־עָשִׂ֥יתָה אִתִּ֖⁠י טוֹבָ֑ה אֵת֩ אֲשֶׁ֨ר סִגְּרַ֧⁠נִי יְהוָ֛ה בְּ⁠יָדְ⁠ךָ֖ וְ⁠לֹ֥א הֲרַגְתָּֽ⁠נִי׃","w⁠ʼţ higȧ֣dĕţá̇ ha⁠ẏ֔wòm ʼé֛ţ ʼàşěr-ʻáşî֥yţáh ʼiţi֖̇⁠y twòbá֑h ʼéţ֩ ʼàşě֨r sigĕ̇ra֧⁠niy yĕhwá֛h bĕ̇⁠yádĕ⁠ká֖ wĕ⁠lò֥ʼ hàragĕţáֽ̇⁠niy׃"],[24,19,"וְ⁠כִֽי־יִמְצָ֥א אִישׁ֙ אֶת־אֹ֣יְב֔⁠וֹ וְ⁠שִׁלְּח֖⁠וֹ בְּ⁠דֶ֣רֶךְ טוֹבָ֑ה וַֽ⁠יהוָה֙ יְשַׁלֶּמְ⁠ךָ֣ טוֹבָ֔ה תַּ֚חַת הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה אֲשֶׁ֥ר עָשִׂ֖יתָה לִֽ⁠י׃","wĕ⁠kiֽy-yimĕẕá֥ʼ ʼiyş̌֙ ʼeţ-ʼò֣yĕb֔⁠wò wĕ⁠şǐlĕ̇ẖ֖⁠wò bĕ̇⁠de֣rekĕ twòbá֑h waֽ⁠yhwáh֙ yĕşǎlėmĕ⁠ká֣ twòbá֔h ţȧ֚ẖaţ ha⁠ẏ֣wòm ha⁠zė֔h ʼàşě֥r ʻáşî֖yţáh liֽ⁠y׃"],[24,20,"וְ⁠עַתָּה֙ הִנֵּ֣ה יָדַ֔עְתִּי כִּ֥י מָלֹ֖ךְ תִּמְל֑וֹךְ וְ⁠קָ֨מָה֙ בְּ⁠יָ֣דְ⁠ךָ֔ מַמְלֶ֖כֶת יִשְׂרָאֵֽל׃","wĕ⁠ʻaţá̇h֙ hiné֣̇h yáda֔ʻĕţi̇y ki֥̇y málò֖kĕ ţi̇mĕl֑wòkĕ wĕ⁠qá֨máh֙ bĕ̇⁠yá֣dĕ⁠ká֔ mamĕle֖keţ yişĕ̂ráʼéֽl׃"],[24,21,"וְ⁠עַתָּ֗ה הִשָּׁ֤בְעָ⁠ה לִּ⁠י֙ בַּֽ⁠יהוָ֔ה אִם־תַּכְרִ֥ית אֶת־זַרְעִ֖⁠י אַֽחֲרָ֑⁠י וְ⁠אִם־תַּשְׁמִ֥יד אֶת־שְׁמִ֖⁠י מִ⁠בֵּ֥ית אָבִֽ⁠י׃","wĕ⁠ʻaţá̇֗h hişá֤̇̌bĕʻá⁠h li̇⁠y֙ bȧֽ⁠yhwá֔h ʼim-ţȧkĕri֥yţ ʼeţ-zarĕʻi֖⁠y ʼaֽẖàrá֑⁠y wĕ⁠ʼim-ţȧşĕ̌mi֥yd ʼeţ-şĕ̌mi֖⁠y mi⁠bé֥̇yţ ʼábiֽ⁠y׃"],[24,22,"וַ⁠יִּשָּׁבַ֥ע דָּוִ֖ד לְ⁠שָׁא֑וּל וַ⁠יֵּ֤לֶךְ שָׁאוּל֙ אֶל־בֵּית֔⁠וֹ וְ⁠דָוִד֙ וַֽ⁠אֲנָשָׁ֔י⁠ו עָל֖וּ עַל־הַ⁠מְּצוּדָֽה׃פ","wa⁠yi̇şá̇̌ba֥ʻ dá̇wi֖d lĕ⁠şá̌ʼ֑ẇl wa⁠yé֤̇lekĕ şá̌ʼẇl֙ ʼel-bé̇yţ֔⁠wò wĕ⁠dáwid֙ waֽ⁠ʼànáşá̌֔y⁠w ʻál֖ẇ ʻal-ha⁠mĕ̇ẕẇdáֽh׃p"],[25,1,"וַ⁠יָּ֣מָת שְׁמוּאֵ֔ל וַ⁠יִּקָּבְצ֤וּ כָל־יִשְׂרָאֵל֙ וַ⁠יִּסְפְּדוּ־ל֔⁠וֹ וַ⁠יִּקְבְּרֻ֥⁠הוּ בְּ⁠בֵית֖⁠וֹ בָּ⁠רָמָ֑ה וַ⁠יָּ֣קָם דָּוִ֔ד וַ⁠יֵּ֖רֶד אֶל־מִדְבַּ֥ר פָּארָֽן׃ס","wa⁠yá֣̇máţ şĕ̌mẇʼé֔l wa⁠yi̇qá̇bĕẕ֤ẇ kál-yişĕ̂ráʼél֙ wa⁠yi̇sĕpĕ̇dẇ-l֔⁠wò wa⁠yi̇qĕbĕ̇ru֥⁠hẇ bĕ̇⁠béyţ֖⁠wò bá̇⁠rámá֑h wa⁠yá֣̇qám dá̇wi֔d wa⁠yé֖̇red ʼel-midĕbȧ֥r pá̇ʼráֽn׃s"],[25,2,"וְ⁠אִ֨ישׁ בְּ⁠מָע֜וֹן וּ⁠מַעֲשֵׂ֣⁠הוּ בַ⁠כַּרְמֶ֗ל וְ⁠הָ⁠אִישׁ֙ גָּד֣וֹל מְאֹ֔ד וְ⁠ל֛⁠וֹ צֹ֥אן שְׁלֹֽשֶׁת־אֲלָפִ֖ים וְ⁠אֶ֣לֶף עִזִּ֑ים וַ⁠יְהִ֛י בִּ⁠גְזֹ֥ז אֶת־צֹאנ֖⁠וֹ בַּ⁠כַּרְמֶֽל׃","wĕ⁠ʼi֨yş̌ bĕ̇⁠máʻ֜wòn ẇ⁠maʻàşé֣̂⁠hẇ ba⁠kȧrĕme֗l wĕ⁠há⁠ʼiyş̌֙ gá̇d֣wòl mĕʼò֔d wĕ⁠l֛⁠wò ẕò֥ʼn şĕ̌lòֽşěţ-ʼàlápi֖ym wĕ⁠ʼe֣lep ʻizi֑̇ym wa⁠yĕhi֛y bi̇⁠gĕzò֥z ʼeţ-ẕòʼn֖⁠wò bȧ⁠kȧrĕmeֽl׃"],[25,3,"וְ⁠שֵׁ֤ם הָ⁠אִישׁ֙ נָבָ֔ל וְ⁠שֵׁ֥ם אִשְׁתּ֖⁠וֹ אֲבִגָ֑יִל וְ⁠הָ⁠אִשָּׁ֤ה טֽוֹבַת־שֶׂ֨כֶל֙ וִ֣⁠יפַת תֹּ֔אַר וְ⁠הָ⁠אִ֥ישׁ קָשֶׁ֛ה וְ⁠רַ֥ע מַעֲלָלִ֖ים וְ⁠ה֥וּא כ⁠לב⁠ו׃","wĕ⁠şé֤̌m há⁠ʼiyş̌֙ nábá֔l wĕ⁠şé֥̌m ʼişĕ̌ţ֖̇⁠wò ʼàbigá֑yil wĕ⁠há⁠ʼişá֤̇̌h tֽwòbaţ-şê֨kel֙ wi֣⁠ypaţ ţò̇֔ʼar wĕ⁠há⁠ʼi֥yş̌ qáşě֛h wĕ⁠ra֥ʻ maʻàláli֖ym wĕ⁠h֥ẇʼ k⁠lb⁠w׃"],[25,4,"וַ⁠יִּשְׁמַ֥ע דָּוִ֖ד בַּ⁠מִּדְבָּ֑ר כִּֽי־גֹזֵ֥ז נָבָ֖ל אֶת־צֹאנֽ⁠וֹ׃","wa⁠yi̇şĕ̌ma֥ʻ dá̇wi֖d bȧ⁠mi̇dĕbá֑̇r kiֽ̇y-gòzé֥z nábá֖l ʼeţ-ẕòʼnֽ⁠wò׃"],[25,5,"וַ⁠יִּשְׁלַ֥ח דָּוִ֖ד עֲשָׂרָ֣ה נְעָרִ֑ים וַ⁠יֹּ֨אמֶר דָּוִ֜ד לַ⁠נְּעָרִ֗ים עֲל֤וּ כַרְמֶ֨לָ⁠ה֙ וּ⁠בָאתֶ֣ם אֶל־נָבָ֔ל וּ⁠שְׁאֶלְתֶּם־ל֥⁠וֹ בִ⁠שְׁמִ֖⁠י לְ⁠שָׁלֽוֹם׃","wa⁠yi̇şĕ̌la֥ẖ dá̇wi֖d ʻàşá̂rá֣h nĕʻári֑ym wa⁠yò̇֨ʼmer dá̇wi֜d la⁠nĕ̇ʻári֗ym ʻàl֤ẇ karĕme֨lá⁠h֙ ẇ⁠báʼţe֣m ʼel-nábá֔l ẇ⁠şĕ̌ʼelĕţėm-l֥⁠wò bi⁠şĕ̌mi֖⁠y lĕ⁠şá̌lֽwòm׃"],[25,6,"וַ⁠אֲמַרְתֶּ֥ם כֹּ֖ה לֶ⁠חָ֑י וְ⁠אַתָּ֤ה שָׁלוֹם֙ וּ⁠בֵיתְ⁠ךָ֣ שָׁל֔וֹם וְ⁠כֹ֥ל אֲשֶׁר־לְ⁠ךָ֖ שָׁלֽוֹם׃","wa⁠ʼàmarĕţė֥m kò֖̇h le⁠ẖá֑y wĕ⁠ʼaţá֤̇h şá̌lwòm֙ ẇ⁠béyţĕ⁠ká֣ şá̌l֔wòm wĕ⁠kò֥l ʼàşěr-lĕ⁠ká֖ şá̌lֽwòm׃"],[25,7,"וְ⁠עַתָּ֣ה שָׁמַ֔עְתִּי כִּ֥י גֹזְזִ֖ים לָ֑⁠ךְ עַתָּ֗ה הָ⁠רֹעִ֤ים אֲשֶׁר־לְ⁠ךָ֙ הָי֣וּ עִמָּ֔⁠נוּ לֹ֣א הֶכְלַמְנ֗וּ⁠ם וְ⁠לֹֽא־נִפְקַ֤ד לָ⁠הֶם֙ מְא֔וּמָה כָּל־יְמֵ֖י הֱיוֹתָ֥⁠ם בַּ⁠כַּרְמֶֽל׃","wĕ⁠ʻaţá֣̇h şá̌ma֔ʻĕţi̇y ki֥̇y gòzĕzi֖ym lá֑⁠kĕ ʻaţá̇֗h há⁠ròʻi֤ym ʼàşěr-lĕ⁠ká֙ háy֣ẇ ʻimá̇֔⁠nẇ lò֣ʼ hekĕlamĕn֗ẇ⁠m wĕ⁠lòֽʼ-nipĕqa֤d lá⁠hem֙ mĕʼ֔ẇmáh ká̇l-yĕmé֖y hèywòţá֥⁠m bȧ⁠kȧrĕmeֽl׃"],[25,8,"שְׁאַ֨ל אֶת־נְעָרֶ֜י⁠ךָ וְ⁠יַגִּ֣ידוּ לָ֗⁠ךְ וְ⁠יִמְצְא֨וּ הַ⁠נְּעָרִ֥ים חֵן֙ בְּ⁠עֵינֶ֔י⁠ךָ כִּֽי־עַל־י֥וֹם ט֖וֹב בָּ֑נוּ תְּנָ⁠ה־נָּ֗א אֵת֩ אֲשֶׁ֨ר תִּמְצָ֤א יָֽדְ⁠ךָ֙ לַ⁠עֲבָדֶ֔י⁠ךָ וּ⁠לְ⁠בִנְ⁠ךָ֖ לְ⁠דָוִֽד׃","şĕ̌ʼa֨l ʼeţ-nĕʻáre֜y⁠ká wĕ⁠yagi֣̇ydẇ lá֗⁠kĕ wĕ⁠yimĕẕĕʼ֨ẇ ha⁠nĕ̇ʻári֥ym ẖén֙ bĕ̇⁠ʻéyne֔y⁠ká kiֽ̇y-ʻal-y֥wòm t֖wòb bá֑̇nẇ ţĕ̇ná⁠h-ná̇֗ʼ ʼéţ֩ ʼàşě֨r ţi̇mĕẕá֤ʼ yáֽdĕ⁠ká֙ la⁠ʻàbáde֔y⁠ká ẇ⁠lĕ⁠binĕ⁠ká֖ lĕ⁠dáwiֽd׃"],[25,9,"וַ⁠יָּבֹ֨אוּ֙ נַעֲרֵ֣י דָוִ֔ד וַ⁠יְדַבְּר֧וּ אֶל־נָבָ֛ל כְּ⁠כָל־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה בְּ⁠שֵׁ֣ם דָּוִ֑ד וַ⁠יָּנֽוּחוּ׃","wa⁠yá̇bò֨ʼẇ֙ naʻàré֣y dáwi֔d wa⁠yĕdabĕ̇r֧ẇ ʼel-nábá֛l kĕ̇⁠kál-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh bĕ̇⁠şé֣̌m dá̇wi֑d wa⁠yá̇nֽẇẖẇ׃"],[25,10,"וַ⁠יַּ֨עַן נָבָ֜ל אֶת־עַבְדֵ֤י דָוִד֙ וַ⁠יֹּ֔אמֶר מִ֥י דָוִ֖ד וּ⁠מִ֣י בֶן־יִשָׁ֑י הַ⁠יּוֹם֙ רַבּ֣וּ עֲבָדִ֔ים הַ⁠מִּתְפָּ֣רְצִ֔ים אִ֖ישׁ מִ⁠פְּנֵ֥י אֲדֹנָֽי⁠ו׃","wa⁠yȧ֨ʻan nábá֜l ʼeţ-ʻabĕdé֤y dáwid֙ wa⁠yò̇֔ʼmer mi֥y dáwi֖d ẇ⁠mi֣y ben-yişá֑̌y ha⁠ẏwòm֙ raḃ֣ẇ ʻàbádi֔ym ha⁠mi̇ţĕpá֣̇rĕẕi֔ym ʼi֖yş̌ mi⁠pĕ̇né֥y ʼàdònáֽy⁠w׃"],[25,11,"וְ⁠לָקַחְתִּ֤י אֶת־לַחְמִ⁠י֙ וְ⁠אֶת־מֵימַ֔⁠י וְ⁠אֵת֙ טִבְחָתִ֔⁠י אֲשֶׁ֥ר טָבַ֖חְתִּי לְ⁠גֹֽזְזָ֑⁠י וְ⁠נָֽתַתִּי֙ לַֽ⁠אֲנָשִׁ֔ים אֲשֶׁר֙ לֹ֣א יָדַ֔עְתִּי אֵ֥י מִ⁠זֶּ֖ה הֵֽמָּה׃","wĕ⁠láqaẖĕţi֤̇y ʼeţ-laẖĕmi⁠y֙ wĕ⁠ʼeţ-méyma֔⁠y wĕ⁠ʼéţ֙ tibĕẖáţi֔⁠y ʼàşě֥r tába֖ẖĕţi̇y lĕ⁠gòֽzĕzá֑⁠y wĕ⁠náֽţaţi̇y֙ laֽ⁠ʼànáşǐ֔ym ʼàşěr֙ lò֣ʼ yáda֔ʻĕţi̇y ʼé֥y mi⁠zė֖h héֽmá̇h׃"],[25,12,"וַ⁠יַּהַפְכ֥וּ נַעֲרֵֽי־דָוִ֖ד לְ⁠דַרְכָּ֑⁠ם וַ⁠יָּשֻׁ֨בוּ֙ וַ⁠יָּבֹ֔אוּ וַ⁠יַּגִּ֣דוּ ל֔⁠וֹ כְּ⁠כֹ֖ל הַ⁠דְּבָרִ֥ים הָ⁠אֵֽלֶּה׃","wa⁠yȧhapĕk֥ẇ naʻàréֽy-dáwi֖d lĕ⁠darĕká֑̇⁠m wa⁠yá̇şǔ֨bẇ֙ wa⁠yá̇bò֔ʼẇ wa⁠yȧgi֣̇dẇ l֔⁠wò kĕ̇⁠kò֖l ha⁠dĕ̇bári֥ym há⁠ʼéֽlėh׃"],[25,13,"וַ⁠יֹּאמֶר֩ דָּוִ֨ד לַ⁠אֲנָשָׁ֜י⁠ו חִגְר֣וּ ׀ אִ֣ישׁ אֶת־חַרְבּ֗⁠וֹ וַֽ⁠יַּחְגְּרוּ֙ אִ֣ישׁ אֶת־חַרְבּ֔⁠וֹ וַ⁠יַּחְגֹּ֥ר גַּם־דָּוִ֖ד אֶת־חַרְבּ֑⁠וֹ וַֽ⁠יַּעֲל֣וּ ׀ אַחֲרֵ֣י דָוִ֗ד כְּ⁠אַרְבַּ֤ע מֵאוֹת֙ אִ֔ישׁ וּ⁠מָאתַ֖יִם יָשְׁב֥וּ עַל־הַ⁠כֵּלִֽים׃","wa⁠yò̇ʼmer֩ dá̇wi֨d la⁠ʼànáşá̌֜y⁠w ẖigĕr֣ẇ ׀ ʼi֣yş̌ ʼeţ-ẖarĕḃ֗⁠wò waֽ⁠yȧẖĕgĕ̇rẇ֙ ʼi֣yş̌ ʼeţ-ẖarĕḃ֔⁠wò wa⁠yȧẖĕgò֥̇r gȧm-dá̇wi֖d ʼeţ-ẖarĕḃ֑⁠wò waֽ⁠yȧʻàl֣ẇ ׀ ʼaẖàré֣y dáwi֗d kĕ̇⁠ʼarĕbȧ֤ʻ méʼwòţ֙ ʼi֔yş̌ ẇ⁠máʼţa֖yim yáşĕ̌b֥ẇ ʻal-ha⁠ké̇liֽym׃"],[25,14,"וְ⁠לַ⁠אֲבִיגַ֨יִל֙ אֵ֣שֶׁת נָבָ֔ל הִגִּ֧יד נַֽעַר־אֶחָ֛ד מֵ⁠הַ⁠נְּעָרִ֖ים לֵ⁠אמֹ֑ר הִנֵּ֣ה שָׁלַח֩ דָּוִ֨ד מַלְאָכִ֧ים ׀ מֵֽ⁠הַ⁠מִּדְבָּ֛ר לְ⁠בָרֵ֥ךְ אֶת־אֲדֹנֵ֖י⁠נוּ וַ⁠יָּ֥עַט בָּ⁠הֶֽם׃","wĕ⁠la⁠ʼàbiyga֨yil֙ ʼé֣şěţ nábá֔l higi֧̇yd naֽʻar-ʼeẖá֛d mé⁠ha⁠nĕ̇ʻári֖ym lé⁠ʼmò֑r hiné֣̇h şá̌laẖ֩ dá̇wi֨d malĕʼáki֧ym ׀ méֽ⁠ha⁠mi̇dĕbá֛̇r lĕ⁠báré֥kĕ ʼeţ-ʼàdòné֖y⁠nẇ wa⁠yá֥̇ʻat bá̇⁠heֽm׃"],[25,15,"וְ⁠הָ֣⁠אֲנָשִׁ֔ים טֹבִ֥ים לָ֖⁠נוּ מְאֹ֑ד וְ⁠לֹ֤א הָכְלַ֨מְנוּ֙ וְ⁠לֹֽא־פָקַ֣דְנוּ מְא֔וּמָה כָּל־יְמֵי֙ הִתְהַלַּ֣כְנוּ אִתָּ֔⁠ם בִּֽ⁠הְיוֹתֵ֖⁠נוּ בַּ⁠שָּׂדֶֽה׃","wĕ⁠há֣⁠ʼànáşǐ֔ym tòbi֥ym lá֖⁠nẇ mĕʼò֑d wĕ⁠lò֤ʼ hákĕla֨mĕnẇ֙ wĕ⁠lòֽʼ-páqa֣dĕnẇ mĕʼ֔ẇmáh ká̇l-yĕméy֙ hiţĕhalȧ֣kĕnẇ ʼiţá̇֔⁠m biֽ̇⁠hĕywòţé֖⁠nẇ bȧ⁠şá̇̂deֽh׃"],[25,16,"חוֹמָה֙ הָי֣וּ עָלֵ֔י⁠נוּ גַּם־לַ֖יְלָה גַּם־יוֹמָ֑ם כָּל־יְמֵ֛י הֱיוֹתֵ֥⁠נוּ עִמָּ֖⁠ם רֹעִ֥ים הַ⁠צֹּֽאן׃","ẖwòmáh֙ háy֣ẇ ʻálé֔y⁠nẇ gȧm-la֖yĕláh gȧm-ywòmá֑m ká̇l-yĕmé֛y hèywòţé֥⁠nẇ ʻimá֖̇⁠m ròʻi֥ym ha⁠ẕòֽ̇ʼn׃"],[25,17,"וְ⁠עַתָּ֗ה דְּעִ֤י וּ⁠רְאִי֙ מַֽה־תַּעֲשִׂ֔י כִּֽי־כָלְתָ֧ה הָ⁠רָעָ֛ה אֶל־אֲדֹנֵ֖י⁠נוּ וְ⁠עַ֣ל כָּל־בֵּית֑⁠וֹ וְ⁠הוּא֙ בֶּן־בְּלִיַּ֔עַל מִ⁠דַּבֵּ֖ר אֵלָֽי⁠ו׃","wĕ⁠ʻaţá̇֗h dĕ̇ʻi֤y ẇ⁠rĕʼiy֙ maֽh-ţȧʻàşî֔y kiֽ̇y-kálĕţá֧h há⁠ráʻá֛h ʼel-ʼàdòné֖y⁠nẇ wĕ⁠ʻa֣l ká̇l-bé̇yţ֑⁠wò wĕ⁠hẇʼ֙ bėn-bĕ̇liyȧ֔ʻal mi⁠dȧbé֖̇r ʼéláֽy⁠w׃"],[25,18,"וַ⁠תְּמַהֵ֣ר אבוגיל וַ⁠תִּקַּח֩ מָאתַ֨יִם לֶ֜חֶם וּ⁠שְׁנַ֣יִם נִבְלֵי־יַ֗יִן וְ⁠חָמֵ֨שׁ צֹ֤אן עשוות וְ⁠חָמֵ֤שׁ סְאִים֙ קָלִ֔י וּ⁠מֵאָ֥ה צִמֻּקִ֖ים וּ⁠מָאתַ֣יִם דְּבֵלִ֑ים וַ⁠תָּ֖שֶׂם עַל־הַ⁠חֲמֹרִֽים׃","wa⁠ţĕ̇mahé֣r ʼbwgyl wa⁠ţi̇qȧẖ֩ máʼţa֨yim le֜ẖem ẇ⁠şĕ̌na֣yim nibĕléy-ya֗yin wĕ⁠ẖámé֨ş̌ ẕò֤ʼn ʻşwwţ wĕ⁠ẖámé֤ş̌ sĕʼiym֙ qáli֔y ẇ⁠méʼá֥h ẕimu̇qi֖ym ẇ⁠máʼţa֣yim dĕ̇béli֑ym wa⁠ţá֖̇şêm ʻal-ha⁠ẖàmòriֽym׃"],[25,19,"וַ⁠תֹּ֤אמֶר לִ⁠נְעָרֶ֨י⁠הָ֙ עִבְר֣וּ לְ⁠פָנַ֔⁠י הִנְ⁠נִ֖י אַחֲרֵי⁠כֶ֣ם בָּאָ֑ה וּ⁠לְ⁠אִישָׁ֥⁠הּ נָבָ֖ל לֹ֥א הִגִּֽידָה׃","wa⁠ţò֤̇ʼmer li⁠nĕʻáre֨y⁠há֙ ʻibĕr֣ẇ lĕ⁠pána֔⁠y hinĕ⁠ni֖y ʼaẖàréy⁠ke֣m bá̇ʼá֑h ẇ⁠lĕ⁠ʼiyşá֥̌⁠ḣ nábá֖l lò֥ʼ higiֽ̇ydáh׃"],[25,20,"וְ⁠הָיָ֞ה הִ֣יא ׀ רֹכֶ֣בֶת עַֽל־הַ⁠חֲמ֗וֹר וְ⁠יֹרֶ֨דֶת֙ בְּ⁠סֵ֣תֶר הָ⁠הָ֔ר וְ⁠הִנֵּ֤ה דָוִד֙ וַ⁠אֲנָשָׁ֔י⁠ו יֹרְדִ֖ים לִ⁠קְרָאתָ֑⁠הּ וַ⁠תִּפְגֹּ֖שׁ אֹתָֽ⁠ם׃","wĕ⁠háyá֞h hi֣yʼ ׀ ròke֣beţ ʻaֽl-ha⁠ẖàm֗wòr wĕ⁠yòre֨deţ֙ bĕ̇⁠sé֣ţer há⁠há֔r wĕ⁠hiné֤̇h dáwid֙ wa⁠ʼànáşá̌֔y⁠w yòrĕdi֖ym li⁠qĕráʼţá֑⁠ḣ wa⁠ţi̇pĕgò֖̇ş̌ ʼòţáֽ⁠m׃"],[25,21,"וְ⁠דָוִ֣ד אָמַ֗ר אַךְ֩ לַ⁠שֶּׁ֨קֶר שָׁמַ֜רְתִּי אֶֽת־כָּל־אֲשֶׁ֤ר לָ⁠זֶה֙ בַּ⁠מִּדְבָּ֔ר וְ⁠לֹא־נִפְקַ֥ד מִ⁠כָּל־אֲשֶׁר־ל֖⁠וֹ מְא֑וּמָה וַ⁠יָּֽשֶׁב־לִ֥⁠י רָעָ֖ה תַּ֥חַת טוֹבָֽה׃","wĕ⁠dáwi֣d ʼáma֗r ʼakĕ֩ la⁠şė̌֨qer şá̌ma֜rĕţi̇y ʼeֽţ-ká̇l-ʼàşě֤r lá⁠zeh֙ bȧ⁠mi̇dĕbá̇֔r wĕ⁠lòʼ-nipĕqa֥d mi⁠ká̇l-ʼàşěr-l֖⁠wò mĕʼ֑ẇmáh wa⁠yáֽ̇şěb-li֥⁠y ráʻá֖h ţȧ֥ẖaţ twòbáֽh׃"],[25,22,"כֹּה־יַעֲשֶׂ֧ה אֱלֹהִ֛ים לְ⁠אֹיְבֵ֥י דָוִ֖ד וְ⁠כֹ֣ה יֹסִ֑יף אִם־אַשְׁאִ֧יר מִ⁠כָּל־אֲשֶׁר־ל֛⁠וֹ עַד־הַ⁠בֹּ֖קֶר מַשְׁתִּ֥ין בְּ⁠קִֽיר׃","kò̇h-yaʻàşê֧h ʼèlòhi֛ym lĕ⁠ʼòyĕbé֥y dáwi֖d wĕ⁠kò֣h yòsi֑yp ʼim-ʼaşĕ̌ʼi֧yr mi⁠ká̇l-ʼàşěr-l֛⁠wò ʻad-ha⁠bò֖̇qer maşĕ̌ţi֥̇yn bĕ̇⁠qiֽyr׃"],[25,23,"וַ⁠תֵּ֤רֶא אֲבִיגַ֨יִל֙ אֶת־דָּוִ֔ד וַ⁠תְּמַהֵ֕ר וַ⁠תֵּ֖רֶד מֵ⁠עַ֣ל הַ⁠חֲמ֑וֹר וַ⁠תִּפֹּ֞ל לְ⁠אַפֵּ֤י דָוִד֙ עַל־פָּנֶ֔י⁠הָ וַ⁠תִּשְׁתַּ֖חוּ אָֽרֶץ׃","wa⁠ţé֤̇reʼ ʼàbiyga֨yil֙ ʼeţ-dá̇wi֔d wa⁠ţĕ̇mahé֕r wa⁠ţé֖̇red mé⁠ʻa֣l ha⁠ẖàm֑wòr wa⁠ţi̇pò̇֞l lĕ⁠ʼapé֤̇y dáwid֙ ʻal-pá̇ne֔y⁠há wa⁠ţi̇şĕ̌ţȧ֖ẖẇ ʼáֽreẕ׃"],[25,24,"וַ⁠תִּפֹּל֙ עַל־רַגְלָ֔י⁠ו וַ⁠תֹּ֕אמֶר בִּ⁠י־אֲנִ֥י אֲדֹנִ֖⁠י הֶֽ⁠עָוֺ֑ן וּֽ⁠תְדַבֶּר־נָ֤א אֲמָֽתְ⁠ךָ֙ בְּ⁠אָזְנֶ֔י⁠ךָ וּ⁠שְׁמַ֕ע אֵ֖ת דִּבְרֵ֥י אֲמָתֶֽ⁠ךָ׃","wa⁠ţi̇pò̇l֙ ʻal-ragĕlá֔y⁠w wa⁠ţò̇֕ʼmer bi̇⁠y-ʼàni֥y ʼàdòni֖⁠y heֽ⁠ʻáwֺ֑n ẇֽ⁠ţĕdabėr-ná֤ʼ ʼàmáֽţĕ⁠ká֙ bĕ̇⁠ʼázĕne֔y⁠ká ẇ⁠şĕ̌ma֕ʻ ʼé֖ţ di̇bĕré֥y ʼàmáţeֽ⁠ká׃"],[25,25,"אַל־נָ֣א יָשִׂ֣ים אֲדֹנִ֣⁠י ׀ אֶת־לִבּ֡⁠וֹ אֶל־אִישׁ֩ הַ⁠בְּלִיַּ֨עַל הַ⁠זֶּ֜ה עַל־נָבָ֗ל כִּ֤י כִ⁠שְׁמ⁠וֹ֙ כֶּן־ה֔וּא נָבָ֣ל שְׁמ֔⁠וֹ וּ⁠נְבָלָ֖ה עִמּ֑⁠וֹ וַֽ⁠אֲנִי֙ אֲמָ֣תְ⁠ךָ֔ לֹ֥א רָאִ֛יתִי אֶת־נַעֲרֵ֥י אֲדֹנִ֖⁠י אֲשֶׁ֥ר שָׁלָֽחְתָּ׃","ʼal-ná֣ʼ yáşî֣ym ʼàdòni֣⁠y ׀ ʼeţ-liḃ֡⁠wò ʼel-ʼiyş̌֩ ha⁠bĕ̇liyȧ֨ʻal ha⁠zė֜h ʻal-nábá֗l ki֤̇y ki⁠şĕ̌m⁠wò֙ kėn-h֔ẇʼ nábá֣l şĕ̌m֔⁠wò ẇ⁠nĕbálá֖h ʻiṁ֑⁠wò wֽa⁠ʼàniy֙ ʼàmá֣ţĕ⁠ká֔ lò֥ʼ ráʼi֛yţiy ʼeţ-naʻàré֥y ʼàdòni֖⁠y ʼàşě֥r şá̌láֽẖĕţá̇׃"],[25,26,"וְ⁠עַתָּ֣ה אֲדֹנִ֗⁠י חַי־יְהוָ֤ה וְ⁠חֵֽי־נַפְשְׁ⁠ךָ֙ אֲשֶׁ֨ר מְנָעֲ⁠ךָ֤ יְהוָה֙ מִ⁠בּ֣וֹא בְ⁠דָמִ֔ים וְ⁠הוֹשֵׁ֥עַ יָדְ⁠ךָ֖ לָ֑⁠ךְ וְ⁠עַתָּ֗ה יִֽהְי֤וּ כְ⁠נָבָל֙ אֹיְבֶ֔י⁠ךָ וְ⁠הַֽ⁠מְבַקְשִׁ֥ים אֶל־אֲדֹנִ֖⁠י רָעָֽה׃","wĕ⁠ʻaţá֣̇h ʼàdòni֗⁠y ẖay-yĕhwá֤h wĕ⁠ẖéֽy-napĕşĕ̌⁠ká֙ ʼàşě֨r mĕnáʻà⁠ká֤ yĕhwáh֙ mi⁠ḃ֣wòʼ bĕ⁠dámi֔ym wĕ⁠hwòşé֥̌ʻa yádĕ⁠ká֖ lá֑⁠kĕ wĕ⁠ʻaţá̇֗h yiֽhĕy֤ẇ kĕ⁠nábál֙ ʼòyĕbe֔y⁠ká wĕ⁠haֽ⁠mĕbaqĕşǐ֥ym ʼel-ʼàdòni֖⁠y ráʻáֽh׃"],[25,27,"וְ⁠עַתָּה֙ הַ⁠בְּרָכָ֣ה הַ⁠זֹּ֔את אֲשֶׁר־הֵבִ֥יא שִׁפְחָתְ⁠ךָ֖ לַֽ⁠אדֹנִ֑⁠י וְ⁠נִתְּנָה֙ לַ⁠נְּעָרִ֔ים הַ⁠מִּֽתְהַלְּכִ֖ים בְּ⁠רַגְלֵ֥י אֲדֹנִֽ⁠י׃","wĕ⁠ʻaţá̇h֙ ha⁠bĕ̇ráká֣h ha⁠zò̇֔ʼţ ʼàşěr-hébi֥yʼ şǐpĕẖáţĕ⁠ká֖ laֽ⁠ʼdòni֑⁠y wĕ⁠niţĕ̇náh֙ la⁠nĕ̇ʻári֔ym ha⁠miֽ̇ţĕhalĕ̇ki֖ym bĕ̇⁠ragĕlé֥y ʼàdòniֽ⁠y׃"],[25,28,"שָׂ֥א נָ֖א לְ⁠פֶ֣שַׁע אֲמָתֶ֑⁠ךָ כִּ֣י עָשֹֽׂה־יַעֲשֶׂה֩ יְהוָ֨ה לַֽ⁠אדֹנִ֜⁠י בַּ֣יִת נֶאֱמָ֗ן כִּי־מִלְחֲמ֤וֹת יְהוָה֙ אֲדֹנִ֣⁠י נִלְחָ֔ם וְ⁠רָעָ֛ה לֹא־תִמָּצֵ֥א בְ⁠ךָ֖ מִ⁠יָּמֶֽי⁠ךָ׃","şá֥̂ʼ ná֖ʼ lĕ⁠pe֣şǎʻ ʼàmáţe֑⁠ká ki֣̇y ʻáşòֽ̂h-yaʻàşêh֩ yĕhwá֨h laֽ⁠ʼdòni֜⁠y bȧ֣yiţ neʼèmá֗n ki̇y-milĕẖàm֤wòţ yĕhwáh֙ ʼàdòni֣⁠y nilĕẖá֔m wĕ⁠ráʻá֛h lòʼ-ţimá̇ẕé֥ʼ bĕ⁠ká֖ mi⁠yá̇meֽy⁠ká׃"],[25,29,"וַ⁠יָּ֤קָם אָדָם֙ לִ⁠רְדָפְ⁠ךָ֔ וּ⁠לְ⁠בַקֵּ֖שׁ אֶת־נַפְשֶׁ֑⁠ךָ וְֽ⁠הָיְתָה֩ נֶ֨פֶשׁ אֲדֹנִ֜⁠י צְרוּרָ֣ה ׀ בִּ⁠צְר֣וֹר הַ⁠חַיִּ֗ים אֵ֚ת יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠אֵ֨ת נֶ֤פֶשׁ אֹיְבֶ֨י⁠ךָ֙ יְקַלְּעֶ֔⁠נָּה בְּ⁠ת֖וֹךְ כַּ֥ף הַ⁠קָּֽלַע׃","wa⁠yá֤̇qám ʼádám֙ li⁠rĕdápĕ⁠ká֔ ẇ⁠lĕ⁠baqé֖̇ş̌ ʼeţ-napĕşě֑⁠ká wĕֽ⁠háyĕţáh֩ ne֨peş̌ ʼàdòni֜⁠y ẕĕrẇrá֣h ׀ bi̇⁠ẕĕr֣wòr ha⁠ẖayi̇֗ym ʼé֚ţ yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠ʼé֨ţ ne֤peş̌ ʼòyĕbe֨y⁠ká֙ yĕqalĕ̇ʻe֔⁠ná̇h bĕ̇⁠ţ֖wòkĕ kȧ֥p ha⁠qáֽ̇laʻ׃"],[25,30,"וְ⁠הָיָ֗ה כִּֽי־יַעֲשֶׂ֤ה יְהוָה֙ לַֽ⁠אדֹנִ֔⁠י כְּ⁠כֹ֛ל אֲשֶׁר־דִּבֶּ֥ר אֶת־הַ⁠טּוֹבָ֖ה עָלֶ֑י⁠ךָ וְ⁠צִוְּ⁠ךָ֥ לְ⁠נָגִ֖יד עַל־יִשְׂרָאֵֽל׃","wĕ⁠háyá֗h kiֽ̇y-yaʻàşê֤h yĕhwáh֙ laֽ⁠ʼdòni֔⁠y kĕ̇⁠kò֛l ʼàşěr-di̇bė֥r ʼeţ-ha⁠ṫwòbá֖h ʻále֑y⁠ká wĕ⁠ẕiwĕ̇⁠ká֥ lĕ⁠nági֖yd ʻal-yişĕ̂ráʼéֽl׃"],[25,31,"וְ⁠לֹ֣א תִהְיֶ֣ה זֹ֣את ׀ לְ⁠ךָ֡ לְ⁠פוּקָה֩ וּ⁠לְ⁠מִכְשׁ֨וֹל לֵ֜ב לַ⁠אדֹנִ֗⁠י וְ⁠לִ⁠שְׁפָּךְ־דָּם֙ חִנָּ֔ם וּ⁠לְ⁠הוֹשִׁ֥יעַ אֲדֹנִ֖⁠י ל֑⁠וֹ וְ⁠הֵיטִ֤ב יְהוָה֙ לַֽ⁠אדֹנִ֔⁠י וְ⁠זָכַרְתָּ֖ אֶת־אֲמָתֶֽ⁠ךָ׃ס","wĕ⁠lò֣ʼ ţihĕye֣h zò֣ʼţ ׀ lĕ⁠ká֡ lĕ⁠pẇqáh֩ ẇ⁠lĕ⁠mikĕş̌֨wòl lé֜b la⁠ʼdòni֗⁠y wĕ⁠li⁠şĕ̌pá̇kĕ-dá̇m֙ ẖiná̇֔m ẇ⁠lĕ⁠hwòşǐ֥yʻa ʼàdòni֖⁠y l֑⁠wò wĕ⁠héyti֤b yĕhwáh֙ laֽ⁠ʼdòni֔⁠y wĕ⁠zákarĕţá֖̇ ʼeţ-ʼàmáţeֽ⁠ká׃s"],[25,32,"וַ⁠יֹּ֥אמֶר דָּוִ֖ד לַ⁠אֲבִיגַ֑ל בָּר֤וּךְ יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֧ר שְׁלָחֵ֛⁠ךְ הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה לִ⁠קְרָאתִֽ⁠י׃","wa⁠yò֥̇ʼmer dá̇wi֖d la⁠ʼàbiyga֑l bá̇r֤ẇkĕ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşě֧r şĕ̌láẖé֛⁠kĕ ha⁠ẏ֥wòm ha⁠zė֖h li⁠qĕráʼţiֽ⁠y׃"],[25,33,"וּ⁠בָר֥וּךְ טַעְמֵ֖⁠ךְ וּ⁠בְרוּכָ֣ה אָ֑תְּ אֲשֶׁ֨ר כְּלִתִ֜⁠נִי הַ⁠יּ֤וֹם הַ⁠זֶּה֙ מִ⁠בּ֣וֹא בְ⁠דָמִ֔ים וְ⁠הֹשֵׁ֥עַ יָדִ֖⁠י לִֽ⁠י׃","ẇ⁠bár֥ẇkĕ taʻĕmé֖⁠kĕ ẇ⁠bĕrẇká֣h ʼá֑ţĕ̇ ʼàşě֨r kĕ̇liţi֜⁠niy ha⁠ẏ֤wòm ha⁠zėh֙ mi⁠ḃ֣wòʼ bĕ⁠dámi֔ym wĕ⁠hòşé֥̌ʻa yádi֖⁠y liֽ⁠y׃"],[25,34,"וְ⁠אוּלָ֗ם חַי־יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֣ר מְנָעַ֔⁠נִי מֵ⁠הָרַ֖ע אֹתָ֑⁠ךְ כִּ֣י ׀ לוּלֵ֣י מִהַ֗רְתְּ ו⁠תבאתי לִ⁠קְרָאתִ֔⁠י כִּ֣י אִם־נוֹתַ֧ר לְ⁠נָבָ֛ל עַד־א֥וֹר הַ⁠בֹּ֖קֶר מַשְׁתִּ֥ין בְּ⁠קִֽיר׃","wĕ⁠ʼẇlá֗m ẖay-yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşě֣r mĕnáʻa֔⁠niy mé⁠hára֖ʻ ʼòţá֑⁠kĕ ki֣̇y ׀ lẇlé֣y miha֗rĕţĕ̇ w⁠ţbʼţy li⁠qĕráʼţi֔⁠y ki֣̇y ʼim-nwòţa֧r lĕ⁠nábá֛l ʻad-ʼ֥wòr ha⁠bò֖̇qer maşĕ̌ţi֥̇yn bĕ̇⁠qiֽyr׃"],[25,35,"וַ⁠יִּקַּ֤ח דָּוִד֙ מִ⁠יָּדָ֔⁠הּ אֵ֥ת אֲשֶׁר־הֵבִ֖יאָה ל֑⁠וֹ וְ⁠לָ֣⁠הּ אָמַ֗ר עֲלִ֤י לְ⁠שָׁלוֹם֙ לְ⁠בֵיתֵ֔⁠ךְ רְאִי֙ שָׁמַ֣עְתִּי בְ⁠קוֹלֵ֔⁠ךְ וָ⁠אֶשָּׂ֖א פָּנָֽיִ⁠ךְ׃","wa⁠yi̇qȧ֤ẖ dá̇wid֙ mi⁠yá̇dá֔⁠ḣ ʼé֥ţ ʼàşěr-hébi֖yʼáh l֑⁠wò wĕ⁠lá֣⁠ḣ ʼáma֗r ʻàli֤y lĕ⁠şá̌lwòm֙ lĕ⁠béyţé֔⁠kĕ rĕʼiy֙ şá̌ma֣ʻĕţi̇y bĕ⁠qwòlé֔⁠kĕ wá⁠ʼeşá֖̇̂ʼ pá̇náֽyi⁠kĕ׃"],[25,36,"וַ⁠תָּבֹ֣א אֲבִיגַ֣יִל ׀ אֶל־נָבָ֡ל וְ⁠הִנֵּה־ל⁠וֹ֩ מִשְׁתֶּ֨ה בְּ⁠בֵית֜⁠וֹ כְּ⁠מִשְׁתֵּ֣ה הַ⁠מֶּ֗לֶךְ וְ⁠לֵ֤ב נָבָל֙ ט֣וֹב עָלָ֔י⁠ו וְ⁠ה֥וּא שִׁכֹּ֖ר עַד־מְאֹ֑ד וְ⁠לֹֽא־הִגִּ֣ידָה לּ֗⁠וֹ דָּבָ֥ר קָטֹ֛ן וְ⁠גָד֖וֹל עַד־א֥וֹר הַ⁠בֹּֽקֶר׃","wa⁠ţá̇bò֣ʼ ʼàbiyga֣yil ׀ ʼel-nábá֡l wĕ⁠hiné̇h-l⁠wò֩ mişĕ̌ţė֨h bĕ̇⁠béyţ֜⁠wò kĕ̇⁠mişĕ̌ţé֣̇h ha⁠mė֗lekĕ wĕ⁠lé֤b nábál֙ t֣wòb ʻálá֔y⁠w wĕ⁠h֥ẇʼ şǐkò֖̇r ʻad-mĕʼò֑d wĕ⁠lòֽʼ-higi֣̇ydáh l̇֗⁠wò dá̇bá֥r qátò֛n wĕ⁠gád֖wòl ʻad-ʼ֥wòr ha⁠bòֽ̇qer׃"],[25,37,"וַ⁠יְהִ֣י בַ⁠בֹּ֗קֶר בְּ⁠צֵ֤את הַ⁠יַּ֨יִן֙ מִ⁠נָּבָ֔ל וַ⁠תַּגֶּד־ל֣⁠וֹ אִשְׁתּ֔⁠וֹ אֶת־הַ⁠דְּבָרִ֖ים הָ⁠אֵ֑לֶּה וַ⁠יָּ֤מָת לִבּ⁠וֹ֙ בְּ⁠קִרְבּ֔⁠וֹ וְ⁠ה֖וּא הָיָ֥ה לְ⁠אָֽבֶן׃","wa⁠yĕhi֣y ba⁠bò̇֗qer bĕ̇⁠ẕé֤ʼţ ha⁠yȧ֨yin֙ mi⁠ná̇bá֔l wa⁠ţȧgėd-l֣⁠wò ʼişĕ̌ţ̇֔⁠wò ʼeţ-ha⁠dĕ̇bári֖ym há⁠ʼé֑lėh wa⁠yá֤̇máţ liḃ⁠wò֙ bĕ̇⁠qirĕḃ֔⁠wò wĕ⁠h֖ẇʼ háyá֥h lĕ⁠ʼáֽben׃"],[25,38,"וַ⁠יְהִ֖י כַּ⁠עֲשֶׂ֣רֶת הַ⁠יָּמִ֑ים וַ⁠יִּגֹּ֧ף יְהוָ֛ה אֶת־נָבָ֖ל וַ⁠יָּמֹֽת׃","wa⁠yĕhi֖y kȧ⁠ʻàşê֣reţ ha⁠yá̇mi֑ym wa⁠yi̇gò֧̇p yĕhwá֛h ʼeţ-nábá֖l wa⁠yá̇mòֽţ׃"],[25,39,"וַ⁠יִּשְׁמַ֣ע דָּוִד֮ כִּ֣י מֵ֣ת נָבָל֒ וַ⁠יֹּ֡אמֶר בָּר֣וּךְ יְהוָ֡ה אֲשֶׁ֣ר רָב֩ אֶת־רִ֨יב חֶרְפָּתִ֜⁠י מִ⁠יַּ֣ד נָבָ֗ל וְ⁠אֶת־עַבְדּ⁠וֹ֙ חָשַׂ֣ךְ מֵֽ⁠רָעָ֔ה וְ⁠אֵת֙ רָעַ֣ת נָבָ֔ל הֵשִׁ֥יב יְהוָ֖ה בְּ⁠רֹאשׁ֑⁠וֹ וַ⁠יִּשְׁלַ֤ח דָּוִד֙ וַ⁠יְדַבֵּ֣ר בַּ⁠אֲבִיגַ֔יִל לְ⁠קַחְתָּ֥⁠הּ ל֖⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠yi̇şĕ̌ma֣ʻ dá̇wid֮ ki֣̇y mé֣ţ nábál֒ wa⁠yò̇֡ʼmer bá̇r֣ẇkĕ yĕhwá֡h ʼàşě֣r ráb֩ ʼeţ-ri֨yb ẖerĕpá̇ţi֜⁠y mi⁠yȧ֣d nábá֗l wĕ⁠ʼeţ-ʻabĕḋ⁠wò֙ ẖáşâ֣kĕ méֽ⁠ráʻá֔h wĕ⁠ʼéţ֙ ráʻa֣ţ nábá֔l héşǐ֥yb yĕhwá֖h bĕ̇⁠ròʼş֑̌⁠wò wa⁠yi̇şĕ̌la֤ẖ dá̇wid֙ wa⁠yĕdabé֣̇r bȧ⁠ʼàbiyga֔yil lĕ⁠qaẖĕţá֥̇⁠ḣ l֖⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[25,40,"וַ⁠יָּבֹ֜אוּ עַבְדֵ֥י דָוִ֛ד אֶל־אֲבִיגַ֖יִל הַ⁠כַּרְמֶ֑לָ⁠ה וַ⁠יְדַבְּר֤וּ אֵלֶ֨י⁠הָ֙ לֵ⁠אמֹ֔ר דָּוִד֙ שְׁלָחָ֣⁠נוּ אֵלַ֔יִ⁠ךְ לְ⁠קַחְתֵּ֥⁠ךְ ל֖⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠yá̇bò֜ʼẇ ʻabĕdé֥y dáwi֛d ʼel-ʼàbiyga֖yil ha⁠kȧrĕme֑lá⁠h wa⁠yĕdabĕ̇r֤ẇ ʼéle֨y⁠há֙ lé⁠ʼmò֔r dá̇wid֙ şĕ̌láẖá֣⁠nẇ ʼéla֔yi⁠kĕ lĕ⁠qaẖĕţé֥̇⁠kĕ l֖⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[25,41,"וַ⁠תָּ֕קָם וַ⁠תִּשְׁתַּ֥חוּ אַפַּ֖יִם אָ֑רְצָ⁠ה וַ⁠תֹּ֗אמֶר הִנֵּ֤ה אֲמָֽתְ⁠ךָ֙ לְ⁠שִׁפְחָ֔ה לִ⁠רְחֹ֕ץ רַגְלֵ֖י עַבְדֵ֥י אֲדֹנִֽ⁠י׃","wa⁠ţá̇֕qám wa⁠ţi̇şĕ̌ţȧ֥ẖẇ ʼapȧ֖yim ʼá֑rĕẕá⁠h wa⁠ţò̇֗ʼmer hiné֤̇h ʼàmáֽţĕ⁠ká֙ lĕ⁠şǐpĕẖá֔h li⁠rĕẖò֕ẕ ragĕlé֖y ʻabĕdé֥y ʼàdòniֽ⁠y׃"],[25,42,"וַ⁠תְּמַהֵ֞ר וַ⁠תָּ֣קָם אֲבִיגַ֗יִל וַ⁠תִּרְכַּב֙ עַֽל־הַ⁠חֲמ֔וֹר וְ⁠חָמֵשׁ֙ נַעֲרֹתֶ֔י⁠הָ הַ⁠הֹלְכ֖וֹת לְ⁠רַגְלָ֑⁠הּ וַ⁠תֵּ֗לֶךְ אַֽחֲרֵי֙ מַלְאֲכֵ֣י דָוִ֔ד וַ⁠תְּהִי־ל֖⁠וֹ לְ⁠אִשָּֽׁה׃","wa⁠ţĕ̇mahé֞r wa⁠ţá֣̇qám ʼàbiyga֗yil wa⁠ţi̇rĕkȧb֙ ʻaֽl-ha⁠ẖàm֔wòr wĕ⁠ẖáméş̌֙ naʻàròţe֔y⁠há ha⁠hòlĕk֖wòţ lĕ⁠ragĕlá֑⁠ḣ wa⁠ţé̇֗lekĕ ʼaֽẖàréy֙ malĕʼàké֣y dáwi֔d wa⁠ţĕ̇hiy-l֖⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[25,43,"וְ⁠אֶת־אֲחִינֹ֛עַם לָקַ֥ח דָּוִ֖ד מִֽ⁠יִּזְרְעֶ֑אל וַ⁠תִּהְיֶ֛יןָ גַּֽם־שְׁתֵּי⁠הֶ֥ן ל֖⁠וֹ לְ⁠נָשִֽׁים׃ס","wĕ⁠ʼeţ-ʼàẖiynò֛ʻam láqa֥ẖ dá̇wi֖d miֽ⁠yi̇zĕrĕʻe֑ʼl wa⁠ţi̇hĕye֛yná gȧֽm-şĕ̌ţé̇y⁠he֥n l֖⁠wò lĕ⁠náşǐֽym׃s"],[25,44,"וְ⁠שָׁא֗וּל נָתַ֛ן אֶת־מִיכַ֥ל בִּתּ֖⁠וֹ אֵ֣שֶׁת דָּוִ֑ד לְ⁠פַלְטִ֥י בֶן־לַ֖יִשׁ אֲשֶׁ֥ר מִ⁠גַּלִּֽים׃","wĕ⁠şá̌ʼ֗ẇl náţa֛n ʼeţ-miyka֥l bi̇ţ֖̇⁠wò ʼé֣şěţ dá̇wi֑d lĕ⁠palĕti֥y ben-la֖yiş̌ ʼàşě֥r mi⁠gȧliֽ̇ym׃"],[26,1,"וַ⁠יָּבֹ֤אוּ הַ⁠זִּפִים֙ אֶל־שָׁא֔וּל הַ⁠גִּבְעָ֖תָ⁠ה לֵ⁠אמֹ֑ר הֲ⁠ל֨וֹא דָוִ֤ד מִסְתַּתֵּר֙ בְּ⁠גִבְעַ֣ת הַ⁠חֲכִילָ֔ה עַ֖ל פְּנֵ֥י הַ⁠יְשִׁימֹֽן׃","wa⁠yá̇bò֤ʼẇ ha⁠zi̇piym֙ ʼel-şá̌ʼ֔ẇl ha⁠gi̇bĕʻá֖ţá⁠h lé⁠ʼmò֑r hà⁠l֨wòʼ dáwi֤d misĕţȧţé̇r֙ bĕ̇⁠gibĕʻa֣ţ ha⁠ẖàkiylá֔h ʻa֖l pĕ̇né֥y ha⁠yĕşǐymòֽn׃"],[26,2,"וַ⁠יָּ֣קָם שָׁא֗וּל וַ⁠יֵּ֨רֶד֙ אֶל־מִדְבַּר־זִ֔יף וְ⁠אִתּ֛⁠וֹ שְׁלֹֽשֶׁת־אֲלָפִ֥ים אִ֖ישׁ בְּחוּרֵ֣י יִשְׂרָאֵ֑ל לְ⁠בַקֵּ֥שׁ אֶת־דָּוִ֖ד בְּ⁠מִדְבַּר־זִֽיף׃","wa⁠yá֣̇qám şá̌ʼ֗ẇl wa⁠yé̇֨red֙ ʼel-midĕbȧr-zi֔yp wĕ⁠ʼiţ֛̇⁠wò şĕ̌lòֽşěţ-ʼàlápi֥ym ʼi֖yş̌ bĕ̇ẖẇré֣y yişĕ̂ráʼé֑l lĕ⁠baqé֥̇ş̌ ʼeţ-dá̇wi֖d bĕ̇⁠midĕbȧr-ziֽyp׃"],[26,3,"וַ⁠יִּ֨חַן שָׁא֜וּל בְּ⁠גִבְעַ֣ת הַ⁠חֲכִילָ֗ה אֲשֶׁ֛ר עַל־פְּנֵ֥י הַ⁠יְשִׁימֹ֖ן עַל־הַ⁠דָּ֑רֶךְ וְ⁠דָוִד֙ יֹשֵׁ֣ב בַּ⁠מִּדְבָּ֔ר וַ⁠יַּ֕רְא כִּ֣י בָ֥א שָׁא֛וּל אַחֲרָ֖י⁠ו הַ⁠מִּדְבָּֽרָ⁠ה׃","wa⁠yi̇֨ẖan şá̌ʼ֜ẇl bĕ̇⁠gibĕʻa֣ţ ha⁠ẖàkiylá֗h ʼàşě֛r ʻal-pĕ̇né֥y ha⁠yĕşǐymò֖n ʻal-ha⁠dá֑̇rekĕ wĕ⁠dáwid֙ yòşé֣̌b bȧ⁠mi̇dĕbá̇֔r wa⁠yȧ֕rĕʼ ki֣̇y bá֥ʼ şá̌ʼ֛ẇl ʼaẖàrá֖y⁠w ha⁠mi̇dĕbáֽ̇rá⁠h׃"],[26,4,"וַ⁠יִּשְׁלַ֥ח דָּוִ֖ד מְרַגְּלִ֑ים וַ⁠יֵּ֕דַע כִּֽי־בָ֥א שָׁא֖וּל אֶל־נָכֽוֹן׃","wa⁠yi̇şĕ̌la֥ẖ dá̇wi֖d mĕragĕ̇li֑ym wa⁠yé̇֕daʻ kiֽ̇y-bá֥ʼ şá̌ʼ֖ẇl ʼel-nákֽwòn׃"],[26,5,"וַ⁠יָּ֣קָם דָּוִ֗ד וַ⁠יָּבֹא֮ אֶֽל־הַ⁠מָּקוֹם֮ אֲשֶׁ֣ר חָנָה־שָׁ֣ם שָׁאוּל֒ וַ⁠יַּ֣רְא דָּוִ֗ד אֶת־הַ⁠מָּקוֹם֙ אֲשֶׁ֣ר שָֽׁכַב־שָׁ֣ם שָׁא֔וּל וְ⁠אַבְנֵ֥ר בֶּן־נֵ֖ר שַׂר־צְבָא֑⁠וֹ וְ⁠שָׁאוּל֙ שֹׁכֵ֣ב בַּ⁠מַּעְגָּ֔ל וְ⁠הָ⁠עָ֖ם חֹנִ֥ים סביבת⁠ו׃","wa⁠yá֣̇qám dá̇wi֗d wa⁠yá̇bòʼ֮ ʼeֽl-ha⁠má̇qwòm֮ ʼàşě֣r ẖánáh-şá֣̌m şá̌ʼẇl֒ wa⁠yȧ֣rĕʼ dá̇wi֗d ʼeţ-ha⁠má̇qwòm֙ ʼàşě֣r şáֽ̌kab-şá֣̌m şá̌ʼ֔ẇl wĕ⁠ʼabĕné֥r bėn-né֖r şâr-ẕĕbáʼ֑⁠wò wĕ⁠şá̌ʼẇl֙ şò̌ké֣b bȧ⁠mȧʻĕgá̇֔l wĕ⁠há⁠ʻá֖m ẖòni֥ym sbybţ⁠w׃"],[26,6,"וַ⁠יַּ֨עַן דָּוִ֜ד וַ⁠יֹּ֣אמֶר ׀ אֶל־אֲחִימֶ֣לֶךְ הַ⁠חִתִּ֗י וְ⁠אֶל־אֲבִישַׁ֨י בֶּן־צְרוּיָ֜ה אֲחִ֤י יוֹאָב֙ לֵ⁠אמֹ֔ר מִֽי־יֵרֵ֥ד אִתִּ֛⁠י אֶל־שָׁא֖וּל אֶל־הַֽ⁠מַּחֲנֶ֑ה וַ⁠יֹּ֣אמֶר אֲבִישַׁ֔י אֲנִ֖י אֵרֵ֥ד עִמָּֽ⁠ךְ׃","wa⁠yȧ֨ʻan dá̇wi֜d wa⁠yò֣̇ʼmer ׀ ʼel-ʼàẖiyme֣lekĕ ha⁠ẖiţi̇֗y wĕ⁠ʼel-ʼàbiyşǎ֨y bėn-ẕĕrẇyá֜h ʼàẖi֤y ywòʼáb֙ lé⁠ʼmò֔r miֽy-yéré֥d ʼiţi֛̇⁠y ʼel-şá̌ʼ֖ẇl ʼel-haֽ⁠mȧẖàne֑h wa⁠yò֣̇ʼmer ʼàbiyşǎ֔y ʼàni֖y ʼéré֥d ʻimáֽ̇⁠kĕ׃"],[26,7,"וַ⁠יָּבֹא֩ דָוִ֨ד וַ⁠אֲבִישַׁ֥י ׀ אֶל־הָ⁠עָם֮ לַיְלָה֒ וְ⁠הִנֵּ֣ה שָׁא֗וּל שֹׁכֵ֤ב יָשֵׁן֙ בַּ⁠מַּעְגָּ֔ל וַ⁠חֲנִית֥⁠וֹ מְעוּכָֽה־בָ⁠אָ֖רֶץ מראשת⁠ו וְ⁠אַבְנֵ֣ר וְ⁠הָ⁠עָ֔ם שֹׁכְבִ֖ים סביבת⁠ו׃ס","wa⁠yá̇bòʼ֩ dáwi֨d wa⁠ʼàbiyşǎ֥y ׀ ʼel-há⁠ʻám֮ layĕláh֒ wĕ⁠hiné֣̇h şá̌ʼ֗ẇl şò̌ké֤b yáşé̌n֙ bȧ⁠mȧʻĕgá̇֔l wa⁠ẖàniyţ֥⁠wò mĕʻẇkáֽh-bá⁠ʼá֖reẕ mrʼşţ⁠w wĕ⁠ʼabĕné֣r wĕ⁠há⁠ʻá֔m şò̌kĕbi֖ym sbybţ⁠w׃s"],[26,8,"וַ⁠יֹּ֤אמֶר אֲבִישַׁי֙ אֶל־דָּוִ֔ד סִגַּ֨ר אֱלֹהִ֥ים הַ⁠יּ֛וֹם אֶת־אוֹיִבְ⁠ךָ֖ בְּ⁠יָדֶ֑⁠ךָ וְ⁠עַתָּה֩ אַכֶּ֨⁠נּוּ נָ֜א בַּ⁠חֲנִ֤ית וּ⁠בָ⁠אָ֨רֶץ֙ פַּ֣עַם אַחַ֔ת וְ⁠לֹ֥א אֶשְׁנֶ֖ה לֽ⁠וֹ׃","wa⁠yò֤̇ʼmer ʼàbiyşǎy֙ ʼel-dá̇wi֔d sigȧ֨r ʼèlòhi֥ym ha⁠ẏ֛wòm ʼeţ-ʼwòyibĕ⁠ká֖ bĕ̇⁠yáde֑⁠ká wĕ⁠ʻaţá̇h֩ ʼakė֨⁠ṅẇ ná֜ʼ bȧ⁠ẖàni֤yţ ẇ⁠bá⁠ʼá֨reẕ֙ pȧ֣ʻam ʼaẖa֔ţ wĕ⁠lò֥ʼ ʼeşĕ̌ne֖h lֽ⁠wò׃"],[26,9,"וַ⁠יֹּ֧אמֶר דָּוִ֛ד אֶל־אֲבִישַׁ֖י אַל־תַּשְׁחִיתֵ֑⁠הוּ כִּ֠י מִ֣י שָׁלַ֥ח יָד֛⁠וֹ בִּ⁠מְשִׁ֥יחַ יְהוָ֖ה וְ⁠נִקָּֽה׃פ","wa⁠yò֧̇ʼmer dá̇wi֛d ʼel-ʼàbiyşǎ֖y ʼal-ţȧşĕ̌ẖiyţé֑⁠hẇ ki̇֠y mi֣y şá̌la֥ẖ yád֛⁠wò bi̇⁠mĕşǐ֥yẖa yĕhwá֖h wĕ⁠niqáֽ̇h׃p"],[26,10,"וַ⁠יֹּ֤אמֶר דָּוִד֙ חַי־יְהוָ֔ה כִּ֥י אִם־יְהוָ֖ה יִגָּפֶ֑⁠נּוּ אֽוֹ־יוֹמ֤⁠וֹ יָבוֹא֙ וָ⁠מֵ֔ת א֧וֹ בַ⁠מִּלְחָמָ֛ה יֵרֵ֖ד וְ⁠נִסְפָּֽה׃","wa⁠yò֤̇ʼmer dá̇wid֙ ẖay-yĕhwá֔h ki֥̇y ʼim-yĕhwá֖h yigá̇pe֑⁠ṅẇ ʼֽwò-ywòm֤⁠wò yábwòʼ֙ wá⁠mé֔ţ ʼ֧wò ba⁠mi̇lĕẖámá֛h yéré֖d wĕ⁠nisĕpáֽ̇h׃"],[26,11,"חָלִ֤ילָ⁠ה לִּ⁠י֙ מֵֽ⁠יהוָ֔ה מִ⁠שְּׁלֹ֥חַ יָדִ֖⁠י בִּ⁠מְשִׁ֣יחַ יְהוָ֑ה וְ֠⁠עַתָּה קַח־נָ֨א אֶֽת־הַ⁠חֲנִ֜ית אֲשֶׁ֧ר מראשת⁠ו וְ⁠אֶת־צַפַּ֥חַת הַ⁠מַּ֖יִם וְ⁠נֵ֥לֲכָה לָּֽ⁠נוּ׃","ẖáli֤ylá⁠h li̇⁠y֙ méֽ⁠yhwá֔h mi⁠şĕ̇̌lò֥ẖa yádi֖⁠y bi̇⁠mĕşǐ֣yẖa yĕhwá֑h wĕ֠⁠ʻaţá̇h qaẖ-ná֨ʼ ʼeֽţ-ha⁠ẖàni֜yţ ʼàşě֧r mrʼşţ⁠w wĕ⁠ʼeţ-ẕapȧ֥ẖaţ ha⁠mȧ֖yim wĕ⁠né֥làkáh láֽ̇⁠nẇ׃"],[26,12,"וַ⁠יִּקַּח֩ דָּוִ֨ד אֶֽת־הַ⁠חֲנִ֜ית וְ⁠אֶת־צַפַּ֤חַת הַ⁠מַּ֨יִם֙ מֵרַאֲשֹׁתֵ֣י שָׁא֔וּל וַ⁠יֵּלְכ֖וּ לָ⁠הֶ֑ם וְ⁠אֵ֣ין רֹאֶה֩ וְ⁠אֵ֨ין יוֹדֵ֜עַ וְ⁠אֵ֣ין מֵקִ֗יץ כִּ֤י כֻלָּ⁠ם֙ יְשֵׁנִ֔ים כִּ֚י תַּרְדֵּמַ֣ת יְהוָ֔ה נָפְלָ֖ה עֲלֵי⁠הֶֽם׃","wa⁠yi̇qȧẖ֩ dá̇wi֨d ʼeֽţ-ha⁠ẖàni֜yţ wĕ⁠ʼeţ-ẕapȧ֤ẖaţ ha⁠mȧ֨yim֙ méraʼàşò̌ţé֣y şá̌ʼ֔ẇl wa⁠yé̇lĕk֖ẇ lá⁠he֑m wĕ⁠ʼé֣yn ròʼeh֩ wĕ⁠ʼé֨yn ywòdé֜ʻa wĕ⁠ʼé֣yn méqi֗yẕ ki֤̇y kulá̇⁠m֙ yĕşé̌ni֔ym ki֚̇y ţȧrĕdé̇ma֣ţ yĕhwá֔h nápĕlá֖h ʻàléy⁠heֽm׃"],[26,13,"וַ⁠יַּעֲבֹ֤ר דָּוִד֙ הָ⁠עֵ֔בֶר וַ⁠יַּעֲמֹ֥ד עַל־רֹאשׁ־הָ⁠הָ֖ר מֵֽ⁠רָחֹ֑ק רַ֥ב הַ⁠מָּק֖וֹם בֵּינֵי⁠הֶֽם׃","wa⁠yȧʻàbò֤r dá̇wid֙ há⁠ʻé֔ber wa⁠yȧʻàmò֥d ʻal-ròʼş̌-há⁠há֖r méֽ⁠ráẖò֑q ra֥b ha⁠má̇q֖wòm bé̇ynéy⁠heֽm׃"],[26,14,"וַ⁠יִּקְרָ֨א דָוִ֜ד אֶל־הָ⁠עָ֗ם וְ⁠אֶל־אַבְנֵ֤ר בֶּן־נֵר֙ לֵ⁠אמֹ֔ר הֲ⁠ל֥וֹא תַעֲנֶ֖ה אַבְנֵ֑ר וַ⁠יַּ֤עַן אַבְנֵר֙ וַ⁠יֹּ֔אמֶר מִ֥י אַתָּ֖ה קָרָ֥אתָ אֶל־הַ⁠מֶּֽלֶךְ׃פ","wa⁠yi̇qĕrá֨ʼ dáwi֜d ʼel-há⁠ʻá֗m wĕ⁠ʼel-ʼabĕné֤r bėn-nér֙ lé⁠ʼmò֔r hà⁠l֥wòʼ ţaʻàne֖h ʼabĕné֑r wa⁠yȧ֤ʻan ʼabĕnér֙ wa⁠yò̇֔ʼmer mi֥y ʼaţá֖̇h qárá֥ʼţá ʼel-ha⁠mėֽlekĕ׃p"],[26,15,"וַ⁠יֹּאמֶר֩ דָּוִ֨ד אֶל־אַבְנֵ֜ר הֲ⁠לוֹא־אִ֣ישׁ אַתָּ֗ה וּ⁠מִ֤י כָמ֨וֹ⁠ךָ֙ בְּ⁠יִשְׂרָאֵ֔ל וְ⁠לָ֨⁠מָּה֙ לֹ֣א שָׁמַ֔רְתָּ אֶל־אֲדֹנֶ֖י⁠ךָ הַ⁠מֶּ֑לֶךְ כִּי־בָא֙ אַחַ֣ד הָ⁠עָ֔ם לְ⁠הַשְׁחִ֖ית אֶת־הַ⁠מֶּ֥לֶךְ אֲדֹנֶֽי⁠ךָ׃","wa⁠yò̇ʼmer֩ dá̇wi֨d ʼel-ʼabĕné֜r hà⁠lwòʼ-ʼi֣yş̌ ʼaţá̇֗h ẇ⁠mi֤y kám֨wò⁠ká֙ bĕ̇⁠yişĕ̂ráʼé֔l wĕ⁠lá֨⁠má̇h֙ lò֣ʼ şá̌ma֔rĕţá̇ ʼel-ʼàdòne֖y⁠ká ha⁠mė֑lekĕ ki̇y-báʼ֙ ʼaẖa֣d há⁠ʻá֔m lĕ⁠haşĕ̌ẖi֖yţ ʼeţ-ha⁠mė֥lekĕ ʼàdòneֽy⁠ká׃"],[26,16,"לֹא־ט֞וֹב הַ⁠דָּבָ֣ר הַ⁠זֶּה֮ אֲשֶׁ֣ר עָשִׂיתָ֒ חַי־יְהוָ֗ה כִּ֤י בְנֵי־מָ֨וֶת֙ אַתֶּ֔ם אֲשֶׁ֧ר לֹֽא־שְׁמַרְתֶּ֛ם עַל־אֲדֹנֵי⁠כֶ֖ם עַל־מְשִׁ֣יחַ יְהוָ֑ה וְ⁠עַתָּ֣ה ׀ רְאֵ֗ה אֵֽי־חֲנִ֥ית הַ⁠מֶּ֛לֶךְ וְ⁠אֶת־צַפַּ֥חַת הַ⁠מַּ֖יִם אֲשֶׁ֥ר מראשת⁠ו׃","lòʼ-t֞wòb ha⁠dá̇bá֣r ha⁠zėh֮ ʼàşě֣r ʻáşîyţá֒ ẖay-yĕhwá֗h ki֤̇y bĕnéy-má֨weţ֙ ʼaţė֔m ʼàşě֧r lòֽʼ-şĕ̌marĕţė֛m ʻal-ʼàdònéy⁠ke֖m ʻal-mĕşǐ֣yẖa yĕhwá֑h wĕ⁠ʻaţá֣̇h ׀ rĕʼé֗h ʼéֽy-ẖàni֥yţ ha⁠mė֛lekĕ wĕ⁠ʼeţ-ẕapȧ֥ẖaţ ha⁠mȧ֖yim ʼàşě֥r mrʼşţ⁠w׃"],[26,17,"וַ⁠יַּכֵּ֤ר שָׁאוּל֙ אֶת־ק֣וֹל דָּוִ֔ד וַ⁠יֹּ֕אמֶר הֲ⁠קוֹלְ⁠ךָ֥ זֶ֖ה בְּנִ֣⁠י דָוִ֑ד וַ⁠יֹּ֣אמֶר דָּוִ֔ד קוֹלִ֖⁠י אֲדֹנִ֥⁠י הַ⁠מֶּֽלֶךְ׃","wa⁠yȧké֤̇r şá̌ʼẇl֙ ʼeţ-q֣wòl dá̇wi֔d wa⁠yò̇֕ʼmer hà⁠qwòlĕ⁠ká֥ ze֖h bĕ̇ni֣⁠y dáwi֑d wa⁠yò֣̇ʼmer dá̇wi֔d qwòli֖⁠y ʼàdòni֥⁠y ha⁠mėֽlekĕ׃"],[26,18,"וַ⁠יֹּ֕אמֶר לָ֥⁠מָּה זֶּ֛ה אֲדֹנִ֥⁠י רֹדֵ֖ף אַחֲרֵ֣י עַבְדּ֑⁠וֹ כִּ֚י מֶ֣ה עָשִׂ֔יתִי וּ⁠מַה־בְּ⁠יָדִ֖⁠י רָעָֽה׃","wa⁠yò̇֕ʼmer lá֥⁠má̇h zė֛h ʼàdòni֥⁠y ròdé֖p ʼaẖàré֣y ʻabĕḋ֑⁠wò ki֚̇y me֣h ʻáşî֔yţiy ẇ⁠mah-bĕ̇⁠yádi֖⁠y ráʻáֽh׃"],[26,19,"וְ⁠עַתָּ֗ה יִֽשְׁמַֽע־נָא֙ אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ אֵ֖ת דִּבְרֵ֣י עַבְדּ֑⁠וֹ אִם־יְהוָ֞ה הֱסִֽיתְ⁠ךָ֥ בִ⁠י֙ יָרַ֣ח מִנְחָ֔ה וְ⁠אִ֣ם ׀ בְּנֵ֣י הָ⁠אָדָ֗ם אֲרוּרִ֥ים הֵם֙ לִ⁠פְנֵ֣י יְהוָ֔ה כִּֽי־גֵרְשׁ֣וּ⁠נִי הַ⁠יּ֗וֹם מֵ⁠הִסְתַּפֵּ֜חַ בְּ⁠נַחֲלַ֤ת יְהוָה֙ לֵ⁠אמֹ֔ר לֵ֥ךְ עֲבֹ֖ד אֱלֹהִ֥ים אֲחֵרִֽים׃","wĕ⁠ʻaţá̇֗h yiֽşĕ̌maֽʻ-náʼ֙ ʼàdòni֣⁠y ha⁠mė֔lekĕ ʼé֖ţ di̇bĕré֣y ʻabĕḋ֑⁠wò ʼim-yĕhwá֞h hèsiֽyţĕ⁠ká֥ bi⁠y֙ yára֣ẖ minĕẖá֔h wĕ⁠ʼi֣m ׀ bĕ̇né֣y há⁠ʼádá֗m ʼàrẇri֥ym hém֙ li⁠pĕné֣y yĕhwá֔h kiֽ̇y-gérĕş֣̌ẇ⁠niy ha⁠ẏ֗wòm mé⁠hisĕţȧpé̇֜ẖa bĕ̇⁠naẖàla֤ţ yĕhwáh֙ lé⁠ʼmò֔r lé֥kĕ ʻàbò֖d ʼèlòhi֥ym ʼàẖériֽym׃"],[26,20,"וְ⁠עַתָּ֗ה אַל־יִפֹּ֤ל דָּֽמִ⁠י֙ אַ֔רְצָ⁠ה מִ⁠נֶּ֖גֶד פְּנֵ֣י יְהוָ֑ה כִּֽי־יָצָ֞א מֶ֣לֶךְ יִשְׂרָאֵ֗ל לְ⁠בַקֵּשׁ֙ אֶת־פַּרְעֹ֣שׁ אֶחָ֔ד כַּ⁠אֲשֶׁ֛ר יִרְדֹּ֥ף הַ⁠קֹּרֵ֖א בֶּ⁠הָרִֽים׃","wĕ⁠ʻaţá̇֗h ʼal-yipò֤̇l dáֽ̇mi⁠y֙ ʼa֔rĕẕá⁠h mi⁠nė֖ged pĕ̇né֣y yĕhwá֑h kiֽ̇y-yáẕá֞ʼ me֣lekĕ yişĕ̂ráʼé֗l lĕ⁠baqé̇ş̌֙ ʼeţ-pȧrĕʻò֣ş̌ ʼeẖá֔d kȧ⁠ʼàşě֛r yirĕdò֥̇p ha⁠qò̇ré֖ʼ bė⁠háriֽym׃"],[26,21,"וַ⁠יֹּאמֶר֩ שָׁא֨וּל חָטָ֜אתִי שׁ֣וּב בְּנִֽ⁠י־דָוִ֗ד כִּ֠י לֹֽא־אָרַ֤ע לְ⁠ךָ֙ ע֔וֹד תַּ֠חַת אֲשֶׁ֨ר יָקְרָ֥ה נַפְשִׁ֛⁠י בְּ⁠עֵינֶ֖י⁠ךָ הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה הִנֵּ֥ה הִסְכַּ֛לְתִּי וָ⁠אֶשְׁגֶּ֖ה הַרְבֵּ֥ה מְאֹֽד׃","wa⁠yò̇ʼmer֩ şá̌ʼ֨ẇl ẖátá֜ʼţiy ş֣̌ẇb bĕ̇niֽ⁠y-dáwi֗d ki̇֠y lòֽʼ-ʼára֤ʻ lĕ⁠ká֙ ʻ֔wòd ţȧ֠ẖaţ ʼàşě֨r yáqĕrá֥h napĕşǐ֛⁠y bĕ̇⁠ʻéyne֖y⁠ká ha⁠ẏ֣wòm ha⁠zė֑h hiné֥̇h hisĕkȧ֛lĕţi̇y wá⁠ʼeşĕ̌gė֖h harĕbé֥̇h mĕʼòֽd׃"],[26,22,"וַ⁠יַּ֤עַן דָּוִד֙ וַ⁠יֹּ֔אמֶר הִנֵּ֖ה החנית הַ⁠מֶּ֑לֶךְ וְ⁠יַעֲבֹ֛ר אֶחָ֥ד מֵֽ⁠הַ⁠נְּעָרִ֖ים וְ⁠יִקָּחֶֽ⁠הָ׃","wa⁠yȧ֤ʻan dá̇wid֙ wa⁠yò̇֔ʼmer hiné֖̇h hẖnyţ ha⁠mė֑lekĕ wĕ⁠yaʻàbò֛r ʼeẖá֥d méֽ⁠ha⁠nĕ̇ʻári֖ym wĕ⁠yiqá̇ẖeֽ⁠há׃"],[26,23,"וַֽ⁠יהוָה֙ יָשִׁ֣יב לָ⁠אִ֔ישׁ אֶת־צִדְקָת֖⁠וֹ וְ⁠אֶת־אֱמֻנָת֑⁠וֹ אֲשֶׁר֩ נְתָנְ⁠ךָ֨ יְהוָ֤ה ׀ הַ⁠יּוֹם֙ בְּ⁠יָ֔ד וְ⁠לֹ֣א אָבִ֔יתִי לִ⁠שְׁלֹ֥חַ יָדִ֖⁠י בִּ⁠מְשִׁ֥יחַ יְהוָֽה׃","waֽ⁠yhwáh֙ yáşǐ֣yb lá⁠ʼi֔yş̌ ʼeţ-ẕidĕqáţ֖⁠wò wĕ⁠ʼeţ-ʼèmunáţ֑⁠wò ʼàşěr֩ nĕţánĕ⁠ká֨ yĕhwá֤h ׀ ha⁠ẏwòm֙ bĕ̇⁠yá֔d wĕ⁠lò֣ʼ ʼábi֔yţiy li⁠şĕ̌lò֥ẖa yádi֖⁠y bi̇⁠mĕşǐ֥yẖa yĕhwáֽh׃"],[26,24,"וְ⁠הִנֵּ֗ה כַּ⁠אֲשֶׁ֨ר גָּדְלָ֧ה נַפְשְׁ⁠ךָ֛ הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה בְּ⁠עֵינָ֑⁠י כֵּ֣ן תִּגְדַּ֤ל נַפְשִׁ⁠י֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה וְ⁠יַצִּלֵ֖⁠נִי מִ⁠כָּל־צָרָֽה׃פ","wĕ⁠hiné̇֗h kȧ⁠ʼàşě֨r gá̇dĕlá֧h napĕşĕ̌⁠ká֛ ha⁠ẏ֥wòm ha⁠zė֖h bĕ̇⁠ʻéyná֑⁠y ké֣̇n ţi̇gĕdȧ֤l napĕşǐ⁠y֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h wĕ⁠yaẕi̇lé֖⁠niy mi⁠ká̇l-ẕáráֽh׃p"],[26,25,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל אֶל־דָּוִ֗ד בָּר֤וּךְ אַתָּה֙ בְּנִ֣⁠י דָוִ֔ד גַּ֚ם עָשֹׂ֣ה תַעֲשֶׂ֔ה וְ⁠גַ֖ם יָכֹ֣ל תּוּכָ֑ל וַ⁠יֵּ֤לֶךְ דָּוִד֙ לְ⁠דַרְכּ֔⁠וֹ וְ⁠שָׁא֖וּל שָׁ֥ב לִ⁠מְקוֹמֽ⁠וֹ׃פ","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl ʼel-dá̇wi֗d bá̇r֤ẇkĕ ʼaţá̇h֙ bĕ̇ni֣⁠y dáwi֔d gȧ֚m ʻáşò֣̂h ţaʻàşê֔h wĕ⁠ga֖m yákò֣l ţ̇ẇká֑l wa⁠yé֤̇lekĕ dá̇wid֙ lĕ⁠darĕk̇֔⁠wò wĕ⁠şá̌ʼ֖ẇl şá֥̌b li⁠mĕqwòmֽ⁠wò׃p"],[27,1,"וַ⁠יֹּ֤אמֶר דָּוִד֙ אֶל־לִבּ֔⁠וֹ עַתָּ֛ה אֶסָּפֶ֥ה יוֹם־אֶחָ֖ד בְּ⁠יַד־שָׁא֑וּל אֵֽין־לִ֨⁠י ט֜וֹב כִּ֣י הִמָּלֵ֥ט אִמָּלֵ֣ט ׀ אֶל־אֶ֣רֶץ פְּלִשְׁתִּ֗ים וְ⁠נוֹאַ֨שׁ מִמֶּ֤⁠נִּי שָׁאוּל֙ לְ⁠בַקְשֵׁ֤⁠נִי עוֹד֙ בְּ⁠כָל־גְּב֣וּל יִשְׂרָאֵ֔ל וְ⁠נִמְלַטְתִּ֖י מִ⁠יָּדֽ⁠וֹ׃","wa⁠yò֤̇ʼmer dá̇wid֙ ʼel-liḃ֔⁠wò ʻaţá֛̇h ʼesá̇pe֥h ywòm-ʼeẖá֖d bĕ̇⁠yad-şá̌ʼ֑ẇl ʼéֽyn-li֨⁠y t֜wòb ki֣̇y himá̇lé֥t ʼimá̇lé֣t ׀ ʼel-ʼe֣reẕ pĕ̇lişĕ̌ţi̇֗ym wĕ⁠nwòʼa֨ş̌ mimė֤⁠ni̇y şá̌ʼẇl֙ lĕ⁠baqĕşé֤̌⁠niy ʻwòd֙ bĕ̇⁠kál-gĕ̇b֣ẇl yişĕ̂ráʼé֔l wĕ⁠nimĕlatĕţi֖̇y mi⁠yá̇dֽ⁠wò׃"],[27,2,"וַ⁠יָּ֣קָם דָּוִ֔ד וַ⁠יַּעֲבֹ֣ר ה֔וּא וְ⁠שֵׁשׁ־מֵא֥וֹת אִ֖ישׁ אֲשֶׁ֣ר עִמּ֑⁠וֹ אֶל־אָכִ֥ישׁ בֶּן־מָע֖וֹךְ מֶ֥לֶךְ גַּֽת׃","wa⁠yá֣̇qám dá̇wi֔d wa⁠yȧʻàbò֣r h֔ẇʼ wĕ⁠şé̌ş̌-méʼ֥wòţ ʼi֖yş̌ ʼàşě֣r ʻiṁ֑⁠wò ʼel-ʼáki֥yş̌ bėn-máʻ֖wòkĕ me֥lekĕ gȧֽţ׃"],[27,3,"וַ⁠יֵּשֶׁב֩ דָּוִ֨ד עִם־אָכִ֥ישׁ בְּ⁠גַ֛ת ה֥וּא וַ⁠אֲנָשָׁ֖י⁠ו אִ֣ישׁ וּ⁠בֵית֑⁠וֹ דָּוִד֙ וּ⁠שְׁתֵּ֣י נָשָׁ֔י⁠ו אֲחִינֹ֨עַם֙ הַ⁠יִּזְרְעֵאלִ֔ית וַ⁠אֲבִיגַ֥יִל אֵֽשֶׁת־נָבָ֖ל הַֽ⁠כַּרְמְלִֽית׃","wa⁠yé̇şěb֩ dá̇wi֨d ʻim-ʼáki֥yş̌ bĕ̇⁠ga֛ţ h֥ẇʼ wa⁠ʼànáşá֖̌y⁠w ʼi֣yş̌ ẇ⁠béyţ֑⁠wò dá̇wid֙ ẇ⁠şĕ̌ţé֣̇y náşá̌֔y⁠w ʼàẖiynò֨ʻam֙ ha⁠yi̇zĕrĕʻéʼli֔yţ wa⁠ʼàbiyga֥yil ʼéֽşěţ-nábá֖l haֽ⁠kȧrĕmĕliֽyţ׃"],[27,4,"וַ⁠יֻּגַּ֣ד לְ⁠שָׁא֔וּל כִּֽי־בָרַ֥ח דָּוִ֖ד גַּ֑ת וְ⁠לֹֽא־יוסף ע֖וֹד לְ⁠בַקְשֽׁ⁠וֹ׃ס","wa⁠yu̇gȧ֣d lĕ⁠şá̌ʼ֔ẇl kiֽ̇y-bára֥ẖ dá̇wi֖d gȧ֑ţ wĕ⁠lòֽʼ-ywsp ʻ֖wòd lĕ⁠baqĕşֽ̌⁠wò׃s"],[27,5,"וַ⁠יֹּ֨אמֶר דָּוִ֜ד אֶל־אָכִ֗ישׁ אִם־נָא֩ מָצָ֨אתִי חֵ֤ן בְּ⁠עֵינֶ֨י⁠ךָ֙ יִתְּנוּ־לִ֣⁠י מָק֗וֹם בְּ⁠אַחַ֛ת עָרֵ֥י הַ⁠שָּׂדֶ֖ה וְ⁠אֵ֣שְׁבָה שָּׁ֑ם וְ⁠לָ֨⁠מָּה יֵשֵׁ֧ב עַבְדְּ⁠ךָ֛ בְּ⁠עִ֥יר הַ⁠מַּמְלָכָ֖ה עִמָּֽ⁠ךְ׃","wa⁠yò̇֨ʼmer dá̇wi֜d ʼel-ʼáki֗yş̌ ʼim-náʼ֩ máẕá֨ʼţiy ẖé֤n bĕ̇⁠ʻéyne֨y⁠ká֙ yiţĕ̇nẇ-li֣⁠y máq֗wòm bĕ̇⁠ʼaẖa֛ţ ʻáré֥y ha⁠şá̇̂de֖h wĕ⁠ʼé֣şĕ̌báh şá֑̇̌m wĕ⁠lá֨⁠má̇h yéşé֧̌b ʻabĕdĕ̇⁠ká֛ bĕ̇⁠ʻi֥yr ha⁠mȧmĕláká֖h ʻimáֽ̇⁠kĕ׃"],[27,6,"וַ⁠יִּתֶּן־ל֥⁠וֹ אָכִ֛ישׁ בַּ⁠יּ֥וֹם הַ⁠ה֖וּא אֶת־צִֽקְלָ֑ג לָ⁠כֵ֞ן הָיְתָ֤ה צִֽקְלַג֙ לְ⁠מַלְכֵ֣י יְהוּדָ֔ה עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yi̇ţėn-l֥⁠wò ʼáki֛yş̌ bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ ʼeţ-ẕiֽqĕlá֑g lá⁠ké֞n háyĕţá֤h ẕiֽqĕlag֙ lĕ⁠malĕké֣y yĕhẇdá֔h ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[27,7,"וַֽ⁠יְהִי֙ מִסְפַּ֣ר הַ⁠יָּמִ֔ים אֲשֶׁר־יָשַׁ֥ב דָּוִ֖ד בִּ⁠שְׂדֵ֣ה פְלִשְׁתִּ֑ים יָמִ֖ים וְ⁠אַרְבָּעָ֥ה חֳדָשִֽׁים׃","waֽ⁠yĕhiy֙ misĕpȧ֣r ha⁠yá̇mi֔ym ʼàşěr-yáşǎ֥b dá̇wi֖d bi̇⁠şĕ̂dé֣h pĕlişĕ̌ţi֑̇ym yámi֖ym wĕ⁠ʼarĕbá̇ʻá֥h ẖodáşǐֽym׃"],[27,8,"וַ⁠יַּ֤עַל דָּוִד֙ וַֽ⁠אֲנָשָׁ֔י⁠ו וַֽ⁠יִּפְשְׁט֛וּ אֶל־הַ⁠גְּשׁוּרִ֥י ו⁠ה⁠גרזי וְ⁠הָ⁠עֲמָלֵקִ֑י כִּ֣י הֵ֜נָּה יֹשְׁב֤וֹת הָ⁠אָ֨רֶץ֙ אֲשֶׁ֣ר מֵֽ⁠עוֹלָ֔ם בּוֹאֲ⁠ךָ֥ שׁ֖וּרָ⁠ה וְ⁠עַד־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yȧ֤ʻal dá̇wid֙ wֽa⁠ʼànáşá̌֔y⁠w waֽ⁠yi̇pĕşĕ̌t֛ẇ ʼel-ha⁠gĕ̇ş̌ẇri֥y w⁠h⁠grzy wĕ⁠há⁠ʻàmáléqi֑y ki֣̇y hé֜ná̇h yòşĕ̌b֤wòţ há⁠ʼá֨reẕ֙ ʼàşě֣r méֽ⁠ʻwòlá֔m ḃwòʼà⁠ká֥ ş֖̌ẇrá⁠h wĕ⁠ʻad-ʼe֥reẕ miẕĕráֽyim׃"],[27,9,"וְ⁠הִכָּ֤ה דָוִד֙ אֶת־הָ⁠אָ֔רֶץ וְ⁠לֹ֥א יְחַיֶּ֖ה אִ֣ישׁ וְ⁠אִשָּׁ֑ה וְ⁠לָקַח֩ צֹ֨אן וּ⁠בָקָ֜ר וַ⁠חֲמֹרִ֤ים וּ⁠גְמַלִּים֙ וּ⁠בְגָדִ֔ים וַ⁠יָּ֖שָׁב וַ⁠יָּבֹ֥א אֶל־אָכִֽישׁ׃","wĕ⁠hiká֤̇h dáwid֙ ʼeţ-há⁠ʼá֔reẕ wĕ⁠lò֥ʼ yĕẖayė֖h ʼi֣yş̌ wĕ⁠ʼişá֑̇̌h wĕ⁠láqaẖ֩ ẕò֨ʼn ẇ⁠báqá֜r wa⁠ẖàmòri֤ym ẇ⁠gĕmali̇ym֙ ẇ⁠bĕgádi֔ym wa⁠yá֖̇şá̌b wa⁠yá̇bò֥ʼ ʼel-ʼákiֽyş̌׃"],[27,10,"וַ⁠יֹּ֣אמֶר אָכִ֔ישׁ אַל־פְּשַׁטְתֶּ֖ם הַ⁠יּ֑וֹם וַ⁠יֹּ֣אמֶר דָּוִ֗ד עַל־נֶ֤גֶב יְהוּדָה֙ וְ⁠עַל־נֶ֣גֶב הַ⁠יַּרְחְמְאֵלִ֔י וְ⁠אֶל־נֶ֖גֶב הַ⁠קֵּינִֽי׃","wa⁠yò֣̇ʼmer ʼáki֔yş̌ ʼal-pĕ̇şǎtĕţė֖m ha⁠ẏ֑wòm wa⁠yò֣̇ʼmer dá̇wi֗d ʻal-ne֤geb yĕhẇdáh֙ wĕ⁠ʻal-ne֣geb ha⁠yȧrĕẖĕmĕʼéli֔y wĕ⁠ʼel-ne֖geb ha⁠qé̇yniֽy׃"],[27,11,"וְ⁠אִ֨ישׁ וְ⁠אִשָּׁ֜ה לֹֽא־יְחַיֶּ֣ה דָוִ֗ד לְ⁠הָבִ֥יא גַת֙ לֵ⁠אמֹ֔ר פֶּן־יַגִּ֥דוּ עָלֵ֖י⁠נוּ לֵ⁠אמֹ֑ר כֹּֽה־עָשָׂ֤ה דָוִד֙ וְ⁠כֹ֣ה מִשְׁפָּט֔⁠וֹ כָּל־הַ֨⁠יָּמִ֔ים אֲשֶׁ֥ר יָשַׁ֖ב בִּ⁠שְׂדֵ֥ה פְלִשְׁתִּֽים׃","wĕ⁠ʼi֨yş̌ wĕ⁠ʼişá̇̌֜h lòֽʼ-yĕẖayė֣h dáwi֗d lĕ⁠hábi֥yʼ gaţ֙ lé⁠ʼmò֔r pėn-yagi֥̇dẇ ʻálé֖y⁠nẇ lé⁠ʼmò֑r kòֽ̇h-ʻáşá֤̂h dáwid֙ wĕ⁠kò֣h mişĕ̌pá̇t֔⁠wò ká̇l-ha֨⁠yá̇mi֔ym ʼàşě֥r yáşǎ֖b bi̇⁠şĕ̂dé֥h pĕlişĕ̌ţiֽ̇ym׃"],[27,12,"וַ⁠יַּאֲמֵ֥ן אָכִ֖ישׁ בְּ⁠דָוִ֣ד לֵ⁠אמֹ֑ר הַבְאֵ֤שׁ הִבְאִישׁ֙ בְּ⁠עַמּ֣⁠וֹ בְ⁠יִשְׂרָאֵ֔ל וְ⁠הָ֥יָה לִ֖⁠י לְ⁠עֶ֥בֶד עוֹלָֽם׃פ","wa⁠yȧʼàmé֥n ʼáki֖yş̌ bĕ̇⁠dáwi֣d lé⁠ʼmò֑r habĕʼé֤ş̌ hibĕʼiyş̌֙ bĕ̇⁠ʻaṁ֣⁠wò bĕ⁠yişĕ̂ráʼé֔l wĕ⁠há֥yáh li֖⁠y lĕ⁠ʻe֥bed ʻwòláֽm׃p"],[28,1,"וַֽ⁠יְהִי֙ בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם וַ⁠יִּקְבְּצ֨וּ פְלִשְׁתִּ֤ים אֶת־מַֽחֲנֵי⁠הֶם֙ לַ⁠צָּבָ֔א לְ⁠הִלָּחֵ֖ם בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יֹּ֤אמֶר אָכִישׁ֙ אֶל־דָּוִ֔ד יָדֹ֣עַ תֵּדַ֗ע כִּ֤י אִתִּ⁠י֙ תֵּצֵ֣א בַֽ⁠מַּחֲנֶ֔ה אַתָּ֖ה וַ⁠אֲנָשֶֽׁי⁠ךָ׃","waֽ⁠yĕhiy֙ bȧ⁠yá̇mi֣ym há⁠hé֔m wa⁠yi̇qĕbĕ̇ẕ֨ẇ pĕlişĕ̌ţi֤̇ym ʼeţ-maֽẖànéy⁠hem֙ la⁠ẕá̇bá֔ʼ lĕ⁠hilá̇ẖé֖m bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yò֤̇ʼmer ʼákiyş̌֙ ʼel-dá̇wi֔d yádò֣ʻa ţé̇da֗ʻ ki֤̇y ʼiţi̇⁠y֙ ţé̇ẕé֣ʼ baֽ⁠mȧẖàne֔h ʼaţá֖̇h wa⁠ʼànáşěֽy⁠ká׃"],[28,2,"וַ⁠יֹּ֤אמֶר דָּוִד֙ אֶל־אָכִ֔ישׁ לָ⁠כֵן֙ אַתָּ֣ה תֵדַ֔ע אֵ֥ת אֲשֶׁר־יַעֲשֶׂ֖ה עַבְדֶּ֑⁠ךָ וַ⁠יֹּ֤אמֶר אָכִישׁ֙ אֶל־דָּוִ֔ד לָ⁠כֵ֗ן שֹׁמֵ֧ר לְ⁠רֹאשִׁ֛⁠י אֲשִֽׂימְ⁠ךָ֖ כָּל־הַ⁠יָּמִֽים׃פ","wa⁠yò֤̇ʼmer dá̇wid֙ ʼel-ʼáki֔yş̌ lá⁠kén֙ ʼaţá֣̇h ţéda֔ʻ ʼé֥ţ ʼàşěr-yaʻàşê֖h ʻabĕdė֑⁠ká wa⁠yò֤̇ʼmer ʼákiyş̌֙ ʼel-dá̇wi֔d lá⁠ké֗n şò̌mé֧r lĕ⁠ròʼşǐ֛⁠y ʼàşîֽymĕ⁠ká֖ ká̇l-ha⁠yá̇miֽym׃p"],[28,3,"וּ⁠שְׁמוּאֵ֣ל מֵ֔ת וַ⁠יִּסְפְּדוּ־ל⁠וֹ֙ כָּל־יִשְׂרָאֵ֔ל וַ⁠יִּקְבְּרֻ֥⁠הוּ בָ⁠רָמָ֖ה וּ⁠בְ⁠עִיר֑⁠וֹ וְ⁠שָׁא֗וּל הֵסִ֛יר הָ⁠אֹב֥וֹת וְ⁠אֶת־הַ⁠יִּדְּעֹנִ֖ים מֵ⁠הָ⁠אָֽרֶץ׃","ẇ⁠şĕ̌mẇʼé֣l mé֔ţ wa⁠yi̇sĕpĕ̇dẇ-l⁠wò֙ ká̇l-yişĕ̂ráʼé֔l wa⁠yi̇qĕbĕ̇ru֥⁠hẇ bá⁠rámá֖h ẇ⁠bĕ⁠ʻiyr֑⁠wò wĕ⁠şá̌ʼ֗ẇl hési֛yr há⁠ʼòb֥wòţ wĕ⁠ʼeţ-ha⁠yi̇dĕ̇ʻòni֖ym mé⁠há⁠ʼáֽreẕ׃"],[28,4,"וַ⁠יִּקָּבְצ֣וּ פְלִשְׁתִּ֔ים וַ⁠יָּבֹ֖אוּ וַ⁠יַּחֲנ֣וּ בְ⁠שׁוּנֵ֑ם וַ⁠יִּקְבֹּ֤ץ שָׁאוּל֙ אֶת־כָּל־יִשְׂרָאֵ֔ל וַֽ⁠יַּחֲנ֖וּ בַּ⁠גִּלְבֹּֽעַ׃","wa⁠yi̇qá̇bĕẕ֣ẇ pĕlişĕ̌ţi̇֔ym wa⁠yá̇bò֖ʼẇ wa⁠yȧẖàn֣ẇ bĕ⁠ş̌ẇné֑m wa⁠yi̇qĕbò֤̇ẕ şá̌ʼẇl֙ ʼeţ-ká̇l-yişĕ̂ráʼé֔l waֽ⁠yȧẖàn֖ẇ bȧ⁠gi̇lĕbòֽ̇ʻa׃"],[28,5,"וַ⁠יַּ֥רְא שָׁא֖וּל אֶת־מַחֲנֵ֣ה פְלִשְׁתִּ֑ים וַ⁠יִּרָ֕א וַ⁠יֶּחֱרַ֥ד לִבּ֖⁠וֹ מְאֹֽד׃","wa⁠yȧ֥rĕʼ şá̌ʼ֖ẇl ʼeţ-maẖàné֣h pĕlişĕ̌ţi֑̇ym wa⁠yi̇rá֕ʼ wa⁠yėẖèra֥d liḃ֖⁠wò mĕʼòֽd׃"],[28,6,"וַ⁠יִּשְׁאַ֤ל שָׁאוּל֙ בַּֽ⁠יהוָ֔ה וְ⁠לֹ֥א עָנָ֖⁠הוּ יְהוָ֑ה גַּ֧ם בַּ⁠חֲלֹמ֛וֹת גַּ֥ם בָּ⁠אוּרִ֖ים גַּ֥ם בַּ⁠נְּבִיאִֽם׃","wa⁠yi̇şĕ̌ʼa֤l şá̌ʼẇl֙ bȧֽ⁠yhwá֔h wĕ⁠lò֥ʼ ʻáná֖⁠hẇ yĕhwá֑h gȧ֧m bȧ⁠ẖàlòm֛wòţ gȧ֥m bá̇⁠ʼẇri֖ym gȧ֥m bȧ⁠nĕ̇biyʼiֽm׃"],[28,7,"וַ⁠יֹּ֨אמֶר שָׁא֜וּל לַ⁠עֲבָדָ֗י⁠ו בַּקְּשׁוּ־לִ⁠י֙ אֵ֣שֶׁת בַּעֲלַת־א֔וֹב וְ⁠אֵלְכָ֥ה אֵלֶ֖י⁠הָ וְ⁠אֶדְרְשָׁה־בָּ֑⁠הּ וַ⁠יֹּאמְר֤וּ עֲבָדָי⁠ו֙ אֵלָ֔י⁠ו הִנֵּ֛ה אֵ֥שֶׁת בַּֽעֲלַת־א֖וֹב בְּ⁠עֵ֥ין דּֽוֹר׃","wa⁠yò̇֨ʼmer şá̌ʼ֜ẇl la⁠ʻàbádá֗y⁠w bȧqĕ̇ş̌ẇ-li⁠y֙ ʼé֣şěţ bȧʻàlaţ-ʼ֔wòb wĕ⁠ʼélĕká֥h ʼéle֖y⁠há wĕ⁠ʼedĕrĕşá̌h-bá֑̇⁠ḣ wa⁠yò̇ʼmĕr֤ẇ ʻàbádáy⁠w֙ ʼélá֔y⁠w hiné֛̇h ʼé֥şěţ bȧֽʻàlaţ-ʼ֖wòb bĕ̇⁠ʻé֥yn ḋֽwòr׃"],[28,8,"וַ⁠יִּתְחַפֵּ֣שׂ שָׁא֗וּל וַ⁠יִּלְבַּשׁ֙ בְּגָדִ֣ים אֲחֵרִ֔ים וַ⁠יֵּ֣לֶךְ ה֗וּא וּ⁠שְׁנֵ֤י אֲנָשִׁים֙ עִמּ֔⁠וֹ וַ⁠יָּבֹ֥אוּ אֶל־הָ⁠אִשָּׁ֖ה לָ֑יְלָה וַ⁠יֹּ֗אמֶר קסומי־נָ֥א לִ⁠י֙ בָּ⁠א֔וֹב וְ⁠הַ֣עֲלִי לִ֔⁠י אֵ֥ת אֲשֶׁר־אֹמַ֖ר אֵלָֽיִ⁠ךְ׃","wa⁠yi̇ţĕẖapé֣̇ş̂ şá̌ʼ֗ẇl wa⁠yi̇lĕbȧş̌֙ bĕ̇gádi֣ym ʼàẖéri֔ym wa⁠yé֣̇lekĕ h֗ẇʼ ẇ⁠şĕ̌né֤y ʼànáşǐym֙ ʻiṁ֔⁠wò wa⁠yá̇bò֥ʼẇ ʼel-há⁠ʼişá֖̇̌h lá֑yĕláh wa⁠yò̇֗ʼmer qswmy-ná֥ʼ li⁠y֙ bá̇⁠ʼ֔wòb wĕ⁠ha֣ʻàliy li֔⁠y ʼé֥ţ ʼàşěr-ʼòma֖r ʼéláֽyi⁠kĕ׃"],[28,9,"וַ⁠תֹּ֨אמֶר הָֽ⁠אִשָּׁ֜ה אֵלָ֗י⁠ו הִנֵּ֨ה אַתָּ֤ה יָדַ֨עְתָּ֙ אֵ֣ת אֲשֶׁר־עָשָׂ֣ה שָׁא֔וּל אֲשֶׁ֥ר הִכְרִ֛ית אֶת־הָ⁠אֹב֥וֹת וְ⁠אֶת־הַ⁠יִּדְּעֹנִ֖י מִן־הָ⁠אָ֑רֶץ וְ⁠לָ⁠מָ֥ה אַתָּ֛ה מִתְנַקֵּ֥שׁ בְּ⁠נַפְשִׁ֖⁠י לַ⁠הֲמִיתֵֽ⁠נִי׃","wa⁠ţò̇֨ʼmer háֽ⁠ʼişá̇̌֜h ʼélá֗y⁠w hiné̇֨h ʼaţá֤̇h yáda֨ʻĕţá̇֙ ʼé֣ţ ʼàşěr-ʻáşá֣̂h şá̌ʼ֔ẇl ʼàşě֥r hikĕri֛yţ ʼeţ-há⁠ʼòb֥wòţ wĕ⁠ʼeţ-ha⁠yi̇dĕ̇ʻòni֖y min-há⁠ʼá֑reẕ wĕ⁠lá⁠má֥h ʼaţá֛̇h miţĕnaqé֥̇ş̌ bĕ̇⁠napĕşǐ֖⁠y la⁠hàmiyţéֽ⁠niy׃"],[28,10,"וַ⁠יִּשָּׁ֤בַֽע לָ⁠הּ֙ שָׁא֔וּל בַּֽ⁠יהוָ֖ה לֵ⁠אמֹ֑ר חַי־יְהוָ֕ה אִֽם־יִקְּרֵ֥⁠ךְ עָוֺ֖ן בַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yi̇şá֤̇̌baֽʻ lá⁠ḣ֙ şá̌ʼ֔ẇl bȧֽ⁠yhwá֖h lé⁠ʼmò֑r ẖay-yĕhwá֕h ʼiֽm-yiqĕ̇ré֥⁠kĕ ʻáwֺ֖n bȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[28,11,"וַ⁠תֹּ֨אמֶר֙ הָֽ⁠אִשָּׁ֔ה אֶת־מִ֖י אַֽעֲלֶה־לָּ֑⁠ךְ וַ⁠יֹּ֕אמֶר אֶת־שְׁמוּאֵ֖ל הַֽעֲלִי־לִֽ⁠י׃","wa⁠ţò̇֨ʼmer֙ háֽ⁠ʼişá̇̌֔h ʼeţ-mi֖y ʼaֽʻàleh-lá֑̇⁠kĕ wa⁠yò̇֕ʼmer ʼeţ-şĕ̌mẇʼé֖l haֽʻàliy-liֽ⁠y׃"],[28,12,"וַ⁠תֵּ֤רֶא הָֽ⁠אִשָּׁה֙ אֶת־שְׁמוּאֵ֔ל וַ⁠תִּזְעַ֖ק בְּ⁠ק֣וֹל גָּד֑וֹל וַ⁠תֹּאמֶר֩ הָ⁠אִשָּׁ֨ה אֶל־שָׁא֧וּל לֵ⁠אמֹ֛ר לָ֥⁠מָּה רִמִּיתָ֖⁠נִי וְ⁠אַתָּ֥ה שָׁאֽוּל׃","wa⁠ţé֤̇reʼ háֽ⁠ʼişá̇̌h֙ ʼeţ-şĕ̌mẇʼé֔l wa⁠ţi̇zĕʻa֖q bĕ̇⁠q֣wòl gá̇d֑wòl wa⁠ţò̇ʼmer֩ há⁠ʼişá̇̌֨h ʼel-şá̌ʼ֧ẇl lé⁠ʼmò֛r lá֥⁠má̇h rimi̇yţá֖⁠niy wĕ⁠ʼaţá֥̇h şá̌ʼֽẇl׃"],[28,13,"וַ⁠יֹּ֨אמֶר לָ֥⁠הּ הַ⁠מֶּ֛לֶךְ אַל־תִּֽירְאִ֖י כִּ֣י מָ֣ה רָאִ֑ית וַ⁠תֹּ֤אמֶר הָֽ⁠אִשָּׁה֙ אֶל־שָׁא֔וּל אֱלֹהִ֥ים רָאִ֖יתִי עֹלִ֥ים מִן־הָ⁠אָֽרֶץ׃","wa⁠yò̇֨ʼmer lá֥⁠ḣ ha⁠mė֛lekĕ ʼal-ţiֽ̇yrĕʼi֖y ki֣̇y má֣h ráʼi֑yţ wa⁠ţò֤̇ʼmer háֽ⁠ʼişá̇̌h֙ ʼel-şá̌ʼ֔ẇl ʼèlòhi֥ym ráʼi֖yţiy ʻòli֥ym min-há⁠ʼáֽreẕ׃"],[28,14,"וַ⁠יֹּ֤אמֶר לָ⁠הּ֙ מַֽה־תָּאֳר֔⁠וֹ וַ⁠תֹּ֗אמֶר אִ֤ישׁ זָקֵן֙ עֹלֶ֔ה וְ⁠ה֥וּא עֹטֶ֖ה מְעִ֑יל וַ⁠יֵּ֤דַע שָׁאוּל֙ כִּֽי־שְׁמוּאֵ֣ל ה֔וּא וַ⁠יִּקֹּ֥ד אַפַּ֛יִם אַ֖רְצָ⁠ה וַ⁠יִּשְׁתָּֽחוּ׃ס","wa⁠yò֤̇ʼmer lá⁠ḣ֙ maֽh-ţá̇ʼor֔⁠wò wa⁠ţò̇֗ʼmer ʼi֤yş̌ záqén֙ ʻòle֔h wĕ⁠h֥ẇʼ ʻòte֖h mĕʻi֑yl wa⁠yé֤̇daʻ şá̌ʼẇl֙ kiֽ̇y-şĕ̌mẇʼé֣l h֔ẇʼ wa⁠yi̇qò֥̇d ʼapȧ֛yim ʼa֖rĕẕá⁠h wa⁠yi̇şĕ̌ţáֽ̇ẖẇ׃s"],[28,15,"וַ⁠יֹּ֤אמֶר שְׁמוּאֵל֙ אֶל־שָׁא֔וּל לָ֥⁠מָּה הִרְגַּזְתַּ֖⁠נִי לְ⁠הַעֲל֣וֹת אֹתִ֑⁠י וַ⁠יֹּ֣אמֶר שָׁ֠אוּל צַר־לִ֨⁠י מְאֹ֜ד וּ⁠פְלִשְׁתִּ֣ים ׀ נִלְחָמִ֣ים בִּ֗⁠י וֵֽ⁠אלֹהִ֞ים סָ֤ר מֵֽ⁠עָלַ⁠י֙ וְ⁠לֹֽא־עָנָ֣⁠נִי ע֗וֹד גַּ֤ם בְּ⁠יַֽד־הַ⁠נְּבִיאִם֙ גַּם־בַּ֣⁠חֲלֹמ֔וֹת וָ⁠אֶקְרָאֶ֣⁠ה לְ⁠ךָ֔ לְ⁠הוֹדִיעֵ֖⁠נִי מָ֥ה אֶעֱשֶֽׂה׃ס","wa⁠yò֤̇ʼmer şĕ̌mẇʼél֙ ʼel-şá̌ʼ֔ẇl lá֥⁠má̇h hirĕgȧzĕţȧ֖⁠niy lĕ⁠haʻàl֣wòţ ʼòţi֑⁠y wa⁠yò֣̇ʼmer şá̌֠ʼẇl ẕar-li֨⁠y mĕʼò֜d ẇ⁠pĕlişĕ̌ţi֣̇ym ׀ nilĕẖámi֣ym bi̇֗⁠y wéֽ⁠ʼlòhi֞ym sá֤r méֽ⁠ʻála⁠y֙ wĕ⁠lòֽʼ-ʻáná֣⁠niy ʻ֗wòd gȧ֤m bĕ̇⁠yaֽd-ha⁠nĕ̇biyʼim֙ gȧm-bȧ֣⁠ẖàlòm֔wòţ wá⁠ʼeqĕráʼe֣⁠h lĕ⁠ká֔ lĕ⁠hwòdiyʻé֖⁠niy má֥h ʼeʻèşêֽh׃s"],[28,16,"וַ⁠יֹּ֣אמֶר שְׁמוּאֵ֔ל וְ⁠לָ֖⁠מָּה תִּשְׁאָלֵ֑⁠נִי וַ⁠יהוָ֛ה סָ֥ר מֵ⁠עָלֶ֖י⁠ךָ וַ⁠יְהִ֥י עָרֶֽ⁠ךָ׃","wa⁠yò֣̇ʼmer şĕ̌mẇʼé֔l wĕ⁠lá֖⁠má̇h ţi̇şĕ̌ʼálé֑⁠niy wa⁠yhwá֛h sá֥r mé⁠ʻále֖y⁠ká wa⁠yĕhi֥y ʻáreֽ⁠ká׃"],[28,17,"וַ⁠יַּ֤עַשׂ יְהוָה֙ ל֔⁠וֹ כַּ⁠אֲשֶׁ֖ר דִּבֶּ֣ר בְּ⁠יָדִ֑⁠י וַ⁠יִּקְרַ֨ע יְהוָ֤ה אֶת־הַ⁠מַּמְלָכָה֙ מִ⁠יָּדֶ֔⁠ךָ וַֽ⁠יִּתְּנָ֖⁠הּ לְ⁠רֵעֲ⁠ךָ֥ לְ⁠דָוִֽד׃","wa⁠yȧ֤ʻaş̂ yĕhwáh֙ l֔⁠wò kȧ⁠ʼàşě֖r di̇bė֣r bĕ̇⁠yádi֑⁠y wa⁠yi̇qĕra֨ʻ yĕhwá֤h ʼeţ-ha⁠mȧmĕlákáh֙ mi⁠yá̇de֔⁠ká waֽ⁠yi̇ţĕ̇ná֖⁠ḣ lĕ⁠réʻà⁠ká֥ lĕ⁠dáwiֽd׃"],[28,18,"כַּ⁠אֲשֶׁ֤ר לֹֽא־שָׁמַ֨עְתָּ֙ בְּ⁠ק֣וֹל יְהוָ֔ה וְ⁠לֹֽא־עָשִׂ֥יתָ חֲרוֹן־אַפּ֖⁠וֹ בַּ⁠עֲמָלֵ֑ק עַל־כֵּן֙ הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה עָשָֽׂה־לְ⁠ךָ֥ יְהוָ֖ה הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","kȧ⁠ʼàşě֤r lòֽʼ-şá̌ma֨ʻĕţá̇֙ bĕ̇⁠q֣wòl yĕhwá֔h wĕ⁠lòֽʼ-ʻáşî֥yţá ẖàrwòn-ʼaṗ֖⁠wò bȧ⁠ʻàmálé֑q ʻal-ké̇n֙ ha⁠dá̇bá֣r ha⁠zė֔h ʻáşáֽ̂h-lĕ⁠ká֥ yĕhwá֖h ha⁠ẏ֥wòm ha⁠zėֽh׃"],[28,19,"וְ⁠יִתֵּ֣ן יְ֠הוָה גַּ֣ם אֶת־יִשְׂרָאֵ֤ל עִמְּ⁠ךָ֙ בְּ⁠יַד־פְּלִשְׁתִּ֔ים וּ⁠מָחָ֕ר אַתָּ֥ה וּ⁠בָנֶ֖י⁠ךָ עִמִּ֑⁠י גַּ֚ם אֶת־מַחֲנֵ֣ה יִשְׂרָאֵ֔ל יִתֵּ֥ן יְהוָ֖ה בְּ⁠יַד־פְּלִשְׁתִּֽים׃","wĕ⁠yiţé֣̇n yĕ֠hwáh gȧ֣m ʼeţ-yişĕ̂ráʼé֤l ʻimĕ̇⁠ká֙ bĕ̇⁠yad-pĕ̇lişĕ̌ţi̇֔ym ẇ⁠máẖá֕r ʼaţá֥̇h ẇ⁠báne֖y⁠ká ʻimi֑̇⁠y gȧ֚m ʼeţ-maẖàné֣h yişĕ̂ráʼé֔l yiţé֥̇n yĕhwá֖h bĕ̇⁠yad-pĕ̇lişĕ̌ţiֽ̇ym׃"],[28,20,"וַ⁠יְמַהֵ֣ר שָׁא֗וּל וַ⁠יִּפֹּ֤ל מְלֹא־קֽוֹמָת⁠וֹ֙ אַ֔רְצָ⁠ה וַ⁠יִּרָ֥א מְאֹ֖ד מִ⁠דִּבְרֵ֣י שְׁמוּאֵ֑ל גַּם־כֹּ֨חַ֙ לֹא־הָ֣יָה ב֔⁠וֹ כִּ֣י לֹ֤א אָכַל֙ לֶ֔חֶם כָּל־הַ⁠יּ֖וֹם וְ⁠כָל־הַ⁠לָּֽיְלָה׃","wa⁠yĕmahé֣r şá̌ʼ֗ẇl wa⁠yi̇pò֤̇l mĕlòʼ-qֽwòmáţ⁠wò֙ ʼa֔rĕẕá⁠h wa⁠yi̇rá֥ʼ mĕʼò֖d mi⁠di̇bĕré֣y şĕ̌mẇʼé֑l gȧm-kò̇֨ẖa֙ lòʼ-há֣yáh b֔⁠wò ki֣̇y lò֤ʼ ʼákal֙ le֔ẖem ká̇l-ha⁠ẏ֖wòm wĕ⁠kál-ha⁠láֽ̇yĕláh׃"],[28,21,"וַ⁠תָּב֤וֹא הָֽ⁠אִשָּׁה֙ אֶל־שָׁא֔וּל וַ⁠תֵּ֖רֶא כִּי־נִבְהַ֣ל מְאֹ֑ד וַ⁠תֹּ֣אמֶר אֵלָ֗י⁠ו הִנֵּ֨ה שָׁמְעָ֤ה שִׁפְחָֽתְ⁠ךָ֙ בְּ⁠קוֹלֶ֔⁠ךָ וָ⁠אָשִׂ֤ים נַפְשִׁ⁠י֙ בְּ⁠כַפִּ֔⁠י וָֽ⁠אֶשְׁמַע֙ אֶת־דְּבָרֶ֔י⁠ךָ אֲשֶׁ֥ר דִּבַּ֖רְתָּ אֵלָֽ⁠י׃","wa⁠ţá̇b֤wòʼ háֽ⁠ʼişá̇̌h֙ ʼel-şá̌ʼ֔ẇl wa⁠ţé֖̇reʼ ki̇y-nibĕha֣l mĕʼò֑d wa⁠ţò֣̇ʼmer ʼélá֗y⁠w hiné̇֨h şá̌mĕʻá֤h şǐpĕẖáֽţĕ⁠ká֙ bĕ̇⁠qwòle֔⁠ká wá⁠ʼáşî֤ym napĕşǐ⁠y֙ bĕ̇⁠kapi̇֔⁠y wáֽ⁠ʼeşĕ̌maʻ֙ ʼeţ-dĕ̇báre֔y⁠ká ʼàşě֥r di̇bȧ֖rĕţá̇ ʼéláֽ⁠y׃"],[28,22,"וְ⁠עַתָּ֗ה שְׁמַֽע־נָ֤א גַם־אַתָּה֙ בְּ⁠ק֣וֹל שִׁפְחָתֶ֔⁠ךָ וְ⁠אָשִׂ֧מָה לְ⁠פָנֶ֛י⁠ךָ פַּת־לֶ֖חֶם וֶ⁠אֱכ֑וֹל וִ⁠יהִ֤י בְ⁠ךָ֙ כֹּ֔חַ כִּ֥י תֵלֵ֖ךְ בַּ⁠דָּֽרֶךְ׃","wĕ⁠ʻaţá̇֗h şĕ̌maֽʻ-ná֤ʼ gam-ʼaţá̇h֙ bĕ̇⁠q֣wòl şǐpĕẖáţe֔⁠ká wĕ⁠ʼáşî֧máh lĕ⁠páne֛y⁠ká pȧţ-le֖ẖem we⁠ʼèk֑wòl wi⁠yhi֤y bĕ⁠ká֙ kò̇֔ẖa ki֥̇y ţélé֖kĕ bȧ⁠dáֽ̇rekĕ׃"],[28,23,"וַ⁠יְמָאֵ֗ן וַ⁠יֹּ֨אמֶר֙ לֹ֣א אֹכַ֔ל וַ⁠יִּפְרְצוּ־ב֤⁠וֹ עֲבָדָי⁠ו֙ וְ⁠גַם־הָ֣⁠אִשָּׁ֔ה וַ⁠יִּשְׁמַ֖ע לְ⁠קֹלָ֑⁠ם וַ⁠יָּ֨קָם֙ מֵֽ⁠הָ⁠אָ֔רֶץ וַ⁠יֵּ֖שֶׁב אֶל־הַ⁠מִּטָּֽה׃","wa⁠yĕmáʼé֗n wa⁠yò̇֨ʼmer֙ lò֣ʼ ʼòka֔l wa⁠yi̇pĕrĕẕẇ-b֤⁠wò ʻàbádáy⁠w֙ wĕ⁠gam-há֣⁠ʼişá̇̌֔h wa⁠yi̇şĕ̌ma֖ʻ lĕ⁠qòlá֑⁠m wa⁠yá̇֨qám֙ méֽ⁠há⁠ʼá֔reẕ wa⁠yé֖̇şěb ʼel-ha⁠mi̇táֽ̇h׃"],[28,24,"וְ⁠לָ⁠אִשָּׁ֤ה עֵֽגֶל־מַרְבֵּק֙ בַּ⁠בַּ֔יִת וַ⁠תְּמַהֵ֖ר וַ⁠תִּזְבָּחֵ֑⁠הוּ וַ⁠תִּקַּח־קֶ֣מַח וַ⁠תָּ֔לָשׁ וַ⁠תֹּפֵ֖⁠הוּ מַצּֽוֹת׃","wĕ⁠lá⁠ʼişá֤̇̌h ʻéֽgel-marĕbé̇q֙ bȧ⁠bȧ֔yiţ wa⁠ţĕ̇mahé֖r wa⁠ţi̇zĕbá̇ẖé֑⁠hẇ wa⁠ţi̇qȧẖ-qe֣maẖ wa⁠ţá̇֔láş̌ wa⁠ţò̇pé֖⁠hẇ maẕֽ̇wòţ׃"],[28,25,"וַ⁠תַּגֵּ֧שׁ לִ⁠פְנֵֽי־שָׁא֛וּל וְ⁠לִ⁠פְנֵ֥י עֲבָדָ֖י⁠ו וַ⁠יֹּאכֵ֑לוּ וַ⁠יָּקֻ֥מוּ וַ⁠יֵּלְכ֖וּ בַּ⁠לַּ֥יְלָה הַ⁠הֽוּא׃פ","wa⁠ţȧgé֧̇ş̌ li⁠pĕnéֽy-şá̌ʼ֛ẇl wĕ⁠li⁠pĕné֥y ʻàbádá֖y⁠w wa⁠yò̇ʼké֑lẇ wa⁠yá̇qu֥mẇ wa⁠yé̇lĕk֖ẇ bȧ⁠lȧ֥yĕláh ha⁠hֽẇʼ׃p"],[29,1,"וַ⁠יִּקְבְּצ֧וּ פְלִשְׁתִּ֛ים אֶת־כָּל־מַחֲנֵי⁠הֶ֖ם אֲפֵ֑קָ⁠ה וְ⁠יִשְׂרָאֵ֣ל חֹנִ֔ים בַּ⁠עַ֖יִן אֲשֶׁ֥ר בְּ⁠יִזְרְעֶֽאל׃","wa⁠yi̇qĕbĕ̇ẕ֧ẇ pĕlişĕ̌ţi֛̇ym ʼeţ-ká̇l-maẖànéy⁠he֖m ʼàpé֑qá⁠h wĕ⁠yişĕ̂ráʼé֣l ẖòni֔ym bȧ⁠ʻa֖yin ʼàşě֥r bĕ̇⁠yizĕrĕʻeֽʼl׃"],[29,2,"וְ⁠סַרְנֵ֤י פְלִשְׁתִּים֙ עֹֽבְרִ֔ים לְ⁠מֵא֖וֹת וְ⁠לַ⁠אֲלָפִ֑ים וְ⁠דָוִ֣ד וַ⁠אֲנָשָׁ֗י⁠ו עֹֽבְרִ֛ים בָּ⁠אַחֲרֹנָ֖ה עִם־אָכִֽישׁ׃","wĕ⁠sarĕné֤y pĕlişĕ̌ţi̇ym֙ ʻòֽbĕri֔ym lĕ⁠méʼ֖wòţ wĕ⁠la⁠ʼàlápi֑ym wĕ⁠dáwi֣d wa⁠ʼànáşá̌֗y⁠w ʻòֽbĕri֛ym bá̇⁠ʼaẖàròná֖h ʻim-ʼákiֽyş̌׃"],[29,3,"וַ⁠יֹּֽאמְרוּ֙ שָׂרֵ֣י פְלִשְׁתִּ֔ים מָ֖ה הָ⁠עִבְרִ֣ים הָ⁠אֵ֑לֶּה וַ⁠יֹּ֨אמֶר אָכִ֜ישׁ אֶל־שָׂרֵ֣י פְלִשְׁתִּ֗ים הֲ⁠לֽוֹא־זֶ֨ה דָוִ֜ד עֶ֣בֶד ׀ שָׁא֣וּל מֶֽלֶךְ־יִשְׂרָאֵ֗ל אֲשֶׁ֨ר הָיָ֤ה אִתִּ⁠י֙ זֶ֤ה יָמִים֙ אוֹ־זֶ֣ה שָׁנִ֔ים וְ⁠לֹֽא־מָצָ֤אתִי ב⁠וֹ֙ מְא֔וּמָה מִ⁠יּ֥וֹם נָפְל֖⁠וֹ עַד־הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yòֽ̇ʼmĕrẇ֙ şá̂ré֣y pĕlişĕ̌ţi̇֔ym má֖h há⁠ʻibĕri֣ym há⁠ʼé֑lėh wa⁠yò̇֨ʼmer ʼáki֜yş̌ ʼel-şá̂ré֣y pĕlişĕ̌ţi̇֗ym hà⁠lֽwòʼ-ze֨h dáwi֜d ʻe֣bed ׀ şá̌ʼ֣ẇl meֽlekĕ-yişĕ̂ráʼé֗l ʼàşě֨r háyá֤h ʼiţi̇⁠y֙ ze֤h yámiym֙ ʼwò-ze֣h şá̌ni֔ym wĕ⁠lòֽʼ-máẕá֤ʼţiy b⁠wò֙ mĕʼ֔ẇmáh mi⁠ẏ֥wòm nápĕl֖⁠wò ʻad-ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[29,4,"וַ⁠יִּקְצְפ֨וּ עָלָ֜י⁠ו שָׂרֵ֣י פְלִשְׁתִּ֗ים וַ⁠יֹּ֣אמְרוּ ל⁠וֹ֩ שָׂרֵ֨י פְלִשְׁתִּ֜ים הָשֵׁ֣ב אֶת־הָ⁠אִ֗ישׁ וְ⁠יָשֹׁב֙ אֶל־מְקוֹמ⁠וֹ֙ אֲשֶׁ֣ר הִפְקַדְתּ֣⁠וֹ שָׁ֔ם וְ⁠לֹֽא־יֵרֵ֤ד עִמָּ֨⁠נוּ֙ בַּ⁠מִּלְחָמָ֔ה וְ⁠לֹא־יִֽהְיֶה־לָּ֥⁠נוּ לְ⁠שָׂטָ֖ן בַּ⁠מִּלְחָמָ֑ה וּ⁠בַ⁠מֶּ֗ה יִתְרַצֶּ֥ה זֶה֙ אֶל־אֲדֹנָ֔י⁠ו הֲ⁠ל֕וֹא בְּ⁠רָאשֵׁ֖י הָ⁠אֲנָשִׁ֥ים הָ⁠הֵֽם׃","wa⁠yi̇qĕẕĕp֨ẇ ʻálá֜y⁠w şá̂ré֣y pĕlişĕ̌ţi̇֗ym wa⁠yò֣̇ʼmĕrẇ l⁠wò֩ şá̂ré֨y pĕlişĕ̌ţi̇֜ym háşé֣̌b ʼeţ-há⁠ʼi֗yş̌ wĕ⁠yáşò̌b֙ ʼel-mĕqwòm⁠wò֙ ʼàşě֣r hipĕqadĕţ֣̇⁠wò şá̌֔m wĕ⁠lòֽʼ-yéré֤d ʻimá̇֨⁠nẇ֙ bȧ⁠mi̇lĕẖámá֔h wĕ⁠lòʼ-yiֽhĕyeh-lá֥̇⁠nẇ lĕ⁠şá̂tá֖n bȧ⁠mi̇lĕẖámá֑h ẇ⁠ba⁠mė֗h yiţĕraẕė֥h zeh֙ ʼel-ʼàdòná֔y⁠w hà⁠l֕wòʼ bĕ̇⁠ráʼşé֖̌y há⁠ʼànáşǐ֥ym há⁠héֽm׃"],[29,5,"הֲ⁠לוֹא־זֶ֣ה דָוִ֔ד אֲשֶׁ֧ר יַעֲנוּ־ל֛⁠וֹ בַּ⁠מְּחֹל֖וֹת לֵ⁠אמֹ֑ר הִכָּ֤ה שָׁאוּל֙ בַּֽ⁠אֲלָפָ֔י⁠ו וְ⁠דָוִ֖ד ב⁠רבבת⁠ו׃ס","hà⁠lwòʼ-ze֣h dáwi֔d ʼàşě֧r yaʻànẇ-l֛⁠wò bȧ⁠mĕ̇ẖòl֖wòţ lé⁠ʼmò֑r hiká֤̇h şá̌ʼẇl֙ bȧֽ⁠ʼàlápá֔y⁠w wĕ⁠dáwi֖d b⁠rbbţ⁠w׃s"],[29,6,"וַ⁠יִּקְרָ֨א אָכִ֜ישׁ אֶל־דָּוִ֗ד וַ⁠יֹּ֣אמֶר אֵ֠לָי⁠ו חַי־יְהוָ֞ה כִּי־יָשָׁ֣ר אַתָּ֗ה וְ⁠ט֣וֹב בְּ֠⁠עֵינַ⁠י צֵאתְ⁠ךָ֨ וּ⁠בֹאֲ⁠ךָ֤ אִתִּ⁠י֙ בַּֽ⁠מַּחֲנֶ֔ה כִּ֠י לֹֽא־מָצָ֤אתִֽי בְ⁠ךָ֙ רָעָ֔ה מִ⁠יּ֛וֹם בֹּאֲ⁠ךָ֥ אֵלַ֖⁠י עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וּ⁠בְ⁠עֵינֵ֥י הַ⁠סְּרָנִ֖ים לֹֽא־ט֥וֹב אָֽתָּה׃","wa⁠yi̇qĕrá֨ʼ ʼáki֜yş̌ ʼel-dá̇wi֗d wa⁠yò֣̇ʼmer ʼé֠láy⁠w ẖay-yĕhwá֞h ki̇y-yáşá֣̌r ʼaţá̇֗h wĕ⁠t֣wòb bĕ̇֠⁠ʻéyna⁠y ẕéʼţĕ⁠ká֨ ẇ⁠bòʼà⁠ká֤ ʼiţi̇⁠y֙ bȧֽ⁠mȧẖàne֔h ki̇֠y lòֽʼ-máẕá֤ʼţiֽy bĕ⁠ká֙ ráʻá֔h mi⁠ẏ֛wòm bò̇ʼà⁠ká֥ ʼéla֖⁠y ʻad-ha⁠ẏ֣wòm ha⁠zė֑h ẇ⁠bĕ⁠ʻéyné֥y ha⁠sĕ̇ráni֖ym lòֽʼ-t֥wòb ʼáֽţá̇h׃"],[29,7,"וְ⁠עַתָּ֥ה שׁ֖וּב וְ⁠לֵ֣ךְ בְּ⁠שָׁל֑וֹם וְ⁠לֹֽא־תַעֲשֶׂ֣ה רָ֔ע בְּ⁠עֵינֵ֖י סַרְנֵ֥י פְלִשְׁתִּֽים׃ס","wĕ⁠ʻaţá֥̇h ş֖̌ẇb wĕ⁠lé֣kĕ bĕ̇⁠şá̌l֑wòm wĕ⁠lòֽʼ-ţaʻàşê֣h rá֔ʻ bĕ̇⁠ʻéyné֖y sarĕné֥y pĕlişĕ̌ţiֽ̇ym׃s"],[29,8,"וַ⁠יֹּ֨אמֶר דָּוִ֜ד אֶל־אָכִ֗ישׁ כִּ֣י מֶ֤ה עָשִׂ֨יתִי֙ וּ⁠מַה־מָּצָ֣אתָ בְ⁠עַבְדְּ⁠ךָ֔ מִ⁠יּוֹם֙ אֲשֶׁ֣ר הָיִ֣יתִי לְ⁠פָנֶ֔י⁠ךָ עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ֣י לֹ֤א אָבוֹא֙ וְ⁠נִלְחַ֔מְתִּי בְּ⁠אֹיְבֵ֖י אֲדֹנִ֥⁠י הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֨ʼmer dá̇wi֜d ʼel-ʼáki֗yş̌ ki֣̇y me֤h ʻáşî֨yţiy֙ ẇ⁠mah-má̇ẕá֣ʼţá bĕ⁠ʻabĕdĕ̇⁠ká֔ mi⁠ẏwòm֙ ʼàşě֣r háyi֣yţiy lĕ⁠páne֔y⁠ká ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h ki֣̇y lò֤ʼ ʼábwòʼ֙ wĕ⁠nilĕẖa֔mĕţi̇y bĕ̇⁠ʼòyĕbé֖y ʼàdòni֥⁠y ha⁠mėֽlekĕ׃"],[29,9,"וַ⁠יַּ֣עַן אָכִישׁ֮ וַ⁠יֹּ֣אמֶר אֶל־דָּוִד֒ יָדַ֕עְתִּי כִּ֣י ט֥וֹב אַתָּ֛ה בְּ⁠עֵינַ֖⁠י כְּ⁠מַלְאַ֣ךְ אֱלֹהִ֑ים אַ֣ךְ שָׂרֵ֤י פְלִשְׁתִּים֙ אָֽמְר֔וּ לֹֽא־יַעֲלֶ֥ה עִמָּ֖⁠נוּ בַּ⁠מִּלְחָמָֽה׃","wa⁠yȧ֣ʻan ʼákiyş֮̌ wa⁠yò֣̇ʼmer ʼel-dá̇wid֒ yáda֕ʻĕţi̇y ki֣̇y t֥wòb ʼaţá֛̇h bĕ̇⁠ʻéyna֖⁠y kĕ̇⁠malĕʼa֣kĕ ʼèlòhi֑ym ʼa֣kĕ şá̂ré֤y pĕlişĕ̌ţi̇ym֙ ʼáֽmĕr֔ẇ lòֽʼ-yaʻàle֥h ʻimá֖̇⁠nẇ bȧ⁠mi̇lĕẖámáֽh׃"],[29,10,"וְ⁠עַתָּה֙ הַשְׁכֵּ֣ם בַּ⁠בֹּ֔קֶר וְ⁠עַבְדֵ֥י אֲדֹנֶ֖י⁠ךָ אֲשֶׁר־בָּ֣אוּ אִתָּ֑⁠ךְ וְ⁠הִשְׁכַּמְתֶּ֣ם בַּ⁠בֹּ֔קֶר וְ⁠א֥וֹר לָ⁠כֶ֖ם וָ⁠לֵֽכוּ׃","wĕ⁠ʻaţá̇h֙ haşĕ̌ké֣̇m bȧ⁠bò̇֔qer wĕ⁠ʻabĕdé֥y ʼàdòne֖y⁠ká ʼàşěr-bá֣̇ʼẇ ʼiţá֑̇⁠kĕ wĕ⁠hişĕ̌kȧmĕţė֣m bȧ⁠bò̇֔qer wĕ⁠ʼ֥wòr lá⁠ke֖m wá⁠léֽkẇ׃"],[29,11,"וַ⁠יַּשְׁכֵּ֨ם דָּוִ֜ד ה֤וּא וַֽ⁠אֲנָשָׁי⁠ו֙ לָ⁠לֶ֣כֶת בַּ⁠בֹּ֔קֶר לָ⁠שׁ֖וּב אֶל־אֶ֣רֶץ פְּלִשְׁתִּ֑ים וּ⁠פְלִשְׁתִּ֖ים עָל֥וּ יִזְרְעֶֽאל׃ס","wa⁠yȧşĕ̌ké̇֨m dá̇wi֜d h֤ẇʼ waֽ⁠ʼànáşá̌y⁠w֙ lá⁠le֣keţ bȧ⁠bò̇֔qer lá⁠ş֖̌ẇb ʼel-ʼe֣reẕ pĕ̇lişĕ̌ţi֑̇ym ẇ⁠pĕlişĕ̌ţi֖̇ym ʻál֥ẇ yizĕrĕʻeֽʼl׃s"],[30,1,"וַ⁠יְהִ֞י בְּ⁠בֹ֨א דָוִ֧ד וַ⁠אֲנָשָׁ֛י⁠ו צִֽקְלַ֖ג בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֑י וַ⁠עֲמָלֵקִ֣י פָֽשְׁט֗וּ אֶל־נֶ֨גֶב֙ וְ⁠אֶל־צִ֣קְלַ֔ג וַ⁠יַּכּוּ֙ אֶת־צִ֣קְלַ֔ג וַ⁠יִּשְׂרְפ֥וּ אֹתָ֖⁠הּ בָּ⁠אֵֽשׁ׃","wa⁠yĕhi֞y bĕ̇⁠bò֨ʼ dáwi֧d wa⁠ʼànáşá֛̌y⁠w ẕiֽqĕla֖g bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֑y wa⁠ʻàmáléqi֣y páֽşĕ̌t֗ẇ ʼel-ne֨geb֙ wĕ⁠ʼel-ẕi֣qĕla֔g wa⁠yȧk̇ẇ֙ ʼeţ-ẕi֣qĕla֔g wa⁠yi̇şĕ̂rĕp֥ẇ ʼòţá֖⁠ḣ bá̇⁠ʼéֽş̌׃"],[30,2,"וַ⁠יִּשְׁבּ֨וּ אֶת־הַ⁠נָּשִׁ֤ים אֲשֶׁר־בָּ⁠הּ֙ מִ⁠קָּטֹ֣ן וְ⁠עַד־גָּד֔וֹל לֹ֥א הֵמִ֖יתוּ אִ֑ישׁ וַ⁠יִּֽנְהֲג֔וּ וַ⁠יֵּלְכ֖וּ לְ⁠דַרְכָּֽ⁠ם׃","wa⁠yi̇şĕ̌ḃ֨ẇ ʼeţ-ha⁠ná̇şǐ֤ym ʼàşěr-bá̇⁠ḣ֙ mi⁠qá̇tò֣n wĕ⁠ʻad-gá̇d֔wòl lò֥ʼ hémi֖yţẇ ʼi֑yş̌ wa⁠yiֽ̇nĕhàg֔ẇ wa⁠yé̇lĕk֖ẇ lĕ⁠darĕkáֽ̇⁠m׃"],[30,3,"וַ⁠יָּבֹ֨א דָוִ֤ד וַֽ⁠אֲנָשָׁי⁠ו֙ אֶל־הָ⁠עִ֔יר וְ⁠הִנֵּ֥ה שְׂרוּפָ֖ה בָּ⁠אֵ֑שׁ וּ⁠נְשֵׁי⁠הֶ֛ם וּ⁠בְנֵי⁠הֶ֥ם וּ⁠בְנֹתֵי⁠הֶ֖ם נִשְׁבּֽוּ׃","wa⁠yá̇bò֨ʼ dáwi֤d waֽ⁠ʼànáşá̌y⁠w֙ ʼel-há⁠ʻi֔yr wĕ⁠hiné֥̇h şĕ̂rẇpá֖h bá̇⁠ʼé֑ş̌ ẇ⁠nĕşé̌y⁠he֛m ẇ⁠bĕnéy⁠he֥m ẇ⁠bĕnòţéy⁠he֖m nişĕ̌ḃֽẇ׃"],[30,4,"וַ⁠יִּשָּׂ֨א דָוִ֜ד וְ⁠הָ⁠עָ֧ם אֲשֶׁר־אִתּ֛⁠וֹ אֶת־קוֹלָ֖⁠ם וַ⁠יִּבְכּ֑וּ עַ֣ד אֲשֶׁ֧ר אֵין־בָּ⁠הֶ֛ם כֹּ֖חַ לִ⁠בְכּֽוֹת׃","wa⁠yi̇şá̇̂֨ʼ dáwi֜d wĕ⁠há⁠ʻá֧m ʼàşěr-ʼiţ֛̇⁠wò ʼeţ-qwòlá֖⁠m wa⁠yi̇bĕk֑̇ẇ ʻa֣d ʼàşě֧r ʼéyn-bá̇⁠he֛m kò֖̇ẖa li⁠bĕkֽ̇wòţ׃"],[30,5,"וּ⁠שְׁתֵּ֥י נְשֵֽׁי־דָוִ֖ד נִשְׁבּ֑וּ אֲחִינֹ֨עַם֙ הַ⁠יִּזְרְעֵלִ֔ית וַ⁠אֲבִיגַ֕יִל אֵ֖שֶׁת נָבָ֥ל הַֽ⁠כַּרְמְלִֽי׃","ẇ⁠şĕ̌ţé֥̇y nĕşéֽ̌y-dáwi֖d nişĕ̌ḃ֑ẇ ʼàẖiynò֨ʻam֙ ha⁠yi̇zĕrĕʻéli֔yţ wa⁠ʼàbiyga֕yil ʼé֖şěţ nábá֥l haֽ⁠kȧrĕmĕliֽy׃"],[30,6,"וַ⁠תֵּ֨צֶר לְ⁠דָוִ֜ד מְאֹ֗ד כִּֽי־אָמְר֤וּ הָ⁠עָם֙ לְ⁠סָקְל֔⁠וֹ כִּֽי־מָ֨רָה֙ נֶ֣פֶשׁ כָּל־הָ⁠עָ֔ם אִ֖ישׁ עַל־בנ⁠ו וְ⁠עַל־בְּנֹתָ֑י⁠ו וַ⁠יִּתְחַזֵּ֣ק דָּוִ֔ד בַּ⁠יהוָ֖ה אֱלֹהָֽי⁠ו׃ס","wa⁠ţé̇֨ẕer lĕ⁠dáwi֜d mĕʼò֗d kiֽ̇y-ʼámĕr֤ẇ há⁠ʻám֙ lĕ⁠sáqĕl֔⁠wò kiֽ̇y-má֨ráh֙ ne֣peş̌ ká̇l-há⁠ʻá֔m ʼi֖yş̌ ʻal-bn⁠w wĕ⁠ʻal-bĕ̇nòţá֑y⁠w wa⁠yi̇ţĕẖazé֣̇q dá̇wi֔d bȧ⁠yhwá֖h ʼèlòháֽy⁠w׃s"],[30,7,"וַ⁠יֹּ֣אמֶר דָּוִ֗ד אֶל־אֶבְיָתָ֤ר הַ⁠כֹּהֵן֙ בֶּן־אֲחִימֶ֔לֶךְ הַגִּֽישָׁ⁠ה־נָּ֥א לִ֖⁠י הָ⁠אֵפֹ֑ד וַ⁠יַּגֵּ֧שׁ אֶבְיָתָ֛ר אֶת־הָ⁠אֵפֹ֖ד אֶל־דָּוִֽד׃","wa⁠yò֣̇ʼmer dá̇wi֗d ʼel-ʼebĕyáţá֤r ha⁠kò̇hén֙ bėn-ʼàẖiyme֔lekĕ hagiֽ̇yşá̌⁠h-ná֥̇ʼ li֖⁠y há⁠ʼépò֑d wa⁠yȧgé֧̇ş̌ ʼebĕyáţá֛r ʼeţ-há⁠ʼépò֖d ʼel-dá̇wiֽd׃"],[30,8,"וַ⁠יִּשְׁאַ֨ל דָּוִ֤ד בַּֽ⁠יהוָה֙ לֵ⁠אמֹ֔ר אֶרְדֹּ֛ף אַחֲרֵ֥י הַ⁠גְּדוּד־הַ⁠זֶּ֖ה הַֽ⁠אַשִּׂגֶ֑⁠נּוּ וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ רְדֹ֔ף כִּֽי־הַשֵּׂ֥ג תַּשִּׂ֖יג וְ⁠הַצֵּ֥ל תַּצִּֽיל׃","wa⁠yi̇şĕ̌ʼa֨l dá̇wi֤d bȧֽ⁠yhwáh֙ lé⁠ʼmò֔r ʼerĕdò֛̇p ʼaẖàré֥y ha⁠gĕ̇dẇd-ha⁠zė֖h haֽ⁠ʼaşi̇̂ge֑⁠ṅẇ wa⁠yò֤̇ʼmer l⁠wò֙ rĕdò֔p kiֽ̇y-haşé֥̇̂g ţȧşi֖̇̂yg wĕ⁠haẕé֥̇l ţȧẕiֽ̇yl׃"],[30,9,"וַ⁠יֵּ֣לֶךְ דָּוִ֗ד ה֚וּא וְ⁠שֵׁשׁ־מֵא֥וֹת אִישׁ֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ וַ⁠יָּבֹ֖אוּ עַד־נַ֣חַל הַ⁠בְּשׂ֑וֹר וְ⁠הַ⁠נּֽוֹתָרִ֖ים עָמָֽדוּ׃","wa⁠yé֣̇lekĕ dá̇wi֗d h֚ẇʼ wĕ⁠şé̌ş̌-méʼ֥wòţ ʼiyş̌֙ ʼàşě֣r ʼiţ̇֔⁠wò wa⁠yá̇bò֖ʼẇ ʻad-na֣ẖal ha⁠bĕ̇ş֑̂wòr wĕ⁠ha⁠ṅֽwòţári֖ym ʻámáֽdẇ׃"],[30,10,"וַ⁠יִּרְדֹּ֣ף דָּוִ֔ד ה֖וּא וְ⁠אַרְבַּע־מֵא֣וֹת אִ֑ישׁ וַ⁠יַּֽעַמְדוּ֙ מָאתַ֣יִם אִ֔ישׁ אֲשֶׁ֣ר פִּגְּר֔וּ מֵ⁠עֲבֹ֖ר אֶת־נַ֥חַל הַ⁠בְּשֽׂוֹר׃","wa⁠yi̇rĕdò֣̇p dá̇wi֔d h֖ẇʼ wĕ⁠ʼarĕbȧʻ-méʼ֣wòţ ʼi֑yş̌ wa⁠yȧֽʻamĕdẇ֙ máʼţa֣yim ʼi֔yş̌ ʼàşě֣r pi̇gĕ̇r֔ẇ mé⁠ʻàbò֖r ʼeţ-na֥ẖal ha⁠bĕ̇şֽ̂wòr׃"],[30,11,"וַֽ⁠יִּמְצְא֤וּ אִישׁ־מִצְרִי֙ בַּ⁠שָּׂדֶ֔ה וַ⁠יִּקְח֥וּ אֹת֖⁠וֹ אֶל־דָּוִ֑ד וַ⁠יִּתְּנוּ־ל֥⁠וֹ לֶ֨חֶם֙ וַ⁠יֹּ֔אכַל וַ⁠יַּשְׁקֻ֖⁠הוּ מָֽיִם׃","waֽ⁠yi̇mĕẕĕʼ֤ẇ ʼiyş̌-miẕĕriy֙ bȧ⁠şá̇̂de֔h wa⁠yi̇qĕẖ֥ẇ ʼòţ֖⁠wò ʼel-dá̇wi֑d wa⁠yi̇ţĕ̇nẇ-l֥⁠wò le֨ẖem֙ wa⁠yò̇֔ʼkal wa⁠yȧşĕ̌qu֖⁠hẇ máֽyim׃"],[30,12,"וַ⁠יִּתְּנוּ־ל⁠וֹ֩ פֶ֨לַח דְּבֵלָ֜ה וּ⁠שְׁנֵ֤י צִמֻּקִים֙ וַ⁠יֹּ֔אכַל וַ⁠תָּ֥שָׁב רוּח֖⁠וֹ אֵלָ֑י⁠ו כִּ֠י לֹֽא־אָ֤כַל לֶ֨חֶם֙ וְ⁠לֹא־שָׁ֣תָה מַ֔יִם שְׁלֹשָׁ֥ה יָמִ֖ים וּ⁠שְׁלֹשָׁ֥ה לֵילֽוֹת׃ס","wa⁠yi̇ţĕ̇nẇ-l⁠wò֩ pe֨laẖ dĕ̇bélá֜h ẇ⁠şĕ̌né֤y ẕimu̇qiym֙ wa⁠yò̇֔ʼkal wa⁠ţá֥̇şá̌b rẇẖ֖⁠wò ʼélá֑y⁠w ki̇֠y lòֽʼ-ʼá֤kal le֨ẖem֙ wĕ⁠lòʼ-şá֣̌ţáh ma֔yim şĕ̌lòşá֥̌h yámi֖ym ẇ⁠şĕ̌lòşá֥̌h léylֽwòţ׃s"],[30,13,"וַ⁠יֹּ֨אמֶר ל֤⁠וֹ דָוִד֙ לְֽ⁠מִי־אַ֔תָּה וְ⁠אֵ֥י מִ⁠זֶּ֖ה אָ֑תָּה וַ⁠יֹּ֜אמֶר נַ֧עַר מִצְרִ֣י אָנֹ֗כִי עֶ֚בֶד לְ⁠אִ֣ישׁ עֲמָֽלֵקִ֔י וַ⁠יַּעַזְבֵ֧⁠נִי אֲדֹנִ֛⁠י כִּ֥י חָלִ֖יתִי הַ⁠יּ֥וֹם שְׁלֹשָֽׁה׃","wa⁠yò̇֨ʼmer l֤⁠wò dáwid֙ lĕֽ⁠miy-ʼa֔ţá̇h wĕ⁠ʼé֥y mi⁠zė֖h ʼá֑ţá̇h wa⁠yò̇֜ʼmer na֧ʻar miẕĕri֣y ʼánò֗kiy ʻe֚bed lĕ⁠ʼi֣yş̌ ʻàmáֽléqi֔y wa⁠yȧʻazĕbé֧⁠niy ʼàdòni֛⁠y ki֥̇y ẖáli֖yţiy ha⁠ẏ֥wòm şĕ̌lòşáֽ̌h׃"],[30,14,"אֲנַ֡חְנוּ פָּשַׁ֜טְנוּ נֶ֧גֶב הַ⁠כְּרֵתִ֛י וְ⁠עַל־אֲשֶׁ֥ר לִֽ⁠יהוּדָ֖ה וְ⁠עַל־נֶ֣גֶב כָּלֵ֑ב וְ⁠אֶת־צִקְלַ֖ג שָׂרַ֥פְנוּ בָ⁠אֵֽשׁ׃","ʼàna֡ẖĕnẇ pá̇şǎ֜tĕnẇ ne֧geb ha⁠kĕ̇réţi֛y wĕ⁠ʻal-ʼàşě֥r liֽ⁠yhẇdá֖h wĕ⁠ʻal-ne֣geb ká̇lé֑b wĕ⁠ʼeţ-ẕiqĕla֖g şá̂ra֥pĕnẇ bá⁠ʼéֽş̌׃"],[30,15,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ דָּוִ֔ד הֲ⁠תוֹרִדֵ֖⁠נִי אֶל־הַ⁠גְּד֣וּד הַ⁠זֶּ֑ה וַ⁠יֹּ֡אמֶר הִשָּׁבְעָ⁠ה֩ לִּ֨⁠י בֵֽ⁠אלֹהִ֜ים אִם־תְּמִיתֵ֗⁠נִי וְ⁠אִם־תַּסְגִּרֵ֨⁠נִי֙ בְּ⁠יַד־אֲדֹנִ֔⁠י וְ⁠אוֹרִֽדְ⁠ךָ֖ אֶל־הַ⁠גְּד֥וּד הַ⁠זֶּֽה׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ dá̇wi֔d hà⁠ţwòridé֖⁠niy ʼel-ha⁠gĕ̇d֣ẇd ha⁠zė֑h wa⁠yò̇֡ʼmer hişá̇̌bĕʻá⁠h֩ li̇֨⁠y béֽ⁠ʼlòhi֜ym ʼim-ţĕ̇miyţé֗⁠niy wĕ⁠ʼim-ţȧsĕgi̇ré֨⁠niy֙ bĕ̇⁠yad-ʼàdòni֔⁠y wĕ⁠ʼwòriֽdĕ⁠ká֖ ʼel-ha⁠gĕ̇d֥ẇd ha⁠zėֽh׃"],[30,16,"וַ⁠יֹּ֣רִדֵ֔⁠הוּ וְ⁠הִנֵּ֥ה נְטֻשִׁ֖ים עַל־פְּנֵ֣י כָל־הָ⁠אָ֑רֶץ אֹכְלִ֤ים וְ⁠שֹׁתִים֙ וְ⁠חֹ֣גְגִ֔ים בְּ⁠כֹל֙ הַ⁠שָּׁלָ֣ל הַ⁠גָּד֔וֹל אֲשֶׁ֥ר לָקְח֛וּ מֵ⁠אֶ֥רֶץ פְּלִשְׁתִּ֖ים וּ⁠מֵ⁠אֶ֥רֶץ יְהוּדָֽה׃","wa⁠yò֣̇ridé֔⁠hẇ wĕ⁠hiné֥̇h nĕtuşǐ֖ym ʻal-pĕ̇né֣y kál-há⁠ʼá֑reẕ ʼòkĕli֤ym wĕ⁠şò̌ţiym֙ wĕ⁠ẖò֣gĕgi֔ym bĕ̇⁠kòl֙ ha⁠şá̇̌lá֣l ha⁠gá̇d֔wòl ʼàşě֥r láqĕẖ֛ẇ mé⁠ʼe֥reẕ pĕ̇lişĕ̌ţi֖̇ym ẇ⁠mé⁠ʼe֥reẕ yĕhẇdáֽh׃"],[30,17,"וַ⁠יַּכֵּ֥⁠ם דָּוִ֛ד מֵ⁠הַ⁠נֶּ֥שֶׁף וְ⁠עַד־הָ⁠עֶ֖רֶב לְ⁠מָֽחֳרָתָ֑⁠ם וְ⁠לֹֽא־נִמְלַ֤ט מֵ⁠הֶם֙ אִ֔ישׁ כִּי֩ אִם־אַרְבַּ֨ע מֵא֧וֹת אִֽישׁ־נַ֛עַר אֲשֶׁר־רָכְב֥וּ עַל־הַ⁠גְּמַלִּ֖ים וַ⁠יָּנֻֽסוּ׃","wa⁠yȧké֥̇⁠m dá̇wi֛d mé⁠ha⁠nė֥şěp wĕ⁠ʻad-há⁠ʻe֖reb lĕ⁠máֽẖoráţá֑⁠m wĕ⁠lòֽʼ-nimĕla֤t mé⁠hem֙ ʼi֔yş̌ ki̇y֩ ʼim-ʼarĕbȧ֨ʻ méʼ֧wòţ ʼiֽyş̌-na֛ʻar ʼàşěr-rákĕb֥ẇ ʻal-ha⁠gĕ̇mali֖̇ym wa⁠yá̇nuֽsẇ׃"],[30,18,"וַ⁠יַּצֵּ֣ל דָּוִ֔ד אֵ֛ת כָּל־אֲשֶׁ֥ר לָקְח֖וּ עֲמָלֵ֑ק וְ⁠אֶת־שְׁתֵּ֥י נָשָׁ֖י⁠ו הִצִּ֥יל דָּוִֽד׃","wa⁠yȧẕé֣̇l dá̇wi֔d ʼé֛ţ ká̇l-ʼàşě֥r láqĕẖ֖ẇ ʻàmálé֑q wĕ⁠ʼeţ-şĕ̌ţé֥̇y náşá֖̌y⁠w hiẕi֥̇yl dá̇wiֽd׃"],[30,19,"וְ⁠לֹ֣א נֶעְדַּר־לָ֠⁠הֶם מִן־הַ⁠קָּטֹ֨ן וְ⁠עַד־הַ⁠גָּד֜וֹל וְ⁠עַד־בָּנִ֤ים וּ⁠בָנוֹת֙ וּ⁠מִ⁠שָּׁלָ֔ל וְ⁠עַ֛ד כָּל־אֲשֶׁ֥ר לָקְח֖וּ לָ⁠הֶ֑ם הַ⁠כֹּ֖ל הֵשִׁ֥יב דָּוִֽד׃","wĕ⁠lò֣ʼ neʻĕdȧr-lá֠⁠hem min-ha⁠qá̇tò֨n wĕ⁠ʻad-ha⁠gá̇d֜wòl wĕ⁠ʻad-bá̇ni֤ym ẇ⁠bánwòţ֙ ẇ⁠mi⁠şá̇̌lá֔l wĕ⁠ʻa֛d ká̇l-ʼàşě֥r láqĕẖ֖ẇ lá⁠he֑m ha⁠kò֖̇l héşǐ֥yb dá̇wiֽd׃"],[30,20,"וַ⁠יִּקַּ֣ח דָּוִ֔ד אֶת־כָּל־הַ⁠צֹּ֖אן וְ⁠הַ⁠בָּקָ֑ר נָהֲג֗וּ לִ⁠פְנֵי֙ הַ⁠מִּקְנֶ֣ה הַ⁠ה֔וּא וַ⁠יֹּ֣אמְר֔וּ זֶ֖ה שְׁלַ֥ל דָּוִֽד׃","wa⁠yi̇qȧ֣ẖ dá̇wi֔d ʼeţ-ká̇l-ha⁠ẕò֖̇ʼn wĕ⁠ha⁠bá̇qá֑r náhàg֗ẇ li⁠pĕnéy֙ ha⁠mi̇qĕne֣h ha⁠h֔ẇʼ wa⁠yò֣̇ʼmĕr֔ẇ ze֖h şĕ̌la֥l dá̇wiֽd׃"],[30,21,"וַ⁠יָּבֹ֣א דָוִ֗ד אֶל־מָאתַ֨יִם הָ⁠אֲנָשִׁ֜ים אֲשֶֽׁר־פִּגְּר֣וּ ׀ מִ⁠לֶּ֣כֶת ׀ אַחֲרֵ֣י דָוִ֗ד וַ⁠יֹּֽשִׁיבֻ⁠ם֙ בְּ⁠נַ֣חַל הַ⁠בְּשׂ֔וֹר וַ⁠יֵּֽצְאוּ֙ לִ⁠קְרַ֣את דָּוִ֔ד וְ⁠לִ⁠קְרַ֖את הָ⁠עָ֣ם אֲשֶׁר־אִתּ֑⁠וֹ וַ⁠יִּגַּ֤שׁ דָּוִד֙ אֶת־הָ⁠עָ֔ם וַ⁠יִּשְׁאַ֥ל לָ⁠הֶ֖ם לְ⁠שָׁלֽוֹם׃ס","wa⁠yá̇bò֣ʼ dáwi֗d ʼel-máʼţa֨yim há⁠ʼànáşǐ֜ym ʼàşěֽr-pi̇gĕ̇r֣ẇ ׀ mi⁠lė֣keţ ׀ ʼaẖàré֣y dáwi֗d wa⁠yòֽ̇şǐybu⁠m֙ bĕ̇⁠na֣ẖal ha⁠bĕ̇ş̂֔wòr wa⁠yéֽ̇ẕĕʼẇ֙ li⁠qĕra֣ʼţ dá̇wi֔d wĕ⁠li⁠qĕra֖ʼţ há⁠ʻá֣m ʼàşěr-ʼiţ֑̇⁠wò wa⁠yi̇gȧ֤ş̌ dá̇wid֙ ʼeţ-há⁠ʻá֔m wa⁠yi̇şĕ̌ʼa֥l lá⁠he֖m lĕ⁠şá̌lֽwòm׃s"],[30,22,"וַ⁠יַּ֜עַן כָּל־אִֽישׁ־רָ֣ע וּ⁠בְלִיַּ֗עַל מֵֽ⁠הָ⁠אֲנָשִׁים֮ אֲשֶׁ֣ר הָלְכ֣וּ עִם־דָּוִד֒ וַ⁠יֹּאמְר֗וּ יַ֚עַן אֲשֶׁ֣ר לֹֽא־הָלְכ֣וּ עִמִּ֔⁠י לֹֽא־נִתֵּ֣ן לָ⁠הֶ֔ם מֵ⁠הַ⁠שָּׁלָ֖ל אֲשֶׁ֣ר הִצַּ֑לְנוּ כִּֽי־אִם־אִ֤ישׁ אֶת־אִשְׁתּ⁠וֹ֙ וְ⁠אֶת־בָּנָ֔י⁠ו וְ⁠יִנְהֲג֖וּ וְ⁠יֵלֵֽכוּ׃ס","wa⁠yȧ֜ʻan ká̇l-ʼiֽyş̌-rá֣ʻ ẇ⁠bĕliyȧ֗ʻal méֽ⁠há⁠ʼànáşǐym֮ ʼàşě֣r hálĕk֣ẇ ʻim-dá̇wid֒ wa⁠yò̇ʼmĕr֗ẇ ya֚ʻan ʼàşě֣r lòֽʼ-hálĕk֣ẇ ʻimi̇֔⁠y lòֽʼ-niţé֣̇n lá⁠he֔m mé⁠ha⁠şá̇̌lá֖l ʼàşě֣r hiẕȧ֑lĕnẇ kiֽ̇y-ʼim-ʼi֤yş̌ ʼeţ-ʼişĕ̌ţ̇⁠wò֙ wĕ⁠ʼeţ-bá̇ná֔y⁠w wĕ⁠yinĕhàg֖ẇ wĕ⁠yéléֽkẇ׃s"],[30,23,"וַ⁠יֹּ֣אמֶר דָּוִ֔ד לֹֽא־תַעֲשׂ֥וּ כֵ֖ן אֶחָ֑⁠י אֵ֠ת אֲשֶׁר־נָתַ֨ן יְהוָ֥ה לָ֨⁠נוּ֙ וַ⁠יִּשְׁמֹ֣ר אֹתָ֔⁠נוּ וַ⁠יִּתֵּ֗ן אֶֽת־הַ⁠גְּד֛וּד הַ⁠בָּ֥א עָלֵ֖י⁠נוּ בְּ⁠יָדֵֽ⁠נוּ׃","wa⁠yò֣̇ʼmer dá̇wi֔d lòֽʼ-ţaʻàş֥̂ẇ ké֖n ʼeẖá֑⁠y ʼé֠ţ ʼàşěr-náţa֨n yĕhwá֥h lá֨⁠nẇ֙ wa⁠yi̇şĕ̌mò֣r ʼòţá֔⁠nẇ wa⁠yi̇ţé̇֗n ʼeֽţ-ha⁠gĕ̇d֛ẇd ha⁠bá֥̇ʼ ʻálé֖y⁠nẇ bĕ̇⁠yádéֽ⁠nẇ׃"],[30,24,"וּ⁠מִי֙ יִשְׁמַ֣ע לָ⁠כֶ֔ם לַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה כִּ֞י כְּ⁠חֵ֣לֶק ׀ הַ⁠יֹּרֵ֣ד בַּ⁠מִּלְחָמָ֗ה וּֽ⁠כְ⁠חֵ֛לֶק הַ⁠יֹּשֵׁ֥ב עַל־הַ⁠כֵּלִ֖ים יַחְדָּ֥ו יַחֲלֹֽקוּ׃ס","ẇ⁠miy֙ yişĕ̌ma֣ʻ lá⁠ke֔m la⁠dá̇bá֖r ha⁠zė֑h ki̇֞y kĕ̇⁠ẖé֣leq ׀ ha⁠yò̇ré֣d bȧ⁠mi̇lĕẖámá֗h ẇֽ⁠kĕ⁠ẖé֛leq ha⁠yò̇şé֥̌b ʻal-ha⁠ké̇li֖ym yaẖĕdá֥̇w yaẖàlòֽqẇ׃s"],[30,25,"וַ⁠יְהִ֕י מֵֽ⁠הַ⁠יּ֥וֹם הַ⁠ה֖וּא וָ⁠מָ֑עְלָ⁠ה וַ⁠יְשִׂמֶ֜⁠הָ לְ⁠חֹ֤ק וּ⁠לְ⁠מִשְׁפָּט֙ לְ⁠יִשְׂרָאֵ֔ל עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yĕhi֕y méֽ⁠ha⁠ẏ֥wòm ha⁠h֖ẇʼ wá⁠má֑ʻĕlá⁠h wa⁠yĕşîme֜⁠há lĕ⁠ẖò֤q ẇ⁠lĕ⁠mişĕ̌pá̇t֙ lĕ⁠yişĕ̂ráʼé֔l ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[30,26,"וַ⁠יָּבֹ֤א דָוִד֙ אֶל־צִ֣קְלַ֔ג וַ⁠יְשַׁלַּ֧ח מֵֽ⁠הַ⁠שָּׁלָ֛ל לְ⁠זִקְנֵ֥י יְהוּדָ֖ה לְ⁠רֵעֵ֣⁠הוּ לֵ⁠אמֹ֑ר הִנֵּ֤ה לָ⁠כֶם֙ בְּרָכָ֔ה מִ⁠שְּׁלַ֖ל אֹיְבֵ֥י יְהוָֽה׃","wa⁠yá̇bò֤ʼ dáwid֙ ʼel-ẕi֣qĕla֔g wa⁠yĕşǎlȧ֧ẖ méֽ⁠ha⁠şá̇̌lá֛l lĕ⁠ziqĕné֥y yĕhẇdá֖h lĕ⁠réʻé֣⁠hẇ lé⁠ʼmò֑r hiné֤̇h lá⁠kem֙ bĕ̇ráká֔h mi⁠şĕ̇̌la֖l ʼòyĕbé֥y yĕhwáֽh׃"],[30,27,"לַ⁠אֲשֶׁ֧ר בְּ⁠בֵֽית־אֵ֛ל וְ⁠לַ⁠אֲשֶׁ֥ר בְּ⁠רָמֽוֹת־נֶ֖גֶב וְ⁠לַ⁠אֲשֶׁ֥ר בְּ⁠יַתִּֽר׃","la⁠ʼàşě֧r bĕ̇⁠béֽyţ-ʼé֛l wĕ⁠la⁠ʼàşě֥r bĕ̇⁠rámֽwòţ-ne֖geb wĕ⁠la⁠ʼàşě֥r bĕ̇⁠yaţiֽ̇r׃"],[30,28,"וְ⁠לַ⁠אֲשֶׁ֧ר בַּ⁠עֲרֹעֵ֛ר וְ⁠לַ⁠אֲשֶׁ֥ר בְּ⁠שִֽׂפְמ֖וֹת וְ⁠לַ⁠אֲשֶׁ֥ר בְּ⁠אֶשְׁתְּמֹֽעַ׃ס","wĕ⁠la⁠ʼàşě֧r bȧ⁠ʻàròʻé֛r wĕ⁠la⁠ʼàşě֥r bĕ̇⁠şîֽpĕm֖wòţ wĕ⁠la⁠ʼàşě֥r bĕ̇⁠ʼeşĕ̌ţĕ̇mòֽʻa׃s"],[30,29,"וְ⁠לַ⁠אֲשֶׁ֣ר בְּ⁠רָכָ֗ל וְ⁠לַֽ⁠אֲשֶׁר֙ בְּ⁠עָרֵ֣י הַ⁠יְּרַחְמְאֵלִ֔י וְ⁠לַ⁠אֲשֶׁ֖ר בְּ⁠עָרֵ֥י הַ⁠קֵּינִֽי׃","wĕ⁠la⁠ʼàşě֣r bĕ̇⁠ráká֗l wĕ⁠laֽ⁠ʼàşěr֙ bĕ̇⁠ʻáré֣y ha⁠yĕ̇raẖĕmĕʼéli֔y wĕ⁠la⁠ʼàşě֖r bĕ̇⁠ʻáré֥y ha⁠qé̇yniֽy׃"],[30,30,"וְ⁠לַ⁠אֲשֶׁ֧ר בְּ⁠חָרְמָ֛ה וְ⁠לַ⁠אֲשֶׁ֥ר בְּ⁠בוֹר־עָשָׁ֖ן וְ⁠לַ⁠אֲשֶׁ֥ר בַּ⁠עֲתָֽךְ׃","wĕ⁠la⁠ʼàşě֧r bĕ̇⁠ẖárĕmá֛h wĕ⁠la⁠ʼàşě֥r bĕ̇⁠bwòr-ʻáşá֖̌n wĕ⁠la⁠ʼàşě֥r bȧ⁠ʻàţáֽkĕ׃"],[30,31,"וְ⁠לַ⁠אֲשֶׁ֖ר בְּ⁠חֶבְר֑וֹן וּֽ⁠לְ⁠כָל־הַ⁠מְּקֹמ֛וֹת אֲשֶֽׁר־הִתְהַלֶּךְ־שָׁ֥ם דָּוִ֖ד ה֥וּא וַ⁠אֲנָשָֽׁי⁠ו׃פ","wĕ⁠la⁠ʼàşě֖r bĕ̇⁠ẖebĕr֑wòn ẇֽ⁠lĕ⁠kál-ha⁠mĕ̇qòm֛wòţ ʼàşěֽr-hiţĕhalėkĕ-şá֥̌m dá̇wi֖d h֥ẇʼ wa⁠ʼànáşáֽ̌y⁠w׃p"],[31,1,"וּ⁠פְלִשְׁתִּ֖ים נִלְחָמִ֣ים בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יָּנֻ֜סוּ אַנְשֵׁ֤י יִשְׂרָאֵל֙ מִ⁠פְּנֵ֣י פְלִשְׁתִּ֔ים וַ⁠יִּפְּל֥וּ חֲלָלִ֖ים בְּ⁠הַ֥ר הַ⁠גִּלְבֹּֽעַ׃","ẇ⁠pĕlişĕ̌ţi֖̇ym nilĕẖámi֣ym bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yá̇nu֜sẇ ʼanĕşé֤̌y yişĕ̂ráʼél֙ mi⁠pĕ̇né֣y pĕlişĕ̌ţi̇֔ym wa⁠yi̇pĕ̇l֥ẇ ẖàláli֖ym bĕ̇⁠ha֥r ha⁠gi̇lĕbòֽ̇ʻa׃"],[31,2,"וַ⁠יַּדְבְּק֣וּ פְלִשְׁתִּ֔ים אֶת־שָׁא֖וּל וְ⁠אֶת־בָּנָ֑י⁠ו וַ⁠יַּכּ֣וּ פְלִשְׁתִּ֗ים אֶת־יְהוֹנָתָ֧ן וְ⁠אֶת־אֲבִינָדָ֛ב וְ⁠אֶת־מַלְכִּי־שׁ֖וּעַ בְּנֵ֥י שָׁאֽוּל׃","wa⁠yȧdĕbĕ̇q֣ẇ pĕlişĕ̌ţi̇֔ym ʼeţ-şá̌ʼ֖ẇl wĕ⁠ʼeţ-bá̇ná֑y⁠w wa⁠yȧk֣̇ẇ pĕlişĕ̌ţi̇֗ym ʼeţ-yĕhwònáţá֧n wĕ⁠ʼeţ-ʼàbiynádá֛b wĕ⁠ʼeţ-malĕki̇y-ş֖̌ẇʻa bĕ̇né֥y şá̌ʼֽẇl׃"],[31,3,"וַ⁠תִּכְבַּ֤ד הַ⁠מִּלְחָמָה֙ אֶל־שָׁא֔וּל וַ⁠יִּמְצָאֻ֥⁠הוּ הַ⁠מּוֹרִ֖ים אֲנָשִׁ֣ים בַּ⁠קָּ֑שֶׁת וַ⁠יָּ֥חֶל מְאֹ֖ד מֵ⁠הַ⁠מּוֹרִֽים׃","wa⁠ţi̇kĕbȧ֤d ha⁠mi̇lĕẖámáh֙ ʼel-şá̌ʼ֔ẇl wa⁠yi̇mĕẕáʼu֥⁠hẇ ha⁠ṁwòri֖ym ʼànáşǐ֣ym bȧ⁠qá֑̇şěţ wa⁠yá֥̇ẖel mĕʼò֖d mé⁠ha⁠ṁwòriֽym׃"],[31,4,"וַ⁠יֹּ֣אמֶר שָׁאוּל֩ לְ⁠נֹשֵׂ֨א כֵלָ֜י⁠ו שְׁלֹ֥ף חַרְבְּ⁠ךָ֣ ׀ וְ⁠דָקְרֵ֣⁠נִי בָ֗⁠הּ פֶּן־יָ֠בוֹאוּ הָ⁠עֲרֵלִ֨ים הָ⁠אֵ֤לֶּה וּ⁠דְקָרֻ֨⁠נִי֙ וְ⁠הִתְעַלְּלוּ־בִ֔⁠י וְ⁠לֹ֤א אָבָה֙ נֹשֵׂ֣א כֵלָ֔י⁠ו כִּ֥י יָרֵ֖א מְאֹ֑ד וַ⁠יִּקַּ֤ח שָׁאוּל֙ אֶת־הַ⁠חֶ֔רֶב וַ⁠יִּפֹּ֖ל עָלֶֽי⁠הָ׃","wa⁠yò֣̇ʼmer şá̌ʼẇl֩ lĕ⁠nòşé̂֨ʼ kélá֜y⁠w şĕ̌lò֥p ẖarĕbĕ̇⁠ká֣ ׀ wĕ⁠dáqĕré֣⁠niy bá֗⁠ḣ pėn-yá֠bwòʼẇ há⁠ʻàréli֨ym há⁠ʼé֤lėh ẇ⁠dĕqáru֨⁠niy֙ wĕ⁠hiţĕʻalĕ̇lẇ-bi֔⁠y wĕ⁠lò֤ʼ ʼábáh֙ nòşé֣̂ʼ kélá֔y⁠w ki֥̇y yáré֖ʼ mĕʼò֑d wa⁠yi̇qȧ֤ẖ şá̌ʼẇl֙ ʼeţ-ha⁠ẖe֔reb wa⁠yi̇pò֖̇l ʻáleֽy⁠há׃"],[31,5,"וַ⁠יַּ֥רְא נֹשֵֽׂא־כֵלָ֖י⁠ו כִּ֣י מֵ֣ת שָׁא֑וּל וַ⁠יִּפֹּ֥ל גַּם־ה֛וּא עַל־חַרְבּ֖⁠וֹ וַ⁠יָּ֥מָת עִמּֽ⁠וֹ׃","wa⁠yȧ֥rĕʼ nòşéֽ̂ʼ-kélá֖y⁠w ki֣̇y mé֣ţ şá̌ʼ֑ẇl wa⁠yi̇pò֥̇l gȧm-h֛ẇʼ ʻal-ẖarĕḃ֖⁠wò wa⁠yá֥̇máţ ʻiṁֽ⁠wò׃"],[31,6,"וַ⁠יָּ֣מָת שָׁא֡וּל וּ⁠שְׁלֹ֣שֶׁת בָּנָי⁠ו֩ וְ⁠נֹשֵׂ֨א כֵלָ֜י⁠ו גַּ֧ם כָּל־אֲנָשָׁ֛י⁠ו בַּ⁠יּ֥וֹם הַ⁠ה֖וּא יַחְדָּֽו׃","wa⁠yá֣̇máţ şá̌ʼ֡ẇl ẇ⁠şĕ̌lò֣şěţ bá̇náy⁠w֩ wĕ⁠nòşé̂֨ʼ kélá֜y⁠w gȧ֧m ká̇l-ʼànáşá֛̌y⁠w bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ yaẖĕdáֽ̇w׃"],[31,7,"וַ⁠יִּרְא֣וּ אַנְשֵֽׁי־יִ֠שְׂרָאֵל אֲשֶׁר־בְּ⁠עֵ֨בֶר הָ⁠עֵ֜מֶק וַ⁠אֲשֶׁ֣ר ׀ בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֗ן כִּֽי־נָ֨סוּ֙ אַנְשֵׁ֣י יִשְׂרָאֵ֔ל וְ⁠כִי־מֵ֖תוּ שָׁא֣וּל וּ⁠בָנָ֑י⁠ו וַ⁠יַּעַזְב֤וּ אֶת־הֶֽ⁠עָרִים֙ וַ⁠יָּנֻ֔סוּ וַ⁠יָּבֹ֣אוּ פְלִשְׁתִּ֔ים וַ⁠יֵּֽשְׁב֖וּ בָּ⁠הֶֽן׃ס","wa⁠yi̇rĕʼ֣ẇ ʼanĕşéֽ̌y-yi֠şĕ̂ráʼél ʼàşěr-bĕ̇⁠ʻé֨ber há⁠ʻé֜meq wa⁠ʼàşě֣r ׀ bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé̇֗n kiֽ̇y-ná֨sẇ֙ ʼanĕşé֣̌y yişĕ̂ráʼé֔l wĕ⁠kiy-mé֖ţẇ şá̌ʼ֣ẇl ẇ⁠báná֑y⁠w wa⁠yȧʻazĕb֤ẇ ʼeţ-heֽ⁠ʻáriym֙ wa⁠yá̇nu֔sẇ wa⁠yá̇bò֣ʼẇ pĕlişĕ̌ţi̇֔ym wa⁠yéֽ̇şĕ̌b֖ẇ bá̇⁠heֽn׃s"],[31,8,"וַֽ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יָּבֹ֣אוּ פְלִשְׁתִּ֔ים לְ⁠פַשֵּׁ֖ט אֶת־הַ⁠חֲלָלִ֑ים וַֽ⁠יִּמְצְא֤וּ אֶת־שָׁאוּל֙ וְ⁠אֶת־שְׁלֹ֣שֶׁת בָּנָ֔י⁠ו נֹפְלִ֖ים בְּ⁠הַ֥ר הַ⁠גִּלְבֹּֽעַ׃","waֽ⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠yá̇bò֣ʼẇ pĕlişĕ̌ţi̇֔ym lĕ⁠paşé֖̇̌t ʼeţ-ha⁠ẖàláli֑ym wֽa⁠yi̇mĕẕĕʼ֤ẇ ʼeţ-şá̌ʼẇl֙ wĕ⁠ʼeţ-şĕ̌lò֣şěţ bá̇ná֔y⁠w nòpĕli֖ym bĕ̇⁠ha֥r ha⁠gi̇lĕbòֽ̇ʻa׃"],[31,9,"וַֽ⁠יִּכְרְתוּ֙ אֶת־רֹאשׁ֔⁠וֹ וַ⁠יַּפְשִׁ֖יטוּ אֶת־כֵּלָ֑י⁠ו וַ⁠יְשַׁלְּח֨וּ בְ⁠אֶֽרֶץ־פְּלִשְׁתִּ֜ים סָבִ֗יב לְ⁠בַשֵּׂ֛ר בֵּ֥ית עֲצַבֵּי⁠הֶ֖ם וְ⁠אֶת־הָ⁠עָֽם׃","waֽ⁠yi̇kĕrĕţẇ֙ ʼeţ-ròʼş̌֔⁠wò wa⁠yȧpĕşǐ֖ytẇ ʼeţ-ké̇lá֑y⁠w wa⁠yĕşǎlĕ̇ẖ֨ẇ bĕ⁠ʼeֽreẕ-pĕ̇lişĕ̌ţi̇֜ym sábi֗yb lĕ⁠başé֛̇̂r bé֥̇yţ ʻàẕabé̇y⁠he֖m wĕ⁠ʼeţ-há⁠ʻáֽm׃"],[31,10,"וַ⁠יָּשִׂ֨מוּ֙ אֶת־כֵּלָ֔י⁠ו בֵּ֖ית עַשְׁתָּר֑וֹת וְ⁠אֶת־גְּוִיָּת⁠וֹ֙ תָּקְע֔וּ בְּ⁠חוֹמַ֖ת בֵּ֥ית שָֽׁן׃","wa⁠yá̇şî֨mẇ֙ ʼeţ-ké̇lá֔y⁠w bé֖̇yţ ʻaşĕ̌ţá̇r֑wòţ wĕ⁠ʼeţ-gĕ̇wiyá̇ţ⁠wò֙ ţá̇qĕʻ֔ẇ bĕ̇⁠ẖwòma֖ţ bé֥̇yţ şáֽ̌n׃"],[31,11,"וַ⁠יִּשְׁמְע֣וּ אֵלָ֔י⁠ו יֹשְׁבֵ֖י יָבֵ֣ישׁ גִּלְעָ֑ד אֵ֛ת אֲשֶׁר־עָשׂ֥וּ פְלִשְׁתִּ֖ים לְ⁠שָׁאֽוּל׃","wa⁠yi̇şĕ̌mĕʻ֣ẇ ʼélá֔y⁠w yòşĕ̌bé֖y yábé֣yş̌ gi̇lĕʻá֑d ʼé֛ţ ʼàşěr-ʻáş֥̂ẇ pĕlişĕ̌ţi֖̇ym lĕ⁠şá̌ʼֽẇl׃"],[31,12,"וַ⁠יָּק֜וּמוּ כָּל־אִ֣ישׁ חַיִל֮ וַ⁠יֵּלְכ֣וּ כָל־הַ⁠לַּיְלָה֒ וַ⁠יִּקְח֞וּ אֶת־גְּוִיַּ֣ת שָׁא֗וּל וְ⁠אֵת֙ גְּוִיֹּ֣ת בָּנָ֔י⁠ו מֵ⁠חוֹמַ֖ת בֵּ֣ית שָׁ֑ן וַ⁠יָּבֹ֣אוּ יָבֵ֔שָׁ⁠ה וַ⁠יִּשְׂרְפ֥וּ אֹתָ֖⁠ם שָֽׁם׃","wa⁠yá̇q֜ẇmẇ ká̇l-ʼi֣yş̌ ẖayil֮ wa⁠yé̇lĕk֣ẇ kál-ha⁠lȧyĕláh֒ wa⁠yi̇qĕẖ֞ẇ ʼeţ-gĕ̇wiyȧ֣ţ şá̌ʼ֗ẇl wĕ⁠ʼéţ֙ gĕ̇wiyò֣̇ţ bá̇ná֔y⁠w mé⁠ẖwòma֖ţ bé֣̇yţ şá֑̌n wa⁠yá̇bò֣ʼẇ yábé֔şá̌⁠h wa⁠yi̇şĕ̂rĕp֥ẇ ʼòţá֖⁠m şáֽ̌m׃"],[31,13,"וַ⁠יִּקְחוּ֙ אֶת־עַצְמֹ֣תֵי⁠הֶ֔ם וַ⁠יִּקְבְּר֥וּ תַֽחַת־הָ⁠אֶ֖שֶׁל בְּ⁠יָבֵ֑שָׁ⁠ה וַ⁠יָּצֻ֖מוּ שִׁבְעַ֥ת יָמִֽים׃פ","wa⁠yi̇qĕẖẇ֙ ʼeţ-ʻaẕĕmò֣ţéy⁠he֔m wa⁠yi̇qĕbĕ̇r֥ẇ ţaֽẖaţ-há⁠ʼe֖şěl bĕ̇⁠yábé֑şá̌⁠h wa⁠yá̇ẕu֖mẇ şǐbĕʻa֥ţ yámiֽym׃p"]]}};